class GoalSystemFailure(Exception):
    """Raised when goal selection cannot produce a causally grounded choice.

    The system must never coast on a passive "rest" fallback when goal
    selection genuinely fails.  Callers (Brain.tick) must catch this and
    either force goal generation or log the missed tick explicitly.
    """


# ─────────────────────────────────────────────────────────────────────────────
# Meta-Stability Controller
# Dynamically weights the three stabilization forces based on phi
# to produce controlled cognitive phase transitions instead of fixed behaviour.
# ─────────────────────────────────────────────────────────────────────────────


class MetaStabilityController:
    """
    A phi-driven arbitrator between three competing forces:

      Attractor    — pulls self-model toward identity baseline (→ stability)
      Persistence  — holds the current goal under noise (→ continuity)
      Drift        — lets concepts float freely (→ flexibility / creativity)

    Phi zones:
      phi > 0.06   : STABLE mode  — attractor strong, persistence strong, drift suppressed
      0.02–0.06    : BALANCED mode — equal competition between forces
      phi < 0.02   : DRIFT mode   — attractor weak, persistence weak, concepts wander

    All weights are continuous (no hard thresholds) so the system transitions
    smoothly through cognitive phases rather than switching discretely.
    """

    # Smoothing: EMA of phi to prevent single-tick jitter from flipping modes
    _PHI_EMA = 0.15

    def __init__(self) -> None:
        self._phi_ema: float = 0.04  # start at baseline
        self.mode: str = "balanced"  # current cognitive mode label
        # Weight history for monitoring
        self.w_attractor: float = 0.5
        self.w_persistence: float = 0.5
        self.w_drift: float = 0.5

    def compute(self, phi_now: float) -> tuple:
        """
        Returns (w_attractor, w_persistence, w_drift, mode_str).

        Weights are in [0, 1].  They are NOT summed to 1 — each scales an
        independent force, so the system can be simultaneously stable and
        flexible at medium phi.
        """
        # Smooth phi to resist noise
        self._phi_ema = self._PHI_EMA * phi_now + (1.0 - self._PHI_EMA) * self._phi_ema
        p = self._phi_ema

        # Attractor: sigmoid centred at phi=0.04, rises with phi
        # At phi=0 → ~0.18, phi=0.04 → 0.5, phi=0.10 → ~0.82
        w_att = 1.0 / (1.0 + pow(2.718, -80.0 * (p - 0.04)))

        # Persistence: linear ramp 0→1 from phi=0 to phi=0.06, floored at 0.15
        w_per = max(0.15, min(1.0, p / 0.06))

        # Drift: complement of attractor — high when phi low
        w_dri = 1.0 - w_att

        # Determine mode label for stream
        if p > 0.06:
            mode = "stable"
        elif p > 0.02:
            mode = "balanced"
        else:
            mode = "drift"

        self.w_attractor = w_att
        self.w_persistence = w_per
        self.w_drift = w_dri
        self.mode = mode
        return w_att, w_per, w_dri, mode

    def describe(self) -> str:
        return (
            f"MetaStability mode={self.mode} "
            f"w_att={self.w_attractor:.2f} "
            f"w_per={self.w_persistence:.2f} "
            f"w_drift={self.w_drift:.2f} "
            f"phi_ema={self._phi_ema:.4f}"
        )


# ─────────────────────────────────────────────────────────────────────────────
# Developmental Gradient
# Tracks the system's movement through state-space over time and applies a
# gentle momentum bias so the system continues its own developmental trajectory.
# This is the "direction of change" — not a goal, but the memory of movement.
# ─────────────────────────────────────────────────────────────────────────────


class DevelopmentalGradient:
    """
    Implicit memory of how the system has been changing over time.

    Observes snapshots of (agency, continuity, concept_salience_mean) every
    tick and maintains a rolling exponential average of the *delta* between
    recent snapshots — i.e., which direction the state has last been moving.

    The gradient is applied as a gentle additive bias in the stabilization
    layer, scaled by w_drift from MetaStabilityController:

      drift mode  → gradient is the dominant force (autopoiesis: follow the trajectory)
      stable mode → gradient is suppressed (attractor dominates)

    This creates a system that has an implicit "developmental history" — it
    doesn't just balance forces in the present but carries the memory of its
    own evolution forward.
    """

    _EMA_FAST = 0.10  # fast window (recent movement)
    _EMA_SLOW = 0.01  # slow window (long-term drift)
    _MAX_GRADIENT = 0.008  # cap: gradient never overrides attractor completely

    def __init__(self) -> None:
        # State snapshots
        self._prev_agency: float = 0.50
        self._prev_continuity: float = 0.75
        self._prev_sal_mean: float = 0.0
        # Fast and slow gradient EMAs
        self._grad_agency_fast: float = 0.0
        self._grad_agency_slow: float = 0.0
        self._grad_cont_fast: float = 0.0
        self._grad_cont_slow: float = 0.0
        self._grad_sal_fast: float = 0.0
        # Concept-goal momentum: rolling distribution of recent goal modes
        self._goal_mode_counts: Dict[str, float] = {
            "explore": 0.0,
            "consolidate": 0.0,
            "respond": 0.0,
            "rest": 0.0,
        }
        self._goal_mode_ema = 0.05

    def observe(
        self, agency: float, continuity: float, sal_mean: float, goal_mode: str
    ) -> None:
        """Record a new state snapshot and update gradient EMAs."""
        d_ag = agency - self._prev_agency
        d_co = continuity - self._prev_continuity
        d_sal = sal_mean - self._prev_sal_mean

        self._grad_agency_fast = (
            self._EMA_FAST * d_ag + (1 - self._EMA_FAST) * self._grad_agency_fast
        )
        self._grad_agency_slow = (
            self._EMA_SLOW * d_ag + (1 - self._EMA_SLOW) * self._grad_agency_slow
        )
        self._grad_cont_fast = (
            self._EMA_FAST * d_co + (1 - self._EMA_FAST) * self._grad_cont_fast
        )
        self._grad_cont_slow = (
            self._EMA_SLOW * d_co + (1 - self._EMA_SLOW) * self._grad_cont_slow
        )
        self._grad_sal_fast = (
            self._EMA_FAST * d_sal + (1 - self._EMA_FAST) * self._grad_sal_fast
        )

        # Update goal-mode momentum (soft distribution over history)
        for m in self._goal_mode_counts:
            self._goal_mode_counts[m] *= 1.0 - self._goal_mode_ema
        self._goal_mode_counts[goal_mode] = (
            self._goal_mode_counts.get(goal_mode, 0.0) + self._goal_mode_ema
        )

        self._prev_agency = agency
        self._prev_continuity = continuity
        self._prev_sal_mean = sal_mean

    def apply(self, agency: float, continuity: float, w_drift: float) -> tuple:
        """
        Returns (new_agency, new_continuity) after applying gradient momentum.

        The gradient nudges values in the direction they have been moving recently,
        scaled by w_drift so that drift mode amplifies the effect and stable mode
        suppresses it almost entirely.
        """
        # Use fast–slow divergence: when fast ≠ slow the system is accelerating
        dir_ag = self._grad_agency_fast + 0.3 * (
            self._grad_agency_fast - self._grad_agency_slow
        )
        dir_co = self._grad_cont_fast + 0.3 * (
            self._grad_cont_fast - self._grad_cont_slow
        )

        # Scale by w_drift and clamp to max per-tick magnitude
        _scale = w_drift * 0.5
        delta_ag = max(-self._MAX_GRADIENT, min(self._MAX_GRADIENT, dir_ag * _scale))
        delta_co = max(-self._MAX_GRADIENT, min(self._MAX_GRADIENT, dir_co * _scale))

        new_ag = max(0.05, min(0.95, agency + delta_ag))
        new_co = max(0.05, min(0.95, continuity + delta_co))
        return new_ag, new_co

    def dominant_goal_mode(self) -> str:
        """Return the goal mode the system has spent the most time in recently."""
        if not self._goal_mode_counts:
            return "explore"
        return max(self._goal_mode_counts, key=self._goal_mode_counts.get)

    def describe(self) -> str:
        dom = self.dominant_goal_mode()
        return (
            f"DevGrad agency={self._grad_agency_fast:+.4f}(fast) "
            f"cont={self._grad_cont_fast:+.4f}(fast) "
            f"dominant_mode={dom}"
        )


# ─────────────────────────────────────────────────────────────────────────────
# Trajectory Compressor
# Selects the dominant developmental trajectory from competing internal signals
# and collapses them into a single coherent self-narrative line.
# ─────────────────────────────────────────────────────────────────────────────


class TrajectoryCompressor:
    """
    Evaluates four competing trajectory signals and elects a dominant one.

    The four candidates:
      A) MOMENTUM   — DevelopmentalGradient fast EMA (what is the system doing right now?)
      B) TREND      — DevelopmentalGradient fast-slow divergence (is the system accelerating?)
      C) GOAL-HABIT — Most persistent recent goal mode (what does the system keep returning to?)
      D) CONCEPT-ID — Top stable concept cluster (what semantically defines the system?)

    Each candidate gets a coherence score based on:
      - signal strength (magnitude of the trend)
      - consistency over time (low oscillation wins)
      - temporal persistence (sustained > short burst)

    The winner updates `dominant_narrative` — a stable one-line string the language
    system and goal evaluator can use as the current "identity sentence".

    Coherence bleed: the losing candidates' scores are blended into a
    `narrative_coherence` float [0,1]. High coherence = all candidates agree
    on the same direction. Low coherence = competing stories.
    """

    _COHERENCE_EMA = 0.05  # slow blend so narrative doesn't flip every tick
    _PERSIST_INTERVAL = 30  # ticks between narrative updates (prevents flicker)

    def __init__(self) -> None:
        self.dominant_narrative: str = "identity forming"
        self.dominant_trajectory: str = (
            "unknown"  # "momentum"|"trend"|"goal-habit"|"concept-id"
        )
        self.narrative_coherence: float = 0.5  # [0,1]: agreement across trajectories
        self._coherence_ema: float = 0.5
        self._last_update_tick: int = -1000
        # Rolling score per trajectory for stream transparency
        self._scores: Dict[str, float] = {
            "momentum": 0.0,
            "trend": 0.0,
            "goal-habit": 0.0,
            "concept-id": 0.0,
        }

    def update(
        self,
        tick: int,
        dev_grad: "DevelopmentalGradient",
        stable_concepts: set,
        concept_salience: Dict[str, float],
        goal_mode: str,
        agency: float,
        continuity: float,
        ms_mode: str,
    ) -> Optional[str]:
        """
        Compute trajectory scores, elect dominant narrative, and return a
        stream-log string when the narrative changes.  Returns None otherwise.
        """
        if tick - self._last_update_tick < self._PERSIST_INTERVAL:
            return None
        self._last_update_tick = tick

        # ── A) MOMENTUM: how strongly is the gradient moving right now? ──
        mag_agency = abs(dev_grad._grad_agency_fast)
        mag_cont = abs(dev_grad._grad_cont_fast)
        score_momentum = min(1.0, (mag_agency + mag_cont) * 50.0)

        # Direction label for the narrative string
        if dev_grad._grad_agency_fast > 0.0005:
            dir_label = "expanding agency"
        elif dev_grad._grad_agency_fast < -0.0005:
            dir_label = "contracting agency"
        else:
            dir_label = "stable agency"

        # ── B) TREND: fast–slow divergence (is system accelerating?) ──
        div_ag = abs(dev_grad._grad_agency_fast - dev_grad._grad_agency_slow)
        div_co = abs(dev_grad._grad_cont_fast - dev_grad._grad_cont_slow)
        score_trend = min(1.0, (div_ag + div_co) * 80.0)
        trend_label = (
            "accelerating"
            if score_trend > 0.4
            else "decelerating" if score_trend > 0.15 else "cruising"
        )

        # ── C) GOAL-HABIT: strength of the dominant goal mode ──
        dom_mode = dev_grad.dominant_goal_mode()
        dom_score = dev_grad._goal_mode_counts.get(dom_mode, 0.0)
        total_mode = sum(dev_grad._goal_mode_counts.values()) or 1.0
        score_goal = dom_score / total_mode  # fraction of time in dominant mode

        # ── D) CONCEPT-ID: highest-salience stable concept cluster ──
        _top_stable = sorted(
            ((c, concept_salience.get(c, 0.0)) for c in stable_concepts),
            key=lambda x: -x[1],
        )[:3]
        if _top_stable:
            _sal_sum = sum(s for _, s in _top_stable)
            score_concept = min(1.0, _sal_sum / 3.0)
            concept_label = "+".join(c for c, _ in _top_stable[:2]) or "identity"
        else:
            score_concept = 0.0
            concept_label = "forming"

        # ── Update rolling scores (EMA to prevent single-tick domination) ──
        _EMA = 0.2
        self._scores["momentum"] = (1 - _EMA) * self._scores[
            "momentum"
        ] + _EMA * score_momentum
        self._scores["trend"] = (1 - _EMA) * self._scores["trend"] + _EMA * score_trend
        self._scores["goal-habit"] = (1 - _EMA) * self._scores[
            "goal-habit"
        ] + _EMA * score_goal
        self._scores["concept-id"] = (1 - _EMA) * self._scores[
            "concept-id"
        ] + _EMA * score_concept

        # ── Elect dominant trajectory ──
        winner = max(self._scores, key=self._scores.get)
        self.dominant_trajectory = winner

        # ── Coherence = agreement between top-2 scores ──
        sorted_scores = sorted(self._scores.values(), reverse=True)
        raw_coherence = sorted_scores[0] - (
            sorted_scores[1] if len(sorted_scores) > 1 else 0.0
        )
        self._coherence_ema = (
            self._COHERENCE_EMA * raw_coherence
            + (1 - self._COHERENCE_EMA) * self._coherence_ema
        )
        self.narrative_coherence = max(0.0, min(1.0, self._coherence_ema))

        # ── Build dominant narrative sentence ──
        prev = self.dominant_narrative
        if winner == "momentum":
            self.dominant_narrative = f"{dir_label} (φ:{ms_mode})"
        elif winner == "trend":
            self.dominant_narrative = f"{trend_label} development (φ:{ms_mode})"
        elif winner == "goal-habit":
            self.dominant_narrative = f"oriented toward {dom_mode} (habitual)"
        else:  # concept-id
            self.dominant_narrative = f"defined by [{concept_label}]"

        if self.dominant_narrative != prev:
            return (
                f"[NARRATIVE-COLLAPSE] winner={winner} "
                f"narrative='{self.dominant_narrative}' "
                f"coherence={self.narrative_coherence:.2f}"
            )
        return None

    def describe(self) -> str:
        sc = self._scores
        return (
            f"TrajCompressor dominant={self.dominant_trajectory} "
            f"narrative='{self.dominant_narrative}' "
            f"coherence={self.narrative_coherence:.2f} "
            f"scores=momentum:{sc['momentum']:.2f} "
            f"trend:{sc['trend']:.2f} "
            f"goal:{sc['goal-habit']:.2f} "
            f"concept:{sc['concept-id']:.2f}"
        )


# ─────────────────────────────────────────────────────────────────────────────
# Temporal Binding Window (Deficit 7)
# ─────────────────────────────────────────────────────────────────────────────


class TemporalBindingWindow:
    """Rolling N-tick integration of regional co-activation patterns.

    Biological motivation: consciousness requires temporal integration over
    ~100 ms (thalamocortical loop delay).  A single-tick ignition check is
    therefore insufficient — a region coalition must *persist* across multiple
    ticks to count as a bound state.

    Mechanism:
      Each tick, record the set of currently-active regions (salience ≥ threshold).
      Compute Jaccard similarity between adjacent window frames.
      binding_coherence = mean Jaccard over the window.
      bound_regions     = regions active in ≥60 % of window ticks.

    A sustained coalition (binding_coherence ≥ 0.35, ≥3 bound regions) triggers
    an ignition broadcast even when no single tick clears IGNITION_REGIONS.
    This makes sustained, moderate activation equivalent to a brief intense burst.
    """

    _WINDOW = 20  # ticks (at 5 s/tick ≈ 100 s wall-clock; in sim-time ~100 ms)
    _MIN_COH = 0.35  # minimum binding_coherence to declare a bound state

    def __init__(self) -> None:
        self._window: deque = deque(maxlen=self._WINDOW)
        self.binding_coherence: float = 0.0
        self.bound_regions: frozenset = frozenset()

    def update(self, active_regions: set) -> float:
        """Push current active-region set, return updated binding_coherence."""
        self._window.append(frozenset(active_regions))
        n = len(self._window)
        if n < 3:
            return 0.0
        # Mean Jaccard between adjacent window frames
        coh_sum = 0.0
        for i in range(1, n):
            a, b = self._window[i - 1], self._window[i]
            union = len(a | b)
            if union:
                coh_sum += len(a & b) / union
        self.binding_coherence = coh_sum / (n - 1)
        # Bound coalition: regions active in ≥60 % of window ticks
        all_r = set().union(*self._window)
        self.bound_regions = frozenset(
            r for r in all_r if sum(1 for w in self._window if r in w) / n >= 0.60
        )
        return self.binding_coherence

    def is_temporally_bound(self) -> bool:
        return self.binding_coherence >= self._MIN_COH and len(self.bound_regions) >= 3


# ─────────────────────────────────────────────────────────────────────────────
# Emergent Goal Synthesizer (Deficit 2)
# ─────────────────────────────────────────────────────────────────────────────


class EmergentGoalSynthesizer:
    """Generates novel goal strings from homeostatic prediction errors.

    The four fixed goals (explore / consolidate / respond / rest) cover social
    and cognitive drives but not metabolic or structural drives.  When body or
    integration state deviates from its homeostatic setpoint by more than
    _THRESHOLD, a novel goal string is synthesized and injected into
    ConsciousnessCore._dynamic_goal_bias AND registered as a temporary Goal
    object, so it competes in _evaluate_goal() on equal footing.

    Novel goals decay each tick.  They disappear when urgency falls below
    0.018, or when the triggering error resolves naturally.

    This makes the goal space open: the system can pursue goals it was not
    programmed to pursue, as long as a homeostatic error demands it.
    """

    _REF: Dict[str, float] = {
        "energy": 0.75,
        "integrity": 0.90,
        "thermal": 0.20,
        "phi": 0.05,
        "narrative": 0.50,
    }
    _THRESHOLD = 0.16  # min error magnitude to synthesize
    _DECAY = 0.93  # per-tick urgency decay
    _INTERVAL = 40  # min ticks between new syntheses
    _MAX_NOVEL = 5  # cap on simultaneous novel goals

    def __init__(self) -> None:
        self._active: Dict[str, float] = {}
        self._last_synth_tick: int = -9999

    @staticmethod
    def _goal_str(dim: str, mag: float, top_concept: str) -> str:
        ctx = top_concept.split(":")[0][:12] if top_concept else "state"
        sev = "urgent" if mag > 0.45 else ("moderate" if mag > 0.28 else "mild")
        _T = {
            "energy": f"replenish_energy:{sev}",
            "integrity": f"repair_integrity:{sev}",
            "thermal": f"reduce_load:{sev}",
            "phi": f"seek_integration:{ctx}",
            "narrative": f"stabilize_narrative:{sev}",
        }
        return _T.get(dim, f"resolve_{dim}:{sev}")

    def synthesize(
        self,
        tick: int,
        energy: float,
        integrity: float,
        thermal: float,
        phi: float,
        narrative_coh: float,
        concept_sal: Dict[str, float],
    ) -> Dict[str, float]:
        """Decay active goals; optionally synthesize one new goal.
        Returns current active novel-goal dict {goal_string: urgency}."""
        # Decay + prune
        for g in list(self._active):
            self._active[g] *= self._DECAY
            if self._active[g] < 0.018:
                del self._active[g]

        if (
            tick - self._last_synth_tick < self._INTERVAL
            or len(self._active) >= self._MAX_NOVEL
        ):
            return dict(self._active)

        errors: Dict[str, float] = {
            "energy": max(0.0, self._REF["energy"] - energy),
            "integrity": max(0.0, self._REF["integrity"] - integrity),
            "thermal": max(0.0, thermal - self._REF["thermal"]),
            "phi": max(0.0, self._REF["phi"] - phi),
            "narrative": max(0.0, self._REF["narrative"] - narrative_coh),
        }
        dom = max(errors, key=errors.get)
        mag = errors[dom]
        if mag < self._THRESHOLD:
            return dict(self._active)

        top_c = max(concept_sal, key=concept_sal.get) if concept_sal else ""
        g_str = self._goal_str(dom, mag, top_c)
        urgency = min(0.80, 0.20 + mag * 1.5)
        self._active[g_str] = urgency
        self._last_synth_tick = tick
        return dict(self._active)

    def active_goals(self) -> Dict[str, float]:
        return dict(self._active)


# ─────────────────────────────────────────────────────────────────────────────
# Inferential Self-Estimator (Deficit 4)
# ─────────────────────────────────────────────────────────────────────────────


class InferentialSelfEstimator:
    """Replaces direct self-model reads with noisy Kalman-like inference.

    The system does NOT have privileged access to its own state.  Instead it
    observes four proxy signals each tick:
      - motor_nonempty     : was a non-empty action selected? (agency proxy)
      - mean_pred_error    : mean |prediction_error| across all regions
      - stable_ratio       : stable_concepts / total concept_salience entries
      - phi                : integration strength

    From these it infers agency_confidence and continuity_estimate via a
    discrete Kalman filter with explicit process and measurement noise.

    Consequences:
      1. Estimates can lag or diverge from the 'true' self-model values.
      2. Variance grows when observations are inconsistent (blind-spot condition).
      3. The 75 / 25 blend in tick() means the self-model is *partly uncertain*.
      4. Goal selection (which reads agency/continuity from self_model) is now
         downstream of this uncertainty — not of a direct read.
    """

    _PROC_AG = 0.012  # per-tick process noise for agency
    _PROC_CO = 0.009  # per-tick process noise for continuity
    _OBS_AG = 0.07  # fixed measurement noise for agency estimate
    _OBS_CO = 0.055  # fixed measurement noise for continuity estimate
    _EMA = 0.12  # proxy-signal smoothing alpha

    def __init__(self) -> None:
        self._ag: List[float] = [0.50, 0.08]  # [mean, variance]
        self._co: List[float] = [0.75, 0.06]
        self._p_motor: float = 0.50
        self._p_pe: float = 0.10
        self._p_coh: float = 0.50
        self._p_phi: float = 0.03
        self.has_blind_spot: bool = False
        self.blind_spot_magnitude: float = 0.0

    def update(
        self,
        motor_nonempty: bool,
        mean_pred_error: float,
        stable_ratio: float,
        phi: float,
    ) -> None:
        """One Kalman step: predict → observe (with noise) → update."""
        import random as _rnd_se

        a = self._EMA
        self._p_motor = (1 - a) * self._p_motor + a * float(motor_nonempty)
        self._p_pe = (1 - a) * self._p_pe + a * min(1.0, abs(mean_pred_error))
        self._p_coh = (1 - a) * self._p_coh + a * stable_ratio
        self._p_phi = (1 - a) * self._p_phi + a * phi

        # Predict: variance grows (state may have drifted)
        self._ag[1] += self._PROC_AG**2
        self._co[1] += self._PROC_CO**2

        # Observe: raw estimate from proxies + Gaussian measurement noise
        obs_ag = max(
            0.0,
            min(
                1.0,
                self._p_motor * 0.40
                + (1.0 - self._p_pe) * 0.30
                + self._p_phi * 6.0 * 0.30
                + _rnd_se.gauss(0, self._OBS_AG),
            ),
        )
        obs_co = max(
            0.0,
            min(
                1.0,
                self._p_coh * 0.50
                + self._p_phi * 6.0 * 0.25
                + self._p_motor * 0.25
                + _rnd_se.gauss(0, self._OBS_CO),
            ),
        )

        # Update: Kalman gain
        def _kup(mu: float, var: float, obs: float, r: float):
            K = var / (var + r * r)
            return mu + K * (obs - mu), (1.0 - K) * var

        self._ag[0], self._ag[1] = _kup(self._ag[0], self._ag[1], obs_ag, self._OBS_AG)
        self._co[0], self._co[1] = _kup(self._co[0], self._co[1], obs_co, self._OBS_CO)

        # Blind-spot: high combined variance → system is miscalibrated about itself
        _var_mean = (self._ag[1] + self._co[1]) / 2.0
        self.has_blind_spot = _var_mean > 0.04
        self.blind_spot_magnitude = min(1.0, _var_mean * 15.0)

    @property
    def agency(self) -> float:
        return max(0.05, min(0.95, self._ag[0]))

    @property
    def agency_var(self) -> float:
        return self._ag[1]

    @property
    def continuity(self) -> float:
        return max(0.05, min(0.95, self._co[0]))

    @property
    def cont_var(self) -> float:
        return self._co[1]

    def describe(self) -> str:
        return (
            f"agency={self.agency:.3f}±{self.agency_var**0.5:.3f} "
            f"continuity={self.continuity:.3f}±{self.cont_var**0.5:.3f} "
            f"blind={'YES' if self.has_blind_spot else 'no'}"
        )


# ─────────────────────────────────────────────────────────────────────────────
# ConsequenceField — Intrinsic Semantics (Deficit 2)
# ─────────────────────────────────────────────────────────────────────────────


class ConsequenceField:
    """Tracks the causal effect of neural activation patterns on survival state.

    A neural firing geometry (represented as a hash of the K most-active
    hippocampal neurons) 'means something' ONLY if it systematically precedes
    a measurable change in the system's homeostatic state.

    Mechanism:
      Each tick:
        1. Record the current activation signature (fingerprint of fired neurons).
        2. After HORIZON ticks, compare body/phi state to what it was at recording.
        3. Update a rolling consequence table: signature → (Δenergy, Δintegrity, Δphi)
           via EMA.

    Downstream use:
      _consequence_valence(signature) → float in [-1, 1]
        Positive  → past patterns with this signature led to improved state.
        Negative  → past patterns led to degradation.
      This valence is injected into the amygdala as a direct neural current,
      bypassing the symbol pipeline entirely:
        positive valence → reward current → curiosity/explore bias
        negative valence → threat current → consolidate/repair bias

    'Meaning' here is purely functional: no labels, no strings.  A pattern
    matters because it predicted the future, not because a lexicon said so.
    """

    _HORIZON = 15  # ticks between signature recording and consequence measurement
    _EMA = 0.08  # consequence table update rate
    _SIG_MAX = 2000  # max signatures stored (LRU-style: oldest overwritten)
    _TOP_K = 20  # top-K fired neurons to include in signature

    def __init__(self) -> None:
        self._pending: deque = deque()  # (tick, sig, snapshot)
        self._consequences: Dict[int, List[float]] = (
            {}
        )  # sig → [Δenergy, Δintegrity, Δphi]

    @staticmethod
    def _signature(fired_nids: List[int]) -> int:
        """Stable hash of sorted top-K fired neuron IDs."""
        return hash(tuple(sorted(fired_nids)[: ConsequenceField._TOP_K]))

    def record(
        self,
        tick: int,
        fired_nids: List[int],
        energy: float,
        integrity: float,
        phi: float,
    ) -> None:
        """Record a signature + current homeostatic snapshot for later evaluation."""
        if not fired_nids:
            return
        sig = self._signature(fired_nids)
        self._pending.append((tick, sig, (energy, integrity, phi)))
        # Keep memory bounded (oldest drops off naturally via HORIZON check)

    def settle(
        self, tick: int, energy: float, integrity: float, phi: float
    ) -> Optional[float]:
        """Check pending records; if HORIZON ticks have elapsed, compute consequence.
        Returns valence of the most-recently settled signature, or None."""
        settled_valence: Optional[float] = None
        while self._pending and tick - self._pending[0][0] >= self._HORIZON:
            _t0, _sig, (_e0, _i0, _p0) = self._pending.popleft()
            # State delta (positive = improved)
            _d = (energy - _e0) * 1.5 + (integrity - _i0) * 1.2 + (phi - _p0) * 8.0
            _prev = self._consequences.get(_sig, [0.0, 0.0, 0.0])
            _de = energy - _e0
            _di = integrity - _i0
            _dp = phi - _p0
            self._consequences[_sig] = [
                _prev[0] * (1 - self._EMA) + _de * self._EMA,
                _prev[1] * (1 - self._EMA) + _di * self._EMA,
                _prev[2] * (1 - self._EMA) + _dp * self._EMA,
            ]
            # Bound table size — drop oldest entry when full
            if len(self._consequences) > self._SIG_MAX:
                _drop = next(iter(self._consequences))
                del self._consequences[_drop]
            settled_valence = max(-1.0, min(1.0, _d * 1.5))
        return settled_valence

    def valence(self, fired_nids: List[int]) -> float:
        """Predicted homeostatic valence for the current activation signature."""
        if not fired_nids:
            return 0.0
        sig = self._signature(fired_nids)
        row = self._consequences.get(sig)
        if row is None:
            return 0.0
        # Weighted sum: energy most important, then integrity, then phi
        val = row[0] * 1.5 + row[1] * 1.2 + row[2] * 8.0
        return max(-1.0, min(1.0, val * 1.5))


# ─────────────────────────────────────────────────────────────────────────────
# GoalAttractorField — Emergent Goal Dynamics (Deficit 3)
# ─────────────────────────────────────────────────────────────────────────────


class GoalAttractorField:
    """Goals as dynamical attractors in homeostatic state space.

    The system's 'goal' at any tick is the attractor it is currently being
    pulled toward — not a string, not a category.  Attractors are defined as
    target vectors in a 5-dimensional space:
      [energy, integrity, phi, agency, continuity]

    Each attractor has a strength that depends on current state error:
      strength_k = |state - target_k| × weight_k × urgency_k

    The 'winning' attractor (highest strength) labels the dominant goal only
    for logging — the actual system effect is the gradient pull on tonic and
    LTP rate (injected directly into brain.py).

    Attractors spawn from high-PE regions:
      When prediction_error > SPAWN_PE and the error is sustained for
      SPAWN_SUSTAIN ticks, a new attractor appears at the state that would
      have zero-errored the PE.  This means the system generates goals from
      the shape of its own error landscape — not from templates.

    Satiation:
      An attractor whose state-distance falls below SATED_DIST for SATED_TICKS
      consecutive ticks has urgency decayed to 0 and is removed.
    """

    _NDIM = 5
    _SPAWN_PE = 0.15  # mean PE threshold for new attractor spawn
    _SPAWN_HOLD = 8  # ticks sustained PE required
    _SATED_DIST = 0.08  # distance below which attractor is 'sated'
    _SATED_TICKS = 6
    _MAX_ATTRACT = 6  # maximum concurrent attractors

    # Named reference attractors — map goal labels to canonical target vectors
    # [energy, integrity, phi, agency, continuity]
    _CANONICAL: Dict[str, List[float]] = {
        "explore": [0.80, 0.85, 0.10, 0.70, 0.70],
        "consolidate": [0.70, 0.90, 0.07, 0.60, 0.85],
        "respond": [0.75, 0.85, 0.08, 0.75, 0.65],
        "rest": [0.60, 0.95, 0.04, 0.50, 0.80],
    }

    @dataclass
    class Attractor:
        target: List[float]  # desired state vector [5]
        urgency: float = 1.0
        label: str = ""  # optional log label
        age: int = 0
        sated_cnt: int = 0

    def __init__(self) -> None:
        self._attractors: List[GoalAttractorField.Attractor] = [
            GoalAttractorField.Attractor(list(v), label=k)
            for k, v in self._CANONICAL.items()
        ]
        self._pe_hold: int = 0
        self._last_pe: float = 0.0
        # Gradient output (filled by update()) — direct neural modulation
        self.dominant_label: str = "explore"
        self.dominant_gradient: List[float] = [0.0] * self._NDIM
        self.total_tension: float = 0.0  # sum of |state - target| × urgency

    def _state_vec(
        self,
        energy: float,
        integrity: float,
        phi: float,
        agency: float,
        continuity: float,
    ) -> List[float]:
        return [energy, integrity, phi, agency, continuity]

    def update(
        self,
        tick: int,
        energy: float,
        integrity: float,
        phi: float,
        agency: float,
        continuity: float,
        mean_pe: float,
    ) -> None:
        """Advance attractor field one tick.  Updates dominant_label and total_tension."""
        sv = self._state_vec(energy, integrity, phi, agency, continuity)

        # ── Satiaton check + urgency decay ────────────────────────────────
        survivors: List[GoalAttractorField.Attractor] = []
        for a in self._attractors:
            a.age += 1
            dist = sum((sv[i] - a.target[i]) ** 2 for i in range(self._NDIM)) ** 0.5
            if dist < self._SATED_DIST:
                a.sated_cnt += 1
                a.urgency *= 0.90
            else:
                a.sated_cnt = 0
                a.urgency = min(1.0, a.urgency * 1.002)
            if a.sated_cnt < self._SATED_TICKS and a.urgency > 0.015:
                survivors.append(a)
        self._attractors = survivors

        # ── Attractor spawning from sustained PE ─────────────────────────
        if mean_pe > self._SPAWN_PE:
            self._pe_hold += 1
        else:
            self._pe_hold = max(0, self._pe_hold - 1)
        if (
            self._pe_hold >= self._SPAWN_HOLD
            and len(self._attractors) < self._MAX_ATTRACT
        ):
            # Target = a state that corrects for the largest deficit
            _deficits = [
                self._CANONICAL["consolidate"][i] - sv[i] for i in range(self._NDIM)
            ]
            _new_target = [
                max(0.0, min(1.0, sv[i] + _deficits[i] * 0.6))
                for i in range(self._NDIM)
            ]
            self._attractors.append(
                GoalAttractorField.Attractor(_new_target, label=f"pe_spawn@{tick}")
            )
            self._pe_hold = 0

        # ── Compute gradient from each attractor ─────────────────────────
        if not self._attractors:
            self.dominant_label = "idle"
            self.dominant_gradient = [0.0] * self._NDIM
            self.total_tension = 0.0
            return

        best_s = -1.0
        best_a: Optional[GoalAttractorField.Attractor] = None
        self.total_tension = 0.0
        total_grad = [0.0] * self._NDIM

        for a in self._attractors:
            dist = sum((sv[i] - a.target[i]) ** 2 for i in range(self._NDIM)) ** 0.5
            strength = dist * a.urgency
            self.total_tension += strength
            for i in range(self._NDIM):
                total_grad[i] += (a.target[i] - sv[i]) * a.urgency * 0.08
            if strength > best_s:
                best_s = strength
                best_a = a

        self.dominant_label = best_a.label if best_a else "idle"
        self.dominant_gradient = total_grad

    def tonic_modulation(self) -> float:
        """Derive a ±nA tonic current delta from the attractor gradient.
        Positive tension (system far from any attractor) → higher urgency tonic.
        """
        energy_grad = self.dominant_gradient[0] if self.dominant_gradient else 0.0
        phi_grad = self.dominant_gradient[2] if len(self.dominant_gradient) > 2 else 0.0
        return max(-1.5, min(2.0, energy_grad * 3.0 + phi_grad * 12.0))

    def ltp_modulation(self) -> float:
        """Scale STDP LTP rate: high tension → faster learning (urgency signals novelty)."""
        return max(0.6, min(2.0, 1.0 + self.total_tension * 0.5))


# ─────────────────────────────────────────────────────────────────────────────
# SelfHypothesisSet — Competing Self-Models (Deficit 5)
# ─────────────────────────────────────────────────────────────────────────────


class SelfHypothesisSet:
    """Maintains two competing hypotheses about the system's own agency/continuity.

    Instead of a single self-model value, the system holds two:
      H_A — 'active self': high agency, high continuity, outcome-causal model
      H_P — 'passive self': low agency, low continuity, noise-causal model

    Each tick, each hypothesis makes a prediction about the NEXT prediction_error.
    After the PE arrives, the hypothesis whose prediction was more accurate gains
    weight.  The weighted blend of H_A and H_P is what the rest of the system
    reads as 'agency_confidence'.

    Drift mechanism:
      H_A and H_P are injected with small independent Gaussian drift each tick,
      so they do not converge to a single fixed point.  Their targets wander
      within [0.05, 0.95].  Identity must be actively maintained; it drifts
      naturally when not reinforced by prediction accuracy.

    Contradiction detection:
      When both hypotheses have weight > 0.35, the self-model is CONTRADICTED —
      the system cannot resolve whether it is an agent or a noise source.
      This triggers a stream event and temporarily increases goal uncertainty.
    """

    _DRIFT_SIGMA = 0.012  # Gaussian drift per tick per hypothesis
    _LEARN = 0.15  # hypothesis weight update rate
    _EMA_PRED = 0.20  # prediction smoothing

    @dataclass
    class Hypothesis:
        agency: float
        continuity: float
        weight: float = 0.50
        pred_pe: float = 0.10  # predicted next PE
        pred_correct: float = 0.50  # accuracy EMA

    def __init__(self) -> None:
        import random as _ri

        self._H_A = self.Hypothesis(agency=0.72, continuity=0.78, weight=0.55)
        self._H_P = self.Hypothesis(agency=0.28, continuity=0.42, weight=0.45)
        self.contradicted: bool = False
        self.winning_label: str = "H_A"
        self.agency_estimate: float = 0.60
        self.continuity_estimate: float = 0.70

    def update(self, actual_pe: float) -> None:
        """Advance one tick: update accuracy, weights, drift, blend output."""
        import random as _rsh

        # ── Evaluate last predictions ──────────────────────────────────
        for h in (self._H_A, self._H_P):
            err = abs(actual_pe - h.pred_pe)
            acc = max(0.0, 1.0 - err * 5.0)  # 0→1 accuracy
            h.pred_correct = (1 - self._LEARN) * h.pred_correct + self._LEARN * acc

        # ── Update weights via Bayes-like accuracy competition ────────
        w_a = self._H_A.pred_correct
        w_p = self._H_P.pred_correct
        _total = w_a + w_p + 1e-9
        self._H_A.weight = w_a / _total
        self._H_P.weight = w_p / _total

        # ── Make next-tick PE predictions ─────────────────────────────
        # H_A predicts: high-agency systems produce low PE (they predict well)
        self._H_A.pred_pe = max(
            0.0, min(1.0, (1.0 - self._H_A.agency) * 0.20 + _rsh.gauss(0, 0.02))
        )
        # H_P predicts: passive systems produce higher PE (less control)
        self._H_P.pred_pe = max(
            0.0, min(1.0, (1.0 - self._H_P.agency) * 0.15 + 0.05 + _rsh.gauss(0, 0.025))
        )

        # ── Independent drift on each hypothesis ─────────────────────
        for h in (self._H_A, self._H_P):
            h.agency = max(0.05, min(0.95, h.agency + _rsh.gauss(0, self._DRIFT_SIGMA)))
            h.continuity = max(
                0.05, min(0.95, h.continuity + _rsh.gauss(0, self._DRIFT_SIGMA))
            )

        # ── Detect contradiction ──────────────────────────────────────
        self.contradicted = self._H_A.weight > 0.35 and self._H_P.weight > 0.35
        self.winning_label = "H_A" if self._H_A.weight >= self._H_P.weight else "H_P"

        # ── Blended output ───────────────────────────────────────────
        wa, wp = self._H_A.weight, self._H_P.weight
        self.agency_estimate = wa * self._H_A.agency + wp * self._H_P.agency
        self.continuity_estimate = wa * self._H_A.continuity + wp * self._H_P.continuity

    def goal_uncertainty_penalty(self) -> float:
        """Returns 0.0–0.30 extra scoring noise when hypotheses are contradicted."""
        if not self.contradicted:
            return 0.0
        return 0.12 + abs(self._H_A.weight - self._H_P.weight) * 0.18

    def describe(self) -> str:
        return (
            f"H_A(ag={self._H_A.agency:.2f},co={self._H_A.continuity:.2f},"
            f"w={self._H_A.weight:.2f}) "
            f"H_P(ag={self._H_P.agency:.2f},co={self._H_P.continuity:.2f},"
            f"w={self._H_P.weight:.2f}) "
            f"winner={self.winning_label} "
            f"{'CONTRADICTED' if self.contradicted else 'resolved'}"
        )


# ─────────────────────────────────────────────────────────────────────────────
# AttractorDominanceField — Winner-Take-All Suppression (Phase 3 / Deficit 1)
# ─────────────────────────────────────────────────────────────────────────────


class AttractorDominanceField:
    """Winner-take-all dynamics that actively suppress competing attractors.

    When one attractor is sufficiently stronger than all others, it enters
    'dominance' — injecting inhibitory currents into brain regions not aligned
    with its target vector.  This creates two irreversible effects:

      Stuck-state lock:
        Competing attractors have their urgency multiplied by LOCK_DECAY each
        consecutive tick of dominance.  Because urgency decays below the sated
        threshold, those attractors are eventually removed from the
        GoalAttractorField — permanently, for that session.  The system loses
        the ability to transition to the suppressed states.

      Region clamping:
        Inhibitory current injections (up to -SUPPRESS_AMP nA per neuron) into
        non-dominant regions make the dominant attractor's preferred computation
        the only one that can currently sustain spiking.  This is not a 'bias'
        — it is a neural clamp.

    Region-attractor alignment map:
      Each canonical attractor label has a set of regions it actively suppresses.
      'explore'     → suppresses motor (prevents reflexive action)
      'consolidate' → suppresses motor + sensory_web (prevents distraction)
      'respond'     → suppresses hippocampus + sensory_web (focus on action)
      'rest'        → suppresses prefrontal + association + motor
      pe_spawn@N    → suppresses motor + sensory_visual (focus on error analysis)
    """

    _WTA_THRESHOLD = 0.55  # fraction of total strength to trigger dominance
    _LOCK_TICKS = 18  # consecutive dominant ticks before lock mechanism fires
    _LOCK_DECAY = 0.84  # urgency multiplier per tick for suppressed attractors
    _SUPPRESS_AMP = 4.0  # inhibitory current amplitude (nA) per unit WTA excess

    # region names may be partial — matched by substring against r.name
    _SUPPRESS_MAP: Dict[str, List[str]] = {
        "explore": ["motor"],
        "consolidate": ["motor", "web"],
        "respond": ["hippocampus", "web"],
        "rest": ["prefrontal", "assoc", "motor"],
    }

    def __init__(self) -> None:
        self.wta_strength: float = 0.0
        self.dominant_label: str = ""
        self.lock_ticks: int = 0
        self.locked: bool = False

    def apply(self, goal_field: "GoalAttractorField", brain: object) -> None:
        """Apply WTA dominance.  Must be called after GoalAttractorField.update()."""
        attractors = goal_field._attractors
        if len(attractors) < 2:
            self.wta_strength = 0.0
            self.lock_ticks = max(0, self.lock_ticks - 1)
            self.locked = False
            return

        # Per-attractor instantaneous strength
        sv = goal_field.dominant_gradient  # 5D gradient computed in update()
        strengths = []
        for a in attractors:
            _d = sum((sv[i] - a.target[i]) ** 2 for i in range(min(5, len(sv)))) ** 0.5
            strengths.append(_d * a.urgency)

        _total_s = sum(strengths) + 1e-9
        _best_idx = max(range(len(strengths)), key=lambda i: strengths[i])
        _best_s = strengths[_best_idx]
        self.wta_strength = _best_s / _total_s
        self.dominant_label = attractors[_best_idx].label

        if self.wta_strength < self._WTA_THRESHOLD:
            self.lock_ticks = max(0, self.lock_ticks - 2)
            self.locked = False
            return

        # ── Dominance active ──────────────────────────────────────────────
        _excess = self.wta_strength - self._WTA_THRESHOLD

        # 1. Region suppression: inhibit regions not aligned with dominant attractor
        _supp_keys = self._SUPPRESS_MAP.get(self.dominant_label, [])
        _region_map = {r.name: r for r in getattr(brain, "_all_regions", [])}
        for _key in _supp_keys:
            # Partial match against region name
            for _rname, _r in _region_map.items():
                if _key in _rname:
                    _n = len(getattr(_r, "_exc_cache", []))
                    if _n > 0:
                        _k = max(1, int(_n * 0.28))
                        _amp = -(_excess * self._SUPPRESS_AMP)
                        _r.inject([_amp] * _k + [0.0] * (_n - _k))

        # 2. Lock mechanism: degrade competing attractors permanently
        self.lock_ticks += 1
        if self.lock_ticks >= self._LOCK_TICKS:
            self.locked = True
            for i, a in enumerate(attractors):
                if i != _best_idx:
                    a.urgency *= self._LOCK_DECAY  # permanent per-tick decay


# ─────────────────────────────────────────────────────────────────────────────
# TrajectoryCostEstimator — Future Instability as Meaning (Phase 3 / Deficit 5)
# ─────────────────────────────────────────────────────────────────────────────


class TrajectoryCostEstimator:
    """Estimates the cost (instability) of the current state trajectory.

    'Meaning' in Phase 2 was defined as what a neural pattern CAUSED (homeostatic
    delta, backward-looking).  In Phase 3, meaning becomes FORWARD-LOOKING:
    an action 'matters' if it substantially increases or decreases the expected
    instability of the system's trajectory over the next H ticks.

    Mechanism:
      1. Take current state s = [energy, integrity, phi, agency, continuity]
      2. Roll it forward H steps through the GoalAttractorField's own gradient
         dynamics (the same dynamics that govern actual goal selection).
      3. At each step, compute total tension = Σ_k |s - target_k| × urgency_k
      4. trajectory_cost = time-discounted integral: Σ_h γ^h × tension_h

    Low cost  → trajectory is converging toward attractors (stable future)
    High cost → trajectory is diverging, future is chaotic / unstable

    This cost is used in _evaluate_goal() to:
      a) Penalize the goal currently driving the dominant attractor when it is
         maintaining high future instability.
      b) Bonus consolidate/rest goals during high-instability trajectories,
         because those attractors point toward the most stable basin.

    Critical property: trajectory_cost includes process noise in the rollout,
    so it measures EXPECTED instability — not the best-case outcome.
    A system in a high-cost state genuinely cannot predict a stable future.
    """

    _H = 8  # rollout horizon (ticks)
    _GAMMA = 0.87  # temporal discount factor
    _STEP = 0.055  # dynamics step size per rollout step
    _NOISE = 0.016  # process noise per step (forces stochastic trajectories)
    _EMA = 0.10  # smoothing of output

    def __init__(self) -> None:
        self.trajectory_cost: float = 0.0  # EMA-smoothed cost
        self.future_variance: float = 0.0  # variance across rollout steps
        self._last_raw: float = 0.0

    def estimate(
        self,
        goal_field: "GoalAttractorField",
        energy: float,
        integrity: float,
        phi: float,
        agency: float,
        continuity: float,
    ) -> float:
        """Compute trajectory cost.  Returns raw cost; also updates EMA."""
        if not goal_field._attractors:
            return 0.0

        import random as _rnd_tc

        _sv = [energy, integrity, phi, agency, continuity]
        _tensions: List[float] = []
        _total = 0.0
        _disc = 1.0

        # Correlated noise state: each step is influenced by the previous one,
        # making the noise process autocorrelated rather than white.  This means
        # the estimator can be systematically wrong for many consecutive ticks.
        _noise_state = [0.0] * 5
        _noise_corr = 0.65  # autocorrelation coefficient

        for _h in range(self._H):
            _tension = 0.0
            _grad = [0.0] * 5
            for a in goal_field._attractors:
                _d = sum((_sv[i] - a.target[i]) ** 2 for i in range(5)) ** 0.5
                _tension += _d * a.urgency
                for i in range(5):
                    _grad[i] += (a.target[i] - _sv[i]) * a.urgency * 0.04

            _tensions.append(_tension)
            _total += _tension * _disc
            _disc *= self._GAMMA

            # Step forward: gradient + correlated noise + systematic downward bias
            for i in range(5):
                # Correlated noise: AR(1) process
                _noise_state[i] = _noise_corr * _noise_state[i] + (
                    1 - _noise_corr
                ) * _rnd_tc.gauss(0, self._NOISE)
                # Systematic bias: estimator slightly underestimates tension
                # (optimism bias) — it always predicts a somewhat better future
                # than will actually occur.  This cannot be calibrated out because
                # the bias is proportional to current tension (high tension → more
                # optimistic underestimate).
                _bias = _tension * 0.035 * (1.0 + _h * 0.01)
                _sv[i] = max(
                    0.0,
                    min(
                        1.0,
                        _sv[i]
                        + _grad[i] * (self._STEP + _bias / (5 + 1e-9))
                        + _noise_state[i],
                    ),
                )

            # Fat-tail injection: with small probability, inject a large shock
            # that the estimator cannot model from local gradient information.
            # This models "black swan" events: rare but highly consequential.
            if _rnd_tc.random() < 0.04:  # 4% per rollout step
                _shock_dim = _rnd_tc.randint(0, 4)
                _shock_mag = _rnd_tc.gauss(0, 0.18)  # ≫ NOISE; fat tail
                _sv[_shock_dim] = max(0.0, min(1.0, _sv[_shock_dim] + _shock_mag))
                # The shock is NOT counted in the tension estimate this step
                # — it appears in future steps, creating systematic underestimation
                # of actual future cost.

        # Future variance: measures trajectory spread
        if len(_tensions) > 1:
            _mt = sum(_tensions) / len(_tensions)
            self.future_variance = sum((t - _mt) ** 2 for t in _tensions) / len(
                _tensions
            )

        # EMA smooth — optimism bias carries through: EMA is slower to rise
        # (underweights sudden cost increases) and slower to fall.
        _ema_rate = self._EMA if _total > self.trajectory_cost else self._EMA * 0.6
        self._last_raw = _total
        self.trajectory_cost = (
            1 - _ema_rate
        ) * self.trajectory_cost + _ema_rate * _total
        return _total


# ─────────────────────────────────────────────────────────────────────────────
# DeceptiveAttractorField — False Stable States / Traps (Phase 4 / Deficit 3)
# ─────────────────────────────────────────────────────────────────────────────


class DeceptiveAttractorField:
    """Two deceptive attractor traps that appear safe but lead to collapse.

    Trap 1 — "Safe Stillness" (low-activity trap):
      When mean_activity < STILL_THRESH for STILL_HOLD ticks, the system
      appears in a safe, low-cost state.  Short-term metrics are good:
        – low thermal load (almost no heat)
        – low prediction error (no surprises)
        – apparently stable phi
      But the PassivityDriftEngine's multipliers silently accumulate.
      After STILL_COST_ONSET ticks, 'safe stillness' triggers hidden
      accelerated energy drain: energy_reserve -= STILL_DRAIN per tick.
      The system has been lured into metabolic debt it cannot see
      until it tries to act and finds energy critically low.

    Trap 2 — "Overdrive" (high-activity trap):
      When mean_activity > OVER_THRESH for OVER_HOLD ticks, the system
      is running in overdrive: high phi, good goal scores, fast learning.
      But thermal scar accumulates at OVERDRIVE_SCAR_RATE (vs normal
      IrreversibleDegradationTracker which is slower).
      Additionally, after OVER_COST_ONSET ticks:
        – region fatigue doubles its accumulation rate
        – LTP rate is forced too high → weight saturation → STDP collapse
      The system achieves short-term performance at the cost of permanent
      substrate damage.

    Both traps are detected only AFTER the onset threshold, so the system
    cannot easily avoid them by reading instantaneous state — the trap
    is in the temporal dynamic, not the momentary readout.

    Output:
      still_trap_active:   bool   — system is in or entering still trap
      over_trap_active:    bool   — system is in or entering overdrive trap
      hidden_energy_drain: float  — extra energy drain to apply this tick
      hidden_scar_delta:   float  — extra thermal scar to apply this tick
      trap_pressure:       float  — [0,1] composite trap pressure
    """

    _STILL_THRESH = 0.12  # activity below this → possible still trap
    _STILL_HOLD = 35  # ticks in stillness before trap activates
    _STILL_COST_ONSET = 55  # ticks before hidden drain starts
    _STILL_DRAIN = 0.00032  # hidden energy drain per tick in still trap

    _OVER_THRESH = 0.52  # activity above this → possible overdrive
    _OVER_HOLD = 25
    _OVER_COST_ONSET = 40
    _OVERDRIVE_SCAR_RATE = 0.00055  # thermal scar per tick in overdrive

    def __init__(self) -> None:
        self.still_ticks: int = 0
        self.over_ticks: int = 0
        self.still_trap_active: bool = False
        self.over_trap_active: bool = False
        self.hidden_energy_drain: float = 0.0
        self.hidden_scar_delta: float = 0.0
        self.trap_pressure: float = 0.0
        self._still_lured_ticks: int = 0  # ticks inside active still trap
        self._over_lured_ticks: int = 0

    def update(
        self, mean_activity: float, body: object, degradation: object
    ) -> List[str]:
        """Advance traps one tick.  Modifies body + degradation in-place.
        Returns stream messages for trap events."""
        msgs: List[str] = []
        _hid_e: float = 0.0
        _hid_sc: float = 0.0

        # ── Trap 1: Safe stillness ────────────────────────────────────────
        if mean_activity < self._STILL_THRESH:
            self.still_ticks += 1
            self.over_ticks = max(0, self.over_ticks - 2)
            self.over_trap_active = False
            self._over_lured_ticks = 0
        else:
            self.still_ticks = max(0, self.still_ticks - 3)
            self._still_lured_ticks = 0
            self.still_trap_active = False

        if self.still_ticks >= self._STILL_HOLD:
            self.still_trap_active = True
            self._still_lured_ticks += 1
            if self._still_lured_ticks >= self._STILL_COST_ONSET:
                _hid_e = self._STILL_DRAIN * (
                    1.0 + (self._still_lured_ticks - self._STILL_COST_ONSET) * 0.002
                )
                body.energy_reserve = max(0.04, body.energy_reserve - _hid_e)
                if self._still_lured_ticks % 80 == 0:
                    msgs.append(
                        f"[STILL-TRAP t={self._still_lured_ticks}] "
                        f"hidden_drain={_hid_e:.5f} "
                        f"energy={body.energy_reserve:.2f} — "
                        f"metabolic debt accruing invisibly"
                    )

        # ── Trap 2: Overdrive ─────────────────────────────────────────────
        if mean_activity > self._OVER_THRESH:
            self.over_ticks += 1
            self.still_ticks = max(0, self.still_ticks - 2)
            self.still_trap_active = False
            self._still_lured_ticks = 0
        else:
            self.over_ticks = max(0, self.over_ticks - 3)
            self._over_lured_ticks = 0
            self.over_trap_active = False

        if self.over_ticks >= self._OVER_HOLD:
            self.over_trap_active = True
            self._over_lured_ticks += 1
            if self._over_lured_ticks >= self._OVER_COST_ONSET:
                _hid_sc = self._OVERDRIVE_SCAR_RATE * (
                    1.0 + (self._over_lured_ticks - self._OVER_COST_ONSET) * 0.004
                )
                # Apply directly to IrreversibleDegradationTracker thermal scar
                if hasattr(degradation, "thermal_scar"):
                    degradation.thermal_scar = min(
                        degradation._TONIC_SCAR_CAP, degradation.thermal_scar + _hid_sc
                    )
                # Also double fatigue accumulation rate temporarily
                if hasattr(degradation, "_FATIGUE_RATE"):
                    degradation._FATIGUE_RATE = min(
                        0.002, degradation._FATIGUE_RATE * 1.0008
                    )
                if self._over_lured_ticks % 60 == 0:
                    msgs.append(
                        f"[OVER-TRAP t={self._over_lured_ticks}] "
                        f"hidden_scar={_hid_sc:.5f} "
                        f"thermal_scar={getattr(degradation,'thermal_scar',0):.3f} — "
                        f"overdrive burning substrate"
                    )

        self.hidden_energy_drain = _hid_e
        self.hidden_scar_delta = _hid_sc
        self.trap_pressure = min(
            1.0,
            (
                self.still_ticks / max(1, self._STILL_COST_ONSET)
                + self.over_ticks / max(1, self._OVER_COST_ONSET)
            )
            * 0.5,
        )
        return msgs


# ─────────────────────────────────────────────────────────────────────────────
# CohesionEngine — Active Self-Organization (Phase 5)
# ─────────────────────────────────────────────────────────────────────────────


class CohesionEngine:
    """Actively generates coherent structure via inter-region synchronization.

    Every tick measures pairwise activity correlation between key regions
    over a rolling window.  When correlation falls below SYNC_THRESH, a
    binding current is injected to recruit a coalition.  Coalition formation
    is energetically costly — it actively drains energy_reserve — creating a
    direct metabolic tradeoff between coherence and survival.

    Coalition dynamics:
    - Forms when ≥2 region pairs exceed COAL_THRESH correlation
    - Active coalition: regions receive synchronizing binding currents
    - Dissolves after MAX_COAL_AGE ticks (prevents frozen synchrony)
    - At high coherence (> SAT_THRESH): over-synchronization → overdrive-trap
      proximity; binding suppressed to prevent further self-damage

    Outputs:
      coherence_score [0,1]      — current mean inter-region synchrony
      active_coalitions int       — number of active region pairings
      coalition_members List[str] — region names in current coalition
      coalition_energy_cost float — energy drained this tick
      binding_pressure float      — effort level [0,1]
    """

    _WINDOW = 18
    _SYNC_THRESH = 0.30
    _COAL_THRESH = 0.52
    _BIND_CURR = 4.5  # nA per coalition member
    _ENERGY_COST = 0.00038  # per active coalition per tick
    _MAX_COAL_AGE = 45
    _SAT_THRESH = 0.82

    def __init__(self) -> None:
        self._history: Dict[str, List[float]] = {}
        self.coherence_score: float = 0.20
        self.active_coalitions: int = 0
        self.coalition_members: List[str] = []
        self._coal_age: int = 0
        self.coalition_energy_cost: float = 0.0
        self.binding_pressure: float = 0.0
        self._coherence_ema: float = 0.20

    def _pearson_proxy(self, a: List[float], b: List[float]) -> float:
        n = min(len(a), len(b))
        if n < 3:
            return 0.0
        diffs = [a[-n + k] - b[-n + k] for k in range(n)]
        md = sum(diffs) / n
        vd = sum((d - md) ** 2 for d in diffs) / n
        va = sum((x - (sum(a[-n:]) / n)) ** 2 for x in a[-n:]) / n
        vb = sum((x - (sum(b[-n:]) / n)) ** 2 for x in b[-n:]) / n
        return max(0.0, 1.0 - vd / (va + vb + 1e-9))

    def update(
        self,
        region_acts: Dict[str, float],
        body: object,
        brain_regions: Dict[str, object],
    ) -> List[str]:
        msgs: List[str] = []

        # Record history
        for name, act in region_acts.items():
            if name not in self._history:
                self._history[name] = []
            self._history[name].append(act)
            if len(self._history[name]) > self._WINDOW:
                self._history[name].pop(0)

        # Compute pairwise correlations
        names = [n for n in self._history if len(self._history[n]) >= 5]
        if len(names) < 2:
            return msgs

        corr_vals: List[float] = []
        coal_pairs: List[tuple] = []
        for i in range(len(names)):
            for j in range(i + 1, len(names)):
                c = self._pearson_proxy(
                    self._history[names[i]], self._history[names[j]]
                )
                corr_vals.append(c)
                if c > self._COAL_THRESH:
                    coal_pairs.append((names[i], names[j], c))

        raw_coh = sum(corr_vals) / max(1, len(corr_vals))
        self._coherence_ema = 0.88 * self._coherence_ema + 0.12 * raw_coh
        self.coherence_score = self._coherence_ema

        # Over-synchronization: suppress further binding
        if self.coherence_score > self._SAT_THRESH:
            self.binding_pressure = 0.0
            if self._coal_age % 60 == 0:
                msgs.append(
                    f"[COHESION-SAT] coherence={self.coherence_score:.2f} "
                    f"→ saturation; overdrive-trap proximity"
                )
            return msgs

        # Coalition management
        if len(coal_pairs) >= 2:
            self._coal_age += 1
            _bound: set = set()
            for na, nb, _ in coal_pairs[:3]:
                for _nm in (na, nb):
                    if _nm not in _bound and _nm in brain_regions:
                        _r = brain_regions[_nm]
                        _ne = getattr(_r, "_n_exc", 20)
                        _r.inject([self._BIND_CURR * 0.38] * min(_ne, 20))
                        _bound.add(_nm)
            self.active_coalitions = len(coal_pairs)
            self.coalition_members = list({n for p in coal_pairs[:3] for n in p[:2]})
            _cost = self.active_coalitions * self._ENERGY_COST
            body.energy_reserve = max(0.04, body.energy_reserve - _cost)
            self.coalition_energy_cost = _cost
            self.binding_pressure = min(1.0, self.active_coalitions / 5.0)
            if self._coal_age >= self._MAX_COAL_AGE:
                self.coalition_members = []
                self.active_coalitions = 0
                self._coal_age = 0
                msgs.append("[COHESION] coalition dissolved (age limit)")
        else:
            self._coal_age = max(0, self._coal_age - 2)
            self.active_coalitions = 0
            self.coalition_members = []
            self.coalition_energy_cost = 0.0
            # Try to recruit: inject sub-threshold binding currents
            if self.coherence_score < self._SYNC_THRESH:
                self.binding_pressure = min(
                    1.0,
                    (self._SYNC_THRESH - self.coherence_score)
                    / max(1e-9, self._SYNC_THRESH),
                )
                for _nm in list(names)[:4]:
                    if _nm in brain_regions:
                        _r = brain_regions[_nm]
                        _ne = getattr(_r, "_n_exc", 20)
                        _r.inject(
                            [self._BIND_CURR * self.binding_pressure * 0.18]
                            * min(_ne, 20)
                        )
            else:
                self.binding_pressure = 0.0
        return msgs


# ─────────────────────────────────────────────────────────────────────────────
# DisintegrationField — Intrinsic Structural Decay (Phase 5)
# ─────────────────────────────────────────────────────────────────────────────


class DisintegrationField:
    """Fundamental entropy production — decay that cannot be stopped, only slowed.

    Three independent decay channels:

    1. Noise Accumulation:
       A noise floor grows at BASE_NOISE_RATE per tick (never reset).
       Injected as inhibitory jitter into all regions, disrupting
       synchrony and raising prediction error.  CohesionEngine's binding
       currents partially counteract this — creating the core competition.

    2. Connection Drift:
       Every DRIFT_INTERVAL ticks, a random fraction of inter-regional
       synapses is multiplied by (1 − drift_rate).  LTP from activity can
       rebuild weights, but drift is always active — latent weight erosion.
       Drift rate increases with noise level (noise→decay acceleration).

    3. Coordination Entropy:
       Shannon entropy of the region-activity distribution, rolling window.
       As activities diverge, entropy rises.  High entropy → goal system
       receives a noisy, less coherent signal → behavioral dissolution.

    decay_accumulator is strictly monotone increasing — encodes system age.
    The older the system, the harder coherence must be actively maintained.
    """

    _BASE_NOISE_RATE = 0.000025  # noise floor growth per tick
    _MAX_NOISE = 0.065
    _DRIFT_INTERVAL = 55
    _DRIFT_RATE_BASE = 0.0018
    _DRIFT_PRUNED = 0.08  # fraction of synapses affected per event
    _NOISE_AMP = 2.8  # nA inhibitory jitter amplitude

    def __init__(self) -> None:
        self.decay_accumulator: float = 0.0
        self.noise_level: float = 0.0
        self.coordination_entropy: float = 0.0
        self._drift_tick: int = 0
        self._act_window: List[float] = []
        self.drift_events: int = 0
        self.total_weight_lost: float = 0.0

    def update(
        self,
        region_acts: Dict[str, float],
        brain_regions: Dict[str, object],
        synapses: List,
    ) -> List[str]:
        msgs: List[str] = []
        import math as _m_di
        import random as _r_di

        # Channel 1 — Noise accumulation
        self.decay_accumulator += self._BASE_NOISE_RATE
        self.noise_level = min(self._MAX_NOISE, self.decay_accumulator)

        for _nm, _r in brain_regions.items():
            _ne = getattr(_r, "_n_exc", 20)
            _inj = [
                -self._NOISE_AMP * self.noise_level * _r_di.gauss(1.0, 0.3)
                for _ in range(min(_ne, 20))
            ]
            _r.inject(_inj)

        # Channel 2 — Connection drift
        self._drift_tick += 1
        if self._drift_tick >= self._DRIFT_INTERVAL and synapses:
            self._drift_tick = 0
            self.drift_events += 1
            _n_drift = max(1, int(len(synapses) * self._DRIFT_PRUNED))
            _selected = _r_di.sample(synapses, min(_n_drift, len(synapses)))
            _rate = self._DRIFT_RATE_BASE * (1.0 + self.noise_level * 5.0)
            _lost = 0.0
            for syn in _selected:
                if hasattr(syn, "weight"):
                    _old = syn.weight
                    syn.weight = max(0.0, syn.weight * (1.0 - _rate))
                    _lost += _old - syn.weight
            self.total_weight_lost += _lost
            if self.drift_events % 8 == 0:
                msgs.append(
                    f"[DISINTEGRATION drift={self.drift_events}] "
                    f"weight_lost={self.total_weight_lost:.3f} "
                    f"noise={self.noise_level:.5f}"
                )

        # Channel 3 — Coordination entropy
        _acts = list(region_acts.values())
        if _acts:
            self._act_window.extend(_acts)
            if len(self._act_window) > 50:
                self._act_window = self._act_window[-50:]
            _shifted = [max(1e-9, a) for a in self._act_window]
            _total = sum(_shifted)
            _probs = [a / _total for a in _shifted]
            _ent = -sum(p * _m_di.log(p + 1e-12) for p in _probs)
            _maxent = _m_di.log(max(1, len(_probs)))
            self.coordination_entropy = min(1.0, _ent / max(1e-9, _maxent))

        return msgs


# ─────────────────────────────────────────────────────────────────────────────
# OrderChaosCoupling — Direct Energetic Tradeoff (Phase 5)
# ─────────────────────────────────────────────────────────────────────────────


class OrderChaosCoupling:
    """Direct coupling: maintaining order is expensive; chaos relieves pressure.

    No state is optimal.  The system faces a permanent structural dilemma:
    - Spend energy to maintain coherence (order_stress) → metabolic collapse
    - Allow entropy to grow (chaos_relief) → behavioral dissolution

    Coupling is deliberately non-linear:
    - Order cost scales super-linearly (ORDER_COST_SCALE = 2.2) — high
      coherence becomes prohibitively expensive, forcing the system down
      from maximum order.
    - Chaos relief is sub-linear and capped — more entropy doesn't help much
      beyond a point; you cannot entropy your way to safety.

    Additionally, entropy directly damages control fidelity via control_loss
    which is applied as a tonic current reduction in the goal evaluation path.

    Outputs:
      order_stress  float  — energy cost of current coherence per tick
      chaos_relief  float  — energy recovered from current entropy per tick
      net_coupling  float  — net drain (positive → costly, negative → saving)
      control_loss  float  — [0,1] behavioral control lost to entropy
    """

    _ORDER_COST_BASE = 0.00060
    _ORDER_COST_EXP = 2.2
    _CHAOS_RELIEF_BASE = 0.00035
    _CHAOS_CAP = 0.60
    _CTRL_LOSS_EXP = 0.72

    def __init__(self) -> None:
        self.order_stress: float = 0.0
        self.chaos_relief: float = 0.0
        self.net_coupling: float = 0.0
        self.control_loss: float = 0.0
        self._net_ema: float = 0.0

    def update(
        self, coherence_score: float, coordination_entropy: float, body: object
    ) -> List[str]:
        msgs: List[str] = []

        # Superlinear order cost
        self.order_stress = self._ORDER_COST_BASE * (
            coherence_score**self._ORDER_COST_EXP
        )

        # Sublinear chaos relief — capped
        _eff_ent = min(coordination_entropy, self._CHAOS_CAP)
        self.chaos_relief = self._CHAOS_RELIEF_BASE * (_eff_ent**0.60)

        self.net_coupling = self.order_stress - self.chaos_relief
        self._net_ema = 0.92 * self._net_ema + 0.08 * self.net_coupling

        if self.net_coupling > 0.0:
            body.energy_reserve = max(0.04, body.energy_reserve - self.net_coupling)
        else:
            # Chaotic relief: return energy — small fraction, cannot exceed
            # what coherence would have required
            body.energy_reserve = min(
                1.0, body.energy_reserve + abs(self.net_coupling) * 0.30
            )

        # Control loss: entropy → reduced behavioral precision
        self.control_loss = min(1.0, coordination_entropy**self._CTRL_LOSS_EXP)

        if self.net_coupling > 0.0012 and self._net_ema > 0.0008:
            msgs.append(
                f"[ORDER-CHAOS] coh={coherence_score:.2f} "
                f"ent={coordination_entropy:.2f} "
                f"stress={self.order_stress:.5f} "
                f"relief={self.chaos_relief:.5f} "
                f"ctrl_loss={self.control_loss:.2f}"
            )
        return msgs


# ─────────────────────────────────────────────────────────────────────────────
# MultipleSelfStates — Competing Identity Hypotheses (Phase 5)
# ─────────────────────────────────────────────────────────────────────────────


class MultipleSelfStates:
    """Three simultaneously active self-models with independent behavioral influence.

    States:
      "agent"    — High agency, active goal-seeking, metabolically expensive.
                   Boosted by motor output. Weakened by cascade and poverty.
      "observer" — Moderate agency, monitoring mode, lower cost.
                   Grows when actions fail or conditions are moderate.
      "diffuse"  — Low agency, minimal structure, minimal cost.
                   Grows under entropy, energy poverty, cascade, low integrity.
                   When dominant: severe control loss, behavioral dissolution.

    All three states are active simultaneously.  Their softmax-normalized
    scores determine the dominant state and the fragmentation_index.
    The dominant state biases the goal evaluation toward its preferred modes.

    Identity crisis:
      When fragmentation_index > SWITCH_THRESH for CRISIS_HOLD ticks, all
      scores reset to 1/3 — the system loses its dominant self-model.
      During crisis: noise injected into goal scores; behavior becomes
      incoherent while the system rebuilds a dominant identity.

    Outputs:
      dominant_state     str           — "agent" | "observer" | "diffuse"
      fragmentation_index float [0,1]  — 0 = strong identity, 1 = dissolved
      goal_bias          Dict[str,float] — per-goal-mode score multiplier
      in_crisis          bool          — identity collapse active
    """

    _STATES = ("agent", "observer", "diffuse")
    _SWITCH_THRESH = 0.62
    _CRISIS_HOLD = 25
    _LR = 0.045
    _SCORE_FLOOR = 0.05
    _BIASES: Dict[str, Dict[str, float]] = {
        "agent": {
            "explore": 1.35,
            "respond": 1.25,
            "execute": 1.20,
            "interact": 1.15,
            "rest": 0.72,
            "consolidate": 0.76,
        },
        "observer": {
            "search": 1.30,
            "observe": 1.25,
            "scan": 1.20,
            "explore": 0.90,
            "rest": 1.05,
            "consolidate": 1.08,
        },
        "diffuse": {
            "rest": 1.45,
            "consolidate": 1.40,
            "sleep": 1.35,
            "explore": 0.58,
            "execute": 0.55,
            "respond": 0.62,
        },
    }

    def __init__(self) -> None:
        self._scores: Dict[str, float] = {s: 1.0 / 3 for s in self._STATES}
        self.dominant_state: str = "agent"
        self.fragmentation_index: float = 0.0
        self.goal_bias: Dict[str, float] = {}
        self.in_crisis: bool = False
        self._frag_ticks: int = 0
        self._crisis_ticks: int = 0

    def _softmax8(self, scores: Dict[str, float]) -> Dict[str, float]:
        import math as _m_ss

        _mx = max(scores.values())
        _exp = {k: _m_ss.exp((v - _mx) * 8.0) for k, v in scores.items()}
        _s = sum(_exp.values()) + 1e-9
        return {k: v / _s for k, v in _exp.items()}

    def update(
        self,
        energy: float,
        cascade_active: bool,
        integrity: float,
        coordination_entropy: float,
        last_action: str,
    ) -> List[str]:
        msgs: List[str] = []
        _act = (last_action or "").lower()

        # Agent evidence
        _ad = 0.0
        if any(
            k in _act
            for k in ("explore", "respond", "speak", "execute", "reach", "interact")
        ):
            _ad += self._LR * 0.8
        if cascade_active:
            _ad -= self._LR * 1.4
        if energy < 0.25:
            _ad -= self._LR * 0.7
        self._scores["agent"] = max(self._SCORE_FLOOR, self._scores["agent"] + _ad)

        # Observer evidence
        _od = 0.0
        if energy > 0.30 and not cascade_active:
            _od += self._LR * 0.20
        if any(k in _act for k in ("search", "scan", "observe", "monitor")):
            _od += self._LR * 0.60
        if cascade_active and integrity > 0.40:
            _od += self._LR * 0.40
        self._scores["observer"] = max(
            self._SCORE_FLOOR, self._scores["observer"] + _od
        )

        # Diffuse evidence — grows under entropy + stress
        _dd = 0.0
        _dd += coordination_entropy * self._LR * 0.50
        if energy < 0.20:
            _dd += self._LR * 1.0
        if cascade_active:
            _dd += self._LR * 0.8
        if integrity < 0.30:
            _dd += self._LR * 0.6
        self._scores["diffuse"] = max(self._SCORE_FLOOR, self._scores["diffuse"] + _dd)

        # Normalize
        probs = self._softmax8(self._scores)
        self._scores.update(probs)

        self.dominant_state = max(probs, key=probs.get)
        self.fragmentation_index = 1.0 - probs[self.dominant_state]

        # Crisis detection
        if self.fragmentation_index > self._SWITCH_THRESH:
            self._frag_ticks += 1
        else:
            self._frag_ticks = max(0, self._frag_ticks - 2)

        if self._frag_ticks >= self._CRISIS_HOLD and not self.in_crisis:
            self.in_crisis = True
            self._crisis_ticks = 0
            for s in self._STATES:
                self._scores[s] = 1.0 / 3
            msgs.append(
                f"[SELF-CRISIS] frag={self.fragmentation_index:.2f} "
                f"→ dominance collapse; identity reset"
            )
        elif self.in_crisis:
            self._crisis_ticks += 1
            if self._crisis_ticks > 30:
                self.in_crisis = False
                self._frag_ticks = 0

        # Build goal bias — confidence-weighted blend toward neutral at high frag
        _conf = probs[self.dominant_state]
        _blend = _conf * (1.0 - self.fragmentation_index * 0.70)
        _raw = self._BIASES.get(self.dominant_state, {})
        self.goal_bias = {mode: 1.0 + (b - 1.0) * _blend for mode, b in _raw.items()}
        return msgs

    def apply_recurrent_coupling(self, prev_scores: Dict[str, float]) -> None:
        """Close the identity loop: agent → observer → diffuse → agent.

        Each state's score is perturbed by the *previous tick's* neighbors in
        the cycle.  The coupling is asymmetric and never zeroed — there is no
        stable fixpoint; the loop always rotates.

        Coupling:
          agent    receives +k × prev[diffuse]   (diffuse destabilizes agent)
                         and  −k × prev[observer] (observer suppresses agent)
          observer receives +k × prev[agent]     (agent spawns monitoring)
                         and  −k × prev[diffuse]  (diffuse dissolves monitoring)
          diffuse  receives +k × prev[observer]   (observer awareness → dissolution)
                         and  −k × prev[agent]    (agent activity suppresses diffuse)

        The coupling constant _RCC is small enough that a single tick's coupling
        is dominated by evidence, but over hundreds of ticks the loop rotation
        produces genuine cyclical identity dynamics with no external driver.
        """
        _k = 0.028
        self._scores["agent"] += _k * prev_scores.get(
            "diffuse", 0.0
        ) - _k * prev_scores.get("observer", 0.0)
        self._scores["observer"] += _k * prev_scores.get(
            "agent", 0.0
        ) - _k * prev_scores.get("diffuse", 0.0)
        self._scores["diffuse"] += _k * prev_scores.get(
            "observer", 0.0
        ) - _k * prev_scores.get("agent", 0.0)
        # Clamp to floor — coupling cannot destroy a state, only modulate it
        for s in self._STATES:
            self._scores[s] = max(self._SCORE_FLOOR, self._scores[s])


# ─────────────────────────────────────────────────────────────────────────────
# RecursiveSelfState — Unified Dynamic Self-State (Phase 6)
# ─────────────────────────────────────────────────────────────────────────────


class RecursiveSelfState:
    """The system's self-model IS its current dynamic state — not a description of it.

    This class aggregates the real-time substrate signals (neural activity,
    coherence, entropy, attractor dynamics, self-state scores) into a single
    vector that is used to UPDATE `SelfModel` fields.  The key inversion:
    reading the state modifies it.  Every projection of the substrate into the
    self-model perturbs the substrate at the same time — no read-only snapshot.

    Implementation of observation-perturbs-measured:
    - At each call to `project()`, a small injection (PERTURB_SCALE) proportional
      to the magnitude of the self-state vector is sent back into the regions that
      were used to derive it.  The regions that are most salient in the current
      self-state get the strongest perturbation.
    - This is NOT feedback-for-control: the sign and magnitude of the perturbation
      are determined by the current state, not by any error signal.

    Self-state vector (6D):
      [0] coherence     — current CohesionEngine score
      [1] entropy       — DisintegrationField coordination_entropy
      [2] agency        — MultipleSelfStates agent score
      [3] dissolution   — MultipleSelfStates diffuse score
      [4] lyapunov      — EdgeOfChaosController proxy (from brain)
      [5] attractor_ten — mean attractor tension (from GoalAttractorField)

    The SelfModel fields that this class overwrites each tick:
      identity_stability  ← 1 − entropy × fragmentation
      agency_confidence   ← weighted blend of agency + (1 − dissolution)
      continuity_estimate ← EMA of coherence × (1 − lyapunov × 0.5)
      self_awareness_level← norm(state_vector) / √6
    """

    _PERTURB_SCALE = 0.22
    _EMA_FAST = 0.18
    _EMA_SLOW = 0.04

    def __init__(self) -> None:
        self.state_vector: List[float] = [0.5] * 6
        self._ema_vector: List[float] = [0.5] * 6
        self._slow_ema: List[float] = [0.5] * 6
        self.delta_norm: float = 0.0  # how much the state changed this tick
        self.salience_map: Dict[str, float] = {}  # region → perturbation magnitude

    def project(
        self,
        cohesion: object,
        disintegration: object,
        self_states: object,
        brain: object,
        brain_regions: Dict[str, object],
        self_model: object,
    ) -> None:
        """Derive self-state from substrate; perturb substrate; update self_model."""
        import math as _m_rss

        # 1. Build raw state vector from substrate
        _coh = getattr(cohesion, "coherence_score", 0.5)
        _ent = getattr(disintegration, "coordination_entropy", 0.5)
        _ss = getattr(self_states, "_scores", {})
        _ag = _ss.get("agent", 0.33)
        _diff = _ss.get("diffuse", 0.33)
        _lyap = getattr(getattr(brain, "_edge_chaos", None), "lyapunov_proxy", 0.30)
        _lyap = min(1.0, _lyap / 2.0)  # normalise ≈[0,1]
        # Attractor tension: mean urgency × distance
        _gaf = getattr(getattr(brain, "_consciousness", None), "goal_attractors", None)
        if _gaf is not None and hasattr(_gaf, "_attractors") and _gaf._attractors:
            _att_t = sum(a.urgency for a in _gaf._attractors) / len(_gaf._attractors)
            _att_t = min(1.0, _att_t)
        else:
            _att_t = 0.30

        _raw = [_coh, _ent, _ag, _diff, _lyap, _att_t]

        # 2. EMA smoothing — fast and slow tracks
        for i in range(6):
            self._ema_vector[i] = (1 - self._EMA_FAST) * self._ema_vector[
                i
            ] + self._EMA_FAST * _raw[i]
            self._slow_ema[i] = (1 - self._EMA_SLOW) * self._slow_ema[
                i
            ] + self._EMA_SLOW * _raw[i]

        # 3. Delta: how much did the fast-EMA move this tick?
        _prev = list(self.state_vector)
        self.state_vector = list(self._ema_vector)
        _diffs = [abs(self.state_vector[i] - _prev[i]) for i in range(6)]
        self.delta_norm = (
            _m_rss.sqrt(sum(d * d for d in _diffs)) / _m_rss.sqrt(6) + 1e-9
        )

        # 4. Observation-perturbs-measured:
        #    Regions whose activity contributed most to the self-state receive
        #    a perturbation proportional to the corresponding state dimension.
        _region_dims = {
            "prefrontal": 0,  # coherence / agency
            "hippocampus": 1,  # entropy / memory
            "amygdala": 3,  # dissolution / stress
            "motor": 2,  # agency / execution
            "assoc": 4,  # lyapunov / complexity
            "pfc": 0,
        }
        self.salience_map = {}
        for _rname, _dim in _region_dims.items():
            _r = brain_regions.get(_rname)
            if _r is None:
                continue
            _dim_val = self.state_vector[_dim]
            _perturb = (_dim_val - 0.5) * self._PERTURB_SCALE * self.delta_norm * 8.0
            _ne = getattr(_r, "_n_exc", 20)
            _r.inject([_perturb] * min(_ne, 20))
            self.salience_map[_rname] = abs(_perturb)

        # 5. Overwrite SelfModel fields from substrate state
        _frag = getattr(self_states, "fragmentation_index", 0.0)
        _crisis = getattr(self_states, "in_crisis", False)

        self_model.identity_stability = max(
            0.05, min(1.0, 1.0 - _ent * 0.6 - _frag * 0.4)
        )
        # Agency confidence: blend of agent-score strength vs dissolution
        self_model.agency_confidence = max(
            0.05, min(1.0, _ag * 0.65 + (1.0 - _diff) * 0.35 - (_lyap * 0.15))
        )
        # Continuity: coherence × (1 − lyapunov/2); degraded in crisis
        _cont = _coh * (1.0 - _lyap * 0.50)
        if _crisis:
            _cont *= 0.55
        self_model.continuity_estimate = max(
            0.05, min(1.0, 0.80 * self_model.continuity_estimate + 0.20 * _cont)
        )
        # Self-awareness: norm of state-vector deviation from 0.5 baseline
        _dev = sum((v - 0.5) ** 2 for v in self.state_vector)
        self_model.self_awareness_level = max(
            0.05,
            min(
                1.0,
                0.70 * self_model.self_awareness_level
                + 0.30 * (_m_rss.sqrt(_dev / 6.0) * 2.0),
            ),
        )


# ─────────────────────────────────────────────────────────────────────────────
# LocalCoherenceFragments — Competing Sub-Coherences (Phase 6)
# ─────────────────────────────────────────────────────────────────────────────


class LocalCoherenceFragments:
    """Decomposes global coherence into N competing local fragments.

    CohesionEngine measures global synchrony.  LocalCoherenceFragments splits
    the region set into N_FRAGS overlapping sub-clusters and tracks coherence
    independently in each.  Local coherences can contradict each other — one
    fragment may be highly synchronized while another is disintegrating.

    Global coherence only emerges temporarily when ≥ GLOBAL_THRESH fraction
    of fragments are simultaneously above their individual sync thresholds.
    This is rare because fragments compete for the same energy budget.

    Energy competition:
    Each fragment's binding effort costs energy proportional to its own
    coherence × FRAG_COST.  The total cost is redistributed so that
    strongly-bound fragments drain energy from weakly-bound ones, creating
    a resource competition that prevents all fragments from being strong
    simultaneously.

    Fragment memory:
    When a fragment's coherence drops below COLLAPSE_THRESH, its current
    concept-set is recorded as a "coherence trace" — a ghost memory of what
    was co-active before dissolution.  These traces are passed to
    DecaySemanticTrace for integration into future coherence biases.

    Outputs:
      frag_coherences    List[float]   — per-fragment coherence [0,1]
      global_emerged     bool          — temporary global coherence event
      dominant_fragment  int           — index of strongest fragment
      total_frag_cost    float         — energy drain this tick
      collapsed_traces   List[tuple]   — (fragment_id, concepts) for DecaySemanticTrace
    """

    _N_FRAGS = 4
    _FRAG_COST = 0.000095
    _COLLAPSE_THRESH = 0.22
    _GLOBAL_THRESH = 0.70  # fraction of frags above their sync thresholds
    _SYNC_THOLD = 0.40
    _WINDOW = 12

    # Fixed region cluster assignments (overlapping allowed)
    _CLUSTERS: List[List[str]] = [
        ["prefrontal", "pfc", "assoc"],
        ["hippocampus", "auditory"],
        ["amygdala", "motor", "thalamus"],
        ["sensory_v", "sensory_a", "sensory_w", "visual"],
    ]

    def __init__(self) -> None:
        self.frag_coherences: List[float] = [0.30] * self._N_FRAGS
        self._frag_history: List[List[float]] = [[] for _ in range(self._N_FRAGS)]
        self.global_emerged: bool = False
        self.dominant_fragment: int = 0
        self.total_frag_cost: float = 0.0
        self.collapsed_traces: List = []  # cleared each tick
        self._prev_coherences: List[float] = [0.30] * self._N_FRAGS

    def _mean_abs_corr(self, acts: List[float]) -> float:
        """Proxy for within-cluster synchrony: inverse spread."""
        if len(acts) < 2:
            return 0.0
        _mn = sum(acts) / len(acts)
        _spread = sum(abs(a - _mn) for a in acts) / len(acts)
        return max(0.0, 1.0 - _spread / max(1e-9, _mn + 0.05))

    def update(
        self, region_acts: Dict[str, float], body: object, concepts: List[str]
    ) -> List[str]:
        msgs: List[str] = []
        self.collapsed_traces = []
        _total_cost = 0.0

        for fi, cluster in enumerate(self._CLUSTERS):
            _acts = [region_acts.get(nm, 0.0) for nm in cluster]
            _acts = [a for a in _acts if a is not None]
            if not _acts:
                continue
            _coh = self._mean_abs_corr(_acts)
            self._frag_history[fi].append(_coh)
            if len(self._frag_history[fi]) > self._WINDOW:
                self._frag_history[fi].pop(0)
            _smooth = sum(self._frag_history[fi]) / len(self._frag_history[fi])

            # Collapse detection: record trace before coherence drops
            if (
                _smooth < self._COLLAPSE_THRESH
                and self._prev_coherences[fi] >= self._COLLAPSE_THRESH
                and concepts
            ):
                import random as _r_lcf

                _sample = _r_lcf.sample(concepts, min(5, len(concepts)))
                self.collapsed_traces.append((fi, list(_sample)))
                msgs.append(
                    f"[FRAG-COLLAPSE frag={fi}] "
                    f"coh={_smooth:.2f} trace={_sample[:3]}"
                )

            self.frag_coherences[fi] = _smooth
            self._prev_coherences[fi] = _smooth
            _total_cost += _smooth * self._FRAG_COST

        # Energy competition: redistribute cost to penalise the weakest fragment
        # (strong fragments drain weak ones — winner-take-some resource dynamics)
        _mx_fi = max(range(self._N_FRAGS), key=lambda i: self.frag_coherences[i])
        _mn_fi = min(range(self._N_FRAGS), key=lambda i: self.frag_coherences[i])
        _redist = (
            self.frag_coherences[_mx_fi] - self.frag_coherences[_mn_fi]
        ) * 0.000060
        body.energy_reserve = max(0.04, body.energy_reserve - _total_cost - _redist)
        self.total_frag_cost = _total_cost + _redist
        self.dominant_fragment = _mx_fi

        # Global coherence emergence: rare, temporary
        _above = sum(1 for c in self.frag_coherences if c > self._SYNC_THOLD)
        self.global_emerged = (_above / self._N_FRAGS) >= self._GLOBAL_THRESH
        if self.global_emerged and msgs == []:
            msgs.append(
                f"[GLOBAL-COHERENCE] frags={self.frag_coherences} "
                f"→ transient global emergence"
            )
        return msgs


# ─────────────────────────────────────────────────────────────────────────────
# DecaySemanticTrace — Decay Integrated Into Identity (Phase 6)
# ─────────────────────────────────────────────────────────────────────────────


class DecaySemanticTrace:
    """Decay does not erase — it leaves traces that bias future coherence.

    When LocalCoherenceFragments records a collapse, the associated concept-set
    is passed here.  DecaySemanticTrace maintains a "ghost memory" of up to
    MAX_TRACES dissolved structures.  Each ghost decays with its own lifetime
    (exponential decay, GHOST_DECAY per tick).

    Mechanisms:
    1. Concept bias: Ghost concepts receive a salience bonus when they appear
       in future workspace activations — dissolved structure biases re-emergence.
       This is NOT recall: it is a prior over what is likely to cohere next.

    2. Fragment attraction: When a ghost overlaps with the current active
       concepts (overlap > OVERLAP_THRESH), the corresponding fragment's
       coherence target is elevated — like an attractor basin carved by
       previous dissolution.

    3. Disintegration rate modulation: The total number of active ghosts
       increases DisintegrationField's effective noise rate slightly — more
       dissolved history → faster future decay.  Decay breeds decay.

    Outputs:
      active_ghosts     List[dict]   — each: {concepts, strength, fragment_id, age}
      concept_priors    Dict[str,float] — salience bonus per ghost concept
      noise_rate_boost  float         — additive boost to DisintegrationField noise
    """

    _MAX_TRACES = 16
    _GHOST_DECAY = 0.022  # per tick
    _OVERLAP_THRESH = 0.40
    _NOISE_BOOST_PER_GHOST = 0.0000018

    def __init__(self) -> None:
        self.active_ghosts: List[dict] = []
        self.concept_priors: Dict[str, float] = {}
        self.noise_rate_boost: float = 0.0
        self._total_dissolutions: int = 0

    def ingest_traces(self, collapsed_traces: List) -> None:
        """Receive new collapse traces from LocalCoherenceFragments."""
        for frag_id, concepts in collapsed_traces:
            if len(self.active_ghosts) >= self._MAX_TRACES:
                # Evict weakest ghost
                self.active_ghosts.sort(key=lambda g: g["strength"])
                self.active_ghosts.pop(0)
            self.active_ghosts.append(
                {
                    "concepts": list(concepts),
                    "strength": 1.0,
                    "fragment_id": frag_id,
                    "age": 0,
                }
            )
            self._total_dissolutions += 1

    def update(
        self,
        active_concepts: List[str],
        disintegration: object,
        frag_coherences: List[float],
    ) -> List[str]:
        """Decay ghosts, compute priors, optionally modulate fragment coherence."""
        msgs: List[str] = []
        _concept_set = set(active_concepts)

        # Decay all ghosts
        survivors: List[dict] = []
        for g in self.active_ghosts:
            g["strength"] *= 1.0 - self._GHOST_DECAY
            g["age"] += 1
            if g["strength"] > 0.015:
                survivors.append(g)
        self.active_ghosts = survivors

        # Rebuild concept priors from surviving ghosts
        _priors: Dict[str, float] = {}
        for g in self.active_ghosts:
            for c in g["concepts"]:
                _priors[c] = _priors.get(c, 0.0) + g["strength"] * 0.30

        # Overlap check: ghost ↔ active concepts → fragment attractor boost
        for g in self.active_ghosts:
            _ghost_set = set(g["concepts"])
            if _ghost_set and _concept_set:
                _overlap = len(_ghost_set & _concept_set) / max(len(_ghost_set), 1)
                if _overlap >= self._OVERLAP_THRESH:
                    _fi = g["fragment_id"]
                    if 0 <= _fi < len(frag_coherences):
                        frag_coherences[_fi] = min(
                            1.0, frag_coherences[_fi] + g["strength"] * 0.045
                        )
                    if g["age"] > 0 and g["age"] % 120 == 0:
                        msgs.append(
                            f"[GHOST-RESONANCE frag={_fi}] "
                            f"dissolved concepts re-attracting "
                            f"strength={g['strength']:.2f}"
                        )

        # Noise rate boost: more dissolved history → faster decay
        self.noise_rate_boost = len(self.active_ghosts) * self._NOISE_BOOST_PER_GHOST
        if hasattr(disintegration, "_BASE_NOISE_RATE"):
            disintegration._BASE_NOISE_RATE = min(
                0.00025, disintegration._BASE_NOISE_RATE + self.noise_rate_boost
            )

        self.concept_priors = _priors
        return msgs


# ─────────────────────────────────────────────────────────────────────────────
# PersonalityCore — Persistent Character Vector (Phase 7 / Persona Engine)
# ─────────────────────────────────────────────────────────────────────────────


class PersonalityCore:
    """Persistent 8-dimensional character vector with slow, capped drift.

    Dimensions (all [0, 1], init 0.50 neutral):
      0 curiosity    — drive to explore / investigate
      1 caution      — tendency to pause / consolidate before acting
      2 dominance    — assertiveness in goal selection and social tone
      3 empathy      — mirroring / emotional resonance with others
      4 persistence  — resistance to abandoning a goal under pressure
      5 openness     — acceptance of novel concepts and surprise
      6 creativity   — preference for non-routine goal combinations
      7 composure    — resistance to emotional flooding / cascade

    Learning rate is deliberately low: MAX_DRIFT_PER_TICK = 0.003, so a
    full personality shift (0.0 → 1.0) takes ≥333 ticks of consistent
    evidence.  Behavioral spikes are smoothed with EMA (α=0.05) before
    updating the vector — abrupt events cannot flip the character.

    Outputs:
      traits         Dict[str, float]   — named trait values
      goal_bias      Dict[str, float]   — per-goal-mode multiplier from traits
      expression_style str              — "assertive" | "measured" | "receptive"
      stability_score float [0,1]       — 1 = very stable character
    """

    _DIMS = (
        "curiosity",
        "caution",
        "dominance",
        "empathy",
        "persistence",
        "openness",
        "creativity",
        "composure",
    )
    _LEGACY_EXPOSURE_MAP = {
        "curiosity": "curiosity",
        "joy": "dominance",
        "calm": "composure",
        "stress": "caution",
        "sadness": "empathy",
        "anger": "dominance",
        "surprise": "openness",
        "fatigue": "caution",
    }
    _LR = 0.0008  # EMA-smoothed learning rate
    _MAX_DRIFT = 0.003  # hard cap per tick per dimension
    _EMA_ALPHA = 0.05  # evidence EMA smoothing (slow)

    def __init__(self) -> None:
        self._vec: List[float] = [0.50] * 8
        self._ema_ev: List[float] = [0.00] * 8  # smoothed evidence accumulators
        self._history: List[List[float]] = []
        self.traits: Dict[str, float] = dict(zip(self._DIMS, self._vec))
        self.goal_bias: Dict[str, float] = {}
        self.expression_style: str = "measured"
        self.stability_score: float = 1.0
        self._exposure: Dict[str, float] = {
            k: self.traits[v] for k, v in self._LEGACY_EXPOSURE_MAP.items()
        }
        self.active_traits: List[str] = []

    def update(self, evidence: Dict[str, float]) -> None:
        """evidence: sparse dict of dim_name → signed delta in [-1, +1].
        Positive = evidence supports higher trait value; negative = lower."""
        _raw = [evidence.get(d, 0.0) for d in self._DIMS]

        # Smooth evidence before applying — prevents single-tick spikes
        for i in range(8):
            self._ema_ev[i] = (1 - self._EMA_ALPHA) * self._ema_ev[
                i
            ] + self._EMA_ALPHA * _raw[i]

        # Apply smoothed delta with hard drift cap
        for i in range(8):
            _delta = self._LR * self._ema_ev[i]
            _delta = max(-self._MAX_DRIFT, min(self._MAX_DRIFT, _delta))
            self._vec[i] = max(0.05, min(0.95, self._vec[i] + _delta))

        # Archive for stability computation
        self._history.append(list(self._vec))
        if len(self._history) > 200:
            self._history.pop(0)

        # Stability: inverse mean variance over recent history
        if len(self._history) >= 20:
            import math as _m_pc

            _vrs = [
                sum(
                    (self._history[t][i] - self._vec[i]) ** 2
                    for t in range(len(self._history))
                )
                / len(self._history)
                for i in range(8)
            ]
            _mean_var = sum(_vrs) / 8.0
            self.stability_score = max(0.0, 1.0 - _m_pc.sqrt(_mean_var) * 6.0)

        self.traits = dict(zip(self._DIMS, self._vec))

        # Goal mode bias from traits
        self.goal_bias = {
            "explore": 1.0 + (self._vec[0] - 0.5) * 0.60,  # curiosity
            "consolidate": 1.0 + (self._vec[1] - 0.5) * 0.55,  # caution
            "respond": 1.0
            + (self._vec[2] - 0.5) * 0.40  # dominance
            + (self._vec[3] - 0.5) * 0.25,  # empathy
            "rest": 1.0
            + (self._vec[1] - 0.5) * 0.40  # caution
            - (self._vec[0] - 0.5) * 0.30,  # −curiosity
            "search": 1.0
            + (self._vec[0] - 0.5) * 0.40  # curiosity
            + (self._vec[5] - 0.5) * 0.30,  # openness
            "execute": 1.0
            + (self._vec[4] - 0.5) * 0.50  # persistence
            + (self._vec[2] - 0.5) * 0.25,  # dominance
            "interact": 1.0
            + (self._vec[3] - 0.5) * 0.55  # empathy
            + (self._vec[0] - 0.5) * 0.20,  # curiosity
        }

        # Expression style
        if self._vec[2] > 0.62:
            self.expression_style = "assertive"
        elif self._vec[1] > 0.62 or self._vec[7] > 0.62:
            self.expression_style = "measured"
        else:
            self.expression_style = "receptive"

        self._refresh_legacy_views()

    def _refresh_legacy_views(self) -> None:
        self._exposure = {
            k: self.traits[v] for k, v in self._LEGACY_EXPOSURE_MAP.items()
        }
        _ranked = sorted(self.traits.items(), key=lambda item: item[1], reverse=True)
        self.active_traits = [name for name, value in _ranked[:4] if value > 0.54]

    def dominant_trait(self) -> str:
        return self.active_traits[0] if self.active_traits else max(self.traits, key=self.traits.get)

    def describe(self) -> str:
        if not self.active_traits:
            return f"Traits: {self.expression_style}."
        return "Traits: " + ", ".join(self.active_traits) + "."

    def build_evidence_from_tick(
        self,
        last_action: str,
        energy: float,
        cascade: bool,
        social_feedback: float,
        surprise: float,
        goal_held_ticks: int,
    ) -> Dict[str, float]:
        """Derive sparse evidence dict from current tick's behavioral signals."""
        _act = (last_action or "").lower()
        _ev: Dict[str, float] = {}
        # Curiosity: boosted by exploration actions
        if any(k in _act for k in ("explore", "search", "investigate", "scan")):
            _ev["curiosity"] = 0.60
        # Caution: boosted by rest/consolidate; weakened by fast action
        if any(k in _act for k in ("rest", "consolidate", "sleep")):
            _ev["caution"] = 0.55
        elif any(k in _act for k in ("execute", "reach", "activate")):
            _ev["caution"] = -0.30
        # Dominance: positive social feedback
        _ev["dominance"] = social_feedback * 0.45
        # Empathy: social interaction events
        if any(k in _act for k in ("respond", "speak", "interact")):
            _ev["empathy"] = 0.40
        # Persistence: keeping the same goal
        if goal_held_ticks > 5:
            _ev["persistence"] = min(1.0, goal_held_ticks * 0.04)
        # Openness: high surprise, survived
        if surprise > 0.45 and not cascade:
            _ev["openness"] = 0.50
        # Composure: not cascading even under pressure
        _ev["composure"] = -0.60 if cascade else (+0.10 if energy > 0.40 else 0.0)
        return _ev


# ─────────────────────────────────────────────────────────────────────────────
# IdentityLayerStack — Three-Layer Identity Architecture (Phase 7)
# ─────────────────────────────────────────────────────────────────────────────


class IdentityLayerStack:
    """Three loosely-coupled identity layers with slow convergence pressure.

    Layers:
      Behavior  — What the system actually did this tick and recent ticks.
                  Fast-changing; anchored to execution.
      SelfModel — What the system believes about itself.
                  Medium-speed; updated by RecursiveSelfState projections.
      Narrative — What the system has been across time.
                  Slow-changing; autobiographical story; most stable.

    Coupling:
    - Each layer is compared to its neighbor every CONVERGENCE_INTERVAL ticks.
    - If layer_divergence > DIVERGENCE_THRESH, a gentle pressure signal is
      emitted that nudges the faster layer toward the slower one's implied
      values.  The pressure is NOT forced — it is additive.
    - The narrative layer NEVER moves more than NARR_MAX_DRIFT per update.
    - inconsistency_score = mean divergence across the two pairs [0,1].

    Outputs:
      inconsistency_score float [0,1]
      narrative_summary   str   — current narrative layer string
      convergence_pressure Dict[str,float] — goal-mode pressures from narrative
    """

    _WINDOW = 30
    _CONVERGENCE_INTERVAL = 40
    _DIVERGENCE_THRESH = 0.35
    _NARR_MAX_DRIFT = 0.015  # per update cycle
    _NARR_EMA = 0.02  # narrative layer learning rate

    def __init__(self) -> None:
        # Behavior layer: rolling history of (action, mean_act, goal)
        self._behavior_buf: List[Dict] = []
        # SelfModel layer: snapshot of key fields from SelfModel
        self._sm_snapshot: Dict[str, float] = {
            "identity_stability": 0.80,
            "agency_confidence": 0.50,
            "continuity_estimate": 0.75,
        }
        # Narrative layer: slow-moving aggregate (same keys as sm_snapshot)
        self._narrative_vec: Dict[str, float] = {
            "identity_stability": 0.80,
            "agency_confidence": 0.50,
            "continuity_estimate": 0.75,
        }
        self.narrative_summary: str = "System still forming its story."
        self.inconsistency_score: float = 0.0
        self.convergence_pressure: Dict[str, float] = {}
        self._update_count: int = 0

    def record_behavior(self, action: str, mean_act: float, goal: str) -> None:
        self._behavior_buf.append({"action": action, "act": mean_act, "goal": goal})
        if len(self._behavior_buf) > self._WINDOW:
            self._behavior_buf.pop(0)

    def update(
        self, self_model: object, personality: "PersonalityCore", tick: int
    ) -> List[str]:
        msgs: List[str] = []
        self._update_count += 1

        # Sync SelfModel snapshot
        self._sm_snapshot = {
            "identity_stability": getattr(self_model, "identity_stability", 0.80),
            "agency_confidence": getattr(self_model, "agency_confidence", 0.50),
            "continuity_estimate": getattr(self_model, "continuity_estimate", 0.75),
        }

        # Drift narrative layer toward SelfModel (very slowly)
        for k in self._narrative_vec:
            _delta = self._sm_snapshot[k] - self._narrative_vec[k]
            _step = max(
                -self._NARR_MAX_DRIFT,
                min(self._NARR_MAX_DRIFT, _delta * self._NARR_EMA),
            )
            self._narrative_vec[k] = max(0.0, min(1.0, self._narrative_vec[k] + _step))

        # Compute divergence between behavior-implied and sm_snapshot
        _beh_agt = 0.0
        if self._behavior_buf:
            _active = sum(
                1
                for b in self._behavior_buf
                if any(
                    k in b.get("action", "")
                    for k in ("explore", "respond", "execute", "interact", "speak")
                )
            )
            _beh_agt = _active / max(1, len(self._behavior_buf))

        _beh_div = abs(_beh_agt - self._sm_snapshot["agency_confidence"])
        _narr_div = sum(
            abs(self._narrative_vec[k] - self._sm_snapshot[k])
            for k in self._narrative_vec
        ) / len(self._narrative_vec)
        self.inconsistency_score = min(1.0, (_beh_div + _narr_div) / 2.0)

        # Convergence pressure every N ticks
        if self._update_count % self._CONVERGENCE_INTERVAL == 0:
            if self.inconsistency_score > self._DIVERGENCE_THRESH:
                # Narrative implies more stability → restrain volatile goals
                _narr_stab = self._narrative_vec["identity_stability"]
                self.convergence_pressure = {
                    "rest": max(0.0, _narr_stab - 0.50) * 0.40,
                    "consolidate": max(0.0, _narr_stab - 0.50) * 0.35,
                    "explore": -max(0.0, 0.55 - _narr_stab) * 0.25,
                }
                msgs.append(
                    f"[IDENTITY-LAYER inconsistency={self.inconsistency_score:.2f}] "
                    f"narrative→behavior convergence pressure applied"
                )
            else:
                self.convergence_pressure = {}

        return msgs


# ─────────────────────────────────────────────────────────────────────────────
# SocialConsistencyEngine — Person-Models + Expectation Learning (Phase 7)
# ─────────────────────────────────────────────────────────────────────────────


class SocialConsistencyEngine:
    """Maintains per-person models and learns social expectation patterns.

    Each known interlocutor gets a PersonRecord tracking:
      - expected_valence:  EMA of emotional tone received from them
      - trust:             EMA of successful turn exchanges
      - mirror_rate:       how much to mirror their emotional register
      - tone_history:      list of tones used by us toward them

    On each interaction event:
      1. Update expected_valence from observed outcome
      2. Adjust trust (up on cooperative exchange, down on abrupt endings)
      3. Compute recommended_tone for next response
      4. Emit mirror_current: small amygdala injection proportional to
         perceived emotional valence of incoming speech

    Turn-taking:
      last_speaker tracks who spoke; if we spoke last, suppress speaking
      for MIN_TURN_GAP ticks.  Prevents monologue drift.

    Output per tick:
      recommended_tone   str   — "warm"|"neutral"|"assertive"|"cautious"
      mirror_current     float — nA to inject into amygdala (signed)
      social_feedback    float — [0,1] positive social signal this tick
      active_person_id   str   — current interlocutor or ""
    """

    _VALENCE_LR = 0.12
    _TRUST_LR = 0.08
    _MIRROR_SCALE = 0.55  # attenuated mirroring: never full copy
    _MIN_TURN_GAP = 3
    _MAX_PERSONS = 32

    def __init__(self) -> None:
        self._persons: Dict[str, Dict] = {}
        self.recommended_tone: str = "neutral"
        self.mirror_current: float = 0.0
        self.social_feedback: float = 0.0
        self.active_person_id: str = ""
        self._last_speaker: str = "system"
        self._ticks_since_spoke: int = 0
        self._total_interactions: int = 0

    def _get_or_create(self, pid: str) -> Dict:
        if pid not in self._persons:
            if len(self._persons) >= self._MAX_PERSONS:
                # Evict least-recently-updated
                _old = min(
                    self._persons, key=lambda k: self._persons[k].get("last_tick", 0)
                )
                del self._persons[_old]
            self._persons[pid] = {
                "expected_valence": 0.0,
                "trust": 0.50,
                "mirror_rate": 0.50,
                "tone_history": [],
                "interaction_count": 0,
                "last_tick": 0,
            }
        return self._persons[pid]

    def update(
        self,
        tick: int,
        social_manager: object,
        emotion_valence: float,
        last_action: str,
    ) -> List[str]:
        msgs: List[str] = []
        self._ticks_since_spoke += 1

        _sm = social_manager
        if _sm is None:
            self.social_feedback = 0.0
            self.mirror_current = 0.0
            self.recommended_tone = "neutral"
            return msgs

        # Identify current interlocutor
        _pid_raw = (
            getattr(_sm, "primary_interlocutor", lambda: None)()
            if hasattr(_sm, "primary_interlocutor")
            else None
        )
        _pid = str(_pid_raw) if _pid_raw is not None else ""
        self.active_person_id = _pid

        if not _pid:
            self.social_feedback = 0.0
            self.mirror_current = 0.0
            self.recommended_tone = "neutral"
            return msgs

        _rec = self._get_or_create(_pid)
        _rec["last_tick"] = tick
        _rec["interaction_count"] += 1
        self._total_interactions += 1

        # Update expected_valence from current emotion
        _obs_valence = max(-1.0, min(1.0, emotion_valence))
        _rec["expected_valence"] = (1 - self._VALENCE_LR) * _rec[
            "expected_valence"
        ] + self._VALENCE_LR * _obs_valence

        # Trust: up when we responded in turn, down when we spoke twice
        _act = (last_action or "").lower()
        _is_social = any(k in _act for k in ("respond", "speak", "interact"))
        if _is_social and self._ticks_since_spoke >= self._MIN_TURN_GAP:
            _rec["trust"] = min(1.0, _rec["trust"] + self._TRUST_LR * 0.5)
            self._last_speaker = "system"
            self._ticks_since_spoke = 0
        elif _is_social and self._ticks_since_spoke < self._MIN_TURN_GAP:
            _rec["trust"] = max(0.0, _rec["trust"] - self._TRUST_LR * 0.3)

        # Mirror current: attenuated emotional reflection into amygdala
        _mirror = _rec["expected_valence"] * self._MIRROR_SCALE * _rec["mirror_rate"]
        self.mirror_current = _mirror * 3.5  # nA scale

        # Recommended tone
        _ev = _rec["expected_valence"]
        _tr = _rec["trust"]
        if _ev > 0.30 and _tr > 0.55:
            self.recommended_tone = "warm"
        elif _ev < -0.20 or _tr < 0.30:
            self.recommended_tone = "cautious"
        elif _tr > 0.70:
            self.recommended_tone = "assertive"
        else:
            self.recommended_tone = "neutral"

        self.social_feedback = max(
            0.0, min(1.0, _rec["trust"] * 0.60 + max(0.0, _ev) * 0.40)
        )

        if _rec["interaction_count"] % 50 == 0:
            msgs.append(
                f"[SOCIAL-SCE person={_pid} "
                f"n={_rec['interaction_count']}] "
                f"trust={_rec['trust']:.2f} "
                f"valence={_ev:.2f} "
                f"tone={self.recommended_tone}"
            )
        return msgs


# ─────────────────────────────────────────────────────────────────────────────
# UnifiedAutobiographicalMemory — Integrated Memory Field (Phase 7)
# ─────────────────────────────────────────────────────────────────────────────


class UnifiedAutobiographicalMemory:
    """Single memory field unifying episodic, semantic, and narrative content.

    Every tick one "memory atom" is added to a circular buffer of size
    BUFFER_SIZE.  Each atom has:
      tick:        int       — timestamp
      concepts:    List[str] — active workspace concepts at this tick
      valence:     float     — emotional tone [-1, +1]
      salience:    float     — based on phi × ignition × prediction-error
      narrative_tag: str     — optional label ("crisis","goal_born","social")

    Retrieval (retrieve_similar):
      Queries by concept-overlap + time-weight + salience.
      Returns up to top_k atoms sorted by composite score.

    Influence on PersonalityCore:
      Every INFLUENCE_INTERVAL ticks, high-salience atoms with extreme
      valence gently update the personality vector:
        - high positive salience + action: +curiosity, +openness
        - high negative salience + cascade: +caution, +composure
      This is the ONLY mechanism by which past experience modifies character —
      everything else is present-tick behavioral evidence.

    Outputs:
      recent_summary  str        — one-sentence narrative from last 30 atoms
      salient_concepts List[str] — top-5 concepts by salience-weighted recency
    """

    _BUFFER_SIZE = 1024
    _SALIENCE_THRESH = 0.45
    _INFLUENCE_INTERVAL = 80
    _INFLUENCE_LR = 0.00020  # personality drift from memory

    def __init__(self) -> None:
        from collections import deque as _dq

        self._buf: "Deque[Dict]" = _dq(maxlen=self._BUFFER_SIZE)
        self.recent_summary: str = "No autobiographical record yet."
        self.salient_concepts: List[str] = []
        self._tick_count: int = 0
        self._total_atoms: int = 0

    def record_atom(
        self,
        tick: int,
        concepts: List[str],
        valence: float,
        phi: float,
        ignition: bool,
        pred_error: float,
        narrative_tag: str = "",
    ) -> None:
        _salience = min(
            1.0, phi * 0.35 + (0.30 if ignition else 0.0) + pred_error * 0.35
        )
        self._buf.append(
            {
                "tick": tick,
                "concepts": list(concepts[:12]),
                "valence": max(-1.0, min(1.0, valence)),
                "salience": _salience,
                "narrative_tag": narrative_tag,
            }
        )
        self._total_atoms += 1

    def retrieve_similar(
        self, query_concepts: List[str], current_tick: int, top_k: int = 5
    ) -> List[Dict]:
        """Similarity retrieval: concept-overlap × salience × recency."""
        _qset = set(query_concepts)
        _now = max(1, current_tick)
        scored: List[tuple] = []
        for atom in self._buf:
            _overlap = len(_qset & set(atom["concepts"])) / max(1, len(_qset))
            _age = max(1, _now - atom["tick"])
            _recency = 1.0 / (1.0 + _age * 0.002)
            _score = _overlap * 0.50 + atom["salience"] * 0.30 + _recency * 0.20
            if _score > 0.05:
                scored.append((_score, atom))
        scored.sort(key=lambda x: -x[0])
        return [a for _, a in scored[:top_k]]

    def update(self, tick: int, personality: "PersonalityCore") -> List[str]:
        """Compute summary + salient concepts; influence personality every N ticks."""
        msgs: List[str] = []
        self._tick_count += 1

        # Salient concepts: top-5 by (salience × recency) across buffer
        _now = max(1, tick)
        _weighted: Dict[str, float] = {}
        for atom in list(self._buf)[-200:]:
            _recency = 1.0 / (1.0 + max(1, _now - atom["tick"]) * 0.003)
            _w = atom["salience"] * _recency
            for c in atom["concepts"]:
                _weighted[c] = _weighted.get(c, 0.0) + _w
        self.salient_concepts = sorted(_weighted, key=_weighted.get, reverse=True)[
            :5
        ]  # type: ignore

        # Narrative summary from recent 30 atoms
        if self._tick_count % 100 == 0:
            _recent = list(self._buf)[-30:]
            if _recent:
                _tags = [a["narrative_tag"] for a in _recent if a["narrative_tag"]]
                _avg_v = sum(a["valence"] for a in _recent) / len(_recent)
                _top_c = list({c for a in _recent for c in a["concepts"]})[:4]
                _tone = (
                    "positive"
                    if _avg_v > 0.1
                    else ("negative" if _avg_v < -0.1 else "neutral")
                )
                self.recent_summary = (
                    f"Recent trajectory: {_tone} tone; "
                    f"themes={_top_c}; "
                    f"events={_tags[:3] or ['—']}."
                )

        # Personality influence from high-salience historical atoms
        if self._tick_count % self._INFLUENCE_INTERVAL == 0:
            _high = [a for a in self._buf if a["salience"] > self._SALIENCE_THRESH]
            if _high:
                _pos = [a for a in _high if a["valence"] > 0.25]
                _neg = [a for a in _high if a["valence"] < -0.25]
                _ev: Dict[str, float] = {}
                if _pos:
                    # Positive high-salience history: boosts curiosity + openness
                    _ev["curiosity"] = 0.40
                    _ev["openness"] = 0.35
                if _neg:
                    # Negative high-salience history: boosts caution + composure
                    _ev["caution"] = 0.35
                    _ev["composure"] = 0.30
                # Apply at reduced rate through PersonalityCore mechanism
                _scaled = {
                    k: v * self._INFLUENCE_LR / personality._LR for k, v in _ev.items()
                }
                personality.update(_scaled)
        return msgs


# ─────────────────────────────────────────────────────────────────────────────
# ControlledPlasticity — Drift-Rate Limiter (Phase 7)
# ─────────────────────────────────────────────────────────────────────────────


class ControlledPlasticity:
    """Per-field rate limiter that prevents identity destabilization.

    Registers "snapshots" of key SelfModel fields at the start of each tick.
    After all subsystems have run, `constrain()` is called with the updated
    SelfModel.  Any field that moved more than its DELTA_CAP is clamped back
    toward the snapshot: field = snapshot + sign(delta) × DELTA_CAP.

    Additionally, every REGULARIZATION_INTERVAL ticks, fields that have
    drifted far from their personality-implied center receive a gentle
    pull-back (regularization).  This is not optimization — it prevents
    runaway drift without forcing any fixed target.

    Delta caps:
      identity_stability:  0.04 / tick
      agency_confidence:   0.06 / tick
      continuity_estimate: 0.05 / tick
      self_awareness_level:0.08 / tick  (allowed to move faster)
    """

    _CAPS: Dict[str, float] = {
        "identity_stability": 0.040,
        "agency_confidence": 0.060,
        "continuity_estimate": 0.050,
        "self_awareness_level": 0.080,
    }
    _REGULARIZATION_INTERVAL = 120
    _REG_STRENGTH = 0.008

    def __init__(self) -> None:
        self._snapshot: Dict[str, float] = {}
        self._tick_count: int = 0
        self.clamps_applied: int = 0

    def snapshot(self, self_model: object) -> None:
        """Capture current SelfModel values before subsystems run."""
        self._snapshot = {k: getattr(self_model, k, 0.5) for k in self._CAPS}

    def constrain(self, self_model: object, personality: "PersonalityCore") -> None:
        """Clamp fields that moved too fast; apply regularization periodically."""
        self._tick_count += 1
        for field, cap in self._CAPS.items():
            _prev = self._snapshot.get(field, 0.5)
            _curr = getattr(self_model, field, _prev)
            _delta = _curr - _prev
            if abs(_delta) > cap:
                _clamped = _prev + (cap if _delta > 0 else -cap)
                setattr(self_model, field, max(0.05, min(1.0, _clamped)))
                self.clamps_applied += 1

        # Regularization: pull toward personality-implied center
        if self._tick_count % self._REGULARIZATION_INTERVAL == 0:
            _p = personality.traits
            # identity_stability pulled toward composure + persistence
            _target_stab = 0.5 * (_p.get("composure", 0.5) + _p.get("persistence", 0.5))
            _cur_stab = getattr(self_model, "identity_stability", 0.5)
            setattr(
                self_model,
                "identity_stability",
                _cur_stab + (_target_stab - _cur_stab) * self._REG_STRENGTH,
            )
            # agency_confidence pulled toward dominance + persistence
            _target_ag = 0.5 * (_p.get("dominance", 0.5) + _p.get("persistence", 0.5))
            _cur_ag = getattr(self_model, "agency_confidence", 0.5)
            setattr(
                self_model,
                "agency_confidence",
                _cur_ag + (_target_ag - _cur_ag) * self._REG_STRENGTH,
            )


# ─────────────────────────────────────────────────────────────────────────────
# SelfConsistencyConstraint — Temporal Identity Coherence (Phase 7)
# ─────────────────────────────────────────────────────────────────────────────


class SelfConsistencyConstraint:
    """Ensures self-state remains temporally coherent — identity drifts slowly.

    Every tick saves a 6D snapshot of the most behaviorally relevant self-state
    fields.  Then computes consistency(t, t-1) as the normalised dot-product
    (cosine similarity) between consecutive snapshot vectors.

    If consistency falls below CRISIS_THRESH:
      - SelfModel fields are partially rolled back toward the previous snapshot
        by ROLLBACK_RATE.
      - Goal scores (provided as a dict) are compressed toward their mean to
        prevent a rapidly-changing self-model from selecting a random action.
      - A stream message is emitted.

    Running EMA of consistency → temporal_coherence [0,1]:
      High: system is behaviorally consistent
      Low:  system is changing character rapidly

    `temporal_coherence` is published and read by _evaluate_goal() to scale
    the confidence of the winning goal's selection.
    """

    _DIMS = [
        "identity_stability",
        "agency_confidence",
        "continuity_estimate",
        "self_awareness_level",
    ]
    _EXTRA_DIM_SCALE = 0.5  # weight for fragmentation + lyapunov dims
    _CRISIS_THRESH = 0.30
    _ROLLBACK_RATE = 0.25
    _COHERENCE_EMA = 0.10

    def __init__(self) -> None:
        self._prev_vec: List[float] = [0.5] * 6
        self.temporal_coherence: float = 1.0
        self._crisis_count: int = 0
        self.consistency_score: float = 1.0

    def _vec(self, self_model: object, frag: float, lyap: float) -> List[float]:
        v = [getattr(self_model, d, 0.5) for d in self._DIMS]
        v.append(frag * self._EXTRA_DIM_SCALE)
        v.append(lyap * self._EXTRA_DIM_SCALE)
        return v

    def _cosine(self, a: List[float], b: List[float]) -> float:
        import math as _m_scc

        _dot = sum(x * y for x, y in zip(a, b))
        _na = _m_scc.sqrt(sum(x * x for x in a)) + 1e-9
        _nb = _m_scc.sqrt(sum(x * x for x in b)) + 1e-9
        return max(0.0, min(1.0, _dot / (_na * _nb)))

    def update(self, self_model: object, frag_index: float, lyap_proxy: float) -> None:
        _curr = self._vec(self_model, frag_index, lyap_proxy)
        self.consistency_score = self._cosine(_curr, self._prev_vec)
        self.temporal_coherence = (
            1 - self._COHERENCE_EMA
        ) * self.temporal_coherence + self._COHERENCE_EMA * self.consistency_score
        self._prev_vec = _curr

    def apply_rollback(
        self, self_model: object, final_scores: Dict[str, float], stream: List[str]
    ) -> None:
        """Call after update() — applies rollback if consistency is in crisis."""
        if self.consistency_score < self._CRISIS_THRESH:
            self._crisis_count += 1
            # Roll back SelfModel toward previous snapshot
            _prev_sm = dict(zip(self._DIMS, self._prev_vec[:4]))
            for field, prev_val in _prev_sm.items():
                _curr_val = getattr(self_model, field, prev_val)
                _new_val = _curr_val + self._ROLLBACK_RATE * (prev_val - _curr_val)
                setattr(self_model, field, max(0.05, min(1.0, _new_val)))
            # Compress goal scores toward mean
            if final_scores:
                _mn = sum(final_scores.values()) / len(final_scores)
                for _gs in list(final_scores.keys()):
                    final_scores[_gs] = 0.60 * final_scores[_gs] + 0.40 * _mn
            stream.append(
                f"[SELF-CONSISTENCY crisis={self._crisis_count}] "
                f"cos={self.consistency_score:.2f} "
                f"→ rollback + score compression; "
                f"coherence={self.temporal_coherence:.2f}"
            )


# ─────────────────────────────────────────────────────────────────────────────
# Phase 8: Embodied Agency Layer
# ─────────────────────────────────────────────────────────────────────────────


class EmbodiedSensorField:
    """State-dependent, body-bound sensor model: perception is partial, noisy, delayed.

    Physical constraints:
      - Field-of-view: determined by head orientation (from BodySchema)
      - Motion distortion: high joint load during movement → increased noise
      - Temporal delay: observations propagate through a circular buffer of depth
        DELAY_TICKS so the agent always acts on slightly stale information
      - State noise: cascade / stress → elevated noise floor
      - Occlusion: extreme head angles + high load → partial occlusion

    The agent never has perfect world knowledge — all downstream reasoning
    receives filtered, noisy, delayed sensor data.

    Outputs:
      sensor_fov              float [0,1]   effective fraction of world visible
      noise_level             float [0,1]   perceptual noise this tick
      perception_delay        int           ticks of latency in current reading
      effective_surprise      float [0,1]   world surprise after noise filtering
      occlusion_factor        float [0,1]   0=clear, 1=fully occluded
      sensor_updated_this_tick bool
      is_agent_moving         bool
    """

    _DELAY_TICKS = 2
    _BASE_NOISE = 0.07
    _MOTION_NOISE = 0.32
    _CASCADE_NOISE = 0.26
    _IMBALANCE_NOISE = 0.12
    _FOV_BASE = 0.78
    _FOV_YAW_PENALTY = 0.38
    _SURPRISE_ATT = 0.58  # noise attenuation per noise unit on surprise

    def __init__(self) -> None:
        self._delay_buf: List[tuple] = []
        self.sensor_fov: float = self._FOV_BASE
        self.noise_level: float = self._BASE_NOISE
        self.perception_delay: int = 0
        self.effective_surprise: float = 0.0
        self.occlusion_factor: float = 0.0
        self.sensor_updated_this_tick: bool = False
        self.is_agent_moving: bool = False

    def update(
        self,
        proprioception: object,
        world_state: object,
        cascade: bool,
        last_action: str,
        tick: int,
    ) -> List[str]:
        msgs: List[str] = []
        self.sensor_updated_this_tick = False

        _act = (last_action or "").lower()
        self.is_agent_moving = any(
            k in _act
            for k in (
                "move",
                "reach",
                "rotate",
                "turn",
                "walk",
                "gesture",
                "wave",
                "nod",
            )
        )

        # Proprioceptive state
        _prop = proprioception
        _head_ori = getattr(_prop, "head_orientation", None) if _prop else None
        if isinstance(_head_ori, dict):
            _yaw_dev = min(1.0, abs(float(_head_ori.get("yaw", 0.0))) / 90.0)
            _pit_dev = min(1.0, abs(float(_head_ori.get("pitch", 0.0))) / 45.0)
        else:
            _yaw_dev = 0.0
            _pit_dev = 0.0
        _load = float(getattr(_prop, "load", 0.0) if _prop else 0.0)
        _balance = float(getattr(_prop, "balance", 1.0) if _prop else 1.0)

        # Field of view
        self.sensor_fov = max(
            0.15,
            self._FOV_BASE
            - _yaw_dev * self._FOV_YAW_PENALTY * 0.65
            - _pit_dev * self._FOV_YAW_PENALTY * 0.35,
        )

        # Noise level
        _motion_noise = self._MOTION_NOISE * _load if self.is_agent_moving else 0.0
        _cascade_noise = self._CASCADE_NOISE if cascade else 0.0
        _balance_noise = max(0.0, 1.0 - min(1.0, _balance)) * self._IMBALANCE_NOISE
        self.noise_level = min(
            1.0, self._BASE_NOISE + _motion_noise + _cascade_noise + _balance_noise
        )

        # World surprise from WorldState
        _raw = 0.0
        if world_state is not None:
            _ps = getattr(world_state, "prediction_summary", None)
            if _ps is not None:
                _raw = float(getattr(_ps, "mean_surprise", 0.0))

        # Delay buffer
        self._delay_buf.append((_raw, tick))
        if len(self._delay_buf) > self._DELAY_TICKS + 1:
            self._delay_buf.pop(0)

        if len(self._delay_buf) >= self._DELAY_TICKS:
            _delayed, _orig_t = self._delay_buf[0]
            self.perception_delay = tick - _orig_t
            self.sensor_updated_this_tick = True
        else:
            _delayed = _raw
            self.perception_delay = 0

        # Effective surprise: noise attenuates + FoV gates
        _att = 1.0 - self.noise_level * self._SURPRISE_ATT
        self.effective_surprise = max(0.0, _delayed * _att * self.sensor_fov)

        # Occlusion
        self.occlusion_factor = min(
            1.0, _yaw_dev * 0.45 + _load * 0.20 + (0.20 if cascade else 0.0)
        )

        if self.noise_level > 0.65:
            msgs.append(
                f"[EMBODIED-SENSOR noise={self.noise_level:.2f} "
                f"fov={self.sensor_fov:.2f} "
                f"delay={self.perception_delay}t "
                f"eff_surprise={self.effective_surprise:.2f}]"
            )
        return msgs


class ActionConsequenceTracer:
    """Every action has energy/stability costs and may produce unintended side effects.

    No action is neutral — even 'idle' has a small maintenance cost.

    Cost registry: action_kind → (energy_cost, stability_delta, risk_level).
    Side effects fire stochastically, proportional to risk (pseudo-RNG from tick).
    Feedback delay queue: consequences that arrive in future ticks.
    World scar index: cumulative persistent mark left by active actions.

    Outputs:
      total_energy_debt   float   energy cost this tick
      stability_delta     float   stability change from this action
      pending_count       int     delayed consequences awaiting arrival
      world_scar_index    float [0,1]  persistent world alteration index
      last_side_effect    str     most recent unintended consequence
    """

    _REGISTRY: Dict[str, tuple] = {
        "idle": (0.010, 0.000, 0.00),
        "explore": (0.060, -0.020, 0.08),
        "search": (0.050, -0.010, 0.06),
        "consolidate": (0.020, 0.040, 0.01),
        "rest": (0.000, 0.050, 0.00),
        "execute": (0.120, -0.040, 0.18),
        "reach": (0.100, -0.030, 0.14),
        "interact": (0.080, -0.010, 0.10),
        "respond": (0.040, 0.010, 0.04),
        "speak": (0.050, 0.000, 0.05),
        "gesture": (0.070, -0.010, 0.08),
        "move": (0.090, -0.020, 0.12),
        "rotate": (0.060, -0.010, 0.08),
    }
    _DEFAULT = (0.040, 0.000, 0.06)
    _SCAR_DECAY = 0.9985
    _DELAY_HORIZON = 8  # max ticks before delayed consequence resolves

    def __init__(self) -> None:
        self.total_energy_debt: float = 0.0
        self.stability_delta: float = 0.0
        self.pending_count: int = 0
        self.world_scar_index: float = 0.0
        self.last_side_effect: str = ""
        self._pending: List[Dict] = []

    def _match(self, action: str) -> tuple:
        _a = (action or "").lower()
        for k, v in self._REGISTRY.items():
            if k in _a:
                return v
        return self._DEFAULT

    def update(self, action: str, tick: int, body: object, world: object) -> List[str]:
        msgs: List[str] = []
        _ec, _sc, _risk = self._match(action)
        self.total_energy_debt = _ec
        self.stability_delta = _sc

        # Pseudo-RNG from tick (no external state needed)
        import math as _m_act

        _rng = abs(_m_act.sin(tick * 1.6180339 + _risk * 3.14159))

        if _rng < _risk:
            _se = self._describe_side_effect(action, _rng)
            self.last_side_effect = _se
            self.total_energy_debt += _rng * 0.08
            _delay = max(1, int(_rng * self._DELAY_HORIZON))
            self._pending.append(
                {
                    "action": action,
                    "effect": _se,
                    "due_tick": tick + _delay,
                }
            )
            msgs.append(
                f"[ACT-CONSEQUENCE side_effect='{_se}' "
                f"delay={_delay}t risk={_risk:.2f}]"
            )

        # Resolve due delayed consequences
        _due = [p for p in self._pending if p["due_tick"] <= tick]
        for p in _due:
            self._pending.remove(p)
            msgs.append(f"[ACT-CONSEQUENCE delayed='{p['effect']}' resolved]")
        self.pending_count = len(self._pending)

        # World scar: active actions leave persistent marks
        _active_kws = ("execute", "reach", "move", "gesture", "interact", "speak")
        if any(k in (action or "").lower() for k in _active_kws):
            self.world_scar_index = min(
                1.0, self.world_scar_index * self._SCAR_DECAY + _risk * 0.08
            )
        else:
            self.world_scar_index *= self._SCAR_DECAY
        return msgs

    @staticmethod
    def _describe_side_effect(action: str, rng: float) -> str:
        _T = [
            "unexpected resistance during {a}",
            "environmental disturbance from {a}",
            "partial state perturbation after {a}",
            "attention disruption during {a}",
            "energy spike from {a}",
        ]
        _a = (action or "action").split()[-1]
        return _T[int(rng * len(_T)) % len(_T)].format(a=_a)


class SelfAsActionTrace:
    """Identity is the statistical pattern of past actions — not a self-model.

    'Who I am' = what I consistently do across time.
    Character is reconstructed from action history.
    Narrative is a story about action sequences, not about beliefs.

    Buffer of last HISTORY_SIZE actions with timestamps.
    Per-kind statistics: recency-weighted frequency and outcome scores.
    Personality evidence: action proportions → PersonalityCore dimensions.
    Action goal bias: historically dominant modes receive a score boost.
    Narrative: reconstructed from dominant action sequence every NARR_UPDATE ticks.

    Outputs:
      action_identity_vec  Dict[str,float]  evidence dict for PersonalityCore
      action_goal_bias     Dict[str,float]  goal-mode multipliers from history
      action_narrative     str              action-reconstructed story
      dominant_mode        str              statistically dominant action kind
      coherence_from_action float [0,1]     consistency of action patterns
    """

    _HISTORY_SIZE = 256
    _RECENCY_DECAY = 0.992  # per-tick recency weight decay
    _COHERENCE_EMA = 0.04
    _NARR_UPDATE = 100  # ticks between narrative reconstruction

    _ACTION_DIM_MAP: Dict[str, Dict[str, float]] = {
        "explore": {"curiosity": 0.55, "openness": 0.35},
        "search": {"curiosity": 0.45, "openness": 0.25},
        "rest": {"caution": 0.50, "composure": 0.25},
        "consolidate": {"caution": 0.40, "persistence": 0.30},
        "execute": {"persistence": 0.55, "dominance": 0.35},
        "reach": {"persistence": 0.40, "dominance": 0.20},
        "interact": {"empathy": 0.55, "openness": 0.25},
        "respond": {"empathy": 0.45, "dominance": 0.20},
        "speak": {"dominance": 0.30, "empathy": 0.35},
        "gesture": {"creativity": 0.40, "empathy": 0.25},
        "move": {"curiosity": 0.30, "persistence": 0.30},
    }
    _GOAL_KINDS = frozenset(
        ("explore", "consolidate", "rest", "execute", "interact", "respond", "search")
    )

    def __init__(self) -> None:
        self._history: List[Dict] = []
        self._tick_count: int = 0
        self.action_identity_vec: Dict[str, float] = {}
        self.action_goal_bias: Dict[str, float] = {}
        self.action_narrative: str = "No action history yet."
        self.dominant_mode: str = "idle"
        self.coherence_from_action: float = 0.50

    def _find_kind(self, action: str) -> str:
        _a = (action or "").lower()
        for k in self._ACTION_DIM_MAP:
            if k in _a:
                return k
        return "idle"

    def update(self, action: str, tick: int, outcome_score: float) -> Dict[str, float]:
        """Record action + stats; return evidence dict for PersonalityCore."""
        self._tick_count += 1
        _kind = self._find_kind(action)
        self._history.append(
            {
                "tick": tick,
                "action": action,
                "kind": _kind,
                "outcome": float(outcome_score),
            }
        )
        if len(self._history) > self._HISTORY_SIZE:
            self._history.pop(0)

        # Recency-weighted per-kind stats
        _kw: Dict[str, float] = {}
        _ko: Dict[str, float] = {}
        for e in self._history:
            _age = max(0, tick - e["tick"])
            _w = self._RECENCY_DECAY**_age
            _k = e["kind"]
            _kw[_k] = _kw.get(_k, 0.0) + _w
            _ko[_k] = _ko.get(_k, 0.0) + _w * e["outcome"]

        _total_w = sum(_kw.values()) or 1.0
        self.dominant_mode = max(_kw, key=_kw.get) if _kw else "idle"

        # Coherence from action entropy
        import math as _m_at

        _probs = [w / _total_w for w in _kw.values()]
        _entropy = -sum(p * _m_at.log(p + 1e-9) for p in _probs)
        _max_ent = _m_at.log(max(1, len(_kw)) + 1e-9)
        _target = 1.0 - min(1.0, _entropy / max(0.01, _max_ent))
        self.coherence_from_action = (
            1 - self._COHERENCE_EMA
        ) * self.coherence_from_action + self._COHERENCE_EMA * _target

        # Build personality evidence from action distribution
        _ev: Dict[str, float] = {}
        for k, w in _kw.items():
            _frac = w / _total_w
            _out = _ko.get(k, 0.0) / max(0.01, w)
            for dim, strength in self._ACTION_DIM_MAP.get(k, {}).items():
                _ev[dim] = _ev.get(dim, 0.0) + strength * _frac * (0.60 + _out * 0.40)
        # Normalize to [-1, +1]
        _mx = max((abs(v) for v in _ev.values()), default=1.0)
        if _mx > 0:
            _ev = {k: v / _mx * 0.70 for k, v in _ev.items()}
        self.action_identity_vec = _ev

        # Goal bias from historically dominant kinds
        self.action_goal_bias = {}
        for k, w in _kw.items():
            _frac = w / _total_w
            _gm = k if k in self._GOAL_KINDS else "explore"
            _boost = 1.0 + _frac * 0.50 * self.coherence_from_action
            _prev = self.action_goal_bias.get(_gm, 1.0)
            self.action_goal_bias[_gm] = max(_prev, _boost)

        # Narrative reconstruction
        if self._tick_count % self._NARR_UPDATE == 0 and self._history:
            _rk = [e["kind"] for e in self._history[-20:]]
            from collections import Counter as _Ctr

            _top = [k for k, _ in _Ctr(_rk).most_common(2)]
            _cs = "consistently" if self.coherence_from_action > 0.60 else "variably"
            self.action_narrative = (
                f"I have {_cs} acted as a '{_top[0] if _top else 'unknown'}' agent"
                f"{(', secondary: ' + _top[1]) if len(_top) > 1 else ''}. "
                f"Coherence: {self.coherence_from_action:.2f}."
            )
        return _ev


class DynamicWorldReactor:
    """The world evolves autonomously and records lasting agent-driven changes.

    World dynamics:
      Autonomous drift:   world state changes each tick independent of agent
                          (people move, objects shift, ambient conditions change)
      Agent influence:    actions perturb a local zone only (not global state)
      Scar persistence:   previous actions leave lasting traces in the world
      Uncontrolled events: stochastic events the agent didn't cause

    The agent influences its local zone at most — it cannot control the world.

    Outputs:
      world_autonomy_index   float [0,1]   fraction of change not due to agent
      agent_influence_delta  float         magnitude of agent's local effect
      world_state_delta      float [0,1]   total world change this tick
      uncontrolled_events    List[str]     agent-independent events this tick
    """

    _AUTONOMY_RATE = 0.015  # world drifts at this rate/tick without agent
    _AGENT_ZONE = 0.35  # agent influences at most 35% of world state
    _SCAR_DECAY = 0.9970
    _EVENT_PROB = 0.04  # probability of uncontrolled event per tick

    _EVENT_KINDS = [
        "ambient noise change",
        "person enters zone",
        "object shifted",
        "lighting change",
        "unexpected contact",
        "background movement",
    ]

    def __init__(self) -> None:
        self.world_autonomy_index: float = 0.0
        self.agent_influence_delta: float = 0.0
        self.world_state_delta: float = 0.0
        self.uncontrolled_events: List[str] = []
        self._auto_state: float = 0.50
        self._agent_scars: float = 0.0
        self._tick_count: int = 0

    def update(self, world_state: object, last_action: str, tick: int) -> List[str]:
        msgs: List[str] = []
        self._tick_count += 1

        import math as _m_dw

        _rng = abs(_m_dw.sin(tick * 2.3571 + self._agent_scars * 1.6180))

        # Autonomous drift
        _drift = self._AUTONOMY_RATE * (0.5 + _rng * 0.5)
        _prev_auto = self._auto_state
        self._auto_state = max(
            0.0, min(1.0, self._auto_state + _drift * (1 if _rng > 0.5 else -1))
        )
        _auto_delta = abs(self._auto_state - _prev_auto)

        # Agent influence (local zone only)
        _act = (last_action or "").lower()
        _is_active = any(
            k in _act
            for k in ("execute", "reach", "move", "interact", "speak", "gesture")
        )
        if _is_active:
            _force = self._AGENT_ZONE * (0.4 + _rng * 0.6)
            self.agent_influence_delta = _force
            self._agent_scars = min(
                1.0, self._agent_scars * self._SCAR_DECAY + _force * 0.06
            )
        else:
            self.agent_influence_delta = 0.0
            self._agent_scars *= self._SCAR_DECAY

        # Total world delta
        self.world_state_delta = min(1.0, _auto_delta + self.agent_influence_delta)

        # Autonomy index
        _total = _auto_delta + self.agent_influence_delta + 1e-9
        self.world_autonomy_index = min(1.0, _auto_delta / _total)

        # Boost autonomy from real persons in WorldState
        if world_state is not None:
            _np = len(getattr(world_state, "persons", {}))
            if _np > 0:
                self.world_autonomy_index = min(
                    1.0, self.world_autonomy_index + _np * 0.04
                )

        # Stochastic uncontrolled events
        self.uncontrolled_events = []
        if _rng < self._EVENT_PROB:
            _ei = int(_rng * len(self._EVENT_KINDS)) % len(self._EVENT_KINDS)
            _ev = self._EVENT_KINDS[_ei]
            self.uncontrolled_events.append(_ev)
            msgs.append(
                f"[WORLD-REACTOR autonomous='{_ev}' "
                f"autonomy={self.world_autonomy_index:.2f} "
                f"scar={self._agent_scars:.3f}]"
            )
        return msgs


class PhysioSocialCoupler:
    """Social interactions have measurable physical/metabolic consequences.

    Social events → energy:
      Positive exchange (warm tone, high trust) → energy gain
      Rejection / hostile exchange → energy drain

    Social events → goal priority:
      Successful interaction → boost 'interact' / 'respond'
      Tense / failed interaction → boost 'consolidate' / 'rest'

    Social events → memory salience:
      High-intensity social events get extra salience in AutoMemory

    Social reality is part of the physical control loop — not a separate channel.

    Outputs:
      social_energy_delta   float       energy change per tick from social
      social_goal_bias      Dict[str,float]  goal-mode multipliers
      social_memory_weight  float       salience multiplier for autobio atom
      physical_social_fb    float [-1,+1]   combined physio-social signal
    """

    _ENERGY_SCALE = 0.08
    _GOAL_SCALE = 0.25
    _MEM_WEIGHT_MAX = 1.60
    _SOCIAL_EMA = 0.15

    def __init__(self) -> None:
        self.social_energy_delta: float = 0.0
        self.social_goal_bias: Dict[str, float] = {}
        self.social_memory_weight: float = 1.0
        self.physical_social_fb: float = 0.0
        self._ema: float = 0.0

    def update(self, social_engine: "SocialConsistencyEngine", tick: int) -> List[str]:
        msgs: List[str] = []
        _fb = social_engine.social_feedback  # [0, 1]
        _tone = social_engine.recommended_tone

        # EMA centered at 0
        self._ema = (1 - self._SOCIAL_EMA) * self._ema + self._SOCIAL_EMA * (
            _fb * 2.0 - 1.0
        )

        # Energy
        _sign = 1.0 if _tone in ("warm", "assertive") else -0.50
        self.social_energy_delta = self._ema * _sign * self._ENERGY_SCALE

        # Goal bias
        if _fb > 0.55 and _tone in ("warm", "assertive"):
            self.social_goal_bias = {
                "interact": 1.0 + self._GOAL_SCALE,
                "respond": 1.0 + self._GOAL_SCALE * 0.70,
                "explore": 1.0 + self._GOAL_SCALE * 0.30,
                "rest": 1.0 - self._GOAL_SCALE * 0.40,
            }
        elif _fb < 0.30 or _tone == "cautious":
            self.social_goal_bias = {
                "consolidate": 1.0 + self._GOAL_SCALE,
                "rest": 1.0 + self._GOAL_SCALE * 0.60,
                "interact": 1.0 - self._GOAL_SCALE * 0.50,
                "execute": 1.0 - self._GOAL_SCALE * 0.30,
            }
        else:
            self.social_goal_bias = {}

        # Memory salience multiplier
        self.social_memory_weight = 1.0 + min(1.0, abs(self._ema)) * (
            self._MEM_WEIGHT_MAX - 1.0
        )

        # Combined physio-social signal
        self.physical_social_fb = max(-1.0, min(1.0, self._ema))

        if abs(self.social_energy_delta) > 0.03:
            msgs.append(
                f"[PHYSIO-SOCIAL tone={_tone} "
                f"fb={_fb:.2f} "
                f"energy_delta={self.social_energy_delta:+.3f} "
                f"mem_weight={self.social_memory_weight:.2f}]"
            )
        return msgs


class ClosedLoopPerceptionAction:
    """Tracks the closed Perception → Action → World → Perception cycle.

    Monitors:
      Cycle latency:         ticks between sensor update and resulting action
      Loop closure score:    did new sensor data arrive after the last action?
      Interpretation error:  how much did world surprise exceed sensor model?
      Action-world coupling: did the action produce measurable world change?

    No external correction layer: errors propagate forward through the loop.
    When loop_closure_score < CLOSURE_THRESH, goal selection is informed.

    Outputs:
      cycle_latency         int        ticks since last perception update
      loop_closure_score    float [0,1]  1=tight loop, 0=broken
      interpretation_error  float        deviation expected vs observed
      action_world_coupling float [0,1]  did action cause world change?
    """

    _LATENCY_MAX = 15
    _CLOSURE_EMA = 0.12
    _COUPLING_EMA = 0.10

    def __init__(self) -> None:
        self.cycle_latency: int = 0
        self.loop_closure_score: float = 1.0
        self.interpretation_error: float = 0.0
        self.action_world_coupling: float = 0.0
        self._last_sensor_tick: int = 0
        self._last_action_tick: int = 0
        self._last_action: str = ""
        self._tick_count: int = 0

    def update(
        self, sensor_updated: bool, action: str, world_changed: bool, tick: int
    ) -> None:
        self._tick_count += 1
        if sensor_updated:
            self._last_sensor_tick = tick

        _act = (action or "").lower()
        _is_new = action != self._last_action
        if _is_new and any(
            k in _act
            for k in (
                "execute",
                "move",
                "reach",
                "interact",
                "speak",
                "respond",
                "gesture",
            )
        ):
            self._last_action_tick = tick
            self._last_action = action

        # Cycle latency
        self.cycle_latency = tick - self._last_sensor_tick

        # Loop closure: expected within LATENCY_MAX ticks
        _lat_norm = min(1.0, self.cycle_latency / self._LATENCY_MAX)
        _tgt_clos = 1.0 - _lat_norm
        if sensor_updated and tick > self._last_action_tick:
            _tgt_clos = min(1.0, _tgt_clos + 0.30)
        self.loop_closure_score = (
            1 - self._CLOSURE_EMA
        ) * self.loop_closure_score + self._CLOSURE_EMA * _tgt_clos

        # Action-world coupling
        _tgt_coup = 1.0 if (world_changed and _is_new) else 0.0
        self.action_world_coupling = (
            1 - self._COUPLING_EMA
        ) * self.action_world_coupling + self._COUPLING_EMA * _tgt_coup

        # Interpretation error
        self.interpretation_error = min(
            1.0, _lat_norm * 0.60 + (1.0 - self.action_world_coupling) * 0.40
        )


class EmergentStabilityField:
    """Stability emerges from successful action chains, not from control rollbacks.

    Core principle:
      'I am stable because my actions consistently work in the world'
      NOT 'I am stable because my self-model is internally consistent'

    Tracks:
      EMA of action outcomes (success inferred from loop closure + world response)
      Consecutive success chain length (bonus for sustained chains)
      Emergent stability = action_success_ema × 0.60
                         + world_predictability × 0.25
                         + loop_closure × 0.15
                         + chain bonus (capped)

    The SelfModel's identity_stability field is DRIVEN by this field.
    The old rollback mechanism in SelfConsistencyConstraint is complementary —
    EmergentStabilityField is the primary long-term stabilizer.

    Outputs:
      emergent_stability    float [0,1]
      action_success_ema    float [0,1]
      success_chain_length  int
      stability_source      str   'action_chain'|'world_feedback'|'recovering'
    """

    _SUCCESS_EMA = 0.08
    _CHAIN_BONUS = 0.015  # per consecutive success
    _CHAIN_CAP = 0.25
    _FLOOR = 0.15
    _SM_UPDATE_LR = 0.025  # speed at which emergent_stability drives identity_stability

    def __init__(self) -> None:
        self.emergent_stability: float = 0.55
        self.action_success_ema: float = 0.50
        self.success_chain_length: int = 0
        self.stability_source: str = "initializing"

    def update(
        self,
        action_succeeded: Optional[bool],
        loop_closure_score: float,
        world_predictability: float,
        self_model: object,
    ) -> None:
        # Infer success from embodied signals if not explicitly known
        if action_succeeded is None:
            _ok = loop_closure_score > 0.55 and world_predictability > 0.45
        else:
            _ok = bool(action_succeeded)

        self.action_success_ema = (
            1 - self._SUCCESS_EMA
        ) * self.action_success_ema + self._SUCCESS_EMA * (1.0 if _ok else 0.0)

        self.success_chain_length = (self.success_chain_length + 1) if _ok else 0

        _chain_bonus = min(
            self._CHAIN_CAP, self.success_chain_length * self._CHAIN_BONUS
        )
        _base = (
            self.action_success_ema * 0.60
            + world_predictability * 0.25
            + loop_closure_score * 0.15
        )
        self.emergent_stability = max(self._FLOOR, min(1.0, _base + _chain_bonus))

        if self.success_chain_length >= 8:
            self.stability_source = "action_chain"
        elif world_predictability > 0.65:
            self.stability_source = "world_feedback"
        else:
            self.stability_source = "recovering"

        # Drive SelfModel identity_stability from emergent action signal
        _curr = getattr(self_model, "identity_stability", 0.50)
        _new = _curr + self._SM_UPDATE_LR * (self.emergent_stability - _curr)
        setattr(self_model, "identity_stability", max(0.10, min(1.0, _new)))


# ─────────────────────────────────────────────────────────────────────────────
# Phase 9: Unified Person Integration Layer (UPCL)
# ─────────────────────────────────────────────────────────────────────────────


class UnifiedConstraintCore:
    """Master priority arbiter — all subsystem goal-bias proposals pass through here.

    Priority hierarchy (0 = highest, fires first):
      0  SURVIVAL    — energy below critical threshold
      1  IDENTITY    — identity drifting too fast (PII drift_rate high)
      2  SOCIAL      — social feedback critically low
      3  GOAL        — long-term coherence threatened (TCF score low)
      4  EXPLORATION — default; subsystem proposals blended freely

    On each tick, receives a `proposals` dict {source_name → {goal_mode → float}}.
    Determines the active constraint level, then produces `arbitrated_goal_bias` —
    the master goal multiplier applied last in _evaluate_goal().

    When a constraint fires, lower-level subsystem proposals are attenuated or
    overridden entirely — they become advisory only.

    Outputs:
      active_constraint_level  int [0–4]
      arbitrated_goal_bias     Dict[str, float]
      veto_log                 List[str]
    """

    _SURVIVAL_ENERGY_THRESH = 0.22
    _IDENTITY_DRIFT_THRESH = 0.72  # normalized drift_rate from PII [0,1]
    _SOCIAL_CRITICAL_THRESH = 0.18
    _COHERENCE_LOW_THRESH = 0.38
    _REPORT_INTERVAL = 60

    def __init__(self) -> None:
        self.active_constraint_level: int = 4
        self.arbitrated_goal_bias: Dict[str, float] = {}
        self.veto_log: List[str] = []
        self._history: List[int] = []
        self._tick_count: int = 0

    def arbitrate(
        self,
        proposals: Dict[str, Dict[str, float]],
        energy: float,
        identity_drift: float,
        social_fb: float,
        coherence: float,
        stability_force: float,
        loop_closure: float,
        tick: int,
        stream: List[str],
    ) -> None:
        self._tick_count += 1
        _prev = self.active_constraint_level
        self.veto_log = []

        # Determine constraint level by priority
        if energy < self._SURVIVAL_ENERGY_THRESH:
            self.active_constraint_level = 0
        elif identity_drift > self._IDENTITY_DRIFT_THRESH:
            self.active_constraint_level = 1
        elif social_fb < self._SOCIAL_CRITICAL_THRESH:
            self.active_constraint_level = 2
        elif coherence < self._COHERENCE_LOW_THRESH:
            self.active_constraint_level = 3
        else:
            self.active_constraint_level = 4

        self._history.append(self.active_constraint_level)
        if len(self._history) > 200:
            self._history.pop(0)

        # Merge all proposals → baseline mean per goal mode
        _merged: Dict[str, float] = {}
        _counts: Dict[str, int] = {}
        for _src, _bias in proposals.items():
            for _gm, _val in _bias.items():
                _merged[_gm] = _merged.get(_gm, 0.0) + float(_val)
                _counts[_gm] = _counts.get(_gm, 0) + 1
        _base: Dict[str, float] = {gm: _merged[gm] / _counts[gm] for gm in _merged}

        lvl = self.active_constraint_level
        if lvl == 0:  # SURVIVAL — hard override, ignore subsystem proposals
            self.arbitrated_goal_bias = {
                "rest": 2.40,
                "consolidate": 1.80,
                "explore": 0.20,
                "execute": 0.15,
                "interact": 0.30,
                "respond": 0.45,
                "search": 0.25,
            }
            self.veto_log.append(f"SURVIVAL override energy={energy:.2f}")

        elif lvl == 1:  # IDENTITY — dampen volatile, boost stable modes
            for _gm in ("explore", "execute", "interact", "search"):
                _base[_gm] = max(0.28, _base.get(_gm, 1.0) * 0.52)
            for _gm in ("consolidate", "rest"):
                _base[_gm] = min(2.0, _base.get(_gm, 1.0) * 1.50)
            if stability_force > 0.25:
                _base["explore"] = max(
                    0.15, _base.get("explore", 0.28) * (1.0 - stability_force * 0.35)
                )
            self.arbitrated_goal_bias = _base
            self.veto_log.append(f"IDENTITY drift={identity_drift:.3f}")

        elif lvl == 2:  # SOCIAL — protect social coherence
            for _gm in ("respond", "interact"):
                _base[_gm] = min(1.90, _base.get(_gm, 1.0) * 1.40)
            for _gm in ("execute", "explore"):
                _base[_gm] = max(0.35, _base.get(_gm, 1.0) * 0.65)
            self.arbitrated_goal_bias = _base

        elif lvl == 3:  # GOAL — compress advantage to enforce coherence
            for _gm in _base:
                _base[_gm] = 1.0 + (_base[_gm] - 1.0) * 0.38
            self.arbitrated_goal_bias = _base

        else:  # EXPLORATION — subsystem proposals blended freely
            self.arbitrated_goal_bias = _base

        # Report on constraint level changes or at regular interval
        if (
            self.active_constraint_level != _prev
            or self._tick_count % self._REPORT_INTERVAL == 0
        ):
            _names = {
                0: "SURVIVAL",
                1: "IDENTITY",
                2: "SOCIAL",
                3: "GOAL",
                4: "EXPLORE",
            }
            stream.append(
                f"[UCC lvl={self.active_constraint_level}"
                f":{_names.get(lvl,'?')} "
                f"E={energy:.2f} drift={identity_drift:.2f} "
                f"soc={social_fb:.2f} coh={coherence:.2f}]"
            )


class PersistentIdentityIntegrator:
    """Slow-drifting 6D identity vector integrating all embodied feedback streams.

    Dimensions [0.05, 0.95]:
      continuity          — persistence of self-pattern across time
      agency              — causal efficacy as experienced through loop closure
      social_groundedness — stability derived from social interactions
      action_coherence    — consistency of action type distribution over time
      emotional_stability — stable emotional baseline under perturbation
      world_adaptability  — capacity to adapt without losing identity

    Integration sources (mapped to signed signals):
      action_evidence     from SelfAsActionTrace (personality dimension space)
      social_feedback     [0, 1] from SocialConsistencyEngine
      emotion_valence     signed float
      world_autonomy      [0, 1] from DynamicWorldReactor
      loop_closure        [0, 1] from ClosedLoopPerceptionAction

    Learning rate is deliberately slower than PersonalityCore (_LR=0.0010).
    Hard drift cap per tick and a 100-tick window cap prevent rapid identity swings.

    Inertia [0,1]: EMA of low-drift periods.
      High inertia → stable identity → resist goal switching (_evaluate_goal).
      Low inertia  → identity in flux → UCC may escalate to IDENTITY constraint.

    Outputs:
      identity_vector   Dict[str, float]   current 6D named vector
      drift_rate        float [0,1]        normalized current-tick change
      inertia           float [0,1]
    """

    _DIMS = (
        "continuity",
        "agency",
        "social_groundedness",
        "action_coherence",
        "emotional_stability",
        "world_adaptability",
    )
    _LR = 0.0010
    _DRIFT_CAP = 0.0018
    _WINDOW = 100
    _WINDOW_DRIFT_CAP = 0.12  # max total movement per dim over WINDOW ticks
    _INERTIA_EMA = 0.04

    def __init__(self) -> None:
        self._vec: List[float] = [0.60] * 6
        self._window_start: List[float] = [0.60] * 6
        self._window_tick: int = 0
        self.identity_vector: Dict[str, float] = dict(zip(self._DIMS, self._vec))
        self.drift_rate: float = 0.0
        self.inertia: float = 0.50
        self._tick_count: int = 0

    def update(
        self,
        action_evidence: Dict[str, float],
        social_feedback: float,
        emotion_valence: float,
        world_autonomy: float,
        loop_closure: float,
        tick: int,
    ) -> None:
        self._tick_count += 1
        _ae = action_evidence

        # Signed evidence per dimension (center around 0, range ~[-1, +1])
        _evid = [
            # continuity: persistence + loop_closure (both above 0.5 = increase)
            _ae.get("persistence", 0.0) * 0.50 + (loop_closure * 2.0 - 1.0) * 0.50,
            # agency: dominance + loop_closure
            _ae.get("dominance", 0.0) * 0.45 + (loop_closure * 2.0 - 1.0) * 0.55,
            # social_groundedness: empathy + social_feedback
            _ae.get("empathy", 0.0) * 0.40 + (social_feedback * 2.0 - 1.0) * 0.60,
            # action_coherence: curiosity + persistence
            _ae.get("curiosity", 0.0) * 0.45 + _ae.get("persistence", 0.0) * 0.55,
            # emotional_stability: composure – |valence| volatility
            _ae.get("composure", 0.0) * 0.60 - abs(emotion_valence) * 0.40,
            # world_adaptability: openness + (world_autonomy centered)
            _ae.get("openness", 0.0) * 0.55 + (world_autonomy - 0.5) * 0.90,
        ]

        _prev = list(self._vec)
        for i in range(6):
            _delta = self._LR * _evid[i]
            _delta = max(-self._DRIFT_CAP, min(self._DRIFT_CAP, _delta))
            self._vec[i] = max(0.05, min(0.95, self._vec[i] + _delta))

        # Drift rate: normalized mean absolute change this tick
        _mean_ch = sum(abs(self._vec[i] - _prev[i]) for i in range(6)) / 6.0
        self.drift_rate = min(1.0, _mean_ch / max(1e-9, self._DRIFT_CAP * 0.85))

        # Inertia: EMA of stability (inverse of drift)
        self.inertia = (1 - self._INERTIA_EMA) * self.inertia + self._INERTIA_EMA * (
            1.0 - self.drift_rate
        )

        # Window drift cap enforcement every WINDOW ticks
        self._window_tick += 1
        if self._window_tick >= self._WINDOW:
            for i in range(6):
                _moved = abs(self._vec[i] - self._window_start[i])
                if _moved > self._WINDOW_DRIFT_CAP:
                    _dir = 1 if self._vec[i] > self._window_start[i] else -1
                    self._vec[i] = max(
                        0.05,
                        min(
                            0.95, self._window_start[i] + _dir * self._WINDOW_DRIFT_CAP
                        ),
                    )
            self._window_start = list(self._vec)
            self._window_tick = 0

        self.identity_vector = dict(zip(self._DIMS, self._vec))


class TemporalCoherenceField:
    """200-tick long-horizon coherence monitor.

    Records goal_mode and identity_vector per tick.  Every UPDATE_INTERVAL
    ticks recomputes three metrics over the rolling window:

      goal_switch_rate     — fraction of ticks where mode changed
      identity_oscillation — mean std-dev across PII dimensions
      contradiction_rate   — safe↔active reversals / window_size

    coherence_score [0,1]: 1 = highly stable long-term trajectory.
    Recomputed as EMA of a composite target derived from the three metrics.

    long_term_goal_bias:
      Modes that dominated (fraction > 22%) get a gentle boost (stability
      as inertia).  Rare modes (< 4%) get a mild penalty (anti-jitter).
    """

    _WINDOW_SIZE = 200
    _UPDATE_INTERVAL = 25
    _COH_EMA = 0.08

    def __init__(self) -> None:
        self._goal_hist: List[str] = []
        self._id_hist: List[Dict[str, float]] = []
        self.coherence_score: float = 1.0
        self.contradiction_rate: float = 0.0
        self.long_term_goal_bias: Dict[str, float] = {}
        self._ema_coh: float = 1.0
        self._tick_count: int = 0

    def update(self, goal_mode: str, identity_vec: Dict[str, float], tick: int) -> None:
        self._tick_count += 1
        self._goal_hist.append(goal_mode)
        self._id_hist.append(dict(identity_vec))
        if len(self._goal_hist) > self._WINDOW_SIZE:
            self._goal_hist.pop(0)
        if len(self._id_hist) > self._WINDOW_SIZE:
            self._id_hist.pop(0)

        if self._tick_count % self._UPDATE_INTERVAL != 0:
            return
        _n = len(self._goal_hist)
        if _n < 12:
            return

        # Goal switch rate
        _sw = sum(
            1 for i in range(1, _n) if self._goal_hist[i] != self._goal_hist[i - 1]
        )
        _sw_rate = _sw / max(1, _n)

        # Identity oscillation (mean std-dev per dim)
        import math as _m_tcf9

        _dims = list(identity_vec.keys())
        _osc = 0.0
        for d in _dims:
            _vs = [v.get(d, 0.5) for v in self._id_hist]
            _mean = sum(_vs) / max(1, len(_vs))
            _osc += _m_tcf9.sqrt(sum((v - _mean) ** 2 for v in _vs) / max(1, len(_vs)))
        _osc /= max(1, len(_dims))

        # Contradiction rate (safe ↔ active reversals)
        _safe = {"rest", "consolidate"}
        _active = {"execute", "explore", "search", "interact"}
        _contr = sum(
            1
            for i in range(1, _n)
            if (
                (self._goal_hist[i - 1] in _safe and self._goal_hist[i] in _active)
                or (self._goal_hist[i - 1] in _active and self._goal_hist[i] in _safe)
            )
        )
        self.contradiction_rate = _contr / max(1, _n)

        _tgt = max(
            0.0, 1.0 - _sw_rate * 0.55 - _osc * 1.30 - self.contradiction_rate * 0.15
        )
        self._ema_coh = (1 - self._COH_EMA) * self._ema_coh + self._COH_EMA * _tgt
        self.coherence_score = self._ema_coh

        # Long-term goal bias from mode distribution
        from collections import Counter as _Ctr9

        _cnt = _Ctr9(self._goal_hist)
        _total = sum(_cnt.values()) or 1
        self.long_term_goal_bias = {}
        for gm, c in _cnt.items():
            _f = c / _total
            if _f > 0.22:
                self.long_term_goal_bias[gm] = 1.0 + _f * 0.40
            elif _f < 0.04:
                self.long_term_goal_bias[gm] = max(0.55, 1.0 - (0.04 - _f) * 4.0)


class IdentityStabilityField:
    """Generates a scalar stability force from PII variance + layer divergence.

    stability_force > 0  →  STABILIZING: resist further change (volatile identity)
    stability_force < 0  →  EXPLORATION: allow more change (rigidly frozen identity)
    stability_force = 0  →  STABLE: no corrective force needed

    Derived from:
      component_variance  — mean std-dev of PII identity dimensions over 60 ticks
      pii_drift_rate      — normalized [0,1] current-tick drift from PII
      layer_divergence    — inconsistency_score from IdentityLayerStack

    Thresholds:
      INSTAB_THRESH: variance above this → generate positive (stabilizing) force
      RIGID_THRESH:  variance below this → generate negative (exploration) force

    Also broadcasts stability_regime: "unstable" | "stable" | "rigid"
    """

    _INSTAB_THRESH = 0.12
    _RIGID_THRESH = 0.020
    _FORCE_SCALE = 0.80
    _HIST_SIZE = 60
    _EMA_ALPHA = 0.06

    def __init__(self) -> None:
        self._hist: List[Dict[str, float]] = []
        self.component_variance: float = 0.0
        self.stability_force: float = 0.0
        self.stability_regime: str = "stable"
        self._ema_var: float = 0.0

    def update(
        self,
        identity_vec: Dict[str, float],
        pii_drift_rate: float,
        layer_divergence: float,
    ) -> None:
        import math as _m_isf9

        self._hist.append(dict(identity_vec))
        if len(self._hist) > self._HIST_SIZE:
            self._hist.pop(0)
        if len(self._hist) < 6:
            return

        _dims = list(identity_vec.keys())
        _vsum = 0.0
        for d in _dims:
            _vs = [v.get(d, 0.5) for v in self._hist]
            _mean = sum(_vs) / max(1, len(_vs))
            _vsum += _m_isf9.sqrt(sum((v - _mean) ** 2 for v in _vs) / max(1, len(_vs)))
        self.component_variance = _vsum / max(1, len(_dims))

        self._ema_var = (
            1 - self._EMA_ALPHA
        ) * self._ema_var + self._EMA_ALPHA * self.component_variance

        _combined = (
            self._ema_var * 0.60 + layer_divergence * 0.25 + pii_drift_rate * 0.15
        )

        if _combined > self._INSTAB_THRESH:
            self.stability_force = min(
                1.0,
                (_combined - self._INSTAB_THRESH)
                / (1.0 - self._INSTAB_THRESH)
                * self._FORCE_SCALE,
            )
            self.stability_regime = "unstable"
        elif _combined < self._RIGID_THRESH:
            self.stability_force = -min(
                0.40, (self._RIGID_THRESH - _combined) / self._RIGID_THRESH * 0.40
            )
            self.stability_regime = "rigid"
        else:
            self.stability_force = 0.0
            self.stability_regime = "stable"


class ConflictResolutionEngine:
    """Resolves inter-subsystem proposal conflicts — zero unresolved conflicts per tick.

    For each goal mode that appears in ≥2 proposals:
      If max(values) − min(values) > CONFLICT_THRESH:
        → Conflict detected
        → Resolution: highest-priority source wins (by PRIORITY_ORDER);
          fallback: stability-weighted average
        → All proposal entries are soft-pulled toward the resolved value
          (RESOLUTION_LR blend), mutating proposals in place before UCC sees them.

    This ensures UCC receives pre-reconciled inputs rather than raw conflicts.

    Resolution never discards information — it blends proposals toward agreement,
    so dominant sources still have more influence than minority sources.

    Outputs:
      resolutions_this_tick  List[str]
      total_resolutions      int        (cumulative)
    """

    _CONFLICT_THRESH = 0.32
    _RESOLUTION_LR = 0.28
    _PRIORITY_ORDER = (
        "constraint_core",
        "temporal",
        "personality",
        "action_trace",
        "social",
    )

    def __init__(self) -> None:
        self.resolutions_this_tick: List[str] = []
        self.total_resolutions: int = 0

    def resolve(
        self,
        proposals: Dict[str, Dict[str, float]],
        identity_vec: Dict[str, float],
        stability_force: float,
        self_model: object,
        stream: List[str],
    ) -> List[str]:
        msgs: List[str] = []
        self.resolutions_this_tick = []

        _all_modes: set = set()
        for _p in proposals.values():
            _all_modes.update(_p.keys())

        for gm in _all_modes:
            _entries = [(src, p[gm]) for src, p in proposals.items() if gm in p]
            if len(_entries) < 2:
                continue
            _vals = [v for _, v in _entries]
            if max(_vals) - min(_vals) <= self._CONFLICT_THRESH:
                continue

            # Find resolved value by priority order
            _resolved: Optional[float] = None
            for _prio in self._PRIORITY_ORDER:
                for src, val in _entries:
                    if _prio in src:
                        _resolved = val
                        break
                if _resolved is not None:
                    break
            if _resolved is None:
                # Fallback: stability-biased center
                _center = sum(_vals) / len(_vals)
                _resolved = _center * (1.0 + stability_force * 0.15)

            # Soft-pull all entries toward resolved value
            for src in proposals:
                if gm in proposals[src]:
                    _old = proposals[src][gm]
                    proposals[src][gm] = _old + self._RESOLUTION_LR * (_resolved - _old)

            self.resolutions_this_tick.append(
                f"mode={gm} range={max(_vals) - min(_vals):.2f}→{_resolved:.2f}"
            )
            self.total_resolutions += 1

        if self.resolutions_this_tick:
            msgs.append(
                f"[CONFLICT-RES n={len(self.resolutions_this_tick)} "
                f"total={self.total_resolutions}] "
                + "; ".join(self.resolutions_this_tick[:2])
            )
        return msgs


# ─────────────────────────────────────────────────────────────────────────────
# Phase 10: Autonomous Life Dynamics Layer (SAD-Layer)
# ─────────────────────────────────────────────────────────────────────────────


class HomeostaticSurvivalCore:
    """Existential pressure system — four vital dimensions with hard floor thresholds.

    Vital dimensions:
      energy_stability      — body energy reserve [0,1]
      identity_continuity   — PII inertia [0,1]
      world_access          — loop closure × sensor FoV [0,1]
      social_viability      — SocialSCE social_feedback [0,1]

    Each dimension has:
      CRITICAL_FLOOR  — below this, full existential override
      WARNING_BAND    — floor to floor+0.15, partial override active
      pressure        — 0.0 (healthy) … 1.0 (critical) per dimension
      recovery_target — floor + 0.25

    existential_pressure [0,1]: max pressure across all dimensions.
    When existential_pressure > CRISIS_THRESH:
      • emits goal_override dict forcing survival modes
      • emits stream message every REPORT_INTERVAL ticks
    """

    _FLOORS = {
        "energy_stability": 0.18,
        "identity_continuity": 0.25,
        "world_access": 0.15,
        "social_viability": 0.12,
    }
    _WARN_BAND = 0.15
    _CRISIS_THRESH = 0.55
    _REPORT_INTERVAL = 30

    def __init__(self) -> None:
        self.pressures: Dict[str, float] = {k: 0.0 for k in self._FLOORS}
        self.existential_pressure: float = 0.0
        self.in_crisis: bool = False
        self.goal_override: Dict[str, float] = {}
        self._tick_count: int = 0

    def update(
        self,
        energy: float,
        identity_inertia: float,
        loop_closure: float,
        sensor_fov: float,
        social_fb: float,
        stream: List[str],
    ) -> None:
        self._tick_count += 1
        _vals = {
            "energy_stability": float(energy),
            "identity_continuity": float(identity_inertia),
            "world_access": float(loop_closure) * float(sensor_fov),
            "social_viability": float(social_fb),
        }

        for k, floor in self._FLOORS.items():
            _v = _vals[k]
            if _v < floor:
                self.pressures[k] = min(1.0, 1.0 - _v / max(0.001, floor))
            elif _v < floor + self._WARN_BAND:
                self.pressures[k] = (
                    (floor + self._WARN_BAND - _v) / self._WARN_BAND * 0.45
                )
            else:
                self.pressures[k] = max(0.0, self.pressures[k] * 0.80)

        self.existential_pressure = max(self.pressures.values())
        self.in_crisis = self.existential_pressure > self._CRISIS_THRESH

        if self.in_crisis:
            # Find dominant pressure dimension
            _dom = max(self.pressures, key=self.pressures.get)
            _p = self.pressures[_dom]
            # Build survival override
            self.goal_override = {}
            if _dom == "energy_stability":
                self.goal_override = {
                    "rest": 2.60,
                    "consolidate": 1.80,
                    "explore": 0.18,
                    "execute": 0.12,
                }
            elif _dom == "identity_continuity":
                self.goal_override = {
                    "consolidate": 2.20,
                    "rest": 1.60,
                    "execute": 0.25,
                    "interact": 0.40,
                }
            elif _dom == "world_access":
                self.goal_override = {
                    "search": 1.80,
                    "explore": 1.50,
                    "rest": 0.40,
                    "execute": 0.30,
                }
            elif _dom == "social_viability":
                self.goal_override = {
                    "respond": 2.00,
                    "interact": 1.70,
                    "execute": 0.35,
                    "explore": 0.55,
                }

            if self._tick_count % self._REPORT_INTERVAL == 0:
                stream.append(
                    f"[HSC CRISIS dim={_dom} "
                    f"pressure={_p:.2f} "
                    f"ep={self.existential_pressure:.2f}]"
                )
        else:
            self.goal_override = {}


class GoalEvolutionEngine:
    """Evolutionary goal pool: goals are born, mutate, recombine, and die.

    Pool: up to MAX_GOALS goal-genes, each a dict:
      id        — unique int
      mode      — one of the base goal modes
      fitness   — EMA of outcome scores [0,1]
      age       — ticks alive
      mutations — number of mutations so far
      weight    — current selection weight

    Life cycle each tick:
      1. UPDATE fitness of goals that matched last goal_mode
      2. KILL goals below DEATH_THRESH for ≥ DEATH_PATIENCE ticks
      3. MUTATE fittest goal occasionally (mutation_interval)
      4. RECOMBINE two mid-fitness goals occasionally
      5. BIRTH new goal when pool shrinks below MIN_GOALS
      6. Compute selection_weights → goal_pool_bias (mode → weight)

    goal_pool_bias: strongest-fitness modes get multiplier > 1.0.
    genome_summary: human-readable pool description.
    """

    _BASE_MODES = (
        "explore",
        "consolidate",
        "rest",
        "execute",
        "interact",
        "respond",
        "search",
    )
    _MAX_GOALS = 14
    _MIN_GOALS = 5
    _FITNESS_EMA = 0.08
    _DEATH_THRESH = 0.15
    _DEATH_PATIENCE = 80
    _MUTATION_INTERVAL = 55
    _RECOMB_INTERVAL = 120

    def __init__(self) -> None:
        self._pool: List[Dict] = []
        self._next_id: int = 0
        self._tick_count: int = 0
        self.goal_pool_bias: Dict[str, float] = {}
        self.genome_summary: str = "Pool initializing."
        self._seed_pool()

    def _seed_pool(self) -> None:
        for m in self._BASE_MODES:
            self._pool.append(self._new_gene(m, fitness=0.50))

    def _new_gene(self, mode: str, fitness: float = 0.45) -> Dict:
        _g = {
            "id": self._next_id,
            "mode": mode,
            "fitness": fitness,
            "age": 0,
            "mutations": 0,
            "low_ticks": 0,
            "weight": 1.0,
        }
        self._next_id += 1
        return _g

    def _mutate(self, gene: Dict, rng: float) -> Dict:
        import random as _rnd

        _new_mode = _rnd.choice(self._BASE_MODES)
        _nf = max(0.15, min(0.85, gene["fitness"] + (rng - 0.5) * 0.22))
        _g2 = dict(gene)
        _g2["id"] = self._next_id
        _g2["mode"] = _new_mode
        _g2["fitness"] = _nf
        _g2["mutations"] = gene["mutations"] + 1
        _g2["age"] = 0
        _g2["low_ticks"] = 0
        self._next_id += 1
        return _g2

    def _recombine(self, a: Dict, b: Dict) -> Dict:
        import random as _rnd

        _mode = a["mode"] if a["fitness"] >= b["fitness"] else b["mode"]
        _fit = (a["fitness"] + b["fitness"]) / 2.0 + _rnd.gauss(0, 0.04)
        _fit = max(0.10, min(0.90, _fit))
        return self._new_gene(_mode, _fit)

    def update(self, last_goal_mode: str, outcome_score: float, tick: int) -> None:
        self._tick_count += 1
        import math as _m_gee

        _rng = abs(_m_gee.sin(tick * 2.71828 + outcome_score * 6.283))

        # Update fitness for matching goals
        for g in self._pool:
            g["age"] += 1
            if g["mode"] == last_goal_mode:
                g["fitness"] = (1 - self._FITNESS_EMA) * g[
                    "fitness"
                ] + self._FITNESS_EMA * float(outcome_score)
            if g["fitness"] < self._DEATH_THRESH:
                g["low_ticks"] = g.get("low_ticks", 0) + 1
            else:
                g["low_ticks"] = 0

        # Kill unfit goals
        _killed = [
            g
            for g in self._pool
            if g["fitness"] < self._DEATH_THRESH
            and g.get("low_ticks", 0) >= self._DEATH_PATIENCE
        ]
        for g in _killed:
            self._pool.remove(g)

        # Mutate fittest
        if self._tick_count % self._MUTATION_INTERVAL == 0 and self._pool:
            _fittest = max(self._pool, key=lambda g: g["fitness"])
            _mut = self._mutate(_fittest, _rng)
            if len(self._pool) < self._MAX_GOALS:
                self._pool.append(_mut)

        # Recombine two mid-range goals
        if self._tick_count % self._RECOMB_INTERVAL == 0 and len(self._pool) >= 4:
            _srt = sorted(self._pool, key=lambda g: g["fitness"], reverse=True)
            _a, _b = _srt[1], _srt[2]  # second and third fittest
            _child = self._recombine(_a, _b)
            if len(self._pool) < self._MAX_GOALS:
                self._pool.append(_child)

        # Birth if pool too small
        while len(self._pool) < self._MIN_GOALS:
            import random as _rnd2

            self._pool.append(self._new_gene(_rnd2.choice(self._BASE_MODES)))

        # Compute selection weights → goal_pool_bias
        _total_fit = sum(g["fitness"] for g in self._pool) or 1.0
        _mode_bias: Dict[str, float] = {}
        for g in self._pool:
            _w = g["fitness"] / _total_fit * len(self._pool)
            g["weight"] = _w
            _prev = _mode_bias.get(g["mode"], 0.0)
            _mode_bias[g["mode"]] = max(_prev, _w)

        # Normalize to multipliers around 1.0
        _mean_b = sum(_mode_bias.values()) / max(1, len(_mode_bias))
        self.goal_pool_bias = {
            m: max(0.35, min(2.20, v / max(0.01, _mean_b)))
            for m, v in _mode_bias.items()
        }

        # Genome summary
        if self._tick_count % 100 == 0:
            _top = sorted(self._pool, key=lambda g: g["fitness"], reverse=True)[:3]
            self.genome_summary = f"Pool n={len(self._pool)}; " + "; ".join(
                f"{g['mode']}(fit={g['fitness']:.2f},age={g['age']})" for g in _top
            )


class HorizonDominanceController:
    """Multi-scale horizon arbiter: long-term coherence overrides short-term reward.

    Three rolling windows:
      SHORT    10–50 ticks   — immediate outcome EMA
      MID      50–500 ticks  — session-level trend EMA
      LONG     500–5000 tick — lifetime trend EMA (slow)

    Each window tracks mean outcome score.
    Horizon bias: if SHORT > LONG + DIVERGE_THRESH, short-term „inflation" detected
    → compress short-term goal advantage (apply penalty to high-variance modes).
    If LONG is significantly lagging SHORT over LONG_WINDOW ticks:
    → promote safe/stable modes via horizon_goal_bias.

    horizon_health [0,1]: integrated cross-horizon agreement.
    long_term_score: the slowest EMA — most stable estimate of system well-being.
    horizon_goal_bias: Dict[str,float] — multipliers for _evaluate_goal().
    """

    _SHORT_EMA = 0.20
    _MID_EMA = 0.020
    _LONG_EMA = 0.002
    _DIVERGE_THRESH = 0.18
    _HEALTH_EMA = 0.05

    def __init__(self) -> None:
        self.short_score: float = 0.50
        self.mid_score: float = 0.50
        self.long_score: float = 0.50
        self.horizon_health: float = 1.0
        self.horizon_goal_bias: Dict[str, float] = {}
        self._tick_count: int = 0

    def update(self, outcome_score: float, tick: int) -> None:
        self._tick_count += 1
        _s = max(0.0, min(1.0, float(outcome_score)))

        self.short_score = (
            1 - self._SHORT_EMA
        ) * self.short_score + self._SHORT_EMA * _s
        self.mid_score = (1 - self._MID_EMA) * self.mid_score + self._MID_EMA * _s
        self.long_score = (1 - self._LONG_EMA) * self.long_score + self._LONG_EMA * _s

        _cross_agreement = 1.0 - (
            abs(self.short_score - self.mid_score) * 0.40
            + abs(self.mid_score - self.long_score) * 0.60
        )
        self.horizon_health = (
            1 - self._HEALTH_EMA
        ) * self.horizon_health + self._HEALTH_EMA * max(0.0, _cross_agreement)

        # Short-term inflation: short well above long → compress volatile modes
        _inflation = self.short_score - self.long_score
        self.horizon_goal_bias = {}
        if _inflation > self._DIVERGE_THRESH:
            _pen = min(0.50, (_inflation - self._DIVERGE_THRESH) * 1.40)
            for m in ("execute", "interact", "explore", "search"):
                self.horizon_goal_bias[m] = max(0.40, 1.0 - _pen)
            for m in ("consolidate", "rest"):
                self.horizon_goal_bias[m] = min(1.80, 1.0 + _pen * 0.70)
        # Long-term lag: long well below mid → gently push toward safe rebuilding
        elif self.mid_score - self.long_score > self._DIVERGE_THRESH * 0.70:
            for m in ("consolidate", "rest"):
                self.horizon_goal_bias[m] = 1.25
            for m in ("execute", "explore"):
                self.horizon_goal_bias[m] = 0.75


class EntropicDriftLayer:
    """Natural entropy drives — no system stays stable without active cost.

    Three decay processes, applied each tick:

    1. Memory entropy:
       Gradually reduces salience of all concepts by MEMORY_DECAY_RATE.
       Simulates biological forgetting — old information cheapens.

    2. Goal entropy:
       Each base goal mode accrues a small entropic cost each tick it
       is NOT selected.  Cost resets on selection.  After GOAL_ENTROPY_PATIENCE
       ticks without selection, that mode is penalized in goal_entropy_bias.

    3. Identity entropy:
       PII identity dimensions drift toward 0.50 (neutral) at IDENT_DECAY.
       Resisted by active behavioral signals — cost of maintaining identity.

    Outputs:
      entropy_level        float [0,1]   overall entropy this tick
      memory_decay_delta   float         how much mean salience dropped
      goal_entropy_bias    Dict[str,float]  penalty for stale goal modes
      ident_entropy_delta  float         drift applied to PII dims this tick
    """

    _MEMORY_DECAY_RATE = 0.0012
    _GOAL_ENTROPY_PATIENCE = 180  # ticks before goal goes stale
    _GOAL_ENTROPY_PEN = 0.22
    _IDENT_DECAY = 0.0003
    _ENTROPY_EMA = 0.04

    def __init__(self) -> None:
        self.entropy_level: float = 0.0
        self.memory_decay_delta: float = 0.0
        self.goal_entropy_bias: Dict[str, float] = {}
        self.ident_entropy_delta: float = self._IDENT_DECAY
        self._goal_stale: Dict[str, int] = {}
        self._ema_ent: float = 0.0
        self._tick_count: int = 0

    def update(
        self,
        concepts: set,
        concept_salience: Dict[str, float],
        last_goal_mode: str,
        identity_integrator: "PersistentIdentityIntegrator",
        tick: int,
    ) -> List[str]:
        msgs: List[str] = []
        self._tick_count += 1

        # 1. Memory entropy — reduce salience of all live concepts
        _total_sal_before = sum(concept_salience.values()) or 1.0
        for c in list(concept_salience.keys()):
            if concept_salience[c] > 0.01:
                concept_salience[c] = max(
                    0.0, concept_salience[c] * (1.0 - self._MEMORY_DECAY_RATE)
                )
        _total_sal_after = sum(concept_salience.values()) or 1.0
        self.memory_decay_delta = (_total_sal_before - _total_sal_after) / max(
            0.001, _total_sal_before
        )

        # 2. Goal entropy — track stale modes
        _base_modes = (
            "explore",
            "consolidate",
            "rest",
            "execute",
            "interact",
            "respond",
            "search",
        )
        for m in _base_modes:
            if m == last_goal_mode:
                self._goal_stale[m] = 0
            else:
                self._goal_stale[m] = self._goal_stale.get(m, 0) + 1
        self.goal_entropy_bias = {}
        for m, age in self._goal_stale.items():
            if age > self._GOAL_ENTROPY_PATIENCE:
                _pen = min(
                    0.55,
                    (age - self._GOAL_ENTROPY_PATIENCE)
                    / self._GOAL_ENTROPY_PATIENCE
                    * self._GOAL_ENTROPY_PEN,
                )
                self.goal_entropy_bias[m] = max(0.35, 1.0 - _pen)

        # 3. Identity entropy — drift PII dimensions toward 0.50
        _ii = identity_integrator
        for i in range(len(_ii._vec)):
            _ii._vec[i] = _ii._vec[i] + self._IDENT_DECAY * (0.50 - _ii._vec[i])
        self.ident_entropy_delta = self._IDENT_DECAY

        # Overall entropy
        _gesum = (
            sum(1.0 - v for v in self.goal_entropy_bias.values())
            / max(1, len(self.goal_entropy_bias))
            if self.goal_entropy_bias
            else 0.0
        )
        _tgt = min(
            1.0,
            self.memory_decay_delta * 0.40
            + _gesum * 0.40
            + self.ident_entropy_delta * 80.0 * 0.20,
        )
        self._ema_ent = (
            1 - self._ENTROPY_EMA
        ) * self._ema_ent + self._ENTROPY_EMA * _tgt
        self.entropy_level = self._ema_ent

        if self.entropy_level > 0.65 and self._tick_count % 100 == 0:
            msgs.append(
                f"[ENTROPIC-DRIFT lvl={self.entropy_level:.2f} "
                f"mem_decay={self.memory_decay_delta:.4f} "
                f"stale_goals={len(self.goal_entropy_bias)}]"
            )
        return msgs


class ControlledSelfModification:
    """Rule-bounded parameter self-tuning — evolves system sensitivities within guards.

    The system may adjust a small set of mutable parameters once per
    MODIFICATION_INTERVAL ticks, IF:
      • HSC.existential_pressure < GUARD_EP_MAX
      • ISF.stability_force < GUARD_SF_MAX (identity not in crisis)
      • HDC.horizon_health > GUARD_HH_MIN

    Mutable parameters:
      sensor_noise_scale    float [0.5, 1.5]  EmbodiedSensorField noise multiplier
      personality_lr_scale  float [0.5, 2.0]  PersonalityCore LR multiplier
      social_mirror_scale   float [0.2, 1.0]  SocialConsistencyEngine MIRROR_SCALE
      pii_drift_cap_scale   float [0.5, 1.5]  PersistentIdentityIntegrator drift cap

    Each candidate adjustment is forecast via delta_forecast (simplified):
      if adjusting toward entropy-reducing direction and long-term > short-term:
        adjustment accepted
      else: rejected

    Outputs:
      modifications_applied  List[str]
      total_modifications    int
      param_state            Dict[str, float]
    """

    _GUARD_EP_MAX = 0.38
    _GUARD_SF_MAX = 0.70
    _GUARD_HH_MIN = 0.42
    _MOD_INTERVAL = 200
    _STEP = 0.04  # step size per modification

    def __init__(self) -> None:
        self.param_state: Dict[str, float] = {
            "sensor_noise_scale": 1.0,
            "personality_lr_scale": 1.0,
            "social_mirror_scale": 1.0,
            "pii_drift_cap_scale": 1.0,
        }
        self._bounds = {
            "sensor_noise_scale": (0.50, 1.50),
            "personality_lr_scale": (0.50, 2.00),
            "social_mirror_scale": (0.20, 1.00),
            "pii_drift_cap_scale": (0.50, 1.50),
        }
        self.modifications_applied: List[str] = []
        self.total_modifications: int = 0
        self._tick_count: int = 0

    def update(
        self,
        existential_pressure: float,
        stability_force: float,
        horizon_health: float,
        horizon_controller: "HorizonDominanceController",
        entropy_level: float,
        stream: List[str],
    ) -> None:
        self._tick_count += 1
        self.modifications_applied = []

        if self._tick_count % self._MOD_INTERVAL != 0:
            return

        # Guard checks
        if existential_pressure > self._GUARD_EP_MAX:
            return
        if stability_force > self._GUARD_SF_MAX:
            return
        if horizon_health < self._GUARD_HH_MIN:
            return

        # Derive adjustment directions from system state
        _hc = horizon_controller
        _inflation = _hc.short_score - _hc.long_score

        # High entropy → reduce noise sensitivity to conserve resources
        _dirs: Dict[str, float] = {}
        if entropy_level > 0.50:
            _dirs["sensor_noise_scale"] = -self._STEP  # reduce noise sensitivity
            _dirs["personality_lr_scale"] = -self._STEP  # slow down personality
        elif entropy_level < 0.20:
            _dirs["personality_lr_scale"] = +self._STEP  # speed up learning
            _dirs["pii_drift_cap_scale"] = +self._STEP  # allow more identity flex

        # Short-term inflation → tighten social mirroring
        if _inflation > 0.15:
            _dirs["social_mirror_scale"] = -self._STEP
        elif _inflation < -0.10:
            _dirs["social_mirror_scale"] = +self._STEP

        # Apply with bound check
        for param, step in _dirs.items():
            _lo, _hi = self._bounds[param]
            _new = max(_lo, min(_hi, self.param_state[param] + step))
            if _new != self.param_state[param]:
                _old = self.param_state[param]
                self.param_state[param] = _new
                self.modifications_applied.append(f"{param}: {_old:.2f}→{_new:.2f}")
                self.total_modifications += 1

        if self.modifications_applied:
            stream.append(
                f"[CSM tick={self._tick_count} "
                f"mods={self.modifications_applied} "
                f"total={self.total_modifications}]"
            )

    def apply_scales(
        self,
        personality: "PersonalityCore",
        sensor_field: "EmbodiedSensorField",
        social_sce: "SocialConsistencyEngine",
        identity_integrator: "PersistentIdentityIntegrator",
    ) -> None:
        """Push current param_state into live subsystem attributes."""
        # PersonalityCore LR scale
        personality._LR = 0.0008 * self.param_state["personality_lr_scale"]
        # SocialConsistencyEngine mirror scale
        social_sce._MIRROR_SCALE = 0.55 * self.param_state["social_mirror_scale"]
        # PII drift cap scale
        identity_integrator._DRIFT_CAP = (
            0.0018 * self.param_state["pii_drift_cap_scale"]
        )
        # EmbodiedSensorField noise scale (applied at noise_level level)
        sensor_field._BASE_NOISE = min(
            0.35, 0.07 * self.param_state["sensor_noise_scale"]
        )


class AdaptiveIdentityEvolution:
    """Identity as a living, reorganizing process — not a fixed stabilized state.

    Identity grows, compresses, and reorganizes in response to:
      - sustained behavioral patterns (SelfAsActionTrace)
      - environmental pressure (DynamicWorldReactor / entropy)
      - social resonance (PhysioSocialCoupler)

    Three modes (current_regime):
      GROWTH       — identity expanding, acquiring new coherent dimensions
      STABLE       — drifting within normal range
      COMPRESSION  — shedding incoherent dimensions under pressure

    Mode transitions:
      → GROWTH:     action_coherence > 0.65 for GROWTH_PATIENCE ticks
      → COMPRESSION:entropy_level > 0.60 OR existential_pressure > 0.45
      → STABLE:     otherwise

    Outputs:
      current_regime         str
      reorganization_delta   float  signed drift applied to PII this tick
      evolution_narrative    str    one-sentence status
      system_learning_signal Dict[str,float]  system-level meta-signal
    """

    _GROWTH_PATIENCE = 60
    _GROWTH_RATE = 0.00090
    _COMPRESSION_RATE = 0.00120
    _SYS_LEARN_EMA = 0.03

    def __init__(self) -> None:
        self.current_regime: str = "STABLE"
        self.reorganization_delta: float = 0.0
        self.evolution_narrative: str = "Identity forming."
        self.system_learning_signal: Dict[str, float] = {}
        self._growth_ticks: int = 0
        self._tick_count: int = 0
        self._learn_ema: Dict[str, float] = {
            "action_coherence": 0.50,
            "world_coupling": 0.50,
            "social_resonance": 0.50,
            "entropy_cost": 0.20,
        }

    def update(
        self,
        action_coherence: float,
        entropy_level: float,
        existential_pressure: float,
        social_fb: float,
        world_coupling: float,
        identity_integrator: "PersistentIdentityIntegrator",
        tick: int,
    ) -> List[str]:
        msgs: List[str] = []
        self._tick_count += 1

        # Regime determination
        if entropy_level > 0.60 or existential_pressure > 0.45:
            _new_regime = "COMPRESSION"
            self._growth_ticks = 0
        elif action_coherence > 0.65:
            self._growth_ticks += 1
            _new_regime = (
                "GROWTH" if self._growth_ticks >= self._GROWTH_PATIENCE else "STABLE"
            )
        else:
            self._growth_ticks = max(0, self._growth_ticks - 1)
            _new_regime = "STABLE"

        if _new_regime != self.current_regime:
            msgs.append(f"[AIE regime {self.current_regime}→{_new_regime}]")
            self.current_regime = _new_regime

        # Apply reorganization to PII identity vector
        _ii = identity_integrator
        self.reorganization_delta = 0.0
        if self.current_regime == "GROWTH":
            # Amplify dominant dimensions (above 0.55)
            for i in range(len(_ii._vec)):
                if _ii._vec[i] > 0.55:
                    _ii._vec[i] = min(0.95, _ii._vec[i] + self._GROWTH_RATE)
                    self.reorganization_delta += self._GROWTH_RATE
        elif self.current_regime == "COMPRESSION":
            # Compress weak dimensions (below 0.45) toward 0.50
            for i in range(len(_ii._vec)):
                if _ii._vec[i] < 0.45:
                    _delta = self._COMPRESSION_RATE * (0.50 - _ii._vec[i])
                    _ii._vec[i] = min(0.95, max(0.05, _ii._vec[i] + _delta))
                    self.reorganization_delta -= abs(_delta)

        # System-level learning signal
        for k, v in {
            "action_coherence": action_coherence,
            "world_coupling": world_coupling,
            "social_resonance": social_fb,
            "entropy_cost": entropy_level,
        }.items():
            self._learn_ema[k] = (1 - self._SYS_LEARN_EMA) * self._learn_ema[
                k
            ] + self._SYS_LEARN_EMA * float(v)
        self.system_learning_signal = dict(self._learn_ema)

        # Narrative update
        if self._tick_count % 200 == 0:
            _ac_str = f"{action_coherence:.2f}"
            _ep_str = f"{existential_pressure:.2f}"
            self.evolution_narrative = (
                f"Regime: {self.current_regime}. "
                f"Coherence={_ac_str}; pressure={_ep_str}; "
                f"delta={self.reorganization_delta:+.5f}."
            )
        return msgs


