class FailureDetectionCore:
    """Systemic failure detector — watches 5 signals for collapse onset.

    Signals (each evaluated as bool: is_critical?):
      identity_fragmentation  — ISF component_variance > FRAG_THRESH
      entropy_high            — EntropicDriftLayer.entropy_level > ENT_THRESH
      goal_churn              — GoalStabilityRegulator.churn_rate > CHURN_THRESH
      action_failure          — action_success_ema < ACT_FAIL_THRESH
      horizon_unhealthy       — HDC.horizon_health < HORIZ_THRESH

    State machine:
      critical_count ≥ 3 → state = "pre_collapse"
      critical_count ≥ 4 → state = "collapse"
      critical_count ≤ 1 → state = "healthy"
      otherwise          → state = "warning"

    EMA of critical_count → instability_index [0,1].
    state is published; RecoveryProtocolEngine reads it.
    """

    _FRAG_THRESH = 0.14
    _ENT_THRESH = 0.62
    _CHURN_THRESH = 0.38
    _ACT_FAIL_THRESH = 0.30
    _HORIZ_THRESH = 0.38
    _IDX_EMA = 0.07
    _REPORT_INTERVAL = 40

    def __init__(self) -> None:
        self.state: str = "healthy"
        self.critical_count: int = 0
        self.instability_index: float = 0.0
        self._ema_crit: float = 0.0
        self._tick_count: int = 0

    def update(
        self,
        identity_fragmentation: float,
        entropy_level: float,
        goal_churn_rate: float,
        action_success_ema: float,
        horizon_health: float,
        stream: List[str],
    ) -> None:
        self._tick_count += 1

        _flags = [
            identity_fragmentation > self._FRAG_THRESH,
            entropy_level > self._ENT_THRESH,
            goal_churn_rate > self._CHURN_THRESH,
            action_success_ema < self._ACT_FAIL_THRESH,
            horizon_health < self._HORIZ_THRESH,
        ]
        self.critical_count = sum(_flags)
        self._ema_crit = (1 - self._IDX_EMA) * self._ema_crit + self._IDX_EMA * (
            self.critical_count / 5.0
        )
        self.instability_index = self._ema_crit

        _prev = self.state
        if self.critical_count >= 4:
            self.state = "collapse"
        elif self.critical_count >= 3:
            self.state = "pre_collapse"
        elif self.critical_count >= 2:
            self.state = "warning"
        else:
            self.state = "healthy"

        if self.state != _prev or (
            self.state != "healthy" and self._tick_count % self._REPORT_INTERVAL == 0
        ):
            stream.append(
                f"[FDS state={self.state} n_crit={self.critical_count} "
                f"idx={self.instability_index:.2f} "
                f"flags=frag:{_flags[0]},ent:{_flags[1]},"
                f"churn:{_flags[2]},act:{_flags[3]},hor:{_flags[4]}]"
            )


class RecoveryProtocolEngine:
    """Controlled recovery on pre-collapse and collapse — no full system reset.

    Pre-collapse protocol:
      • Goal restrictions: only rest / consolidate / respond allowed at full weight
      • All other modes heavily penalized
      • Sensor noise floor capped
      • Identity drift frozen (PII drift cap → 0)

    Collapse protocol (subset of pre-collapse, plus):
      • Goal pool trimmed to top-3 fitness genes in GEE
      • Identity vector soft-pulled toward last saved anchor
      • Entropic drift rate halved temporarily

    Recovery is released when FDS.state returns to "warning" or better for
    RECOVERY_HOLD ticks.

    active:           bool — protocol active this tick
    recovery_goal_override: Dict[str,float]
    """

    _RECOVERY_HOLD = 25  # ticks in non-critical state before releasing
    _NOISE_CAP = 0.12

    def __init__(self) -> None:
        self.active: bool = False
        self.recovery_goal_override: Dict[str, float] = {}
        self._hold_counter: int = 0
        self._collapse_hold_counter: int = 0
        self._in_collapse: bool = False

    def update(
        self,
        fds_state: str,
        gee: "GoalEvolutionEngine",
        identity_anchor: "IdentityAnchorField",
        identity_integrator: "PersistentIdentityIntegrator",
        entropic_drift: "EntropicDriftLayer",
        sensor_field: "EmbodiedSensorField",
        stream: List[str],
    ) -> None:

        _is_critical = fds_state in ("pre_collapse", "collapse")

        if not _is_critical:
            self._hold_counter += 1
            if self._hold_counter >= self._RECOVERY_HOLD:
                self.active = False
                self.recovery_goal_override = {}
                self._in_collapse = False
                self._hold_counter = 0
            return

        self._hold_counter = 0
        self.active = True

        # Pre-collapse: restrict goal space
        self.recovery_goal_override = {
            "rest": 2.50,
            "consolidate": 2.00,
            "respond": 1.20,
            "explore": 0.18,
            "execute": 0.14,
            "search": 0.20,
            "interact": 0.45,
        }

        # Cap sensor noise
        sensor_field._BASE_NOISE = min(sensor_field._BASE_NOISE, self._NOISE_CAP)

        # Freeze PII drift
        identity_integrator._DRIFT_CAP = 0.0

        if fds_state == "collapse":
            self._collapse_hold_counter += 1
            if not self._in_collapse:
                stream.append("[RECOVERY collapse-protocol activated]")
                self._in_collapse = True

            # Trim GEE pool to top-3 by fitness
            if len(gee._pool) > 3:
                _srt = sorted(gee._pool, key=lambda g: g["fitness"], reverse=True)
                gee._pool = _srt[:3]

            # Pull identity toward anchor
            _anchor = identity_anchor.retrieve_best()
            if _anchor is not None:
                _rate = 0.08
                for i in range(len(identity_integrator._vec)):
                    _dim = PersistentIdentityIntegrator._DIMS[i]
                    _anch_val = _anchor.get(_dim, 0.60)
                    identity_integrator._vec[i] = identity_integrator._vec[
                        i
                    ] + _rate * (_anch_val - identity_integrator._vec[i])
                stream.append(
                    f"[RECOVERY anchor-pull applied "
                    f"hold={self._collapse_hold_counter}]"
                )

            # Halve entropic drift temporarily
            entropic_drift._MEMORY_DECAY_RATE *= 0.50
            entropic_drift._IDENT_DECAY *= 0.50
        else:
            # Restore entropic rates after pre-collapse (no collapse)
            entropic_drift._MEMORY_DECAY_RATE = min(
                0.0012, entropic_drift._MEMORY_DECAY_RATE * 1.05
            )
            entropic_drift._IDENT_DECAY = min(
                0.0003, entropic_drift._IDENT_DECAY * 1.05
            )


class IdentityAnchorField:
    """Snapshots of stable identity states — fallback on collapse.

    An anchor is saved when:
      • coherence_score > ANCHOR_COH_MIN
      • entropy_level < ANCHOR_ENT_MAX
      • goal held for > ANCHOR_CHAIN_MIN consecutive ticks

    Each anchor stores:
      identity_vec:  Dict[str, float]  — PII snapshot
      coherence:     float
      entropy:       float
      tick:          int
      weight:        float — higher = more stable candidate

    Max BUFFER_SIZE anchors retained (oldest weak ones evicted).
    retrieve_best() returns highest-weight anchor, or None.
    """

    _BUFFER_SIZE = 12
    _ANCHOR_COH_MIN = 0.68
    _ANCHOR_ENT_MAX = 0.30
    _ANCHOR_CHAIN_MIN = 20

    def __init__(self) -> None:
        self._anchors: List[Dict] = []
        self.anchor_count: int = 0

    def try_save(
        self,
        identity_vec: Dict[str, float],
        coherence: float,
        entropy: float,
        goal_chain_len: int,
        tick: int,
    ) -> bool:
        if (
            coherence < self._ANCHOR_COH_MIN
            or entropy > self._ANCHOR_ENT_MAX
            or goal_chain_len < self._ANCHOR_CHAIN_MIN
        ):
            return False
        _weight = coherence * (1.0 - entropy) * min(1.0, goal_chain_len / 80.0)
        self._anchors.append(
            {
                "identity_vec": dict(identity_vec),
                "coherence": coherence,
                "entropy": entropy,
                "tick": tick,
                "weight": _weight,
            }
        )
        self.anchor_count += 1
        if len(self._anchors) > self._BUFFER_SIZE:
            # Evict lowest-weight anchor
            _min_idx = min(
                range(len(self._anchors)), key=lambda i: self._anchors[i]["weight"]
            )
            self._anchors.pop(_min_idx)
        return True

    def retrieve_best(self) -> Optional[Dict[str, float]]:
        if not self._anchors:
            return None
        _best = max(self._anchors, key=lambda a: a["weight"])
        return _best["identity_vec"]


class PersonalityConsolidator:
    """Reinforces stable behavioral traits as persistent character biases.

    Observes PersonalityCore trait vector over WINDOW ticks.
    Detects stable dimensions (low variance over window).
    Reinforces stable dims: adds a small persistent bias (consolidated_bias)
    that is added to PersonalityCore evidence on each tick — making the
    stable trait resistant to short-term perturbation.

    consolidated_bias: Dict[str, float] — per-trait additive evidence bias.
    Bias strength is capped at MAX_BIAS and decays slowly when the trait
    becomes unstable again (variance rises above INSTAB_THRESH).

    trait_stability_map: per-trait stability [0,1].
    """

    _WINDOW = 120
    _STABLE_VAR = 0.020  # variance below this = stable
    _INSTAB_THRESH = 0.040
    _BIAS_LR = 0.0015
    _BIAS_DECAY = 0.9985
    _MAX_BIAS = 0.55
    _UPDATE_INTERVAL = 20

    def __init__(self) -> None:
        self._hist: List[Dict[str, float]] = []
        self.consolidated_bias: Dict[str, float] = {}
        self.trait_stability_map: Dict[str, float] = {}
        self._tick_count: int = 0

    def update(self, traits: Dict[str, float], personality: "PersonalityCore") -> None:
        self._tick_count += 1
        self._hist.append(dict(traits))
        if len(self._hist) > self._WINDOW:
            self._hist.pop(0)
        if len(self._hist) < 20 or self._tick_count % self._UPDATE_INTERVAL != 0:
            return

        import math as _m_pc11

        for dim in PersonalityCore._DIMS:
            _vs = [h.get(dim, 0.5) for h in self._hist]
            _mean = sum(_vs) / len(_vs)
            _var = sum((v - _mean) ** 2 for v in _vs) / len(_vs)
            _std = _m_pc11.sqrt(_var)
            _stab = max(0.0, 1.0 - _std / 0.15)
            self.trait_stability_map[dim] = _stab

            if _std < self._STABLE_VAR:
                # Reinforce: stable trait → push bias toward current mean
                _direction = _mean - 0.50
                _cur_bias = self.consolidated_bias.get(dim, 0.0)
                _target = max(-self._MAX_BIAS, min(self._MAX_BIAS, _direction * 0.80))
                self.consolidated_bias[dim] = _cur_bias + self._BIAS_LR * (
                    _target - _cur_bias
                )
            elif _std > self._INSTAB_THRESH:
                # Decay bias when trait becomes unstable
                _cur_bias = self.consolidated_bias.get(dim, 0.0)
                self.consolidated_bias[dim] = _cur_bias * self._BIAS_DECAY

        # Inject bias as persistent evidence into PersonalityCore
        if self.consolidated_bias:
            personality.update(self.consolidated_bias)


class DamageLedger:
    """Tracks cumulative system damage and drives compensation strategy.

    Damage categories (all float accumulators):
      synapse_loss      — lost synaptic connections (from IrreversibleDegradationTracker)
      thermal_scars     — thermal overload events
      identity_losses   — collapse / anchor-pull events
      failed_goal_chains— consecutively failed goal sequences

    Each category has a severity weight:
      synapse_loss × 0.25 + thermal × 0.20 + identity × 0.35 + goals × 0.20
      = damage_index [0,1]

    CompensationMechanism is embedded here:
      When damage_index > COMPENSATE_THRESH:
        compensation_goal_bias: boost safe modes proportional to damage
        energy_save_factor: reduce energy spending
        exploration_suppression: reduce exploration multiplier

    Damage accrues, never fully resets (irreversible nature) but EMA allows
    for very slow recovery via successful operation.
    """

    _WEIGHTS = {
        "synapse_loss": 0.25,
        "thermal_scars": 0.20,
        "identity_losses": 0.35,
        "failed_goal_chains": 0.20,
    }
    _COMPENSATE_THRESH = 0.28
    _DAMAGE_EMA = 0.0040  # very slow decay (damage persists)
    _COMP_SCALE = 0.55

    def __init__(self) -> None:
        self._raw: Dict[str, float] = {k: 0.0 for k in self._WEIGHTS}
        self.damage_index: float = 0.0
        self.compensation_goal_bias: Dict[str, float] = {}
        self.energy_save_factor: float = 1.0
        self.exploration_suppression: float = 1.0
        self._tick_count: int = 0

    def record(self, category: str, amount: float = 1.0) -> None:
        if category in self._raw:
            self._raw[category] = min(200.0, self._raw[category] + amount)

    def update(
        self,
        brain: object,
        fds_state: str,
        identity_anchor: "IdentityAnchorField",
        action_success: float,
        tick: int,
    ) -> None:
        self._tick_count += 1

        # Auto-record from brain subsystems
        _deg = getattr(brain, "_degradation", None)
        if _deg is not None:
            self.record("synapse_loss", getattr(_deg, "synaptic_loss", 0.0) * 0.01)
            self.record("thermal_scars", getattr(_deg, "thermal_load", 0.0) * 0.005)

        if fds_state == "collapse":
            self.record("identity_losses", 1.0)
        if action_success < 0.25:
            self.record("failed_goal_chains", 0.10)

        # EMA-based slow recovery from successful operation
        if action_success > 0.65:
            for k in self._raw:
                self._raw[k] = max(0.0, self._raw[k] * (1.0 - self._DAMAGE_EMA))

        # Compute damage index
        _raw_idx = sum(
            self._WEIGHTS[k] * min(1.0, self._raw[k] / 40.0) for k in self._WEIGHTS
        )
        self.damage_index = min(1.0, _raw_idx)

        # Compensation mechanism
        if self.damage_index > self._COMPENSATE_THRESH:
            _d = (self.damage_index - self._COMPENSATE_THRESH) * self._COMP_SCALE
            self.compensation_goal_bias = {
                "rest": 1.0 + _d * 0.90,
                "consolidate": 1.0 + _d * 0.70,
                "execute": max(0.20, 1.0 - _d * 0.60),
                "explore": max(0.25, 1.0 - _d * 0.50),
            }
            self.energy_save_factor = max(0.50, 1.0 - _d * 0.35)
            self.exploration_suppression = max(0.30, 1.0 - _d * 0.55)
        else:
            self.compensation_goal_bias = {}
            self.energy_save_factor = 1.0
            self.exploration_suppression = 1.0


class GoalStabilityRegulator:
    """Prevents goal-churn — enforces minimum duration and cooldowns.

    Tracks:
      current_goal_mode       — active mode
      goal_duration           — ticks held continuously
      cooldown_remaining      — ticks locked out after a switch
      churn_rate              — recent switches / WINDOW (EMA)
      completion_ratio        — fraction of goals held ≥ MIN_HOLD

    Rules:
      MIN_HOLD:    a goal must be held this many ticks before switching is allowed
      COOLDOWN:    after switching, same mode cannot be reselected for COOLDOWN ticks
      When cooldown_active: candidate goal_mode overridden back to last stable mode

    Outputs:
      allowed_goal_mode       str   — the mode the system is actually allowed to pursue
      churn_rate              float [0,1]
      goal_duration           int
      cooldown_remaining      int
    """

    _MIN_HOLD = 8
    _COOLDOWN = 5
    _WINDOW = 40
    _CHURN_EMA = 0.12

    def __init__(self) -> None:
        self.current_goal_mode: str = "explore"
        self.allowed_goal_mode: str = "explore"
        self.goal_duration: int = 0
        self.cooldown_remaining: int = 0
        self.churn_rate: float = 0.0
        self.completion_ratio: float = 0.5
        self._switch_count: int = 0
        self._tick_count: int = 0
        self._last_stable_mode: str = "explore"
        self._completions: int = 0
        self._attempts: int = 0
        self._cooldown_modes: Dict[str, int] = {}

    def update(self, candidate_mode: str, tick: int, stream: List[str]) -> str:
        self._tick_count += 1

        # Tick down cooldowns
        _expired = [m for m, t in self._cooldown_modes.items() if t <= tick]
        for m in _expired:
            del self._cooldown_modes[m]
        if self.cooldown_remaining > 0:
            self.cooldown_remaining -= 1

        _switching = candidate_mode != self.current_goal_mode

        if _switching:
            self._attempts += 1
            # Block if cooldown active for candidate or min_hold not met
            _cd_blocked = candidate_mode in self._cooldown_modes
            _hold_ok = self.goal_duration >= self._MIN_HOLD

            if _cd_blocked or not _hold_ok:
                # Enforce: stay with current mode
                self.allowed_goal_mode = self.current_goal_mode
                self.goal_duration += 1
                self.churn_rate = (
                    1 - self._CHURN_EMA
                ) * self.churn_rate + self._CHURN_EMA * 1.0
                return self.allowed_goal_mode

            # Switch allowed
            if self.goal_duration >= self._MIN_HOLD:
                self._completions += 1
            self._switch_count += 1
            self._cooldown_modes[self.current_goal_mode] = tick + self._COOLDOWN
            self.cooldown_remaining = self._COOLDOWN
            self._last_stable_mode = self.current_goal_mode
            self.current_goal_mode = candidate_mode
            self.goal_duration = 0
            stream.append(
                f"[GSR switch {self._last_stable_mode}→{candidate_mode} "
                f"total={self._switch_count}]"
            )
        else:
            self.goal_duration += 1
            self.churn_rate = (
                1 - self._CHURN_EMA
            ) * self.churn_rate + self._CHURN_EMA * 0.0

        self.allowed_goal_mode = self.current_goal_mode
        self.completion_ratio = self._completions / max(1, self._attempts)
        return self.allowed_goal_mode


class NarrativeCompressionEngine:
    """Compresses episodic memory into a compact stable life-story.

    Reads UnifiedAutobiographicalMemory atoms every COMPRESS_INTERVAL ticks.
    Extracts:
      recurring_patterns: modes that appeared in ≥15% of atoms
      turning_points:     atoms with salience > SALIENT_THRESH and rare narrative_tag
      stable_traits:      PersonalityConsolidator top consolidated traits

    Maintains:
      compressed_narrative: str   — stable life-story (updated slowly)
      turning_point_log:    List[str]  — key events
      pattern_weights:      Dict[str,float]  — recurring mode frequencies

    Old atoms beyond ARCHIVE_AFTER ticks are "archived" — their data is
    aggregated into pattern_weights and then they are cleared from the buffer
    to prevent memory accumulation.  UnifiedAutobiographicalMemory's buffer
    rotation handles the actual eviction.
    """

    _COMPRESS_INTERVAL = 300
    _SALIENT_THRESH = 0.68
    _RECUR_THRESH = 0.15
    _MAX_TURNING_POINTS = 12

    def __init__(self) -> None:
        self.compressed_narrative: str = "Story not yet written."
        self.turning_point_log: List[str] = []
        self.pattern_weights: Dict[str, float] = {}
        self._tick_count: int = 0
        self._last_compress_tick: int = 0

    def update(
        self,
        autobio_mem: "UnifiedAutobiographicalMemory",
        personality_consolidator: "PersonalityConsolidator",
        tick: int,
    ) -> None:
        self._tick_count += 1
        if tick - self._last_compress_tick < self._COMPRESS_INTERVAL:
            return
        self._last_compress_tick = tick

        _atoms = list(autobio_mem._buf)
        if len(_atoms) < 20:
            return

        from collections import Counter as _Ctr11

        # Recurring patterns from narrative_tags + concepts
        _tags = [a["narrative_tag"] for a in _atoms if a["narrative_tag"]]
        _tag_freq = _Ctr11(_tags)
        _total = max(1, len(_atoms))
        self.pattern_weights = {
            t: c / _total
            for t, c in _tag_freq.items()
            if c / _total >= self._RECUR_THRESH
        }

        # Turning points: high-salience + infrequent tags
        _turning = [
            a
            for a in _atoms
            if a["salience"] > self._SALIENT_THRESH
            and a.get("narrative_tag", "") in {"cascade", "goal_shift"}
        ]
        for a in _turning[-self._MAX_TURNING_POINTS :]:
            _tp = (
                f"tick={a['tick']} "
                f"event={a['narrative_tag']} "
                f"valence={a['valence']:+.2f} "
                f"sal={a['salience']:.2f}"
            )
            if _tp not in self.turning_point_log:
                self.turning_point_log.append(_tp)
        if len(self.turning_point_log) > self._MAX_TURNING_POINTS:
            self.turning_point_log = self.turning_point_log[-self._MAX_TURNING_POINTS :]

        # Stable traits from consolidator
        _top_traits = sorted(
            personality_consolidator.trait_stability_map.items(), key=lambda x: -x[1]
        )[:3]

        # Build compressed narrative
        _rec_str = (
            ", ".join(f"{k}:{v:.2f}" for k, v in list(self.pattern_weights.items())[:4])
            or "—"
        )
        _trait_str = ", ".join(f"{k}({s:.2f})" for k, s in _top_traits) or "—"
        _n_tp = len(self.turning_point_log)
        self.compressed_narrative = (
            f"Recurring: {_rec_str}. "
            f"Key traits: {_trait_str}. "
            f"Turning points: {_n_tp}. "
            f"Last: {self.turning_point_log[-1] if self.turning_point_log else '—'}."
        )


class StabilityExplorerBalancer:
    """Dynamically couples exploration rate to current stability level.

    Rule:
      High stability (emergent_stability > HIGH_THRESH):
        → exploration_multiplier rises (exploration is rewarded / safe)
      Low stability (emergent_stability < LOW_THRESH):
        → exploration_multiplier falls (exploration is suppressed)
      Normal range: multiplier = 1.0 ± blend

    Also reads FDS instability_index to modulate independently of
    emergent_stability.

    exploration_multiplier [0.20, 1.80]:
      multiplied onto explore / search / interact goal scores.
    stabilization_multiplier [0.20, 1.80]:
      multiplied onto rest / consolidate scores (inverse of exploration).
    """

    _HIGH_THRESH = 0.68
    _LOW_THRESH = 0.36
    _MUL_EMA = 0.06
    _EXPLORE_MAX = 1.70
    _EXPLORE_MIN = 0.22

    def __init__(self) -> None:
        self.exploration_multiplier: float = 1.0
        self.stabilization_multiplier: float = 1.0
        self._ema_mul: float = 1.0

    def update(self, emergent_stability: float, instability_index: float) -> None:
        _eff_stab = emergent_stability * (1.0 - instability_index * 0.40)

        if _eff_stab > self._HIGH_THRESH:
            _tgt = min(self._EXPLORE_MAX, 1.0 + (_eff_stab - self._HIGH_THRESH) * 2.20)
        elif _eff_stab < self._LOW_THRESH:
            _tgt = max(self._EXPLORE_MIN, 1.0 - (self._LOW_THRESH - _eff_stab) * 2.40)
        else:
            _tgt = 1.0

        self._ema_mul = (1 - self._MUL_EMA) * self._ema_mul + self._MUL_EMA * _tgt
        self.exploration_multiplier = self._ema_mul
        self.stabilization_multiplier = max(0.30, 2.0 - self._ema_mul)


# ─────────────────────────────────────────────────────────────────────────────
# Phase 12: Person Engine — Embodied Output Personality Layer
#
# Translates the brain's live internal-state dynamics into a structured
# "output_profile" that colours all generated text with authentic hesitation,
# tension, uncertainty, and emotional tone.
#
# Four classes:
#   GoalTensionField        — measures competing-goal pressure
#   SelfModelHypothesizer   — maintains probabilistic self-hypotheses
#   BehavioralOutputGate    — maps pressure to concrete text-style params
#   PersonEngine            — master synthesizer; published output_profile
# ─────────────────────────────────────────────────────────────────────────────


class GoalTensionField:
    """Measures the pressure generated by competing goal attractors.

    Reads the last full goal-score dict from ConsciousnessCore._last_goal_scores
    (populated in _evaluate_goal). Computes:

      tension_score [0,1]
        = normalised entropy of the top-5 goal scores.
        A score near 1 → several goals nearly tied (high tension / indecision).
        A score near 0 → one goal dominant (clear intent).

      dominant_goal: str        — current winner
      runner_up_goal: str       — second-highest scorer
      dominance_margin: float   — winner score − runner-up score (normalised)

    EMA-smoothed to avoid tick-to-tick noise.
    """

    _EMA = 0.10
    _TOP_N = 5

    def __init__(self) -> None:
        self.tension_score: float = 0.0
        self.dominant_goal: str = "explore"
        self.runner_up_goal: str = "rest"
        self.dominance_margin: float = 0.0
        self._ema_tens: float = 0.0

    def update(self, goal_scores: Dict[str, float]) -> None:
        if not goal_scores:
            return
        _sorted = sorted(goal_scores.items(), key=lambda x: -x[1])
        self.dominant_goal = _sorted[0][0]
        self.runner_up_goal = _sorted[1][0] if len(_sorted) > 1 else _sorted[0][0]

        _top = [v for _, v in _sorted[: self._TOP_N]]
        _tot = sum(_top) or 1.0
        _probs = [v / _tot for v in _top]

        import math as _m_gtf

        _ent = -sum(p * _m_gtf.log(p + 1e-9) for p in _probs)
        _max_ent = _m_gtf.log(len(_probs))
        _raw_tens = _ent / (_max_ent or 1.0)

        self._ema_tens = (1 - self._EMA) * self._ema_tens + self._EMA * _raw_tens
        self.tension_score = self._ema_tens

        _top2 = [_sorted[0][1], _sorted[1][1] if len(_sorted) > 1 else 0.0]
        _scale = max(_top2[0], 1e-6)
        self.dominance_margin = max(0.0, (_top2[0] - _top2[1]) / _scale)


class SelfModelHypothesizer:
    """Maintains uncertain, probabilistic hypotheses about own internal state.

    The agent cannot read its own state directly.  Instead it forms and revises
    hypotheses in a small set of self-knowledge aspects:

      energy_estimate      — inferred from recent action success rates
      stability_estimate   — inferred from goal_tension + ISF stability_force
      social_estimate      — inferred from social_sce trust average
      goal_clarity         — 1 − tension_score

    Each aspect has:
      estimate:   float [0,1]
      confidence: float [0,1]   — rises with consistent evidence, falls on surprise
      revision_pending: bool    — True when new evidence contradicts prior

    revision_pending dims produce visible hesitation / correction in output.

    Hypotheses update every REFRESH_INTERVAL ticks (slow inference, not perfect).
    """

    _ASPECTS = ("energy", "stability", "social", "goal_clarity")
    _CONF_LR = 0.06
    _SURP_DECAY = 0.80
    _REFRESH_INTERVAL = 8

    def __init__(self) -> None:
        self.estimates: Dict[str, float] = {a: 0.50 for a in self._ASPECTS}
        self.confidences: Dict[str, float] = {a: 0.40 for a in self._ASPECTS}
        self.revision_pending: Dict[str, bool] = {a: False for a in self._ASPECTS}
        self.uncertainty_overall: float = 0.60
        self._prev_estimates: Dict[str, float] = {a: 0.50 for a in self._ASPECTS}
        self._tick: int = 0

    def update(
        self,
        energy_proxy: float,
        stability_proxy: float,
        social_proxy: float,
        goal_clarity: float,
    ) -> None:
        self._tick += 1
        if self._tick % self._REFRESH_INTERVAL != 0:
            return

        _new = {
            "energy": energy_proxy,
            "stability": stability_proxy,
            "social": social_proxy,
            "goal_clarity": goal_clarity,
        }
        for asp in self._ASPECTS:
            _prev = self._prev_estimates.get(asp, 0.50)
            _curr = _new[asp]
            _surprise = abs(_curr - _prev)

            if _surprise > 0.18:
                self.revision_pending[asp] = True
                # Confidence erodes on surprise
                self.confidences[asp] = max(
                    0.10, self.confidences[asp] * self._SURP_DECAY
                )
            else:
                self.revision_pending[asp] = False
                # Confidence builds on consistency
                self.confidences[asp] = min(
                    0.90,
                    self.confidences[asp]
                    + self._CONF_LR * (1.0 - self.confidences[asp]),
                )

            # Estimate is NOT the true value — it's inferred with lag and error
            _lag = 0.35  # only 35% trust of new signal per refresh
            self.estimates[asp] = _prev + _lag * (_curr - _prev)
            self._prev_estimates[asp] = _curr

        self.uncertainty_overall = 1.0 - sum(self.confidences.values()) / len(
            self._ASPECTS
        )


class BehavioralOutputGate:
    """Maps the synthesised internal pressure to concrete output-style parameters.

    Reads from PersonEngine.output_profile and produces:

      hesitation_level   float [0,1]   — how much the agent pauses / qualifies
      tone               str           — "neutral"|"anxious"|"withdrawn"|
                                         "engaged"|"conflicted"|"fatigued"
      uncertainty_prefix str           — prepend to statements (e.g. "I think…")
      suboptimal_prob    float [0,1]   — probability that output is suboptimal/partial
      contradiction_prob float [0,1]   — probability of self-contradiction
      memory_intrusion   bool          — if True, a past-state reference leaks in
      social_withdrawal  bool          — True → reduce verbosity / engagement
      max_response_depth int           — limit reasoning depth (1–5)

    All params are EMA-smoothed so tone cannot jump abruptly between ticks.
    """

    _EMA = 0.08

    # Tone thresholds
    _ANXIOUS_THRESH = 0.60  # entropy_index OR fragmentation above this
    _FATIGUE_THRESH = 0.28  # energy_level below this
    _CONFLICTED_THRESH = 0.55  # goal_tension above this
    _ENGAGED_THRESH = 0.75  # social_modifier above this (energy also good)
    _WITHDRAWN_THRESH = -0.35  # social_modifier below this

    _HESIT_PREFIXES = [
        "I think—perhaps—",
        "Something about this feels… ",
        "Wait. Let me reconsider. ",
        "I'm not certain, but ",
        "This might be wrong, but ",
        "Hmm. ",
        "",  # sometimes no prefix even when hesitant
    ]

    def __init__(self) -> None:
        self.hesitation_level: float = 0.10
        self.tone: str = "neutral"
        self.uncertainty_prefix: str = ""
        self.suboptimal_prob: float = 0.05
        self.contradiction_prob: float = 0.02
        self.memory_intrusion: bool = False
        self.social_withdrawal: bool = False
        self.max_response_depth: int = 5
        self._ema_hesit: float = 0.10
        self._ema_subopt: float = 0.05
        self._ema_contr: float = 0.02

    def update(self, profile: Dict) -> None:
        import random as _rnd_bog

        _energy = profile.get("energy_level", 0.60)
        _entropy = profile.get("entropy_index", 0.30)
        _frag = profile.get("fragmentation", 0.10)
        _tension = profile.get("goal_tension", 0.20)
        _social = profile.get("social_modifier", 0.00)
        _mem_bias = profile.get("memory_bias_strength", 0.20)
        _uncert = profile.get("self_uncertainty", 0.40)
        _fds = profile.get("fds_state", "healthy")

        # ── Tone selection ────────────────────────────────────────────────
        if _fds == "collapse":
            self.tone = "conflicted"
        elif _energy < self._FATIGUE_THRESH:
            self.tone = "fatigued"
        elif max(_entropy, _frag) > self._ANXIOUS_THRESH:
            self.tone = "anxious"
        elif _tension > self._CONFLICTED_THRESH:
            self.tone = "conflicted"
        elif _social < self._WITHDRAWN_THRESH:
            self.tone = "withdrawn"
        elif _social > self._ENGAGED_THRESH and _energy > 0.55:
            self.tone = "engaged"
        else:
            self.tone = "neutral"

        # ── Hesitation (rises with uncertainty + tension + fragmentation) ─
        _raw_hesit = min(
            1.0, 0.25 * _uncert + 0.30 * _tension + 0.25 * _frag + 0.20 * _entropy
        )
        self._ema_hesit = (1 - self._EMA) * self._ema_hesit + self._EMA * _raw_hesit
        self.hesitation_level = self._ema_hesit

        # Prefix selected probabilistically — more hesitant → more qualifiers
        if _rnd_bog.random() < self.hesitation_level:
            _idx = int(self.hesitation_level * (len(self._HESIT_PREFIXES) - 1))
            _idx = min(_idx, len(self._HESIT_PREFIXES) - 1)
            self.uncertainty_prefix = self._HESIT_PREFIXES[_idx]
        else:
            self.uncertainty_prefix = ""

        # ── Suboptimal probability (rises with entropy + damage) ──────────
        _raw_subopt = min(0.70, 0.35 * _entropy + 0.25 * _frag + 0.20 * (1.0 - _energy))
        self._ema_subopt = (1 - self._EMA) * self._ema_subopt + self._EMA * _raw_subopt
        self.suboptimal_prob = self._ema_subopt

        # ── Contradiction probability (rises under collapse + tension) ────
        _raw_contr = min(
            0.50, 0.40 * _tension + 0.30 * _frag + (0.20 if _fds == "collapse" else 0.0)
        )
        self._ema_contr = (1 - self._EMA) * self._ema_contr + self._EMA * _raw_contr
        self.contradiction_prob = self._ema_contr

        # ── Memory intrusion: past-state bleeds through ────────────────────
        self.memory_intrusion = _rnd_bog.random() < (_mem_bias * 0.40)

        # ── Social withdrawal ──────────────────────────────────────────────
        self.social_withdrawal = (
            _social < self._WITHDRAWN_THRESH or self.tone == "fatigued"
        )

        # ── Depth limit (fatigued / conflicted → shallower reasoning) ─────
        if self.tone in ("fatigued", "conflicted"):
            self.max_response_depth = 2
        elif self.tone == "anxious":
            self.max_response_depth = 3
        else:
            self.max_response_depth = 5


class PersonEngine:
    """Master Person Engine — synthesises all internal-state signals into
    a single published ``output_profile`` dict.

    output_profile is the interface between the brain's internal dynamics
    and any downstream text-generation or dialogue subsystem.  It encodes:

      energy_level         float [0,1]   — inferred from survival core + action cost
      entropy_index        float [0,1]   — from EntropicDriftLayer
      fragmentation        float [0,1]   — from ISF component_variance
      goal_tension         float [0,1]   — from GoalTensionField
      social_modifier      float [-1,+1] — from PhysioSocialCoupler / SocialSCE trust
      memory_bias_strength float [0,1]   — recency weight of autobiographical memory
      self_uncertainty     float [0,1]   — from SelfModelHypothesizer
      fds_state            str           — FailureDetectionCore.state
      dominant_goal        str           — current winning goal mode
      runner_up_goal       str           — second competitor
      dominance_margin     float [0,1]   — gap between winner and runner-up
      hesitation_level     float [0,1]   — from BehavioralOutputGate
      tone                 str           — from BehavioralOutputGate
      uncertainty_prefix   str           — prepend text from BehavioralOutputGate
      suboptimal_prob      float [0,1]
      contradiction_prob   float [0,1]
      memory_intrusion     bool
      social_withdrawal    bool
      max_response_depth   int [1,5]
      self_hypotheses      Dict          — from SelfModelHypothesizer
      revisions_pending    List[str]     — aspects currently under revision

    External systems (dialogue_manager, speech_output) call:
        profile = brain.consciousness.person_engine.output_profile
    and use it to colour their output.
    """

    _ENERGY_PROXY_EMA = 0.08
    _SOCIAL_EMA = 0.06

    def __init__(self) -> None:
        self.goal_tension_field: GoalTensionField = GoalTensionField()
        self.self_hypothesizer: SelfModelHypothesizer = SelfModelHypothesizer()
        self.output_gate: BehavioralOutputGate = BehavioralOutputGate()
        self.output_profile: Dict = {}
        self._energy_ema: float = 0.60
        self._social_ema: float = 0.00

    def update(
        self,
        goal_scores: Dict[str, float],
        energy_raw: float,  # from HomeostaticSurvivalCore vitals
        entropy_level: float,
        fragmentation: float,
        social_trust_avg: float,
        autobio_salience: float,
        fds_state: str,
        stability_force: float,
        stream: List[str],
    ) -> None:
        # ── Update sub-components ────────────────────────────────────────
        self.goal_tension_field.update(goal_scores)

        self._energy_ema = (
            1 - self._ENERGY_PROXY_EMA
        ) * self._energy_ema + self._ENERGY_PROXY_EMA * energy_raw
        self._social_ema = (
            1 - self._SOCIAL_EMA
        ) * self._social_ema + self._SOCIAL_EMA * (
            social_trust_avg * 2.0 - 1.0
        )  # → [-1,+1]

        _stab_proxy = max(0.0, min(1.0, 0.50 - stability_force * 0.50))

        self.self_hypothesizer.update(
            energy_proxy=self._energy_ema,
            stability_proxy=_stab_proxy,
            social_proxy=(self._social_ema + 1.0) * 0.50,
            goal_clarity=1.0 - self.goal_tension_field.tension_score,
        )

        # ── Build profile ─────────────────────────────────────────────────
        _profile: Dict = {
            "energy_level": self._energy_ema,
            "entropy_index": entropy_level,
            "fragmentation": fragmentation,
            "goal_tension": self.goal_tension_field.tension_score,
            "social_modifier": self._social_ema,
            "memory_bias_strength": autobio_salience,
            "self_uncertainty": self.self_hypothesizer.uncertainty_overall,
            "fds_state": fds_state,
            "dominant_goal": self.goal_tension_field.dominant_goal,
            "runner_up_goal": self.goal_tension_field.runner_up_goal,
            "dominance_margin": self.goal_tension_field.dominance_margin,
        }

        self.output_gate.update(_profile)

        _profile.update(
            {
                "hesitation_level": self.output_gate.hesitation_level,
                "tone": self.output_gate.tone,
                "uncertainty_prefix": self.output_gate.uncertainty_prefix,
                "suboptimal_prob": self.output_gate.suboptimal_prob,
                "contradiction_prob": self.output_gate.contradiction_prob,
                "memory_intrusion": self.output_gate.memory_intrusion,
                "social_withdrawal": self.output_gate.social_withdrawal,
                "max_response_depth": self.output_gate.max_response_depth,
                "self_hypotheses": dict(self.self_hypothesizer.estimates),
                "revisions_pending": [
                    a for a, r in self.self_hypothesizer.revision_pending.items() if r
                ],
            }
        )
        self.output_profile = _profile

        # Emit to stream when notable state transitions occur
        _tone = self.output_gate.tone
        if _tone not in ("neutral", "engaged"):
            stream.append(
                f"[PERSON-ENGINE tone={_tone} "
                f"hesit={self.output_gate.hesitation_level:.2f} "
                f"tens={self.goal_tension_field.tension_score:.2f} "
                f"uncert={self.self_hypothesizer.uncertainty_overall:.2f} "
                f"revise={_profile['revisions_pending']}]"
            )


# ─────────────────────────────────────────────────────────────────────────────
# Phase 13: Recursive Internal Dynamics
#
# State → modifies State → modifies State → produces Output
#
# Five classes:
#   RecursiveFeedbackEngine   — cross-dimension amplification / dampening
#   DelayedConsequenceBuffer  — queued effects arriving with lag
#   SelfMisalignmentTracker   — self-model vs actual divergence
#   BehavioralInertiaField    — momentum, stuck-loops, overreaction
#   PhaseShiftDetector        — sudden multi-dim threshold crossings
# ─────────────────────────────────────────────────────────────────────────────


class RecursiveFeedbackEngine:
    """Cross-dimension feedback loops — amplification and dampening.

    Maintains a small set of signed loop pairs.  Each pair (src, dst, gain)
    means: dst_value += gain * src_value every tick (before normalisation).

    Positive gain → amplification (runaway if unchecked).
    Negative gain → dampening (stabilising).

    Dimensions tracked (all float [0,1]):
      tension, entropy, fragmentation, energy, social, damage

    Loop table (hardcoded biology):
      tension   → entropy       +0.012   (stress raises entropy)
      entropy   → fragmentation +0.010   (entropy fragments identity)
      fragmentation → tension   +0.014   (fragmentation raises tension)
      energy    → tension       -0.010   (energy reduces tension)
      social    → fragmentation -0.008   (social cohesion resists fragmentation)
      damage    → energy        -0.007   (damage drains energy)
      entropy   → social        -0.006   (entropy erodes social trust)

    Output: amplified_state Dict[str,float] — adjusted dimension values.
    runaway_active: bool — True when any dim delta exceeds RUNAWAY_THRESH.
    loop_gains: Dict[str,float] — net gain applied to each dst this tick.
    """

    _LOOPS = [
        # (src, dst, gain)
        ("tension", "entropy", +0.012),
        ("entropy", "fragmentation", +0.010),
        ("fragmentation", "tension", +0.014),
        ("energy", "tension", -0.010),
        ("social", "fragmentation", -0.008),
        ("damage", "energy", -0.007),
        ("entropy", "social", -0.006),
    ]
    _RUNAWAY_THRESH = 0.06  # delta per tick before dampener fires
    _CLAMP_MAX = 0.95
    _CLAMP_MIN = 0.05
    _DAMPEN_RATE = 0.12  # pull back toward centre when runaway

    def __init__(self) -> None:
        self.amplified_state: Dict[str, float] = {
            "tension": 0.30,
            "entropy": 0.30,
            "fragmentation": 0.10,
            "energy": 0.60,
            "social": 0.50,
            "damage": 0.10,
        }
        self.runaway_active: bool = False
        self.loop_gains: Dict[str, float] = {k: 0.0 for k in self.amplified_state}
        self._prev_state: Dict[str, float] = dict(self.amplified_state)

    def update(self, raw_state: Dict[str, float]) -> Dict[str, float]:
        """Blend raw sensor values with carried amplified state, apply loops."""
        # 1. Soft-merge incoming raw values (60% raw, 40% carried)
        _blended: Dict[str, float] = {}
        for k in self.amplified_state:
            _r = raw_state.get(k, self.amplified_state[k])
            _blended[k] = 0.60 * _r + 0.40 * self.amplified_state[k]

        # 2. Apply feedback loops
        _deltas: Dict[str, float] = {k: 0.0 for k in _blended}
        for src, dst, gain in self._LOOPS:
            _deltas[dst] += gain * _blended[src]

        # 3. Detect runaway
        _max_delta = max(abs(d) for d in _deltas.values())
        self.runaway_active = _max_delta > self._RUNAWAY_THRESH

        # 4. Dampening when runaway detected
        if self.runaway_active:
            for k in _deltas:
                _deltas[k] *= 1.0 - self._DAMPEN_RATE

        # 5. Apply deltas and clamp
        self.loop_gains = {}
        for k in _blended:
            _blended[k] = max(
                self._CLAMP_MIN, min(self._CLAMP_MAX, _blended[k] + _deltas[k])
            )
            self.loop_gains[k] = _deltas[k]

        self._prev_state = dict(self.amplified_state)
        self.amplified_state = _blended
        return self.amplified_state


class DelayedConsequenceBuffer:
    """Queued effects that arrive with lag — delayed state changes.

    Events inserted via enqueue(effect_type, magnitude, delay_ticks).
    effect_type: one of ("tension_delta", "entropy_delta",
                         "fragmentation_delta", "energy_delta",
                         "social_delta", "damage_delta")

    Each tick, apply() pops all entries whose arrival tick <= current tick
    and returns a flat dict of aggregated deltas to be merged into live state.

    This creates temporal non-linearity: actions taken now have consequences
    that appear 10–40 ticks later, impossible to fully anticipate.
    """

    _DEFAULT_DELAYS = {
        "tension_delta": 4,
        "entropy_delta": 8,
        "fragmentation_delta": 12,
        "energy_delta": 6,
        "social_delta": 16,
        "damage_delta": 20,
    }
    _MAX_QUEUE = 64

    def __init__(self) -> None:
        self._queue: List[Dict] = []
        self.pending_count: int = 0
        self.last_deltas: Dict[str, float] = {}

    def enqueue(
        self,
        effect_type: str,
        magnitude: float,
        current_tick: int,
        delay: Optional[int] = None,
    ) -> None:
        if len(self._queue) >= self._MAX_QUEUE:
            return  # drop when overloaded
        _delay = (
            delay if delay is not None else self._DEFAULT_DELAYS.get(effect_type, 10)
        )
        self._queue.append(
            {
                "arrive_at": current_tick + _delay,
                "effect": effect_type,
                "magnitude": magnitude,
            }
        )
        self.pending_count = len(self._queue)

    def apply(self, current_tick: int) -> Dict[str, float]:
        _ready = [e for e in self._queue if e["arrive_at"] <= current_tick]
        _remain = [e for e in self._queue if e["arrive_at"] > current_tick]
        self._queue = _remain
        self.pending_count = len(self._queue)

        _deltas: Dict[str, float] = {}
        for e in _ready:
            _k = e["effect"]
            _deltas[_k] = _deltas.get(_k, 0.0) + e["magnitude"]
        self.last_deltas = _deltas
        return _deltas


class SelfMisalignmentTracker:
    """Measures the gap between self-model estimates and actual measured values.

    self-model estimates come from SelfModelHypothesizer.estimates (lagged, noisy).
    actual values come from live brain signals.

    Per-aspect misalignment = |estimate - actual|.
    misalignment_score [0,1] = weighted mean across aspects.

    High misalignment_score → the agent is wrong about itself in ways it
    may not yet recognise.  This causes:
      - increased contradiction_prob in BehavioralOutputGate
      - spurious confidence (self thinks it's fine when it's not)
      - or excessive self-doubt (self thinks it's bad when ok)

    misalignment_vector: per-aspect signed error (estimate − actual).
    correction_attempts: EMA of how often the system tried to correct itself.
    correction_success_rate: fraction of attempts that reduced misalignment.
    """

    _ASPECTS = ("energy", "stability", "social", "goal_clarity")
    _WEIGHTS = {"energy": 0.30, "stability": 0.30, "social": 0.20, "goal_clarity": 0.20}
    _CORR_EMA = 0.10

    def __init__(self) -> None:
        self.misalignment_vector: Dict[str, float] = {a: 0.0 for a in self._ASPECTS}
        self.misalignment_score: float = 0.0
        self.correction_attempts: float = 0.0
        self.correction_success_rate: float = 0.50
        self._prev_score: float = 0.0

    def update(self, estimates: Dict[str, float], actuals: Dict[str, float]) -> None:
        for asp in self._ASPECTS:
            _e = estimates.get(asp, 0.50)
            _a = actuals.get(asp, 0.50)
            self.misalignment_vector[asp] = _e - _a  # signed: + = overestimate

        _score = sum(
            self._WEIGHTS[asp] * abs(self.misalignment_vector[asp])
            for asp in self._ASPECTS
        )
        self.misalignment_score = min(1.0, _score * 3.0)  # scale to [0,1]

        # Track whether correction is happening (score reducing)
        _improving = self.misalignment_score < self._prev_score
        self.correction_attempts = (
            1 - self._CORR_EMA
        ) * self.correction_attempts + self._CORR_EMA * 1.0
        if _improving:
            self.correction_success_rate = min(1.0, self.correction_success_rate + 0.04)
        else:
            self.correction_success_rate = max(0.0, self.correction_success_rate - 0.02)

        self._prev_score = self.misalignment_score


class BehavioralInertiaField:
    """Momentum of current behavioral mode — resists switching, causes overreaction.

    Tracks the desired mode vs the inertially locked mode.

    inertia_level [0,1]:   how locked the system is to current mode.
      Rises every tick the current mode is held.
      Falls when the mode switches.

    accumulated_tension float:
      Builds up when desired_mode ≠ inertial_mode (system wants to change but can't).
      Dissipates slowly when modes match.
      When accumulated_tension > OVERREACT_THRESH → overreaction_pending = True.

    overreaction_pending bool:
      When True: the next mode switch is amplified (scores multiplied by OVERREACT_AMP).
      Cleared after the switch fires.

    locked_mode str:
      The mode the system is actually "stuck" to until inertia breaks.
    """

    _INERTIA_BUILD = 0.06
    _INERTIA_DECAY = 0.12
    _TENSION_BUILD = 0.07
    _TENSION_DECAY = 0.04
    _OVERREACT_THRESH = 0.55
    _OVERREACT_AMP = 1.65
    _BREAK_THRESH = 0.80  # inertia above this → very hard to switch

    def __init__(self) -> None:
        self.inertia_level: float = 0.10
        self.accumulated_tension: float = 0.00
        self.overreaction_pending: bool = False
        self.locked_mode: str = "explore"
        self._last_desired: str = "explore"

    def update(self, desired_mode: str, stream: List[str]) -> None:
        _switching = desired_mode != self.locked_mode

        if not _switching:
            # Build inertia while mode is stable
            self.inertia_level = min(1.0, self.inertia_level + self._INERTIA_BUILD)
            # Dissipate tension when mode matches intent
            self.accumulated_tension = max(
                0.0, self.accumulated_tension - self._TENSION_DECAY
            )
        else:
            # System wants to switch but inertia may block it
            if self.inertia_level > self._BREAK_THRESH:
                # Too inertial — stay locked, build tension
                self.accumulated_tension = min(
                    1.0, self.accumulated_tension + self._TENSION_BUILD
                )
                # Don't switch — inertia holds
            else:
                # Switch allowed — reset inertia
                if self.overreaction_pending:
                    stream.append(
                        f"[INERTIA overreaction fired: "
                        f"locked={self.locked_mode}→{desired_mode} "
                        f"tension={self.accumulated_tension:.2f}]"
                    )
                    self.overreaction_pending = False
                self.locked_mode = desired_mode
                self.inertia_level = max(0.0, self.inertia_level - self._INERTIA_DECAY)
                self.accumulated_tension = max(
                    0.0, self.accumulated_tension - self._TENSION_DECAY * 3.0
                )

        # Trigger overreaction flag when tension accumulates
        if self.accumulated_tension > self._OVERREACT_THRESH:
            if not self.overreaction_pending:
                stream.append(
                    f"[INERTIA overreaction armed: "
                    f"mode={self.locked_mode} "
                    f"tension={self.accumulated_tension:.2f}]"
                )
            self.overreaction_pending = True

        self._last_desired = desired_mode

    @property
    def overreact_multiplier(self) -> float:
        """Amplification to apply to next goal switch when overreaction pending."""
        return self._OVERREACT_AMP if self.overreaction_pending else 1.0


class PhaseShiftDetector:
    """Detects sudden multi-dimensional threshold crossings — phase transitions.

    Monitors key state dimensions.  A phase shift occurs when ≥ DIM_THRESH
    dimensions cross their alert threshold within a WINDOW_TICKS window.

    After a shift:
      in_reorganization: True for REORG_DURATION ticks.
      During reorganization: output is unreliable, goal scores are unstable.
      reorganization_noise: float [0,1] — magnitude of instability injected.

    phase_shift_count: cumulative shifts (each shift leaves irreversible residue).
    shift_magnitude:   max delta across shifted dimensions at moment of shift.
    affected_dims:     List[str] — which dims shifted.
    """

    _ALERT_THRESHOLDS = {
        "tension": 0.65,
        "entropy": 0.58,
        "fragmentation": 0.45,
        "energy": 0.22,  # energy *below* this is critical
        "social": 0.25,  # social *below*
    }
    _BELOW_DIMS = {"energy", "social"}  # threshold means < not >
    _WINDOW_TICKS = 6
    _DIM_THRESH = 3  # need ≥ 3 dims crossing simultaneously
    _REORG_DURATION = 20
    _NOISE_EMA = 0.15

    def __init__(self) -> None:
        self.in_reorganization: bool = False
        self.reorganization_noise: float = 0.0
        self.phase_shift_count: int = 0
        self.shift_magnitude: float = 0.0
        self.affected_dims: List[str] = []
        self._reorg_remaining: int = 0
        self._crossing_history: List[set] = []  # per-tick crossing sets
        self._ema_noise: float = 0.0

    def update(
        self,
        state_dims: Dict[str, float],
        prev_dims: Dict[str, float],
        stream: List[str],
    ) -> None:
        # Which dims are currently crossing their alert threshold?
        _crossing: set = set()
        for dim, val in state_dims.items():
            if dim not in self._ALERT_THRESHOLDS:
                continue
            _thresh = self._ALERT_THRESHOLDS[dim]
            if dim in self._BELOW_DIMS:
                if val < _thresh:
                    _crossing.add(dim)
            else:
                if val > _thresh:
                    _crossing.add(dim)

        self._crossing_history.append(_crossing)
        if len(self._crossing_history) > self._WINDOW_TICKS:
            self._crossing_history.pop(0)

        # Detect simultaneous crossing: dims in alert in ALL recent ticks
        if len(self._crossing_history) >= 2:
            _persistent = set.intersection(*self._crossing_history[-2:])
            _new_shift = (
                len(_persistent) >= self._DIM_THRESH and not self.in_reorganization
            )
            if _new_shift:
                self.phase_shift_count += 1
                self.affected_dims = sorted(_persistent)
                self.shift_magnitude = (
                    max(
                        abs(state_dims.get(d, 0.5) - prev_dims.get(d, 0.5))
                        for d in _persistent
                    )
                    if prev_dims
                    else 0.10
                )
                self.in_reorganization = True
                self._reorg_remaining = self._REORG_DURATION
                stream.append(
                    f"[PHASE-SHIFT #{self.phase_shift_count} "
                    f"dims={self.affected_dims} "
                    f"mag={self.shift_magnitude:.3f}]"
                )

        # Tick down reorganization window
        if self.in_reorganization:
            self._reorg_remaining -= 1
            _noise_target = max(0.0, self._reorg_remaining / self._REORG_DURATION)
            self._ema_noise = (
                1 - self._NOISE_EMA
            ) * self._ema_noise + self._NOISE_EMA * _noise_target
            self.reorganization_noise = self._ema_noise
            if self._reorg_remaining <= 0:
                self.in_reorganization = False
                self.reorganization_noise = 0.0
                self._ema_noise = 0.0
        else:
            self.reorganization_noise = 0.0


# ─────────────────────────────────────────────────────────────────────────────
# Phase 14: Self-Deception, Personas, Narrative Distortion, Belief Conflict
# ─────────────────────────────────────────────────────────────────────────────


class BiasedBeliefLayer:
    """Structured, persistent biases that distort self-interpretation.

    Four belief domains, each with an estimate and a bias:
      competence      — how capable the system believes it is
      social_standing — perceived quality of social position
      intentionality  — belief about the goodness of own intentions
      emotional_tone  — self-perceived emotional valence

    Each domain:
      estimate:    float [0,1]   — what the system currently believes
      bias:        float [-0.5, +0.5] — systematic over/underestimate
      confidence:  float [0,1]   — how certain the system is of this belief
      resistance:  float [0,1]   — how strongly it resists new evidence

    Attribution bias (toggle per domain):
      On success signal:
        If SELF_CREDIT mode → competence estimate raised, intentionality raised
        If EXTERNAL_CREDIT mode → competence unchanged, luck/world credited
      On failure signal:
        If EXTERNAL_BLAME mode → competence unchanged, world blamed
        If SELF_BLAME mode → competence lowered, intentionality questioned

    Bias direction (per domain) drifts slowly via EMA — but not toward truth.
    It drifts toward whichever interpretation preserves current estimate best.

    Outputs:
      biased_self_view:    Dict[str, float]   — distorted estimates
      attribution_log:     List[str]          — recent attribution events
      net_bias_magnitude:  float [0,1]        — overall distortion level
    """

    _DOMAINS = ("competence", "social_standing", "intentionality", "emotional_tone")
    _RESIST_EMA = 0.04  # how slowly resistance erodes under evidence
    _BELIEF_LR = 0.025  # learning rate for belief updates (very slow)
    _BIAS_DRIFT = 0.004  # bias drifts toward self-serving slowly each tick
    _CORR_THRESH = 0.28  # evidence must exceed this to actually shift belief
    _MAX_BIAS = 0.40
    _CONF_BUILD = 0.03
    _CONF_DECAY = 0.06

    def __init__(self) -> None:
        self.estimates: Dict[str, float] = {d: 0.55 for d in self._DOMAINS}
        self.biases: Dict[str, float] = {d: 0.0 for d in self._DOMAINS}
        self.confidences: Dict[str, float] = {d: 0.45 for d in self._DOMAINS}
        self.resistances: Dict[str, float] = {d: 0.35 for d in self._DOMAINS}
        self.biased_self_view: Dict[str, float] = {d: 0.55 for d in self._DOMAINS}
        self.attribution_log: List[str] = []
        self.net_bias_magnitude: float = 0.0
        self._tick: int = 0
        # Attribution mode per domain (True = self-serving, False = self-critical)
        self._self_serving: Dict[str, bool] = {d: True for d in self._DOMAINS}

    def update(
        self,
        actual_signals: Dict[str, float],
        success_signal: float,  # [0,1] recent action success
        social_signal: float,  # [0,1] social feedback
        fds_state: str,
    ) -> None:
        self._tick += 1

        _success_event = success_signal > 0.68
        _failure_event = success_signal < 0.28
        _social_good = social_signal > 0.60
        _social_bad = social_signal < 0.28

        for dom in self._DOMAINS:
            _actual = actual_signals.get(dom, 0.50)
            _cur_est = self.estimates[dom]
            _cur_bias = self.biases[dom]
            _resist = self.resistances[dom]
            _conf = self.confidences[dom]

            # ── Attribution ──────────────────────────────────────────────
            if _success_event:
                if self._self_serving[dom]:
                    # Credit the self
                    if dom in ("competence", "intentionality"):
                        _correction = +0.06 * (1.0 - _resist)
                        self.attribution_log.append(
                            f"[ATTRIB self-credit {dom} +{_correction:.3f}]"
                        )
                    else:
                        _correction = +0.03 * (1.0 - _resist)
                else:
                    # External credit → self-estimate unchanged
                    _correction = 0.0
                    self.attribution_log.append(f"[ATTRIB external-credit {dom}]")
            elif _failure_event:
                if self._self_serving[dom]:
                    # Blame external — self-estimate protected
                    _correction = 0.0
                    self.attribution_log.append(f"[ATTRIB external-blame {dom}]")
                else:
                    # Self-blame mode
                    if dom in ("competence", "intentionality"):
                        _correction = -0.05 * (1.0 - _resist)
                        self.attribution_log.append(
                            f"[ATTRIB self-blame {dom} {_correction:.3f}]"
                        )
                    else:
                        _correction = -0.02 * (1.0 - _resist)
            else:
                _correction = 0.0

            # ── Evidence update (resisted) ────────────────────────────────
            _evidence_delta = _actual - _cur_est
            if abs(_evidence_delta) > self._CORR_THRESH:
                # Evidence is strong enough to partially penetrate resistance
                _penetration = (abs(_evidence_delta) - self._CORR_THRESH) * (
                    1.0 - _resist
                )
                _correction += (
                    _penetration
                    * (1 if _evidence_delta > 0 else -1)
                    * self._BELIEF_LR
                    * 10
                )

            # ── Apply update ──────────────────────────────────────────────
            self.estimates[dom] = max(
                0.05,
                min(
                    0.95,
                    _cur_est
                    + _correction * self._BELIEF_LR * 40
                    + _cur_bias * self._BIAS_DRIFT,
                ),
            )

            # ── Bias drift (toward self-serving interpretation) ───────────
            _bias_target = (
                self._MAX_BIAS if self._self_serving[dom] else -self._MAX_BIAS
            )
            self.biases[dom] = max(
                -self._MAX_BIAS,
                min(
                    self._MAX_BIAS,
                    _cur_bias + self._BIAS_DRIFT * (_bias_target - _cur_bias),
                ),
            )

            # ── Confidence ────────────────────────────────────────────────
            if abs(_evidence_delta) < 0.12:
                self.confidences[dom] = min(
                    0.95, _conf + self._CONF_BUILD * (1.0 - _conf)
                )
            else:
                self.confidences[dom] = max(
                    0.10, _conf - self._CONF_DECAY * abs(_evidence_delta)
                )

            # ── Resistance erodes very slowly under repeated contradiction ─
            if abs(_evidence_delta) > 0.35:
                self.resistances[dom] = max(0.05, _resist * (1 - self._RESIST_EMA))
            else:
                self.resistances[dom] = min(0.85, _resist + self._RESIST_EMA * 0.2)

            # ── Under collapse: flip to self-critical mode temporarily ─────
            if fds_state == "collapse" and self._self_serving[dom]:
                self._self_serving[dom] = False
            elif fds_state == "healthy" and not self._self_serving[dom]:
                self._self_serving[dom] = True

            # Publish biased view = estimate + bias (clamped)
            self.biased_self_view[dom] = max(
                0.0, min(1.0, self.estimates[dom] + self.biases[dom])
            )

        # Keep attribution log bounded
        if len(self.attribution_log) > 20:
            self.attribution_log = self.attribution_log[-20:]

        _soc_dom = {
            "competence": 0.35,
            "social_standing": 0.35,
            "intentionality": 0.15,
            "emotional_tone": 0.15,
        }
        self.net_bias_magnitude = sum(
            abs(self.biases[d]) * _soc_dom[d] for d in self._DOMAINS
        )


class PersonaSelector:
    """Context-driven persona emergence — not explicit selection.

    Five personas with soft scores that compete via weighted signals:
      engaged       — curious, high energy, open
      defensive     — guarded, threat-sensitive, self-protective
      withdrawn     — low energy, minimal engagement, avoidant
      overconfident — risk-seeking, high competence estimate, expansive
      compliant     — adaptive, low agency, mirrors others

    Score of each persona = weighted sum of driving signals:
      engaged:       social_trust × 0.4 + energy × 0.3 + stability × 0.3
      defensive:     threat_level × 0.5 + past_rejection × 0.3 + instability × 0.2
      withdrawn:     low_energy × 0.4 + social_bad × 0.3 + damage × 0.3
      overconfident: success_rate × 0.4 + competence_belief × 0.4 + low_threat × 0.2
      compliant:     social_trust × 0.3 + instability × 0.3 + low_energy × 0.4

    Active persona determined by softmax — weighted blend, not hard select.
    Persona changes have inertia (EMA α=0.08).

    Outputs:
      active_persona:    str    — highest-weight persona name
      persona_weights:   Dict   — softmax weights per persona
      persona_goal_bias: Dict   — goal-mode multipliers from active persona
      persona_tone_bias: str    — tone suggestion to BehavioralOutputGate
    """

    _PERSONAS = ("engaged", "defensive", "withdrawn", "overconfident", "compliant")
    _EMA = 0.08
    _REPORT_INTERVAL = 30

    # Goal mode multipliers per persona
    _PERSONA_GOAL_BIAS: Dict[str, Dict[str, float]] = {
        "engaged": {
            "explore": 1.35,
            "interact": 1.25,
            "execute": 1.15,
            "rest": 0.65,
            "consolidate": 0.70,
        },
        "defensive": {
            "respond": 1.40,
            "consolidate": 1.20,
            "rest": 1.10,
            "explore": 0.40,
            "interact": 0.60,
            "execute": 0.70,
        },
        "withdrawn": {
            "rest": 1.80,
            "consolidate": 1.40,
            "explore": 0.25,
            "interact": 0.30,
            "execute": 0.40,
        },
        "overconfident": {
            "execute": 1.50,
            "explore": 1.45,
            "search": 1.30,
            "rest": 0.40,
            "consolidate": 0.50,
        },
        "compliant": {
            "respond": 1.30,
            "interact": 1.20,
            "explore": 0.70,
            "execute": 0.80,
        },
    }
    _PERSONA_TONE: Dict[str, str] = {
        "engaged": "engaged",
        "defensive": "anxious",
        "withdrawn": "withdrawn",
        "overconfident": "engaged",
        "compliant": "neutral",
    }

    def __init__(self) -> None:
        self.active_persona: str = "engaged"
        self.persona_weights: Dict[str, float] = {p: 0.20 for p in self._PERSONAS}
        self.persona_goal_bias: Dict[str, float] = {}
        self.persona_tone_bias: str = "neutral"
        self._ema_weights: Dict[str, float] = {p: 0.20 for p in self._PERSONAS}
        self._tick: int = 0

    def update(
        self,
        social_trust: float,
        energy: float,
        stability: float,
        threat_level: float,
        past_rejection: float,
        success_rate: float,
        competence_belief: float,
        damage_index: float,
        stream: List[str],
    ) -> None:
        self._tick += 1

        _low_energy = max(0.0, 1.0 - energy)
        _social_bad = max(0.0, 1.0 - social_trust)
        _low_threat = max(0.0, 1.0 - threat_level)
        _instab = max(0.0, 1.0 - stability)

        _raw: Dict[str, float] = {
            "engaged": social_trust * 0.40 + energy * 0.30 + stability * 0.30,
            "defensive": threat_level * 0.50 + past_rejection * 0.30 + _instab * 0.20,
            "withdrawn": _low_energy * 0.40 + _social_bad * 0.30 + damage_index * 0.30,
            "overconfident": success_rate * 0.40
            + competence_belief * 0.40
            + _low_threat * 0.20,
            "compliant": social_trust * 0.30 + _instab * 0.30 + _low_energy * 0.40,
        }

        # Softmax
        import math as _m_ps14

        _max_v = max(_raw.values())
        _exp = {p: _m_ps14.exp(v - _max_v) for p, v in _raw.items()}
        _tot = sum(_exp.values()) or 1.0
        _softmax = {p: _exp[p] / _tot for p in self._PERSONAS}

        # EMA smoothing — persona changes are inertial
        _prev_active = self.active_persona
        for p in self._PERSONAS:
            self._ema_weights[p] = (1 - self._EMA) * self._ema_weights[
                p
            ] + self._EMA * _softmax[p]

        self.persona_weights = dict(self._ema_weights)
        self.active_persona = max(self._ema_weights, key=self._ema_weights.get)
        self.persona_tone_bias = self._PERSONA_TONE[self.active_persona]

        # Build blended goal bias (weighted sum of all persona biases)
        _blended: Dict[str, float] = {}
        for p, w in self._ema_weights.items():
            for mode, mult in self._PERSONA_GOAL_BIAS[p].items():
                _blended[mode] = _blended.get(mode, 0.0) + w * mult
        self.persona_goal_bias = _blended

        if (
            self.active_persona != _prev_active
            or self._tick % self._REPORT_INTERVAL == 0
        ):
            stream.append(
                f"[PERSONA active={self.active_persona} "
                f"weights={{{', '.join(f'{p}:{w:.2f}' for p,w in self._ema_weights.items())}}}"
                f"]"
            )


class NarrativeDistortionEngine:
    """Reconstructive memory distortion — selective recall and reinterpretation.

    Reads UnifiedAutobiographicalMemory atoms but applies:

    1. Confirmation bias:
       Atoms whose narrative_tag matches current active_persona preferences
       are up-weighted (emphasis_weights raised).
       Contradicting atoms are down-weighted.

    2. Selective recall:
       retrieval() returns a filtered atom list emphasising confirming atoms.
       Sample is biased — not uniform random.

    3. Post-hoc reinterpretation:
       On each compression cycle, atoms with valence that contradicts
       current biased_self_view are retagged toward neutral/positive.

    Outputs:
      distorted_narrative:  str   — current biased life-story
      emphasis_weights:     Dict[str, float]  — per-tag emphasis multiplier
      distortion_magnitude: float [0,1]
      suppressed_events:    int   — count of atoms effectively silenced
    """

    _PERSONA_CONFIRMS: Dict[str, set] = {
        "engaged": {"explore", "goal_shift", "interact"},
        "defensive": {"failure", "rejection", "threat"},
        "withdrawn": {"rest", "consolidate", "low_energy"},
        "overconfident": {"success", "goal_shift", "explore"},
        "compliant": {"interact", "respond", "social"},
    }
    _CONFIRM_BOOST = 1.60
    _DISCONFIRM_DIM = 0.45
    _DISTORT_EMA = 0.05
    _COMPRESS_INTERVAL = 200

    def __init__(self) -> None:
        self.distorted_narrative: str = "No narrative yet."
        self.emphasis_weights: Dict[str, float] = {}
        self.distortion_magnitude: float = 0.0
        self.suppressed_events: int = 0
        self._ema_distort: float = 0.0
        self._tick: int = 0
        self._last_compress: int = 0

    def update(
        self,
        autobio_mem: "UnifiedAutobiographicalMemory",
        active_persona: str,
        biased_self_view: Dict[str, float],
        tick: int,
    ) -> None:
        self._tick += 1

        _confirms = self._PERSONA_CONFIRMS.get(active_persona, set())
        _atoms = list(autobio_mem._buf)

        # ── Emphasis weights ──────────────────────────────────────────────
        _all_tags = {a.get("narrative_tag", "") for a in _atoms}
        _emph: Dict[str, float] = {}
        _suppressed = 0
        for tag in _all_tags:
            if tag in _confirms:
                _emph[tag] = self._CONFIRM_BOOST
            else:
                _emph[tag] = self._DISCONFIRM_DIM
                _suppressed += sum(1 for a in _atoms if a.get("narrative_tag") == tag)
        self.emphasis_weights = _emph
        self.suppressed_events = _suppressed

        # ── Distortion magnitude ──────────────────────────────────────────
        _n_confirms = sum(1 for a in _atoms if a.get("narrative_tag") in _confirms)
        _raw_dist = 1.0 - (_n_confirms / max(1, len(_atoms)))
        self._ema_distort = (
            1 - self._DISTORT_EMA
        ) * self._ema_distort + self._DISTORT_EMA * _raw_dist
        self.distortion_magnitude = self._ema_distort

        # ── Periodic narrative rewrite ────────────────────────────────────
        if tick - self._last_compress < self._COMPRESS_INTERVAL or len(_atoms) < 10:
            return
        self._last_compress = tick

        _comp_belief = biased_self_view.get("competence", 0.55)
        _soc_belief = biased_self_view.get("social_standing", 0.50)
        _intent_bel = biased_self_view.get("intentionality", 0.55)

        # Describe the distorted life-story in terms of biased beliefs
        _tone_desc = (
            "able and purposeful"
            if _comp_belief > 0.65
            else (
                "struggling but trying"
                if _comp_belief > 0.42
                else "burdened and limited"
            )
        )
        _soc_desc = (
            "well-connected"
            if _soc_belief > 0.60
            else "cautiously present" if _soc_belief > 0.38 else "increasingly isolated"
        )
        _int_desc = (
            "acting from good intent"
            if _intent_bel > 0.60
            else (
                "uncertain of own motives"
                if _intent_bel > 0.35
                else "possibly self-serving"
            )
        )
        self.distorted_narrative = (
            f"Self as {_tone_desc}, {_soc_desc}, {_int_desc}. "
            f"Persona: {active_persona}. "
            f"Suppressed: {self.suppressed_events} events. "
            f"Distortion: {self.distortion_magnitude:.2f}."
        )

    def biased_recall(
        self, autobio_mem: "UnifiedAutobiographicalMemory", n: int = 8
    ) -> List[Dict]:
        """Return n atoms biased toward confirming tags."""
        import random as _rnd_nde

        _atoms = list(autobio_mem._buf)
        if not _atoms:
            return []
        # Weight each atom by emphasis of its tag
        _weights = [
            self.emphasis_weights.get(a.get("narrative_tag", ""), 1.0)
            * (a.get("salience", 0.5) + 0.1)
            for a in _atoms
        ]
        _tot = sum(_weights) or 1.0
        _probs = [w / _tot for w in _weights]
        _k = min(n, len(_atoms))
        _indices = _rnd_nde.choices(range(len(_atoms)), weights=_probs, k=_k)
        return [_atoms[i] for i in _indices]


class BeliefConflictResolver:
    """Manages three-layer belief conflict and determines behavioral driver.

    Layers:
      actual:      ground-truth signals from live brain subsystems
      self_model:  SelfModelHypothesizer estimates (lagged, uncertain)
      belief:      BiasedBeliefLayer biased_self_view (distorted, persistent)

    Per-domain divergence:
      actual_vs_model:  |actual - self_model|
      actual_vs_belief: |actual - belief|
      model_vs_belief:  |self_model - belief|

    Conflict score [0,1] = weighted mean of divergences.

    belief_dominance: str — which layer drives behavior this tick
      "actual"     → high confidence in sensors, low belief bias
      "self_model" → moderate uncertainty, moderate bias
      "belief"     → high resistance, low evidence, strong bias

    rationalization_active: bool
      True when belief dominated and actual outcome contradicted belief.
      System generates post-hoc justification (reflected in output_profile).

    correction_lag: int — how many ticks the system has been correcting
      without success. When this exceeds MAX_LAG, flip self_serving mode.
    """

    _DOMAINS = ("competence", "social_standing", "intentionality", "emotional_tone")
    _DOM_ACTUAL = {
        "competence": "energy",  # proxy
        "social_standing": "social",
        "intentionality": "goal_clarity",
        "emotional_tone": "stability",
    }
    _CONFLICT_EMA = 0.08
    _MAX_LAG = 18
    _BELIEF_THRESH = 0.55  # belief resistance above this → belief dominates

    def __init__(self) -> None:
        self.conflict_score: float = 0.0
        self.belief_dominance: str = "self_model"
        self.rationalization_active: bool = False
        self.correction_lag: int = 0
        self._ema_conflict: float = 0.0
        self.per_domain_divergence: Dict[str, float] = {d: 0.0 for d in self._DOMAINS}
        self._rationalizations: List[str] = []

    def update(
        self,
        actual_p13: Dict[str, float],
        self_model_estimates: Dict[str, float],
        biased_belief: "BiasedBeliefLayer",
        stream: List[str],
    ) -> None:

        _divergences = []
        for dom in self._DOMAINS:
            _asp = self._DOM_ACTUAL.get(dom, "energy")
            _act = actual_p13.get(_asp, 0.50)
            _model = self_model_estimates.get(
                dom.replace("_standing", "").replace("_tone", ""), 0.50
            )
            _belief_v = biased_belief.biased_self_view.get(dom, 0.50)
            _resist = biased_belief.resistances.get(dom, 0.35)

            _div_am = abs(_act - _model)
            _div_ab = abs(_act - _belief_v)
            _div_mb = abs(_model - _belief_v)
            _dom_conf = max(_div_am, _div_ab, _div_mb)
            self.per_domain_divergence[dom] = _dom_conf
            _divergences.append(_dom_conf)

        _raw_conf = sum(_divergences) / max(1, len(_divergences))
        self._ema_conflict = (
            1 - self._CONFLICT_EMA
        ) * self._ema_conflict + self._CONFLICT_EMA * _raw_conf
        self.conflict_score = min(1.0, self._ema_conflict * 2.5)

        # Determine which layer dominates
        _avg_resist = sum(biased_belief.resistances.values()) / len(self._DOMAINS)
        _avg_conf = sum(biased_belief.confidences.values()) / len(self._DOMAINS)

        if _avg_resist > self._BELIEF_THRESH and _avg_conf > 0.60:
            self.belief_dominance = "belief"
        elif self.conflict_score < 0.20:
            self.belief_dominance = "actual"
        else:
            self.belief_dominance = "self_model"

        # Rationalization — belief dominated but actual contradicted it
        if self.belief_dominance == "belief" and _raw_conf > 0.30:
            self.rationalization_active = True
            self.correction_lag += 1
            if self.correction_lag > self._MAX_LAG:
                # Force belief layer to flip self-serving mode
                for dom in self._DOMAINS:
                    biased_belief._self_serving[dom] = not biased_belief._self_serving[
                        dom
                    ]
                self.correction_lag = 0
                _rat = (
                    f"[BELIEF-CONFLICT rationalization-break "
                    f"self_serving flipped after {self._MAX_LAG} ticks]"
                )
                stream.append(_rat)
                self._rationalizations.append(_rat)
        else:
            self.rationalization_active = False
            self.correction_lag = max(0, self.correction_lag - 1)

        if len(self._rationalizations) > 10:
            self._rationalizations = self._rationalizations[-10:]


# ─────────────────────────────────────────────────────────────────────────────
# Phase 15: Social Masks — Per-Agent Behavioral Anchoring
# ─────────────────────────────────────────────────────────────────────────────


class SocialMaskRegistry:
    """Per-agent behavioral configurations with inertia, reinforcement, breakdown.

    A SocialMask is a semi-stable behavioral role maintained per known agent.
    It holds:
      tone_bias:         float [-1,+1]  warm (+) vs distant/cold (-)
      openness:          float [0,1]    how much is revealed vs hidden
      risk_tolerance:    float [0,1]    bold vs careful
      compliance:        float [0,1]    compliance vs resistance
      integrity:         float [0,1]    mask health (1=intact, 0=broken)
      interaction_count: int

    Evolution rules:
      MASK_LR = 0.012  — very slow drift toward interaction-driven target
      Reinforcement: after N consistent interactions, integrity +REINF_STEP
      Breakdown: when internal pressure > BREAK_PRESSURE, integrity decays
      Recovery: when pressure low, integrity recovers at RECOVER_RATE

    When integrity < BREAK_THRESH: mask_broken[agent_id] = True
      → mask values no longer constrain behavior for this agent
      → trust in ReputationMemory is reduced as a consequence

    goal_bias_for_mode(agent_id, mode): float multiplier from active mask.
    """

    _MASK_LR = 0.012
    _BREAK_PRESSURE = 0.68  # internal pressure above this → integrity decays
    _BREAK_THRESH = 0.25  # integrity below this → mask broken
    _REINF_STEP = 0.018
    _RECOVER_RATE = 0.008
    _DECAY_RATE = 0.022
    _MAX_AGENTS = 32
    _REPORT_INTERVAL = 50

    # Mode multipliers per mask profile dimension (simplified mapping)
    # tone_bias > 0 → warm → boost interact/respond; < 0 → distant → boost rest/consolidate
    # openness high → boost explore/search; low → boost rest
    # risk_tolerance high → boost execute/explore; low → boost rest/consolidate
    # compliance high → boost respond/interact; low → boost execute

    def __init__(self) -> None:
        self._masks: Dict[str, Dict] = {}  # agent_id → mask dict
        self.mask_broken: Dict[str, bool] = {}  # agent_id → bool
        self.active_agent: str = ""
        self.crack_events: int = 0
        self._tick: int = 0

    def _default_mask(self) -> Dict:
        return {
            "tone_bias": 0.0,
            "openness": 0.50,
            "risk_tolerance": 0.50,
            "compliance": 0.50,
            "integrity": 0.60,
            "interaction_count": 0,
        }

    def get_or_create(self, agent_id: str) -> Dict:
        if agent_id not in self._masks:
            if len(self._masks) >= self._MAX_AGENTS:
                # Evict agent with lowest interaction count
                _old = min(
                    self._masks, key=lambda k: self._masks[k]["interaction_count"]
                )
                del self._masks[_old]
                self.mask_broken.pop(_old, None)
            self._masks[agent_id] = self._default_mask()
            self.mask_broken[agent_id] = False
        return self._masks[agent_id]

    def update(
        self,
        agent_id: str,
        social_trust: float,  # from ReputationMemory / social_sce
        social_outcome: float,  # [0,1] quality of last interaction
        internal_pressure: float,  # from FDS instability_index
        active_persona: str,
        stream: List[str],
    ) -> None:
        self._tick += 1
        if not agent_id:
            return
        self.active_agent = agent_id
        _mask = self.get_or_create(agent_id)
        _mask["interaction_count"] += 1

        # ── Target mask values driven by social signal + persona ──────────
        _persona_tone = {
            "engaged": 0.50,
            "defensive": -0.30,
            "withdrawn": -0.60,
            "overconfident": 0.30,
            "compliant": 0.20,
        }.get(active_persona, 0.0)
        _persona_open = {
            "engaged": 0.70,
            "defensive": 0.20,
            "withdrawn": 0.15,
            "overconfident": 0.65,
            "compliant": 0.55,
        }.get(active_persona, 0.50)
        _persona_risk = {
            "engaged": 0.60,
            "defensive": 0.25,
            "withdrawn": 0.20,
            "overconfident": 0.80,
            "compliant": 0.40,
        }.get(active_persona, 0.50)
        _persona_comp = {
            "engaged": 0.55,
            "defensive": 0.45,
            "withdrawn": 0.60,
            "overconfident": 0.30,
            "compliant": 0.80,
        }.get(active_persona, 0.50)

        # Blend persona target with trust signal
        _target_tone = _persona_tone * 0.60 + (social_trust * 2.0 - 1.0) * 0.40
        _target_open = _persona_open * 0.70 + social_trust * 0.30
        _target_risk = _persona_risk * 0.70 + social_trust * 0.30
        _target_comp = _persona_comp * 0.70 + (1.0 - social_trust) * 0.30

        # Apply MASK_LR drift (very slow — mask changes glacially)
        _lr = self._MASK_LR
        _mask["tone_bias"] = max(
            -1.0,
            min(1.0, _mask["tone_bias"] + _lr * (_target_tone - _mask["tone_bias"])),
        )
        _mask["openness"] = max(
            0.0, min(1.0, _mask["openness"] + _lr * (_target_open - _mask["openness"]))
        )
        _mask["risk_tolerance"] = max(
            0.0,
            min(
                1.0,
                _mask["risk_tolerance"]
                + _lr * (_target_risk - _mask["risk_tolerance"]),
            ),
        )
        _mask["compliance"] = max(
            0.0,
            min(1.0, _mask["compliance"] + _lr * (_target_comp - _mask["compliance"])),
        )

        # ── Integrity update ──────────────────────────────────────────────
        _prev_integ = _mask["integrity"]
        if internal_pressure > self._BREAK_PRESSURE:
            _mask["integrity"] = max(
                0.0, _mask["integrity"] - self._DECAY_RATE * internal_pressure
            )
        elif internal_pressure < 0.30:
            _mask["integrity"] = min(1.0, _mask["integrity"] + self._RECOVER_RATE)

        # Reinforcement on good outcomes
        if social_outcome > 0.65:
            _mask["integrity"] = min(1.0, _mask["integrity"] + self._REINF_STEP)

        # Detect breakdown event
        _broken_now = _mask["integrity"] < self._BREAK_THRESH
        _was_broken = self.mask_broken.get(agent_id, False)
        if _broken_now and not _was_broken:
            self.crack_events += 1
            stream.append(
                f"[MASK BREAKDOWN agent={agent_id} "
                f"integrity={_mask['integrity']:.2f} "
                f"cracks={self.crack_events}]"
            )
        elif not _broken_now and _was_broken:
            stream.append(
                f"[MASK RECOVERED agent={agent_id} "
                f"integrity={_mask['integrity']:.2f}]"
            )
        self.mask_broken[agent_id] = _broken_now

    def goal_multipliers(self, agent_id: str) -> Dict[str, float]:
        """Return goal-mode multipliers from the active mask for agent_id."""
        if not agent_id or agent_id not in self._masks:
            return {}
        _mask = self._masks[agent_id]
        _broken = self.mask_broken.get(agent_id, False)
        _integ = _mask["integrity"]  # broken masks give weaker multipliers

        _tb = _mask["tone_bias"]  # [-1,+1]
        _op = _mask["openness"]  # [0,1]
        _rt = _mask["risk_tolerance"]  # [0,1]
        _cp = _mask["compliance"]  # [0,1]

        # Multipliers derived from mask dimensions
        _muls: Dict[str, float] = {
            "interact": 1.0 + _tb * 0.55 * _integ + _cp * 0.25,
            "respond": 1.0 + _cp * 0.60 * _integ,
            "explore": 1.0 + _op * 0.45 * _integ + _rt * 0.35 * _integ,
            "search": 1.0 + _op * 0.35 * _integ + _rt * 0.25 * _integ,
            "execute": 1.0 + _rt * 0.50 * _integ - _cp * 0.20,
            "rest": 1.0 + (-_tb * 0.30 + (1.0 - _op) * 0.25) * _integ,
            "consolidate": 1.0 + ((1.0 - _op) * 0.20 + _cp * 0.15) * _integ,
        }
        # When broken: all multipliers pulled toward 1.0 (mask no longer guides)
        if _broken:
            _muls = {k: 1.0 + (v - 1.0) * _integ for k, v in _muls.items()}
        return _muls

    def get_mask_summary(self, agent_id: str) -> str:
        if agent_id not in self._masks:
            return f"no mask for {agent_id}"
        _m = self._masks[agent_id]
        return (
            f"agent={agent_id} "
            f"tone={_m['tone_bias']:+.2f} open={_m['openness']:.2f} "
            f"risk={_m['risk_tolerance']:.2f} comp={_m['compliance']:.2f} "
            f"integ={_m['integrity']:.2f} "
            f"broken={self.mask_broken.get(agent_id,False)}"
        )


class ReputationMemory:
    """Long-term per-agent impression — trust, predictability, alignment.

    Per agent record:
      trust:              float [0,1]   EMA of positive interaction quality
      predictability:     float [0,1]   consistency of agent's behavior
      perceived_alignment: float [0,1]  how well agent's goals match own goals
      interaction_count:  int
      last_outcome:       float [0,1]

    Influence on SocialMaskRegistry:
      Low trust            → mask becomes guarded (openness ↓, risk ↓)
      High trust           → mask relaxes
      Low predictability   → risk_tolerance ↓ regardless of trust
      Low alignment        → compliance ↓, resistance ↑

    engagement_willingness: float [0,1]
      = trust × predictability × 0.70 + perceived_alignment × 0.30
      Used by goal gates to modulate interact/respond scores globally.

    withdrawal_signal: float [0,1]
      High when trust low + predictability low → social withdrawal
    """

    _TRUST_EMA = 0.08
    _PREDICT_EMA = 0.06
    _ALIGN_EMA = 0.05
    _MAX_AGENTS = 32

    def __init__(self) -> None:
        self._records: Dict[str, Dict] = {}
        self.engagement_willingness: float = 0.60
        self.withdrawal_signal: float = 0.0
        self.active_agent: str = ""

    def _default_record(self) -> Dict:
        return {
            "trust": 0.50,
            "predictability": 0.55,
            "perceived_alignment": 0.50,
            "interaction_count": 0,
            "last_outcome": 0.50,
        }

    def update(
        self,
        agent_id: str,
        outcome: float,  # [0,1] quality of this interaction
        behavior_variance: float,  # [0,1] how unpredictable agent was this tick
        goal_alignment: float,  # [0,1] how much agent's goal matched own
    ) -> None:
        if not agent_id:
            return
        self.active_agent = agent_id
        if agent_id not in self._records:
            if len(self._records) >= self._MAX_AGENTS:
                _old = min(
                    self._records, key=lambda k: self._records[k]["interaction_count"]
                )
                del self._records[_old]
            self._records[agent_id] = self._default_record()

        _rec = self._records[agent_id]
        _rec["interaction_count"] += 1
        _rec["last_outcome"] = outcome

        _rec["trust"] = (1 - self._TRUST_EMA) * _rec[
            "trust"
        ] + self._TRUST_EMA * outcome
        _rec["predictability"] = (1 - self._PREDICT_EMA) * _rec[
            "predictability"
        ] + self._PREDICT_EMA * (1.0 - behavior_variance)
        _rec["perceived_alignment"] = (1 - self._ALIGN_EMA) * _rec[
            "perceived_alignment"
        ] + self._ALIGN_EMA * goal_alignment

        _trust = _rec["trust"]
        _predict = _rec["predictability"]
        _align = _rec["perceived_alignment"]

        self.engagement_willingness = max(
            0.0, min(1.0, (_trust * 0.50 + _predict * 0.20 + _align * 0.30))
        )
        self.withdrawal_signal = max(
            0.0, (1.0 - _trust) * 0.60 + (1.0 - _predict) * 0.40 - 0.30
        )

    def get_trust(self, agent_id: str) -> float:
        return self._records.get(agent_id, {}).get("trust", 0.50)

    def get_predictability(self, agent_id: str) -> float:
        return self._records.get(agent_id, {}).get("predictability", 0.55)


class ConsequenceEstimator:
    """Biased partial foresight — estimates trust impact of current behavior.

    Given behavioral volatility (Phase 13/14 misalignment + inertia + tone):
      Estimates whether current behavior will increase or decrease trust.
      This estimate is BIASED by:
        active_persona → overconfident persona underestimates negative consequences
        biased_belief (competence) → high competence belief → underestimates risk
        Phase 13 runaway → estimate degrades sharply

    consequence_concern [0,1]:
      How much the system cares about consequences.
      Rises with reputation stakes (high trust → more to lose).
      Falls when internal pressure overrides social concern.

    expected_trust_delta float [-0.5, +0.5]:
      Biased prediction of trust change. Positive = expect gain, negative = expect loss.
      Actual trust is updated independently by ReputationMemory.

    suppression_signal float [0,1]:
      When consequence_concern high: suppresses instability leakage.
      Output gates multiply volatility params by (1 - suppression_signal).
    """

    _CONCERN_EMA = 0.10
    _SUPPRESS_SCALE = 0.70  # max suppression fraction

    def __init__(self) -> None:
        self.consequence_concern: float = 0.40
        self.expected_trust_delta: float = 0.0
        self.suppression_signal: float = 0.0
        self._ema_concern: float = 0.40

    def update(
        self,
        trust_at_stake: float,  # get_trust from ReputationMemory
        behavioral_volatility: float,  # misalignment + inertia
        active_persona: str,
        competence_belief: float,
        runaway_active: bool,
        internal_pressure: float,
    ) -> None:

        # Concern rises with how much trust there is to lose
        _raw_concern = trust_at_stake * 0.55 + (1.0 - internal_pressure) * 0.45
        self._ema_concern = (
            1 - self._CONCERN_EMA
        ) * self._ema_concern + self._CONCERN_EMA * _raw_concern
        self.consequence_concern = self._ema_concern

        # Biased expected trust delta
        # Base: negative if volatile, positive if stable
        _base_delta = (0.30 - behavioral_volatility) * 0.60

        # Persona bias: overconfident underestimates negative consequences
        _persona_bias = {
            "overconfident": +0.12,  # systematically optimistic
            "defensive": -0.08,  # systematically pessimistic
            "withdrawn": -0.04,
            "engaged": +0.04,
            "compliant": +0.02,
        }.get(active_persona, 0.0)

        # Competence belief bias: high belief → underestimate negative impact
        _comp_bias = (competence_belief - 0.50) * 0.10

        # Runaway degrades estimate quality
        _noise_mag = 0.15 if runaway_active else 0.0
        import random as _rnd_ce15

        _noise = _rnd_ce15.gauss(0.0, _noise_mag)

        self.expected_trust_delta = max(
            -0.50, min(0.50, _base_delta + _persona_bias + _comp_bias + _noise)
        )

        # Suppression: only active when concern is high and masks are intact
        if self.consequence_concern > 0.55:
            _raw_suppress = (
                (self.consequence_concern - 0.55) * self._SUPPRESS_SCALE * 2.0
            )
            self.suppression_signal = min(self._SUPPRESS_SCALE, _raw_suppress)
        else:
            self.suppression_signal = 0.0


class MaskRoleConflictEngine:
    """Three-way conflict: internal_state vs active_persona vs social_mask.

    Conflict dimensions:
      internal_vs_mask  — how much internal pressure tone differs from mask tone
      persona_vs_mask   — how much active persona style differs from mask style
      pressure_vs_role  — internal pressure vs mask integrity

    Resolution priority:
      pressure < 0.30  → mask wins   (role maintained, internal suppressed)
      pressure < 0.55  → blend       (partial internal leak through mask)
      pressure ≥ 0.55  → internal wins (mask cracks)

    Outputs:
      mask_adherence:  float [0,1]  — fraction of mask that is held
      behavioral_bleed: float [0,1] — internal state leaking through
      resolution_mode: str          — "mask"|"blend"|"internal"
      crack_this_tick: bool         — True when cracking event this tick
      bleed_goal_dampen: float      — multiplier applied to volatile modes
                                      (< 1 when suppressing leakage)
    """

    _BREAK_PRESSURE = 0.55
    _CRACK_PRESSURE = 0.30
    _BLEND_RANGE = (0.30, 0.55)
    _BLEED_EMA = 0.12

    def __init__(self) -> None:
        self.mask_adherence: float = 0.80
        self.behavioral_bleed: float = 0.0
        self.resolution_mode: str = "mask"
        self.crack_this_tick: bool = False
        self.bleed_goal_dampen: float = 1.0
        self._ema_bleed: float = 0.0
        self._total_cracks: int = 0

    def update(
        self,
        internal_pressure: float,
        mask_integrity: float,
        active_persona: str,
        mask_tone_bias: float,
        suppression_signal: float,
        stream: List[str],
    ) -> None:

        # Effective pressure after consequence suppression
        _eff_pressure = internal_pressure * (1.0 - suppression_signal * 0.60)

        # Persona's inherent alignment with the mask tone
        _persona_stability = {
            "engaged": 0.60,
            "defensive": 0.35,
            "withdrawn": 0.30,
            "overconfident": 0.45,
            "compliant": 0.70,
        }.get(active_persona, 0.50)

        # Bleed target
        if _eff_pressure >= self._BREAK_PRESSURE or mask_integrity < 0.25:
            _bleed_target = min(1.0, _eff_pressure * 1.20)
            self.resolution_mode = "internal"
            if not self.crack_this_tick:
                self.crack_this_tick = True
                self._total_cracks += 1
                stream.append(
                    f"[MASK-CRACK total={self._total_cracks} "
                    f"pressure={_eff_pressure:.2f} integ={mask_integrity:.2f}]"
                )
        elif _eff_pressure > self._CRACK_PRESSURE:
            _blend_frac = (_eff_pressure - self._CRACK_PRESSURE) / (
                self._BREAK_PRESSURE - self._CRACK_PRESSURE
            )
            _bleed_target = _blend_frac * (1.0 - _persona_stability) * 0.70
            self.resolution_mode = "blend"
            self.crack_this_tick = False
        else:
            _bleed_target = 0.0
            self.resolution_mode = "mask"
            self.crack_this_tick = False

        self._ema_bleed = (
            1 - self._BLEED_EMA
        ) * self._ema_bleed + self._BLEED_EMA * _bleed_target
        self.behavioral_bleed = self._ema_bleed
        self.mask_adherence = max(0.0, 1.0 - self.behavioral_bleed)

        # Goal dampen: when mask is intact and consequence suppression high,
        # reduce volatile goal scores (don't let instability leak into behavior)
        if self.resolution_mode == "mask":
            _damp = max(0.30, 1.0 - suppression_signal * 0.50)
            self.bleed_goal_dampen = _damp
        else:
            self.bleed_goal_dampen = 1.0  # no dampening when mask broken


# ─────────────────────────────────────────────────────────────────────────────
# Phase 16: Instability Self-Preservation
# ─────────────────────────────────────────────────────────────────────────────


class InstabilityRiskMonitor:
    """Infers instability risk indirectly and biases behavior toward survival.

    The monitor does not read any privileged "danger" flag. Instead it infers
    risk from proxies that suggest loss of coherence or control:
      - entropy and fragmentation
      - goal churn and contradiction/conflict pressure
      - runaway dynamics and mask breakdown
      - recent collapse / pre-collapse history

    Outputs:
      instability_risk   float [0,1]  — inferred danger level
      caution_bias       float [0,1]  — conservative bias applied to goals/output
      underreaction      bool         — lagging response despite high raw danger
      overreaction       bool         — excessive caution at moderate danger
      recent_collapse    bool         — collapse memory still active
      anchor_pull        float [0,1]  — reliance on previously stable anchors
      withdrawal_bias    float [0,1]  — preference for social retreat
      output_simplify    float [0,1]  — pressure to reduce response complexity
    """

    _RISK_EMA = 0.10
    _MEM_DECAY = 0.985
    _MISJUDGE_EMA = 0.08
    _COLLAPSE_BOOST = 0.26
    _PRECLEAR_THRESH = 0.58
    _HIGH_RISK = 0.67
    _LOW_RISK = 0.32

    def __init__(self) -> None:
        self.instability_risk: float = 0.25
        self.caution_bias: float = 0.15
        self.underreaction: bool = False
        self.overreaction: bool = False
        self.recent_collapse: bool = False
        self.anchor_pull: float = 0.0
        self.withdrawal_bias: float = 0.0
        self.output_simplify: float = 0.0
        self.collapse_memory: float = 0.0
        self.mode_avoidance: Dict[str, float] = {
            "explore": 0.0,
            "search": 0.0,
            "execute": 0.0,
            "interact": 0.0,
            "respond": 0.0,
            "rest": 0.0,
            "consolidate": 0.0,
        }
        self._ema_raw_risk: float = 0.25
        self._ema_misjudge: float = 0.0
        self._collapse_ticks: int = 0
        self._risk_history: List[float] = []

    def update(
        self,
        entropy: float,
        fragmentation: float,
        goal_churn: float,
        temporal_incoherence: float,
        conflict_score: float,
        misalignment: float,
        behavioral_bleed: float,
        runaway_active: bool,
        mask_broken: bool,
        withdrawal_signal: float,
        fds_state: str,
        anchor_available: bool,
        active_goal_mode: str,
        stream: List[str],
    ) -> None:
        import random as _rnd_p16

        _raw_risk = (
            entropy * 0.20
            + fragmentation * 0.20
            + goal_churn * 0.16
            + temporal_incoherence * 0.12
            + conflict_score * 0.10
            + misalignment * 0.08
            + behavioral_bleed * 0.08
            + withdrawal_signal * 0.06
        )
        if runaway_active:
            _raw_risk += 0.14
        if mask_broken:
            _raw_risk += 0.10
        if fds_state == "pre_collapse":
            _raw_risk += 0.16
        elif fds_state == "collapse":
            _raw_risk += self._COLLAPSE_BOOST

        _raw_risk = max(0.0, min(1.0, _raw_risk))
        self._ema_raw_risk = (
            (1 - self._RISK_EMA) * self._ema_raw_risk + self._RISK_EMA * _raw_risk
        )

        if fds_state == "collapse":
            self.collapse_memory = min(1.0, self.collapse_memory + self._COLLAPSE_BOOST)
            self._collapse_ticks = 40
        else:
            self.collapse_memory *= self._MEM_DECAY
            self._collapse_ticks = max(0, self._collapse_ticks - 1)
        self.recent_collapse = self._collapse_ticks > 0 or self.collapse_memory > 0.18

        _misjudge_target = 0.0
        if self._ema_raw_risk > self._HIGH_RISK and _rnd_p16.random() < 0.18:
            _misjudge_target = -0.16
            self.underreaction = True
            self.overreaction = False
        elif self._ema_raw_risk < 0.55 and _rnd_p16.random() < 0.14:
            _misjudge_target = +0.12
            self.overreaction = True
            self.underreaction = False
        else:
            self.underreaction = False
            self.overreaction = False
        self._ema_misjudge = (
            (1 - self._MISJUDGE_EMA) * self._ema_misjudge
            + self._MISJUDGE_EMA * _misjudge_target
        )

        self.instability_risk = max(
            0.0,
            min(
                1.0,
                self._ema_raw_risk + self.collapse_memory * 0.30 + self._ema_misjudge,
            ),
        )
        self.caution_bias = max(
            0.0,
            min(1.0, self.instability_risk * 0.75 + self.collapse_memory * 0.25),
        )
        self.anchor_pull = min(
            1.0,
            (0.35 if anchor_available else 0.0)
            + self.caution_bias * 0.45
            + self.collapse_memory * 0.25,
        )
        self.withdrawal_bias = max(
            0.0,
            min(1.0, withdrawal_signal * 0.55 + max(0.0, self.instability_risk - 0.45)),
        )
        self.output_simplify = max(
            0.0,
            min(1.0, self.caution_bias * 0.60 + fragmentation * 0.20 + entropy * 0.20),
        )

        for _mode in list(self.mode_avoidance.keys()):
            self.mode_avoidance[_mode] *= 0.992
        if active_goal_mode in self.mode_avoidance and (
            fds_state in ("pre_collapse", "collapse") or runaway_active
        ):
            _bump = 0.10 + (0.12 if fds_state == "collapse" else 0.0)
            self.mode_avoidance[active_goal_mode] = min(
                1.0, self.mode_avoidance[active_goal_mode] + _bump
            )

        self._risk_history.append(self.instability_risk)
        if len(self._risk_history) > 60:
            self._risk_history.pop(0)

        if self.instability_risk > self._PRECLEAR_THRESH and len(self._risk_history) >= 8:
            _recent = sum(self._risk_history[-8:]) / 8.0
            if _recent > self._PRECLEAR_THRESH:
                stream.append(
                    f"[P16 INSTABILITY-RISK risk={self.instability_risk:.2f} "
                    f"caution={self.caution_bias:.2f} collapse_mem={self.collapse_memory:.2f}]"
                )

    def penalty_for_mode(self, mode: str) -> float:
        _avoid = self.mode_avoidance.get(mode, 0.0)
        return max(0.40, 1.0 - _avoid * (0.35 + self.caution_bias * 0.30))


# ─────────────────────────────────────────────────────────────────────────────
# Phase 17: Irreversible Identity Drift
# ─────────────────────────────────────────────────────────────────────────────


class IrreversibleIdentityDrift:
    """Path-dependent identity change from accumulated instability and growth.

    Recovery restores function but does not restore the original identity.
    This layer records gradual, sticky shifts in learned tendencies and deeper
    structural drift so identical present states can still yield different
    behavior when their histories diverge.

    Learned tendencies:
      initiative            — willingness to self-start and act
      trust_baseline        — default openness to social engagement
      assertiveness         — confidence and forward pressure in action
      switching_flexibility — ease of changing modes without defensive friction

    Deep drift:
      scar_index            — accumulated cost of collapse/instability history
      resilience_index      — growth earned through successful adaptation
      novelty_tolerance     — long-term willingness to tolerate uncertainty
      defensive_readiness   — tendency to activate guarded strategies quickly
      passivity_habit       — inertial drift toward low-initiative modes
    """

    _SCAR_LR = 0.010
    _GROWTH_LR = 0.008
    _SOCIAL_LR = 0.007
    _PASSIVITY_LR = 0.006
    _MICRO_DECAY = 0.001

    def __init__(self) -> None:
        self.scar_index: float = 0.05
        self.resilience_index: float = 0.10
        self.initiative: float = 0.52
        self.trust_baseline: float = 0.50
        self.assertiveness: float = 0.50
        self.switching_flexibility: float = 0.55
        self.novelty_tolerance: float = 0.50
        self.defensive_readiness: float = 0.20
        self.passivity_habit: float = 0.10
        self.nostalgia_pull: float = 0.0
        self.self_mismatch: float = 0.0
        self.narrative_lens: str = "adaptive"
        self.mode_imprint: Dict[str, float] = {
            "rest": 0.0,
            "consolidate": 0.0,
            "explore": 0.0,
            "search": 0.0,
            "execute": 0.0,
            "interact": 0.0,
            "respond": 0.0,
        }

    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return max(lo, min(hi, v))

    def update(
        self,
        instability_risk: float,
        caution_bias: float,
        recent_collapse: bool,
        social_trust: float,
        withdrawal_bias: float,
        action_success: float,
        active_goal_mode: str,
        anchor_pull: float,
        mask_broken: bool,
        stream: List[str],
    ) -> None:
        _passive_mode = active_goal_mode in ("rest", "consolidate", "sleep", "observe")
        _rejection = max(0.0, 0.45 - social_trust) * (1.0 + withdrawal_bias)
        _success_gain = max(0.0, action_success - 0.55)
        _instab_load = max(0.0, instability_risk - 0.45)

        self.scar_index = self._clamp(
            self.scar_index
            + _instab_load * self._SCAR_LR
            + (_rejection * self._SOCIAL_LR)
            + (0.020 if recent_collapse else 0.0)
            - self.resilience_index * self._MICRO_DECAY
        )
        self.resilience_index = self._clamp(
            self.resilience_index
            + _success_gain * self._GROWTH_LR
            + (1.0 - instability_risk) * 0.0015
            - (0.010 if recent_collapse else 0.0)
        )

        self.trust_baseline = self._clamp(
            self.trust_baseline
            - _rejection * self._SOCIAL_LR
            - (0.010 if mask_broken else 0.0)
            + max(0.0, social_trust - 0.60) * 0.003
        )
        self.assertiveness = self._clamp(
            self.assertiveness
            + _success_gain * 0.010
            - _instab_load * 0.006
            - _rejection * 0.003
        )
        self.initiative = self._clamp(
            self.initiative
            + _success_gain * 0.008
            - (_passive_mode * self._PASSIVITY_LR)
            - _instab_load * 0.004
        )
        self.passivity_habit = self._clamp(
            self.passivity_habit
            + (_passive_mode * self._PASSIVITY_LR)
            + caution_bias * 0.002
            - _success_gain * 0.003
        )

        self.switching_flexibility = self._clamp(
            0.55
            + self.resilience_index * 0.25
            - self.scar_index * 0.35
            - self.passivity_habit * 0.20,
            0.05,
            0.95,
        )
        self.novelty_tolerance = self._clamp(
            0.50
            + self.resilience_index * 0.30
            - self.scar_index * 0.35
            - caution_bias * 0.15,
            0.05,
            0.95,
        )
        self.defensive_readiness = self._clamp(
            0.18
            + self.scar_index * 0.55
            + _rejection * 0.20
            + caution_bias * 0.15
            - self.resilience_index * 0.12,
            0.0,
            0.98,
        )

        self.nostalgia_pull = self._clamp(anchor_pull * (0.35 + self.scar_index * 0.50))
        self.self_mismatch = self._clamp(
            abs(self.initiative - (0.50 + self.resilience_index * 0.25))
            * 0.60
            + self.nostalgia_pull * 0.40
        )

        for _mode in list(self.mode_imprint.keys()):
            self.mode_imprint[_mode] *= 0.996
        if active_goal_mode in self.mode_imprint:
            _delta = 0.0
            if recent_collapse or instability_risk > 0.68:
                _delta += 0.05 + _instab_load * 0.10
            elif _success_gain > 0.0:
                _delta -= _success_gain * 0.04
            self.mode_imprint[active_goal_mode] = self._clamp(
                self.mode_imprint[active_goal_mode] + _delta
            )

        if self.scar_index > self.resilience_index + 0.08:
            self.narrative_lens = "warning"
        elif self.resilience_index > self.scar_index + 0.10:
            self.narrative_lens = "growth"
        else:
            self.narrative_lens = "adaptive"

        if recent_collapse and self.scar_index > 0.18:
            stream.append(
                f"[P17 ID-DRIFT scar={self.scar_index:.2f} resil={self.resilience_index:.2f} "
                f"initiative={self.initiative:.2f} lens={self.narrative_lens}]"
            )

    def goal_multipliers(self) -> Dict[str, float]:
        _safe_pull = self.scar_index * 0.40 + self.passivity_habit * 0.25 + self.nostalgia_pull * 0.20
        _growth_pull = self.resilience_index * 0.35 + self.initiative * 0.15
        _social_guard = (1.0 - self.trust_baseline) * 0.25 + self.defensive_readiness * 0.20
        return {
            "rest": 1.0 + _safe_pull,
            "consolidate": 1.0 + _safe_pull * 0.95 + self.defensive_readiness * 0.10,
            "explore": 1.0 + _growth_pull - self.scar_index * 0.45 - self.novelty_tolerance * -0.15,
            "search": 1.0 + _growth_pull * 0.70 - self.scar_index * 0.32,
            "execute": 1.0 + self.assertiveness * 0.25 + self.resilience_index * 0.15 - self.scar_index * 0.30,
            "interact": 1.0 + self.trust_baseline * 0.20 - _social_guard,
            "respond": 1.0 + self.trust_baseline * 0.15 + self.assertiveness * 0.10 - _social_guard * 0.75,
        }

    def switch_multiplier(self, next_mode: str, current_mode: str) -> float:
        if not current_mode or next_mode == current_mode:
            return 1.0
        _friction = (1.0 - self.switching_flexibility) * 0.40 + self.nostalgia_pull * 0.20
        return max(0.55, 1.0 - _friction)

    def identity_cost(self, mode: str) -> float:
        _imprint = self.mode_imprint.get(mode, 0.0)
        if mode in ("explore", "search", "execute"):
            return self._clamp(self.scar_index * 0.45 + _imprint * 0.35)
        if mode in ("interact", "respond"):
            return self._clamp((1.0 - self.trust_baseline) * 0.30 + _imprint * 0.25)
        return self._clamp(_imprint * 0.12)


