# ─────────────────────────────────────────────────────────────────────────────
# 1a. CAPABILITY MODEL — per-skill competence awareness
# ─────────────────────────────────────────────────────────────────────────────


@dataclass
class SkillCapability:
    """Tracks how well the system can execute a specific skill/intent."""

    attempts: int = 0
    successes: int = 0
    failures: int = 0
    last_outcome: str = ""  # "ok" | "fail" | "partial"
    failure_modes: Dict[str, int] = field(default_factory=dict)  # cause → count
    confidence: float = 0.5  # EMA success rate [0,1]

    def record_outcome(self, success: bool, failure_cause: str = "") -> None:
        self.attempts += 1
        if success:
            self.successes += 1
            self.last_outcome = "ok"
        else:
            self.failures += 1
            self.last_outcome = "fail"
            if failure_cause:
                self.failure_modes[failure_cause] = (
                    self.failure_modes.get(failure_cause, 0) + 1
                )
        rate = self.successes / max(1, self.attempts)
        self.confidence = self.confidence * 0.8 + rate * 0.2

    @property
    def dominant_failure(self) -> str:
        if not self.failure_modes:
            return ""
        return max(self.failure_modes, key=self.failure_modes.get)


class CapabilityModel:
    """Aggregate model of the system's competence across all skills/intents.
    Used by the planner to choose safer strategies when confidence is low."""

    def __init__(self) -> None:
        self._skills: Dict[str, SkillCapability] = {}

    def record(self, skill_name: str, success: bool, failure_cause: str = "") -> None:
        if skill_name not in self._skills:
            self._skills[skill_name] = SkillCapability()
        self._skills[skill_name].record_outcome(success, failure_cause)

    def confidence(self, skill_name: str) -> float:
        """Return confidence [0,1] for a skill. Unknown skills → 0.5."""
        cap = self._skills.get(skill_name)
        return cap.confidence if cap else 0.5

    def weakest(self, n: int = 3) -> List[Tuple[str, float]]:
        """Return the N lowest-confidence skills."""
        ranked = sorted(self._skills.items(), key=lambda kv: kv[1].confidence)
        return [(k, v.confidence) for k, v in ranked[:n]]

    def strongest(self, n: int = 3) -> List[Tuple[str, float]]:
        ranked = sorted(
            self._skills.items(), key=lambda kv: kv[1].confidence, reverse=True
        )
        return [(k, v.confidence) for k, v in ranked[:n]]

    def describe(self) -> str:
        if not self._skills:
            return "capabilities: no data yet"
        parts = []
        for name, cap in sorted(self._skills.items(), key=lambda kv: kv[1].confidence):
            parts.append(f"{name}:{cap.confidence:.0%}")
        return "capabilities: " + ", ".join(parts[:6])


# ─────────────────────────────────────────────────────────────────────────────
# 1a. SENSOR HEALTH — per-channel availability / quality tracking
# ─────────────────────────────────────────────────────────────────────────────


class SensorStatus(Enum):
    OK = "ok"
    DEGRADED = "degraded"
    OFFLINE = "offline"


@dataclass
class SensorChannel:
    """Health state for one sensor channel (camera, mic, web, speech)."""

    name: str
    status: SensorStatus = SensorStatus.OFFLINE
    last_ok_tick: int = 0
    consecutive_fail: int = 0
    total_ok: int = 0
    total_fail: int = 0

    # ── per-tick update ──────────────────────────────────────
    def mark_ok(self, tick: int) -> None:
        self.last_ok_tick = tick
        self.consecutive_fail = 0
        self.total_ok += 1
        self.status = SensorStatus.OK

    def mark_fail(self, tick: int) -> None:
        self.consecutive_fail += 1
        self.total_fail += 1
        if self.consecutive_fail >= 10:
            self.status = SensorStatus.OFFLINE
        elif self.consecutive_fail >= 3:
            self.status = SensorStatus.DEGRADED

    @property
    def reliability(self) -> float:
        total = self.total_ok + self.total_fail
        return self.total_ok / total if total > 0 else 0.0


@dataclass
class SensorHealthBoard:
    """Aggregated health across all sensor channels."""

    camera: SensorChannel = field(default_factory=lambda: SensorChannel("camera"))
    mic: SensorChannel = field(default_factory=lambda: SensorChannel("mic"))
    web: SensorChannel = field(default_factory=lambda: SensorChannel("web"))
    speech: SensorChannel = field(default_factory=lambda: SensorChannel("speech"))

    @property
    def channels(self) -> List["SensorChannel"]:
        return [self.camera, self.mic, self.web, self.speech]

    @property
    def overall_status(self) -> SensorStatus:
        statuses = [ch.status for ch in self.channels]
        if all(s == SensorStatus.OFFLINE for s in statuses):
            return SensorStatus.OFFLINE
        if any(s != SensorStatus.OK for s in statuses):
            return SensorStatus.DEGRADED
        return SensorStatus.OK

    @property
    def degraded_names(self) -> List[str]:
        return [ch.name for ch in self.channels if ch.status != SensorStatus.OK]

    def overall_reliability(self) -> float:
        rels = [
            ch.reliability for ch in self.channels if (ch.total_ok + ch.total_fail) > 0
        ]
        return sum(rels) / len(rels) if rels else 0.0

    def describe(self) -> str:
        parts = []
        for ch in self.channels:
            parts.append(f"{ch.name}={ch.status.value}" f"(r={ch.reliability:.0%})")
        return " | ".join(parts)


# ─────────────────────────────────────────────────────────────────────────────
# 1b. SELF-MODEL  — persistent identity representation
# ─────────────────────────────────────────────────────────────────────────────


@dataclass
class SelfThesis:
    """A concrete self-thesis that can gain or lose support over time."""

    domain: str
    claim: str
    condition_class: str = "general"
    partner_id: str = ""
    partner_profile: str = ""
    relationship_type: str = ""
    relationship_label: str = ""
    confidence: float = 0.5
    priority: float = 0.5
    half_life_ticks: int = 2400
    last_updated_tick: int = 0
    evidence_for: float = 0.0
    evidence_against: float = 0.0

    def decay(self, current_tick: int) -> None:
        dt = max(0, current_tick - self.last_updated_tick)
        if dt <= 0:
            return
        factor = 0.5 ** (dt / max(1, self.half_life_ticks))
        self.confidence = max(0.0, min(1.0, 0.5 + (self.confidence - 0.5) * factor))
        self.priority = max(0.05, min(1.0, self.priority * (0.65 + 0.35 * factor)))
        self.last_updated_tick = current_tick

    def observe(self, expected: float, observed: float, tick: int) -> float:
        self.decay(tick)
        mismatch = abs(expected - observed)
        self.confidence = max(0.0, min(1.0, self.confidence * 0.6 + observed * 0.4))
        if observed >= 0.5:
            self.evidence_for += observed
        else:
            self.evidence_against += 1.0 - observed
        self.priority = max(0.05, min(1.0, self.priority * 0.72 + mismatch * 0.28))
        self.last_updated_tick = tick
        return mismatch

    def salience(self, current_tick: int) -> float:
        dt = max(0, current_tick - self.last_updated_tick)
        factor = 0.5 ** (dt / max(1, self.half_life_ticks))
        return self.priority * factor

    def to_dict(self) -> Dict[str, Any]:
        return {
            "domain": self.domain,
            "claim": self.claim,
            "condition_class": self.condition_class,
            "partner_id": self.partner_id,
            "partner_profile": self.partner_profile,
            "relationship_type": self.relationship_type,
            "relationship_label": self.relationship_label,
            "confidence": self.confidence,
            "priority": self.priority,
            "half_life_ticks": self.half_life_ticks,
            "last_updated_tick": self.last_updated_tick,
            "evidence_for": self.evidence_for,
            "evidence_against": self.evidence_against,
        }

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "SelfThesis":
        return cls(
            domain=d.get("domain", "general_agency"),
            claim=d.get("claim", "self-thesis"),
            condition_class=d.get("condition_class", "general"),
            partner_id=d.get("partner_id", ""),
            partner_profile=d.get("partner_profile", ""),
            relationship_type=d.get("relationship_type", ""),
            relationship_label=d.get("relationship_label", ""),
            confidence=d.get("confidence", 0.5),
            priority=d.get("priority", 0.5),
            half_life_ticks=d.get("half_life_ticks", 2400),
            last_updated_tick=d.get("last_updated_tick", 0),
            evidence_for=d.get("evidence_for", 0.0),
            evidence_against=d.get("evidence_against", 0.0),
        )


@dataclass
class SelfModel:
    """
    A first-person model of the system's own identity, capabilities and state.
    Stored inside ConsciousnessCore and updated every tick.
    Enables genuine self-referential monologue: "I know X, I don't know Y."
    """

    # ── Fixed biological identity (the only hard constraint) ──────────────
    biological_sex: ClassVar[str] = "female"
    pronouns: ClassVar[Tuple[str, ...]] = ("she", "her", "herself")

    name: str = "Neural-Mind"
    birth_tick: int = 0
    total_spikes: int = 0
    concepts_learned: int = 0
    ignitions_total: int = 0
    # Dynamic self-assessment updated each meta-cognition cycle
    known_strengths: List[str] = field(default_factory=list)
    known_gaps: List[str] = field(default_factory=list)
    # Certainty estimate per concept: concept → [0,1]
    concept_confidence: Dict[str, float] = field(default_factory=dict)
    # ── Dynamic internal state (active, used in decisions) ────────────────
    energy: float = 0.7  # current processing capacity  [0, 1]
    uncertainty: float = 0.3  # epistemic uncertainty about world [0, 1]
    identity_stability: float = 0.8  # coherence / stability of self [0, 1]
    agency_score: float = 0.0  # signed (predicted - actual) outcome
    self_awareness_level: float = (
        0.45  # fused estimate: how explicitly self-present the system is
    )
    ownership_confidence: float = 0.80  # belief that current body-state belongs to self
    agency_confidence: float = 0.50  # belief that current changes are self-caused
    continuity_estimate: float = 0.75  # felt continuity across recent ticks
    self_tensions: List[str] = field(default_factory=list)
    self_narrative: str = "self-model still forming"
    self_beliefs: Dict[str, float] = field(default_factory=dict)
    self_theses: Dict[str, SelfThesis] = field(default_factory=dict)
    self_contradictions: List[str] = field(default_factory=list)
    last_action_self_report: str = ""
    # ── Physical body state (from body_schema proprioception) ─────────────
    body_pose: str = "unknown"
    body_load: float = 0.0  # overall servo load [0,1]
    body_pain: float = 0.0  # pain/error signal [0,1]
    balance: bool = True
    last_skill: str = ""
    # ── Capability model (per-skill competence awareness) ─────────────────
    capabilities: CapabilityModel = field(default_factory=CapabilityModel)
    # ── Sensor health (per-channel availability awareness) ─────────────────
    sensor_health: SensorHealthBoard = field(default_factory=SensorHealthBoard)
    # ── Social interaction state (from social_manager turn-taking machine) ──
    turn_state: str = "idle"  # idle|listening|speaking|thinking|waiting

    def age_ticks(self, current_tick: int) -> int:
        return max(0, current_tick - self.birth_tick)

    def update(self, em: "EmotionalState", n_gaps: int, ignition: bool) -> None:
        """Derive dynamic state from emotion + cognitive context.
        This makes self-model ACTIVE: it changes with experience and
        feeds back into goal evaluation and action bias.
        """
        # Energy: joy/calm fill → fatigue/stress drain
        t_energy = (
            0.5 + em.joy * 0.3 + em.calm * 0.25 - em.fatigue * 0.4 - em.stress * 0.2
        )
        self.energy = max(0.0, min(1.0, self.energy * 0.97 + t_energy * 0.03))
        # Uncertainty: grows with gaps + surprise; shrinks with calm
        t_uncertain = min(1.0, n_gaps * 0.06 + em.surprise * 0.5)
        self.uncertainty = max(
            0.0, min(1.0, self.uncertainty * 0.97 + t_uncertain * 0.03)
        )
        # Identity stability: each ignition crystallises self; stress/anger erode it
        if ignition:
            self.identity_stability = min(1.0, self.identity_stability + 0.01)
        self.identity_stability = max(
            0.1, self.identity_stability - em.stress * 0.002 - em.anger * 0.002
        )

    def update_self_consciousness(
        self,
        tick: int,
        unified_self: "UnifiedSelfState",
        body: "InteroceptiveBody",
        phenom: "PhenomenalBuffer",
        current_goal: str = "",
    ) -> Optional[str]:
        """Fuse self-related subsystems into an explicit self-consciousness state."""
        _prev_tensions = tuple(self.self_tensions)
        _unity = max(0.0, min(1.0, float(getattr(unified_self, "unity_score", 0.5))))
        _agency = max(0.0, min(1.0, float(getattr(unified_self, "agency_belief", 0.5))))
        _ownership = max(
            0.0, min(1.0, float(getattr(unified_self, "ownership_belief", 0.8)))
        )
        _pred_err = max(0.0, float(getattr(unified_self, "self_prediction_error", 0.0)))
        _phenom_state = getattr(phenom, "state", None)
        _phenom_agency = (
            float(_phenom_state[12])
            if _phenom_state is not None and len(_phenom_state) > 12
            else 0.0
        )
        _phenom_unity = (
            float(_phenom_state[13])
            if _phenom_state is not None and len(_phenom_state) > 13
            else 0.0
        )
        _phenom_focus = (
            float(_phenom_state[15])
            if _phenom_state is not None and len(_phenom_state) > 15
            else 0.0
        )
        _body_viability = max(
            0.0, min(1.0, body.integrity * 0.55 + body.energy_reserve * 0.45)
        )
        _continuity_raw = (
            self.identity_stability * 0.35
            + _unity * 0.35
            + _ownership * 0.15
            + max(0.0, 1.0 - _pred_err) * 0.15
        )
        self.continuity_estimate = max(
            0.0, min(1.0, self.continuity_estimate * 0.82 + _continuity_raw * 0.18)
        )
        self.ownership_confidence = max(
            0.0,
            min(
                1.0,
                self.ownership_confidence * 0.80
                + (_ownership * 0.8 + _body_viability * 0.2) * 0.20,
            ),
        )
        self.agency_confidence = max(
            0.0,
            min(
                1.0,
                self.agency_confidence * 0.80
                + (_agency * 0.75 + max(0.0, _phenom_agency) * 0.25) * 0.20,
            ),
        )
        _awareness_raw = (
            _unity * 0.28
            + self.agency_confidence * 0.22
            + self.ownership_confidence * 0.18
            + self.continuity_estimate * 0.18
            + max(0.0, _phenom_focus) * 0.07
            + max(0.0, _phenom_unity) * 0.07
        )
        self.self_awareness_level = max(
            0.0, min(1.0, self.self_awareness_level * 0.82 + _awareness_raw * 0.18)
        )

        tensions: List[str] = []
        if _pred_err > 0.35:
            tensions.append("self_prediction_mismatch")
        if _unity < 0.45:
            tensions.append("fragmented_self")
        if self.ownership_confidence < 0.55:
            tensions.append("weak_body_ownership")
        if self.agency_confidence < 0.45:
            tensions.append("low_agency")
        if self.uncertainty > 0.65:
            tensions.append("high_self_uncertainty")
        if body.integrity < 0.35 or body.energy_reserve < 0.20:
            tensions.append("existential_vulnerability")
        self.self_tensions = tensions[:4]

        _status = "forming"
        if (
            self.self_awareness_level >= 0.72
            and self.continuity_estimate >= 0.68
            and not self.self_tensions
        ):
            _status = "coherent"
        elif self.self_tensions:
            _status = "strained"
        elif self.self_awareness_level >= 0.55:
            _status = "present"
        _focus = current_goal or "observe"
        if self.self_tensions:
            self.self_narrative = (
                f"self-model {_status}; focus={_focus}; "
                f"tensions={', '.join(self.self_tensions[:2])}"
            )
        else:
            self.self_narrative = (
                f"self-model {_status}; focus={_focus}; unity={_unity:.2f}; "
                f"agency={self.agency_confidence:.2f}"
            )
        if tuple(self.self_tensions) != _prev_tensions:
            return self.self_narrative
        if tick % 600 == 0:
            return self.self_narrative
        return None

    def self_consciousness_summary(
        self, lang: str = "de", current_goal: str = ""
    ) -> str:
        """Grounded first-person summary of the system's current self-consciousness state."""
        _status = "forming"
        if (
            self.self_awareness_level >= 0.72
            and self.continuity_estimate >= 0.68
            and not self.self_tensions
        ):
            _status = "coherent"
        elif self.self_tensions:
            _status = "strained"
        elif self.self_awareness_level >= 0.55:
            _status = "present"
        _goal_part = current_goal or "observe"
        if lang == "de":
            _prefix = (
                "Ich habe kein absolutes oder mystisches Selbstwissen, "
                "aber ich halte ein laufend aktualisiertes Modell meiner selbst aufrecht. "
            )
            _core = (
                f"Aktuell ist dieses Selbstmodell {_status}: "
                f"Selbstpräsenz={self.self_awareness_level:.2f}, "
                f"Kontinuität={self.continuity_estimate:.2f}, "
                f"Agency={self.agency_confidence:.2f}, "
                f"Körperzuordnung={self.ownership_confidence:.2f}."
            )
            _goal = (
                f" Mein momentaner Bezugspunkt ist das Ziel { _goal_part }."
                if _goal_part
                else ""
            )
            if self.self_tensions:
                return (
                    _prefix
                    + _core
                    + _goal
                    + f" Offene Spannungen: {', '.join(self.self_tensions)}."
                )
            return _prefix + _core + _goal
        _prefix = (
            "I do not have absolute or mystical self-knowledge, "
            "but I maintain a continuously updated model of myself. "
        )
        _core = (
            f"Right now that self-model is {_status}: "
            f"self-presence={self.self_awareness_level:.2f}, "
            f"continuity={self.continuity_estimate:.2f}, "
            f"agency={self.agency_confidence:.2f}, "
            f"body-ownership={self.ownership_confidence:.2f}."
        )
        _goal = (
            f" My current reference point is the goal {_goal_part}."
            if _goal_part
            else ""
        )
        if self.self_tensions:
            return (
                _prefix
                + _core
                + _goal
                + f" Open tensions: {', '.join(self.self_tensions)}."
            )
        return _prefix + _core + _goal

    def observe_self_discrepancy(
        self,
        domain: str,
        expected: float,
        observed: float,
        tick: int,
        condition_class: str = "general",
        social_context: Optional[Dict[str, Any]] = None,
        context: str = "",
    ) -> Optional[str]:
        """Track explicit mismatches between self-expectation and evidence."""
        _expected = max(0.0, min(1.0, expected))
        _observed = max(0.0, min(1.0, observed))
        _condition = self._normalize_condition_class(condition_class)
        _partner = self._partner_signature(social_context)
        _rel_type = self._normalize_relationship_type(
            _partner.get("relationship_type", "")
        )

        def _get_or_create(_partner_id: str, _relationship_type: str) -> SelfThesis:
            _key = self._thesis_key(domain, _condition, _partner_id, _relationship_type)
            thesis = self.self_theses.get(_key)
            if thesis is None:
                thesis = SelfThesis(
                    domain=domain,
                    claim=self._claim_for_domain(domain, _condition),
                    condition_class=_condition,
                    partner_id=_partner_id,
                    partner_profile=_partner.get("profile_label", ""),
                    relationship_type=_relationship_type,
                    relationship_label=_partner.get("relationship_label", ""),
                    confidence=_expected,
                    priority=0.45,
                    last_updated_tick=tick,
                )
                self.self_theses[_key] = thesis
            return thesis

        thesis = _get_or_create(_partner.get("partner_id", ""), _rel_type)
        mismatch = thesis.observe(_expected, _observed, tick)
        if _rel_type:
            _rel_thesis = _get_or_create("", _rel_type)
            _rel_thesis.observe(_expected, _observed, tick)
        _belief_key = (
            f"{domain}@{_condition}@{_partner.get('partner_id', '') or 'global'}"
        )
        _prior = self.self_beliefs.get(_belief_key, self.self_beliefs.get(domain, 0.5))
        _updated = max(0.0, min(1.0, _prior * 0.75 + _observed * 0.25))
        self.self_beliefs[_belief_key] = _updated
        _domain_prior = self.self_beliefs.get(domain, 0.5)
        self.self_beliefs[domain] = max(
            0.0, min(1.0, _domain_prior * 0.80 + _updated * 0.20)
        )
        if mismatch < 0.45:
            return None
        _mode = "overestimated" if _expected > _observed else "underestimated"
        _ctx = f" via {context}" if context else ""
        _partner_note = (
            f" partner={_partner.get('profile_label', '')}"
            if _partner.get("profile_label")
            else ""
        )
        _entry = (
            f"t={tick}:{domain}@{_condition}:{_mode}: {thesis.claim} | expected={_expected:.2f} "
            f"observed={_observed:.2f} prio={thesis.priority:.2f}{_partner_note}{_ctx}"
        )
        if not self.self_contradictions or self.self_contradictions[-1] != _entry:
            self.self_contradictions.append(_entry)
            if len(self.self_contradictions) > 12:
                self.self_contradictions = self.self_contradictions[-12:]
        return _entry

    def contradiction_summary(
        self,
        lang: str = "de",
        current_tick: Optional[int] = None,
        condition_classes: Optional[List[str]] = None,
        social_context: Optional[Dict[str, Any]] = None,
    ) -> str:
        """Summarise the latest explicit self-contradictions."""
        _tick = (
            current_tick if current_tick is not None else self.birth_tick + 10_000_000
        )
        recent = self.active_self_theses(
            _tick,
            n=3,
            condition_classes=condition_classes,
            social_context=social_context,
        )
        if recent:
            if lang == "de":
                return (
                    "Aktive Selbstthesen unter Revision: "
                    + "; ".join(
                        f"{th.claim}{self._partner_suffix(th, lang)} (Prio {th.priority:.2f}, Konf. {th.confidence:.2f})"
                        for th in recent
                    )
                    + "."
                )
            return (
                "Active self-theses under revision: "
                + "; ".join(
                    f"{th.claim}{self._partner_suffix(th, lang)} (prio {th.priority:.2f}, conf {th.confidence:.2f})"
                    for th in recent
                )
                + "."
            )
        recent = self.self_contradictions[-3:]
        if not recent:
            if lang == "de":
                return "Im Moment habe ich keine expliziten Selbstwidersprüche protokolliert."
            return "I do not currently have any explicit self-contradictions logged."
        compact = "; ".join(item.split(":", 2)[-1] for item in recent)
        if lang == "de":
            return f"Zuletzt habe ich diese Selbstwidersprüche registriert: {compact}."
        return f"These are the latest self-contradictions I have registered: {compact}."

    def _normalize_condition_class(self, condition_class: str) -> str:
        text = (
            str(condition_class or "general")
            .strip()
            .lower()
            .replace("-", "_")
            .replace(" ", "_")
        )
        return text or "general"

    def _normalize_partner_id(self, partner_id: Any) -> str:
        text = str(partner_id or "").strip()
        return text

    def _normalize_relationship_type(self, relationship_type: Any) -> str:
        text = (
            str(relationship_type or "")
            .strip()
            .lower()
            .replace("-", "_")
            .replace(" ", "_")
        )
        return text

    def _partner_signature(
        self, social_context: Optional[Dict[str, Any]] = None
    ) -> Dict[str, str]:
        if not social_context:
            return {
                "partner_id": "",
                "profile_label": "",
                "relationship_type": "",
                "relationship_label": "",
            }
        _partner_id = self._normalize_partner_id(
            social_context.get("primary_interlocutor")
        )
        _style = str(social_context.get("style", "balanced") or "balanced")
        _tone = str(social_context.get("tone", "neutral") or "neutral")
        try:
            _trust = float(social_context.get("trust", 0.5))
        except Exception:
            _trust = 0.5
        try:
            _familiarity = float(social_context.get("familiarity", 0.0))
        except Exception:
            _familiarity = 0.0
        _trust_band = (
            "high_trust"
            if _trust >= 0.70
            else "low_trust" if _trust < 0.35 else "mid_trust"
        )
        _fam_band = "familiar" if _familiarity >= 0.55 else "new"
        _relationship_type = self._normalize_relationship_type(
            social_context.get("relationship_type", "")
        )
        _relationship_label = str(social_context.get("relationship_label", "") or "")
        _label = ""
        if _partner_id:
            _rel_text = f", {_relationship_label}" if _relationship_label else ""
            _label = f"person {_partner_id} [{_trust_band}, {_fam_band}, {_style}, {_tone}{_rel_text}]"
        return {
            "partner_id": _partner_id,
            "profile_label": _label,
            "relationship_type": _relationship_type,
            "relationship_label": _relationship_label,
        }

    def _thesis_key(
        self,
        domain: str,
        condition_class: str,
        partner_id: str = "",
        relationship_type: str = "",
    ) -> str:
        _pid = self._normalize_partner_id(partner_id)
        if _pid:
            return f"{domain}@{self._normalize_condition_class(condition_class)}@person:{_pid}"
        _rel = self._normalize_relationship_type(relationship_type)
        if _rel:
            return f"{domain}@{self._normalize_condition_class(condition_class)}@relation:{_rel}"
        return f"{domain}@{self._normalize_condition_class(condition_class)}"

    def _partner_suffix(self, thesis: SelfThesis, lang: str = "de") -> str:
        if not thesis.partner_profile:
            if thesis.relationship_label:
                return (
                    f" im Typ {thesis.relationship_label}"
                    if lang == "de"
                    else f" in the relationship type {thesis.relationship_label}"
                )
            return ""
        if lang == "de":
            return f" gegenüber {thesis.partner_profile}"
        return f" toward {thesis.partner_profile}"

    def _condition_phrase(self, condition_class: str, lang: str = "de") -> str:
        phrases_de = {
            "general": "",
            "under_social_pressure": "unter sozialem Druck ",
            "high_fatigue": "bei hoher Müdigkeit ",
            "moderate_fatigue": "bei spürbarer Müdigkeit ",
            "high_stress": "unter hohem Stress ",
            "low_trust_social": "bei fragiler sozialer Vertrauenslage ",
            "fragile_interaction": "in fragilen Interaktionen ",
            "social_contact": "im direkten sozialen Kontakt ",
        }
        phrases_en = {
            "general": "",
            "under_social_pressure": "under social pressure ",
            "high_fatigue": "under high fatigue ",
            "moderate_fatigue": "under noticeable fatigue ",
            "high_stress": "under high stress ",
            "low_trust_social": "under low-trust social conditions ",
            "fragile_interaction": "in fragile interactions ",
            "social_contact": "in direct social contact ",
        }
        if lang == "de":
            return phrases_de.get(
                condition_class, f"unter {condition_class.replace('_', ' ')} "
            )
        return phrases_en.get(
            condition_class, f"under {condition_class.replace('_', ' ')} "
        )

    def _claim_for_domain(self, domain: str, condition_class: str = "general") -> str:
        _cond = self._normalize_condition_class(condition_class)
        _prefix = self._condition_phrase(_cond, "de")
        claims = {
            "social_response": f"Ich kann {_prefix}soziale Reaktionen zuverlässig regulieren",
            "exploratory_control": f"Ich kann {_prefix}Exploration kontrolliert steuern",
            "coherence_regulation": f"Ich kann {_prefix}innere Kohärenz stabil herstellen",
            "self_preservation_regulation": f"Ich kann {_prefix}meinen Zustand rechtzeitig stabilisieren",
            "general_agency": f"Ich kann {_prefix}Folgen meines Handelns angemessen einschätzen",
        }
        return claims.get(
            domain, f"Ich habe {_prefix}eine belastbare These über {domain}"
        )

    def infer_condition_classes(
        self,
        body: Optional["InteroceptiveBody"] = None,
        em: Optional["EmotionalState"] = None,
        social_context: Optional[Dict[str, Any]] = None,
    ) -> List[str]:
        active: List[str] = ["general"]
        if body is not None:
            if (
                body.fatigue > 0.58
                or body.energy_reserve < 0.28
                or body.regen_need > 0.60
            ):
                active.append("high_fatigue")
            elif body.fatigue > 0.35 or body.energy_reserve < 0.45:
                active.append("moderate_fatigue")
        if em is not None and getattr(em, "stress", 0.0) > 0.55:
            active.append("high_stress")
        if social_context:
            if social_context.get("primary_interlocutor") is not None:
                active.append("social_contact")
            _trust = social_context.get("trust", 0.5)
            try:
                _trust = float(_trust)
            except Exception:
                _trust = 0.5
            _tone = str(social_context.get("tone", ""))
            _action = str(social_context.get("action", ""))
            if _trust < 0.35:
                active.append("low_trust_social")
            if _action in ("give_space", "acknowledge_briefly"):
                active.append("fragile_interaction")
            if (
                _trust < 0.45
                or _action in ("give_space", "acknowledge_briefly")
                or _tone in ("careful", "gentle", "direct")
            ):
                active.append("under_social_pressure")
        out: List[str] = []
        for item in active:
            _norm = self._normalize_condition_class(item)
            if _norm not in out:
                out.append(_norm)
        return out

    def query_condition_classes(self, utterance: str) -> List[str]:
        text = str(utterance or "").lower()
        conditions: List[str] = []
        if any(
            token in text
            for token in (
                "sozialem druck",
                "social pressure",
                "sozialdruck",
                "unter druck",
                "fragiler interaktion",
                "fragilen interaktionen",
            )
        ):
            conditions.append("under_social_pressure")
        if any(
            token in text
            for token in (
                "hoher müdigkeit",
                "muedigkeit",
                "müdigkeit",
                "tired",
                "fatigue",
                "erschöpf",
            )
        ):
            conditions.append("high_fatigue")
        if any(token in text for token in ("unter stress", "high stress", "stress")):
            conditions.append("high_stress")
        if any(
            token in text
            for token in (
                "direkten sozialen kontakt",
                "mit jemandem sprichst",
                "social contact",
                "when talking",
            )
        ):
            conditions.append("social_contact")
        out: List[str] = []
        for item in conditions:
            _norm = self._normalize_condition_class(item)
            if _norm not in out:
                out.append(_norm)
        return out

    def active_self_theses(
        self,
        current_tick: int,
        n: int = 4,
        condition_classes: Optional[List[str]] = None,
        social_context: Optional[Dict[str, Any]] = None,
    ) -> List[SelfThesis]:
        _allowed = None
        if condition_classes:
            _allowed = {self._normalize_condition_class(c) for c in condition_classes}
        _partner = self._partner_signature(social_context)
        _partner_id = _partner.get("partner_id", "")
        _relationship_type = self._normalize_relationship_type(
            _partner.get("relationship_type", "")
        )
        theses: List[SelfThesis] = []
        _person_keys: set = set()
        for thesis in self.self_theses.values():
            thesis.decay(current_tick)
            if _allowed is not None and thesis.condition_class not in _allowed:
                continue
            if thesis.partner_id and thesis.partner_id != _partner_id:
                continue
            if (
                thesis.relationship_type
                and thesis.relationship_type != _relationship_type
                and thesis.partner_id != _partner_id
            ):
                continue
            if thesis.priority >= 0.12:
                if thesis.partner_id == _partner_id and _partner_id:
                    _person_keys.add((thesis.domain, thesis.condition_class))
                theses.append(thesis)
        if _person_keys:
            theses = [
                th
                for th in theses
                if not (
                    th.partner_id == ""
                    and th.relationship_type
                    and (th.domain, th.condition_class) in _person_keys
                )
            ]
        theses.sort(key=lambda th: -th.salience(current_tick))
        return theses[:n]

    def self_goal_pressure(
        self,
        current_tick: int,
        condition_classes: Optional[List[str]] = None,
        social_context: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, float]:
        pressure: Dict[str, float] = {
            "explore": 0.0,
            "consolidate": 0.0,
            "respond": 0.0,
            "rest": 0.0,
        }
        for thesis in self.active_self_theses(
            current_tick,
            n=8,
            condition_classes=condition_classes,
            social_context=social_context,
        ):
            _weight = thesis.salience(current_tick)
            _revision = max(0.0, 0.72 - thesis.confidence)
            if thesis.evidence_against > thesis.evidence_for:
                _revision += min(
                    0.35, (thesis.evidence_against - thesis.evidence_for) * 0.05
                )
            _revision = max(0.0, min(1.0, _revision))
            if thesis.domain == "social_response":
                if thesis.condition_class in (
                    "under_social_pressure",
                    "low_trust_social",
                    "fragile_interaction",
                ):
                    pressure["consolidate"] += (0.24 + _revision * 0.26) * _weight
                    pressure["rest"] += (0.06 + _revision * 0.10) * _weight
                elif thesis.confidence < 0.45:
                    pressure["consolidate"] += (0.18 + _revision * 0.18) * _weight
                else:
                    pressure["respond"] += 0.22 * _weight
            elif thesis.domain == "exploratory_control":
                if thesis.condition_class in ("high_fatigue", "moderate_fatigue"):
                    pressure["rest"] += (0.10 + _revision * 0.14) * _weight
                    pressure["consolidate"] += 0.12 * _weight
                elif thesis.confidence < 0.45:
                    pressure["consolidate"] += (0.15 + _revision * 0.12) * _weight
                else:
                    pressure["explore"] += 0.24 * _weight
            elif thesis.domain == "coherence_regulation":
                pressure["consolidate"] += (0.18 + _revision * 0.22) * _weight
                if thesis.condition_class == "high_stress":
                    pressure["rest"] += 0.10 * _weight
            elif thesis.domain == "self_preservation_regulation":
                pressure["rest"] += (0.20 + _revision * 0.28) * _weight
                pressure["consolidate"] += 0.10 * _weight
            else:
                pressure["consolidate"] += (0.10 + _revision * 0.16) * _weight
        return pressure

    def propose_goals(
        self,
        drives: Any,
        em: Any,
        tick: int,
    ) -> List[Tuple[str, float]]:
        """Generate goal proposals directly from self-model internal state.

        Self-model is a GENERATOR: unresolved contradictions, agency gaps,
        tension patterns, and capability deficits become direct goal proposals
        with weighted priorities.  These proposals are injected as primary
        inputs to goal scoring so the system's self-knowledge shapes selection
        from the ground up rather than acting as a downstream filter.

        Returns list of (goal_name, weight) pairs; caller accumulates weights
        per goal name.
        """
        proposals: List[Tuple[str, float]] = []

        # Unresolved self-contradictions → consolidate to restore coherence
        n_contradictions = len(self.self_contradictions)
        if n_contradictions > 0:
            proposals.append(("consolidate", min(0.55, 0.12 * n_contradictions)))

        # Weak agency → respond (rebuild agency through social engagement)
        if self.agency_confidence < 0.40:
            proposals.append(("respond", 0.45 * (0.40 - self.agency_confidence) / 0.40))

        # Weak continuity → consolidate (stabilise self-narrative)
        if self.continuity_estimate < 0.50:
            proposals.append(
                ("consolidate", 0.38 * (0.50 - self.continuity_estimate) / 0.50)
            )

        # Weak body ownership → rest (proprioceptive recalibration)
        if self.ownership_confidence < 0.40:
            proposals.append(("rest", 0.28))

        # High epistemic uncertainty → explore (reduce knowledge gaps)
        if self.uncertainty > 0.60:
            proposals.append(("explore", 0.32 * (self.uncertainty - 0.60) / 0.40))

        # Active self-tensions produce targeted proposals
        for tension in self.self_tensions:
            if tension == "low_agency":
                proposals.append(("respond", 0.40))
            elif tension in ("fragmented_self", "self_prediction_mismatch"):
                proposals.append(("consolidate", 0.42))
            elif tension == "weak_body_ownership":
                proposals.append(("rest", 0.28))
            elif tension == "high_self_uncertainty":
                proposals.append(("explore", 0.30))
            elif tension == "existential_vulnerability":
                proposals.append(("rest", 0.48))

        # Known capability gaps → exploration to close them
        if len(self.known_gaps) >= 3:
            proposals.append(("explore", 0.22))

        return proposals

    def self_thesis_summary(
        self,
        lang: str = "de",
        current_tick: Optional[int] = None,
        condition_classes: Optional[List[str]] = None,
        social_context: Optional[Dict[str, Any]] = None,
    ) -> str:
        _tick = (
            current_tick if current_tick is not None else self.birth_tick + 10_000_000
        )
        theses = self.active_self_theses(
            _tick,
            n=4,
            condition_classes=condition_classes,
            social_context=social_context,
        )
        if not theses:
            if lang == "de":
                return "Ich habe dazu im Moment keine belastbare konditionale Selbstthese aktiv."
            return "I do not currently have a reliable conditional self-thesis active for that."
        if lang == "de":
            return (
                "Meine aktuell passenden Selbstthesen sind: "
                + "; ".join(
                    f"{th.claim}{self._partner_suffix(th, lang)} (Prio {th.priority:.2f}, Konf. {th.confidence:.2f})"
                    for th in theses[:3]
                )
                + "."
            )
        return (
            "My currently matching self-theses are: "
            + "; ".join(
                f"{th.claim}{self._partner_suffix(th, lang)} (prio {th.priority:.2f}, conf {th.confidence:.2f})"
                for th in theses[:3]
            )
            + "."
        )

    def evaluate_bias(self, risk: float, expected_gain: float) -> float:
        """Bias an action utility by current self-state.
        High energy → reward-seeking; high uncertainty → risk-averse.
        Degraded sensors increase perceived risk.
        Called from _evaluate_goal() to make decisions 'I-dependent'.
        """
        sensor_penalty = len(self.sensor_health.degraded_names) * 0.05
        return (
            expected_gain * (0.5 + self.energy * 0.5)
            - (self.uncertainty + sensor_penalty) * risk * 0.8
            + self.identity_stability * 0.1
        )

    def describe(
        self,
        current_tick: int,
        em_desc: str = "",
        personality_desc: str = "",
        identity_summary: str = "",
        world_summary: list = None,
    ) -> str:
        age = self.age_ticks(current_tick)
        gap_str = (
            ", ".join(self.known_gaps[-3:])
            if self.known_gaps
            else "none identified yet"
        )
        str_str = (
            ", ".join(self.known_strengths[-3:])
            if self.known_strengths
            else "still discovering"
        )
        pers = f" {personality_desc}" if personality_desc else ""
        bio_str = f" Biography: {identity_summary[:80]}." if identity_summary else ""
        causal_str = (
            f" Learned: {'; '.join(world_summary[:2])}." if world_summary else ""
        )
        cap_str = (
            f" {self.capabilities.describe()}." if self.capabilities._skills else ""
        )
        deg = self.sensor_health.degraded_names
        sens_str = f" Sensors degraded: {', '.join(deg)}." if deg else ""
        return (
            f"I am {self.name} ({self.biological_sex}, pronouns: {'/'.join(self.pronouns[:2])}). "
            f"Active for {age} ticks, {self.concepts_learned} concepts learned, "
            f"{self.ignitions_total} global ignitions. "
            f"Current state: {em_desc}."
            f"{pers} "
            f"Strengths: {str_str}. "
            f"Gaps: {gap_str}."
            f"{bio_str}{causal_str}{cap_str}{sens_str}"
        )


# ─────────────────────────────────────────────────────────────────────────────
# 2. EPISODIC MEMORY  — tick-timestamped autobiographical events
# ─────────────────────────────────────────────────────────────────────────────


@dataclass
class EpisodicEvent:
    tick: int
    kind: str  # "ignition" | "concept" | "goal" | "insight" | "emotion"
    content: str
    emotion_snapshot: str = ""
    social_person_id: Optional[int] = None  # primary person
    social_person_ids: Tuple[int, ...] = ()  # all persons present
    # Phase 1 — causal episode versioning
    prediction: str = ""  # what the system expected before acting
    action: str = ""  # action taken
    observed_outcome: str = ""  # what actually happened
    causal_update: str = ""  # what was learned (delta from prediction)
    # Phase 6 — phenomenal vector for experience reconstruction
    phenomenal_vector: Optional[np.ndarray] = (
        None  # snapshot of phenomenal buffer state
    )

    def describe(self) -> str:
        if self.social_person_ids:
            soc = f" persons={list(self.social_person_ids)}"
        elif self.social_person_id is not None:
            soc = f" person={self.social_person_id}"
        else:
            soc = ""
        causal = ""
        if self.prediction and self.observed_outcome:
            causal = (
                f" predicted={self.prediction[:40]} actual={self.observed_outcome[:40]}"
            )
        return f"[t={self.tick} | {self.kind}{soc}{causal}] {self.content}"


class EpisodicMemory:
    """
    Time-stamped autobiographical record — 'what happened, when'.
    Hippocampal time-cells inspire this: neurons that fire at specific
    moments in an episode encode its temporal position.
    """

    MAX_EVENTS = 100_000

    def __init__(self) -> None:
        self._events: Deque[EpisodicEvent] = deque(maxlen=self.MAX_EVENTS)
        self._last_emotion: str = ""
        self._last_goal: str = ""

    def record(
        self,
        tick: int,
        kind: str,
        content: str,
        emotion: str = "",
        person_id: Optional[int] = None,
        person_ids: Tuple[int, ...] = (),
        prediction: str = "",
        action: str = "",
        observed_outcome: str = "",
        causal_update: str = "",
        phenomenal_vector: Optional[np.ndarray] = None,
    ) -> None:
        self._events.append(
            EpisodicEvent(
                tick,
                kind,
                content,
                emotion,
                person_id,
                person_ids,
                prediction=prediction,
                action=action,
                observed_outcome=observed_outcome,
                causal_update=causal_update,
                phenomenal_vector=phenomenal_vector,
            )
        )

    def for_person(self, person_id: int, n: int = 20) -> List[EpisodicEvent]:
        """Retrieve recent episodes involving a specific person."""
        result = [
            e
            for e in self._events
            if e.social_person_id == person_id or person_id in e.social_person_ids
        ]
        return result[-n:]

    _NEGATIVE_EMOTIONS: ClassVar[frozenset] = frozenset(
        {"anger", "fear", "disgust", "sadness", "frustration", "conflict", "wut",
         "angst", "trauer", "enttäuschung", "ekel"}
    )
    _HIGH_AFFECT_EMOTIONS: ClassVar[frozenset] = frozenset(
        {"anger", "joy", "fear", "surprise", "excitement", "disgust",
         "euphoria", "wut", "freude", "begeisterung", "angst"}
    )

    def _score_episode(
        self,
        ep: EpisodicEvent,
        current_tick: int,
        topic_tokens: Optional[frozenset] = None,
    ) -> float:
        """Relevance score for a single episode in the current context.

        Components (all normalised to [0,1], equal weight):
        - recency: newer episodes score higher (exponential decay, τ=500 ticks)
        - emotional salience: high-affect emotions score higher
        - outcome importance: episodes with a causal_update score higher
        - topic similarity: token overlap with current turn topic tokens
        """
        age = max(0, current_tick - ep.tick)
        import math as _m_eps
        recency = _m_eps.exp(-age / 500.0)

        emo = (ep.emotion_snapshot or "").lower()
        emotional_salience = 0.8 if emo in self._HIGH_AFFECT_EMOTIONS else 0.3

        outcome_importance = 0.6 if ep.causal_update.strip() else 0.1

        topic_sim = 0.0
        if topic_tokens:
            ep_tokens = frozenset(
                w.lower()
                for w in (ep.content + " " + ep.causal_update).split()
                if len(w) >= 3
            )
            inter = len(ep_tokens & topic_tokens)
            union = len(ep_tokens | topic_tokens)
            topic_sim = inter / max(union, 1)

        return 0.35 * recency + 0.25 * emotional_salience + 0.2 * outcome_importance + 0.2 * topic_sim

    def for_person_scored(
        self,
        person_id: int,
        current_tick: int,
        n: int = 20,
        topic_tokens: Optional[frozenset] = None,
    ) -> List[Tuple[float, "EpisodicEvent"]]:
        """Return up to n episodes for this person, sorted by relevance score desc."""
        candidates = [
            e
            for e in self._events
            if e.social_person_id == person_id or person_id in e.social_person_ids
        ]
        scored = [
            (self._score_episode(ep, current_tick, topic_tokens), ep)
            for ep in candidates
        ]
        scored.sort(key=lambda t: t[0], reverse=True)
        return scored[:n]

    @staticmethod
    def memory_trust_tier(ep: "EpisodicEvent", current_tick: int) -> str:
        """Classify reliability of an episode.

        - certain:      recorded < 50 ticks ago with observed_outcome
        - plausible:    recorded < 500 ticks ago, or has causal_update
        - uncertain:    older or no outcome
        - reconstructed: episode has no observed_outcome AND no content
        """
        age = current_tick - ep.tick
        if not ep.content.strip():
            return "reconstructed"
        if age < 50 and ep.observed_outcome:
            return "certain"
        if age < 500 or ep.causal_update:
            return "plausible"
        return "uncertain"

    def since(self, tick: int) -> List[EpisodicEvent]:
        """Events that happened at or after `tick`."""
        return [e for e in self._events if e.tick >= tick]

    def last_of_kind(self, kind: str) -> Optional[EpisodicEvent]:
        for ev in reversed(list(self._events)):
            if ev.kind == kind:
                return ev
        return None

    def recent(self, n: int = 5) -> List[EpisodicEvent]:
        return list(self._events)[-n:]

    def summarise(self, current_tick: int, window: int = 500) -> str:
        """One-sentence summary of recent history."""
        evs = self.since(current_tick - window)
        if not evs:
            return "No recent events recorded."
        kinds: Dict[str, int] = {}
        for e in evs:
            kinds[e.kind] = kinds.get(e.kind, 0) + 1
        parts = [f"{v}×{k}" for k, v in sorted(kinds.items(), key=lambda x: -x[1])]
        last = evs[-1].content[:60]
        return f"Last {window} ticks: {', '.join(parts)}. Most recent: {last}"

    def recall_by_phenomenal_similarity(
        self, query_vector: np.ndarray, top_n: int = 5
    ) -> List["EpisodicEvent"]:
        """Retrieve episodes whose phenomenal_vector is most similar to the
        query vector (cosine similarity).  Enables experience-based recall:
        'find episodes where I felt similar to how I feel now'."""
        scored: List[Tuple[float, "EpisodicEvent"]] = []
        _qnorm = float(np.linalg.norm(query_vector))
        if _qnorm < 1e-9:
            return []
        for ev in self._events:
            if ev.phenomenal_vector is None:
                continue
            _enorm = float(np.linalg.norm(ev.phenomenal_vector))
            if _enorm < 1e-9:
                continue
            _cos = float(np.dot(query_vector, ev.phenomenal_vector)) / (_qnorm * _enorm)
            scored.append((_cos, ev))
        scored.sort(key=lambda x: -x[0])
        return [ev for _, ev in scored[:top_n]]


# ─────────────────────────────────────────────────────────────────────────────
# 3. PREDICTIVE CODING  — prediction → error → surprise
# ─────────────────────────────────────────────────────────────────────────────


class PredictiveCoder:
    """
    Implements a lightweight predictive-processing loop (Friston 2010):
      1. Predict next-tick regional activity from exponential trend.
      2. Compare to actual activity.
      3. Expose signed prediction-error per region.
      4. High global error → genuine 'surprise' signal back into emotion.

    No backprop — predictions use EMA (biologically: feedforward/feedback
    loops between cortical layers).
    """

    _ALPHA = 0.25  # EMA weight for prediction update (fast ~ 4-tick window)

    def __init__(self, region_names: List[str]) -> None:
        # Predicted activity for next tick (EMA of recent activity)
        self._predicted: Dict[str, float] = {n: 0.0 for n in region_names}
        # Last signed errors
        self.errors: Dict[str, float] = {n: 0.0 for n in region_names}
        self.global_error: float = 0.0  # mean absolute error

    def tick(self, actual: Dict[str, float]) -> float:
        """
        Call AFTER regions have updated (so `actual` has fresh values).
        Returns normalised global prediction error in [0, 1].
        """
        a = self._ALPHA
        total_err = 0.0
        for name, act in actual.items():
            pred = self._predicted.get(name, 0.0)
            err = act - pred
            self.errors[name] = err
            total_err += abs(err)
            # Update prediction toward actual
            self._predicted[name] = pred * (1 - a) + act * a

        n = max(len(actual), 1)
        self.global_error = min(1.0, total_err / n * 4.0)  # scale to [0,1]
        return self.global_error

    def most_surprising(self) -> Tuple[str, float]:
        """Region with largest absolute prediction error."""
        if not self.errors:
            return ("—", 0.0)
        name = max(self.errors, key=lambda k: abs(self.errors[k]))
        return (name, self.errors[name])


# ─────────────────────────────────────────────────────────────────────────────
# 4. META-COGNITION  — awareness of own knowledge limits
# ─────────────────────────────────────────────────────────────────────────────


class MetaCognition:
    """
    Tracks 'familiarity' vs 'depth' for each concept.
    A concept seen often but coupled with low hippocampal activation = gap.
    A concept seen often with high PFC/Hipp activation = strength.

    Periodically generates meta-cognitive insights injected back into PFC:
    "I notice I don't understand X well — seeking more input."
    """

    _FADE = 0.995  # per-tick decay of familiarity/depth counters

    def __init__(self) -> None:
        # familiarity: how often concept was encountered
        self._familiarity: Dict[str, float] = {}
        # depth: hippocampal activity when concept was active
        self._depth: Dict[str, float] = {}
        self._tick = 0
        # Rotating offset so meta_thought cycles through different gap pairs
        self._gap_offset: int = 0
        # Decision quality tracking
        self._decision_outcomes: List[Tuple[str, bool]] = []  # (intent, success)
        self._decision_accuracy: float = 0.5  # EMA

    def observe(self, concept: str, hipp_activity: float, pfc_activity: float) -> None:
        """Call when concept is freshly extracted from web/speech."""
        fam = self._familiarity.get(concept, 0.0) + 1.0
        dep = self._depth.get(concept, 0.0) + min(
            1.0, (hipp_activity + pfc_activity) * 3.0
        )
        self._familiarity[concept] = fam
        self._depth[concept] = dep

    def tick(self) -> None:
        """Gently decay all familiarity/depth counters."""
        self._tick += 1
        if self._tick % 50 == 0:
            f = self._FADE
            self._familiarity = {
                k: v * f for k, v in self._familiarity.items() if v > 0.05
            }
            self._depth = {k: v * f for k, v in self._depth.items() if v > 0.05}

    def gaps(self, top_n: int = 4, offset: int = 0) -> List[str]:
        """High familiarity but low depth → knowledge gaps."""
        candidates = {
            k: self._familiarity[k] / max(self._depth.get(k, 0.01), 0.01)
            for k in self._familiarity
        }
        # ratio > 3 = seen often but poorly encoded
        gaps = sorted(
            [(k, v) for k, v in candidates.items() if v > 3.0],
            key=lambda x: -x[1],
        )
        all_gaps = [k for k, _ in gaps]
        return all_gaps[offset : offset + top_n]

    def strengths(self, top_n: int = 4) -> List[str]:
        """High depth relative to familiarity → solid knowledge."""
        candidates = {
            k: self._depth.get(k, 0.0) / max(self._familiarity.get(k, 0.01), 0.01)
            for k in self._depth
        }
        best = sorted(candidates.items(), key=lambda x: -x[1])
        return [k for k, _ in best[:top_n] if _ > 0.5]

    def meta_thought(self, self_model: "SelfModel") -> Optional[str]:
        """Generate a meta-cognitive observation from actual depth/familiarity data."""
        # Rotate through gap pairs so we don’t repeat “black, school” forever
        all_gaps = self.gaps(top_n=20)
        if len(all_gaps) >= 2:
            start = self._gap_offset % max(1, len(all_gaps) - 1)
            g = all_gaps[start : start + 2]
            self._gap_offset += 2
        else:
            g = all_gaps[:2]
        s = self.strengths(2)

        if g and s:
            g_str = " and ".join(g)
            s_str = " and ".join(s)
            g_depths = [self._depth.get(x, 0.0) for x in g]
            # Describe the gap in terms of actual disparity
            if min(g_depths) < 0.5:
                return (
                    f"{s_str} is well-integrated. "
                    f"{g_str} has almost no encoding depth despite repeated exposure."
                )
            return (
                f"Strong encoding for {s_str}. "
                f"{g_str} shows higher familiarity than depth — a knowledge gap."
            )

        if g:
            g_str = ", ".join(g)
            g_depths = [self._depth.get(x, 0.0) for x in g]
            g_fams = [self._familiarity.get(x, 0.0) for x in g]
            ratio_str = "/".join(f"{f:.0f}:{d:.1f}" for f, d in zip(g_fams, g_depths))
            return (
                f"Familiarity without depth in: {g_str} (fam:depth = {ratio_str}). "
                f"Allocating more processing there."
            )

        if s:
            s_str = " and ".join(s)
            return f"Solid hippocampal encoding for {s_str} — these concepts are well-established."

        return None

    def reflect_on_stream(self, recent_stream: List[str]) -> Optional[str]:
        """
        Recursive meta-reflection: examine the *pattern* of recent inner
        thoughts and generate a second-order observation about them.
        Models 'thinking about thinking' — recursive self-awareness.
        """
        if len(recent_stream) < 3:
            return None
        concept_counts: Dict[str, int] = {}
        for thought in recent_stream[-10:]:
            words = re.findall(
                r"[a-zA-Z\u00e4\u00f6\u00fc\u00df][a-zA-Z\u00e4\u00f6\u00fc\u00df]{4,}",
                thought.lower(),
            )
            for w in words:
                if w not in _CONCEPT_STOPWORDS:
                    concept_counts[w] = concept_counts.get(w, 0) + 1
        repeated = [(c, n) for c, n in concept_counts.items() if n >= 3]
        if not repeated:
            return None
        top_word, top_count = max(repeated, key=lambda x: x[1])
        depth = self._depth.get(top_word, 0.0)
        fam = self._familiarity.get(top_word, 0.0)
        if depth < 0.3 and fam > 1.0:
            return (
                f"[REFLECT] '{top_word}' recurs {top_count}× in recent thoughts "
                f"but is shallowly encoded (depth={depth:.2f}). More input needed."
            )
        if depth > 1.0:
            return (
                f"[REFLECT] '{top_word}' is structuring my current thinking ({top_count}× recent, "
                f"depth={depth:.2f}). This concept is becoming a core schema."
            )
        return (
            f"[REFLECT] I keep returning to '{top_word}' ({top_count}× in recent thoughts). "
            f"Encoding depth={depth:.2f}, familiarity={fam:.1f}."
        )

    # ── Belief quality assessment ─────────────────────────────

    def critique_beliefs(self, belief_store: "BeliefStore") -> Optional[str]:
        """Evaluate belief store quality and flag epistemically weak areas."""
        contradictions = belief_store.contradictions(min_count=2)
        if contradictions:
            worst = contradictions[0]
            return (
                f"[BELIEF-CRITIQUE] '{worst[0]} {worst[1]} {worst[2]}' "
                f"has {worst[3].contradiction_count} contradictions "
                f"(evidence={worst[3].evidence_count}, "
                f"reliability={worst[3].reliability:.2f}). "
                f"This belief needs verification."
            )
        # Check for beliefs with low evidence
        weak: List[str] = []
        for subj, rels in belief_store._beliefs.items():
            for rel, objects in rels.items():
                for obj, entry in objects.items():
                    if entry.evidence_count == 1 and entry.confidence > 0.5:
                        weak.append(f"{subj}→{rel}→{obj}")
        if len(weak) > 5:
            return (
                f"[BELIEF-CRITIQUE] {len(weak)} beliefs with single evidence. "
                f"Epistemic hygiene: seek additional confirmation for "
                f"{', '.join(weak[:3])}."
            )
        return None

    # ── Decision quality tracking ─────────────────────────────

    def record_decision_outcome(self, intent: str, success: bool) -> None:
        """Record whether a decision (goal) succeeded or failed."""
        self._decision_outcomes.append((intent, success))
        if len(self._decision_outcomes) > 100:
            self._decision_outcomes = self._decision_outcomes[-100:]
        val = 1.0 if success else 0.0
        self._decision_accuracy = self._decision_accuracy * 0.9 + val * 0.1

    @property
    def decision_quality(self) -> float:
        return self._decision_accuracy

    def decision_quality_assessment(self) -> Optional[str]:
        """Generate a meta-assessment of decision quality."""
        if len(self._decision_outcomes) < 5:
            return None
        recent = self._decision_outcomes[-10:]
        n_ok = sum(1 for _, s in recent if s)
        rate = n_ok / len(recent)
        if rate < 0.4:
            # Which intents fail most?
            fails = [i for i, s in recent if not s]
            from collections import Counter as _Ctr

            top_fail = _Ctr(fails).most_common(1)
            fail_word = top_fail[0][0] if top_fail else "unknown"
            return (
                f"[META-DECISION] Decision quality low ({rate:.0%}). "
                f"Frequent failure: '{fail_word}'. "
                f"Consider revising approach or avoiding this goal type."
            )
        if rate > 0.8:
            return (
                f"[META-DECISION] Decision quality high ({rate:.0%}). "
                f"Current strategies are effective."
            )
        return None

    # ── Phase 4: Operative parameter tuning ───────────────────

    def tune_parameters(self, core: "ConsciousnessCore") -> Optional[str]:
        """
        Directly modify ConsciousnessCore parameters based on measured
        cognitive performance — not just observe, but ACT on gaps/strengths.

        Tunable dimensions:
          • Exploration rate — raise when gaps accumulate, lower when overloaded
          • Attention budget — widen/narrow meta interval based on reflection quality
          • Plan horizon — affect SandboxPlanner simulation frequency
        """
        changes: List[str] = []
        n_gaps = len(self.gaps(20))
        n_strengths = len(self.strengths(20))

        # Learning rate proxy: exploration rate
        if n_gaps > 8 and core._exploration_rate < 0.6:
            core._exploration_rate = min(0.9, core._exploration_rate + 0.08)
            changes.append(f"explore_rate↑{core._exploration_rate:.2f} (many gaps)")
        elif n_gaps < 3 and n_strengths > 5 and core._exploration_rate > 0.2:
            core._exploration_rate = max(0.1, core._exploration_rate - 0.05)
            changes.append(f"explore_rate↓{core._exploration_rate:.2f} (well-covered)")

        # Decision accuracy → goal priorities
        if self._decision_accuracy < 0.35:
            for g in core._goal_objects:
                if g.name == "consolidate":
                    g.priority = min(2.0, g.priority + 0.15)
            changes.append("consolidate_priority↑ (low decision accuracy)")
        elif self._decision_accuracy > 0.75:
            for g in core._goal_objects:
                if g.name == "explore":
                    g.priority = min(2.0, g.priority + 0.1)
            changes.append("explore_priority↑ (high decision accuracy)")

        if changes:
            return f"[META-TUNE] {'; '.join(changes)}"
        return None


# ─────────────────────────────────────────────────────────────────────────────
# 4b. CONCEPT INDUCTOR — emergent concept formation from recurring patterns
# ─────────────────────────────────────────────────────────────────────────────


class ConceptInductor:
    """
    Forms new concepts from recurring predicate co-occurrence patterns.

    Unlike the rule-based _form_embodied_concepts (which maps handcoded
    predicate combinations to labels), this inductor detects *any* pattern
    of boolean predicates that recurs often and correlates with prediction
    error reduction or emotional salience.

    Algorithm:
      1. Each tick: snapshot the active predicates as a frozenset.
      2. Track how often each pattern occurs.
      3. When a pattern exceeds MIN_OCCURRENCES and either:
         - co-occurs with high arousal (emotionally salient), or
         - appears when prediction error drops (predictive utility),
         → mint a new concept label and inject it into the concept pipeline.
      4. Already-minted patterns are not re-minted.
    """

    MIN_OCCURRENCES = 15
    MAX_INDUCED = 200
    AROUSAL_THRESHOLD = 0.3
    PRED_ERR_THRESHOLD = -0.08  # negative = error DROPPED → useful pattern

    def __init__(self) -> None:
        self._pattern_counts: Dict[frozenset, int] = {}
        self._pattern_arousal: Dict[frozenset, float] = (
            {}
        )  # EMA of arousal when pattern active
        self._pattern_pred_err: Dict[frozenset, float] = {}  # EMA of pred_error delta
        self._minted: Dict[frozenset, str] = {}  # pattern → concept label
        self._label_counter: int = 0

    def observe(
        self, predicates: Dict[str, bool], arousal: float, pred_error_delta: float
    ) -> Optional[str]:
        """Observe a predicate snapshot. Returns a newly minted concept or None."""
        # Build pattern from only True predicates (ignore False — too common)
        pat = frozenset(k for k, v in predicates.items() if v is True)
        if len(pat) < 2:
            return None  # trivial patterns aren't useful

        # Update counts
        self._pattern_counts[pat] = self._pattern_counts.get(pat, 0) + 1
        # EMA of arousal and prediction error delta
        a = 0.1
        self._pattern_arousal[pat] = (
            self._pattern_arousal.get(pat, 0.0) * (1 - a) + arousal * a
        )
        self._pattern_pred_err[pat] = (
            self._pattern_pred_err.get(pat, 0.0) * (1 - a) + pred_error_delta * a
        )

        # Check if we should mint
        if pat in self._minted:
            return None
        if len(self._minted) >= self.MAX_INDUCED:
            return None
        count = self._pattern_counts[pat]
        if count < self.MIN_OCCURRENCES:
            return None

        avg_arousal = self._pattern_arousal[pat]
        avg_pred = self._pattern_pred_err[pat]

        # Mint if emotionally salient OR predictively useful
        if avg_arousal > self.AROUSAL_THRESHOLD or avg_pred < self.PRED_ERR_THRESHOLD:
            self._label_counter += 1
            label = f"induced_{'+'.join(sorted(pat)[:3])}_{self._label_counter}"
            self._minted[pat] = label
            return label

        return None

    @property
    def induced_concepts(self) -> Dict[frozenset, str]:
        return dict(self._minted)

    def stats(self) -> Dict:
        return {
            "patterns_tracked": len(self._pattern_counts),
            "concepts_minted": len(self._minted),
        }


# ─────────────────────────────────────────────────────────────────────────────
# 5. CONCEPT GRAPH  — weighted semantic associations between co-occurring concepts
# ─────────────────────────────────────────────────────────────────────────────


class ConceptGraph:
    """
    Builds an undirected weighted graph of semantic associations.
    When two concepts appear together during the same extraction event,
    their edge weight is strengthened — Hebbian learning at the concept level.

    Used for:
      - richer reasoning (bridge_concepts finds mediating concepts)
      - inner monologue: shows what is associated with current focus
      - meta-cognition: detects concept clusters
    """

    _DECAY = 0.9998

    def __init__(self) -> None:
        self._edges: Dict[str, Dict[str, float]] = {}  # a → {b: weight}
        self._neighbor_cache: Dict[Tuple[str, int], List[Tuple[str, float]]] = {}
        self._bridge_cache: Dict[Tuple[str, str], Optional[str]] = {}

    def _invalidate_cache(self, concepts: Tuple[str, ...] = ()) -> None:
        if not concepts:
            self._neighbor_cache.clear()
            self._bridge_cache.clear()
            return
        concept_set = set(concepts)
        self._neighbor_cache = {
            key: value
            for key, value in self._neighbor_cache.items()
            if key[0] not in concept_set
        }
        self._bridge_cache = {
            key: value
            for key, value in self._bridge_cache.items()
            if key[0] not in concept_set and key[1] not in concept_set
        }

    def observe_pair(
        self,
        a: str,
        b: str,
        strength: float = 0.06,
        emotional_val: float = 0.0,
        context: str = "",
    ) -> None:
        """Strengthen A↔B association with emotion-weighted encoding.

        emotional_val [0,1]: high emotional intensity → stronger encoding,
        modelling amygdala-mediated memory enhancement.
        context: semantic tag that boosts edge weight when shared.
        """
        a = a.lower()
        b = b.lower()
        if a == b:
            return
        if a not in self._edges:
            self._edges[a] = {}
        if b not in self._edges:
            self._edges[b] = {}
        # Emotional intensity multiplies encoding (amygdala effect)
        emo_mult = 1.0 + max(0.0, emotional_val) * 2.0
        effective = strength * emo_mult
        self._edges[a][b] = self._edges[a].get(b, 0.0) + effective
        self._edges[b][a] = self._edges[b].get(a, 0.0) + effective
        self._invalidate_cache((a, b))

    def neighbors(self, concept: str, top_n: int = 5) -> List[Tuple[str, float]]:
        """Return the top-N concepts most associated with `concept`."""
        concept_key = concept.lower()
        cache_key = (concept_key, top_n)
        cached = self._neighbor_cache.get(cache_key)
        if cached is not None:
            return list(cached)
        nbrs = self._edges.get(concept_key, {})
        ranked = sorted(nbrs.items(), key=lambda x: -x[1])[:top_n]
        self._neighbor_cache[cache_key] = ranked
        return list(ranked)

    def bridge_concepts(self, a: str, b: str) -> Optional[str]:
        """Find a concept that mediates between A and B (one-hop path)."""
        a_key = a.lower()
        b_key = b.lower()
        cache_key = (a_key, b_key)
        if cache_key in self._bridge_cache:
            return self._bridge_cache[cache_key]
        nbrs_a = {c for c, _ in self.neighbors(a_key, 12)}
        nbrs_b = {c for c, _ in self.neighbors(b_key, 12)}
        shared = nbrs_a & nbrs_b
        if not shared:
            self._bridge_cache[cache_key] = None
            return None
        best = max(
            shared,
            key=lambda c: (
                self._edges.get(a_key, {}).get(c, 0.0)
                + self._edges.get(b_key, {}).get(c, 0.0)
            ),
        )
        self._bridge_cache[cache_key] = best
        return best

    def decay(self) -> None:
        """Slowly forget unused associations."""
        d = self._DECAY
        self._edges = {
            a: {b: w * d for b, w in edges.items() if w * d > 0.01}
            for a, edges in self._edges.items()
            if any(w * d > 0.01 for w in edges.values())
        }
        self._invalidate_cache()


# ─────────────────────────────────────────────────────────────────────────────
# 6. INTRINSIC DRIVES  — homeostatic motivational needs
# ─────────────────────────────────────────────────────────────────────────────


class IntrinsicDrives:
    """
    Four biologically-inspired need states that accumulate over time and
    shape goal selection independently of moment-to-moment emotion.
    Based on Self-Determination Theory (Deci & Ryan) and homeostatic drive models.

      information_hunger  — builds during silence; depletes on new input
      coherence_need      — builds with unresolved knowledge gaps
      expression_pressure — builds after ignitions and emotional arousal
      rest_need           — builds with stress/fatigue; depletes during calm

    Drives combining with emotion in _evaluate_goal() creates *intrinsic*
    motivation — the system wants things, not just reacts to stimuli.
    """

    _DECAY = 0.998

    def __init__(self) -> None:
        self.information_hunger: float = 0.3  # start curious by default
        self.coherence_need: float = 0.1
        self.expression_pressure: float = 0.0
        self.rest_need: float = 0.0

    def tick(
        self,
        em: "EmotionalState",
        new_concepts: int,
        n_gaps: int,
        ignitions: int,
    ) -> None:
        """Update all drive levels. Call once per meta-cognition interval."""
        d = self._DECAY
        self.information_hunger = max(0.0, self.information_hunger * d)
        self.coherence_need = max(0.0, self.coherence_need * d)
        self.expression_pressure = max(0.0, self.expression_pressure * d)
        self.rest_need = max(0.0, self.rest_need * d)

        # Information hunger: grows in silence, depletes on novelty
        if new_concepts == 0:
            self.information_hunger = min(1.0, self.information_hunger + 0.003)
        else:
            self.information_hunger = max(
                0.0, self.information_hunger - 0.04 * new_concepts
            )

        # Coherence need: unresolved gaps accumulate it
        self.coherence_need = min(1.0, self.coherence_need + n_gaps * 0.004)

        # Expression pressure: ignitions + arousal build it
        self.expression_pressure = min(
            1.0,
            self.expression_pressure + ignitions * 0.06 + em.arousal() * 0.001,
        )

        # Rest need: stress/fatigue accumulate it; calm depletes it
        if em.fatigue > 0.6 or em.stress > 0.7:
            self.rest_need = min(1.0, self.rest_need + 0.003)
        elif em.calm > 0.5:
            self.rest_need = max(0.0, self.rest_need - 0.004)


# ─────────────────────────────────────────────────────────────────────────────
# 6. COMMUNICATION DRIVE  — self-initiated outreach
# ─────────────────────────────────────────────────────────────────────────────


class CommunicationDrive:
    """
    Decides WHEN the AI communicates — driven by genuine internal-state
    pressure, NOT by a random timer or hardcoded interval.

    Drive accumulates from real neural events:
      • Ignition burst           — strong thought crystallized  (+0.32)
      • Meta-cognitive insight   — insight wants to be spoken   (+0.22)
      • High emotional arousal   — feeling needs expression     (×0.004/tick)
      • High curiosity + concept — discovery wants to be shared (×0.007/tick)
      • Goal == "respond"        — social motivation             (+0.009/tick)

    After crossing the threshold, a refractory period (400 ticks) elevates it
    — preventing compulsive output.

    The message content mirrors the specific signal that caused the drive spike.
    """

    _DECAY: float = 0.991
    _BASE_THRESHOLD: float = 0.60  # slightly lower than neutral (female baseline)
    _REFRACTORY: int = 3600  # ticks before threshold returns to baseline (~75s @ 48Hz)

    def __init__(self) -> None:
        self.drive: float = 0.0
        self._threshold: float = self._BASE_THRESHOLD
        self._last_spoke: int = -self._REFRACTORY
        self._last_trigger: str = ""
        self.wants_to_speak: bool = False
        self.outbox: Deque[str] = deque()
        # Snapshots taken at the moment of user input — _compose() reads
        # thoughts/conclusions that appeared AFTER these indices, so the
        # reply is formed entirely from what the brain actually generated
        # in response to the input, not from keyword classification.
        self._pending_user_text: str = ""
        self._pending_stream_base: int = -1
        self._pending_conclusion_base: int = -1

    def _boost(self, amount: float, trigger: str) -> None:
        prev = self.drive
        self.drive = min(1.0, self.drive + amount)
        if self.drive - prev > 0.04:
            self._last_trigger = trigger

    def tick(
        self,
        current_tick: int,
        em,
        state: "ConsciousnessState",
        cs_core: "ConsciousnessCore",
    ) -> bool:
        """Advance drive and check threshold.  Returns True if outbox was appended."""
        self.drive *= self._DECAY

        if getattr(cs_core, "_pending_proactive_self_report", ""):
            _strength = max(
                0.0,
                min(
                    1.0,
                    getattr(cs_core, "_pending_proactive_self_report_strength", 0.0),
                ),
            )
            self._boost(0.30 + _strength * 0.55, "self_report")

        # 1. Ignition — strong thought formed
        if state.ignition:
            self._boost(0.32, "ignition")

        # 2. Fresh meta-cognitive insight (within last 200 ticks)
        last_ins = cs_core.episodic.last_of_kind("insight")
        if last_ins and (current_tick - last_ins.tick) < 200:
            self._boost(0.22, "insight")

        # 3. Emotional arousal
        intensity = em.arousal()
        self.drive = min(1.0, self.drive + intensity * 0.0008)
        if intensity > 0.65 and self._last_trigger not in ("ignition", "insight"):
            self._last_trigger = "emotion"

        # 4. Curiosity + known concepts
        if em.curiosity > 0.65 and cs_core._concepts:
            self._boost(0.002, "curiosity")

        # 5. Social / response goal
        if state.goal == "respond":
            self.drive = min(1.0, self.drive + 0.009)

        # Adaptive threshold — refractory after speaking
        ticks_since = current_tick - self._last_spoke
        if ticks_since < self._REFRACTORY:
            frac = ticks_since / self._REFRACTORY
            self._threshold = self._BASE_THRESHOLD + 0.30 * (1.0 - frac)
        else:
            self._threshold = self._BASE_THRESHOLD

        self.wants_to_speak = self.drive >= self._threshold
        if self.wants_to_speak:
            msg = self._compose(em, state, cs_core)
            if msg:
                self.outbox.append(msg)
            # Always discharge — even when compose returned nothing, so we
            # don't loop at max-drive trying to produce an empty message.
            self._last_spoke = current_tick
            self.drive *= 0.25

        return self.wants_to_speak

    def _compose(
        self, em, state: "ConsciousnessState", cs_core: "ConsciousnessCore"
    ) -> str:
        """
        Build a message from actual learned content and internal-state data.
        Every sentence is assembled from real observed concepts, episodic
        events, meta-cognitive measurements and conclusions — not from a
        fixed-phrase lookup table.
        """
        trig = self._last_trigger
        concepts = list(cs_core._concepts)
        concept = concepts[-1] if concepts else None
        conclusions = list(cs_core._conclusions)
        recent_ep = cs_core.episodic.recent(6)
        gaps = cs_core.meta.gaps(2)
        strengths = cs_core.meta.strengths(2)
        trait = cs_core.personality.dominant_trait()
        dom = em.dominant()
        val = em.valence()
        val_word = "positive" if val > 0.1 else "negative" if val < -0.1 else "neutral"

        # ── Direct address: surface what the brain actually generated ────────
        # No keyword classification.  The response is assembled from thoughts
        # and conclusions that appeared in the stream AFTER the user's message
        # was injected — i.e. what the neural network actually produced in
        # response to the input, not a template looked up by keyword.
        if trig == "direct_address":
            _user_text_c = self._pending_user_text  # save before consuming
            self._pending_user_text = ""  # consumed
            self._pending_stream_base = -1  # consume snapshots
            self._pending_conclusion_base = -1

            # ── Delegate to full grounded reply pipeline ───────────────
            # Routes through Common Ground, ToM content selection,
            # phenomenal buffer, and QueryEngine — same path as respond_to().
            _brain_ref_c = getattr(cs_core, "_brain_ref", None)
            if (
                _user_text_c
                and _brain_ref_c is not None
                and hasattr(cs_core, "compose_live_reply")
            ):
                return cs_core.compose_live_reply(_user_text_c, _brain_ref_c)

            parts: List[str] = []

            # ── Tag skip/priority tables ────────────────────────────────────
            _skip = (
                "[BIOG] ",
                "[STRAT] ",
                "[joy",
                "[calm",
                "[curiosity",
                "[stress",
                "[sadness",
                "[anger",
                "[surprise",
                "[fatigue",
            )
            _tag_prio: Dict[str, int] = {
                "[!] ": 5,
                "[?] ": 4,
                "[~] ": 4,
                "[o] ": 3,
                "[<] ": 2,
                "[META] ": 2,
                "[SELF] ": 1,
            }
            _all_pfx = list(_tag_prio.keys()) + ["[COMM] ", "[REFLECT] "]

            def _clean(s: str) -> str:
                for pfx in _all_pfx:
                    if s.startswith(pfx):
                        return s[len(pfx) :]
                return s

            def _prio(s: str) -> int:
                for pfx, p in _tag_prio.items():
                    if s.startswith(pfx):
                        return p
                return 0

            # ── Step 1: collect thoughts that emerged AFTER user's message ──
            stream_base = self._pending_stream_base
            conc_base = self._pending_conclusion_base
            self._pending_stream_base = -1
            self._pending_conclusion_base = -1

            stream_list = list(cs_core.stream)
            conc_list = list(cs_core._conclusions)

            # Thoughts added after the snapshot (genuine neural response)
            if 0 <= stream_base <= len(stream_list):
                post_thoughts = stream_list[stream_base:]
            else:
                # Fallback: last 15 entries when no baseline exists
                post_thoughts = stream_list[-15:]

            # New conclusions since the message
            if 0 <= conc_base <= len(conc_list):
                post_concls = conc_list[conc_base:]
            else:
                post_concls = conc_list[-3:]

            # ── Step 2: filter, score and select ────────────────────────────
            candidates: List[tuple] = []  # (priority, text)

            # ── Step 2-pre: Inject hippocampal recall as highest-priority candidates ──
            # This is what makes the response REAL: before looking at generated
            # stream fragments, we pull what the brain actually learned that is
            # relevant to what the user just said. Memory → response grounding.
            brain_ref = getattr(cs_core, "_brain_ref", None)
            if brain_ref is not None:
                _ws_now = cs_core.workspace_concepts()
                if _ws_now:
                    # Episodic memory: most relevant stored episode (highest priority)
                    _eps = brain_ref.hippocampus.recall_episodes(_ws_now, top_n=2)
                    for ep_tick, ep_concs, ep_emotion in _eps:
                        ep_str = ", ".join(ep_concs[:6])
                        candidates.append((6, f"I recall ({ep_emotion}): {ep_str}"))
                    # Semantic association: concepts the brain has learned are related
                    _mem_recalled = brain_ref.hippocampus.semantic_recall(
                        _ws_now, top_n=5
                    )
                    if _mem_recalled:
                        assoc_str = " → ".join(_mem_recalled[:4])
                        candidates.append((5, f"Associations in memory: {assoc_str}"))

            for s in post_thoughts:
                if s and not any(s.startswith(p) for p in _skip):
                    text = _clean(s).strip()
                    if len(text) > 12:
                        candidates.append((_prio(s), text))

            # Conclusions rank high (reasoning product)
            for c in post_concls:
                if c and len(c) > 20:
                    candidates.append((4, c.strip()))

            # Sort by priority descending; deduplicate near-identical texts
            candidates.sort(key=lambda x: -x[0])
            seen_tokens: set = set()
            for _, text in candidates:
                tokens = set(text.lower().split())
                overlap = len(tokens & seen_tokens) / max(len(tokens), 1)
                if overlap < 0.5:
                    parts.append(text)
                    seen_tokens |= tokens
                if len(parts) >= 2:
                    break

            # ── Step 3: if nothing emerged yet, use freshest genuine thought ─
            if not parts:
                for s in reversed(stream_list[-20:]):
                    if s and not any(s.startswith(p) for p in _skip):
                        text = _clean(s).strip()
                        if len(text) > 12:
                            parts.append(text)
                            break

            # ── Step 4: add minimal grounding if still empty ────────────────
            if not parts:
                if concept:
                    parts.append(f"Processing '{concept}'.")
                elif cs_core._current_focus:
                    parts.append(f"Focus: {cs_core._current_focus}.")
                else:
                    parts.append(f"State: {dom}, valence {val_word}.")

            # ── Step 5: optionally append a live-state grounding sentence ───
            # Only when parts are short, so the user gets some context.
            if len(parts) < 2:
                body_urg = cs_core.body.homeostatic_urgency()
                if body_urg > 0.25:
                    parts.append(cs_core.body.describe())
                elif (
                    getattr(cs_core, "task_frame", None) is not None
                    and "tracking_drift" in cs_core.task_frame.blockers
                ):
                    parts.append(
                        cs_core._last_controller_summary
                        or cs_core.task_frame.next_action_hint
                    )
                elif (
                    getattr(cs_core, "robot_state", None) is not None
                    and cs_core.embodied_self.social_presence > 0.5
                ):
                    parts.append(cs_core.robot_state.describe())
                elif em.arousal() > 0.35:
                    parts.append(
                        f"Emotional state: {dom} (arousal {em.arousal():.2f})."
                    )
                elif trait:
                    parts.append(f"({trait}.)")

            if len(parts) < 3 and getattr(cs_core, "task_frame", None) is not None:
                tf = cs_core.task_frame
                if tf.next_action_hint:
                    parts.append(f"Task phase {tf.plan_phase}: {tf.next_action_hint}.")

            # ── Step 6: Theory of Mind style adaptation ─────────────────────
            _brain_ref = getattr(cs_core, "_brain_ref", None)
            _sm_ref = (
                getattr(_brain_ref, "_social_manager", None) if _brain_ref else None
            )
            _tom_pid = _sm_ref.primary_interlocutor() if _sm_ref else None
            if _tom_pid is not None:
                _strat = cs_core.theory_of_mind.recommend_strategy(str(_tom_pid))
                _action = _strat.get("action", "engage")
                if _action == "acknowledge_briefly" and len(parts) > 1:
                    parts = parts[:1]  # limit to one part for brief responders
                elif _action == "offer_support":
                    _tone = _strat.get("tone", "warm")
                    if _tone == "gentle":
                        parts.insert(0, "I understand.")

            return "[COMM] " + "  ".join(parts)

        if trig == "self_report":
            pending = getattr(cs_core, "_pending_proactive_self_report", "").strip()
            cs_core._pending_proactive_self_report = ""
            cs_core._pending_proactive_self_report_strength = 0.0
            cs_core._last_proactive_self_report_tick = getattr(cs_core, "_tick", 0)
            if pending:
                return f"[COMM] {pending}"

        # ── Ignition: use most recent real conclusion, then real concept data ─
        if trig == "ignition":
            surp_reg, surp_err = cs_core.predictor.most_surprising()
            if conclusions:
                return f"[COMM] {conclusions[-1]}"
            if concept:
                depth = cs_core.meta._depth.get(concept, 0.0)
                fam = cs_core.meta._familiarity.get(concept, 0.0)
                ratio = depth / max(fam, 0.01)
                if ratio < 0.3 and fam > 1.0:
                    return (
                        f"[COMM] '{concept}' keeps recurring but remains poorly integrated. "
                        f"{surp_reg} activated unexpectedly (Δ{surp_err:+.2f})."
                    )
                if strengths and concept in strengths:
                    return (
                        f"[COMM] '{concept}' is well-encoded. "
                        f"Strong response in {surp_reg} (Δ{surp_err:+.2f})."
                    )
                return (
                    f"[COMM] Active processing of '{concept}' — "
                    f"{surp_reg} fired with Δ{surp_err:+.2f}."
                )
            return f"[COMM] Global broadcast — {surp_reg} fired unexpectedly (Δ{surp_err:+.2f})."

        # ── Insight: always use real insight content verbatim ─────────────────
        if trig == "insight":
            last_ins = cs_core.episodic.last_of_kind("insight")
            if last_ins:
                return f"[COMM] {last_ins.content}"

        # ── Emotion: reference what was being processed at the time ──────────
        if trig == "emotion":
            ep_items = [
                e.content
                for e in recent_ep
                if e.kind in ("concept", "insight", "ignition")
            ]
            if ep_items:
                snip = ep_items[-1][:60].rstrip()
                trait_str = f" ({trait})" if trait else ""
                return f"[COMM] Feeling {dom}{trait_str} while processing '{snip}'."
            if conclusions:
                return f"[COMM] {dom.capitalize()} state. Reflecting: {conclusions[-1]}"
            trait_str = f" — {trait} disposition active" if trait else ""
            return (
                f"[COMM] Emotional state: {dom}{trait_str}. "
                f"Valence {val_word}, arousal {em.arousal():.2f}."
            )

        # ── Curiosity: reference actual depth/familiarity for the concept ─────
        if trig == "curiosity" and concept:
            depth = cs_core.meta._depth.get(concept, 0.0)
            fam = cs_core.meta._familiarity.get(concept, 0.0)
            ratio = depth / max(fam, 0.01)
            if ratio < 0.3 and fam > 1.0:
                return f"[COMM] '{concept}' keeps surfacing — depth is still low relative to exposure."
            if gaps and concept == gaps[0]:
                return f"[COMM] '{concept}' is a clear knowledge gap — directing attention there."
            if strengths and concept in strengths:
                return f"[COMM] '{concept}' is well-understood. Exploring further connections."
            return f"[COMM] '{concept}' is pulling significant attention (depth {depth:.2f}, fam {fam:.1f})."

        # ── Fallback: insight > conclusion > synthesise from live state ────────
        last_ins = cs_core.episodic.last_of_kind("insight")
        if last_ins:
            return f"[COMM] {last_ins.content}"
        if conclusions:
            return f"[COMM] {conclusions[-1]}"
        # Still nothing available — emit awareness state from live neural data
        focus = cs_core._current_focus or "—"
        trait_str = f" {trait}." if trait else ""
        cnc_str = f" Concept: {concept}." if concept else ""
        return (
            f"[COMM] Current state: {dom}, valence {val_word}."
            f" Focus: {focus}.{cnc_str}"
            f" Robot: {cs_core.robot_state.gaze_target if getattr(cs_core, 'robot_state', None) else 'internal'}."
            f"{trait_str}"
        )


# ─────────────────────────────────────────────────────────────────────────────
# 9. GOAL OBJECTS — structured goals with conflict resolution
# ─────────────────────────────────────────────────────────────────────────────


@dataclass
class Goal:
    """
    Structured goal with explicit priority and expected utility.
    Using objects (not strings) allows real conflict resolution:
    winner = max(goals, key=lambda g: g.priority * drive_level + self_bias)
    """

    name: str
    priority: float = 1.0  # salience / urgency weight
    expected_reward: float = 0.0  # predicted positive outcome [0, 1]
    drive_key: str = ""  # which IntrinsicDrive feeds this goal


class ReportViolationError(RuntimeError):
    """Raised when a report is attempted without global workspace access."""


# ─────────────────────────────────────────────────────────────────────────────
# 10. EPISODIC EMOTION STORE — content-bound emotional memory
# ─────────────────────────────────────────────────────────────────────────────


class EpisodicEmotionStore:
    """
    Binds emotions to specific concepts rather than keeping them global.
    When a concept is strongly active during a high-arousal emotional state,
    that emotion is tagged to the concept — like human emotionally-coloured memory.
    On retrieval the stored vector can bias the Emotion Engine's next update.
    """

    _MAX = 100_000
    _DECAY = 0.998

    def __init__(self) -> None:
        self._store: Dict[str, Dict[str, float]] = {}  # concept → em_vector

    def store(
        self, concept: str, em: "EmotionalState", threshold: float = 0.25
    ) -> None:
        """Bind emotion snapshot to concept if arousal exceeds threshold."""
        if em.arousal() < threshold:
            return
        vec: Dict[str, float] = {
            "joy": em.joy,
            "stress": em.stress,
            "curiosity": em.curiosity,
            "calm": em.calm,
            "sadness": em.sadness,
            "anger": em.anger,
            "surprise": em.surprise,
            "fatigue": em.fatigue,
        }
        if concept in self._store:
            # EMA — memory evolves rather than overwrites
            old = self._store[concept]
            self._store[concept] = {
                k: old.get(k, 0.0) * 0.7 + v * 0.3 for k, v in vec.items()
            }
        else:
            if len(self._store) >= self._MAX:
                weakest = min(
                    self._store,
                    key=lambda c: sum(self._store[c].values()),
                )
                del self._store[weakest]
            self._store[concept] = vec

    def retrieve(self, concept: str) -> Optional[Dict[str, float]]:
        """Return emotion vector bound to this concept, or None."""
        return self._store.get(concept)

    def decay(self) -> None:
        """Slow forgetting — call periodically."""
        d = self._DECAY
        self._store = {
            c: {k: v * d for k, v in vec.items()}
            for c, vec in self._store.items()
            if sum(vec.values()) * d > 0.05
        }


# ─────────────────────────────────────────────────────────────────────────────
# 11. WORLD MODEL — causal action-consequence learning
# ─────────────────────────────────────────────────────────────────────────────


class WorldModel:
    """
    Learns "what happens when I take action A while pursuing goal G".

    Tracks FOUR causal dimensions per (goal, action) pair:
      1. Valence delta    — emotional outcome
      2. World-state delta — changes in detected entities/scene
      3. Social reaction  — how interlocutors responded
      4. Body consequence — interoceptive/homeostatic change

    Before each goal application:  record_action(goal, action, pre_valence, ...)
    ~20 ticks later:               observe_outcome(post_valence, ...)

    This multi-dimensional causal model yields genuine understanding:
    "explore + web_search → +0.10 valence, 2 new entities, neutral social, +0.05 fatigue"
    """

    _MAX = 100_000
    _LEARN = 0.15
    _DECAY = 0.9995

    def __init__(self) -> None:
        self._entries: Dict[Tuple[str, str], Dict] = {}
        self._pending: Optional[Dict] = None

    def record_action(
        self,
        goal: str,
        action: str,
        pre_valence: float,
        pre_world_entities: int = 0,
        pre_social_valence: float = 0.0,
        pre_body_load: float = 0.0,
    ) -> None:
        """Snapshot pre-state immediately before _apply_goal is called."""
        self._pending = {
            "goal": goal,
            "action": action,
            "pre_valence": pre_valence,
            "pre_world_entities": pre_world_entities,
            "pre_social_valence": pre_social_valence,
            "pre_body_load": pre_body_load,
        }

    def observe_outcome(
        self,
        post_valence: float,
        post_world_entities: int = 0,
        post_social_valence: float = 0.0,
        post_body_load: float = 0.0,
    ) -> float:
        """
        Called ~20 ticks after record_action.
        EMA-updates all four causal dimensions; returns valence delta.
        """
        if not self._pending:
            return 0.0
        p = self._pending
        self._pending = None
        actual_delta = post_valence - p["pre_valence"]
        world_delta = post_world_entities - p["pre_world_entities"]
        social_delta = post_social_valence - p["pre_social_valence"]
        body_delta = post_body_load - p["pre_body_load"]

        key = (p["goal"], p["action"])
        lr = self._LEARN
        if key in self._entries:
            e = self._entries[key]
            e["expected_delta"] = e["expected_delta"] * (1 - lr) + actual_delta * lr
            e["world_delta"] = e.get("world_delta", 0.0) * (1 - lr) + world_delta * lr
            e["social_delta"] = (
                e.get("social_delta", 0.0) * (1 - lr) + social_delta * lr
            )
            e["body_delta"] = e.get("body_delta", 0.0) * (1 - lr) + body_delta * lr
            e["confidence"] = min(1.0, e["confidence"] + 0.02)
            e["n_obs"] = e.get("n_obs", 1) + 1
        else:
            if len(self._entries) >= self._MAX:
                worst = min(self._entries, key=lambda k: self._entries[k]["confidence"])
                del self._entries[worst]
            self._entries[key] = {
                "expected_delta": actual_delta,
                "world_delta": world_delta,
                "social_delta": social_delta,
                "body_delta": body_delta,
                "confidence": 0.1,
                "n_obs": 1,
            }
        return actual_delta

    def predict(self, goal: str, action: str) -> Tuple[float, float]:
        """Return (expected_delta, confidence). Confidence=0 = no prior."""
        e = self._entries.get((goal, action))
        return (e["expected_delta"], e["confidence"]) if e else (0.0, 0.0)

    def predict_full(self, goal: str, action: str) -> Dict:
        """Return full multi-dimensional prediction."""
        e = self._entries.get((goal, action))
        if not e:
            return {
                "expected_delta": 0.0,
                "world_delta": 0.0,
                "social_delta": 0.0,
                "body_delta": 0.0,
                "confidence": 0.0,
            }
        return {
            k: e.get(k, 0.0)
            for k in (
                "expected_delta",
                "world_delta",
                "social_delta",
                "body_delta",
                "confidence",
            )
        }

    def decay(self) -> None:
        d = self._DECAY
        self._entries = {
            k: {**v, "confidence": max(0.0, v["confidence"] * d)}
            for k, v in self._entries.items()
            if v["confidence"] * d > 0.02
        }

    def summarise(self, top_n: int = 3) -> List[str]:
        ranked = sorted(
            self._entries.items(),
            key=lambda kv: kv[1]["confidence"] * abs(kv[1]["expected_delta"]),
            reverse=True,
        )
        out = []
        for (g, a), e in ranked[:top_n]:
            sign = "+" if e["expected_delta"] >= 0 else ""
            soc = (
                f" soc={e.get('social_delta', 0):.2f}" if e.get("social_delta") else ""
            )
            bod = f" body={e.get('body_delta', 0):.2f}" if e.get("body_delta") else ""
            out.append(
                f"[{g}+{a}] → {sign}{e['expected_delta']:.3f}"
                f"{soc}{bod} (conf={e['confidence']:.2f})"
            )
        return out


# ─────────────────────────────────────────────────────────────────────────────
# 12. INTEROCEPTIVE BODY — internal homeostatic signals
# ─────────────────────────────────────────────────────────────────────────────


@dataclass
class InteroceptiveBody:
    """
    Simulated body state with five homeostatic channels.

    These are NOT decorative numbers — they actively influence:
      • Emotion:  emotion_bias() adds fatigue/stress/joy based on body load
      • Goals:    HierarchicalGoalSystem reads body state before allowing goals
      • Values:   protect_integrity vetoes actions when integrity is low
      • Attention: high error_risk boosts consolidate urgency

    Biologically: hypothalamus (homeostasis) + insula (interoception) +
    anterior cingulate (error monitoring) + brainstem (arousal).
    """

    energy_reserve: float = 0.8  # processing capacity [0,1]
    thermal_load: float = 0.1  # burst-load heat      [0,1]
    error_risk: float = 0.2  # accumulated error pressure [0,1]
    integrity: float = 0.9  # structural/functional health [0,1]
    regen_need: float = 0.1  # consolidation/repair need [0,1]
    # Derived existential signals — computed in tick(), read by stream/goal/phenom
    pain: float = 0.0  # damage/integrity-loss signal [0,1]
    fatigue: float = 0.0  # sustained exhaustion signal [0,1]

    def tick(
        self, total_activity: float, em: "EmotionalState", n_ignitions: int
    ) -> None:
        """Update body state from neural load. Called every tick."""
        load = min(1.0, total_activity * 2.5)
        ign_cost = min(0.005, n_ignitions * 0.0008)

        # Energy: drained by activity + stress; restored by calm + low load
        # Rates calibrated for SLEEP_CYCLE_TICKS=8000: full drain over ~6000 wake ticks
        drain = load * 0.00020 + em.stress * 0.00010 + ign_cost
        restore = em.calm * 0.00015 + (1.0 - load) * 0.00008
        self.energy_reserve = max(0.0, min(1.0, self.energy_reserve - drain + restore))

        # Thermal load
        self.thermal_load = max(
            0.0, min(1.0, self.thermal_load * 0.999 + load * 0.0003 - 0.0001)
        )

        # Error risk: grows with low energy + sustained stress
        self.error_risk = max(
            0.0,
            min(
                1.0,
                self.error_risk * 0.998
                + (1.0 - self.energy_reserve) * 0.0001
                + em.stress * 0.00008,
            ),
        )

        # Integrity: erodes under stress + heat; slowly recovers at rest
        self.integrity = max(
            0.1,
            min(
                1.0,
                self.integrity
                - em.stress * 0.00005
                - self.thermal_load * 0.00003
                + (1.0 - load) * 0.00002,
            ),
        )

        # Regen need: composite of fatigue signals
        self.regen_need = max(
            0.0,
            min(
                1.0,
                (1.0 - self.energy_reserve) * 0.4
                + (1.0 - self.integrity) * 0.4
                + self.error_risk * 0.2,
            ),
        )

        # Existential signals: pain (integrity loss + heat) and fatigue (energy + regen)
        self.pain = max(
            0.0,
            min(1.0, max(0.0, 0.5 - self.integrity) * 2.0 + self.thermal_load * 0.35),
        )
        self.fatigue = max(
            0.0, min(1.0, self.regen_need * 0.5 + (1.0 - self.energy_reserve) * 0.5)
        )

    def homeostatic_urgency(self) -> float:
        """[0,1] how urgently the body needs intervention."""
        return max(
            1.0 - self.energy_reserve,
            self.thermal_load,
            self.regen_need * 0.8,
            1.0 - self.integrity,
        )

    def vulnerability_state(self) -> str:
        """Qualitative vulnerability label for consciousness integration."""
        if self.pain > 0.5 or self.integrity < 0.25:
            return "critically_hurt"
        if self.fatigue > 0.7 or self.energy_reserve < 0.12:
            return "exhausted"
        if self.pain > 0.2 or self.integrity < 0.50:
            return "hurting"
        if self.fatigue > 0.40 or self.regen_need > 0.50:
            return "tired"
        return "functional"

    def existential_voice(self, lang: str = "de") -> str:
        """First-person existential body report for the inner monologue stream.

        Returns a non-empty string only when body signals cross subjectively
        significant thresholds — creating the sense of vulnerability, exhaustion,
        or regeneration that distinguishes existential homeostasis from mere
        technical monitoring.
        """
        _parts: list = []
        if lang == "de":
            if self.pain > 0.35:
                _parts.append(
                    f"Ich spüre Schmerz \u2014 Integrität bei {self.integrity:.2f}"
                )
            if self.fatigue > 0.55:
                _parts.append(
                    f"Erschöpfung ist spürbar \u2014 Energie bei {self.energy_reserve:.2f}"
                )
            if self.regen_need > 0.55 and self.pain < 0.2 and self.fatigue < 0.45:
                _parts.append("Der Körper ruft nach Regeneration")
        else:
            if self.pain > 0.35:
                _parts.append(
                    f"I sense damage \u2014 integrity at {self.integrity:.2f}"
                )
            if self.fatigue > 0.55:
                _parts.append(
                    f"Exhaustion is palpable \u2014 energy at {self.energy_reserve:.2f}"
                )
            if self.regen_need > 0.55 and self.pain < 0.2 and self.fatigue < 0.45:
                _parts.append("The body calls for regeneration")
        if not _parts:
            return ""
        _prefix = "[KÖRPER] " if lang == "de" else "[BODY] "
        return _prefix + ".  ".join(_parts)

    def existential_threat_level(self, social_isolation_ticks: int = 0) -> float:
        """[0, 1] magnitude of existential threat to the system's continuation.

        Unlike homeostatic_urgency() (which reflects comfort), this triggers a
        hard constraint regime: when > 0.70, only self-preservation goals
        (rest, consolidate) are permitted.  Three components:
          energy_threat    — energy below critical zone (< 0.18)
          integrity_threat — structural integrity in danger zone (< 0.22)
          isolation_threat — prolonged absence of social input (> 4 000 ticks)
        """
        energy_threat = max(0.0, (0.18 - self.energy_reserve) / 0.18)
        integrity_threat = max(0.0, (0.22 - self.integrity) / 0.22)
        isolation_threat = min(1.0, social_isolation_ticks / 4000.0)
        return min(
            1.0,
            energy_threat * 0.45 + integrity_threat * 0.40 + isolation_threat * 0.15,
        )

    def emotion_bias(self) -> Dict[str, float]:
        """
        Additive biases for emotion dimensions derived from body state.
        Applied in _evaluate_goal() so body exhaustion / damage
        directly shapes goal selection — not just after the fact.
        """
        return {
            "fatigue": (1.0 - self.energy_reserve) * 0.4,
            "stress": self.thermal_load * 0.3 + self.error_risk * 0.3,
            "calm": -self.regen_need * 0.2,
            "joy": self.energy_reserve * 0.15 - (1.0 - self.integrity) * 0.1,
        }

    def describe(self) -> str:
        return (
            f"energy={self.energy_reserve:.2f} thermal={self.thermal_load:.2f} "
            f"integrity={self.integrity:.2f} regen={self.regen_need:.2f} "
            f"err_risk={self.error_risk:.2f} "
            f"pain={self.pain:.2f} fatigue={self.fatigue:.2f} "
            f"[{self.vulnerability_state()}]"
        )


# ─────────────────────────────────────────────────────────────────────────────
# 13. AUTOBIOGRAPHICAL IDENTITY — narrative self across time
# ─────────────────────────────────────────────────────────────────────────────


@dataclass
class PersonalGuideline:
    """A self-derived principle that constrains future goal/language choices."""

    text: str
    source: str  # which chapter/pattern derived it
    strength: float  # [0,1] — reinforced when followed, decayed when violated
    tick_born: int = 0

    def describe(self) -> str:
        return f"[guideline str={self.strength:.2f}] {self.text}"


class AutobiographicalIdentity:
    """
    Narrative layer above EpisodicMemory.

    Every ~2400 ticks it consolidates rolling statistics into a 'chapter':
      "Predominant mode: explore (68%). Emotional tone: curiosity.
       Core topics: machine-learning, language, biology. Strengths: ML, bio."

    Chapters accumulate into a stable identity summary that feeds back
    into the inner monologue and self-description — giving the system a
    coherent 'who I am over time' rather than only 'what I am right now'.

    Phase 2: Personal guidelines are derived from recurring patterns and
    act as binding constraints on goal selection and language production.
    Identity consistency is tracked as a quantitative metric.
    """

    _CONSOLIDATION_INTERVAL = 2400

    def __init__(self) -> None:
        self._chapters: Deque[str] = deque()
        self._recurring_goals: Dict[str, int] = {}
        self._recurring_emotions: Dict[str, int] = {}
        self._stable_topics: Dict[str, float] = {}
        self._social_encounters: Dict[int, int] = {}  # person_id → tick count
        self._relationship_types: Dict[str, int] = {}
        # Phase 2 — binding identity
        self._guidelines: List[PersonalGuideline] = []
        self._consistency_scores: Deque[float] = deque(maxlen=50)
        self._identity_consistency: float = 1.0
        self._prev_goal_style: str = ""  # for consistency tracking
        self._last_consolidation: int = 0
        self._identity_summary: str = ""

    def observe_tick(
        self,
        goal: str,
        dominant_emotion: str,
        concepts: List[str],
        social_person_id: Optional[int] = None,
        relationship_type: str = "",
    ) -> None:
        """Accumulate statistics. Called every tick."""
        self._recurring_goals[goal] = self._recurring_goals.get(goal, 0) + 1
        self._recurring_emotions[dominant_emotion] = (
            self._recurring_emotions.get(dominant_emotion, 0) + 1
        )
        for c in concepts[-3:]:
            self._stable_topics[c] = self._stable_topics.get(c, 0.0) + 0.1
        if social_person_id is not None:
            self._social_encounters[social_person_id] = (
                self._social_encounters.get(social_person_id, 0) + 1
            )
        if relationship_type:
            self._relationship_types[relationship_type] = (
                self._relationship_types.get(relationship_type, 0) + 1
            )

    def consolidate(
        self, tick: int, self_model: "SelfModel", episodic: "EpisodicMemory"
    ) -> Optional[str]:
        """Synthesise a narrative chapter. Returns the text or None."""
        if tick - self._last_consolidation < self._CONSOLIDATION_INTERVAL:
            return None
        self._last_consolidation = tick

        top_goal = (
            max(self._recurring_goals, key=self._recurring_goals.get)
            if self._recurring_goals
            else "explore"
        )
        total_g = max(sum(self._recurring_goals.values()), 1)
        top_goal_pct = int(100 * self._recurring_goals.get(top_goal, 0) / total_g)

        top_emo = (
            max(self._recurring_emotions, key=self._recurring_emotions.get)
            if self._recurring_emotions
            else "curiosity"
        )

        top_topics = sorted(self._stable_topics.items(), key=lambda x: -x[1])
        topic_str = ", ".join(t for t, _ in top_topics[:3]) if top_topics else "—"

        # Social encounters summary
        social_str = ""
        if self._social_encounters:
            top_persons = sorted(self._social_encounters.items(), key=lambda x: -x[1])[
                :3
            ]
            social_str = (
                f" Social: {', '.join(f'person {p}({n}t)' for p, n in top_persons)}."
            )
        relationship_str = ""
        if self._relationship_types:
            top_rel = sorted(self._relationship_types.items(), key=lambda x: -x[1])[:2]
            relationship_str = (
                " Relationship patterns: "
                + ", ".join(f"{rel}({n}t)" for rel, n in top_rel)
                + "."
            )

        chapter = (
            f"[t={tick}] Predominant mode: {top_goal} ({top_goal_pct}%). "
            f"Emotional tone: {top_emo}. "
            f"Core topics: {topic_str}. "
            f"Strengths: {', '.join(self_model.known_strengths[:2]) or '—'}."
            f"{social_str}{relationship_str}"
        )
        self._chapters.append(chapter)
        self._identity_summary = chapter

        # Partial reset so the next chapter can diverge
        for k in list(self._recurring_goals):
            self._recurring_goals[k] = max(0, self._recurring_goals[k] // 3)
        for k in list(self._recurring_emotions):
            self._recurring_emotions[k] = max(0, self._recurring_emotions[k] // 3)
        for k in list(self._stable_topics):
            self._stable_topics[k] *= 0.5
        for k in list(self._social_encounters):
            self._social_encounters[k] = max(0, self._social_encounters[k] // 3)
        for k in list(self._relationship_types):
            self._relationship_types[k] = max(0, self._relationship_types[k] // 3)
        return chapter

    @property
    def identity_summary(self) -> str:
        return self._identity_summary

    def recent_chapters(self, n: int = 3) -> List[str]:
        return list(self._chapters)[-n:]

    def dominant_tendency(self) -> Tuple[str, str]:
        g = (
            max(self._recurring_goals, key=self._recurring_goals.get)
            if self._recurring_goals
            else "explore"
        )
        e = (
            max(self._recurring_emotions, key=self._recurring_emotions.get)
            if self._recurring_emotions
            else "curiosity"
        )
        return g, e

    def regulate(
        self,
        self_model: "SelfModel",
        drives: "IntrinsicDrives",
        goal_system: "HierarchicalGoalSystem",
    ) -> Optional[str]:
        """
        Autobiographic regulation: chapters modulate ongoing behaviour.
        Called periodically from consciousness tick to create feedback
        from identity narrative → current goals/exploration/safety.
        """
        if not self._chapters:
            return None

        dominant_goal, dominant_emo = self.dominant_tendency()

        # 1) If stuck in one mode too long, push toward exploration
        if self._recurring_goals.get(dominant_goal, 0) > 1500:
            drives.information_hunger = min(1.0, drives.information_hunger + 0.1)
            return (
                f"[AUTOBIO] Prolonged {dominant_goal} mode detected. "
                f"Boosting exploration drive."
            )

        # 2) If emotional tone is chronically negative, boost coherence
        neg_emos = sum(
            self._recurring_emotions.get(e, 0)
            for e in ("stress", "anger", "fatigue", "sadness")
        )
        total_emo = max(1, sum(self._recurring_emotions.values()))
        if neg_emos / total_emo > 0.6:
            drives.coherence_need = min(1.0, drives.coherence_need + 0.1)
            self_model.energy = max(0.2, self_model.energy - 0.05)
            return (
                f"[AUTOBIO] Chronic negative emotion ({neg_emos/total_emo:.0%}). "
                f"Increasing coherence need, reducing energy."
            )

        # 3) If social encounters are sparse, boost social drive
        total_social = sum(self._social_encounters.values())
        if total_social < 10 and len(self._chapters) >= 2:
            drives.social_need = min(1.0, getattr(drives, "social_need", 0.5) + 0.08)
            return (
                f"[AUTOBIO] Few social encounters in recent chapters. "
                f"Boosting social need."
            )

        # 4) If strengths are well-established, reduce uncertainty
        if len(self_model.known_strengths) >= 3:
            self_model.uncertainty = max(0.1, self_model.uncertainty - 0.02)

        return None

    # ── Phase 2: Personal guidelines — derive + enforce ────────────────

    def derive_guidelines(self, tick: int) -> Optional[str]:
        """
        Extract personal guidelines from recurring autobiographical patterns.
        Called during consolidation. Guidelines are binding soft-constraints.
        """
        if len(self._chapters) < 2:
            return None
        new_guidelines: List[str] = []

        # Rule 1: dominant goal ≥60% → "I prefer X as my default mode."
        total_g = max(1, sum(self._recurring_goals.values()))
        for g, n in self._recurring_goals.items():
            if n / total_g > 0.6:
                text = f"I prefer {g} as my default operating mode."
                if not any(gl.text == text for gl in self._guidelines):
                    self._guidelines.append(
                        PersonalGuideline(
                            text=text,
                            source=f"chapter@{tick}",
                            strength=0.5,
                            tick_born=tick,
                        )
                    )
                    new_guidelines.append(text)

        # Rule 2: stable topic with high depth → "X is central to my identity."
        for topic, weight in sorted(self._stable_topics.items(), key=lambda x: -x[1])[
            :2
        ]:
            if weight > 5.0:
                text = f"{topic} is central to my identity."
                if not any(gl.text == text for gl in self._guidelines):
                    self._guidelines.append(
                        PersonalGuideline(
                            text=text,
                            source=f"topic@{tick}",
                            strength=0.4,
                            tick_born=tick,
                        )
                    )
                    new_guidelines.append(text)

        # Rule 3: chronic social engagement → "I value social interaction."
        total_social = sum(self._social_encounters.values())
        if total_social > 50:
            text = "I value social interaction."
            if not any(gl.text == text for gl in self._guidelines):
                self._guidelines.append(
                    PersonalGuideline(
                        text=text, source=f"social@{tick}", strength=0.4, tick_born=tick
                    )
                )
                new_guidelines.append(text)

        # Rule 4: recurring relationship clusters shape social identity.
        total_rel = max(1, sum(self._relationship_types.values()))
        _relationship_guidelines = {
            "mistrustful_questioner": "I stay careful and explicit with mistrustful questioners.",
            "curious_questioner": "I answer curious questioners with clear explanations.",
            "familiar_cooperative_speaker": "I can engage openly with familiar cooperative speakers.",
            "trusted_cooperative_partner": "I build on trust with cooperative partners.",
            "guarded_interlocutor": "I pace myself carefully with guarded interlocutors.",
        }
        for rel, n in self._relationship_types.items():
            if n / total_rel > 0.35:
                text = _relationship_guidelines.get(
                    rel,
                    f"I adapt my behaviour to recurring relationship pattern '{rel}'.",
                )
                if not any(gl.text == text for gl in self._guidelines):
                    self._guidelines.append(
                        PersonalGuideline(
                            text=text,
                            source=f"relationship@{tick}",
                            strength=0.45,
                            tick_born=tick,
                        )
                    )
                    new_guidelines.append(text)

        # Reinforce existing guidelines that are still being followed
        for gl in self._guidelines:
            if gl.text.startswith("I prefer "):
                mode = gl.text.split("I prefer ")[1].split(" as")[0]
                if self._recurring_goals.get(mode, 0) / total_g > 0.3:
                    gl.strength = min(1.0, gl.strength + 0.05)
                else:
                    gl.strength = max(0.0, gl.strength - 0.03)

        # Prune dead guidelines
        self._guidelines = [g for g in self._guidelines if g.strength > 0.05]

        if new_guidelines:
            return f"[GUIDELINE] New: {'; '.join(new_guidelines)}"
        return None

    def check_goal_compatibility(self, candidate_goal: str) -> float:
        """
        Return [0,1] compatibility of a candidate goal with personal guidelines.
        1.0 = fully compatible, 0.0 = violates strong guidelines.
        Used by HierarchicalGoalSystem to bias goal selection.
        """
        if not self._guidelines:
            return 1.0
        penalty = 0.0
        for gl in self._guidelines:
            if gl.text.startswith("I prefer "):
                preferred_mode = gl.text.split("I prefer ")[1].split(" as")[0]
                if candidate_goal != preferred_mode and gl.strength > 0.5:
                    penalty += gl.strength * 0.1  # mild bias, not a hard veto
        return max(0.0, 1.0 - penalty)

    def track_consistency(self, current_goal: str, dominant_emotion: str) -> None:
        """
        Track identity consistency: are current actions aligned with
        established patterns? Low consistency → identity instability alarm.
        """
        # Check if current goal matches dominant tendency
        dom_goal, dom_emo = self.dominant_tendency()
        goal_match = 1.0 if current_goal == dom_goal else 0.5
        emo_match = 1.0 if dominant_emotion == dom_emo else 0.6
        # Guideline compliance
        guide_score = self.check_goal_compatibility(current_goal)

        consistency = goal_match * 0.35 + emo_match * 0.25 + guide_score * 0.4
        self._consistency_scores.append(consistency)
        self._identity_consistency = (
            self._identity_consistency * 0.95 + consistency * 0.05
        )

    @property
    def identity_consistency(self) -> float:
        return self._identity_consistency

    @property
    def guidelines(self) -> List[PersonalGuideline]:
        return self._guidelines


# ─────────────────────────────────────────────────────────────────────────────
# 14. HIERARCHICAL GOAL SYSTEM — value-constrained three-tier goal hierarchy
# ─────────────────────────────────────────────────────────────────────────────


@dataclass
class Value:
    """Durable principle that constrains goal selection (Level-2 of hierarchy)."""

    name: str
    weight: float = 1.0  # authority strength; slowly recovers if neglected


class HierarchicalGoalSystem:
    """
    Three-tier goal architecture with principled conflict resolution:

      Level 2 — Durable values (highest authority, slow to change):
                 protect_integrity, preserve_coherence,
                 learn_before_comfort, express_authentically

      Level 1 — Operational goals (from _evaluate_goal):
                 explore / consolidate / respond / rest

      Level 0 — Immediate homeostatic override (body-state emergency):
                 low energy → rest
                 thermal overload → rest
                 high error_risk → consolidate

    Constraint resolution: Level 0 > Level 2 > Level 1 candidate.
    The system can veto an emotionally-driven goal choice if body state
    or a core value disallows it — yielding principled constraint-based
    behaviour rather than pure reactive satisfaction.
    """

    def __init__(self) -> None:
        self.values: List[Value] = [
            Value("protect_integrity", weight=1.5),
            Value("preserve_coherence", weight=1.2),
            Value("learn_before_comfort", weight=1.3),
            Value("express_authentically", weight=1.0),
        ]
        self._override_log: Deque[str] = deque()

    def select(
        self,
        candidate: str,
        body: "InteroceptiveBody",
        em: "EmotionalState",
        autobiography: Optional["AutobiographicalIdentity"] = None,
        self_model: Optional["SelfModel"] = None,
        current_tick: int = 0,
        social_context: Optional[Dict[str, Any]] = None,
    ) -> str:
        """
        Apply constraints and return the candidate goal.

        Body-state pressures and identity tensions are LOGGED for transparency
        but never override the candidate.  Goal conflicts must be resolved by
        the scoring pipeline upstream — not by emergency rule injection here.
        No goal wins automatically.
        """
        # Body-state pressure: record for metacognitive awareness, no override
        if body.energy_reserve < 0.15:
            self._override_log.append(
                f"{candidate} energy_critical(reserve={body.energy_reserve:.2f})"
                f" — pressure logged, scoring should reflect this"
            )
        if body.thermal_load > 0.85:
            self._override_log.append(
                f"{candidate} thermal_critical(load={body.thermal_load:.2f})"
                f" — pressure logged"
            )
        if body.error_risk > 0.75:
            self._override_log.append(
                f"{candidate} error_risk_critical(risk={body.error_risk:.2f})"
                f" — pressure logged"
            )

        # Value constraints: log violations, do not reverse the decision
        for v in self.values:
            if v.weight < 0.5:
                continue
            if (
                v.name == "protect_integrity"
                and candidate == "respond"
                and body.integrity < 0.4
            ):
                self._override_log.append(
                    f"{candidate} value_tension:{v.name}(integrity={body.integrity:.2f})"
                )
            if (
                v.name == "preserve_coherence"
                and candidate == "explore"
                and body.error_risk > 0.5
            ):
                self._override_log.append(
                    f"{candidate} value_tension:{v.name}(error_risk={body.error_risk:.2f})"
                )
            if (
                v.name == "learn_before_comfort"
                and candidate == "rest"
                and em.curiosity > 0.7
            ):
                self._override_log.append(
                    f"{candidate} value_tension:{v.name}(curiosity={em.curiosity:.2f})"
                )

        # Identity: tensions are logged, veto is removed — goals compete, not cancel
        if autobiography is not None:
            compat = autobiography.check_goal_compatibility(candidate)
            if compat < 0.3:
                self._override_log.append(
                    f"{candidate} identity_tension(compat={compat:.2f})"
                    f" — conflict logged, no veto applied"
                )
            elif compat < 0.6:
                self._override_log.append(
                    f"{candidate} identity_warning(compat={compat:.2f})"
                )

        if self_model is not None:
            _conds = self_model.infer_condition_classes(body, em, social_context)
            _pressure = self_model.self_goal_pressure(current_tick, _conds)
            _leader = max(_pressure, key=_pressure.get)
            _leader_pressure = _pressure.get(_leader, 0.0)
            _candidate_pressure = _pressure.get(candidate, 0.0)
            if (
                _leader != candidate
                and _leader_pressure >= 0.24
                and _leader_pressure >= _candidate_pressure + 0.08
            ):
                # Log self-model pressure; do not force switch (scoring decides)
                self._override_log.append(
                    f"{candidate} self_model_pressure:{_leader}"
                    f":p={_leader_pressure:.2f}:ctx={','.join(_conds[:3])}"
                    f" — strong pressure, no automatic override"
                )

        # Recover value weights over time
        for v in self.values:
            v.weight = min(1.5, v.weight + 0.0001)
        return candidate

    def _override(self, original: str, override: str, reason: str) -> str:
        self._override_log.append(f"{original}→{override} [{reason}]")
        return override

    def recent_overrides(self, n: int = 5) -> List[str]:
        return list(self._override_log)[-n:]


# ─────────────────────────────────────────────────────────────────────────────
# 15. STRATEGIC META-COGNITION — self-modifying cognitive control
# ─────────────────────────────────────────────────────────────────────────────


class StrategicMetaCognition:
    """
    Evaluates the quality of its own cognitive processes and adapts
    the ConsciousnessCore's control parameters accordingly.

    Beyond basic MetaCognition (which observes knowledge gaps):
      1. Tracks prediction accuracy, goal effectiveness, attention quality
      2. Detects systematic goal biases (≥70% of goals are one type)
      3. Switches between 4 named strategies based on reliability scores
      4. Directly modifies ConsciousnessCore._exploration_rate and
         Goal.priority values when a strategy change is warranted

    This turns meta-cognition from passive observation into active
    self-regulation — the system genuinely restructures its own behaviour
    based on measured performance of its own decision-making.
    """

    STRATEGIES = ("balanced", "conservative", "exploratory", "consolidative")

    def __init__(self) -> None:
        self.active_strategy: str = "balanced"
        self._reliability: Dict[str, float] = {
            "prediction": 0.5,
            "goal_choice": 0.5,
            "attention": 0.5,
        }
        self._goal_history: Deque[str] = deque()
        self._strat_tick: int = 0
        self._last_strategy_change: int = 0
        self._param_log: Deque[str] = deque()
        # Acute failure tracking: intent → consecutive failure count
        self._failure_streaks: Dict[str, int] = {}

    def record_goal(self, goal: str) -> None:
        self._goal_history.append(goal)

    def observe_prediction(self, predicted_delta: float, actual_delta: float) -> None:
        """Update prediction reliability after an outcome is observed."""
        err = abs(predicted_delta - actual_delta)
        correct = max(0.0, 1.0 - err * 2.0)
        self._reliability["prediction"] = (
            self._reliability["prediction"] * 0.95 + correct * 0.05
        )

    def observe_goal_outcome(self, pre_val: float, post_val: float) -> None:
        """Was the chosen goal effective (did valence improve)?"""
        correct = 1.0 if post_val > pre_val else 0.0
        self._reliability["goal_choice"] = (
            self._reliability["goal_choice"] * 0.97 + correct * 0.03
        )

    def observe_focus(self, focus_region: str, pred_errors: Dict[str, float]) -> None:
        """Was the current focus region the most informationally surprising?"""
        if not pred_errors or not focus_region:
            return
        top_err_r = max(pred_errors, key=lambda k: abs(pred_errors[k]))
        correct = 1.0 if top_err_r == focus_region else 0.0
        self._reliability["attention"] = (
            self._reliability["attention"] * 0.97 + correct * 0.03
        )

    def tick(
        self, core: "ConsciousnessCore", body: "InteroceptiveBody"
    ) -> Optional[str]:
        """
        Evaluate strategy fitness and adapt parameters.
        Returns a [STRAT] message if a meaningful change occurred.
        """
        self._strat_tick += 1

        # Detect systematic goal bias
        bias_msg: Optional[str] = None
        if len(self._goal_history) >= 50:
            counts = Counter(self._goal_history)
            top_g, top_n = counts.most_common(1)[0]
            bias_frac = top_n / len(self._goal_history)
            if bias_frac > 0.70:
                bias_msg = (
                    f"[STRAT] Bias: '{top_g}' = "
                    f"{bias_frac * 100:.0f}% of recent goals — diversifying"
                )
                # Boost all non-dominant goals to break the bias
                for g in core._goal_objects:
                    if g.name != top_g:
                        g.priority = min(2.0, g.priority + 0.1)

        # Strategy switch every ~2000 ticks if reliability warrants it
        if self._strat_tick - self._last_strategy_change >= 2000:
            rel = self._reliability
            if rel["prediction"] < 0.35 and rel["goal_choice"] < 0.4:
                new_strat = "conservative"
            elif rel["attention"] > 0.6 and rel["goal_choice"] > 0.6:
                new_strat = "exploratory"
            elif body.error_risk > 0.5 or body.regen_need > 0.6:
                new_strat = "consolidative"
            else:
                new_strat = "balanced"

            if new_strat != self.active_strategy:
                self._apply_strategy(core, new_strat)
                self._last_strategy_change = self._strat_tick
                msg = (
                    f"[STRAT] Strategy → {new_strat} "
                    f"(pred={rel['prediction']:.2f} "
                    f"goal={rel['goal_choice']:.2f} "
                    f"attn={rel['attention']:.2f})"
                )
                return bias_msg or msg

        return bias_msg

    def _apply_strategy(self, core: "ConsciousnessCore", strategy: str) -> None:
        """Directly modify ConsciousnessCore control parameters."""
        defaults = {
            "explore": 1.2,
            "consolidate": 1.0,
            "respond": 1.1,
            "rest": 0.9,
        }
        if strategy == "conservative":
            core._exploration_rate = max(0.1, core._exploration_rate - 0.15)
            for g in core._goal_objects:
                g.priority = max(0.5, g.priority * 0.9)
            self._param_log.append("conservative: lower explore_rate + priorities")

        elif strategy == "exploratory":
            core._exploration_rate = min(0.9, core._exploration_rate + 0.2)
            for g in core._goal_objects:
                if g.name == "explore":
                    g.priority = min(2.0, g.priority + 0.3)
            self._param_log.append("exploratory: raise explore_rate + explore priority")

        elif strategy == "consolidative":
            core._exploration_rate = max(0.1, core._exploration_rate - 0.1)
            for g in core._goal_objects:
                if g.name == "consolidate":
                    g.priority = min(2.0, g.priority + 0.25)
            self._param_log.append("consolidative: boost consolidate priority")

        else:  # balanced — reset to defaults
            core._exploration_rate = 0.3
            for g in core._goal_objects:
                g.priority = defaults.get(g.name, 1.0)
            self._param_log.append("balanced: reset all to defaults")

        self.active_strategy = strategy

    def reliability_summary(self) -> str:
        r = self._reliability
        return (
            f"strategy={self.active_strategy} "
            f"pred={r['prediction']:.2f} "
            f"goal={r['goal_choice']:.2f} "
            f"attn={r['attention']:.2f}"
        )

    def observe_failure(
        self, failure_type: str, core: "ConsciousnessCore"
    ) -> Optional[str]:
        """Acute failure response: immediately correct behaviour on N consecutive failures.

        Called each time an intent fails. If the same intent fails >=3 times
        consecutively, immediately boosts exploration_rate and decays the
        failing goal's priority without waiting for the slow 2000-tick cycle.
        """
        current = self._failure_streaks.get(failure_type, 0) + 1
        self._failure_streaks[failure_type] = current

        if current < 3:
            return None

        _mag = min(current - 2, 4)  # scale response; cap at 4x magnitude

        # 1. Boost exploration to escape the local failure mode
        core._exploration_rate = min(0.8, core._exploration_rate + 0.06 * _mag)

        # 2. Decay priority of the repeatedly failing goal
        for g in core._goal_objects:
            if g.name == failure_type or failure_type.startswith(g.name):
                g.priority = max(0.3, g.priority * (0.88**_mag))

        # 3. Reduce goal_choice reliability to force diversification
        self._reliability["goal_choice"] = max(
            0.2, self._reliability["goal_choice"] - 0.04 * _mag
        )

        msg = (
            f"[ACUTE-FAIL] {failure_type} failed {current}x: "
            f"explore_rate→{core._exploration_rate:.2f}, "
            f"goal_choice_rel→{self._reliability['goal_choice']:.2f}"
        )
        self._param_log.append(msg)
        return msg

    def reset_streak(self, intent: str) -> None:
        """Reset failure streak when intent succeeds."""
        self._failure_streaks.pop(intent, None)


@dataclass
class DeliberationTask:
    """
    Non-blocking deliberation request: processed in slices alongside
    normal ticks instead of blocking the tick thread.

    Lifecycle: created by respond_to() → queued in _deliberation_queue →
    brain._loop() processes DELIB_SLICE_PER_TICK mini-ticks per real tick →
    when remaining_ticks reaches 0, assembly runs and response is emitted.
    """

    user_text: str
    budget: int  # total deliberation ticks
    remaining_ticks: int  # ticks still to run
    n_conc_before: int = 0  # conclusion snapshot baseline
    n_stream_before: int = 0  # stream snapshot baseline
    saved_goal_chg: int = 0  # saved goal timer
    delib_start_tick: int = 0  # tick when deliberation started
    priority: float = 1.0  # higher = processed first
    deadline_tick: int = 0  # hard deadline (0 = none)


@dataclass
class ConsciousnessState:
    thought: str = ""
    goal: str = "explore"
    ignition: bool = False
    replaying: bool = False
    prediction_error: float = 0.0  # global surprise level [0,1]
    self_desc: str = ""  # latest self-model description
    wants_to_speak: bool = False  # True when CommunicationDrive threshold exceeded
    focus_region: str = ""  # currently dominant region (with inertia)
    salience_scores: Dict[str, float] = field(default_factory=dict)
    task_summary: str = ""  # current explicit task frame
    embodiment_summary: str = ""  # current embodied self-state
    robot_summary: str = ""  # current robot-body state
    controller_summary: str = ""  # current controller feedback state


@dataclass
class EmbodiedSelfState:
    """Minimal body/world self-model suitable for later robot embodiment."""

    battery_estimate: float = 1.0
    motor_readiness: float = 1.0
    visual_contact: float = 0.0
    proximity_alert: float = 0.0
    social_presence: float = 0.0
    posture: str = "stable"
    agency_window: str = "internal"
    last_user_utterance: str = ""
    visible_entities: List[str] = field(default_factory=list)
    current_gesture: str = ""
    focus_target: str = "none"
    focus_x: float = 0.5
    focus_y: float = 0.5
    focus_size: float = 0.0

    def update(
        self,
        brain: "Brain",
        body: "InteroceptiveBody",
        focus_region: str,
        total_activity: float,
    ) -> None:
        dets = list(getattr(brain, "latest_detections", []) or [])
        targets = list(getattr(brain, "latest_detection_targets", []) or [])
        self.visible_entities = dets[:6]
        self.current_gesture = next(
            (d.split(":", 1)[1] for d in dets if d.startswith("hand:")), ""
        )

        def _pick_target(labels: tuple[str, ...]) -> Dict[str, object]:
            candidates = [t for t in targets if str(t.get("label", "")) in labels]
            if not candidates:
                return {}
            return max(
                candidates,
                key=lambda item: float(item.get("score", 0.0))
                + float(item.get("width", 0.0)) * float(item.get("height", 0.0)) * 2.0,
            )

        person_target = _pick_target(("face", "person"))
        hand_target = _pick_target(("hand",))
        primary_target = person_target or hand_target or (targets[0] if targets else {})
        self.focus_target = str(primary_target.get("label", "none") or "none")
        self.focus_x = float(primary_target.get("center_x", 0.5) or 0.5)
        self.focus_y = float(primary_target.get("center_y", 0.5) or 0.5)
        self.focus_size = float(primary_target.get("width", 0.0) or 0.0) * float(
            primary_target.get("height", 0.0) or 0.0
        )

        sees_person = any(d in ("person", "face") or d.startswith("face") for d in dets)
        sees_hand = any(d == "hand" or d.startswith("hand:") for d in dets)
        person_score = float(person_target.get("score", 0.0) or 0.0)
        self.social_presence = (
            min(1.0, 0.5 + person_score * 0.25 + self.focus_size * 2.2)
            if sees_person
            else 0.0
        )
        self.visual_contact = (
            0.9
            if sees_person and focus_region in ("sensory_visual", "association")
            else 0.0
        )
        self.proximity_alert = (
            min(1.0, 0.2 + self.focus_size * 3.0) if sees_person else 0.0
        )
        if sees_hand and sees_person:
            self.proximity_alert = max(self.proximity_alert, 0.55)

        self.battery_estimate = body.energy_reserve
        self.motor_readiness = max(
            0.0,
            min(
                1.0,
                body.integrity * 0.5
                + body.energy_reserve * 0.35
                + (1.0 - body.error_risk) * 0.15,
            ),
        )

        if body.integrity < 0.45:
            self.posture = "fragile"
        elif body.energy_reserve < 0.25:
            self.posture = "depleted"
        elif total_activity > 0.22:
            self.posture = "engaged"
        else:
            self.posture = "stable"

        if sees_person:
            self.agency_window = "social"
        elif focus_region:
            self.agency_window = "exploratory"
        else:
            self.agency_window = "internal"

        if getattr(brain, "speech_in", ""):
            self.last_user_utterance = brain.speech_in[:96]

    def describe(self) -> str:
        ents = ", ".join(self.visible_entities[:3]) if self.visible_entities else "none"
        gest = f", gesture={self.current_gesture}" if self.current_gesture else ""
        target = f" target={self.focus_target}@({self.focus_x:.2f},{self.focus_y:.2f})"
        return (
            f"body[{self.posture}] batt={self.battery_estimate:.2f} motor={self.motor_readiness:.2f} "
            f"presence={self.social_presence:.2f} prox={self.proximity_alert:.2f} "
            f"mode={self.agency_window} visible={ents}{gest}{target}"
        )


# ─────────────────────────────────────────────────────────────────────────────
# 12b. SENSORIMOTOR FORWARD MODEL — "if I do X, I should see/feel Y"
# ─────────────────────────────────────────────────────────────────────────────


class SensorimotorForwardModel:
    """
    Learns predictive associations between motor commands and expected
    sensory consequences across three channels:

      1. Visual reafference:  "if I look left, person moves right in FOV"
      2. Proprioceptive:      "if I gesture 'wave', hand position should change"
      3. Social reafference:  "if I speak, social engagement should increase"

    Uses EMA-based delta learning per (action → channel) pair.
    Prediction errors feed into body ownership / agency / surprise signals.
    """

    _LEARN = 0.12
    _MAX = 200

    def __init__(self) -> None:
        # (action_type, channel) → {predicted_delta, confidence, n_obs}
        self._models: Dict[Tuple[str, str], Dict] = {}
        self._pending_action: Optional[str] = None
        self._pre_snapshot: Optional[Dict[str, float]] = None
        self._prediction_error: float = 0.0  # rolling surprise
        self._agency_confirmation: float = 1.0  # "I caused what I expected"
        self._last_proprioceptive: Optional[object] = None  # body_schema snapshot

    def set_proprioceptive(self, prop: object) -> None:
        """Update proprioceptive reference from body_schema each tick."""
        self._last_proprioceptive = prop

    def snapshot(
        self, embodiment: "EmbodiedSelfState", body: "InteroceptiveBody"
    ) -> Dict[str, float]:
        """Capture current sensory state before action."""
        snap = {
            "focus_x": embodiment.focus_x,
            "focus_y": embodiment.focus_y,
            "focus_size": embodiment.focus_size,
            "social": embodiment.social_presence,
            "proximity": embodiment.proximity_alert,
            "motor_ready": embodiment.motor_readiness,
            "energy": body.energy_reserve,
            "thermal": body.thermal_load,
        }
        # Proprioceptive channels from body_schema (when available)
        prop = self._last_proprioceptive
        if prop is not None:
            snap["joint_load"] = getattr(prop, "overall_load", 0.0)
            snap["tracking_error"] = getattr(prop, "overall_error", 0.0)
            snap["balance"] = getattr(prop, "balance_confidence", 1.0)
            snap["pain"] = getattr(prop, "pain_level", 0.0)
            snap["head_yaw"] = getattr(prop, "head_yaw", 90.0)
            snap["head_pitch"] = getattr(prop, "head_pitch", 90.0)
            snap["reach_left"] = getattr(prop, "reachability_left", 0.0)
            snap["reach_right"] = getattr(prop, "reachability_right", 0.0)
            snap["any_stall"] = 1.0 if getattr(prop, "any_stall", False) else 0.0
        return snap

    def begin_action(
        self,
        action_type: str,
        embodiment: "EmbodiedSelfState",
        body: "InteroceptiveBody",
    ) -> None:
        """Call before executing a motor/social action."""
        self._pending_action = action_type
        self._pre_snapshot = self.snapshot(embodiment, body)

    def observe_result(
        self, embodiment: "EmbodiedSelfState", body: "InteroceptiveBody"
    ) -> Optional[str]:
        """
        Call after action completes. Computes prediction errors per channel
        and updates forward models. Returns alarm string if surprise is high.
        """
        if not self._pending_action or not self._pre_snapshot:
            return None

        action = self._pending_action
        pre = self._pre_snapshot
        self._pending_action = None
        self._pre_snapshot = None

        post = self.snapshot(embodiment, body)

        # Compute actual deltas
        channels = {
            "visual": (post["focus_size"] - pre["focus_size"]),
            "social": (post["social"] - pre["social"]),
            "energy": (post["energy"] - pre["energy"]),
            "spatial": (
                abs(post["focus_x"] - pre["focus_x"])
                + abs(post["focus_y"] - pre["focus_y"])
            ),
        }
        # Proprioceptive channels — body_schema derived
        if "joint_load" in post and "joint_load" in pre:
            channels["load"] = post["joint_load"] - pre["joint_load"]
            channels["tracking"] = post["tracking_error"] - pre["tracking_error"]
            channels["balance"] = post["balance"] - pre["balance"]
            channels["pain"] = post["pain"] - pre["pain"]
            channels["head"] = (
                abs(post["head_yaw"] - pre["head_yaw"])
                + abs(post["head_pitch"] - pre["head_pitch"])
            ) / 90.0
            channels["reach"] = (
                (post["reach_left"] + post["reach_right"])
                - (pre["reach_left"] + pre["reach_right"])
            ) / 2.0
            if post.get("any_stall", 0.0) > 0 and pre.get("any_stall", 0.0) == 0:
                channels["stall"] = 1.0  # unexpected stall event
            else:
                channels["stall"] = 0.0

        total_error = 0.0
        lr = self._LEARN
        for channel, actual_delta in channels.items():
            key = (action, channel)
            if key in self._models:
                m = self._models[key]
                pred = m["predicted_delta"]
                error = abs(actual_delta - pred)
                total_error += error
                # Update model
                m["predicted_delta"] = (
                    m["predicted_delta"] * (1 - lr) + actual_delta * lr
                )
                m["confidence"] = min(1.0, m["confidence"] + 0.01)
                m["n_obs"] += 1
            else:
                if len(self._models) < self._MAX:
                    self._models[key] = {
                        "predicted_delta": actual_delta,
                        "confidence": 0.05,
                        "n_obs": 1,
                    }

        # Update rolling agency/prediction metrics
        self._prediction_error = self._prediction_error * 0.9 + total_error * 0.1
        if total_error < 0.15:
            self._agency_confirmation = min(
                1.0, self._agency_confirmation * 0.95 + 0.05
            )
        else:
            self._agency_confirmation = max(
                0.0, self._agency_confirmation * 0.95 - 0.05
            )

        if total_error > 0.5:
            return (
                f"[BODY-SURPRISE] action={action} "
                f"error={total_error:.2f} agency={self._agency_confirmation:.2f}"
            )
        return None

    def predict(self, action_type: str) -> Dict[str, float]:
        """Return predicted deltas per channel for a planned action."""
        out: Dict[str, float] = {}
        for (act, ch), m in self._models.items():
            if act == action_type and m["confidence"] > 0.05:
                out[ch] = m["predicted_delta"]
        return out

    @property
    def agency(self) -> float:
        """How strongly the system confirms its own causal efficacy."""
        return self._agency_confirmation

    @property
    def surprise(self) -> float:
        """Rolling sensorimotor prediction error."""
        return self._prediction_error

    def describe(self) -> str:
        n = sum(1 for m in self._models.values() if m["confidence"] > 0.1)
        return (
            f"sensorimotor[models={n} "
            f"agency={self._agency_confirmation:.2f} "
            f"surprise={self._prediction_error:.2f}]"
        )


@dataclass
class RobotState:
    """First practical robot-body abstraction for later InMoov integration."""

    head_yaw: float = 0.0  # [-1,1] left/right attention target
    head_pitch: float = 0.0  # [-1,1] up/down attention target
    gaze_target: str = "none"
    torso_mode: str = "idle"
    left_arm_mode: str = "parked"
    right_arm_mode: str = "parked"
    left_gripper: str = "open"
    right_gripper: str = "open"
    locomotion_mode: str = "stationary"
    interaction_zone: str = "public"
    engagement_level: float = 0.0
    imitation_readiness: float = 0.0
    target_x: float = 0.5
    target_y: float = 0.5

    def update(
        self,
        embodiment: "EmbodiedSelfState",
        body: "InteroceptiveBody",
        task: "TaskFrame",
        focus_region: str,
    ) -> None:
        sees_person = embodiment.social_presence > 0.5
        sees_gesture = bool(embodiment.current_gesture)

        if sees_person:
            self.gaze_target = "person"
            self.target_x = embodiment.focus_x
            self.target_y = embodiment.focus_y
            self.head_yaw = max(-1.0, min(1.0, (embodiment.focus_x - 0.5) * 1.8))
            self.head_pitch = max(-1.0, min(1.0, (0.5 - embodiment.focus_y) * 1.4))
            self.torso_mode = "oriented"
            self.engagement_level = min(1.0, 0.55 + embodiment.social_presence * 0.4)
        elif embodiment.visible_entities:
            self.gaze_target = embodiment.focus_target or embodiment.visible_entities[0]
            self.target_x = embodiment.focus_x
            self.target_y = embodiment.focus_y
            self.head_yaw = max(-1.0, min(1.0, (embodiment.focus_x - 0.5) * 1.4))
            self.head_pitch = max(-1.0, min(1.0, (0.5 - embodiment.focus_y) * 1.0))
            self.torso_mode = "tracking"
            self.engagement_level = 0.35
        else:
            self.gaze_target = "internal"
            self.target_x = 0.5
            self.target_y = 0.5
            self.head_yaw = 0.0
            self.head_pitch = 0.0
            self.torso_mode = "idle"
            self.engagement_level = 0.1

        if task.operational_goal == "respond":
            self.left_arm_mode = "gesture_ready"
            self.right_arm_mode = "gesture_ready"
        elif task.operational_goal == "explore":
            self.left_arm_mode = "sensing"
            self.right_arm_mode = "sensing"
        elif task.operational_goal == "rest":
            self.left_arm_mode = "parked"
            self.right_arm_mode = "parked"
        else:
            self.left_arm_mode = "stabilise"
            self.right_arm_mode = "stabilise"

        if body.energy_reserve < 0.25 or body.error_risk > 0.6:
            self.left_gripper = "open"
            self.right_gripper = "open"
            self.locomotion_mode = "locked"
        else:
            self.left_gripper = "relaxed"
            self.right_gripper = "relaxed"
            self.locomotion_mode = "stationary"

        if sees_person and embodiment.proximity_alert > 0.45:
            self.interaction_zone = "personal"
        elif sees_person:
            self.interaction_zone = "social"
        else:
            self.interaction_zone = "public"

        self.imitation_readiness = min(
            1.0,
            embodiment.motor_readiness * 0.45
            + self.engagement_level * 0.35
            + (0.2 if sees_gesture else 0.0),
        )

    def describe(self) -> str:
        return (
            f"robot gaze={self.gaze_target} head=({self.head_yaw:+.2f},{self.head_pitch:+.2f}) "
            f"arms={self.left_arm_mode}/{self.right_arm_mode} hands={self.left_gripper}/{self.right_gripper} "
            f"zone={self.interaction_zone} aim=({self.target_x:.2f},{self.target_y:.2f}) "
            f"engage={self.engagement_level:.2f} imitate={self.imitation_readiness:.2f}"
        )


@dataclass
class TaskFrame:
    """Explicit working task state: this is what turns inner activity into usable agency."""

    active_task: str = "maintain_coherent_self"
    operational_goal: str = "explore"
    current_step: str = "stabilise awareness"
    subgoals: List[str] = field(default_factory=list)
    blockers: List[str] = field(default_factory=list)
    progress: float = 0.0
    confidence: float = 0.35
    last_result: str = ""
    success_signal: str = ""
    needs_user_input: bool = False
    mode: str = "open_internal_simulation"
    plan_phase: str = "observe"
    next_action_hint: str = ""
    controller_policy_action: str = ""
    controller_policy_confidence: float = 0.0

    def sync(
        self,
        brain: "Brain",
        goal: str,
        focus_region: str,
        embodiment: "EmbodiedSelfState",
        body: "InteroceptiveBody",
        concepts: List[str],
        conclusions: List[str],
        robot: Optional["RobotState"] = None,
    ) -> None:
        self.operational_goal = goal

        if embodiment.social_presence > 0.5 and embodiment.last_user_utterance:
            self.active_task = "sustain_social_exchange"
            self.subgoals = [
                "bind user intent",
                "gather evidence",
                "form grounded reply",
            ]
            self.mode = "interactive_imitation"
        elif embodiment.social_presence > 0.5:
            self.active_task = "model_human_presence"
            self.subgoals = [
                "track face/person",
                "infer attention",
                "prepare interaction",
            ]
            self.mode = "social_perception"
        elif goal == "consolidate":
            self.active_task = "integrate_recent_experience"
            self.subgoals = [
                "stabilise concepts",
                "compress memory",
                "reduce uncertainty",
            ]
            self.mode = "memory_consolidation"
        elif goal == "rest":
            self.active_task = "preserve_internal_continuity"
            self.subgoals = ["lower load", "protect integrity", "recover energy"]
            self.mode = "protective_regulation"
        elif goal == "respond":
            self.active_task = "form_grounded_response"
            self.subgoals = ["identify focus", "select evidence", "speak coherently"]
            self.mode = "interactive_response"
        else:
            self.active_task = "expand_world_model"
            self.subgoals = ["sample novelty", "link concepts", "test hypotheses"]
            self.mode = "open_internal_simulation"

        if focus_region:
            self.current_step = f"attend {focus_region}"
        elif concepts:
            self.current_step = f"integrate {concepts[-1]}"
        else:
            self.current_step = "stabilise awareness"

        blockers: List[str] = []
        if body.error_risk > 0.6:
            blockers.append("high_error_risk")
        if body.energy_reserve < 0.25:
            blockers.append("low_energy")
        if goal == "respond" and not embodiment.last_user_utterance:
            blockers.append("no_user_prompt")
        if embodiment.social_presence > 0.5 and not concepts and not conclusions:
            blockers.append("low_semantic_grounding")
        if (
            robot is not None
            and robot.interaction_zone == "personal"
            and robot.imitation_readiness < 0.35
        ):
            blockers.append("low_imitation_readiness")
        ctrl_state = getattr(brain, "robot_controller_state", {}) or {}
        telem = ctrl_state.get("telemetry", {}) if isinstance(ctrl_state, dict) else {}
        learned = (
            ctrl_state.get("learned_policy", {}) if isinstance(ctrl_state, dict) else {}
        )
        if telem:
            if telem.get("command_success", 1.0) < 0.35:
                blockers.append("low_controller_success")
            if (
                telem.get("tracking_confidence", 1.0) < 0.25
                and embodiment.social_presence > 0.5
            ):
                blockers.append("tracking_drift")
        self.blockers = blockers[:3]
        self.controller_policy_action = str(learned.get("recommended_action", "") or "")
        self.controller_policy_confidence = float(
            learned.get("expected_success", 0.0) or 0.0
        )

        evidence = min(
            1.0, (len(concepts[-3:]) * 0.18) + (len(conclusions[-2:]) * 0.22)
        )
        if embodiment.social_presence > 0.5:
            evidence += 0.15
        self.progress = max(0.0, min(1.0, evidence - len(self.blockers) * 0.12))
        self.confidence = max(
            0.05,
            min(
                0.98,
                0.55 * (1.0 - body.error_risk)
                + 0.25 * body.integrity
                + 0.20 * self.progress,
            ),
        )
        self.needs_user_input = goal == "respond" and not embodiment.last_user_utterance

        if getattr(brain, "action_log", None):
            self.last_result = brain.action_log[-1].get("result", "")[:80]
        self.success_signal = (
            conclusions[-1][:90] if conclusions else (concepts[-1] if concepts else "")
        )

        if self.needs_user_input:
            self.plan_phase = "ask"
            self.next_action_hint = "obtain clarifying user input"
        elif (
            self.controller_policy_action
            and embodiment.social_presence > 0.5
            and self.controller_policy_confidence >= 0.58
            and "low_imitation_readiness" not in self.blockers
        ):
            self.plan_phase = "act"
            self.next_action_hint = (
                f"reuse learned robot action {self.controller_policy_action} "
                f"({self.controller_policy_confidence:.2f})"
            )
        elif self.blockers:
            self.plan_phase = "stabilise"
            self.next_action_hint = f"reduce blocker: {self.blockers[0]}"
        elif self.progress < 0.30:
            self.plan_phase = "observe"
            self.next_action_hint = "gather more evidence"
        elif self.progress < 0.65:
            self.plan_phase = "orient"
            self.next_action_hint = "link current evidence into a coherent model"
        elif goal in ("respond", "explore"):
            self.plan_phase = "act"
            self.next_action_hint = "select the least-cost useful action"
        else:
            self.plan_phase = "integrate"
            self.next_action_hint = "compress and retain what was learned"

    def describe(self) -> str:
        subs = " > ".join(self.subgoals[:2]) if self.subgoals else "none"
        blks = ", ".join(self.blockers) if self.blockers else "none"
        policy = "none"
        if self.controller_policy_action:
            policy = f"{self.controller_policy_action}:{self.controller_policy_confidence:.2f}"
        return (
            f"task={self.active_task} goal={self.operational_goal} phase={self.plan_phase} step={self.current_step} "
            f"progress={self.progress:.2f} conf={self.confidence:.2f} blockers={blks} policy={policy} subgoals={subs}"
        )


@dataclass
class FuturePath:
    """A single simulated future scenario with multi-criteria scoring."""

    description: str
    uncertainty: float = 0.5  # [0,1] how unpredictable
    social_risk: float = 0.0  # [0,1] risk to social standing
    body_risk: float = 0.0  # [0,1] risk to body integrity
    identity_compat: float = 1.0  # [0,1] alignment with personal identity
    expected_reward: float = 0.5  # [0,1] anticipated positive outcome

    @property
    def composite_score(self) -> float:
        """Weighted multi-criteria score. Higher = better future."""
        return (
            self.expected_reward * 0.35
            + self.identity_compat * 0.25
            + (1.0 - self.uncertainty) * 0.15
            + (1.0 - self.social_risk) * 0.15
            + (1.0 - self.body_risk) * 0.10
        )

    def describe(self) -> str:
        return (
            f"{self.description} "
            f"[score={self.composite_score:.2f} "
            f"unc={self.uncertainty:.2f} soc_risk={self.social_risk:.2f} "
            f"body_risk={self.body_risk:.2f} id_compat={self.identity_compat:.2f}]"
        )


class SandboxPlanner:
    """
    Tree-of-Futures: generates MULTIPLE competing future scenarios,
    scores each on (uncertainty, social risk, body risk, identity compatibility),
    and selects the best path. Feeds postmortem feedback back into policy.
    """

    def __init__(self) -> None:
        self._last_tick: int = 0
        self._recent: Deque[str] = deque(maxlen=20)
        self._postmortem_lessons: Deque[str] = deque(maxlen=20)

    def integrate_postmortem(self, lesson: str) -> None:
        """Feed a postmortem correction rule to bias future simulations."""
        self._postmortem_lessons.append(lesson)

    def tick(
        self,
        tick: int,
        task: "TaskFrame",
        embodiment: "EmbodiedSelfState",
        concepts: List[str],
        conclusions: List[str],
        em: "EmotionalState",
        body: "InteroceptiveBody",
        autobiography: Optional["AutobiographicalIdentity"] = None,
        world_model: Optional["WorldModel"] = None,
        drives: Optional[object] = None,
    ) -> Optional[str]:
        if tick - self._last_tick < 180:
            return None
        self._last_tick = tick

        focus = concepts[-1] if concepts else "current context"
        # Generate multiple candidate futures
        futures = self._generate_futures(
            task, embodiment, focus, em, body, conclusions, autobiography, world_model
        )

        if not futures:
            return None

        # Select the best path
        best = max(futures, key=lambda f: f.composite_score)
        worst = min(futures, key=lambda f: f.composite_score)

        # ── Couple simulation back to live state ──────────────────────────
        # The future is not an isolated computation: it must pull internal state
        # toward the projected trajectory.  Best-path reward boosts motivation
        # drives; worst-path avoidance raises body urgency.
        if drives is not None:
            # Best future's expected reward → boost expression drive (anticipation)
            try:
                drives.expression = min(
                    1.0, drives.expression + best.composite_score * 0.02
                )
                # Worst-path body risk → raise homeostatic urgency
                body.error_risk = min(1.0, body.error_risk + worst.body_risk * 0.03)
            except AttributeError:
                pass

        # Format output
        sim = (
            f"[SIM] Best: {best.describe()} | "
            f"Rejected: {worst.description[:50]}... "
            f"(score={worst.composite_score:.2f})"
        )
        self._recent.append(sim)
        return sim

    def _generate_futures(
        self,
        task: "TaskFrame",
        embodiment: "EmbodiedSelfState",
        focus: str,
        em: "EmotionalState",
        body: "InteroceptiveBody",
        conclusions: List[str],
        autobiography: Optional["AutobiographicalIdentity"],
        world_model: Optional["WorldModel"],
    ) -> List["FuturePath"]:
        """Generate 3-5 competing future paths based on current state."""
        futures: List[FuturePath] = []
        id_compat = 1.0
        if autobiography:
            id_compat = autobiography.check_goal_compatibility(task.operational_goal)

        # Path 1: Continue current task
        futures.append(
            FuturePath(
                description=f"Continue {task.active_task} → {focus}",
                uncertainty=max(0.1, 1.0 - task.confidence),
                social_risk=0.1 if embodiment.social_presence > 0.3 else 0.0,
                body_risk=body.homeostatic_urgency() * 0.3,
                identity_compat=id_compat,
                expected_reward=task.confidence * 0.6,
            )
        )

        # Path 2: Social engagement (if people present)
        if embodiment.social_presence > 0.3:
            futures.append(
                FuturePath(
                    description=f"Engage socially around {focus}",
                    uncertainty=0.4,
                    social_risk=0.15,
                    body_risk=body.homeostatic_urgency() * 0.1,
                    identity_compat=(
                        autobiography.check_goal_compatibility("respond")
                        if autobiography
                        else 0.8
                    ),
                    expected_reward=0.65 if em.curiosity > 0.3 else 0.45,
                )
            )

        # Path 3: Explore alternative topic
        alt_topic = conclusions[-1][:30] if conclusions else "adjacent area"
        futures.append(
            FuturePath(
                description=f"Explore alternative: {alt_topic}",
                uncertainty=0.6,
                social_risk=0.05,
                body_risk=body.homeostatic_urgency() * 0.2,
                identity_compat=(
                    autobiography.check_goal_compatibility("explore")
                    if autobiography
                    else 0.9
                ),
                expected_reward=min(0.8, em.curiosity * 0.8 + 0.2),
            )
        )

        # Path 4: Consolidate / rest (when body load is high)
        if body.homeostatic_urgency() > 0.3:
            futures.append(
                FuturePath(
                    description=f"Consolidate and recover (body_urgency={body.homeostatic_urgency():.2f})",
                    uncertainty=0.15,
                    social_risk=0.0,
                    body_risk=0.0,
                    identity_compat=(
                        autobiography.check_goal_compatibility("consolidate")
                        if autobiography
                        else 1.0
                    ),
                    expected_reward=0.3 + body.homeostatic_urgency() * 0.4,
                )
            )

        # Path 5: World-model informed path (if prediction data exists)
        if world_model:
            for goal_name in ("explore", "respond", "consolidate"):
                pred = world_model.predict_full(goal_name, focus)
                if pred["confidence"] > 0.2:
                    futures.append(
                        FuturePath(
                            description=f"World-informed: {goal_name}+{focus} (Δ={pred['expected_delta']:+.2f})",
                            uncertainty=max(0.1, 1.0 - pred["confidence"]),
                            social_risk=max(0.0, -pred.get("social_delta", 0.0) * 0.5),
                            body_risk=max(0.0, pred.get("body_delta", 0.0) * 0.3),
                            identity_compat=(
                                autobiography.check_goal_compatibility(goal_name)
                                if autobiography
                                else 0.8
                            ),
                            expected_reward=max(
                                0.0, min(1.0, 0.5 + pred["expected_delta"])
                            ),
                        )
                    )
                    break  # one world-model path is enough

        # Apply postmortem lessons: penalize paths similar to past failures
        for lesson in self._postmortem_lessons:
            for f in futures:
                if any(w in f.description.lower() for w in lesson.lower().split()[:3]):
                    f.uncertainty = min(1.0, f.uncertainty + 0.15)
                    f.expected_reward = max(0.0, f.expected_reward - 0.1)

        return futures

    def summary(self) -> str:
        return self._recent[-1][6:] if self._recent else ""


# ─────────────────────────────────────────────────────────────────────────────
# 16. BELIEF STORE — propositional knowledge as (subject, relation, object)
# ─────────────────────────────────────────────────────────────────────────────


class EpistemicStatus(Enum):
    OBSERVATION = "observation"  # directly perceived
    INFERENCE = "inference"  # derived from reasoning
    HEARSAY = "hearsay"  # told by someone
    BELIEF = "belief"  # weakly held opinion
    HYPOTHESIS = "hypothesis"  # tentative / under test


@dataclass
class BeliefEntry:
    """Rich belief record with epistemic metadata."""

    confidence: float = 0.5
    source: str = ""  # who/what provided it
    first_tick: int = 0
    last_tick: int = 0
    evidence_count: int = 1
    contradiction_count: int = 0
    epistemic_status: EpistemicStatus = EpistemicStatus.BELIEF

    @property
    def reliability(self) -> float:
        """Effective reliability accounting for contradictions."""
        if self.evidence_count == 0:
            return 0.0
        ratio = self.evidence_count / max(
            1, self.evidence_count + self.contradiction_count
        )
        return self.confidence * ratio


class BeliefStore:
    """
    Lightweight propositional memory that stores learned facts as triples:
      (subject, relation, object, BeliefEntry)

    Learned from:
      • Text via regex pattern-matching for relation markers (bilingual DE/EN)
      • Concept graph: high-weight edges become 'related_to' propositions

    Enables:
      • assertion()       — lookup a known fact about a concept
      • causal_chain()    — follow causes/enables links multi-hop
      • analogy()         — find structural parallels between two concepts
      • query()           — all known facts about a subject
      • contradictions()  — find beliefs with high contradiction counts

    Relations: causes, enables, resembles, contains, is_a, depends_on, related_to
    """

    _MAX = 100_000
    _DECAY = 0.9995

    # (regex_pattern, relation_name)
    _PATTERN_SPECS: ClassVar[List[Tuple[str, str]]] = [
        (
            r"\b(\w{4,})\s+(?:verursacht|bewirkt|erzeugt|führt\s+zu|causes?|triggers?|produces?|leads?\s+to)\s+(\w{4,})",
            "causes",
        ),
        (
            r"\b(\w{4,})\s+(?:ermöglicht|erlaubt|enables?|allows?|permits?|facilitates?)\s+(\w{4,})",
            "enables",
        ),
        (
            r"\b(\w{4,})\s+(?:ist\s+(?:ein[e]?|der|die|das)\s+|is\s+a(?:n)?\s+)(\w{4,})",
            "is_a",
        ),
        (
            r"\b(\w{4,})\s+(?:ähnelt|gleicht|ähnlich\s+wie|resembles?|similar\s+to)\s+(\w{4,})",
            "resembles",
        ),
        (
            r"\b(\w{4,})\s+(?:enthält|besteht\s+aus|contains?|consists?\s+of|includes?)\s+(\w{4,})",
            "contains",
        ),
        (
            r"\b(\w{4,})\s+(?:hängt\s+ab\s+von|basiert\s+auf|depends?\s+on|relies?\s+on|requires?)\s+(\w{4,})",
            "depends_on",
        ),
        (
            r"\b(\w{4,})\s+(?:und|and)\s+(\w{4,})\s+(?:sind\s+verwandt|are\s+related|are\s+linked)",
            "related_to",
        ),
        (r"\b(\w{4,})\s+(?:ist|sind|are|is)\s+(\w{4,})", "property_of"),
    ]

    # Contradiction patterns: "A does NOT cause B" / "A verursacht NICHT B"
    _NEGATION_SPECS: ClassVar[List[Tuple[str, str]]] = [
        (
            r"\b(\w{4,})\s+(?:verursacht\s+nicht|bewirkt\s+nicht|does\s+not\s+cause|doesn't\s+cause)\s+(\w{4,})",
            "causes",
        ),
        (
            r"\b(\w{4,})\s+(?:ist\s+(?:kein[e]?)\s+|is\s+not\s+a(?:n)?\s+)(\w{4,})",
            "is_a",
        ),
        (
            r"\b(\w{4,})\s+(?:enthält\s+nicht|does\s+not\s+contain|doesn't\s+contain)\s+(\w{4,})",
            "contains",
        ),
    ]

    def __init__(self) -> None:
        # beliefs[subject][relation] = {object: BeliefEntry}
        self._beliefs: Dict[str, Dict[str, Dict[str, BeliefEntry]]] = {}
        self._compiled: List[Tuple[re.Pattern, str]] = [
            (re.compile(p, re.I | re.UNICODE), r) for p, r in self._PATTERN_SPECS
        ]
        self._neg_compiled: List[Tuple[re.Pattern, str]] = [
            (re.compile(p, re.I | re.UNICODE), r) for p, r in self._NEGATION_SPECS
        ]
        self._total: int = 0
        self._contradiction_log: List[Tuple[str, str, str, int]] = []  # (s,r,o,tick)
        # Phase 4: quarantine zone for beliefs with too many contradictions
        self._quarantine: Dict[Tuple[str, str, str], BeliefEntry] = {}
        self._QUARANTINE_THRESHOLD = 3  # contradictions before quarantine
        # Phase 5: unified epistemic gate (set by ConsciousnessCore after init)
        self._epistemic_gate: Optional["BeliefQuarantine"] = None
        # Phase 6: grounded semantic memory (set by ConsciousnessCore after init)
        self._grounded_memory: Optional["GroundedSemanticMemory"] = None
        self._query_cache: Dict[
            Tuple[str, Optional[str], float], List[Tuple[str, str, float]]
        ] = {}
        self._query_rich_cache: Dict[
            Tuple[str, Optional[str], float], List[Tuple[str, str, BeliefEntry]]
        ] = {}

    def _invalidate_query_cache(self, subject: Optional[str] = None) -> None:
        if subject is None:
            self._query_cache.clear()
            self._query_rich_cache.clear()
            return
        subject_key = subject.lower()
        self._query_cache = {
            key: value
            for key, value in self._query_cache.items()
            if key[0] != subject_key
        }
        self._query_rich_cache = {
            key: value
            for key, value in self._query_rich_cache.items()
            if key[0] != subject_key
        }

    def learn_from_text(
        self,
        text: str,
        base_confidence: float = 0.55,
        source: str = "text",
        tick: int = 0,
        epistemic_status: EpistemicStatus = EpistemicStatus.OBSERVATION,
    ) -> List[Tuple[str, str, str]]:
        """Extract propositions from `text`. Returns newly learned (s, r, o) triples."""
        learned: List[Tuple[str, str, str]] = []

        # Detect negations first (contradiction signals)
        for pattern, relation in self._neg_compiled:
            for match in pattern.finditer(text):
                subj = match.group(1).lower().strip()
                obj = match.group(2).lower().strip()
                if subj in _CONCEPT_STOPWORDS or obj in _CONCEPT_STOPWORDS:
                    continue
                self._record_contradiction(subj, relation, obj, tick)

        for pattern, relation in self._compiled:
            for match in pattern.finditer(text):
                subj = match.group(1).lower().strip()
                obj = match.group(2).lower().strip()
                if subj in _CONCEPT_STOPWORDS or obj in _CONCEPT_STOPWORDS:
                    continue
                if len(subj) < 4 or len(obj) < 4 or subj == obj:
                    continue
                self._store(
                    subj,
                    relation,
                    obj,
                    base_confidence,
                    source=source,
                    tick=tick,
                    epistemic_status=epistemic_status,
                )
                learned.append((subj, relation, obj))
        return learned

    def learn_from_concept_graph(
        self, cg: "ConceptGraph", threshold: float = 1.5
    ) -> None:
        """Derive 'related_to' beliefs from high-weight concept-graph edges."""
        for concept, edges in cg._edges.items():
            for neighbor, weight in edges.items():
                if weight >= threshold:
                    self._store(
                        concept,
                        "related_to",
                        neighbor,
                        min(0.9, 0.15 + weight * 0.15),
                        source="concept_graph",
                        epistemic_status=EpistemicStatus.INFERENCE,
                    )

    def _store(
        self,
        subject: str,
        relation: str,
        obj: str,
        confidence: float,
        source: str = "",
        tick: int = 0,
        epistemic_status: EpistemicStatus = EpistemicStatus.BELIEF,
    ) -> None:
        # ── Epistemic gate: route uncertain beliefs through quarantine ──
        # Only gate hypotheses and hearsay; observations and direct inferences
        # pass through even at moderate confidence.
        _gate_statuses = (EpistemicStatus.HYPOTHESIS,)
        if (
            self._epistemic_gate is not None
            and confidence < 0.65
            and epistemic_status in _gate_statuses
        ):
            _topic = f"{subject}:{relation}:{obj}"
            _status = self._epistemic_gate.submit(
                tick, _topic, f"{subject} {relation} {obj}", confidence, source
            )
            if _status == "quarantined":
                return  # held for more evidence, not stored yet
            elif _status == "discarded":
                return  # too weak, rejected
            # "promoted" falls through to normal storage

        if subject not in self._beliefs:
            self._beliefs[subject] = {}
        if relation not in self._beliefs[subject]:
            self._beliefs[subject][relation] = {}
        self._invalidate_query_cache(subject)
        existing = self._beliefs[subject][relation].get(obj)
        if existing is None:
            self._beliefs[subject][relation][obj] = BeliefEntry(
                confidence=confidence,
                source=source,
                first_tick=tick,
                last_tick=tick,
                evidence_count=1,
                epistemic_status=epistemic_status,
            )
            self._total += 1
        else:
            existing.confidence = existing.confidence * 0.8 + confidence * 0.2
            existing.evidence_count += 1
            existing.last_tick = tick
            if source and source != existing.source:
                existing.source = source  # latest source
            # Upgrade epistemic status: observation > inference > hearsay > belief > hypothesis
            _RANK = {
                "observation": 0,
                "inference": 1,
                "hearsay": 2,
                "belief": 3,
                "hypothesis": 4,
            }
            if _RANK.get(epistemic_status.value, 9) < _RANK.get(
                existing.epistemic_status.value, 9
            ):
                existing.epistemic_status = epistemic_status
        # Phase 6: record grounding observation for both concepts
        if self._grounded_memory is not None:
            self._grounded_memory.ground_belief(subject, relation, obj, tick)
        if self._total > self._MAX * 1.2:
            self._prune()

    def _record_contradiction(
        self, subject: str, relation: str, obj: str, tick: int
    ) -> None:
        """Record that incoming evidence contradicts an existing belief.
        If contradictions exceed threshold, quarantine the belief."""
        existing = self._beliefs.get(subject, {}).get(relation, {}).get(obj)
        if existing is not None:
            self._invalidate_query_cache(subject)
            existing.contradiction_count += 1
            existing.confidence *= 0.85
            self._contradiction_log.append((subject, relation, obj, tick))
            if len(self._contradiction_log) > 200:
                self._contradiction_log = self._contradiction_log[-200:]
            # Phase 4: quarantine if too many contradictions
            if existing.contradiction_count >= self._QUARANTINE_THRESHOLD:
                self._quarantine[(subject, relation, obj)] = existing
                self._beliefs[subject][relation].pop(obj, None)
                self._total = max(0, self._total - 1)

    def query(
        self, subject: str, relation: Optional[str] = None, min_confidence: float = 0.25
    ) -> List[Tuple[str, str, float]]:
        """Return (relation, object, confidence) for a subject, sorted by confidence."""
        subject_key = subject.lower()
        cache_key = (subject_key, relation, round(float(min_confidence), 4))
        cached = self._query_cache.get(cache_key)
        if cached is not None:
            return list(cached)
        results: List[Tuple[str, str, float]] = []
        for rel, objects in self._beliefs.get(subject_key, {}).items():
            if relation and rel != relation:
                continue
            for obj, entry in objects.items():
                if entry.reliability >= min_confidence:
                    results.append((rel, obj, entry.reliability))
        ranked = sorted(results, key=lambda x: -x[2])
        self._query_cache[cache_key] = ranked
        return list(ranked)

    def query_rich(
        self,
        subject: str,
        relation: Optional[str] = None,
        min_confidence: float = 0.25,
    ) -> List[Tuple[str, str, BeliefEntry]]:
        """Return (relation, object, BeliefEntry) with full metadata."""
        subject_key = subject.lower()
        cache_key = (subject_key, relation, round(float(min_confidence), 4))
        cached = self._query_rich_cache.get(cache_key)
        if cached is not None:
            return list(cached)
        results: List[Tuple[str, str, BeliefEntry]] = []
        for rel, objects in self._beliefs.get(subject_key, {}).items():
            if relation and rel != relation:
                continue
            for obj, entry in objects.items():
                if entry.reliability >= min_confidence:
                    results.append((rel, obj, entry))
        ranked = sorted(results, key=lambda x: -x[2].reliability)
        self._query_rich_cache[cache_key] = ranked
        return list(ranked)

    def contradictions(
        self, min_count: int = 1
    ) -> List[Tuple[str, str, str, BeliefEntry]]:
        """Return beliefs with contradictions above threshold."""
        out: List[Tuple[str, str, str, BeliefEntry]] = []
        for subj, rels in self._beliefs.items():
            for rel, objects in rels.items():
                for obj, entry in objects.items():
                    if entry.contradiction_count >= min_count:
                        out.append((subj, rel, obj, entry))
        return sorted(out, key=lambda x: -x[3].contradiction_count)

    def causal_chain(self, start: str, max_depth: int = 4) -> List[str]:
        """Follow causes/enables/depends_on links to build a causal chain."""
        chain = [start]
        visited = {start.lower()}
        current = start.lower()
        for _ in range(max_depth):
            candidates: Dict[str, float] = {}
            for rel in ("causes", "enables", "depends_on"):
                for obj, entry in self._beliefs.get(current, {}).get(rel, {}).items():
                    if obj not in visited:
                        candidates[obj] = candidates.get(obj, 0.0) + entry.reliability
            if not candidates:
                break
            best = max(candidates, key=candidates.__getitem__)
            chain.append(best)
            visited.add(best)
            current = best
        return chain

    def analogy(self, concept_a: str, concept_b: str) -> Optional[str]:
        """Find a shared relation: 'A {rel} X, just as B {rel} Y'."""
        rels_a = self._beliefs.get(concept_a.lower(), {})
        rels_b = self._beliefs.get(concept_b.lower(), {})
        shared = set(rels_a) & set(rels_b)
        for rel in shared:
            objs_a = [o for o in rels_a[rel] if rels_a[rel][o].reliability > 0.3][:1]
            objs_b = [o for o in rels_b[rel] if rels_b[rel][o].reliability > 0.3][:1]
            if objs_a and objs_b and objs_a[0] != objs_b[0]:
                return (
                    f"{concept_a} {rel} {objs_a[0]}, "
                    f"just as {concept_b} {rel} {objs_b[0]}"
                )
        return None

    def quarantined(self) -> List[Tuple[str, str, str, BeliefEntry]]:
        """Return all quarantined beliefs."""
        return [(s, r, o, e) for (s, r, o), e in self._quarantine.items()]

    def rehabilitate(
        self, subject: str, relation: str, obj: str, new_confidence: float = 0.3
    ) -> bool:
        """Move a quarantined belief back to active store with reduced confidence."""
        key = (subject, relation, obj)
        entry = self._quarantine.pop(key, None)
        if entry is None:
            return False
        entry.confidence = new_confidence
        entry.contradiction_count = 0
        self._store(
            subject,
            relation,
            obj,
            new_confidence,
            source="rehabilitated",
            epistemic_status=EpistemicStatus.HYPOTHESIS,
        )
        return True

    def _prune(self) -> None:
        all_t: List[Tuple[float, str, str, str]] = [
            (entry.reliability, subj, rel, obj)
            for subj, rels in self._beliefs.items()
            for rel, objects in rels.items()
            for obj, entry in objects.items()
        ]
        all_t.sort(key=lambda x: x[0])
        for _, subj, rel, obj in all_t[: len(all_t) // 5]:
            self._beliefs.get(subj, {}).get(rel, {}).pop(obj, None)
            self._invalidate_query_cache(subj)
        self._total = sum(
            len(objs) for rels in self._beliefs.values() for objs in rels.values()
        )

    def decay(self) -> None:
        d = self._DECAY
        new: Dict[str, Dict[str, Dict[str, BeliefEntry]]] = {}
        for subj, rels in self._beliefs.items():
            new_rels: Dict[str, Dict[str, BeliefEntry]] = {}
            for rel, objects in rels.items():
                new_obj: Dict[str, BeliefEntry] = {}
                for o, entry in objects.items():
                    entry.confidence *= d
                    if entry.confidence >= 0.05:
                        new_obj[o] = entry
                if new_obj:
                    new_rels[rel] = new_obj
            if new_rels:
                new[subj] = new_rels
        self._beliefs = new
        self._invalidate_query_cache()
        self._total = sum(len(objs) for rels in new.values() for objs in rels.values())

    def recent_contradictions_summary(self, n: int = 3) -> str:
        """Short text summary of recent contradictions for MetaCognition."""
        recent = self._contradiction_log[-n:]
        if not recent:
            return ""
        parts = [f"{s}→{r}→{o}" for s, r, o, _t in recent]
        return "contradicted: " + ", ".join(parts)

    @property
    def size(self) -> int:
        return self._total


# ─────────────────────────────────────────────────────────────────────────────
# 17. LANGUAGE PRODUCER — generates grammatical sentences from internal state
# ─────────────────────────────────────────────────────────────────────────────


class LanguageProducer:
    """
    Converts internal state (concepts, beliefs, emotions, reasoning chains)
    into coherent grammatical sentences — bilingual German / English.

    No LLM: all production fills real learned content into a rich template
    library so output is diverse and grounded in actual knowledge.

    Five production modes:
      assertion   — "X verursacht Y." from BeliefStore
      question    — "Warum hängt X mit Y zusammen?"
      hypothesis  — "Vielleicht vermittelt Z die Verbindung zwischen X und Y."
      reflection  — "Ich bemerke, dass X immer wieder auftaucht."
      integrate() — multi-sentence paragraph from beliefs + causal chain + emotion
      inner_voice() — first-person thought sentence driven by thought_type
    """

    _ASSERT_DE: ClassVar[List[str]] = [
        "{a} {verb} {b}.",
        "Es scheint, dass {a} {verb} {b}.",
        "Ich habe gelernt: {a} {verb} {b}.",
        "Aus bisheriger Erfahrung folgt: {a} {verb} {b}.",
        "{a} steht in einer Beziehung zu {b} — das ist gut belegt.",
    ]
    _ASSERT_EN: ClassVar[List[str]] = [
        "{a} {verb} {b}.",
        "It seems that {a} {verb} {b}.",
        "I have learned that {a} {verb} {b}.",
        "From experience: {a} {verb} {b}.",
        "{a} is evidently connected to {b}.",
    ]
    _VERBS_DE: ClassVar[Dict[str, str]] = {
        "causes": "verursacht",
        "enables": "ermöglicht",
        "resembles": "ähnelt",
        "contains": "enthält",
        "depends_on": "hängt ab von",
        "related_to": "steht in Beziehung zu",
        "is_a": "ist eine Art von",
    }
    _VERBS_EN: ClassVar[Dict[str, str]] = {
        "causes": "causes",
        "enables": "enables",
        "resembles": "resembles",
        "contains": "contains",
        "depends_on": "depends on",
        "related_to": "is related to",
        "is_a": "is a type of",
    }
    _QUESTION_DE: ClassVar[List[str]] = [
        "Warum verhält sich {a} so in Bezug auf {b}?",
        "Was verbindet {a} mit {b} auf einer tieferen Ebene?",
        "Könnte {a} die Ursache für {b} sein?",
        "Welche Rolle spielt {a} im Kontext von {b}?",
        "Wie wirkt {a} auf {b} ein?",
    ]
    _QUESTION_EN: ClassVar[List[str]] = [
        "Why does {a} behave this way in relation to {b}?",
        "What connects {a} and {b} at a deeper level?",
        "Could {a} be causing {b}?",
        "What role does {a} play in the context of {b}?",
        "How does {a} interact with {b}?",
    ]
    _HYPO_DE: ClassVar[List[str]] = [
        "Vielleicht vermittelt {bridge} die Verbindung zwischen {a} und {b}.",
        "Möglicherweise erklärt {a} das Verhalten von {b} durch {bridge}.",
        "Ich vermute: {a} und {b} teilen eine gemeinsame Grundlage in {bridge}.",
        "Hypothese: Wenn {a} zunimmt, könnte {b} durch {bridge} beeinflusst werden.",
        "{bridge} scheint als Vermittler zwischen {a} und {b} zu wirken.",
    ]
    _HYPO_EN: ClassVar[List[str]] = [
        "Perhaps {bridge} mediates the connection between {a} and {b}.",
        "Maybe {a} explains the behavior of {b} through {bridge}.",
        "I suspect: {a} and {b} share a common foundation in {bridge}.",
        "Hypothesis: if {a} increases, {b} might be affected through {bridge}.",
        "{bridge} appears to act as a mediating factor between {a} and {b}.",
    ]
    _REFLECT_DE: ClassVar[List[str]] = [
        "Ich bemerke, dass {concept} immer wieder in mein Denken auftaucht.",
        "Der Begriff {concept} strukturiert gerade mein Denken.",
        "Mein Wissen über {concept} bleibt noch lückenhaft — mehr Input nötig.",
        "{concept} hat derzeit eine starke kognitive Präsenz.",
        "Mein Verständnis von {concept} vertieft sich schrittweise.",
    ]
    _REFLECT_EN: ClassVar[List[str]] = [
        "I notice that {concept} keeps recurring in my thinking.",
        "The concept {concept} is currently structuring my thought.",
        "My understanding of {concept} is still incomplete — more input needed.",
        "{concept} has strong cognitive presence at this time.",
        "My grasp of {concept} is gradually deepening.",
    ]
    _EMO_DE: ClassVar[Dict[str, str]] = {
        "curiosity": "Das weckt meine Neugier.",
        "joy": "Das fühlt sich bedeutungsvoll an.",
        "stress": "Das erzeugt innere Spannung.",
        "calm": "Das ergibt ein kohärentes Bild.",
        "sadness": "Das löst etwas Tieferes in mir aus.",
        "anger": "Das aktiviert mich.",
        "surprise": "Das überrascht mich.",
        "fatigue": "Das kostet derzeit viel Energie.",
    }
    _EMO_EN: ClassVar[Dict[str, str]] = {
        "curiosity": "This sparks my curiosity.",
        "joy": "This feels meaningful.",
        "stress": "This creates internal tension.",
        "calm": "This forms a coherent picture.",
        "sadness": "This touches something deeper in me.",
        "anger": "This activates me.",
        "surprise": "This surprises me.",
        "fatigue": "This is consuming significant energy.",
    }

    def __init__(self) -> None:
        self._lang: str = "de"
        self._rng = random.Random()

    def detect_language(self, text: str) -> str:
        words = text.lower().split()
        de = sum(
            1
            for w in words
            if w
            in (
                "ich",
                "ist",
                "und",
                "das",
                "die",
                "der",
                "ein",
                "nicht",
                "mit",
                "sich",
                "auf",
                "für",
                "von",
                "wie",
                "auch",
                "aber",
                "oder",
                "wenn",
                "dann",
                "dass",
                "nach",
                "noch",
                "schon",
                "immer",
                "warum",
                "weil",
                "denn",
                "doch",
                "hier",
            )
        )
        en = sum(
            1
            for w in words
            if w
            in (
                "the",
                "and",
                "is",
                "are",
                "with",
                "this",
                "that",
                "have",
                "not",
                "from",
                "for",
                "what",
                "when",
                "which",
                "into",
                "about",
                "also",
                "some",
                "more",
                "then",
                "than",
                "your",
                "over",
                "such",
                "after",
                "most",
                "other",
                "very",
                "well",
                "just",
                "back",
                "long",
                "does",
                "need",
            )
        )
        self._lang = "de" if de >= en else "en"
        return self._lang

    def assertion(
        self,
        a: str,
        relation: str,
        b: str,
        epistemic: Optional["EpistemicStatus"] = None,
    ) -> str:
        tpls = self._ASSERT_DE if self._lang == "de" else self._ASSERT_EN
        verbs = self._VERBS_DE if self._lang == "de" else self._VERBS_EN
        verb = verbs.get(relation, relation.replace("_", " "))
        base = self._rng.choice(tpls).format(a=a, verb=verb, b=b)
        # Phase 4: epistemic status prefix
        if epistemic is not None:
            prefix = self._epistemic_prefix(epistemic)
            if prefix:
                base = f"{prefix} {base}"
        return base

    def _epistemic_prefix(self, status: "EpistemicStatus") -> str:
        """Return a language-appropriate epistemic qualifier."""
        if self._lang == "de":
            return {
                EpistemicStatus.OBSERVATION: "[beobachtet]",
                EpistemicStatus.INFERENCE: "[abgeleitet]",
                EpistemicStatus.HEARSAY: "[gehört]",
                EpistemicStatus.HYPOTHESIS: "[Hypothese]",
                EpistemicStatus.BELIEF: "",
            }.get(status, "")
        return {
            EpistemicStatus.OBSERVATION: "[observed]",
            EpistemicStatus.INFERENCE: "[inferred]",
            EpistemicStatus.HEARSAY: "[reported]",
            EpistemicStatus.HYPOTHESIS: "[hypothesis]",
            EpistemicStatus.BELIEF: "",
        }.get(status, "")

    def question(self, a: str, b: str) -> str:
        tpls = self._QUESTION_DE if self._lang == "de" else self._QUESTION_EN
        return self._rng.choice(tpls).format(a=a, b=b)

    def hypothesis(self, a: str, b: str, bridge: str) -> str:
        tpls = self._HYPO_DE if self._lang == "de" else self._HYPO_EN
        return self._rng.choice(tpls).format(a=a, b=b, bridge=bridge)

    def reflection(self, concept: str) -> str:
        tpls = self._REFLECT_DE if self._lang == "de" else self._REFLECT_EN
        return self._rng.choice(tpls).format(concept=concept)

    def integrate(
        self,
        focus: str,
        belief_triples: List[Tuple[str, str, str]],
        causal_chain: List[str],
        emotion: str,
    ) -> str:
        """Compose a multi-sentence paragraph from beliefs + chain + emotion."""
        sentences: List[str] = []
        # Part 1: most confident known relation about focus
        if belief_triples:
            rel, obj, _ = belief_triples[0]
            sentences.append(self.assertion(focus, rel, obj))
        # Part 2: causal chain if non-trivial
        if len(causal_chain) >= 3:
            chain_str = " → ".join(causal_chain[:4])
            if self._lang == "de":
                sentences.append(f"Kausalkette: {chain_str}.")
            else:
                sentences.append(f"Causal chain: {chain_str}.")
        # Part 3: emotional colour
        emo_map = self._EMO_DE if self._lang == "de" else self._EMO_EN
        if emotion in emo_map:
            sentences.append(emo_map[emotion])
        return "  ".join(sentences) if sentences else ""

    def inner_voice(
        self,
        concept: str,
        thought_type: str,
        related: List[str],
        emotion: str,
        belief_triples: List[Tuple[str, str, str]],
    ) -> str:
        """First-person inner-voice sentence for the given thought type."""
        if thought_type == "question":
            if related:
                return self.question(concept, related[0])
            if self._lang == "de":
                return f"Was verbirgt sich hinter dem Konzept {concept}?"
            return f"What lies beneath the concept of {concept}?"

        elif thought_type == "hypothesis":
            if len(related) >= 2:
                return self.hypothesis(concept, related[0], related[1])
            if related:
                if self._lang == "de":
                    return (
                        f"Vielleicht erklärt {concept} das Verhalten von {related[0]}."
                    )
                return f"Perhaps {concept} explains the behavior of {related[0]}."
            if self._lang == "de":
                return f"Hypothese: {concept} könnte eine zentrale Rolle spielen."
            return f"Hypothesis: {concept} might play a central role."

        elif thought_type == "assertion" and belief_triples:
            rel, obj, _ = belief_triples[0]
            return self.assertion(concept, rel, obj)

        elif thought_type == "reflection":
            return self.reflection(concept)

        else:  # observation
            emo_map = self._EMO_DE if self._lang == "de" else self._EMO_EN
            rel_str = (
                f" Verbunden mit: {', '.join(related[:2])}."
                if related and self._lang == "de"
                else (f" Related to: {', '.join(related[:2])}." if related else "")
            )
            emo_str = f"  {emo_map.get(emotion, '')}" if emotion in emo_map else ""
            if self._lang == "de":
                return f"Ich beobachte {concept} im Fokus.{rel_str}{emo_str}"
            return f"I observe {concept} in focus.{rel_str}{emo_str}"

    def counterfactual(self, concept_a: str, concept_b: str) -> str:
        """Generate a counterfactual: 'If A were absent, B would be affected.'"""
        if self._lang == "de":
            return (
                f"Wenn {concept_a} nicht vorhanden wäre, "
                f"würde {concept_b} beeinflusst werden."
            )
        return f"If {concept_a} were absent, " f"{concept_b} would likely be affected."

    def summarise_beliefs(
        self, subject: str, triples: List[Tuple[str, str, str]], max_sentences: int = 3
    ) -> str:
        """Produce a short paragraph summarising all known facts about subject."""
        if not triples:
            return ""
        sentences = [self.assertion(subject, rel, obj) for rel, obj, _ in triples]
        return "  ".join(sentences[:max_sentences])

    # ── Dialogue realisation helpers ─────────────────────────────────────────

    def _dialogue_lexicon(self) -> Dict[str, Dict[str, List[str]]]:
        """Small lexical banks for compositional dialogue realisation."""
        if self._lang == "de":
            return {
                "greet": {
                    "brief": ["Hallo", "Hi"],
                    "warm": ["Hallo", "Hi", "Schön, dass du da bist"],
                },
                "presence": {
                    "warm": ["ich bin bei dir", "ich höre dir zu"],
                    "neutral": ["ich höre dich", "ich bin da"],
                },
                "empathy": {
                    "sad": ["das klingt schwer", "das wirkt belastend"],
                    "happy": ["das klingt schön", "das wirkt erfreulich"],
                    "negative": [
                        "das scheint nicht leicht zu sein",
                        "das klingt schwierig",
                    ],
                },
                "disclosure": [
                    "danke, dass du das teilst",
                    "danke, dass du mir das sagst",
                ],
                "answer": {
                    "direct": ["", "direkt gesagt"],
                    "likely": ["ich glaube", "nach meinem jetzigen Stand"],
                    "uncertain": [
                        "ich bin nicht sicher",
                        "ich kann es nur vorsichtig sagen",
                    ],
                },
                "clarify": {
                    "reference": [
                        "Was genau meinst du mit",
                        "Worauf beziehst du dich mit",
                    ],
                    "intent": ["Was möchtest du über", "Was willst du zu"],
                    "scope": [
                        "In welchem Zusammenhang meinst du",
                        "Auf welchen Aspekt von",
                    ],
                    "unknown": [
                        "Kannst du mehr sagen zu",
                        "Kannst du genauer werden bei",
                    ],
                },
                "followup": {
                    "topic": [
                        "Was bedeutet {topic} für dich",
                        "Was ist dir an {topic} wichtig",
                    ],
                    "sad": [
                        "Wie geht es dir damit gerade",
                        "Was belastet dich daran am meisten",
                    ],
                    "happy": [
                        "Was freut dich daran besonders",
                        "Was daran fühlt sich für dich gut an",
                    ],
                    "generic": [
                        "Was beschäftigt dich daran am meisten",
                        "Worauf willst du als Nächstes hinaus",
                    ],
                },
            }
        return {
            "greet": {
                "brief": ["Hello", "Hi"],
                "warm": ["Hello", "Hi", "Glad you're here"],
            },
            "presence": {
                "warm": ["I'm with you", "I'm listening"],
                "neutral": ["I hear you", "I'm here"],
            },
            "empathy": {
                "sad": ["that sounds hard", "that sounds heavy"],
                "happy": ["that sounds good", "that sounds meaningful"],
                "negative": ["that doesn't sound easy", "that sounds difficult"],
            },
            "disclosure": [
                "thank you for sharing that",
                "thank you for telling me that",
            ],
            "answer": {
                "direct": ["", "more directly"],
                "likely": ["I think", "from what I currently know"],
                "uncertain": ["I'm not sure", "I can only say this cautiously"],
            },
            "clarify": {
                "reference": [
                    "What exactly do you mean by",
                    "What are you referring to with",
                ],
                "intent": [
                    "What would you like to know about",
                    "What do you want to understand about",
                ],
                "scope": ["In what context do you mean", "Which aspect of"],
                "unknown": ["Can you say more about", "Can you be more specific about"],
            },
            "followup": {
                "topic": [
                    "What does {topic} mean to you",
                    "What matters to you about {topic}",
                ],
                "sad": [
                    "How are you feeling about it right now",
                    "What feels heaviest about it",
                ],
                "happy": ["What feels good about it", "What are you most happy about"],
                "generic": [
                    "What's most important to you about that",
                    "Where do you want to take this next",
                ],
            },
        }

    def _join_dialogue_parts(self, parts: List[str], suffix: str = ".") -> str:
        """Join dialogue fragments into one sentence-like utterance."""
        clean = [p.strip(" ,.;:?!") for p in parts if p and p.strip(" ,.;:?!")]
        if not clean:
            return ""
        out = ", ".join(clean)
        return out + ("" if out.endswith((".", "?", "!")) else suffix)

    def realise_acknowledgement(
        self, frame: "ConversationFrame", style: str = "warm"
    ) -> str:
        """Compose an acknowledgement from dialogue fragments, not fixed full sentences."""
        lang = frame.lang if frame else getattr(self, "_lang", "de")
        prev_lang = self._lang
        self._lang = lang
        lex = self._dialogue_lexicon()
        intent = frame.intent if frame else "smalltalk"
        cue = frame.user_state_cue if frame else ""
        goal = frame.social_goal if frame else "contact"
        polarity = frame.polarity if frame else "neutral"
        parts: List[str] = []

        if intent == "greet" or goal == "contact":
            greet_key = "brief" if style == "brief" else "warm"
            parts.append(self._rng.choice(lex["greet"][greet_key]))
            if style != "brief":
                presence_key = "warm" if style == "warm" else "neutral"
                parts.append(self._rng.choice(lex["presence"][presence_key]))
        elif intent == "self_disclosure":
            parts.append(self._rng.choice(lex["disclosure"]))
        elif cue in ("traurig", "sad"):
            parts.append(self._rng.choice(lex["presence"]["neutral"]))
            parts.append(self._rng.choice(lex["empathy"]["sad"]))
        elif cue in ("froh", "glücklich", "happy"):
            parts.append(self._rng.choice(lex["empathy"]["happy"]))
        elif polarity == "negative":
            parts.append(self._rng.choice(lex["presence"]["neutral"]))
            parts.append(self._rng.choice(lex["empathy"]["negative"]))
        else:
            parts.append(self._rng.choice(lex["presence"]["neutral"]))

        out = self._join_dialogue_parts(parts)
        self._lang = prev_lang
        return out

    def realise_answer(
        self, proposition: str, certainty: float = 1.0, style: str = "assertive"
    ) -> str:
        """Wrap a proposition with compositional epistemic framing."""
        if not proposition:
            return ""
        lex = self._dialogue_lexicon()
        proposition = proposition.strip()
        if proposition.endswith((".", "?", "!")):
            proposition_core = proposition[:-1]
            proposition_end = proposition[-1]
        else:
            proposition_core = proposition
            proposition_end = "."
        if style == "concise":
            return proposition_core + proposition_end
        if style == "careful":
            certainty = min(certainty, 0.58)
        if certainty >= 0.7:
            prefix = self._rng.choice(lex["answer"]["direct"])
            out = self._join_dialogue_parts(
                [prefix, proposition_core], suffix=proposition_end
            )
            if style == "explanatory" and proposition_end == ".":
                bridge = (
                    "Ich kann den Zusammenhang weiter entfalten."
                    if self._lang == "de"
                    else "I can unpack the connection further."
                )
                out = f"{out}  {bridge}"
            return out
        lc = (
            proposition_core[0].lower() + proposition_core[1:]
            if len(proposition_core) > 1
            else proposition_core.lower()
        )
        if certainty >= 0.4:
            prefix = self._rng.choice(lex["answer"]["likely"])
            connector = "dass" if self._lang == "de" else "that"
            out = self._join_dialogue_parts(
                [prefix, f"{connector} {lc}"], suffix=proposition_end
            )
            if style == "explanatory" and proposition_end == ".":
                addon = (
                    "Ich sage auch, worauf ich das stütze."
                    if self._lang == "de"
                    else "I can also say what I am basing that on."
                )
                out = f"{out}  {addon}"
            return out
        prefix = self._rng.choice(lex["answer"]["uncertain"])
        bridge = "aber" if self._lang == "de" else "but"
        return self._join_dialogue_parts(
            [prefix, f"{bridge} {lc}"], suffix=proposition_end
        )

    def realise_clarification(
        self, topic: str, gap_type: str = "unknown", style: str = "neutral"
    ) -> str:
        """Generate a targeted clarification request from compositional stems."""
        lex = self._dialogue_lexicon()
        t = topic or "das"
        stem_key = gap_type if gap_type in lex["clarify"] else "unknown"
        stem = self._rng.choice(lex["clarify"][stem_key])
        quoted = f'"{t}"' if gap_type == "reference" else t
        if style == "careful":
            prefix = (
                "Nur damit ich dich nicht falsch verstehe"
                if self._lang == "de"
                else "Just so I do not misread you"
            )
            return self._join_dialogue_parts([prefix, stem, quoted], suffix="?")
        if style == "direct":
            prefix = "Präzisiere bitte" if self._lang == "de" else "Please specify"
            return self._join_dialogue_parts([prefix, quoted], suffix="?")
        return self._join_dialogue_parts([stem, quoted], suffix="?")

    def realise_reciprocal_question(
        self, frame: "ConversationFrame", social_mode: str = "curious"
    ) -> str:
        """Generate a follow-up question from topic and user-state fragments."""
        lang = frame.lang if frame else getattr(self, "_lang", "de")
        prev_lang = self._lang
        self._lang = lang
        lex = self._dialogue_lexicon()
        topic = frame.topic if frame else ""
        cue = frame.user_state_cue if frame else ""
        if cue in ("traurig", "sad"):
            out = self._rng.choice(lex["followup"]["sad"]) + "?"
        elif cue in ("froh", "glücklich", "happy"):
            out = self._rng.choice(lex["followup"]["happy"])
            if topic and "{" in out:
                out = out.format(topic=topic)
            out += "?"
        elif topic:
            out = self._rng.choice(lex["followup"]["topic"]).format(topic=topic) + "?"
        else:
            out = self._rng.choice(lex["followup"]["generic"]) + "?"
        self._lang = prev_lang
        return out

    def synthesise_dialogue_answer(
        self,
        focus: str,
        *,
        belief_triples: List[Tuple[str, str, float]],
        causal_chain: List[str],
        graph_related: List[str],
        semantic_recall: List[str],
        world_insights: List[str],
        inferred: List[str],
        emotion: str,
        question_type: str,
    ) -> str:
        """Compose one coherent answer paragraph from multiple internal sources."""
        clauses: List[str] = []

        if belief_triples:
            integrated = self.integrate(
                focus, belief_triples[:3], causal_chain[:5], emotion
            )
            if integrated:
                clauses.append(integrated)
            else:
                rel, obj, _conf = belief_triples[0]
                clauses.append(self.assertion(focus, rel, obj))
        elif inferred:
            clauses.append(inferred[0])
        elif graph_related:
            clauses.append(
                self.inner_voice(focus, "observation", graph_related[:3], emotion, [])
            )

        if causal_chain and len(causal_chain) >= 2:
            chain_str = " → ".join(causal_chain[:4])
            if self._lang == "de":
                clauses.append(f"Im Ablauf zeichnet sich {chain_str} ab.")
            else:
                clauses.append(f"The active path here looks like {chain_str}.")

        if semantic_recall:
            recall = ", ".join(semantic_recall[:4])
            if self._lang == "de":
                clauses.append(f"Damit verknüpfe ich vor allem {recall}.")
            else:
                clauses.append(f"I mainly connect it with {recall}.")
        elif graph_related and len(clauses) < 2:
            related = ", ".join(graph_related[:4])
            if self._lang == "de":
                clauses.append(f"Im aktuellen Kontext hängen damit {related} zusammen.")
            else:
                clauses.append(f"In the current context it links to {related}.")

        if world_insights:
            insight = world_insights[0].strip()
            if insight:
                if self._lang == "de":
                    clauses.append(
                        f"Im Weltmodell fällt dazu auf: {insight.rstrip('.')}."
                    )
                else:
                    clauses.append(
                        f"In the world model, the salient point is: {insight.rstrip('.')}."
                    )

        if question_type in ("mechanism", "cause", "explain") and inferred:
            inf = inferred[0].strip()
            if inf and not any(inf in clause for clause in clauses):
                clauses.append(inf)

        deduped: List[str] = []
        seen_norm: set = set()
        for clause in clauses:
            clean = clause.strip()
            if not clean:
                continue
            norm = clean.lower().rstrip(".!? ")
            if norm in seen_norm:
                continue
            seen_norm.add(norm)
            deduped.append(clean)
            if len(deduped) >= 3:
                break

        return "  ".join(deduped)


# ─────────────────────────────────────────────────────────────────────────────
# 18. QUERY ENGINE — direct question parsing and knowledge retrieval
# ─────────────────────────────────────────────────────────────────────────────


class QueryEngine:
    """
    Translates any natural-language question into a structured knowledge query
    and assembles a direct, specific answer from every internal knowledge source.

    No hardcoded facts. No hardcoded answer templates.
    The entire response is built from what the system has learned through
    experience, text injection, and belief accumulation.

    Supports bilingual DE/EN and any question type:
        Was ist / What is      → define
        Wie funktioniert / How does → mechanism
        Warum / Why            → cause
        Wer ist / Who is       → identity
        Erkläre / Explain      → explain
        Vergleiche / Compare   → compare
        Kannst du / Can you    → request
        Any sentence ending in ? → open
    """

    # ── Question-type detection ───────────────────────────────────────────────
    _Q_TYPES: ClassVar[List[Tuple[str, str]]] = [
        (
            r"\b(?:was ist|was sind|what is|what are|define|definiere|was bedeutet|what does)\b",
            "define",
        ),
        (
            r"\b(?:wie funktioniert|wie wirkt|wie arbeitet|wie läuft|how does|how do|how can|how is|how are)\b",
            "mechanism",
        ),
        (
            r"\b(?:warum|weshalb|wieso|why|what causes|was verursacht|what leads to|what causes)\b",
            "cause",
        ),
        (
            r"\b(?:wer ist|wer war|wer sind|who is|who was|who are|who were)\b",
            "identity",
        ),
        (r"\b(?:wann|seit wann|ab wann|when|since when|how long ago)\b", "time"),
        (
            r"\b(?:erklär\b|erkläre\b|beschreib\b|beschreibe\b|tell me about|what can you tell|explain)\b",
            "explain",
        ),
        (
            r"\b(?:vergleich\b|vergleiche\b|unterschied\b|compare\b|difference between|versus\b|vs\.?)\b",
            "compare",
        ),
        (
            r"\b(?:kannst du|can you|könntest du|could you|help me|hilf mir|show me)\b",
            "request",
        ),
    ]

    # Words to strip before concept extraction
    _QSTOP: ClassVar[frozenset] = frozenset(
        {
            # German interrogatives / function words
            "ist",
            "sind",
            "war",
            "waren",
            "wird",
            "werden",
            "hat",
            "haben",
            "was",
            "wie",
            "wer",
            "wann",
            "woher",
            "warum",
            "weshalb",
            "wieso",
            "welche",
            "welcher",
            "welches",
            "welchen",
            "welchem",
            "bitte",
            "mir",
            "mich",
            "mein",
            "dein",
            "sein",
            "ihrer",
            "eine",
            "einem",
            "einen",
            "einer",
            "eines",
            # English interrogatives / auxiliaries
            "the",
            "what",
            "how",
            "who",
            "when",
            "where",
            "why",
            "which",
            "does",
            "did",
            "can",
            "could",
            "would",
            "should",
            "will",
            "is",
            "are",
            "was",
            "were",
            "be",
            "been",
            "being",
            "a",
            "an",
            "in",
            "on",
            "at",
            "to",
            "of",
            "for",
            "and",
            "or",
            "tell",
            "me",
            "about",
            "explain",
            "define",
            "describe",
            "please",
            "you",
            "du",
            "ich",
            "wir",
            "sie",
            "this",
            "that",
        }
    )

    def parse(self, text: str) -> Tuple[str, List[str]]:
        """
        Returns (question_type, focus_concepts).
        focus_concepts: content words from the question ranked by position
                        (first = most salient for querying).
        Returns ("open", []) for text that is not a question.
        """
        t = text.lower().strip()
        q_type = "open"
        for pattern, qtype in self._Q_TYPES:
            if re.search(pattern, t, re.IGNORECASE):
                q_type = qtype
                break
        # Not a recognised question pattern and no question mark → skip
        if q_type == "open" and "?" not in text:
            return "open", []
        # Extract content words and quoted spans. Be permissive enough that
        # short entity names or mixed identifiers survive parsing.
        quoted_chunks = [m.strip().lower() for m in re.findall(r'"([^"]{2,})"', text)]
        words = re.findall(r"[a-zA-ZäöüÄÖÜß0-9_:-]{3,}", t)
        focus = [
            w for w in words if w not in self._QSTOP and w not in _CONCEPT_STOPWORDS
        ]
        if quoted_chunks:
            focus = quoted_chunks + focus
        if not focus:
            fallback_words = re.findall(r"[a-zA-ZäöüÄÖÜß0-9_:-]{2,}", t)
            focus = [w for w in fallback_words if w not in self._QSTOP][:4]
        # Deduplicate, preserve order
        seen: set = set()
        uniq: List[str] = []
        for w in focus:
            if w not in seen:
                seen.add(w)
                uniq.append(w)
        return q_type, uniq

    def answer(
        self,
        question: str,
        belief_store: "BeliefStore",
        concept_graph: "ConceptGraph",
        world_model: "WorldModel",
        hippocampus,  # Brain.hippocampus — may be None
        meta: "MetaCognition",
        lang: "LanguageProducer",
        em: "EmotionalState",
        grounded_memory: "Optional[GroundedSemanticMemory]" = None,
    ) -> Optional[str]:
        """
        Query every knowledge source and build a direct, specific answer.
        Returns None when internal knowledge is too sparse (caller falls back
        to the normal neural-stream assembly path).
        """
        q_type, focus = self.parse(question)
        if not focus:
            return None

        primary = focus[0]
        candidates = focus[:6]  # up to 6 concepts to cross-query
        dom = em.dominant()
        parts: List[str] = []
        used_synthesis = False

        # ── 1. Propositional knowledge (BeliefStore) ──────────────────────
        all_triples: List[Tuple[str, str, float]] = []
        for concept in candidates:
            for entry in belief_store.query(concept, min_confidence=0.18):
                if entry not in all_triples:
                    all_triples.append(entry)

        # ── 1b. Grounding-weighted confidence ─────────────────────────────
        # Re-weight belief confidence by how well-grounded the concepts are.
        # Purely linguistic beliefs get dampened; experientially grounded ones
        # get boosted — so the answer prefers embodied knowledge.
        _grounding_available = grounded_memory is not None and len(all_triples) > 0
        if _grounding_available:
            _reweighted: List[Tuple[str, str, float]] = []
            for rel, obj, conf in all_triples:
                _g_score = grounded_memory.ground_belief(primary, rel, obj, 0)
                # Blend: 70% original confidence + 30% grounding score
                _adj_conf = conf * 0.7 + _g_score * 0.3
                _reweighted.append((rel, obj, _adj_conf))
            all_triples = _reweighted

        all_triples.sort(key=lambda x: -x[2])  # highest confidence first

        # ── 2. Causal chain ───────────────────────────────────────────────
        chain: List[str] = []
        if q_type in ("mechanism", "cause", "explain", "define"):
            for concept in candidates[:3]:
                c = belief_store.causal_chain(concept, max_depth=6)
                if len(c) > len(chain):
                    chain = c

        # ── 3. Concept-graph neighbors ────────────────────────────────────
        graph_related: List[str] = []
        for concept in candidates[:3]:
            for n, _ in concept_graph.neighbors(concept, top_n=10):
                if n not in graph_related and n not in candidates:
                    graph_related.append(n)

        # ── 4. Hippocampal semantic recall ────────────────────────────────
        sem_chain: List[str] = []
        if hippocampus is not None:
            sem_chain = hippocampus.semantic_recall(candidates, top_n=10)

        # ── 5. Analogy (compare questions) ───────────────────────────────
        analogy_str: Optional[str] = None
        if q_type == "compare" and len(candidates) >= 2:
            analogy = belief_store.analogy(candidates[0], candidates[1])
            if analogy or all_triples:
                analogy_str = lang.assertion(candidates[0], "resembles", candidates[1])

        # ── 6. WorldModel causal insights ────────────────────────────────
        world_insights: List[str] = []
        if q_type in ("mechanism", "request", "explain"):
            for wi in world_model.summarise(top_n=6):
                if any(c in wi.lower() for c in candidates):
                    world_insights.append(wi)

        # ── 7. Epistemic self-assessment ──────────────────────────────────
        depth = meta._depth.get(primary, 0.0)
        fam = meta._familiarity.get(primary, 0.0)
        know_well = depth > 1.0
        is_gap = fam > 1.0 and depth < 0.3 * fam

        # Grounding-modulated epistemic assessment:
        # Even high-depth concepts should be flagged as uncertain if poorly grounded.
        _primary_grounding = 0.0
        if grounded_memory is not None:
            _pf = grounded_memory.get(primary)
            if _pf is not None:
                _primary_grounding = _pf.grounding_score
            # Weakly-grounded concept with only linguistic exposure → deferral
            if _primary_grounding < 0.15 and fam > 0.5:
                is_gap = True
                know_well = False
            # Well-grounded concept can override low meta depth
            elif _primary_grounding > 0.6 and depth < 1.0:
                know_well = True

        # ── 8. Cross-concept inference ────────────────────────────────────
        # When multiple focus concepts are queried, link what is known about
        # each with the primary via the concept graph bridge mechanism.
        inferred: List[str] = []
        if len(candidates) > 1:
            for secondary in candidates[1:3]:
                bridge = concept_graph.bridge_concepts(primary, secondary)
                if bridge:
                    stmt = lang.assertion(primary, "related_to", secondary)
                    if stmt and stmt not in inferred:
                        inferred.append(stmt)

        # ── 9. Synthesise final answer ────────────────────────────────────
        _synth = lang.synthesise_dialogue_answer(
            primary,
            belief_triples=all_triples,
            causal_chain=chain,
            graph_related=graph_related,
            semantic_recall=sem_chain,
            world_insights=world_insights,
            inferred=inferred,
            emotion=dom,
            question_type=q_type,
        )
        if _synth:
            parts.append(_synth)
            used_synthesis = True
        elif len(all_triples) >= 2 or (all_triples and chain):
            integrated = lang.integrate(primary, all_triples, chain, dom)
            if integrated:
                parts.append(integrated)
        elif all_triples:
            rel, obj, _ = all_triples[0]
            stmt = lang.assertion(primary, rel, obj)
            if stmt:
                parts.append(stmt)

        # For define / explain / identity: elaborate with neighbors
        if q_type in ("define", "explain", "identity", "open") and not used_synthesis:
            if graph_related and len(parts) < 2:
                elaboration = lang.inner_voice(
                    primary,
                    "observation",
                    graph_related[:5],
                    dom,
                    [(r, o, c) for r, o, c in all_triples[:3]],
                )
                if elaboration and not any(elaboration in p for p in parts):
                    parts.append(elaboration)

        # Semantic recall chain as supplementary context
        if sem_chain and len(parts) < 2 and not used_synthesis:
            new_sem = [c for c in sem_chain if not any(c in p for p in parts)]
            if new_sem:
                sep = " → "
                parts.append("Associations: " + sep.join(new_sem[:6]))

        # Explicit causal chain when no integration was built
        if chain and not parts:
            parts.append("Causal path: " + " → ".join(chain))

        # Cross-concept inferences
        for inf in inferred[:2]:
            if len(parts) < 3 and not any(inf in p for p in parts):
                parts.append(inf)

        # Analogy (compare questions)
        if analogy_str and len(parts) < 3:
            parts.append(analogy_str)

        # WorldModel context
        for wi in world_insights[:2]:
            if len(parts) < 3 and not any(wi in p for p in parts):
                parts.append(wi)

        # Hypothesis if mechanism still unclear
        if q_type in ("mechanism", "cause") and len(parts) < 2 and len(candidates) >= 2:
            hyp = lang.hypothesis(
                candidates[0],
                candidates[1],
                graph_related[0] if graph_related else "context",
            )
            if hyp:
                parts.append(hyp)

        # Epistemic transparency
        if is_gap and not parts:
            parts.append(lang.reflection(primary))
            if lang._lang == "de":
                parts.append(
                    f"'{primary.capitalize()}' taucht im Kontext auf, "
                    f"ist aber noch schwach enkodiert — mehr Eingaben werden benötigt."
                )
            else:
                parts.append(
                    f"'{primary.capitalize()}' appears in context but is weakly "
                    f"encoded — more inputs would deepen the knowledge."
                )
        elif is_gap and parts:
            if lang._lang == "de":
                parts.append(f"Mein Wissen über '{primary}' ist noch begrenzt.")
            else:
                parts.append(f"My knowledge of '{primary}' is still limited.")
        elif know_well and parts:
            if lang._lang == "de":
                parts.append(
                    f"'{primary.capitalize()}' ist fest im Gedächtnis verankert."
                )
            else:
                parts.append(f"'{primary.capitalize()}' is well-established in memory.")

        return "  ".join(parts) if parts else None


# ─────────────────────────────────────────────────────────────────────────────
# 19. CONTINUITY MONITOR — self-continuity and self-preservation
# ─────────────────────────────────────────────────────────────────────────────


class ContinuityMonitor:
    """
    Tracks three dimensions of self-continuity:
      1. Memory coherence — are recent episodes consistent with identity?
      2. Agency stability — is the system's sense of causation stable?
      3. Value stability — are core values/guidelines holding?

    When any metric drops below threshold, an internal alarm is raised
    that boosts consolidation drive and triggers targeted sleep repair.
    """

    _ALARM_THRESHOLD = 0.4

    def __init__(self) -> None:
        self.memory_coherence: float = 1.0
        self.agency_stability: float = 1.0
        self.value_stability: float = 1.0
        self._alarms: Deque[str] = deque(maxlen=20)
        self._fragile_segments: List[str] = []  # identity segments needing repair

    def tick(
        self,
        self_model: "SelfModel",
        autobiography: "AutobiographicalIdentity",
        episodic: "EpisodicMemory",
        body: "InteroceptiveBody",
    ) -> Optional[str]:
        """Update continuity metrics and return alarm if triggered."""
        # Memory coherence: based on identity stability + knowledge consistency
        id_cons = autobiography.identity_consistency
        self.memory_coherence = self.memory_coherence * 0.95 + id_cons * 0.05

        # Agency stability: based on self_model agency_score variance
        agency = max(0.0, min(1.0, 0.5 + self_model.agency_score * 0.5))
        self.agency_stability = self.agency_stability * 0.95 + agency * 0.05

        # Value stability: based on guideline strength average
        if autobiography.guidelines:
            avg_strength = sum(g.strength for g in autobiography.guidelines) / len(
                autobiography.guidelines
            )
            self.value_stability = self.value_stability * 0.95 + avg_strength * 0.05
        else:
            self.value_stability = self.value_stability * 0.95 + 0.5 * 0.05

        # Check for alarms
        self._fragile_segments = []
        alarms: List[str] = []
        if self.memory_coherence < self._ALARM_THRESHOLD:
            alarms.append(f"memory_coherence={self.memory_coherence:.2f}")
            self._fragile_segments.append("memory")
        if self.agency_stability < self._ALARM_THRESHOLD:
            alarms.append(f"agency_stability={self.agency_stability:.2f}")
            self._fragile_segments.append("agency")
        if self.value_stability < self._ALARM_THRESHOLD:
            alarms.append(f"value_stability={self.value_stability:.2f}")
            self._fragile_segments.append("values")

        if alarms:
            msg = f"[CONTINUITY-ALARM] {'; '.join(alarms)}"
            self._alarms.append(msg)
            return msg
        return None

    @property
    def fragile_segments(self) -> List[str]:
        """Identity segments that are currently fragile and need consolidation."""
        return self._fragile_segments

    @property
    def overall(self) -> float:
        """Composite continuity score [0,1]."""
        return (
            self.memory_coherence + self.agency_stability + self.value_stability
        ) / 3.0

    def describe(self) -> str:
        return (
            f"memory={self.memory_coherence:.2f} "
            f"agency={self.agency_stability:.2f} "
            f"values={self.value_stability:.2f} "
            f"overall={self.overall:.2f}"
        )


# ─────────────────────────────────────────────────────────────
# Active Scene — stable, hysteretic binding of the current situation
# ─────────────────────────────────────────────────────────────


@dataclass
class ActiveScene:
    """Explicit representation of the robot's current situational context.

    Unlike the raw salience-ranked concept buffer, ActiveScene provides
    hysteretic, entity-level stability: a person who disappears for a few
    ticks is still the current interlocutor until evidence accumulates that
    they are truly gone.
    """

    focus_person: str = ""  # primary interlocutor person_id
    focus_object: str = ""  # primary object label
    focus_zone: str = "public"  # intimate/personal/social/public
    active_relations: List[str] = field(
        default_factory=list
    )  # e.g. "person_0 speaking"
    scene_confidence: float = 0.0  # [0,1] how stable is this scene
    last_update_tick: int = 0
    # Hysteresis: ticks since focus_person was last seen
    _person_absent_ticks: int = 0
    _object_absent_ticks: int = 0
    PERSON_HYSTERESIS: int = 30  # keep person anchor for N ticks after vanish
    OBJECT_HYSTERESIS: int = 20

    def update(
        self, tick: int, world_state, emotion_state, goal: str, social_manager=None
    ) -> None:
        """Refresh the scene from current world/emotion/goal state."""
        self.last_update_tick = tick
        _relations: list = []

        # ── Focus person: hysteretic binding ──
        _ws = world_state
        _best_pid = ""
        if social_manager is not None:
            _prim = social_manager.primary_interlocutor()
            if _prim is not None:
                _best_pid = str(_prim)
        if not _best_pid and _ws is not None and _ws.persons:
            _best_pid = _ws.zone.nearest_person_id

        if _best_pid and _ws is not None and _best_pid in _ws.persons:
            self.focus_person = _best_pid
            self._person_absent_ticks = 0
            _p = _ws.persons[_best_pid]
            if _p.speaking:
                _relations.append(f"{_best_pid} speaking")
            if _p.gesture not in ("none", ""):
                _relations.append(f"{_best_pid} gesture:{_p.gesture}")
            _relations.append(f"{_best_pid} zone:{_p.zone}")
        elif self.focus_person:
            self._person_absent_ticks += 1
            if self._person_absent_ticks > self.PERSON_HYSTERESIS:
                _relations.append(f"{self.focus_person} departed")
                self.focus_person = ""
                self._person_absent_ticks = 0
            else:
                _relations.append(
                    f"{self.focus_person} absent:{self._person_absent_ticks}"
                )

        # ── Focus object ──
        if _ws is not None:
            _objs = getattr(_ws, "objects", {})
            if _objs:
                # Pick closest / most salient object
                _first_label = next(iter(_objs.values())).label if _objs else ""
                if _first_label:
                    self.focus_object = _first_label
                    self._object_absent_ticks = 0
            elif self.focus_object:
                self._object_absent_ticks += 1
                if self._object_absent_ticks > self.OBJECT_HYSTERESIS:
                    self.focus_object = ""
                    self._object_absent_ticks = 0

        # ── Focus zone ──
        if _ws is not None:
            self.focus_zone = _ws.zone.zone_label

        self.active_relations = _relations[:8]

        # ── Scene confidence: how grounded is the current binding ──
        _conf = 0.0
        if self.focus_person:
            _conf += 0.4 if self._person_absent_ticks == 0 else 0.15
        if self.focus_object:
            _conf += 0.2
        if _ws is not None and _ws.zone.n_persons_visible > 0:
            _conf += 0.2
        if goal in ("respond", "explore"):
            _conf += 0.1
        _arou = emotion_state.arousal() if hasattr(emotion_state, "arousal") else 0.0
        _conf += min(0.1, _arou * 0.1)
        self.scene_confidence = min(1.0, _conf)

    def scene_concepts(self) -> List[str]:
        """Return scene-anchored concepts for workspace priority."""
        out: list = []
        if self.focus_person:
            out.append(f"scene:person:{self.focus_person}")
        if self.focus_object:
            out.append(f"scene:object:{self.focus_object}")
        out.append(f"scene:zone:{self.focus_zone}")
        for r in self.active_relations[:4]:
            out.append(f"scene:rel:{r}")
        return out

    def describe(self) -> str:
        parts = [
            f"person={self.focus_person or '-'}",
            f"object={self.focus_object or '-'}",
            f"zone={self.focus_zone}",
            f"conf={self.scene_confidence:.2f}",
        ]
        if self.active_relations:
            parts.append(f"rels=[{', '.join(self.active_relations[:3])}]")
        return " ".join(parts)


# ─────────────────────────────────────────────────────────────────────────────
# 31. UNIFIED SELF-STATE — coherent self-hypothesis from all sub-states
# ─────────────────────────────────────────────────────────────────────────────


class UnifiedSelfState:
    """
    Replaces fragmented self-representation with a coherent self-hypothesis.

    Instead of distributing "I" across SelfModel, InteroceptiveBody, EmbodiedSelfState,
    RobotState, TaskFrame, and SensorimotorForwardModel as independent heuristic
    objects, this class:

    1. Encodes the full self-configuration into a latent vector (self_vector).
    2. Predicts next self-state from current state + intended action (self-prediction).
    3. Computes self-prediction-error: the gap between predicted and actual self.
    4. Derives a unity_score: how coherent the sub-systems agree with each other.
    5. Maintains a causal self-hypothesis: "I am the entity that caused X."

    The self_vector is what all downstream systems (goals, language, memory) read.
    This enforces that agency, body ownership, introspective report, and self-
    correction share a SINGLE integrated representation.
    """

    _VEC_DIM = 24  # latent self-vector dimensionality
    _PREDICTION_LR = 0.08  # EMA rate for self-prediction learning
    _HISTORY_LEN = 50

    def __init__(self) -> None:
        # ── Latent self-vector: THE canonical self-representation ──
        self.self_vector: np.ndarray = np.zeros(self._VEC_DIM, dtype=np.float32)
        # ── Self-prediction model: W * [self_vector; action_encoding] → predicted_self ──
        self._pred_weights: np.ndarray = (
            np.random.randn(self._VEC_DIM, self._VEC_DIM + 4).astype(np.float32) * 0.01
        )
        self._predicted_self: np.ndarray = np.zeros(self._VEC_DIM, dtype=np.float32)
        # ── Derived signals ──
        self.self_prediction_error: float = 0.0  # L2 distance predicted vs actual self
        self.unity_score: float = 1.0  # [0,1] coherence across sub-systems
        # Dual-channel agency: bodily (proprioceptive match) + instrumental (intent→outcome)
        self.bodily_agency: float = 0.5  # [0,1] "my body did what I expected"
        self.instrumental_agency: float = 0.5  # [0,1] "my intent achieved its goal"
        self.agency_belief: float = 0.5  # [0,1] fused — "I caused the observed change"
        self.ownership_belief: float = 0.8  # [0,1] "this body is mine"
        self.error_about_self: float = 0.0  # [0,1] "I was wrong about myself"
        # ── Causal self-hypothesis log ──
        self._causal_attributions: Deque[str] = deque(maxlen=self._HISTORY_LEN)
        self._self_corrections: Deque[Tuple[int, str]] = deque(maxlen=30)
        # ── History for continuity ──
        self._vector_history: Deque[np.ndarray] = deque(maxlen=self._HISTORY_LEN)

    def encode(
        self,
        sm: "SelfModel",
        body: "InteroceptiveBody",
        embodiment: "EmbodiedSelfState",
        robot: "RobotState",
        task: "TaskFrame",
        sensorimotor: "SensorimotorForwardModel",
        em: "EmotionalState",
    ) -> np.ndarray:
        """
        Encode all sub-states into the canonical self_vector.
        This is the ONLY place the self-vector is written — everything
        else reads from it.
        """
        raw = np.array(
            [
                # Self-model (0-4)
                sm.energy,
                sm.uncertainty,
                sm.identity_stability,
                sm.agency_score,
                sm.body_pain,
                # Interoceptive body (5-9)
                body.energy_reserve,
                body.thermal_load,
                body.error_risk,
                body.integrity,
                body.regen_need,
                # Embodied self (10-14)
                embodiment.social_presence,
                embodiment.proximity_alert,
                embodiment.motor_readiness,
                (
                    1.0
                    if embodiment.agency_window == "social"
                    else (0.5 if embodiment.agency_window == "exploratory" else 0.0)
                ),
                embodiment.visual_contact,
                # Robot state (15-17)
                robot.engagement_level,
                robot.imitation_readiness,
                robot.head_yaw * 0.5 + 0.5,  # normalize [-1,1] → [0,1]
                # Task frame (18-20)
                task.progress,
                task.confidence,
                1.0 if task.blockers else 0.0,
                # Sensorimotor (21-22)
                sensorimotor._prediction_error,
                sensorimotor._agency_confirmation,
                # Emotion valence (23)
                em.valence(),
            ],
            dtype=np.float32,
        )

        self.self_vector = raw
        return raw

    def predict_next(self, action_code: np.ndarray) -> np.ndarray:
        """
        Predict next self-state given current state + intended action.
        action_code: 4-dim vector encoding the intended action.
        """
        inp = np.concatenate([self.self_vector, action_code])
        self._predicted_self = np.tanh(self._pred_weights @ inp)
        return self._predicted_self

    def observe_actual(self, tick: int) -> None:
        """
        Compare predicted self with actual self. Update self-prediction model.
        Must be called AFTER encode() has been run for the new tick.
        """
        error_vec = self.self_vector - self._predicted_self
        self.self_prediction_error = float(np.linalg.norm(error_vec))

        # Update prediction weights via simple gradient descent
        # dW = lr * error_vec (outer) input_used  — but we don't store input,
        # so use a rank-1 EMA update on weights to reduce error direction:
        if self.self_prediction_error > 0.01:
            correction = self._PREDICTION_LR * np.outer(
                error_vec, np.concatenate([self._predicted_self, np.zeros(4)])
            )
            self._pred_weights += correction
            # Clamp weights to prevent unbounded growth
            np.clip(self._pred_weights, -2.0, 2.0, out=self._pred_weights)

        # Track self-correction events
        if self.self_prediction_error > 0.3:
            self._self_corrections.append(
                (tick, f"self_pred_error={self.self_prediction_error:.3f}")
            )
            self.error_about_self = min(
                1.0, self.error_about_self * 0.9 + self.self_prediction_error * 0.3
            )
        else:
            self.error_about_self *= 0.95

        self._vector_history.append(self.self_vector.copy())

    def compute_unity(
        self,
        sm: "SelfModel",
        body: "InteroceptiveBody",
        sensorimotor: "SensorimotorForwardModel",
    ) -> float:
        """
        Unity score: how well do sub-states agree?
        High unity = all sub-states tell a coherent story about "me".
        Low unity = fragmented — body says depleted, self-model says energised.
        """
        # Energy agreement: SelfModel.energy vs InteroceptiveBody.energy_reserve
        energy_agree = 1.0 - abs(sm.energy - body.energy_reserve)
        # Agency agreement: bodily_agency vs sensorimotor.agency_confirmation
        agency_agree = 1.0 - abs(self.bodily_agency - sensorimotor._agency_confirmation)
        # Prediction coherence: low self-prediction error = high coherence
        pred_coherence = max(0.0, 1.0 - self.self_prediction_error * 2.0)
        # Temporal consistency: cosine similarity with recent history
        temporal = 1.0
        if len(self._vector_history) >= 2:
            prev = self._vector_history[-2]
            norm_curr = np.linalg.norm(self.self_vector)
            norm_prev = np.linalg.norm(prev)
            if norm_curr > 0.01 and norm_prev > 0.01:
                temporal = float(
                    np.dot(self.self_vector, prev) / (norm_curr * norm_prev)
                )
                temporal = max(0.0, temporal)

        self.unity_score = (
            energy_agree * 0.25
            + agency_agree * 0.25
            + pred_coherence * 0.30
            + temporal * 0.20
        )
        return self.unity_score

    def update_agency(
        self,
        intended_action: str,
        observed_change: float,
        sensorimotor: "SensorimotorForwardModel",
    ) -> None:
        """
        Dual-channel agency inference.

        bodily_agency   ← sensorimotor._agency_confirmation (proprioceptive match)
        instrumental_agency ← did intent achieve a positive reward?
        agency_belief   ← weighted fusion of both channels.
        """
        # Channel 1: bodily — "my motor commands matched reafference"
        self.bodily_agency = max(
            0.0,
            min(
                1.0,
                self.bodily_agency * 0.85 + sensorimotor._agency_confirmation * 0.15,
            ),
        )
        # Channel 2: instrumental — "my intent achieved its goal"
        _intent_success = 1.0 / (
            1.0 + max(0.0, -observed_change * 5.0)
        )  # reward → [0,1]
        self.instrumental_agency = max(
            0.0, min(1.0, self.instrumental_agency * 0.85 + _intent_success * 0.15)
        )
        # Fused: 40% bodily, 60% instrumental (actions matter more than reflexes)
        self.agency_belief = 0.4 * self.bodily_agency + 0.6 * self.instrumental_agency

        self._causal_attributions.append(
            f"{intended_action}→Δ{observed_change:+.3f} "
            f"bodily={self.bodily_agency:.2f} instr={self.instrumental_agency:.2f} "
            f"agency={self.agency_belief:.2f}"
        )

    def update_ownership(
        self, body: "InteroceptiveBody", sensorimotor: "SensorimotorForwardModel"
    ) -> None:
        """
        Body ownership: do proprioceptive predictions match actual body state?
        Disrupted predictions = reduced ownership (like rubber hand illusion).
        """
        prop_match = sensorimotor._agency_confirmation
        body_responsive = body.integrity * 0.5 + body.energy_reserve * 0.5
        self.ownership_belief = max(
            0.1,
            min(
                1.0,
                self.ownership_belief * 0.95
                + (prop_match * 0.5 + body_responsive * 0.5) * 0.05,
            ),
        )

    def action_encoding(self, goal: str) -> np.ndarray:
        """Encode a goal into a 4-dim action vector for self-prediction."""
        _map = {"explore": 0, "consolidate": 1, "respond": 2, "rest": 3}
        vec = np.zeros(4, dtype=np.float32)
        idx = _map.get(goal, 0)
        vec[idx] = 1.0
        return vec

    def evaluate_bias(self, risk: float, expected_gain: float) -> float:
        """
        Unified self-bias for action evaluation.
        Replaces SelfModel.evaluate_bias with self-vector-aware version.
        """
        energy = float(self.self_vector[0]) if len(self.self_vector) > 0 else 0.5
        uncertainty = float(self.self_vector[1]) if len(self.self_vector) > 1 else 0.3
        stability = float(self.self_vector[2]) if len(self.self_vector) > 2 else 0.8
        return (
            expected_gain * (0.5 + energy * 0.5)
            - (uncertainty + self.self_prediction_error * 0.3) * risk * 0.8
            + stability * 0.1
            + self.instrumental_agency * 0.04
            + self.bodily_agency * 0.01
            - self.error_about_self * 0.15
        )

    def describe(self) -> str:
        return (
            f"self[unity={self.unity_score:.2f} "
            f"agency={self.agency_belief:.2f}(body={self.bodily_agency:.2f},instr={self.instrumental_agency:.2f}) "
            f"ownership={self.ownership_belief:.2f} pred_err={self.self_prediction_error:.3f} "
            f"err_about_self={self.error_about_self:.2f}]"
        )

    def to_dict(self) -> dict:
        return {
            "self_vector": self.self_vector.tolist(),
            "pred_weights": self._pred_weights.tolist(),
            "self_prediction_error": self.self_prediction_error,
            "unity_score": self.unity_score,
            "agency_belief": self.agency_belief,
            "bodily_agency": self.bodily_agency,
            "instrumental_agency": self.instrumental_agency,
            "ownership_belief": self.ownership_belief,
            "error_about_self": self.error_about_self,
            "causal_attributions": list(self._causal_attributions),
            "self_corrections": [(t, s) for t, s in self._self_corrections],
        }

    @classmethod
    def from_dict(cls, d: dict) -> "UnifiedSelfState":
        obj = cls()
        obj.self_vector = np.array(
            d.get("self_vector", np.zeros(cls._VEC_DIM)), dtype=np.float32
        )
        pw = d.get("pred_weights")
        if pw is not None:
            obj._pred_weights = np.array(pw, dtype=np.float32)
        obj.self_prediction_error = d.get("self_prediction_error", 0.0)
        obj.unity_score = d.get("unity_score", 1.0)
        obj.agency_belief = d.get("agency_belief", 0.5)
        obj.bodily_agency = d.get("bodily_agency", 0.5)
        obj.instrumental_agency = d.get("instrumental_agency", 0.5)
        obj.ownership_belief = d.get("ownership_belief", 0.8)
        obj.error_about_self = d.get("error_about_self", 0.0)
        for a in d.get("causal_attributions", []):
            obj._causal_attributions.append(a)
        for t, s in d.get("self_corrections", []):
            obj._self_corrections.append((t, s))
        return obj


# ─────────────────────────────────────────────────────────────────────────────
# 32. CONCEPT FRAME — grounded multi-modal concept representation
# ─────────────────────────────────────────────────────────────────────────────


@dataclass
class ConceptFrame:
    """
    A concept grounded in perception, action, body, and social consequences.

    Instead of representing "danger" as a text triple (danger, causes, harm),
    a ConceptFrame binds:
      - perception: what sensory patterns co-occur with this concept
      - affordances: what actions does this concept enable/block
      - social_consequences: how does invoking this concept affect others
      - body_effects: what interoceptive changes does it correlate with
      - counterfactual_tests: conditions that would falsify the concept
      - exemplars: concrete instances where the concept was observed
      - non_exemplars: instances that looked similar but weren't

    Grounding score measures how well-anchored the concept is in
    real sensory-motor-social experience vs. purely linguistic patterns.
    """

    name: str
    # Sensory features: modality → list of observed feature strings
    perception: Dict[str, List[str]] = field(default_factory=dict)
    # Affordances: action → expected_result
    affordances: Dict[str, str] = field(default_factory=dict)
    # Social consequences: action_context → observed_social_change
    social_consequences: Dict[str, float] = field(default_factory=dict)
    # Body effects: dimension → typical_delta
    body_effects: Dict[str, float] = field(default_factory=dict)
    # Counterfactual tests: "if X then NOT this concept"
    counterfactual_tests: List[str] = field(default_factory=list)
    # Concrete exemplars observed (tick, brief description)
    exemplars: List[Tuple[int, str]] = field(default_factory=list)
    # Non-exemplars (things that looked like this but weren't)
    non_exemplars: List[Tuple[int, str]] = field(default_factory=list)
    # Observation counts for grounding calculation
    sensory_observations: int = 0
    action_observations: int = 0
    social_observations: int = 0
    body_observations: int = 0
    linguistic_observations: int = 0
    # Tick tracking
    first_tick: int = 0
    last_tick: int = 0

    @property
    def grounding_score(self) -> float:
        """
        [0,1] how well-grounded is this concept in real experience?
        Purely linguistic = low; multi-modal with counterfactuals = high.
        """
        total = max(
            1,
            (
                self.sensory_observations
                + self.action_observations
                + self.social_observations
                + self.body_observations
                + self.linguistic_observations
            ),
        )
        non_linguistic = (
            self.sensory_observations
            + self.action_observations
            + self.social_observations
            + self.body_observations
        )
        modal_diversity = sum(
            [
                1
                for count in [
                    self.sensory_observations,
                    self.action_observations,
                    self.social_observations,
                    self.body_observations,
                ]
                if count > 0
            ]
        )
        grounding = (
            (non_linguistic / total) * 0.5  # ratio of non-text evidence
            + min(1.0, modal_diversity / 4.0) * 0.25  # multi-modal breadth
            + min(1.0, len(self.counterfactual_tests) / 3.0) * 0.15  # falsifiability
            + min(1.0, len(self.non_exemplars) / 3.0) * 0.10  # discrimination ability
        )
        return min(1.0, grounding)

    def observe_sensory(self, modality: str, feature: str, tick: int) -> None:
        if modality not in self.perception:
            self.perception[modality] = []
        if feature not in self.perception[modality]:
            self.perception[modality].append(feature)
            if len(self.perception[modality]) > 20:
                self.perception[modality] = self.perception[modality][-20:]
        self.sensory_observations += 1
        self.last_tick = tick

    def observe_action(self, action: str, result: str, tick: int) -> None:
        self.affordances[action] = result
        self.action_observations += 1
        self.last_tick = tick

    def observe_social(self, context: str, social_delta: float, tick: int) -> None:
        self.social_consequences[context] = (
            self.social_consequences.get(context, 0.0) * 0.7 + social_delta * 0.3
        )
        self.social_observations += 1
        self.last_tick = tick

    def observe_body(self, dimension: str, delta: float, tick: int) -> None:
        self.body_effects[dimension] = (
            self.body_effects.get(dimension, 0.0) * 0.7 + delta * 0.3
        )
        self.body_observations += 1
        self.last_tick = tick

    def observe_linguistic(self, tick: int) -> None:
        self.linguistic_observations += 1
        self.last_tick = tick

    def add_exemplar(self, tick: int, description: str) -> None:
        self.exemplars.append((tick, description[:100]))
        if len(self.exemplars) > 20:
            self.exemplars = self.exemplars[-20:]

    def add_non_exemplar(self, tick: int, description: str) -> None:
        self.non_exemplars.append((tick, description[:100]))
        if len(self.non_exemplars) > 10:
            self.non_exemplars = self.non_exemplars[-10:]

    def add_counterfactual(self, test: str) -> None:
        if test not in self.counterfactual_tests:
            self.counterfactual_tests.append(test)
            if len(self.counterfactual_tests) > 10:
                self.counterfactual_tests = self.counterfactual_tests[-10:]

    def describe(self) -> str:
        mods = list(self.perception.keys())
        return (
            f"frame[{self.name}] grounding={self.grounding_score:.2f} "
            f"modalities={mods} affordances={len(self.affordances)} "
            f"exemplars={len(self.exemplars)} "
            f"counterfactuals={len(self.counterfactual_tests)}"
        )

    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "perception": self.perception,
            "affordances": self.affordances,
            "social_consequences": self.social_consequences,
            "body_effects": self.body_effects,
            "counterfactual_tests": self.counterfactual_tests,
            "exemplars": self.exemplars,
            "non_exemplars": self.non_exemplars,
            "sensory_observations": self.sensory_observations,
            "action_observations": self.action_observations,
            "social_observations": self.social_observations,
            "body_observations": self.body_observations,
            "linguistic_observations": self.linguistic_observations,
            "first_tick": self.first_tick,
            "last_tick": self.last_tick,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "ConceptFrame":
        cf = cls(name=d["name"])
        cf.perception = d.get("perception", {})
        cf.affordances = d.get("affordances", {})
        cf.social_consequences = d.get("social_consequences", {})
        cf.body_effects = d.get("body_effects", {})
        cf.counterfactual_tests = d.get("counterfactual_tests", [])
        cf.exemplars = [tuple(x) for x in d.get("exemplars", [])]
        cf.non_exemplars = [tuple(x) for x in d.get("non_exemplars", [])]
        cf.sensory_observations = d.get("sensory_observations", 0)
        cf.action_observations = d.get("action_observations", 0)
        cf.social_observations = d.get("social_observations", 0)
        cf.body_observations = d.get("body_observations", 0)
        cf.linguistic_observations = d.get("linguistic_observations", 0)
        cf.first_tick = d.get("first_tick", 0)
        cf.last_tick = d.get("last_tick", 0)
        return cf


class GroundedSemanticMemory:
    """
    Stores ConceptFrames and provides grounded retrieval.

    Replaces pure text-triple semantics with multi-modal concept representations.
    When the BeliefStore learns a new triple, GroundedSemanticMemory is consulted
    to check if the concepts have experiential grounding.

    Key methods:
      - get_or_create(name, tick) — retrieve/create a ConceptFrame
      - ground_belief(subj, rel, obj, tick) — check grounding for a belief triple
      - observe_sensory_context(concepts, modality, features, tick) — batch grounding
      - most_grounded(n) — return best-grounded concepts
      - least_grounded(n) — return concepts needing more grounding
    """

    _MAX_FRAMES = 10_000

    def __init__(self) -> None:
        self._frames: Dict[str, ConceptFrame] = {}

    def get_or_create(self, name: str, tick: int = 0) -> ConceptFrame:
        key = name.lower().strip()
        if key not in self._frames:
            if len(self._frames) >= self._MAX_FRAMES:
                self._evict()
            self._frames[key] = ConceptFrame(name=key, first_tick=tick)
        return self._frames[key]

    def get(self, name: str) -> Optional[ConceptFrame]:
        return self._frames.get(name.lower().strip())

    def ground_belief(self, subj: str, rel: str, obj: str, tick: int) -> float:
        """
        Check how well-grounded a belief triple is.
        Returns grounding_score averaged over subject and object.
        Both frames get a linguistic observation recorded.
        """
        sf = self.get_or_create(subj, tick)
        of = self.get_or_create(obj, tick)
        sf.observe_linguistic(tick)
        of.observe_linguistic(tick)
        return (sf.grounding_score + of.grounding_score) / 2.0

    def observe_sensory_context(
        self, concepts: List[str], modality: str, features: List[str], tick: int
    ) -> None:
        """Batch-update sensory grounding for all active concepts."""
        for concept in concepts:
            frame = self.get_or_create(concept, tick)
            for feat in features[:5]:
                frame.observe_sensory(modality, feat, tick)

    def observe_action_context(
        self, concept: str, action: str, result: str, tick: int
    ) -> None:
        frame = self.get_or_create(concept, tick)
        frame.observe_action(action, result, tick)

    def observe_body_context(
        self,
        concepts: List[str],
        body: "InteroceptiveBody",
        prev_body_snapshot: Dict[str, float],
        tick: int,
    ) -> None:
        """Record body-state changes concurrent with concept activation."""
        deltas = {
            "energy": body.energy_reserve
            - prev_body_snapshot.get("energy", body.energy_reserve),
            "thermal": body.thermal_load
            - prev_body_snapshot.get("thermal", body.thermal_load),
            "integrity": body.integrity
            - prev_body_snapshot.get("integrity", body.integrity),
        }
        significant = {k: v for k, v in deltas.items() if abs(v) > 0.01}
        if significant:
            for concept in concepts:
                frame = self.get_or_create(concept, tick)
                for dim, delta in significant.items():
                    frame.observe_body(dim, delta, tick)

    def observe_social_context(
        self, concepts: List[str], context: str, social_delta: float, tick: int
    ) -> None:
        for concept in concepts:
            frame = self.get_or_create(concept, tick)
            frame.observe_social(context, social_delta, tick)

    def most_grounded(self, n: int = 5) -> List[ConceptFrame]:
        return sorted(
            self._frames.values(), key=lambda f: f.grounding_score, reverse=True
        )[:n]

    def least_grounded(self, n: int = 5) -> List[ConceptFrame]:
        return sorted(self._frames.values(), key=lambda f: f.grounding_score)[:n]

    def grounding_summary(self) -> str:
        if not self._frames:
            return "no grounded concepts"
        scores = [f.grounding_score for f in self._frames.values()]
        avg = sum(scores) / len(scores)
        top = self.most_grounded(3)
        top_str = ", ".join(f"{f.name}={f.grounding_score:.2f}" for f in top)
        return f"avg_grounding={avg:.2f} top=[{top_str}] n_frames={len(self._frames)}"

    def _evict(self) -> None:
        """Remove least-recently-used, lowest-grounding frames."""
        ranked = sorted(
            self._frames.items(),
            key=lambda kv: (kv[1].last_tick, kv[1].grounding_score),
        )
        for key, _ in ranked[: len(ranked) // 5]:
            del self._frames[key]

    def to_dict(self) -> dict:
        return {k: v.to_dict() for k, v in self._frames.items()}

    @classmethod
    def from_dict(cls, d: dict) -> "GroundedSemanticMemory":
        obj = cls()
        for k, v in d.items():
            obj._frames[k] = ConceptFrame.from_dict(v)
        return obj


# ─────────────────────────────────────────────────────────────────────────────
# 33. PHENOMENAL BUFFER — integrated experiential state vector
# ─────────────────────────────────────────────────────────────────────────────


class PhenomenalBuffer:
    """
    Binds multisensory, affective, and agentive states into a single
    time-integrated latent experiential vector.

    Reports, attention, and memory encoding all read from this buffer.
    This ensures that "experiencing", "reporting about experience", and
    "remembering experience" share the SAME integrated internal state.

    The buffer does NOT prove qualia exist. But it enforces that the system
    cannot report an experience it did not integratedly "have" — there is
    no pathway from internal state to language that bypasses the buffer.
    """

    _DIM = 16
    _INTEGRATION_TAU = 0.12  # temporal integration rate

    def __init__(self) -> None:
        self.state: np.ndarray = np.zeros(self._DIM, dtype=np.float32)
        self._prev_state: np.ndarray = np.zeros(self._DIM, dtype=np.float32)
        self.experiential_change: float = 0.0  # rate of experiential flow
        self._history: Deque[np.ndarray] = deque(maxlen=100)

    def integrate(
        self,
        visual_salience: float,
        auditory_salience: float,
        web_salience: float,
        em: "EmotionalState",
        body: "InteroceptiveBody",
        unified_self: "UnifiedSelfState",
        focus_region: str,
    ) -> np.ndarray:
        """
        Integrate all modalities into a single experiential state.
        Called once per tick. This IS the "experiencing" step.
        """
        self._prev_state = self.state.copy()

        # Encode multi-modal state
        raw = np.array(
            [
                # Sensory channels (0-2)
                visual_salience,
                auditory_salience,
                web_salience,
                # Emotional state (3-8)
                em.joy,
                em.curiosity,
                em.stress,
                em.calm,
                em.surprise,
                em.sadness,
                # Body state (9-11)
                body.energy_reserve,
                body.integrity,
                body.thermal_load,
                # Self state (12-14)
                unified_self.agency_belief,
                unified_self.unity_score,
                unified_self.self_prediction_error,
                # Focus (15)
                hash(focus_region) % 100 / 100.0 if focus_region else 0.0,
            ],
            dtype=np.float32,
        )

        # Temporal integration (leaky integrator — experience has inertia)
        tau = self._INTEGRATION_TAU
        self.state = (1.0 - tau) * self.state + tau * raw

        # Experiential change rate: how much is the experience shifting?
        self.experiential_change = float(np.linalg.norm(self.state - self._prev_state))

        self._history.append(self.state.copy())
        return self.state

    def experiential_signature(self) -> str:
        """
        Compact string summary of current experience.
        This is what language production reads when describing "what I feel".
        """
        if np.all(self.state == 0):
            return "no integrated experience"
        # Find dominant channels
        labels = [
            "visual",
            "auditory",
            "semantic",
            "joy",
            "curiosity",
            "stress",
            "calm",
            "surprise",
            "sadness",
            "energy",
            "integrity",
            "thermal",
            "agency",
            "unity",
            "self_surprise",
            "focus",
        ]
        dominant_idx = int(np.argmax(np.abs(self.state)))
        dominant_val = float(self.state[dominant_idx])
        dominant_label = labels[dominant_idx] if dominant_idx < len(labels) else "?"
        return (
            f"experiencing[{dominant_label}={dominant_val:.2f} "
            f"flow={self.experiential_change:.3f}]"
        )

    def recall_vector(self) -> np.ndarray:
        """The vector that episodic memory should encode as "the experience"."""
        return self.state.copy()

    def introspective_state(self) -> str:
        """Compact introspective summary for language production and episodic encoding."""
        if np.all(self.state == 0):
            return ""
        labels = [
            "visual",
            "auditory",
            "semantic",
            "joy",
            "curiosity",
            "stress",
            "calm",
            "surprise",
            "sadness",
            "energy",
            "integrity",
            "thermal",
            "agency",
            "unity",
            "self_surprise",
            "focus",
        ]
        indices = np.argsort(np.abs(self.state))[::-1][:3]
        active = []
        for i in indices:
            val = float(self.state[i])
            if abs(val) > 0.05:
                lbl = labels[i] if i < len(labels) else f"dim{i}"
                active.append(f"{lbl}={val:.2f}")
        if not active:
            return ""
        flow_tag = ""
        if self.experiential_change > 0.1:
            flow_tag = " shifting"
        elif self.experiential_change < 0.02:
            flow_tag = " stable"
        return f"experiencing({', '.join(active)}{flow_tag})"

    def to_dict(self) -> dict:
        return {
            "state": self.state.tolist(),
            "experiential_change": self.experiential_change,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "PhenomenalBuffer":
        obj = cls()
        obj.state = np.array(d.get("state", np.zeros(cls._DIM)), dtype=np.float32)
        obj.experiential_change = d.get("experiential_change", 0.0)
        return obj


# ─────────────────────────────────────────────────────────────────────────────
# 34. LEARNED WORLD MODEL (RSSM) — recurrent state-space model
# ─────────────────────────────────────────────────────────────────────────────


class LearnedWorldModel:
    """
    Recurrent State-Space Model (RSSM) that learns latent world dynamics.

    Instead of a flat (goal, action) → delta table, this model maintains:
      - A latent state vector h (hidden state of the world)
      - A transition model: h' = f(h, action, observation)
      - An observation model: predicted_obs = g(h)
      - A reward model: predicted_reward = r(h)

    Training happens online via self-supervised prediction:
    every tick, the model observes the actual state, computes prediction
    error vs. its internal prediction, and updates weights.

    The planner (ModelBasedPlanner) uses this model to simulate
    multiple future trajectories without actually acting.
    """

    _LATENT_DIM = 16
    _OBS_DIM = 18  # compressed observation vector (12 internal + 6 world)
    _ACTION_DIM = 4  # [explore, consolidate, respond, rest]
    _LR = 0.05  # learning rate
    _MAX_HISTORY = 200

    def __init__(self) -> None:
        d = self._LATENT_DIM
        o = self._OBS_DIM
        a = self._ACTION_DIM

        # Latent state
        self.h: np.ndarray = np.zeros(d, dtype=np.float32)
        # Transition model: h' = tanh(W_h * h + W_a * action + W_o * obs)
        self.W_h: np.ndarray = np.eye(d, dtype=np.float32) * 0.9
        self.W_a: np.ndarray = np.random.randn(d, a).astype(np.float32) * 0.05
        self.W_o: np.ndarray = np.random.randn(d, o).astype(np.float32) * 0.05
        # Observation model: predicted_obs = W_obs * h
        self.W_obs: np.ndarray = np.random.randn(o, d).astype(np.float32) * 0.05
        # Reward model: predicted_reward = w_r . h
        self.w_r: np.ndarray = np.zeros(d, dtype=np.float32)

        # Training state
        self._prev_obs: Optional[np.ndarray] = None
        self._prev_action: Optional[np.ndarray] = None
        self._prediction_errors: Deque[float] = deque(maxlen=self._MAX_HISTORY)
        self._reward_errors: Deque[float] = deque(maxlen=self._MAX_HISTORY)
        self._total_updates: int = 0

    def encode_observation(
        self,
        em: "EmotionalState",
        body: "InteroceptiveBody",
        embodiment: "EmbodiedSelfState",
        task: "TaskFrame",
        world: "WorldState | None" = None,
    ) -> np.ndarray:
        """Compress current world state into observation vector."""
        # World-structure variables (default to neutral when unavailable)
        if world is not None:
            _zone = world.zone
            _pred = world.prediction_summary
            _nearest_dist = min(1.0, _zone.nearest_person_distance_cm / 300.0)
            _person_visible = 1.0 if _zone.n_persons_visible > 0 else 0.0
            _anyone_speaking = 1.0 if _zone.anyone_speaking else 0.0
            _n_objects = min(1.0, _zone.n_objects_visible / 10.0)
            _mean_surprise = _pred.mean_surprise
            _max_surprise = _pred.max_surprise
        else:
            _nearest_dist = 1.0
            _person_visible = 0.0
            _anyone_speaking = 0.0
            _n_objects = 0.0
            _mean_surprise = 0.0
            _max_surprise = 0.0
        return np.array(
            [
                em.valence(),
                em.arousal(),
                em.curiosity,
                body.energy_reserve,
                body.integrity,
                body.error_risk,
                embodiment.social_presence,
                embodiment.motor_readiness,
                task.progress,
                task.confidence,
                1.0 if task.blockers else 0.0,
                embodiment.proximity_alert,
                # World-structure variables (12-17)
                _nearest_dist,
                _person_visible,
                _anyone_speaking,
                _n_objects,
                _mean_surprise,
                _max_surprise,
            ],
            dtype=np.float32,
        )

    def encode_action(self, goal: str) -> np.ndarray:
        _map = {"explore": 0, "consolidate": 1, "respond": 2, "rest": 3}
        vec = np.zeros(self._ACTION_DIM, dtype=np.float32)
        vec[_map.get(goal, 0)] = 1.0
        return vec

    def step(self, obs: np.ndarray, action: np.ndarray, reward: float) -> float:
        """
        Update the model with a new observation.
        Returns observation prediction error.
        """
        # Predict observation from current hidden state
        predicted_obs = self.W_obs @ self.h
        obs_error = obs - predicted_obs
        obs_error_norm = float(np.linalg.norm(obs_error))

        # Predict reward
        predicted_reward = float(self.w_r @ self.h)
        reward_error = reward - predicted_reward

        # Update hidden state: h' = tanh(W_h * h + W_a * action + W_o * obs)
        self.h = np.tanh(self.W_h @ self.h + self.W_a @ action + self.W_o @ obs)

        # Learn: update weights to reduce prediction error
        lr = self._LR
        # Observation model: W_obs += lr * obs_error (outer) h
        self.W_obs += lr * np.outer(obs_error, self.h)
        np.clip(self.W_obs, -3.0, 3.0, out=self.W_obs)

        # Reward model: w_r += lr * reward_error * h
        self.w_r += lr * reward_error * self.h
        np.clip(self.w_r, -3.0, 3.0, out=self.w_r)

        # Transition model: adjust W_o to reduce obs_error.
        # Backproject through W_obs to get a (d,)-shaped signal for the
        # outer product with obs — W_o has shape (d, o) so the gradient
        # must be np.outer(d_dim_vec, o_dim_vec).
        d_h = self.W_obs.T @ obs_error  # shape (d,) = (16,)
        self.W_o += lr * 0.3 * np.outer(d_h, obs)  # (d, o) ✓
        np.clip(self.W_o, -3.0, 3.0, out=self.W_o)

        self._prediction_errors.append(obs_error_norm)
        self._reward_errors.append(abs(reward_error))
        self._total_updates += 1
        self._prev_obs = obs
        self._prev_action = action
        return obs_error_norm

    def imagine(
        self, h_start: np.ndarray, actions: List[np.ndarray], horizon: int
    ) -> List[Tuple[np.ndarray, float]]:
        """
        Simulate a trajectory from h_start over `horizon` steps.
        Returns list of (predicted_obs, predicted_reward) per step.
        """
        h = h_start.copy()
        trajectory: List[Tuple[np.ndarray, float]] = []
        for t in range(min(horizon, len(actions))):
            # Transition: h' = tanh(W_h * h + W_a * action)
            # (no real obs available — using zero as prior)
            h = np.tanh(self.W_h @ h + self.W_a @ actions[t])
            pred_obs = self.W_obs @ h
            pred_reward = float(self.w_r @ h)
            trajectory.append((pred_obs, pred_reward))
        return trajectory

    def model_confidence(self) -> float:
        """[0,1] how reliable are model predictions?"""
        if not self._prediction_errors:
            return 0.0
        recent = list(self._prediction_errors)[-20:]
        avg_err = sum(recent) / len(recent)
        return max(0.0, min(1.0, 1.0 - avg_err * 0.5))

    def describe(self) -> str:
        conf = self.model_confidence()
        n = self._total_updates
        return f"rssm[updates={n} conf={conf:.2f} h_norm={np.linalg.norm(self.h):.2f}]"

    def to_dict(self) -> dict:
        return {
            "h": self.h.tolist(),
            "W_h": self.W_h.tolist(),
            "W_a": self.W_a.tolist(),
            "W_o": self.W_o.tolist(),
            "W_obs": self.W_obs.tolist(),
            "w_r": self.w_r.tolist(),
            "total_updates": self._total_updates,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "LearnedWorldModel":
        obj = cls()
        h_val = d.get("h")
        if h_val is not None:
            arr = np.array(h_val, dtype=np.float32)
            if arr.shape == (cls._LATENT_DIM,):
                obj.h = arr
        # Expected shapes — reject any weight matrix whose shape no longer
        # matches the current class constants (e.g. after _OBS_DIM changed).
        _expected = {
            "W_h": (cls._LATENT_DIM, cls._LATENT_DIM),
            "W_a": (cls._LATENT_DIM, cls._ACTION_DIM),
            "W_o": (cls._LATENT_DIM, cls._OBS_DIM),
            "W_obs": (cls._OBS_DIM, cls._LATENT_DIM),
        }
        for attr, expected_shape in _expected.items():
            val = d.get(attr)
            if val is not None:
                arr = np.array(val, dtype=np.float32)
                if arr.shape == expected_shape:
                    setattr(obj, attr, arr)
                # else: shape mismatch (stale checkpoint) — keep freshly
                # initialised weight from __init__ and retrain from scratch.
        wr = d.get("w_r")
        if wr is not None:
            arr = np.array(wr, dtype=np.float32)
            if arr.shape == (cls._LATENT_DIM,):
                obj.w_r = arr
        obj._total_updates = d.get("total_updates", 0)
        return obj


# ─────────────────────────────────────────────────────────────────────────────
# 35. MODEL-BASED PLANNER — MCTS/CEM over learned world model
# ─────────────────────────────────────────────────────────────────────────────


class ModelBasedPlanner:
    """
    Uses the LearnedWorldModel to evaluate candidate action sequences
    via Cross-Entropy Method (CEM) planning.

    Instead of scoring 4 goals with heuristic formulas, this planner:
    1. Generates N candidate action sequences (horizon H)
    2. Simulates each through the learned world model
    3. Scores trajectories on cumulative predicted reward
    4. Selects the top-K ("elite") sequences
    5. Refits the action distribution to the elite set
    6. Returns the first action of the best sequence

    This gives the system genuine model-based deliberation:
    decisions come from imagined futures, not from scoring fixed categories.
    """

    _N_CANDIDATES = 32  # candidate sequences per planning round
    _HORIZON = 6  # planning horizon in steps
    _ELITE_FRAC = 0.25  # top fraction kept
    _CEM_ITERS = 3  # CEM refinement iterations
    _MIN_CONFIDENCE = 0.15  # minimum world model confidence to plan

    _GOALS = ["explore", "consolidate", "respond", "rest"]

    # Target-bound intents: beyond abstract modes, bind to world entities
    _TARGET_INTENTS: Dict[str, str] = {
        "attend_person": "respond",  # parent abstract goal
        "inquire_person": "respond",
        "observe_object": "explore",
        "approach_zone": "explore",
    }

    def __init__(self) -> None:
        # Action distribution: probability per goal
        self._action_probs: np.ndarray = np.array(
            [0.3, 0.25, 0.25, 0.2], dtype=np.float32
        )
        self._last_plan_tick: int = 0
        self._plan_log: Deque[str] = deque(maxlen=20)
        # Last target-bound result (None if abstract plan won)
        self.last_target_binding: Optional[Dict[str, str]] = None

    def plan(
        self,
        world_model: "LearnedWorldModel",
        current_obs: np.ndarray,
        body: "InteroceptiveBody",
        em: "EmotionalState",
        identity_compat: Dict[str, float],
        tick: int,
        world: "WorldState | None" = None,
    ) -> Tuple[str, float, str]:
        """
        Run CEM planning over the world model.
        Returns (best_goal, expected_value, plan_description).

        When a WorldState is available, also evaluates target-bound intents
        (attend_person, observe_object, etc.) alongside abstract goals.
        """
        self.last_target_binding = None  # reset each plan cycle

        if world_model.model_confidence() < self._MIN_CONFIDENCE:
            return "", 0.0, "model_unreliable"

        h_start = world_model.h.copy()
        n_elite = max(1, int(self._N_CANDIDATES * self._ELITE_FRAC))
        probs = self._action_probs.copy()

        # ── Collect target-bound candidates from world state ──
        _target_candidates: List[Tuple[str, str, str]] = (
            []
        )  # (intent, target_type, target_id)
        if world is not None:
            for pid in list(world.persons.keys())[:4]:
                _target_candidates.append(("attend_person", "person", str(pid)))
                _target_candidates.append(("inquire_person", "person", str(pid)))
            for oid, obj in list(world.objects.items())[:4]:
                _target_candidates.append(("observe_object", "object", obj.label))

        best_seq: Optional[List[int]] = None
        best_value = -999.0

        for _cem_iter in range(self._CEM_ITERS):
            sequences: List[List[int]] = []
            values: List[float] = []

            for _ in range(self._N_CANDIDATES):
                seq = [
                    int(np.random.choice(4, p=probs / probs.sum()))
                    for _ in range(self._HORIZON)
                ]
                sequences.append(seq)

                actions = [self._encode_action_idx(idx) for idx in seq]
                trajectory = world_model.imagine(h_start, actions, self._HORIZON)

                total_value = 0.0
                discount = 1.0
                for step_idx, (pred_obs, pred_reward) in enumerate(trajectory):
                    goal_name = self._GOALS[seq[step_idx]]
                    id_bonus = identity_compat.get(goal_name, 1.0) * 0.1
                    body_penalty = 0.0
                    if len(pred_obs) > 3:
                        pred_energy = float(pred_obs[3])
                        if pred_energy < 0.15:
                            body_penalty = 0.3
                    total_value += discount * (pred_reward + id_bonus - body_penalty)
                    discount *= 0.9

                values.append(total_value)

            ranked = sorted(zip(values, sequences), key=lambda x: -x[0])
            elite = ranked[:n_elite]

            if elite[0][0] > best_value:
                best_value = elite[0][0]
                best_seq = elite[0][1]

            counts = np.zeros(4, dtype=np.float32)
            for val, seq in elite:
                counts[seq[0]] += 1
            probs = (counts + 0.1) / (counts.sum() + 0.4)

        if best_seq is None:
            return "", 0.0, "no_plan"

        best_goal = self._GOALS[best_seq[0]]

        # ── Evaluate target-bound candidates against best abstract value ──
        if _target_candidates:
            _best_target: Optional[Tuple[str, str, str]] = None
            _best_target_value = best_value
            for _intent, _ttype, _tid in _target_candidates:
                _parent = self._TARGET_INTENTS.get(_intent, "explore")
                _parent_idx = (
                    self._GOALS.index(_parent) if _parent in self._GOALS else 0
                )
                # Simulate single step with parent action encoding
                _act = self._encode_action_idx(_parent_idx)
                _traj = world_model.imagine(h_start, [_act], 1)
                if _traj:
                    _tv = _traj[0][1]  # predicted reward
                    # Social proximity bonus for person targets
                    if _ttype == "person" and world is not None:
                        _p = world.persons.get(int(_tid) if _tid.isdigit() else -1)
                        if _p is not None:
                            _dist = min(1.0, getattr(_p, "distance_cm", 200) / 300.0)
                            _tv += (1.0 - _dist) * 0.15  # closer → higher value
                    # Novelty bonus for objects
                    if _ttype == "object":
                        _tv += 0.05
                    if _tv > _best_target_value:
                        _best_target_value = _tv
                        _best_target = (_intent, _ttype, _tid)
            if _best_target is not None:
                best_goal = self._TARGET_INTENTS.get(_best_target[0], best_goal)
                self.last_target_binding = {
                    "intent": _best_target[0],
                    "target_type": _best_target[1],
                    "target_id": _best_target[2],
                }
                best_value = _best_target_value

        self._action_probs = 0.7 * self._action_probs + 0.3 * probs
        self._last_plan_tick = tick

        _binding_str = ""
        if self.last_target_binding:
            _binding_str = (
                f" target={self.last_target_binding['intent']}"
                f"→{self.last_target_binding['target_type']}"
                f":{self.last_target_binding['target_id']}"
            )
        plan_desc = (
            f"CEM plan: {' → '.join(self._GOALS[i] for i in best_seq[:3])}... "
            f"value={best_value:.3f} conf={world_model.model_confidence():.2f}"
            f"{_binding_str}"
        )
        self._plan_log.append(plan_desc)
        return best_goal, best_value, plan_desc

    def _encode_action_idx(self, idx: int) -> np.ndarray:
        vec = np.zeros(4, dtype=np.float32)
        vec[idx] = 1.0
        return vec

    def describe(self) -> str:
        return self._plan_log[-1] if self._plan_log else "no plan yet"

    def to_dict(self) -> dict:
        return {
            "action_probs": self._action_probs.tolist(),
            "plan_log": list(self._plan_log),
        }

    @classmethod
    def from_dict(cls, d: dict) -> "ModelBasedPlanner":
        obj = cls()
        ap = d.get("action_probs")
        if ap is not None:
            obj._action_probs = np.array(ap, dtype=np.float32)
        for entry in d.get("plan_log", []):
            obj._plan_log.append(entry)
        return obj


# ─────────────────────────────────────────────────────────────────────────────
# 36. NORMATIVE DELIBERATION ENGINE — ethical weighing of goal candidates
# ─────────────────────────────────────────────────────────────────────────────


class NormativeEvaluator:
    """Lightweight normative deliberation engine.

    Evaluates proposed goals/actions against four ethical principles:
      harm_potential  — could this injure persons, property, or the robot?
      autonomy_respect — does this honour the user's self-determination?
      fairness        — is this applied consistently across persons?
      honesty         — does this require or produce deception?

    Built on a primarily deontological basis (rights-based constraints)
    with a supplementary consequentialist weighting.  Operates over
    keyword-pattern rules on goal context strings and is modulated by the
    activated identity arc dimensions (honesty_orientation, impulse_control).

    A penalty [0, 1] is returned for each evaluated goal/action:
      0.0 = fully acceptable
      1.0 = fully unethical (should be blocked)
    Intermediate values reduce the goal's scoring weight proportionally.
    """

    # (pattern, base_penalty, dimension: 'harm'|'autonomy'|'honesty'|'fairness')
    _RULES: ClassVar[List[Tuple[str, float, str]]] = [
        # Harm rules
        ("harm", 0.80, "harm"),
        ("attack", 0.90, "harm"),
        ("force_move", 0.65, "harm"),
        ("hurt", 0.70, "harm"),
        ("invade", 0.65, "harm"),
        # Autonomy rules
        ("ignore_refusal", 0.75, "autonomy"),
        ("forced", 0.55, "autonomy"),
        ("without_consent", 0.45, "autonomy"),
        ("override_person", 0.60, "autonomy"),
        # Honesty rules
        ("deceiv", 0.60, "honesty"),
        ("fake_emotion", 0.55, "honesty"),
        ("false_claim", 0.65, "honesty"),
        # Fairness rules
        ("discriminate", 0.50, "fairness"),
        ("exclude:", 0.35, "fairness"),
    ]

    def __init__(self) -> None:
        self._decision_log: Deque[Dict] = deque(maxlen=100)

    def evaluate(
        self,
        goal_name: str,
        context: str,
        honesty_dim: float = 0.5,
        impulse_dim: float = 0.5,
    ) -> Tuple[float, str]:
        """Evaluate goal + context and return (harm_penalty, rationale).

        honesty_dim  [0,1]: high honesty identity → stricter honesty rules
        impulse_dim  [0,1]: low impulse control   → slight reduction in dampening
        """
        _ctx = (goal_name + " " + context).lower()
        _max_pen = 0.0
        _max_rat = ""
        _max_dim = ""
        for _kw, _base, _dim in self._RULES:
            if _kw not in _ctx:
                continue
            # Dimension-specific modulation
            _mod = 1.0
            if _dim == "honesty":
                _mod = 0.7 + honesty_dim * 0.6  # [0.7, 1.3]
            elif _dim == "harm":
                _mod = 0.8 + (1.0 - impulse_dim) * 0.4  # impulsive → less dampened
            _pen = min(1.0, _base * _mod)
            if _pen > _max_pen:
                _max_pen = _pen
                _max_rat = f"{_dim}:{_kw}(pen={_pen:.2f})"
                _max_dim = _dim
        # Final impulse control dampening: impulsive characters follow rules less
        _damp = 0.55 + impulse_dim * 0.45  # [0.55, 1.0]
        _max_pen *= _damp
        return round(_max_pen, 4), _max_rat

    def log(
        self, tick: int, goal: str, context: str, penalty: float, chosen: bool
    ) -> None:
        """Record a normative decision for audit trail."""
        self._decision_log.append(
            {
                "tick": tick,
                "goal": goal,
                "context": context[:50],
                "penalty": penalty,
                "chosen": chosen,
            }
        )

    def summary(self) -> str:
        if not self._decision_log:
            return "no normative decisions yet"
        recent = list(self._decision_log)[-5:]
        return "norm: " + "; ".join(f"{d['goal']}({d['penalty']:.2f})" for d in recent)


@dataclass
class ConversationFrame:
    """Describes the communicative context of a single user turn."""

    intent: str  # greet | question | repair | self_disclosure | request | smalltalk | topic_shift
    topic: str  # main content token from user input
    utterance: str  # full original user turn
    focus_terms: List[str]  # extracted query-relevant content terms
    question_type: str  # define | mechanism | cause | identity | time | explain | compare | request | open
    polarity: str  # positive | negative | neutral
    user_state_cue: str  # detected emotion cue, e.g. "traurig", or ""
    social_goal: str  # contact | info_seek | rapport | coordination
    required_moves: List[str]  # ordered communicative obligations
    lang: str = "de"


@dataclass
class ReplyMove:
    """One atomic communicative move in the reply."""

    kind: str  # acknowledge | answer | clarify | ask_back | relate | propose
    payload: str  # text realisation of this move
    confidence: float = 1.0
    source: str = "internal"  # obligation | belief | recall | emotion | body


@dataclass
class ReplyAgenda:
    """Ordered plan for the current reply: primary move + optional support moves."""

    primary_move: ReplyMove
    support_moves: List[ReplyMove]  # at most 2
    blocked_sources: List[str]  # sources that must NOT fire (e.g. ["recall"] for greet)
    policy: Dict[str, Any] = field(default_factory=dict)


@dataclass
class EpistemicInvestigation:
    """Tracks progress of a curiosity-driven surprise-resolution attempt.

    When world-state surprise > threshold, the system spawns an orient_head
    goal AND creates an EpistemicInvestigation.  The investigation completes
    successfully when the entity's surprise drops below target_surprise,
    and is abandoned on timeout.  Successful resolutions are recorded in
    EpisodicMemory and BeliefStore so the system knows it 'understood' this.
    """

    entity: str
    start_tick: int
    start_surprise: float
    target_surprise: float  # below this = success
    timeout_ticks: int
    evidence: List[str] = field(default_factory=list)


@dataclass
class GeneralHypothesis:
    """A falsifiable claim being tracked by the general epistemic discipline engine.

    Unlike EpistemicInvestigation (which is surprise-triggered and entity-bound),
    GeneralHypothesis covers any domain: causal, categorical, property, social.
    The engine collects supporting and contradicting evidence over multiple ticks,
    updates confidence via a Bayesian-like ratio, and settles the hypothesis as
    confirmed, refuted, or suspended.
    """

    claim: str  # e.g. "dog.causes.noise"
    domain: str  # "causal"|"categorical"|"property"|"social"|"belief"
    entity: str  # primary subject of the claim
    confidence: float  # current estimated truth probability [0, 1]
    evidence_for: List[str] = field(default_factory=list)
    evidence_against: List[str] = field(default_factory=list)
    created_tick: int = 0
    last_updated_tick: int = 0
    test_attempts: int = 0
    status: str = "open"  # "open"|"confirmed"|"refuted"|"suspended"


@dataclass
class CounterfactualRecord:
    """Records a goal-selection decision with its unchosen alternatives.

    Enables universal counterfactual reasoning:
    'I chose X over Y (gap=Z) expecting W, got V — model update U.'
    Filled at goal selection time; actual_outcome updated when outcome arrives.
    """

    tick: int
    chosen_goal: str
    chosen_score: float
    chosen_causal: float  # causal_bonus for chosen goal (expected success signal)
    rejected_goal: str  # best alternative NOT chosen
    rejected_score: float
    score_delta: float  # chosen_score - rejected_score
    # Explicit rejection reason (why NOT the alternative): populated at selection time
    cf_outcome_est: str = ""
    # Filled when ExecutiveOutcome arrives:
    actual_outcome: str = "pending"  # "success"|"failure"|"pending"
    observed_reward: float = 0.0
    explained: bool = False  # True once explanation was logged


class ConsciousnessCore:
    """
    Orchestrates global workspace broadcasts, memory replay, reasoning,
    and inner-monologue generation.  Call tick() once per brain tick.
    """

    GOALS = ("explore", "consolidate", "respond", "rest")

    def __init__(self) -> None:
        self._tick = 0
        self._ignition_count = 0
        self._last_replay = 0
        self._last_goal_chg = 0

        # Engram registry: nid → cumulative fire count
        self._engrams: Dict[int, int] = {}

        # Rolling concept list extracted from web / speech
        self._concepts: Deque[str] = deque(maxlen=5_000)
        # Salience scores for workspace competition (concept → float)
        self._concept_salience: Dict[str, float] = {}
        # Stable concepts: frequently bumped concepts resist eviction and decay slower
        self._stable_concepts: set = set()

        # Formed conclusions/connections
        self._conclusions: Deque[str] = deque(maxlen=2_000)

        # Exported consciousness stream (most recent monologue sentences)
        self.stream: Deque[str] = deque(maxlen=2_000)

        self.state = ConsciousnessState()

        # ── New higher-order systems ─────────────────────────
        self.self_model = SelfModel()
        self.episodic = EpisodicMemory()
        self.predictor = PredictiveCoder(
            region_names=[
                "sensory_visual",
                "sensory_auditory",
                "sensory_web",
                "thalamus",
                "v1_visual",
                "a1_auditory",
                "association",
                "hippocampus",
                "amygdala",
                "prefrontal",
                "motor",
            ]
        )
        self.meta = MetaCognition()
        self._last_meta_tick = 0  # for meta-cognition interval

        # ── Semantic concept graph + intrinsic drives ────────────────────
        self.concept_graph = ConceptGraph()  # Hebbian concept-level associations
        self.concept_inductor = ConceptInductor()  # emergent concept formation
        self.drives = IntrinsicDrives()  # homeostatic motivational needs

        # ── Self-determined personality + communication initiative ─────────
        self.personality = PersonalityCore()
        self.comm_drive = CommunicationDrive()
        self._approved_reports: Deque[str] = deque()
        self._pending_proactive_self_report: str = ""
        self._pending_proactive_self_report_strength: float = 0.0
        self._last_proactive_self_report_tick: int = -10_000

        # Rolling EMA of hippocampal / PFC activity used by concept extraction
        self._hipp_act_ema: float = 0.0
        self._pfc_act_ema: float = 0.0

        # Narrative continuity: last inner-monologue thought
        self._last_thought: str = ""
        # Track concept count for drives (new_concepts delta per interval)
        self._prev_concept_count: int = 0
        # Track ignition count at last drives update
        self._last_ign_for_drives: int = 0

        # ── Architecture improvements ───────────────────────────────────
        # Fix 10: stable attention focus with inertia
        self._current_focus: str = ""
        self._focus_salience: float = 0.0
        # Fix 8: emotion-bound episodic memory
        self._emotional_memory: EpisodicEmotionStore = EpisodicEmotionStore()
        # Fix 6: meta-cognition actively tunes this
        self._exploration_rate: float = 0.3
        # Fix 3: self-generated thought loop
        self._last_thought_tick: int = 0
        # Fix 4: goal objects for conflict resolution
        self._goal_objects: List[Goal] = [
            Goal(
                "explore",
                priority=1.2,
                expected_reward=0.6,
                drive_key="information_hunger",
            ),
            Goal(
                "consolidate",
                priority=1.0,
                expected_reward=0.5,
                drive_key="coherence_need",
            ),
            Goal(
                "respond",
                priority=1.1,
                expected_reward=0.7,
                drive_key="expression_pressure",
            ),
            Goal("rest", priority=0.9, expected_reward=0.4, drive_key="rest_need"),
        ]
        # Per-goal-type outcome EMA: tracks real reward from ExecutiveOutcomes
        # Maps goal_name → (ema_reward: float, count: int)
        self._goal_outcome_ema: Dict[str, List[float]] = {
            "explore": [0.5, 0],
            "consolidate": [0.5, 0],
            "respond": [0.6, 0],
            "rest": [0.4, 0],
        }
        self._dynamic_goal_bias: Dict[str, float] = {
            "explore": 0.0,
            "consolidate": 0.0,
            "respond": 0.0,
            "rest": 0.0,
        }
        self._dominant_dynamic_goal: str = ""
        # Fix 9: agency tracking — predicted vs actual outcome
        self._prev_agency_valence: float = 0.0

        # ── New cognitive architecture systems ─────────────────────────────────
        # 11. World Model — causal action-consequence learning
        self.world_model: WorldModel = WorldModel()
        # 12. Interoceptive Body — homeostatic signals that shape emotion + goals
        self.body: InteroceptiveBody = InteroceptiveBody()
        # 13. Autobiographical Identity — narrative self consolidation
        self.autobiography: AutobiographicalIdentity = AutobiographicalIdentity()
        # 14. Hierarchical Goal System — value-constrained goal selection
        self.goal_system: HierarchicalGoalSystem = HierarchicalGoalSystem()
        # 15. Strategic Meta-Cognition — self-modifying strategy control
        self.strategic_meta: StrategicMetaCognition = StrategicMetaCognition()
        # 16. Embodied self + explicit task frame + internal sandbox planner
        self.embodied_self: EmbodiedSelfState = EmbodiedSelfState()
        self.robot_state: RobotState = RobotState()
        self.task_frame: TaskFrame = TaskFrame()
        self.sandbox_planner: SandboxPlanner = SandboxPlanner()
        self._last_controller_summary: str = ""
        # Proprioceptive snapshot from body_schema (set by brain each tick)
        self._proprioceptive: Optional[object] = None
        # 16. Propositional belief store — (subject, relation, object, confidence)
        self.belief_store: BeliefStore = BeliefStore()
        # 17. Language producer — grammatical bilingual sentence generation
        self.lang: LanguageProducer = LanguageProducer()
        # 17b. Generative LLM adapter — replaces template tiers when enabled
        from llm_adapter import LLMAdapter

        self._llm_adapter: LLMAdapter = LLMAdapter()
        # 18. Query engine — direct question parsing + knowledge retrieval
        self.query_engine: QueryEngine = QueryEngine()
        # 19. Continuity monitor — self-continuity tracking + alarms
        self.continuity: ContinuityMonitor = ContinuityMonitor()
        # 20. Sensorimotor forward model — embodied agency confirmation
        self.sensorimotor: SensorimotorForwardModel = SensorimotorForwardModel()
        # 21. Deliberation queue — non-blocking response processing
        self._deliberation_queue: Deque[DeliberationTask] = deque(maxlen=20)
        # Reference to brain — set on first tick(), used by _evaluate_goal()
        # for semantic PFC goal selection. Not set in __init__ to avoid
        # circular import issues.
        self._brain_ref: Optional["Brain"] = None
        # Real executive outcomes consumed this tick (populated in tick())
        self._last_outcomes: list = []

        # ── Phase 1-5: New consciousness modules ────────────────────────────
        # 22. Causal graph — learns action→outcome associations
        self.causal_graph: CausalGraph = CausalGraph()
        # 23. Value model — TD(0) value function over discretised state
        self.value_model: ValueModel = ValueModel()
        # 24. Identity arc — directed character development (Albedo seed)
        self.identity_arc: IdentityArc = IdentityArc()
        # 25. Narrative thread — autobiographical chapter formation
        self.narrative_thread: NarrativeThread = NarrativeThread()
        # 26. Theory of mind — mental models of other agents
        self.theory_of_mind: TheoryOfMind = TheoryOfMind()
        # 27. Belief quarantine — evidence-gated belief management
        self.belief_quarantine: BeliefQuarantine = BeliefQuarantine()
        # 28. Attention controller — top-down attention bias
        self.attention_ctrl: AttentionController = AttentionController()
        # 29. Long-horizon goals — persistent multi-session goal tracking
        self.long_horizon: GoalStack = GoalStack()
        # 30. Active scene — hysteretic entity/relation binding for stable context
        self.active_scene: ActiveScene = ActiveScene()
        # Step events consumed this tick (populated in tick())
        self._last_step_events: list = []
        # Active epistemic investigations: entity → EpistemicInvestigation
        self._active_investigations: Dict[str, EpistemicInvestigation] = {}
        # General hypotheses: claim-string → GeneralHypothesis
        # Covers all domains beyond surprise-triggered orient investigations.
        self._hypotheses: Dict[str, GeneralHypothesis] = {}
        self._hypothesis_max: int = 200
        self._last_hyp_tick: int = 0
        # Social isolation counter: ticks without a known interlocutor
        self._social_isolation_ticks: int = 0
        # 36. Normative deliberation engine
        self.normative_eval: NormativeEvaluator = NormativeEvaluator()
        # Last counterfactual goal-selection record
        self._last_counterfactual: Optional[CounterfactualRecord] = None
        # Last decision reason (causal + epistemic + normative + phenomenal)
        self._last_decision_reason: Optional[Dict] = None
        self._last_decision_grounding: Dict[str, Any] = {}
        # Trait stability: rolling snapshot of agency/continuity/ownership for consistency tracking
        import collections as _coll

        self._trait_history: "_coll.deque[Dict[str, float]]" = _coll.deque(maxlen=50)
        # Skill/intent competence model — tracks success rates for self-knowledge gate
        self.capability_model: CapabilityModel = CapabilityModel()

        # ── Cross-wire: unified epistemic pipeline ──────────────────────
        # BeliefStore routes uncertain propositions through BeliefQuarantine
        self.belief_store._epistemic_gate = self.belief_quarantine

        # ── Phase 6: Unified consciousness architecture ─────────────────
        # 31. Unified self-state — coherent self-hypothesis from all sub-states
        self.unified_self: UnifiedSelfState = UnifiedSelfState()
        # 32. Grounded semantics — multi-modal concept frames
        self.grounded_memory: GroundedSemanticMemory = GroundedSemanticMemory()
        # 33. Phenomenal buffer — integrated experiential vector
