    def get_person_engine_state(self) -> Dict:
        """Return a copy of the current PersonEngine output_profile.

        Call this from dialogue_manager, speech_output, or any downstream
        system to obtain the current internal-state-coloured output parameters.

        Returns an empty dict if PersonEngine has not yet run its first tick.
        """
        return dict(self.person_engine.output_profile)

    # ─────────────────────────────────────────────────────────

    def _run_epistemic_discipline(self, brain: "Brain") -> None:
        """General-purpose epistemic discipline: track, test, and revise hypotheses.

        Called every 80 ticks.  Unlike the narrow surprise-investigation pipeline
        (which only fires on entity surprise > 0.4), this engine:
          1. Scans recent workspace concepts for uncertain belief triples not yet
             tracked as hypotheses — spawning a GeneralHypothesis for each.
          2. For open hypotheses, queries the BeliefStore for supporting and
             contradicting evidence and performs a Bayesian-ratio update.
          3. Settles hypotheses as confirmed (conf > 0.80), refuted (conf < 0.12),
             or suspended (too many attempts with no result).
          4. Records outcomes in the stream and episodic memory.
          5. Prunes the pool to stay within _hypothesis_max.
        """
        tick = getattr(brain, "tick_count", self._tick)

        # ── 1. Seed new hypotheses from recent uncertain beliefs ────────────
        _seed_concepts = list(self._concepts)[-60:]
        for _sc in _seed_concepts:
            if len(self._hypotheses) >= self._hypothesis_max:
                break
            try:
                _triples = self.belief_store.query_rich(_sc, min_confidence=0.0)
            except Exception:
                continue
            for _rel, _obj, _entry in _triples:
                if _entry.reliability >= 0.45:
                    continue  # already confident enough
                _claim = f"{_sc}.{_rel}.{_obj[:30]}"
                if _claim not in self._hypotheses:
                    self._hypotheses[_claim] = GeneralHypothesis(
                        claim=_claim,
                        domain="belief",
                        entity=_sc,
                        confidence=_entry.reliability,
                        created_tick=tick,
                        last_updated_tick=tick,
                    )

        # ── 2. Process up to 3 open hypotheses per call ─────────────────────
        _open = [(c, h) for c, h in self._hypotheses.items() if h.status == "open"]
        # Prioritise most uncertain (confidence closest to 0.5)
        _open.sort(key=lambda x: abs(x[1].confidence - 0.5))
        for _ep_claim, _hyp in _open[:3]:
            _hyp.test_attempts += 1
            _hyp.last_updated_tick = tick

            # Supporting evidence: confident triples about the same subject
            try:
                _for_raw = self.belief_store.query(_hyp.entity, min_confidence=0.50)
            except Exception:
                _for_raw = []
            _ev_for = [
                f"{r}:{o}"
                for r, o, _c in _for_raw
                if o.lower()[:20] in _ep_claim.lower() or r.lower() in _ep_claim.lower()
            ]

            # Contradicting evidence: triples with negating/opposing relations
            try:
                _against_raw = self.belief_store.query(_hyp.entity, min_confidence=0.0)
            except Exception:
                _against_raw = []
            _ev_against = [
                f"{r}:{o}"
                for r, o, _c in _against_raw
                if any(
                    _neg in r.lower()
                    for _neg in ("not_", "prevents", "opposes", "contradicts", "lacks")
                )
            ]
            # Beliefs registered as contradictions in the store
            try:
                for _cs, _cr, _co, _ce in self.belief_store.contradictions(min_count=1):
                    if _cs == _hyp.entity.lower():
                        _ev_against.append(f"contradiction:{_cr}:{_co}")
            except Exception:
                pass

            _hyp.evidence_for = (_hyp.evidence_for + _ev_for[:2])[-10:]
            _hyp.evidence_against = (_hyp.evidence_against + _ev_against[:2])[-10:]

            # Bayesian-ratio confidence update
            _n_for = len(_hyp.evidence_for)
            _n_against = len(_hyp.evidence_against)
            if _n_for + _n_against > 0:
                _ratio = _n_for / (_n_for + _n_against)
                _hyp.confidence = _hyp.confidence * 0.75 + _ratio * 0.25

            # ── 3. Settle hypothesis ──────────────────────────────────────
            _em_tag = (
                getattr(getattr(brain, "emotion_state", None), "dominant", lambda: "")()
                or ""
            )
            if _hyp.confidence > 0.80:
                _hyp.status = "confirmed"
                self.belief_store._store(
                    _hyp.entity,
                    "epistemic_confirmed",
                    _ep_claim[:50],
                    confidence=min(0.90, _hyp.confidence),
                    tick=tick,
                )
                self.stream.append(
                    f"[EPISTEMIC] Confirmed: {_ep_claim[:60]}"
                    f" conf={_hyp.confidence:.2f}"
                    f" ({_n_for}+ / {_n_against}-)"
                )
                self.episodic.record(
                    tick, "hypothesis_confirmed", f"confirmed:{_ep_claim[:60]}", _em_tag
                )
            elif _hyp.confidence < 0.12:
                _hyp.status = "refuted"
                self.stream.append(
                    f"[EPISTEMIC] Refuted: {_ep_claim[:60]}"
                    f" conf={_hyp.confidence:.2f}"
                    f" ({_n_for}+ / {_n_against}-)"
                )
                self.episodic.record(
                    tick, "hypothesis_refuted", f"refuted:{_ep_claim[:60]}", _em_tag
                )
            elif _hyp.test_attempts >= 12:
                _hyp.status = "suspended"
                self.stream.append(
                    f"[EPISTEMIC] Suspended: {_ep_claim[:60]}"
                    f" (inconclusive after {_hyp.test_attempts} attempts)"
                )

        # ── 4. Prune pool ────────────────────────────────────────────────────
        if len(self._hypotheses) > self._hypothesis_max:
            _closed = sorted(
                [(c, h) for c, h in self._hypotheses.items() if h.status != "open"],
                key=lambda x: x[1].last_updated_tick,
            )
            for _dc, _ in _closed[: len(_closed) // 2]:
                del self._hypotheses[_dc]

    # ─────────────────────────────────────────────────────────

    def tick(self, brain: "Brain") -> ConsciousnessState:
        """Main tick — call after all regions and emotion have updated."""
        self._tick += 1
        # Wire brain reference for semantic PFC goal selection
        self._brain_ref = brain

        # Salience decay — every concept fades unless re-bumped
        self._decay_salience()

        em: EmotionalState = brain.emotion_state  # type: ignore[attr-defined]
        state = ConsciousnessState(goal=self.state.goal)

        total = sum(brain.region_activity.values()) / max(len(brain.region_activity), 1)

        # Update rolling activity EMAs — gives reliable depth signal for concept
        # encoding even when instantaneous read would be 0 (propagation lag).
        _EMA = 0.08
        self._hipp_act_ema = (
            _EMA * brain.hippocampus.activity() + (1 - _EMA) * self._hipp_act_ema
        )
        self._pfc_act_ema = (
            _EMA * brain.prefrontal.activity() + (1 - _EMA) * self._pfc_act_ema
        )

        # ── 1. Global ignition check (salience-based) ───────────────
        # Fix 1: composite salience (activity + prediction error + emotion + goal)
        # Fix 10: focus with inertia — spotlight doesn't flip every tick
        salience = self._compute_salience(brain, em)
        state.salience_scores = salience
        if salience:
            top_region = max(salience, key=salience.get)
            top_sal = salience[top_region]
            if top_sal > IGNITION_THRESHOLD:
                # Inertia: 80% old focus, 20% new winner
                if self._current_focus and self._current_focus != top_region:
                    self._focus_salience = 0.8 * self._focus_salience + 0.2 * top_sal
                    # Switch focus only when new winner is sufficiently dominant
                    if top_sal > self._focus_salience * 1.1:
                        self._current_focus = top_region
                        self._focus_salience = top_sal
                else:
                    self._current_focus = top_region
                    self._focus_salience = 0.8 * self._focus_salience + 0.2 * top_sal
        state.focus_region = self._current_focus
        active_count = sum(1 for v in salience.values() if v >= IGNITION_THRESHOLD)
        state.ignition = active_count >= IGNITION_REGIONS
        if state.ignition:
            self._ignition_count += 1
            self._global_broadcast(brain)
            # Salience bump: ignition boosts all current workspace concepts
            for _c in list(self._concepts)[-12:]:
                self._bump_salience(_c, 0.5)

        # ── 1c. Temporal binding ──────────────────────────────────────────────
        # Update rolling window with the set of currently-active regions.
        # If binding_coherence ≥ 0.35 and ≥3 regions form a sustained coalition,
        # trigger a broadcast even when no single tick cleared IGNITION_REGIONS.
        # This implements temporal integration: sustained moderate activity ≡
        # brief intense burst for the purposes of global workspace access.
        _active_r_set = {r for r, v in salience.items() if v >= IGNITION_THRESHOLD}
        _tb_coh = self.temporal_binding.update(_active_r_set)
        if self.temporal_binding.is_temporally_bound() and not state.ignition:
            state.ignition = True
            self._ignition_count += 1
            self._global_broadcast(brain)
            if self._tick % 50 == 0:
                self.stream.append(
                    f"[TEMPORAL-BIND] coherence={_tb_coh:.2f} "
                    f"bound={','.join(sorted(self.temporal_binding.bound_regions)[:4])} "
                    f"→ sustained coalition triggers broadcast"
                )

        # ── 1b. Gateway: tick + register globally-accessible workspace concepts ──
        self.gateway.tick(brain.tick_count)
        self.integration_probe.observe(brain, brain.tick_count)
        self.metacog_calib.tick(brain.tick_count)

        # ── CASCADING STRUCTURAL DEGRADATION ─────────────────────────────────
        # Integration is the carrier of ALL processes, not a gate.
        # When phi drops below baseline → degrade coherence, goal stability,
        # self-model consistency proportionally.  This makes integration
        # structurally necessary — removal causes visible, measurable collapse.
        _phi_degrad = self.integration_probe.phi_degradation_level()
        if _phi_degrad > 0.05:
            import random as _rand

            # 1. Report coherence: inject noise phrases that contaminate the stream
            #    with proportional probability — reports become contradictory
            _noise_prob = _phi_degrad * 0.8
            if _rand.random() < _noise_prob and self._concepts:
                _nc = list(self._concepts)
                _noise_concept = _rand.choice(_nc) if _nc else "?"
                self.stream.append(
                    f"[INTEGRATION-NOISE φ_degrad={_phi_degrad:.2f}] "
                    f"stale / incoherent signal: '{_noise_concept}' — "
                    f"report reliability degraded"
                )
            # 2. Goal conflict: inject contradictory self-theses proportionally
            #    Goal system cannot resolve them → goal_conflict increases
            if _phi_degrad > 0.3 and self._tick % 20 == 0:
                import uuid as _uuid

                _conf = max(0.0, 0.5 - _phi_degrad * 0.5)
                self.self_model.self_contradictions.append(
                    f"[DEGRAD-tick{self._tick}] integration collapse "
                    f"makes self-report unreliable (φ_drop={_phi_degrad:.2f})"
                )
                # Cap contradictions list to prevent unbounded growth
                if len(self.self_model.self_contradictions) > 40:
                    self.self_model.self_contradictions.pop(0)
            # 3. Self-model drift: agency/continuity estimates degrade
            #    with integration collapse — system loses grip on itself
            if _phi_degrad > 0.15:
                _drift_rate = _phi_degrad * 0.04
                self.self_model.agency_confidence = max(
                    0.0, self.self_model.agency_confidence - _drift_rate
                )
                self.self_model.continuity_estimate = max(
                    0.0, self.self_model.continuity_estimate - _drift_rate * 0.7
                )
            # 4. Workspace concept eviction proportional to degradation
            #    Stable concepts (identity-core) are NEVER evicted; only
            #    transient concepts become inaccessible under degradation.
            if _phi_degrad > 0.5 and self._concepts:
                _evict_n = max(1, int(len(self._concepts) * (_phi_degrad - 0.5)))
                # Evict only from non-stable concepts
                _evict_candidates = [
                    c
                    for c in list(self._concepts)[:_evict_n]
                    if c not in self._stable_concepts
                ]
                _evicted_set = set(_evict_candidates)
                # deque has no discard — rebuild without the evicted items
                _remaining = [c for c in self._concepts if c not in _evicted_set]
                self._concepts.clear()
                self._concepts.extend(_remaining)
                for _c in _evicted_set:
                    self.gateway._workspace.pop(_c, None)

        # ── STABILIZATION LAYER ───────────────────────────────────────────────
        # Meta-stability controller computes phi-dependent weights for each force.
        # These weights modulate: attractor pull, persistent salience, concept drift.
        _phi_stab = self.integration_probe.phi_surrogate()
        _w_att, _w_per, _w_drift, _ms_mode = self.meta_stability.compute(_phi_stab)

        # Log mode transitions to stream (only on change, at most every 200 ticks)
        if (
            self.meta_stability.mode != getattr(self, "_last_ms_mode", "")
            and self._tick % 200 == 0
        ):
            self.stream.append(f"[META-STABILITY] {self.meta_stability.describe()}")
        self._last_ms_mode = _ms_mode

        # Attractor pull: scaled by w_attractor
        # phi high → strong pull toward baseline; phi low → weak pull, drift allowed
        _base_attractor = 0.04  # max pull rate per tick
        _attractor_strength = _base_attractor * _w_att
        _SM_ANCHOR_AGENCY = 0.50
        _SM_ANCHOR_CONT = 0.75
        _sm_stab = self.self_model
        _sm_stab.agency_confidence = max(
            0.05,
            min(
                0.95,
                _sm_stab.agency_confidence
                + _attractor_strength
                * (_SM_ANCHOR_AGENCY - _sm_stab.agency_confidence),
            ),
        )
        _sm_stab.continuity_estimate = max(
            0.05,
            min(
                0.95,
                _sm_stab.continuity_estimate
                + _attractor_strength
                * (_SM_ANCHOR_CONT - _sm_stab.continuity_estimate),
            ),
        )

        # ── DEVELOPMENTAL GRADIENT — momentum of the system's own history ──
        # Observe the current state (post-attractor) to measure how the system
        # has been moving.  Then apply gradient momentum scaled by w_drift so
        # that drift mode continues the trajectory and stable mode suppresses it.
        _sal_vals = list(self._concept_salience.values())
        _sal_mean = (sum(_sal_vals) / len(_sal_vals)) if _sal_vals else 0.0
        _cur_goal_mode = self._goal_mode(self.state.goal or "explore")
        self.dev_gradient.observe(
            _sm_stab.agency_confidence,
            _sm_stab.continuity_estimate,
            _sal_mean,
            _cur_goal_mode,
        )
        # Apply gradient: nudges self-model forward along its developmental axis
        _new_ag, _new_co = self.dev_gradient.apply(
            _sm_stab.agency_confidence,
            _sm_stab.continuity_estimate,
            _w_drift,
        )
        _sm_stab.agency_confidence = _new_ag
        _sm_stab.continuity_estimate = _new_co

        # Periodic stream log (every 500 ticks) so the gradient is observable
        if self._tick % 500 == 0:
            self.stream.append(f"[DEV-GRADIENT] {self.dev_gradient.describe()}")

        # ── TRAJECTORY COMPRESSION — narrative collapse ──────────────────────────
        _traj_log = self.traj_compressor.update(
            tick=self._tick,
            dev_grad=self.dev_gradient,
            stable_concepts=self._stable_concepts,
            concept_salience=self._concept_salience,
            goal_mode=_cur_goal_mode,
            agency=_sm_stab.agency_confidence,
            continuity=_sm_stab.continuity_estimate,
            ms_mode=_ms_mode,
        )
        if _traj_log:
            self.stream.append(_traj_log)
            self.self_model.self_narrative = self.traj_compressor.dominant_narrative

        # ── EMERGENT GOAL SYNTHESIS ───────────────────────────────────────────────
        # Novel goals emerge from homeostatic errors and compete with fixed goals.
        _body_eg = self.body
        _eg_out = self.emergent_goals.synthesize(
            tick=self._tick,
            energy=_body_eg.energy_reserve,
            integrity=_body_eg.integrity,
            thermal=_body_eg.thermal_load,
            phi=_phi_stab,
            narrative_coh=self.traj_compressor.narrative_coherence,
            concept_sal=self._concept_salience,
        )
        _existing_g_names = {g.name for g in self._goal_objects}
        for _eg_name, _eg_w in _eg_out.items():
            self._dynamic_goal_bias[_eg_name] = _eg_w
            if _eg_name not in _existing_g_names:
                self._goal_objects.append(
                    Goal(
                        name=_eg_name,
                        priority=_eg_w,
                        expected_reward=_eg_w * 0.6,
                        drive_key="homeostatic",
                    )
                )
                _existing_g_names.add(_eg_name)
        # Prune expired novel goals from _goal_objects (urgency below threshold)
        _live_novel = set(_eg_out.keys())
        self._goal_objects = [
            g
            for g in self._goal_objects
            if g.drive_key != "homeostatic" or g.name in _live_novel
        ]
        if _eg_out and self._tick % 100 == 0:
            _eg_top = max(_eg_out, key=_eg_out.get)
            self.stream.append(
                f"[EMERGENT-GOAL] '{_eg_top}' urgency={_eg_out[_eg_top]:.2f} "
                f"({len(_eg_out)} active novel goals)"
            )

        # ── INFERENTIAL SELF-ESTIMATOR ──────────────────────────────────────────
        # Self-model is inferred from proxy signals, not read directly.
        # agency_confidence and continuity_estimate become partly uncertain.
        _stable_cnt = len(self._stable_concepts)
        _total_sal = len(self._concept_salience)
        _stable_ratio = _stable_cnt / max(1, _total_sal)
        _mean_pe_est = getattr(brain, "_mean_pred_error", 0.10)
        self.self_estimator.update(
            motor_nonempty=bool(getattr(brain, "last_action", "")),
            mean_pred_error=_mean_pe_est,
            stable_ratio=_stable_ratio,
            phi=_phi_stab,
        )
        # 75 % estimator / 25 % prior direct value — self-model is now partly uncertain
        _sm_inf = self.self_model
        _sm_inf.agency_confidence = (
            0.75 * self.self_estimator.agency + 0.25 * _sm_inf.agency_confidence
        )
        _sm_inf.continuity_estimate = (
            0.75 * self.self_estimator.continuity + 0.25 * _sm_inf.continuity_estimate
        )
        if self.self_estimator.has_blind_spot and self._tick % 200 == 0:
            self.stream.append(
                f"[SELF-BLIND-SPOT] {self.self_estimator.describe()} "
                f"→ self-model uncertain, inferences unreliable"
            )

        # ── CONSEQUENCE FIELD — intrinsic semantics ───────────────────────────
        # Record hippocampal activation signature + current homeostatic state.
        # After HORIZON ticks, settle consequences and inject valence as direct
        # neural current into the amygdala — no label, no symbol.
        _hipp_fired_ids = [
            brain.hippocampus._exc_cache[k].nid
            for k, pos in enumerate(brain.hippocampus._exc_positions)
            if brain.hippocampus._fired_this_tick[pos]
        ][: self.consequence_field._TOP_K * 2]
        self.consequence_field.record(
            self._tick,
            _hipp_fired_ids,
            energy=self.body.energy_reserve,
            integrity=self.body.integrity,
            phi=_phi_stab,
        )
        _cf_valence = self.consequence_field.settle(
            self._tick,
            energy=self.body.energy_reserve,
            integrity=self.body.integrity,
            phi=_phi_stab,
        )
        if _cf_valence is not None and len(brain.amygdala.excitatory) > 0:
            _amyg_n = len(brain.amygdala.excitatory)
            if _cf_valence > 0.05:
                # Reward-valence: excitatory boost → curiosity/explore
                _k_cf = min(30, _amyg_n // 4)
                brain.amygdala.inject(
                    [_cf_valence * 8.0] * _k_cf + [0.0] * (_amyg_n - _k_cf)
                )
            elif _cf_valence < -0.05:
                # Threat-valence: strong excitatory burst (threat signal)
                _k_cf = min(50, _amyg_n // 3)
                brain.amygdala.inject(
                    [abs(_cf_valence) * 14.0] * _k_cf + [0.0] * (_amyg_n - _k_cf)
                )
        # Current valence for goal attractor field
        _cur_cf_val = self.consequence_field.valence(_hipp_fired_ids[:20])

        # ── GOAL ATTRACTOR FIELD — emergent goal dynamics ─────────────────────
        # Update attractor field with current state vector.
        # The winning attractor's gradient modulates tonic and LTP directly.
        self.goal_attractors.update(
            tick=self._tick,
            energy=self.body.energy_reserve,
            integrity=self.body.integrity,
            phi=_phi_stab,
            agency=_sm_inf.agency_confidence,
            continuity=_sm_inf.continuity_estimate,
            mean_pe=getattr(brain, "_mean_pred_error", 0.10),
        )
        # Attractor tonic modulation: applied to global tonic this tick
        _att_tonic_delta = self.goal_attractors.tonic_modulation()
        if abs(_att_tonic_delta) > 0.05:
            from neuron import Neuron as _Natt

            _Natt.global_tonic_current = max(
                3.0, min(18.0, _Natt.global_tonic_current + _att_tonic_delta * 0.15)
            )
        # LTP modulation from tension
        try:
            import neuron as _nmod_att

            _ltp_att = self.goal_attractors.ltp_modulation()
            _nmod_att.A_PLUS = max(
                0.003, min(0.055, _nmod_att.A_PLUS * (1 + (_ltp_att - 1.0) * 0.05))
            )
        except Exception:
            pass
        if self._tick % 150 == 0:
            self.stream.append(
                f"[ATTRACTOR] dominant={self.goal_attractors.dominant_label} "
                f"tension={self.goal_attractors.total_tension:.2f} "
                f"tonic_Δ={_att_tonic_delta:+.2f}"
            )

        # ── ATTRACTOR DOMINANCE — winner-take-all region suppression ─────────
        # When one attractor holds > WTA_THRESHOLD fraction of total strength,
        # it clamps competing regions and permanently decays competing urgencies.
        # Once locked, the system cannot easily transition to another goal state.
        self.attractor_dom.apply(self.goal_attractors, brain)
        if self.attractor_dom.locked and self._tick % 200 == 0:
            self.stream.append(
                f"[WTA-LOCKED] dominant={self.attractor_dom.dominant_label} "
                f"wta={self.attractor_dom.wta_strength:.2f} "
                f"lock_ticks={self.attractor_dom.lock_ticks}"
            )

        # ── TRAJECTORY COST — future instability as meaning ───────────────────
        # Roll current state forward H steps; cost = discounted tension integral.
        # High cost → current trajectory is diverging; goals that stabilize are
        # relatively favored in _evaluate_goal().
        self.traj_cost_est.estimate(
            self.goal_attractors,
            energy=self.body.energy_reserve,
            integrity=self.body.integrity,
            phi=_phi_stab,
            agency=_sm_inf.agency_confidence,
            continuity=_sm_inf.continuity_estimate,
        )
        if self._tick % 200 == 0 and self.traj_cost_est.trajectory_cost > 0.3:
            self.stream.append(
                f"[TRAJ-COST] cost={self.traj_cost_est.trajectory_cost:.3f} "
                f"var={self.traj_cost_est.future_variance:.3f} "
                f"→ future instability detected"
            )

        # ── SELF-HYPOTHESIS SET — competing self-models with drift ────────────
        _actual_pe = getattr(brain, "_mean_pred_error", 0.10)
        self.self_hypothesis.update(_actual_pe)
        # Blend hypothesis output into self_model (partially overrides estimator blend)
        _sh_blend = 0.35  # hypothesis influence fraction
        _sm_inf.agency_confidence = (
            (1 - _sh_blend) * _sm_inf.agency_confidence
            + _sh_blend * self.self_hypothesis.agency_estimate
        )
        _sm_inf.continuity_estimate = (
            (1 - _sh_blend) * _sm_inf.continuity_estimate
            + _sh_blend * self.self_hypothesis.continuity_estimate
        )
        if self.self_hypothesis.contradicted:
            # Inject contradiction into self_contradictions list
            _contra_msg = (
                f"[SELF-CONTRADICTION t={self._tick}] "
                f"{self.self_hypothesis.describe()}"
            )
            _existing = self.self_model.self_contradictions
            if not _existing or _existing[-1] != _contra_msg:
                _existing.append(_contra_msg)
                if len(_existing) > 40:
                    _existing.pop(0)
            if self._tick % 300 == 0:
                self.stream.append(_contra_msg)

        # Drift mode: inject small noise into stable concepts so they are not frozen
        # This prevents the system from locking into a static identity under low phi
        if _ms_mode == "drift" and self._stable_concepts and self._tick % 5 == 0:
            import random as _rnd_ms

            _jitter_c = _rnd_ms.choice(list(self._stable_concepts))
            # Slightly bumping a random stable concept re-activates it
            self._bump_salience(_jitter_c, _rnd_ms.gauss(0, 0.15))

        # ── Phase 5: Self-organization vs. Self-decay ─────────────────────────
        # Build region activity dict from brain's named regions
        _p5_region_acts: Dict[str, float] = {}
        _p5_brain_rgns: Dict[str, object] = {}
        for _p5_name in (
            "pfc",
            "prefrontal",
            "hippocampus",
            "amygdala",
            "assoc",
            "motor",
            "sensory_v",
            "sensory_a",
            "sensory_w",
            "thalamus",
            "visual",
            "auditory",
        ):
            _p5_r = getattr(brain, _p5_name, None)
            if _p5_r is not None:
                _p5_region_acts[_p5_name] = (
                    _p5_r.activity() if hasattr(_p5_r, "activity") else 0.0
                )
                _p5_brain_rgns[_p5_name] = _p5_r
        _p5_body = getattr(brain, "_body_hardware", None) or self.body

        # 55. CohesionEngine — active synchrony, coalition formation, energy cost
        for _cm in self.cohesion.update(_p5_region_acts, _p5_body, _p5_brain_rgns):
            self.stream.append(_cm)

        # 56. DisintegrationField — noise floor growth, connection drift, coord entropy
        for _dm in self.disintegration.update(
            _p5_region_acts, _p5_brain_rgns, getattr(brain, "_inter_synapses", [])
        ):
            self.stream.append(_dm)

        # 57. OrderChaosCoupling — superlinear order cost, chaos energy relief
        for _ocm in self.order_chaos.update(
            self.cohesion.coherence_score,
            self.disintegration.coordination_entropy,
            _p5_body,
        ):
            self.stream.append(_ocm)

        # 58. MultipleSelfStates — competing identity hypotheses
        _p5_energy = getattr(_p5_body, "energy_reserve", 0.5)
        _p5_integrity = getattr(_p5_body, "integrity", 0.5)
        _p5_cascade = getattr(getattr(brain, "_cascade", None), "cascading", False)
        # Save scores from previous tick for recurrent coupling
        _ss_prev_scores = dict(self.self_states._scores)
        for _ssm in self.self_states.update(
            energy=_p5_energy,
            cascade_active=_p5_cascade,
            integrity=_p5_integrity,
            coordination_entropy=self.disintegration.coordination_entropy,
            last_action=getattr(brain, "last_action", "idle"),
        ):
            self.stream.append(_ssm)
        # Apply recurrent identity loop: agent → observer → diffuse → agent
        self.self_states.apply_recurrent_coupling(_ss_prev_scores)

        # ── Phase 6: Recursive Self-Closure ──────────────────────────────────

        # 59. LocalCoherenceFragments — competing sub-coherences
        # Split global coherence into N=4 clusters; fragments compete for energy;
        # collapses produce traces for DecaySemanticTrace.
        _p6_concepts = list(self._concepts)[-30:] if self._concepts else []
        for _lfm in self.local_frags.update(
            region_acts=_p5_region_acts, body=_p5_body, concepts=_p6_concepts
        ):
            self.stream.append(_lfm)

        # 60. DecaySemanticTrace — ingest new collapse traces + update ghost memory
        # Ghost concepts bias salience; fragment attractor from overlap; decay breeds decay.
        self.decay_traces.ingest_traces(self.local_frags.collapsed_traces)
        for _dtm in self.decay_traces.update(
            active_concepts=_p6_concepts,
            disintegration=self.disintegration,
            frag_coherences=self.local_frags.frag_coherences,
        ):
            self.stream.append(_dtm)

        # Apply ghost concept salience priors to workspace
        for _gc, _prior in self.decay_traces.concept_priors.items():
            if _prior > 0.05:
                self._bump_salience(_gc, _prior)

        # 61. RecursiveSelfState — substrate projection → SelfModel overwrite
        # Every call perturbs the regions it reads from (observation-perturbs-measured).
        self.recursive_self.project(
            cohesion=self.cohesion,
            disintegration=self.disintegration,
            self_states=self.self_states,
            brain=brain,
            brain_regions=_p5_brain_rgns,
            self_model=self.self_model,
        )

        # ── Phase 7: Persona Engine ───────────────────────────────────────────

        # Snapshot SelfModel BEFORE subsystems can change it further
        self.ctrl_plasticity.snapshot(self.self_model)

        # 62 + 63. PersonalityCore — derive behavioral evidence and update
        _p7_action = getattr(brain, "last_action", "idle")
        _p7_energy = getattr(_p5_body, "energy_reserve", 0.5)
        _p7_cascade = getattr(getattr(brain, "_cascade", None), "cascading", False)
        _p7_surprise = getattr(
            getattr(brain, "_latent_world", None), "obs_surprise", 0.0
        )
        _p7_sm_ref = getattr(brain, "_social_manager", None)

        # Track goal persistence for personality
        _p7_cur_mode = self._goal_mode(state.goal or "idle") if state else "idle"
        if _p7_cur_mode == self._last_goal_mode:
            self._goal_held_ticks += 1
        else:
            self._goal_held_ticks = 0
            self._last_goal_mode = _p7_cur_mode

        # SocialConsistencyEngine: update person models, get social feedback
        _p7_emotion_valence = (
            getattr(getattr(self, "emotion", None), "valence", 0.0)
            if hasattr(self, "emotion")
            else 0.0
        )
        # Try to get emotion valence from body / emotion state
        _p7_ev_src = getattr(_p5_body, "valence", None)
        if _p7_ev_src is None:
            _p7_ev_src = (
                getattr(getattr(brain, "amygdala", None), "_tonic_valence", 0.0)
                if hasattr(brain, "amygdala")
                else 0.0
            )
        _p7_emotion_valence = float(_p7_ev_src or 0.0)

        for _scm in self.social_sce.update(
            tick=self._tick,
            social_manager=_p7_sm_ref,
            emotion_valence=_p7_emotion_valence,
            last_action=_p7_action,
        ):
            self.stream.append(_scm)

        # Mirror current → amygdala injection (attenuated emotional resonance)
        if abs(self.social_sce.mirror_current) > 0.05:
            _an = len(brain.amygdala.excitatory)
            _mc = self.social_sce.mirror_current
            brain.amygdala.inject([_mc] * min(_an, 12) + [0.0] * max(0, _an - 12))

        # Build personality evidence and update
        _p7_ev = self.personality.build_evidence_from_tick(
            last_action=_p7_action,
            energy=_p7_energy,
            cascade=_p7_cascade,
            social_feedback=self.social_sce.social_feedback,
            surprise=_p7_surprise,
            goal_held_ticks=self._goal_held_ticks,
        )
        self.personality.update(_p7_ev)

        # 64. IdentityLayerStack — record behavior, update narrative convergence
        self.identity_stack.record_behavior(
            action=_p7_action,
            mean_act=_mean_act,
            goal=_p7_cur_mode,
        )
        for _ilm in self.identity_stack.update(
            self_model=self.self_model, personality=self.personality, tick=self._tick
        ):
            self.stream.append(_ilm)

        # 65. UnifiedAutobiographicalMemory — record atom this tick
        _p7_phi = getattr(state, "phi", 0.0) if state else 0.0
        _p7_ign = getattr(state, "ignition", False) if state else False
        _p7_pe = getattr(brain, "_mean_pred_error", 0.0)
        _p7_ntag = ""
        if _p7_cascade:
            _p7_ntag = "cascade"
        elif _p7_ign:
            _p7_ntag = "ignition"
        elif self._goal_held_ticks == 0:
            _p7_ntag = "goal_shift"
        self.auto_memory.record_atom(
            tick=self._tick,
            concepts=list(self._concepts)[-10:],
            valence=_p7_emotion_valence,
            phi=_p7_phi,
            ignition=_p7_ign,
            pred_error=_p7_pe,
            narrative_tag=_p7_ntag,
        )
        for _amm in self.auto_memory.update(self._tick, self.personality):
            self.stream.append(_amm)

        # 66 + 67. ControlledPlasticity + SelfConsistencyConstraint
        # Clamp SelfModel fields that changed too fast
        self.ctrl_plasticity.constrain(self.self_model, self.personality)

        # Compute consistency and potential rollback
        _p7_frag = getattr(self.self_states, "fragmentation_index", 0.0)
        _p7_lyap = getattr(getattr(brain, "_edge_chaos", None), "lyapunov_proxy", 0.30)
        self.self_consist.update(
            self_model=self.self_model,
            frag_index=_p7_frag,
            lyap_proxy=min(1.0, _p7_lyap / 2.0),
        )
        # Rollback only applied if crisis; final_scores not available here —
        # rollback is called from _evaluate_goal() where scores are live.

        # ── Phase 8: Embodied Agency Layer ───────────────────────────────────

        # Get embodied state: proprioception + world state
        _p8_schema = getattr(brain, "_body_schema", None)
        _p8_prop = None
        if _p8_schema is not None:
            try:
                _p8_prop = _p8_schema.proprioceptive_snapshot()
            except Exception:
                _p8_prop = None
        _p8_world = getattr(brain, "_world_state", None)

        # 68. EmbodiedSensorField — body-bound, noisy, delayed perception
        for _esf_m in self.sensor_field.update(
            proprioception=_p8_prop,
            world_state=_p8_world,
            cascade=_p7_cascade,
            last_action=_p7_action,
            tick=self._tick,
        ):
            self.stream.append(_esf_m)

        # 69. ActionConsequenceTracer — every action has costs + side effects
        for _act_m in self.action_tracer.update(
            action=_p7_action, tick=self._tick, body=_p5_body, world=_p8_world
        ):
            self.stream.append(_act_m)
        # Apply energy debt to body if supported
        if (
            hasattr(_p5_body, "energy_reserve")
            and self.action_tracer.total_energy_debt > 0
        ):
            _p5_body.energy_reserve = max(
                0.0,
                min(
                    1.0, _p5_body.energy_reserve - self.action_tracer.total_energy_debt
                ),
            )

        # 70. SelfAsActionTrace — identity from action history (primary embodied source)
        _p8_at_ev = self.action_identity.update(
            action=_p7_action,
            tick=self._tick,
            outcome_score=self.emergent_stability.action_success_ema,
        )
        # Feed action-history evidence into PersonalityCore
        self.personality.update(_p8_at_ev)

        # 71. DynamicWorldReactor — world evolves autonomously
        for _dwr_m in self.world_reactor.update(
            world_state=_p8_world, last_action=_p7_action, tick=self._tick
        ):
            self.stream.append(_dwr_m)

        # 72. PhysioSocialCoupler — social feedback has physical consequences
        for _psc_m in self.physio_social.update(
            social_engine=self.social_sce, tick=self._tick
        ):
            self.stream.append(_psc_m)
        # Apply social energy delta to body
        if hasattr(_p5_body, "energy_reserve"):
            _p5_body.energy_reserve = max(
                0.0,
                min(
                    1.0,
                    _p5_body.energy_reserve + self.physio_social.social_energy_delta,
                ),
            )

        # 73. ClosedLoopPerceptionAction — track cycle closure
        self.perception_loop.update(
            sensor_updated=self.sensor_field.sensor_updated_this_tick,
            action=_p7_action,
            world_changed=self.world_reactor.world_state_delta > 0.05,
            tick=self._tick,
        )

        # 74. EmergentStabilityField — stability from action success chains
        _p8_task_exec = getattr(brain, "_task_executive", None)
        _p8_act_ok = getattr(_p8_task_exec, "last_action_success", None)
        _p8_world_pred = max(0.0, 1.0 - self.sensor_field.effective_surprise)
        self.emergent_stability.update(
            action_succeeded=_p8_act_ok,
            loop_closure_score=self.perception_loop.loop_closure_score,
            world_predictability=_p8_world_pred,
            self_model=self.self_model,
        )

        # ── Phase 9: Unified Person Integration Layer (UPCL) ─────────────────
        # Collect proposals from all proposal-layer subsystems
        _p9_proposals: Dict[str, Dict[str, float]] = {
            "personality": dict(self.personality.goal_bias),
            "action_trace": dict(self.action_identity.action_goal_bias),
            "social": dict(self.physio_social.social_goal_bias),
            "temporal": dict(self.tcf.long_term_goal_bias),
        }

        # 76. PersistentIdentityIntegrator — slow-drift 6D identity
        self.identity_integrator.update(
            action_evidence=self.action_identity.action_identity_vec,
            social_feedback=self.social_sce.social_feedback,
            emotion_valence=_p7_emotion_valence,
            world_autonomy=self.world_reactor.world_autonomy_index,
            loop_closure=self.perception_loop.loop_closure_score,
            tick=self._tick,
        )

        # 77. TemporalCoherenceField — record + recompute long-horizon coherence
        self.tcf.update(
            goal_mode=_p7_cur_mode,
            identity_vec=self.identity_integrator.identity_vector,
            tick=self._tick,
        )

        # 78. IdentityStabilityField — compute stability force
        self.isf.update(
            identity_vec=self.identity_integrator.identity_vector,
            pii_drift_rate=self.identity_integrator.drift_rate,
            layer_divergence=self.identity_stack.inconsistency_score,
        )

        # 79. ConflictResolutionEngine — resolve conflicts before arbitration
        for _crm in self.conflict_resolver.resolve(
            proposals=_p9_proposals,
            identity_vec=self.identity_integrator.identity_vector,
            stability_force=self.isf.stability_force,
            self_model=self.self_model,
            stream=self.stream,
        ):
            self.stream.append(_crm)

        # 75. UnifiedConstraintCore — arbitrate all resolved proposals
        self.ucc.arbitrate(
            proposals=_p9_proposals,
            energy=_p7_energy,
            identity_drift=self.identity_integrator.drift_rate,
            social_fb=self.social_sce.social_feedback,
            coherence=self.tcf.coherence_score,
            stability_force=self.isf.stability_force,
            loop_closure=self.perception_loop.loop_closure_score,
            tick=self._tick,
            stream=self.stream,
        )

        # ── Phase 10: Autonomous Life Dynamics (SAD-Layer) ───────────────────

        # 80. HomeostaticSurvivalCore — vital pressure check
        self.hsc.update(
            energy=_p7_energy,
            identity_inertia=self.identity_integrator.inertia,
            loop_closure=self.perception_loop.loop_closure_score,
            sensor_fov=self.sensor_field.sensor_fov,
            social_fb=self.social_sce.social_feedback,
            stream=self.stream,
        )

        # 81. GoalEvolutionEngine — evolve the goal pool
        _p10_outcome = self.emergent_stability.action_success_ema
        self.gee.update(
            last_goal_mode=_p7_cur_mode,
            outcome_score=_p10_outcome,
            tick=self._tick,
        )

        # 82. HorizonDominanceController — track multi-scale outcome trends
        self.hdc.update(
            outcome_score=_p10_outcome,
            tick=self._tick,
        )

        # 84. EntropicDriftLayer — apply natural decay to concepts + goals + identity
        for _edl_m in self.entropic_drift.update(
            concepts=self._concepts,
            concept_salience=self._concept_salience,
            last_goal_mode=_p7_cur_mode,
            identity_integrator=self.identity_integrator,
            tick=self._tick,
        ):
            self.stream.append(_edl_m)

        # 85. AdaptiveIdentityEvolution — reorganize identity as living process
        for _aie_m in self.identity_evolution.update(
            action_coherence=self.action_identity.coherence_from_action,
            entropy_level=self.entropic_drift.entropy_level,
            existential_pressure=self.hsc.existential_pressure,
            social_fb=self.social_sce.social_feedback,
            world_coupling=self.perception_loop.action_world_coupling,
            identity_integrator=self.identity_integrator,
            tick=self._tick,
        ):
            self.stream.append(_aie_m)

        # 83. ControlledSelfModification — rule-bounded param tuning
        self.self_mod.update(
            existential_pressure=self.hsc.existential_pressure,
            stability_force=self.isf.stability_force,
            horizon_health=self.hdc.horizon_health,
            horizon_controller=self.hdc,
            entropy_level=self.entropic_drift.entropy_level,
            stream=self.stream,
        )
        self.self_mod.apply_scales(
            personality=self.personality,
            sensor_field=self.sensor_field,
            social_sce=self.social_sce,
            identity_integrator=self.identity_integrator,
        )

        # ── Phase 11: Long-Term Stability & Identity Consolidation ────────────
        _p11_tick = brain.tick_count

        # Collect Phase-10 stability signals for Phase 11
        _p11_entropy = getattr(
            self.entropic_drift,
            "entropy_level",
            getattr(self.entropic_drift, "_entropy", 0.40),
        )
        _p11_act_suc = getattr(self.emergent_stability, "action_success_ema", 0.60)
        _p11_horiz_h = getattr(self.hdc, "horizon_health", 0.60)
        _p11_frag = getattr(self.isf, "component_variance", 0.10)

        # 1. FailureDetectionCore
        self.failure_detector.update(
            identity_fragmentation=_p11_frag,
            entropy_level=_p11_entropy,
            goal_churn_rate=self.goal_regulator.churn_rate,
            action_success_ema=_p11_act_suc,
            horizon_health=_p11_horiz_h,
            stream=self.stream,
        )
        _p11_fds_state = self.failure_detector.state

        # 2. RecoveryProtocolEngine
        self.recovery_engine.update(
            fds_state=_p11_fds_state,
            gee=self.gee,
            identity_anchor=self.identity_anchor,
            identity_integrator=self.identity_integrator,
            entropic_drift=self.entropic_drift,
            sensor_field=self.sensor_field,
            stream=self.stream,
        )

        # 3. IdentityAnchorField — save snapshot when system is healthy
        _p11_pii_vec = dict(
            zip(PersistentIdentityIntegrator._DIMS, self.identity_integrator._vec)
        )
        _p11_coh = getattr(self.tcf, "coherence_score", 0.60)
        _p11_chain_len = self.goal_regulator.goal_duration
        self.identity_anchor.try_save(
            identity_vec=_p11_pii_vec,
            coherence=_p11_coh,
            entropy=_p11_entropy,
            goal_chain_len=_p11_chain_len,
            tick=_p11_tick,
        )

        # 4. PersonalityConsolidator — reinforce stable trait patterns
        _p11_traits = dict(zip(PersonalityCore._DIMS, self.personality._vec))
        self.trait_consolidator.update(
            traits=_p11_traits,
            personality=self.personality,
        )

        # 5. DamageLedger + CompensationMechanism
        self.damage_ledger.update(
            brain=brain,
            fds_state=_p11_fds_state,
            identity_anchor=self.identity_anchor,
            action_success=_p11_act_suc,
            tick=_p11_tick,
        )

        # 6. GoalStabilityRegulator — gate goal-mode switching
        _p11_raw_mode = self._goal_mode(state.goal or "explore")
        _p11_allowed_mode = self.goal_regulator.update(
            candidate_mode=_p11_raw_mode,
            tick=_p11_tick,
            stream=self.stream,
        )

        # 7. NarrativeCompressionEngine
        self.narrative_compress.update(
            autobio_mem=self.auto_memory,
            personality_consolidator=self.trait_consolidator,
            tick=_p11_tick,
        )

        # 8. StabilityExplorerBalancer
        self.stab_explorer.update(
            emergent_stability=_p11_act_suc,
            instability_index=self.failure_detector.instability_index,
        )
        # ── End Phase 11 tick block ───────────────────────────────────────────

        # ── Phase 12: Person Engine tick ──────────────────────────────────────
        _p12_energy = 1.0 - self.hsc.pressures.get("energy_stability", 0.40)
        _p12_social = self.social_sce.social_feedback
        _p12_mem_sal = sum(
            a["salience"] for a in list(self.auto_memory._buf)[-20:]
        ) / max(1, min(20, len(self.auto_memory._buf)))
        self.person_engine.update(
            goal_scores=getattr(self, "_last_goal_scores", {}),
            energy_raw=_p12_energy,
            entropy_level=_p11_entropy,
            fragmentation=_p11_frag,
            social_trust_avg=_p12_social,
            autobio_salience=_p12_mem_sal,
            fds_state=_p11_fds_state,
            stability_force=getattr(self.isf, "stability_force", 0.0),
            stream=self.stream,
        )
        # ── End Phase 12 tick block ───────────────────────────────────────────

        # ── Phase 13: Recursive Internal Dynamics ────────────────────────────
        _p13_tick = brain.tick_count

        # Build raw state dict from current live signals
        _p13_raw_state: Dict[str, float] = {
            "tension": self.person_engine.goal_tension_field.tension_score,
            "entropy": _p11_entropy,
            "fragmentation": _p11_frag,
            "energy": max(0.0, 1.0 - self.hsc.existential_pressure),
            "social": self.social_sce.social_feedback,
            "damage": self.damage_ledger.damage_index,
        }

        # 1. Delayed consequences — apply any queued effects arriving this tick
        _p13_delayed = self.delay_buffer.apply(_p13_tick)
        if _p13_delayed:
            for _eff, _mag in _p13_delayed.items():
                _dim = _eff.replace("_delta", "")
                if _dim in _p13_raw_state:
                    _p13_raw_state[_dim] = max(
                        0.0, min(1.0, _p13_raw_state[_dim] + _mag)
                    )

        # 2. RecursiveFeedbackEngine — amplify / dampen cross-dimension
        _p13_prev_amp = (
            dict(self._p13_prev_amp_state)
            if self._p13_prev_amp_state
            else dict(_p13_raw_state)
        )
        _p13_amp = self.recursive_feedback.update(_p13_raw_state)
        self._p13_prev_amp_state = dict(_p13_amp)

        # Feed delayed consequences from amplification runaway events
        if self.recursive_feedback.runaway_active:
            # Runaway → queue a future tension spike and entropy surge
            self.delay_buffer.enqueue("tension_delta", +0.08, _p13_tick, delay=6)
            self.delay_buffer.enqueue("entropy_delta", +0.05, _p13_tick, delay=10)
            self.delay_buffer.enqueue("fragmentation_delta", +0.04, _p13_tick, delay=14)

        # 3. SelfMisalignmentTracker — compare self-model estimates to actuals
        _p13_estimates = dict(self.person_engine.self_hypothesizer.estimates)
        _p13_actuals = {
            "energy": _p13_amp["energy"],
            "stability": max(0.0, 1.0 - _p13_amp["fragmentation"]),
            "social": _p13_amp["social"],
            "goal_clarity": 1.0 - _p13_amp["tension"],
        }
        self.self_misalign.update(_p13_estimates, _p13_actuals)

        # 4. BehavioralInertiaField — momentum on current goal mode
        _p13_desired_mode = self.goal_regulator.allowed_goal_mode
        self.behav_inertia.update(_p13_desired_mode, self.stream)

        # 5. PhaseShiftDetector — detect sudden multi-dim phase transitions
        self.phase_shift_det.update(
            state_dims=_p13_amp,
            prev_dims=_p13_prev_amp,
            stream=self.stream,
        )

        # Inject phase-shift-induced delayed damage when shift occurs
        if (
            self.phase_shift_det.in_reorganization
            and self.phase_shift_det._reorg_remaining
            == self.phase_shift_det._REORG_DURATION - 1
        ):
            _shift_mag = self.phase_shift_det.shift_magnitude
            self.delay_buffer.enqueue(
                "damage_delta", +_shift_mag * 0.15, _p13_tick, delay=20
            )
            self.delay_buffer.enqueue(
                "energy_delta", -_shift_mag * 0.12, _p13_tick, delay=8
            )

        # Publish Phase 13 metrics into person_engine profile for downstream use
        self.person_engine.output_profile["p13_misalignment"] = (
            self.self_misalign.misalignment_score
        )
        self.person_engine.output_profile["p13_inertia"] = (
            self.behav_inertia.inertia_level
        )
        self.person_engine.output_profile["p13_tension_amp"] = _p13_amp["tension"]
        self.person_engine.output_profile["p13_reorg_noise"] = (
            self.phase_shift_det.reorganization_noise
        )
        self.person_engine.output_profile["p13_overreact"] = (
            self.behav_inertia.overreaction_pending
        )
        self.person_engine.output_profile["p13_runaway"] = (
            self.recursive_feedback.runaway_active
        )
        # ── End Phase 13 tick block ───────────────────────────────────────────

        # ── Phase 14: Self-Deception, Personas, Narrative Distortion ─────────
        _p14_tick = brain.tick_count

        # Signals needed by Phase 14 (from Phase 13 amplified state)
        _p14_amp = self._p13_prev_amp_state  # latest amplified state dict
        _p14_act_suc = _p11_act_suc  # action success EMA
        _p14_social = self.social_sce.social_feedback
        _p14_damage = self.damage_ledger.damage_index
        _p14_energy = _p14_amp.get("energy", 0.60)
        _p14_stab = max(0.0, 1.0 - _p14_amp.get("fragmentation", 0.10))

        # 1. BiasedBeliefLayer — domain-specific self-view distortion
        _p14_actual_signals = {
            "competence": _p14_act_suc,
            "social_standing": _p14_social,
            "intentionality": 1.0 - _p14_amp.get("tension", 0.30),
            "emotional_tone": _p14_stab,
        }
        self.biased_beliefs.update(
            actual_signals=_p14_actual_signals,
            success_signal=_p14_act_suc,
            social_signal=_p14_social,
            fds_state=_p11_fds_state,
        )

        # 2. PersonaSelector — context-driven persona emergence
        _p14_threat = self.failure_detector.instability_index
        _p14_past_rej = max(0.0, 1.0 - _p14_social) * (1.0 - _p14_act_suc)
        _p14_comp_belief = self.biased_beliefs.biased_self_view.get("competence", 0.55)
        self.persona_sel.update(
            social_trust=_p14_social,
            energy=_p14_energy,
            stability=_p14_stab,
            threat_level=_p14_threat,
            past_rejection=_p14_past_rej,
            success_rate=_p14_act_suc,
            competence_belief=_p14_comp_belief,
            damage_index=_p14_damage,
            stream=self.stream,
        )

        # 3. NarrativeDistortionEngine — biased reconstructive memory
        self.narr_distort.update(
            autobio_mem=self.auto_memory,
            active_persona=self.persona_sel.active_persona,
            biased_self_view=self.biased_beliefs.biased_self_view,
            tick=_p14_tick,
        )

        # 4. BeliefConflictResolver — three-layer arbitration
        _p14_model_estimates = dict(self.person_engine.self_hypothesizer.estimates)
        self.belief_conflict.update(
            actual_p13=_p14_amp,
            self_model_estimates=_p14_model_estimates,
            biased_belief=self.biased_beliefs,
            stream=self.stream,
        )

        # Publish Phase 14 metrics into output_profile
        _p14_profile = self.person_engine.output_profile
        _p14_profile["p14_persona"] = self.persona_sel.active_persona
        _p14_profile["p14_bias_magnitude"] = self.biased_beliefs.net_bias_magnitude
        _p14_profile["p14_conflict_score"] = self.belief_conflict.conflict_score
        _p14_profile["p14_belief_driver"] = self.belief_conflict.belief_dominance
        _p14_profile["p14_rationalize"] = self.belief_conflict.rationalization_active
        _p14_profile["p14_distortion"] = self.narr_distort.distortion_magnitude
        _p14_profile["p14_comp_belief"] = _p14_comp_belief
        _p14_profile["p14_biased_view"] = dict(self.biased_beliefs.biased_self_view)

        # Override BehavioralOutputGate tone with persona suggestion when belief dominates
        if self.belief_conflict.belief_dominance == "belief":
            _p14_profile["tone"] = self.persona_sel.persona_tone_bias
        # ── End Phase 14 tick block ───────────────────────────────────────────

        # ── Phase 15: Social Masks ────────────────────────────────────────────
        _p15_tick = brain.tick_count

        # Active agent from SocialConsistencyEngine
        _p15_agent = self.social_sce.active_person_id or "default"
        _p15_persona = self.persona_sel.active_persona
        _p15_pressure = self.failure_detector.instability_index
        _p15_act_suc = _p11_act_suc
        _p15_comp_bel = self.biased_beliefs.biased_self_view.get("competence", 0.55)

        # 1. ReputationMemory — update per-agent trust/predictability/alignment
        #    outcome proxy: action success × social feedback
        _p15_outcome = _p15_act_suc * 0.60 + self.social_sce.social_feedback * 0.40
        _p15_behav_var = (
            self.self_misalign.misalignment_score
        )  # proxy for how unpredictable we are
        _p15_goal_align = max(0.0, 1.0 - self.goal_regulator.churn_rate)
        self.reputation_mem.update(
            agent_id=_p15_agent,
            outcome=_p15_outcome,
            behavior_variance=_p15_behav_var,
            goal_alignment=_p15_goal_align,
        )

        # 2. SocialMaskRegistry — update mask for active agent
        _p15_trust = self.reputation_mem.get_trust(_p15_agent)
        self.mask_registry.update(
            agent_id=_p15_agent,
            social_trust=_p15_trust,
            social_outcome=_p15_outcome,
            internal_pressure=_p15_pressure,
            active_persona=_p15_persona,
            stream=self.stream,
        )

        # 3. ConsequenceEstimator — biased foresight
        _p15_volatility = (
            self.self_misalign.misalignment_score * 0.50
            + self.behav_inertia.accumulated_tension * 0.30
            + self.failure_detector.instability_index * 0.20
        )
        self.consequence_est.update(
            trust_at_stake=_p15_trust,
            behavioral_volatility=_p15_volatility,
            active_persona=_p15_persona,
            competence_belief=_p15_comp_bel,
            runaway_active=self.recursive_feedback.runaway_active,
            internal_pressure=_p15_pressure,
        )

        # 4. MaskRoleConflictEngine — resolve mask vs internal state
        _p15_mask = self.mask_registry.get_or_create(_p15_agent)
        _p15_mask_tone = _p15_mask.get("tone_bias", 0.0)
        _p15_mask_integ = _p15_mask.get("integrity", 0.60)
        self.mask_conflict.update(
            internal_pressure=_p15_pressure,
            mask_integrity=_p15_mask_integ,
            active_persona=_p15_persona,
            mask_tone_bias=_p15_mask_tone,
            suppression_signal=self.consequence_est.suppression_signal,
            stream=self.stream,
        )

        # Publish Phase 15 metrics into output_profile
        _p15_profile = self.person_engine.output_profile
        _p15_profile["p15_agent"] = _p15_agent
        _p15_profile["p15_mask_integrity"] = _p15_mask_integ
        _p15_profile["p15_mask_broken"] = self.mask_registry.mask_broken.get(
            _p15_agent, False
        )
        _p15_profile["p15_mask_adherence"] = self.mask_conflict.mask_adherence
        _p15_profile["p15_bleed"] = self.mask_conflict.behavioral_bleed
        _p15_profile["p15_resolution"] = self.mask_conflict.resolution_mode
        _p15_profile["p15_trust"] = _p15_trust
        _p15_profile["p15_engage_will"] = self.reputation_mem.engagement_willingness
        _p15_profile["p15_withdraw"] = self.reputation_mem.withdrawal_signal
        _p15_profile["p15_consequence_conc"] = self.consequence_est.consequence_concern
        _p15_profile["p15_suppress"] = self.consequence_est.suppression_signal
        _p15_profile["p15_exp_trust_delta"] = self.consequence_est.expected_trust_delta

        # Social withdrawal → override tone to withdrawn when withdrawal_signal high
        if (
            self.reputation_mem.withdrawal_signal > 0.55
            and self.mask_conflict.resolution_mode != "mask"
        ):
            _p15_profile["tone"] = "withdrawn"
        # ── End Phase 15 tick block ───────────────────────────────────────────

        # ── Phase 16: Instability self-preservation ──────────────────────────
        _p16_anchor = self.identity_anchor.retrieve_best()
        _p16_anchor_available = _p16_anchor is not None
        _p16_agent = self.social_sce.active_person_id or "default"
        _p16_mask_broken = self.mask_registry.mask_broken.get(_p16_agent, False)
        _p16_temporal_incoh = 1.0 - getattr(self.self_consist, "temporal_coherence", 1.0)
        _p16_active_mode = getattr(self, "_last_goal_mode", "")
        self.instability_monitor.update(
            entropy=self.entropic_drift.entropy_level,
            fragmentation=getattr(self.isf, "component_variance", 0.10),
            goal_churn=self.goal_regulator.churn_rate,
            temporal_incoherence=_p16_temporal_incoh,
            conflict_score=self.belief_conflict.conflict_score,
            misalignment=self.self_misalign.misalignment_score,
            behavioral_bleed=self.mask_conflict.behavioral_bleed,
            runaway_active=self.recursive_feedback.runaway_active,
            mask_broken=_p16_mask_broken,
            withdrawal_signal=self.reputation_mem.withdrawal_signal,
            fds_state=self.failure_detector.state,
            anchor_available=_p16_anchor_available,
            active_goal_mode=_p16_active_mode,
            stream=self.stream,
        )

        _p16_profile = self.person_engine.output_profile
        _p16_profile["p16_instability_risk"] = self.instability_monitor.instability_risk
        _p16_profile["p16_caution_bias"] = self.instability_monitor.caution_bias
        _p16_profile["p16_anchor_pull"] = self.instability_monitor.anchor_pull
        _p16_profile["p16_withdrawal_bias"] = self.instability_monitor.withdrawal_bias
        _p16_profile["p16_recent_collapse"] = self.instability_monitor.recent_collapse
        _p16_profile["p16_output_simplify"] = self.instability_monitor.output_simplify

        if self.instability_monitor.instability_risk > 0.52:
            _p16_profile["hesitation_level"] = max(
                _p16_profile.get("hesitation_level", 0.0),
                min(1.0, 0.25 + self.instability_monitor.caution_bias * 0.70),
            )
            _depth = max(1, 5 - int(round(self.instability_monitor.output_simplify * 4.0)))
            _p16_profile["max_response_depth"] = min(
                _p16_profile.get("max_response_depth", 5), _depth
            )
            if self.instability_monitor.withdrawal_bias > 0.45:
                _p16_profile["tone"] = "withdrawn"
                _p16_profile["social_withdrawal"] = True
            elif _p16_profile.get("tone") == "engaged":
                _p16_profile["tone"] = "neutral"
            elif self.instability_monitor.instability_risk > 0.68:
                _p16_profile["tone"] = "anxious"
            if (
                self.instability_monitor.instability_risk > 0.72
                and not _p16_profile.get("uncertainty_prefix")
            ):
                _p16_profile["uncertainty_prefix"] = "Let me keep this brief. "
        # ── End Phase 16 tick block ───────────────────────────────────────────

            # ── Phase 17: Irreversible identity drift ───────────────────────────
            _p17_agent = self.social_sce.active_person_id or "default"
            _p17_trust = self.reputation_mem.get_trust(_p17_agent)
            _p17_mask_broken = self.mask_registry.mask_broken.get(_p17_agent, False)
            _p17_mode = getattr(self, "_last_goal_mode", "")
            self.identity_drift.update(
                instability_risk=self.instability_monitor.instability_risk,
                caution_bias=self.instability_monitor.caution_bias,
                recent_collapse=self.instability_monitor.recent_collapse,
                social_trust=_p17_trust,
                withdrawal_bias=self.instability_monitor.withdrawal_bias,
                action_success=_p11_act_suc,
                active_goal_mode=_p17_mode,
                anchor_pull=self.instability_monitor.anchor_pull,
                mask_broken=_p17_mask_broken,
                stream=self.stream,
            )

            _p17_profile = self.person_engine.output_profile
            _p17_profile["p17_scar_index"] = self.identity_drift.scar_index
            _p17_profile["p17_resilience"] = self.identity_drift.resilience_index
            _p17_profile["p17_initiative"] = self.identity_drift.initiative
            _p17_profile["p17_trust_baseline"] = self.identity_drift.trust_baseline
            _p17_profile["p17_switch_flex"] = self.identity_drift.switching_flexibility
            _p17_profile["p17_novelty_tolerance"] = self.identity_drift.novelty_tolerance
            _p17_profile["p17_self_mismatch"] = self.identity_drift.self_mismatch
            _p17_profile["p17_narrative_lens"] = self.identity_drift.narrative_lens

            if self.identity_drift.scar_index > 0.24:
                _p17_profile["max_response_depth"] = min(
                    _p17_profile.get("max_response_depth", 5),
                    max(1, 4 - int(round(self.identity_drift.scar_index * 4.0))),
                )
                if _p17_profile.get("tone") == "engaged":
                    _p17_profile["tone"] = "neutral"

            if (
                self.identity_drift.narrative_lens == "warning"
                and self.instability_monitor.instability_risk > 0.50
                and not _p17_profile.get("uncertainty_prefix")
            ):
                _p17_profile["uncertainty_prefix"] = "Best to avoid overreaching. "
            elif (
                self.identity_drift.narrative_lens == "growth"
                and self.instability_monitor.instability_risk < 0.35
                and _p17_profile.get("tone") == "neutral"
            ):
                _p17_profile["tone"] = "engaged"
            # ── End Phase 17 tick block ───────────────────────────────────────────

        # Promote concepts that survived ignition to global workspace
        for _c in list(self._concepts)[-20:]:
            _sal = self._concept_salience.get(_c, 0.0)
            _integ_score = _sal * 0.5 + (0.3 if state.ignition else 0.0)
            self.gateway.try_promote(_c, _integ_score, source="workspace")
        _accessible_now = self.gateway.report_all_accessible()
        if _accessible_now:
            _global_gain = min(2.4, 0.35 + 0.12 * len(_accessible_now))
            for _region in (brain.prefrontal, brain.assoc, brain.hippocampus):
                _rn = len(_region.excitatory)
                if _rn > 0:
                    _region.inject(
                        [_global_gain] * min(10, _rn) + [0.0] * max(0, _rn - 10)
                    )
            if self._goal_mode(state.goal or "explore") == "respond":
                _an = len(brain.amygdala.excitatory)
                if _an > 0:
                    brain.amygdala.inject([0.8] * min(8, _an) + [0.0] * max(0, _an - 8))

        # ── 2. Engram update (every tick — fired resets each tick so must capture now) ─
        self._update_engrams(brain)

        # ── 3. Hippocampal replay (quiet periods) ─────────────
        if (
            total < REPLAY_IDLE_THRESHOLD
            and self._tick - self._last_replay > REPLAY_INTERVAL
            and self._engrams
        ):
            self._replay(brain)
            state.replaying = True
            self._last_replay = self._tick

        # ── 4. Concept extraction ─────────────────────────────
        _n_concepts_before = len(self._concepts)
        if brain._use_web and brain._web_enc.last_items:
            latest = brain._web_enc.last_items[-1]
            extract_text = latest.get("text", "") or latest.get("title", "")
            self._extract_concepts(
                latest.get("title", "") + " " + extract_text,
                self._hipp_act_ema,
                self._pfc_act_ema,
            )
        # Extract from speech too
        if brain.speech_in:
            self._extract_concepts(
                brain.speech_in,
                self._hipp_act_ema,
                self._pfc_act_ema,
            )

        # ── 4b. Semantic hippocampus encoding — store new concepts as episodes ──
        # This is what makes the system ACTUALLY LEARN from input, not just fire neurons.
        _new_concepts = list(self._concepts)[_n_concepts_before:]
        if _new_concepts:
            em_label = em.dominant()
            self.record_semantic_input(_new_concepts, brain.tick_count, em_label, brain)

        # ── 4c. Update concept graph: strengthen edges between co-occurring concepts ──
        if self._tick % REASON_INTERVAL == 1 and len(self._concepts) >= 2:
            recent_c = list(self._concepts)[-min(10, len(self._concepts)) :]
            _arousal = em.arousal()
            for _ci in range(len(recent_c)):
                for _cj in range(_ci + 1, min(_ci + 4, len(recent_c))):
                    self.concept_graph.observe_pair(
                        recent_c[_ci],
                        recent_c[_cj],
                        emotional_val=_arousal,
                    )
            for c in recent_c:
                self._emotional_memory.store(c, em)
                # Emotional arousal boosts salience of co-active concepts
                if _arousal > 0.4:
                    self._bump_salience(c, _arousal * 0.4)

        # ── 4d. Embodied concept formation — derive concepts from body/world state ──
        if self._tick % (REASON_INTERVAL * 2) == 0:
            self._form_embodied_concepts(brain, em)

        # em_desc used by reasoning (step 5), episodic (step 9), self-desc (step 10)
        em_desc = em.describe()

        # ── 5. Reasoning ─────────────────────────────────────
        if self._tick % REASON_INTERVAL == 0 and len(self._concepts) >= 2:
            conclusion = self._reason()
            if conclusion:
                self._conclusions.append(conclusion)
                # Inject conclusion back into semantic pathway for neural processing
                brain.inject_text_input(conclusion)
                # Record as "insight" only when reasoning found a substantive depth
                # contrast — this triggers comm_drive to speak about real findings
                if any(
                    kw in conclusion
                    for kw in (
                        "strongly encoded",
                        "deeper",
                        "causally",
                        "co-activation",
                        "depends on",
                        "near-identical",
                        "explains aspects",
                        "provides a bridging",
                        "mediates the connection",
                        "structuring my current",
                        "recurs",
                        "REFLECT",
                    )
                ):
                    self.episodic.record(
                        brain.tick_count, "insight", conclusion[:100], em_desc
                    )

        # ── 6. Goal evaluation ────────────────────────────────
        _self_goal_spawns = self._maintain_self_horizon_goals(brain.tick_count)
        for _sg in _self_goal_spawns:
            self.stream.append(f"[SELF-GOAL] {_sg}")
            self.episodic.record(brain.tick_count, "self_goal", _sg[:120], em_desc)
        if self._tick - self._last_goal_chg > GOAL_CHANGE_INTERVAL:
            _candidate = self._evaluate_goal(em, total)
            # Hierarchical goal system: values + body state can veto or override
            new_goal = self.goal_system.select(
                _candidate,
                self.body,
                em,
                autobiography=self.autobiography,
                self_model=self.self_model,
                current_tick=self._tick,
                social_context=self._current_self_social_context(brain),
            )

            # ── Goal synthesizer: generate open goals from internal signals ──
            _ws_ents = getattr(getattr(brain, "_world_state", None), "persons", {})
            _surp_reg, _surp_mag = self.predictor.most_surprising()
            _sm_pid = getattr(
                getattr(brain, "_social_manager", None),
                "primary_interlocutor",
                lambda: None,
            )()
            _synth_new = self.goal_synth.synthesize(
                tick=brain.tick_count,
                prediction_error=abs(state.prediction_error),
                surprise_entity=_surp_reg or "",
                drives=self.drives,
                em=em,
                meta_gaps=self.meta.gaps(4),
                self_tensions=getattr(self.self_model, "self_tensions", [])[:3],
                social_person=str(_sm_pid) if _sm_pid else None,
                narrative_pattern=None,
                world_entities=len(_ws_ents),
            )
            for _sg in _synth_new:
                self.stream.append(f"[GOAL-BORN] {_sg.name}: {_sg.description}")
                self.episodic.record(
                    brain.tick_count, "goal_born", f"{_sg.name}({_sg.source})", em_desc
                )
            self._refresh_dynamic_goal_bias()
            if self._dominant_dynamic_goal:
                _dyn_mode = self._goal_mode(self._dominant_dynamic_goal)
                if (
                    self._dynamic_goal_bias.get(_dyn_mode, 0.0)
                    > self._dynamic_goal_bias.get(new_goal, 0.0) + 0.08
                ):
                    new_goal = self._dominant_dynamic_goal

            # ── CF engine: record goal decision ──────────────────────────────
            _rejected_candidate = _candidate if _candidate != new_goal else "rest"
            _chosen_causal = getattr(self, "_last_causal_bonus", {}).get(
                new_goal,
                getattr(self, "_last_causal_bonus", {}).get(
                    self._goal_mode(new_goal), 0.3
                ),
            )
            _rejected_score = getattr(self, "_last_goal_scores", {}).get(
                _rejected_candidate, 0.0
            )
            _chosen_score = getattr(self, "_last_goal_scores", {}).get(
                new_goal,
                getattr(self, "_last_goal_scores", {}).get(
                    self._goal_mode(new_goal), 0.5
                ),
            )
            self.cf_engine.record_decision(
                brain.tick_count,
                new_goal,
                _rejected_candidate,
                _chosen_score,
                _rejected_score,
                _chosen_causal,
            )
            # Register goal prediction in calibrator
            self.metacog_calib.register_claim(
                f"Goal '{new_goal}' will succeed",
                claim_type="goal_prediction",
                confidence=min(0.95, max(0.3, _chosen_causal + 0.2)),
                tick=brain.tick_count,
            )

            if new_goal != state.goal:  # goal changed — snapshot valence
                self._prev_agency_valence = em.valence()
                # Sensorimotor forward model: begin action prediction
                self.sensorimotor.begin_action(new_goal, self.embodied_self, self.body)
                # World model: record pre-state with multi-dimensional snapshot
                _ws = getattr(brain, "_world_state", None)
                _sm_m = getattr(brain, "_social_manager", None)
                self.world_model.record_action(
                    new_goal,
                    getattr(brain, "last_executed_action", brain.last_action),
                    em.valence(),
                    pre_world_entities=(
                        len(_ws.persons) + len(getattr(_ws, "objects", {}))
                        if _ws
                        else 0
                    ),
                    pre_social_valence=(
                        _sm_m.social_summary().get("rapport", 0.0) if _sm_m else 0.0
                    ),
                    pre_body_load=self.body.homeostatic_urgency(),
                )
            state.goal = new_goal
            self._last_goal_chg = self._tick
            _grounding = self.decision_grounding()
            # ENFORCEMENT 1: full self-causality — every decision depends on
            # self_model, global_state AND goal_structure simultaneously.
            # If any pillar is absent, block the action completely.
            if not (
                _grounding.get("goal") == state.goal
                and _grounding.get("integration_ready", False)
                and _grounding.get("global_access_ready", False)
                and float(_grounding.get("self_model_signal", 0.0)) > 0.10
                and _grounding.get("goal_scores_present", False)
            ):
                self.stream.append(
                    f"[CAUSAL-STOP] goal={state.goal} grounding={_grounding}"
                )
            else:
                self._apply_goal(brain, state.goal)
            # Strategic meta: log goal for bias detection
            self.strategic_meta.record_goal(state.goal)
        # Fix 9 + world-model outcome: observe actual result ~20 ticks after
        _ticks_since = self._tick - self._last_goal_chg
        if 20 <= _ticks_since <= 22:
            _agency_delta = em.valence() - self._prev_agency_valence
            self.self_model.agency_score = max(
                -1.0, min(1.0, self.self_model.agency_score * 0.9 + _agency_delta * 0.4)
            )
            # Sensorimotor forward model: observe result + update agency
            _sm_alarm = self.sensorimotor.observe_result(self.embodied_self, self.body)
            if _sm_alarm:
                self.stream.append(_sm_alarm)
            # Blend sensorimotor agency into self-model agency
            self.self_model.agency_score = (
                self.self_model.agency_score * 0.7 + self.sensorimotor.agency * 0.3
            )
            # World model: compare predicted delta to actual for EMA update
            _ws_o = getattr(brain, "_world_state", None)
            _sm_o = getattr(brain, "_social_manager", None)
            _actual_delta = self.world_model.observe_outcome(
                em.valence(),
                post_world_entities=(
                    len(_ws_o.persons) + len(getattr(_ws_o, "objects", {}))
                    if _ws_o
                    else 0
                ),
                post_social_valence=(
                    _sm_o.social_summary().get("rapport", 0.0) if _sm_o else 0.0
                ),
                post_body_load=self.body.homeostatic_urgency(),
            )
            # Record causal episode with prediction vs outcome
            _real_act = getattr(brain, "last_executed_action", brain.last_action)
            _pred_delta, _conf = self.world_model.predict(state.goal, _real_act)
            if _conf > 0.1:
                self.episodic.record(
                    brain.tick_count,
                    "causal",
                    f"goal={state.goal} action={_real_act} "
                    f"predicted={_pred_delta:+.3f} actual={_actual_delta:+.3f}",
                    em_desc,
                    prediction=f"delta={_pred_delta:+.3f}",
                    observed_outcome=f"delta={_actual_delta:+.3f}",
                    causal_update=f"error={abs(_pred_delta - _actual_delta):.3f}",
                )
            self.strategic_meta.observe_prediction(_pred_delta, _actual_delta)
            self.strategic_meta.observe_goal_outcome(
                self._prev_agency_valence, em.valence()
            )

            # Causal graph: record transition for action→outcome learning
            _social_p = self.embodied_self.social_presence
            _cg_sig = build_state_signature(
                state.goal,
                em.dominant(),
                _social_p,
                self.body.energy_reserve,
                len(self._concepts),
                self._current_focus,
            )
            self.causal_graph.record_goal_transition(
                TransitionRecord(
                    tick=brain.tick_count,
                    state_signature=_cg_sig,
                    action_kind=state.goal,
                    action_args={"last_action": _real_act or ""},
                    predicted_outcome=str(_pred_delta) if _conf > 0.1 else "0.0",
                    observed_outcome=str(_actual_delta),
                    reward=em.valence(),
                    surprise=abs(_pred_delta - _actual_delta) if _conf > 0.1 else 0.0,
                    success=_actual_delta > -0.05,
                    involved_persons=[
                        str(p)
                        for p in (
                            tuple(
                                getattr(
                                    getattr(brain, "_world_state", None), "persons", {}
                                ).keys()
                            )
                        )[:3]
                    ],
                )
            )

        # ── 7. Inner monologue ────────────────────────────────
        if self._tick % MONOLOGUE_INTERVAL == 0:
            thought = self._monologue(brain, em, state)
            self.stream.append(thought)
            state.thought = thought
            self._last_thought_tick = self._tick
        elif self._tick - self._last_thought_tick >= 30:
            # Fix 3: self-generated thought loop independent of external input
            inner = self._generate_inner_thought(em)
            if inner:
                self.stream.append(inner)
                if not state.thought:
                    state.thought = inner
                self._last_thought_tick = self._tick

        # ── 8. Predictive coding ─────────────────────────────
        pred_error = self.predictor.tick(brain.region_activity)
        state.prediction_error = pred_error
        # Feed prediction-error back: surprise = 20% from pred-error, 80% from delta_asc
        brain._consciousness_pred_error = pred_error  # read by emotion.py EMA path
        # Fix 5: prediction error has real consequences
        if abs(pred_error) > 0.3:
            surp_r, _ = self.predictor.most_surprising()
            if surp_r:
                self._current_focus = surp_r  # redirect spotlight immediately
            self.drives.information_hunger = min(
                1.0, self.drives.information_hunger + 0.15
            )
            # Salience bump: surprise makes current concepts more conscious
            _pred_bump = min(0.8, abs(pred_error))
            for _c in list(self._concepts)[-8:]:
                self._bump_salience(_c, _pred_bump)

        # ── 8b. World prediction errors → semantic concepts ──
        _ws = getattr(brain, "_world_state", None)
        if _ws is not None:
            _wps = _ws.prediction_summary
            if _wps.is_surprising:
                # Generate semantic concepts from world surprise
                for lab in _wps.semantic_labels:
                    self._concepts.append(f"world:{lab}")
                # Record as episodic event when very surprising
                if _wps.max_surprise > 0.5:
                    self.episodic.record(
                        brain.tick_count,
                        "world_surprise",
                        f"Unexpected: {','.join(_wps.semantic_labels)} "
                        f"surprise={_wps.max_surprise:.2f} "
                        f"entity={_wps.max_surprise_entity}",
                        em.describe(),
                    )
                # Boost information hunger proportionally
                self.drives.information_hunger = min(
                    1.0, self.drives.information_hunger + _wps.max_surprise * 0.2
                )
                # Compound neural + world prediction error for emotion
                state.prediction_error = max(
                    state.prediction_error,
                    _wps.max_surprise * 0.6,
                )

                # ── Surprise → Attention priority (entity-specific) ──
                # Feed the most surprising entity directly into the attention
                # controller so the system actively orients toward it.
                _surp_entity = _wps.max_surprise_entity
                if _surp_entity and _wps.max_surprise > 0.25:
                    self.attention_ctrl.set_priority(
                        _surp_entity,
                        weight=min(0.9, _wps.max_surprise),
                        source="surprise",
                        reason=f"surprise:{_wps.max_surprise:.2f}",
                        decay_rate=0.04,  # faster decay than goal-driven
                        tick=brain.tick_count,
                        surprise_now=_wps.max_surprise,
                    )

                # ── Surprise → Planner target-bound intent ──
                # High surprise should generate an epistemic goal to investigate
                # the surprising entity, not just global information hunger.
                if _wps.max_surprise > 0.4 and _surp_entity:
                    _exec_surp = getattr(brain, "_task_executive", None)
                    if _exec_surp is not None:
                        _already_investigating = (
                            _exec_surp.active_goal is not None
                            and _exec_surp.active_goal.context
                            and _surp_entity in _exec_surp.active_goal.context
                        )
                        if not _already_investigating:
                            # Start an EpistemicInvestigation for this entity
                            if _surp_entity not in self._active_investigations:
                                self._active_investigations[_surp_entity] = (
                                    EpistemicInvestigation(
                                        entity=_surp_entity,
                                        start_tick=brain.tick_count,
                                        start_surprise=_wps.max_surprise,
                                        target_surprise=_wps.max_surprise * 0.45,
                                        timeout_ticks=400,
                                    )
                                )
                            _exec_surp.submit_goal(
                                "orient_head",
                                context=f"investigate:{_surp_entity}",
                                tick=brain.tick_count,
                                world=_ws,
                            )
                            self.stream.append(
                                f"[ORIENT] Surprise {_wps.max_surprise:.2f} "
                                f"→ investigating {_surp_entity}"
                            )

                # ── Surprise follow-up: track whether orientation reduces surprise ──
                # If we previously oriented toward an entity and its surprise dropped,
                # log the successful active inference cycle.
                _prev_orient = getattr(self, "_surprise_orient_target", None)
                if _prev_orient and _prev_orient == _surp_entity:
                    _prev_surp = getattr(self, "_surprise_orient_level", 0.0)
                    if _wps.max_surprise < _prev_surp * 0.6:
                        self.stream.append(
                            f"[ORIENT] Surprise reduced: {_prev_surp:.2f} → "
                            f"{_wps.max_surprise:.2f} for {_surp_entity}"
                        )
                        self._surprise_orient_target = None
                        self._surprise_orient_level = 0.0
                if _surp_entity and _wps.max_surprise > 0.4:
                    self._surprise_orient_target = _surp_entity
                    self._surprise_orient_level = _wps.max_surprise

                # ── EpistemicInvestigation resolution check ───────────
                _finished_inv: List[str] = []
                _cur_surp_map: Dict[str, float] = {}
                if _surp_entity:
                    _cur_surp_map[_surp_entity] = _wps.max_surprise
                for _inv_e, _inv in list(self._active_investigations.items()):
                    _elapsed_inv = brain.tick_count - _inv.start_tick
                    _cur_s = _cur_surp_map.get(_inv_e, 0.0)
                    if _cur_s <= _inv.target_surprise:
                        # Success: surprise resolved
                        self.stream.append(
                            f"[EPISTEMIC] Investigation resolved: {_inv_e} "
                            f"surprise {_inv.start_surprise:.2f} → {_cur_s:.2f} "
                            f"in {_elapsed_inv} ticks"
                        )
                        self.episodic.record(
                            brain.tick_count,
                            "epistemic_resolution",
                            f"resolved:{_inv_e} in {_elapsed_inv} ticks "
                            f"start={_inv.start_surprise:.2f} final={_cur_s:.2f}",
                            em_desc,
                        )
                        self.belief_store._store(
                            _inv_e,
                            "investigated_and_resolved",
                            f"surprise_from_{_inv.start_surprise:.2f}",
                            confidence=0.65,
                            tick=brain.tick_count,
                        )
                        _finished_inv.append(_inv_e)
                    elif _elapsed_inv > _inv.timeout_ticks:
                        # Timeout
                        self.stream.append(
                            f"[EPISTEMIC] Investigation timed out: {_inv_e} "
                            f"(unresolved after {_elapsed_inv} ticks)"
                        )
                        self.episodic.record(
                            brain.tick_count,
                            "epistemic_timeout",
                            f"unresolved:{_inv_e} timed out in {_elapsed_inv} ticks",
                            em_desc,
                        )
                        _finished_inv.append(_inv_e)
                for _fe in _finished_inv:
                    self._active_investigations.pop(_fe, None)

            # 1.1 — Unexpected departures → search goal: person disappeared triggers orient
            if _wps.unexpected_departures > 0:
                _exec_8b = getattr(brain, "_task_executive", None)
                if _exec_8b is not None:
                    _lost_id = _wps.max_surprise_entity or ""
                    _already_searching = (
                        _exec_8b.active_goal is not None
                        and _exec_8b.active_goal.intent
                        in ("look_around", "orient_head")
                    )
                    if not _already_searching:
                        _exec_8b.submit_goal(
                            "look_around",
                            context=f"person_departed:{_lost_id}",
                            tick=brain.tick_count,
                            world=_ws,
                        )
                        self.stream.append(
                            f"[WORLD] Person departed unexpectedly: "
                            f"{_lost_id} — searching"
                        )

        # ── General epistemic discipline ──────────────────────────────
        # Broader hypothesis engine: not just surprise-triggered, but any
        # uncertain belief triple in the workspace can become a hypothesis.
        if self._tick > 0 and self._tick % 80 == 0:
            self._run_epistemic_discipline(brain)

        # ── 9. Episodic memory ────────────────────────────────
        # Determine social interlocutors for person-linked episodes
        _sm = getattr(brain, "_social_manager", None)
        _primary_pid = _sm.primary_interlocutor() if _sm else None
        # Track social isolation: reset when interlocutor present, else accumulate
        if _primary_pid is not None:
            self._social_isolation_ticks = 0
        else:
            self._social_isolation_ticks += 1
        _ws = getattr(brain, "_world_state", None)
        _visible_pids = tuple(_ws.persons.keys()) if _ws and _ws.persons else ()

        if state.ignition:
            surp_region, surp_mag = self.predictor.most_surprising()
            self.episodic.record(
                brain.tick_count,
                "ignition",
                f"Global broadcast #{self._ignition_count} "
                f"(most surprised: {surp_region} Δ={surp_mag:+.3f})",
                em_desc,
                person_id=_primary_pid,
                person_ids=_visible_pids,
            )
        # Record new concepts as they arrive
        if brain._use_web and brain._web_enc.last_items:
            latest_title = brain._web_enc.last_items[-1].get("title", "")
            if latest_title and not self.episodic.last_of_kind("concept"):
                self.episodic.record(
                    brain.tick_count,
                    "concept",
                    latest_title[:80],
                    em_desc,
                    person_id=_primary_pid,
                    person_ids=_visible_pids,
                )
            elif latest_title:
                last_c = self.episodic.last_of_kind("concept")
                if last_c and last_c.content[:80] != latest_title[:80]:
                    self.episodic.record(
                        brain.tick_count,
                        "concept",
                        latest_title[:80],
                        em_desc,
                        person_id=_primary_pid,
                        person_ids=_visible_pids,
                    )
        if state.replaying:
            self.episodic.record(
                brain.tick_count,
                "replay",
                f"Memory replay ({len(self._engrams)} engrams)",
                em_desc,
            )
        # Record emotion shifts
        prev_dom = self.episodic.last_of_kind("emotion")
        if em_desc != (prev_dom.content if prev_dom else ""):
            if self._tick % 200 == 0:  # don't flood
                self.episodic.record(
                    brain.tick_count,
                    "emotion",
                    em_desc,
                    person_id=_primary_pid,
                    person_ids=_visible_pids,
                )
        # Record goal changes
        prev_goal = getattr(self, "_prev_goal", "")
        if state.goal != prev_goal:
            self.episodic.record(
                brain.tick_count,
                "goal",
                f"Goal changed: {prev_goal} → {state.goal}",
                em_desc,
                person_id=_primary_pid,
                person_ids=_visible_pids,
            )
            self._prev_goal = state.goal

        # ── 10. Self-model update ─────────────────────────────
        sm = self.self_model
        sm.concepts_learned = len(self._concepts)
        sm.ignitions_total = self._ignition_count
        # Count total spikes via hippocampus+assoc fired masks (avoids O(N) n.fired reads)
        sm.total_spikes += int(
            np.count_nonzero(
                brain.hippocampus._fired_this_tick[brain.hippocampus._exc_positions]
            )
            + np.count_nonzero(brain.assoc._fired_this_tick[brain.assoc._exc_positions])
        )
        sm.known_gaps = self.meta.gaps(4)
        sm.known_strengths = self.meta.strengths(4)
        # Fix 2: dynamic self-model update — energy/uncertainty/identity_stability
        sm.update(em, len(self.meta.gaps(8)), state.ignition)
        # Interoceptive body update — body state feeds back into emotion + goals
        self.body.tick(total, em, 1 if state.ignition else 0)
        # Merge proprioceptive data from real/simulated body into self-model
        if self._proprioceptive is not None:
            _prop = self._proprioceptive
            sm.body_pose = getattr(_prop, "body_pose", "unknown")
            sm.body_load = getattr(_prop, "overall_load", 0.0)
            sm.body_pain = getattr(_prop, "pain_signal", 0.0)
            sm.balance = getattr(_prop, "balance_ok", True)
            sm.last_skill = getattr(_prop, "last_skill", "")
            # Feed physical load/pain into interoceptive body
            self.body.thermal_load = max(
                self.body.thermal_load, getattr(_prop, "overall_load", 0.0) * 0.3
            )
            if getattr(_prop, "pain_signal", 0.0) > 0.3:
                self.body.error_risk = min(
                    1.0,
                    self.body.error_risk + getattr(_prop, "pain_signal", 0.0) * 0.05,
                )
            # Wire proprioceptive data into sensorimotor forward model
            self.sensorimotor.set_proprioceptive(_prop)
        # Embodied self + explicit task state
        self.embodied_self.update(brain, self.body, self._current_focus, total)
        self.robot_state.update(
            self.embodied_self, self.body, self.task_frame, self._current_focus
        )
        self.task_frame.sync(
            brain,
            state.goal,
            self._current_focus,
            self.embodied_self,
            self.body,
            list(self._concepts),
            list(self._conclusions),
            self.robot_state,
        )
        self.robot_state.update(
            self.embodied_self, self.body, self.task_frame, self._current_focus
        )
        state.embodiment_summary = self.embodied_self.describe()
        state.robot_summary = self.robot_state.describe()
        self._last_controller_summary = brain.robot_controller_summary
        state.controller_summary = self._last_controller_summary
        state.task_summary = self.task_frame.describe()
        # Autobiographical identity: accumulate per-tick statistics
        _autobio_social_ctx = self._current_self_social_context(brain)
        self.autobiography.observe_tick(
            state.goal,
            em.dominant(),
            list(self._concepts)[-3:],
            social_person_id=_primary_pid,
            relationship_type=str(_autobio_social_ctx.get("relationship_type", "")),
        )
        # Strategic meta: observe attention quality each tick
        self.strategic_meta.observe_focus(self._current_focus, self.predictor.errors)
        if self._tick % 300 == 0:
            state.self_desc = sm.describe(
                brain.tick_count,
                em_desc,
                self.personality.describe(),
                identity_summary=self.autobiography.identity_summary,
                world_summary=self.world_model.summarise(2),
            )
            self.stream.append(f"[SELF] {state.self_desc}")
            self.stream.append(f"[ROBOT] {self.robot_state.describe()}")
            self.episodic.record(
                brain.tick_count, "self", state.self_desc[:120], em_desc
            )

        sim_t = self.sandbox_planner.tick(
            self._tick,
            self.task_frame,
            self.embodied_self,
            list(self._concepts),
            list(self._conclusions),
            em,
            self.body,
            autobiography=self.autobiography,
            world_model=self.world_model,
            drives=self.drives,
        )
        if sim_t:
            self.stream.append(sim_t)
            self.episodic.record(brain.tick_count, "simulate", sim_t[:120], em_desc)

        # ── 10b. Postmortem integration ──────────────────────
        _exec = getattr(brain, "_task_executive", None)
        if _exec is not None:
            for pm in _exec.recent_postmortems(3):
                # Feed into capability model
                sm.capabilities.record(pm.intent, pm.success, pm.failure_cause)
                # Feed into decision quality tracking
                self.meta.record_decision_outcome(pm.intent, pm.success)
                # Record significant postmortems as episodic events
                if not pm.success:
                    self.episodic.record(
                        brain.tick_count,
                        "postmortem",
                        f"FAILED:{pm.intent} cause={pm.failure_cause[:60]} "
                        f"correction={pm.correction_rule}",
                        em.describe(),
                    )
                # Feed correction rules into metacognition
                if pm.correction_rule:
                    self.meta.observe(f"correction:{pm.correction_rule}", 0.6, 0.6)
                    # Phase 3: feed lessons into sandbox planner
                    self.sandbox_planner.integrate_postmortem(pm.correction_rule)
            # Clear consumed postmortems
            if _exec._postmortems:
                _exec._postmortems.clear()

        # ── 10c. ExecutiveOutcome integration ────────────────
        # Drain real action outcomes from the executive and store
        # for use by identity_arc, narrative, value_model below.
        self._last_outcomes: list = []
        if _exec is not None:
            self._last_outcomes = _exec.drain_outcomes()
            for _oc in self._last_outcomes:
                # Episodic memory: record real outcome + phenomenal snapshot
                _phenom_sig = self.phenomenal_buffer.experiential_signature()
                _phenom_vec = self.phenomenal_buffer.recall_vector()
                self.episodic.record(
                    brain.tick_count,
                    "executive_outcome",
                    f"{'OK' if _oc.success else 'FAIL'}:{_oc.intent} "
                    f"skill={_oc.executed_skill} r={_oc.reward:+.2f}"
                    f"{' target=' + _oc.target_person if _oc.target_person else ''}"
                    f" phenom={_phenom_sig}",
                    em_desc,
                    phenomenal_vector=_phenom_vec,
                )
                # ToM feedback: record outcome as social learning for person-targeted actions
                if _oc.target_person:
                    self.theory_of_mind.observe_interaction(
                        brain.tick_count,
                        _oc.target_person,
                        action=_oc.executed_skill,
                        success=_oc.success,
                        valence=_oc.reward,
                    )
                # ── Per-goal outcome EMA: fine-grained calibration ──
                # Map the executive intent back to a goal name and update
                # the EMA with the actual reward, so expected_reward learns
                # from concrete outcomes rather than global mood.
                _intent_to_goal = {
                    "look_around": "explore",
                    "attend_speaker": "respond",
                    "idle_pose": "rest",
                }
                _oc_goal = _intent_to_goal.get(_oc.intent, _oc.intent)
                if _oc_goal in self._goal_outcome_ema:
                    _ema_entry = self._goal_outcome_ema[_oc_goal]
                    _alpha = 0.2 if _ema_entry[1] < 10 else 0.08
                    _oc_signal = _oc.reward + (0.3 if _oc.success else -0.2)
                    _ema_entry[0] = _ema_entry[0] * (1 - _alpha) + _oc_signal * _alpha
                    _ema_entry[0] = max(0.0, min(1.0, _ema_entry[0]))
                    _ema_entry[1] += 1

                # ── Acute failure / success response ──────────────────
                if not _oc.success:
                    _acute_msg = self.strategic_meta.observe_failure(_oc.intent, self)
                    if _acute_msg:
                        self.stream.append(_acute_msg)
                else:
                    self.strategic_meta.reset_streak(_oc.intent)
                # ── Capability model: update skill competence tracker ──
                self.capability_model.record(_oc.executed_skill, _oc.success)
                self._reflect_on_action_outcome(_oc, brain.tick_count, em_desc)

                # ── Counterfactual resolution ─────────────────────────
                # When a concrete outcome arrives, match it to the last
                # counterfactual record and emit a full explanation:
                # "I chose X over Y (gap Z) — expected W — got V"
                _cf = self._last_counterfactual
                _intent_to_g2 = {
                    "look_around": "explore",
                    "attend_speaker": "respond",
                    "idle_pose": "rest",
                }
                _oc_goal2 = _intent_to_g2.get(_oc.intent, _oc.intent)
                if _cf is not None and not _cf.explained:
                    if _oc_goal2 == _cf.chosen_goal:
                        _cf.actual_outcome = "success" if _oc.success else "failure"
                        _cf.observed_reward = _oc.reward
                        _cf.explained = True
                        _expected = (
                            "success" if _cf.chosen_causal > 0.3 else "uncertain"
                        )
                        _match = (_cf.actual_outcome == "success") == (
                            _cf.chosen_causal > 0.3
                        )
                        _surprise_tag = "" if _match else " [✗ surprised]"
                        _lk_cf = getattr(self.lang, "current", "de")
                        if _lk_cf == "de":
                            _cf_msg = (
                                f"[CF] Wählte '{_cf.chosen_goal}'"
                                f"(score={_cf.chosen_score:.2f}) über"
                                f" '{_cf.rejected_goal}'"
                                f"(score={_cf.rejected_score:.2f},"
                                f" gap=+{_cf.score_delta:.2f})"
                                f" — erwartet: {_expected}"
                                f" — erhalten: {_cf.actual_outcome}"
                                f"{_surprise_tag}"
                            )
                        else:
                            _cf_msg = (
                                f"[CF] Chose '{_cf.chosen_goal}'"
                                f"(score={_cf.chosen_score:.2f}) over"
                                f" '{_cf.rejected_goal}'"
                                f"(score={_cf.rejected_score:.2f},"
                                f" gap=+{_cf.score_delta:.2f})"
                                f" - expected: {_expected}"
                                f" - observed: {_cf.actual_outcome}"
                                f"{_surprise_tag}"
                            )
                        self.stream.append(_cf_msg)
                        self.episodic.record(
                            brain.tick_count,
                            "counterfactual_resolved",
                            _cf_msg,
                            em_desc,
                        )

                # ── CF engine: record outcome + generate self-explanation ──
                _cf_explanation = self.cf_engine.record_outcome(
                    brain.tick_count, _oc_goal2, _oc.success, _oc.reward
                )
                if _cf_explanation and brain.tick_count % 200 == 0:
                    self.stream.append(f"[CF-SELF] {_cf_explanation}")
                    self.episodic.record(
                        brain.tick_count,
                        "cf_self_explanation",
                        _cf_explanation[:120],
                        em_desc,
                    )

                # ── Agency validator: observe action outcome ──────────────
                # Update goal synthesizer with outcome
                self.goal_synth.record_outcome(
                    _oc_goal2, _oc.success, _oc.reward, brain.tick_count
                )
                # Resolve metacog calibrator claim
                self.metacog_calib.resolve_by_type(
                    "goal_prediction",
                    correct=_oc.success,
                    tick=brain.tick_count,
                )

        # ── 10c-bis. Grounded semantics: learn from executive outcomes ────
        if self._last_outcomes:
            _active_concepts = list(self._concepts)[-8:]
            for _oc in self._last_outcomes:
                # Action-context grounding for active concepts
                for _c in _active_concepts:
                    self.grounded_memory.observe_action_context(
                        _c,
                        _oc.executed_skill,
                        "success" if _oc.success else "failure",
                        brain.tick_count,
                    )
                # Failed outcomes → non-exemplar + counterfactual knowledge
                if not _oc.success and _active_concepts:
                    for _c in _active_concepts[:3]:
                        _frame = self.grounded_memory.get_or_create(
                            _c, brain.tick_count
                        )
                        _frame.add_non_exemplar(
                            brain.tick_count,
                            f"{_oc.executed_skill} failed during {_oc.intent}",
                        )
                        _frame.add_counterfactual(
                            f"if {_oc.executed_skill} when {_c} active "
                            f"→ failure (not suitable for {_oc.intent})"
                        )

        # ── 10d. SkillEvent (step-level) integration ─────────
        # Drain per-step events for fine-grained learning and narrative.
        self._last_step_events = []
        if _exec is not None:
            self._last_step_events = _exec.drain_step_events()
            for _se in self._last_step_events:
                if _se.status in ("succeeded", "failed"):
                    self.episodic.record(
                        brain.tick_count,
                        "skill_event",
                        f"{_se.status}:{_se.skill_name} "
                        f"step={_se.step_index} goal={_se.goal_intent}"
                        f"{' person=' + _se.target_person if _se.target_person else ''}",
                        em_desc,
                    )
                    # Salience bump: real skill outcomes are experience
                    self._bump_salience(f"skill:{_se.skill_name}", 0.5)
                    # Theory of mind: update person model on person-targeted events
                    if _se.target_person:
                        self.theory_of_mind.observe_interaction(
                            brain.tick_count,
                            _se.target_person,
                            action=_se.skill_name,
                            success=(_se.status == "succeeded"),
                        )

        # ── 10e. ActiveScene update ──────────────────────────
        # Refresh the stable scene binding with hysteretic anchors.
        _ws = getattr(brain, "_world_state", None)
        _sm = getattr(brain, "_social_manager", None)
        self.active_scene.update(brain.tick_count, _ws, em, state.goal, _sm)
        # Feed scene-anchored concepts into workspace with high salience
        for _sc in self.active_scene.scene_concepts():
            if _sc not in self._concepts:
                self._concepts.append(_sc)
            self._bump_salience(_sc, 0.7)  # scene anchors resist displacement

        # ── 11. Meta-cognition ────────────────────────────────
        META_INTERVAL = 600  # every ~12s at 48Hz (was 180 = ~3.75s)
        if self._tick - self._last_meta_tick >= META_INTERVAL:
            self.meta.tick()
            meta_t = self.meta.meta_thought(sm)
            if meta_t:
                self.stream.append(f"[META] {meta_t}")
                self._conclusions.append(meta_t)
                # Inject into PFC to drive curiosity
                brain.inject_text_input(meta_t)
                # Record as "meta" (NOT "insight") so comm_drive is NOT triggered.
                # This prevents the 180-tick meta_thought loop that spammed identical messages.
                self.episodic.record(brain.tick_count, "meta", meta_t[:100], em_desc)
                # Feed knowledge gaps directly into web sensor interest queue
                if brain._use_web:
                    for gap in self.meta.gaps(3):
                        brain._web_enc.add_interest_topic(gap.capitalize())

            # ── Recursive meta-reflection: think about recent thought patterns ──
            if len(self.stream) >= 5:
                reflect_t = self.meta.reflect_on_stream(list(self.stream)[-10:])
                if reflect_t:
                    self.stream.append(reflect_t)
                    brain.inject_text_input(reflect_t)
                    self.episodic.record(
                        brain.tick_count, "reflect", reflect_t[:100], em_desc
                    )
                    # Fix 6: meta-cognition actively modifies behaviour
                    rl = reflect_t.upper()
                    if "REPETITION" in rl or "CIRCULAR" in rl or "REFLECT" in rl:
                        # Detected loop — break it by boosting exploration
                        self._exploration_rate = min(1.0, self._exploration_rate + 0.15)
                        self.drives.information_hunger = min(
                            1.0, self.drives.information_hunger + 0.12
                        )
                    elif (
                        "CONFUSION" in rl or "INCONSISTENCY" in rl or "CONTRADICT" in rl
                    ):
                        # Detected confusion — consolidate
                        self.drives.coherence_need = min(
                            1.0, self.drives.coherence_need + 0.18
                        )
                        state.goal = "consolidate"
                        self._last_goal_chg = self._tick

            # ── 11b. Belief quality critique ──────────────────────────────────
            belief_critique = self.meta.critique_beliefs(self.belief_store)
            if belief_critique:
                self.stream.append(belief_critique)
                self.episodic.record(
                    brain.tick_count, "belief_critique", belief_critique[:120], em_desc
                )
                # Contradicted beliefs increase uncertainty
                self.self_model.uncertainty = min(
                    1.0, self.self_model.uncertainty + 0.05
                )

            # ── 11c. Decision quality meta-assessment ─────────────────────────
            dq_assessment = self.meta.decision_quality_assessment()
            if dq_assessment:
                self.stream.append(dq_assessment)
                self.episodic.record(
                    brain.tick_count, "meta_decision", dq_assessment[:120], em_desc
                )

            # ── 11d. Phase 4: Operative parameter tuning ──────────────────────
            tune_msg = self.meta.tune_parameters(self)
            if tune_msg:
                self.stream.append(tune_msg)
                self.episodic.record(
                    brain.tick_count, "meta_tune", tune_msg[:120], em_desc
                )

            # ── Intrinsic drives update ───────────────────────────────────────
            _new_c = max(0, len(self._concepts) - self._prev_concept_count)
            _n_gaps = len(self.meta.gaps(8))
            _ign_new = self._ignition_count - self._last_ign_for_drives
            self.drives.tick(em, _new_c, _n_gaps, _ign_new)
            self._prev_concept_count = len(self._concepts)
            self._last_ign_for_drives = self._ignition_count

            # ── Concept graph periodic decay ──────────────────────────────────
            if self._tick % 2400 == 0:
                self.concept_graph.decay()
                self._emotional_memory.decay()  # Fix 8: periodic emotion memory decay
                self.world_model.decay()
                self.belief_store.decay()

            # ── Belief store: learn from concept graph co-occurrence ───────────
            self.belief_store.learn_from_concept_graph(self.concept_graph)

            # Autobiographical consolidation — synthesise a narrative chapter
            chapter = self.autobiography.consolidate(
                brain.tick_count, sm, self.episodic
            )
            if chapter:
                self.stream.append(f"[BIOG] {chapter}")
                self.episodic.record(
                    brain.tick_count, "biography", chapter[:120], em_desc
                )
                # Feed back into self_model so identity summary is current
                sm.known_strengths = self.meta.strengths(4)
                # Phase 2: derive personal guidelines from patterns
                guide_msg = self.autobiography.derive_guidelines(brain.tick_count)
                if guide_msg:
                    self.stream.append(guide_msg)
                    self.episodic.record(
                        brain.tick_count, "guideline", guide_msg[:120], em_desc
                    )

            # Phase 2: track identity consistency every tick
            self.autobiography.track_consistency(state.goal, em.dominant())
            sm.identity_stability = self.autobiography.identity_consistency

            # ── Autobiographic regulation — chapters modulate drives/goals ──
            auto_reg = self.autobiography.regulate(sm, self.drives, self.goal_system)
            if auto_reg:
                self.stream.append(auto_reg)
                self.episodic.record(
                    brain.tick_count, "autobio_regulation", auto_reg[:120], em_desc
                )

            # Strategic meta-cognition — evaluate reliability + adapt strategy
            strat_msg = self.strategic_meta.tick(self, self.body)
            if strat_msg:
                self.stream.append(strat_msg)
                brain.inject_text_input(strat_msg)
                self.episodic.record(
                    brain.tick_count, "strategy", strat_msg[:100], em_desc
                )

            # ── Phase 7: Architecture-verification module outputs ─────────
            # Integration probe: run perturbation test and log result
            if brain.tick_count % 300 == 0:
                _probe_regions = list(brain.region_activity.keys())
                if _probe_regions:
                    _p_res = self.integration_probe.run_perturbation_test(
                        brain, _probe_regions[0], brain.tick_count
                    )
                    if _p_res:
                        self.stream.append(
                            f"[INTEG] {self.integration_probe.describe()}"
                        )
                        self.episodic.record(
                            brain.tick_count,
                            "integration_probe",
                            self.integration_probe.describe()[:120],
                            em_desc,
                        )

            # Temporal consistency: check CF engine trait coherence
            if brain.tick_count % 400 == 0:
                _cons_r = self.cf_engine.check_temporal_consistency(brain.tick_count)
                if not _cons_r.consistent:
                    self.stream.append(
                        f"[CF-CONS] Temporal inconsistency detected: "
                        f"score={_cons_r.consistency_score:.2f} "
                        f"contradicted={_cons_r.contradicted_traits[:3]}"
                    )
                    self.episodic.record(
                        brain.tick_count,
                        "cf_inconsistency",
                        f"score={_cons_r.consistency_score:.2f} "
                        f"contradicted={_cons_r.contradicted_traits[:3]}",
                        em_desc,
                    )
                # Declare knowledge gaps as explicit unknowns to calibrator
                for _gap in self.meta.gaps(2):
                    self.metacog_calib.declare_unknown(_gap)

            # Metacog calibrator: emit report every 600 ticks
            if brain.tick_count % 600 == 0:
                _cal_rep = self.metacog_calib.self_error_report(brain.tick_count)
                if _cal_rep.overconfidence > 0.15 or _cal_rep.flagged_claim_types:
                    self.stream.append(
                        f"[CALIB] {_cal_rep.notes.strip()} "
                        f"acc={_cal_rep.accuracy:.2f} "
                        f"ECE={_cal_rep.calibration_error:.3f}"
                    )
                    self.episodic.record(
                        brain.tick_count,
                        "calib_report",
                        f"overconf={_cal_rep.overconfidence:+.2f} "
                        f"acc={_cal_rep.accuracy:.2f}",
                        em_desc,
                    )

                # ENFORCEMENT 7: Metacognitive correction assertion.
                # If ECE is above 0.15 and uncertainty has NOT increased since
                # the previous calibration window, the metacognitive channel
                # is not correcting — force an uncertainty bump and log the gap.
                _ece_now = self.metacog_calib.expected_calibration_error()
                if _ece_now > 0.15:
                    if sm.uncertainty < max(0.0, _ece_now - 0.05):
                        sm.uncertainty = min(
                            1.0, sm.uncertainty + (_ece_now - 0.10) * 0.5
                        )
                        self.stream.append(
                            f"[METACOG-CORRECTION-FORCED] ECE={_ece_now:.3f} "
                            f"uncertainty forced to {sm.uncertainty:.3f} "
                            f"\u2192 metacognition must correct, not ignore overconfidence"
                        )

                # Agency summary — authoritative signal from SelfModel
                self.stream.append(
                    f"[AGENCY] conf={sm.agency_confidence:.2f}"
                    f" cont={sm.continuity_estimate:.2f}"
                    f" stab={sm.identity_stability:.2f}"
                )
                self.stream.append(f"[GATEWAY] {self.gateway.describe_access_state()}")
                self.stream.append(f"[GOAL-POOL] {self.goal_synth.pool_summary()}")
                self.stream.append(f"[TRAITS] {self.cf_engine.trait_summary()}")

            # ── Phase 5: Continuity monitoring — self-preservation alarms ──
            cont_alarm = self.continuity.tick(
                sm, self.autobiography, self.episodic, self.body
            )
            if cont_alarm:
                self.stream.append(cont_alarm)
                self.episodic.record(
                    brain.tick_count, "continuity_alarm", cont_alarm[:120], em_desc
                )
                # Boost consolidation drive when continuity is threatened
                self.drives.coherence_need = min(1.0, self.drives.coherence_need + 0.2)
                # Signal brain to prioritize targeted sleep consolidation
                brain._continuity_fragile = self.continuity.fragile_segments
                # Record pattern for long-horizon goal generation
                self.long_horizon.record_pattern("continuity_alarm")

            # ── Phase 1-5: New module periodic updates ────────────────────
            # Value model: TD step using current state
            _social_p = self.embodied_self.social_presence
            _val_sig = build_state_signature(
                state.goal,
                em.dominant(),
                _social_p,
                self.body.energy_reserve,
                len(self._concepts),
                self._current_focus,
            )

            # 3.16 — Reward → value model: each executive outcome triggers its own
            # goal-specific TD update so multi-outcome ticks are all captured.
            # State signature is goal-specific to avoid conflating different intents.
            for _oc in self._last_outcomes:
                _oc_sig = build_state_signature(
                    _oc.intent,
                    em.dominant(),
                    _social_p,
                    self.body.energy_reserve,
                    len(self._concepts),
                    _oc.target_person or self._current_focus,
                )
                self.value_model.update(
                    _oc_sig, _oc.reward, _val_sig, tick=brain.tick_count
                )

            # Background TD step for current state (fall back to valence when no outcomes)
            _any_outcome = bool(self._last_outcomes)
            _oc_reward = self._last_outcomes[-1].reward if _any_outcome else 0.0
            _val_reward = (
                _oc_reward * 0.5 + em.valence() * 0.2
                if _any_outcome
                else em.valence() * 0.3 + (0.2 if state.ignition else 0.0)
            )

            # 4.5 — TD error → self_model surprise: large TD errors are felt as surprise
            _td_err = self.value_model.step(_val_sig, _val_reward, brain.tick_count)
            if abs(_td_err) > 0.3:
                sm.uncertainty = min(1.0, sm.uncertainty + abs(_td_err) * 0.12)
                em.surprise = min(1.0, em.surprise + abs(_td_err) * 0.15)
                if abs(_td_err) > 0.6:
                    self.stream.append(
                        f"[VALUE] Unexpected outcome: TD-error={_td_err:+.2f} "
                        f"state={state.goal}"
                    )

            # ── policy_error: intent-specific expected vs observed world change ──
            # For each outcome, compute gap between predicted and actual
            # world change, then feed into self_model, world_model, strategic_meta.
            for _oc in self._last_outcomes:
                _pred_delta, _pred_conf = self.world_model.predict(
                    _oc.intent, _oc.executed_skill
                )
                _actual_reward = _oc.reward
                if _pred_conf > 0.05:
                    _policy_err = abs(_pred_delta - _actual_reward)
                    # Feed policy error into agency score
                    sm.agency_score = max(
                        -1.0,
                        min(
                            1.0,
                            sm.agency_score
                            - _policy_err * 0.15
                            + (0.1 if _oc.success else -0.1),
                        ),
                    )
                    # Feed into strategic meta for reliability tracking
                    self.strategic_meta.observe_prediction(_pred_delta, _actual_reward)
                    # Record in causal graph
                    if _oc.target_person:
                        self.causal_graph.record_skill_transition(
                            TransitionRecord(
                                tick=brain.tick_count,
                                state_signature=f"policy:{_oc.intent}:{_oc.target_person}",
                                action_kind=_oc.executed_skill,
                                action_args={"target": _oc.target_person},
                                predicted_outcome=str(_pred_delta),
                                observed_outcome=str(_actual_reward),
                                reward=_actual_reward,
                                surprise=_policy_err,
                                success=_oc.success,
                                involved_persons=[_oc.target_person],
                            )
                        )

            # ── Step-based identity observation ──
            # Identity learns from patterns within skill steps, not just goals
            for _se in self._last_step_events:
                if _se.status in ("succeeded", "failed"):
                    self.identity_arc.observe_step(
                        brain.tick_count,
                        _se.skill_name,
                        _se.step_index,
                        success=(_se.status == "succeeded"),
                        goal_intent=_se.goal_intent,
                    )

            # Identity arc: observe current state and periodically self-evaluate
            # Real decision quality: did the executive actually succeed?
            _decision_ok = (
                any(_oc.success for _oc in self._last_outcomes)
                if self._last_outcomes
                else (state.goal == self.state.goal)
            )
            self.identity_arc.observe(
                brain.tick_count,
                em,
                state.goal,
                _social_p,
                _decision_ok,
                list(self._concepts)[-8:],
            )
            id_eval = self.identity_arc.self_evaluate(brain.tick_count)
            if id_eval:
                self.stream.append(f"[IDENTITY] {id_eval}")
                self.episodic.record(
                    brain.tick_count, "identity_eval", id_eval[:120], em_desc
                )

            # Narrative thread: observe and try closing chapters
            # Real success: executive outcome > proxy (rest+low_fatigue / ignition)
            _goal_succeeded = (
                any(_oc.success for _oc in self._last_outcomes)
                if self._last_outcomes
                else (state.goal == "rest" and em.fatigue < 0.3) or state.ignition
            )
            self.narrative_thread.observe_tick(
                brain.tick_count,
                state.goal,
                em.dominant(),
                list(self._concepts)[-5:],
                success=_goal_succeeded,
                person_ids=[str(p) for p in _visible_pids[:3]] if _visible_pids else [],
                event_type=state.goal,
            )
            # Step-based narrative: accumulate skill episodes into the chapter
            for _se in self._last_step_events:
                if _se.status in ("succeeded", "failed"):
                    self.narrative_thread.observe_skill_event(
                        brain.tick_count,
                        _se.skill_name,
                        _se.status,
                        _se.goal_intent,
                        person_id=_se.target_person,
                    )
            _chapter = self.narrative_thread.try_close_chapter(brain.tick_count)
            if _chapter is not None:
                _ch_desc = (
                    _chapter.describe()
                    if hasattr(_chapter, "describe")
                    else str(_chapter)
                )
                self.stream.append(f"[NARRATIVE] {_ch_desc}")
                self.episodic.record(
                    brain.tick_count, "narrative_chapter", _ch_desc[:120], em_desc
                )

                # ── Narrative → Rebuild: chapter closure drives self-modification ──
                # 1. Lessons become meta-goals / identity adjustments
                for _lesson in getattr(_chapter, "lessons", []):
                    self.identity_arc.set_meta_goal(_lesson, brain.tick_count)
                    if not any(
                        gl.text == _lesson for gl in self.autobiography._guidelines
                    ):
                        self.autobiography._guidelines.append(
                            PersonalGuideline(
                                text=_lesson,
                                source="narrative_lesson",
                                strength=0.5,
                                tick_born=brain.tick_count,
                            )
                        )

                # 2. Turning points shift identity dimensions more strongly
                if getattr(_chapter, "turning_point", False):
                    _ch_emo = getattr(_chapter, "dominant_emotion", "")
                    if _ch_emo in ("stress", "anger"):
                        self.identity_arc.error_shift("strategy_failure", 0.8)
                    elif _ch_emo in ("joy", "calm"):
                        dim = self.identity_arc.dimensions.get("self_confidence")
                        if dim:
                            dim.update(0.8, lr=0.01)
                    self.stream.append(
                        f"[IDENTITY] Turning point shifts identity: {_ch_emo}"
                    )
                    # Record pattern for long-horizon goal spawning
                    self.long_horizon.record_pattern("turning_point", _ch_emo)

                # 3. Repeated chapter types generate long-horizon goals
                _recent_chs = self.narrative_thread.recent_chapters(5)
                _type_counts: Dict[str, int] = {}
                for _rch in _recent_chs:
                    _type_counts[_rch.chapter_type] = (
                        _type_counts.get(_rch.chapter_type, 0) + 1
                    )
                for _ct, _cc in _type_counts.items():
                    if _cc >= 3:
                        _existing = [
                            g.description for g in self.long_horizon.active_goals()
                        ]
                        _desc = f"Address recurring {_ct} pattern"
                        if not any(_desc in e for e in _existing):
                            self.long_horizon.add_goal(
                                _desc, category=_ct, priority=6, tick=brain.tick_count
                            )
                            self.stream.append(
                                f"[LONG-GOAL] Born from narrative: {_desc}"
                            )

                # 4. Relationship events update Theory of Mind
                for _pid in getattr(_chapter, "persons_involved", []):
                    self.narrative_thread.record_relationship_event(
                        brain.tick_count, _pid, em.valence(), _chapter.chapter_type
                    )

            # Theory of mind: feed interaction data
            if _primary_pid:
                _sm_obj = getattr(brain, "_social_manager", None)
                _sm_summary = _sm_obj.social_summary() if _sm_obj else {}
                _eng_val = (
                    _sm_summary.get("engagement", 0.5)
                    if isinstance(_sm_summary, dict)
                    else 0.5
                )
                _heard = len(brain.speech_in.split()) if brain.speech_in else 0
                self.theory_of_mind.observe_interaction(
                    brain.tick_count,
                    _primary_pid,
                    spoke=bool(brain.speech_in),
                    words_heard=_heard,
                    engagement=_eng_val,
                    valence=em.valence(),
                    topics=list(self._concepts)[-3:],
                )

            # Belief quarantine: periodic review — promoted beliefs enter active store
            bq_changes = self.belief_quarantine.review(brain.tick_count)
            for _bq_topic, _bq_status in bq_changes:
                self.stream.append(f"[BELIEF] {_bq_topic} → {_bq_status}")
                # Promoted beliefs: parse topic key and store in BeliefStore
                if _bq_status == "promoted" and ":" in _bq_topic:
                    _parts = _bq_topic.split(":", 2)
                    if len(_parts) == 3:
                        self.belief_store._store(
                            _parts[0],
                            _parts[1],
                            _parts[2],
                            confidence=0.7,
                            source="quarantine_promoted",
                            tick=brain.tick_count,
                        )

            # Attention controller: tick decay + set goal-driven priorities
            self.attention_ctrl.tick()
            if self._current_focus:
                self.attention_ctrl.set_priority(
                    self._current_focus,
                    0.6,
                    "goal",
                    reason=f"goal:{state.goal}",
                    tick=brain.tick_count,
                )
            # Evaluate attention utility: did recent focus reduce surprise?
            _ws_pred = getattr(
                getattr(brain, "_world_state", None), "prediction_summary", None
            )
            _cur_surprise = _ws_pred.max_surprise if _ws_pred else 0.0
            _goal_succ = 1.0 if state.goal == self._prev_goal else 0.5
            self.attention_ctrl.evaluate_utility(
                _cur_surprise, _goal_succ, brain.tick_count, eval_window=40
            )

            # Long-horizon goals: tick + process due reviews
            lh_actions = self.long_horizon.tick(brain.tick_count)
            for lh_act in lh_actions:
                self.stream.append(f"[LONG-GOAL] {lh_act}")
                self.episodic.record(
                    brain.tick_count, "long_horizon", lh_act[:120], em_desc
                )

            # Long-horizon: bridge executive outcomes to milestones
            if self._last_outcomes:
                for _lh_gc in self.long_horizon.active_goals():
                    for _ms_i, _ms in enumerate(_lh_gc.milestones):
                        if _ms.completed:
                            continue
                        for _oc in self._last_outcomes:
                            if not _oc.success:
                                continue
                            # Primary match: executable_intent matches outcome intent/skill
                            _matched = False
                            if _ms.executable_intent:
                                _matched = (
                                    _oc.intent == _ms.executable_intent
                                    or _oc.executed_skill == _ms.executable_intent
                                )
                            # Fallback: text-similarity match (legacy milestones without intent)
                            if not _matched:
                                _ms_lower = _ms.description.lower()
                                _matched = (
                                    _oc.intent in _ms_lower
                                    or _oc.executed_skill in _ms_lower
                                )
                            if _matched:
                                _lh_gc.complete_milestone(_ms_i, brain.tick_count)
                                _lh_gc.reinforce_commitment(0.05)
                                self.stream.append(
                                    f"[LONG-GOAL] Milestone done: "
                                    f"{_ms.description[:50]}"
                                )
                                self.episodic.record(
                                    brain.tick_count,
                                    "milestone_complete",
                                    f"{_lh_gc.goal_id}:{_ms.description[:80]}",
                                    em_desc,
                                )
                                break

            # Long-horizon: conduct due reviews
            for _lh_gc in self.long_horizon.active_goals():
                for _rp in _lh_gc.due_reviews(brain.tick_count):
                    _done_ms = sum(1 for m in _lh_gc.milestones if m.completed)
                    _total_ms = len(_lh_gc.milestones) or 1
                    _progress_pct = _done_ms / _total_ms
                    if _progress_pct > 0.5:
                        _outcome = (
                            f"good progress ({_progress_pct:.0%}), "
                            f"reinforcing commitment"
                        )
                        _lh_gc.reinforce_commitment(0.03)
                    elif _progress_pct > 0.1:
                        _outcome = (
                            f"some progress ({_progress_pct:.0%}), " f"maintaining"
                        )
                    else:
                        _outcome = (
                            f"stalled ({_progress_pct:.0%}), "
                            f"considering re-prioritisation"
                        )
                        _lh_gc.erode_commitment(0.02)
                    _lh_gc.complete_review(_rp.review_tick, _outcome)
                    _lh_gc.add_journal(f"Review: {_outcome}")
                    # Schedule next review
                    _lh_gc.schedule_review(
                        brain.tick_count + self.long_horizon.REVIEW_INTERVAL,
                        _rp.criteria,
                    )
                    self.stream.append(
                        f"[LONG-GOAL] Review {_lh_gc.goal_id}: {_outcome}"
                    )
                    self.episodic.record(
                        brain.tick_count,
                        "long_horizon_review",
                        f"{_lh_gc.goal_id}: {_outcome[:80]}",
                        em_desc,
                    )

            # Record meta-cognitive patterns for auto-goal generation
            _gaps = self.meta.gaps(3)
            for _gap in _gaps:
                self.long_horizon.record_pattern("knowledge_gap", _gap)

            # 2.4 — Meta/gaps → short-term explore goal: when knowledge gaps accumulate,
            # spawn an immediate explore goal targeting the most critical gap
            _exec_ref = getattr(brain, "_task_executive", None)
            if _exec_ref is not None and len(_gaps) >= 2:
                _gap_topic = _gaps[0].replace(" ", "_")[:30]
                _explore_intent = "explore"
                # Only spawn if no explore is already queued/active
                _already_exploring = (
                    _exec_ref.active_goal is not None
                    and _exec_ref.active_goal.intent == _explore_intent
                ) or any(g.intent == _explore_intent for g in _exec_ref._goal_queue)
                if not _already_exploring:
                    _exec_ref.submit_goal(
                        _explore_intent,
                        context=f"gap_driven:{_gap_topic}",
                        tick=brain.tick_count,
                        world=getattr(brain, "_world_state", None),
                    )
                    self.stream.append(f"[META] Explore goal from gap: {_gaps[0]}")

            # Auto-generate long-horizon goals from accumulated patterns
            _spawned = self.long_horizon.detect_and_spawn_goals(brain.tick_count)
            for _sp in _spawned:
                self.stream.append(f"[LONG-GOAL] Auto-born: {_sp}")
                self.episodic.record(
                    brain.tick_count, "long_horizon_auto", _sp[:120], em_desc
                )

            # ── Long-horizon → TaskExecutive: milestone submit_goal bridge ──
            # For each active long-horizon goal, push the next executable
            # milestone into the TaskExecutive when that intent is not yet
            # queued or active.  This makes LH goals drive concrete action
            # rather than just decaying in a list.
            _lh_exec = getattr(brain, "_task_executive", None)
            if _lh_exec is not None:
                _queued_intents: set = set()
                if _lh_exec.active_goal is not None:
                    _queued_intents.add(_lh_exec.active_goal.intent)
                for _qg in _lh_exec._goal_queue:
                    _queued_intents.add(_qg.intent)
                for _lh_gc_ms in self.long_horizon.active_goals():
                    _next_ms = self.long_horizon.next_executable_milestone(_lh_gc_ms.goal_id)
                    if _next_ms is None:
                        continue
                    if _next_ms.executable_intent in _queued_intents:
                        continue
                    # Submit the milestone intent; low priority so it doesn't
                    # pre-empt urgent social or safety tasks
                    try:
                        from task_executive import GoalPriority as _GP
                        _lh_exec.submit_goal(
                            _next_ms.executable_intent,
                            context=f"lh:{_lh_gc_ms.goal_id}:{_lh_gc_ms.description[:40]}",
                            tick=brain.tick_count,
                            world=getattr(brain, "_world_state", None),
                        )
                        _queued_intents.add(_next_ms.executable_intent)
                        self.stream.append(
                            f"[LONG-GOAL] Milestone submitted: "
                            f"{_next_ms.executable_intent} "
                            f"({_lh_gc_ms.goal_id})"
                        )
                    except Exception:
                        pass

            # ── Long-horizon: resume paused goals when person reappears ──
            # Social obligations and interrupted goals resume when the linked
            # person becomes the primary interlocutor.
            _sm_lh_resume = getattr(brain, "_social_manager", None)
            _resume_pid = _sm_lh_resume.primary_interlocutor() if _sm_lh_resume else None
            if _resume_pid is not None:
                _resume_cands = self.long_horizon.resume_candidates(
                    brain.tick_count, person_id=_resume_pid, min_pause_ticks=200
                )
                for _rc in _resume_cands:
                    if _rc.status == "paused":
                        self.long_horizon.resume_goal(_rc.goal_id, brain.tick_count)
                        self.stream.append(
                            f"[LONG-GOAL] Resumed: {_rc.description[:50]} "
                            f"(was paused {brain.tick_count - _rc.interrupted_tick} ticks)"
                        )
                        self.episodic.record(
                            brain.tick_count,
                            "long_horizon_resume",
                            f"{_rc.goal_id}: resumed",
                            em_desc,
                            person_id=_resume_pid,
                        )

            self._last_meta_tick = self._tick

        # ── 12. Personality update ────────────────────────────────────────
        self.personality.update(em)

        # ── 13. Communication drive ───────────────────────────────────────
        # Decision is made entirely from internal state — not random, not timed.
        spoke = self.comm_drive.tick(brain.tick_count, em, state, self)
        state.wants_to_speak = spoke
        if spoke and self.comm_drive.outbox:
            latest_msg = list(self.comm_drive.outbox)[-1]
            self.stream.append(latest_msg)
            self.episodic.record(brain.tick_count, "comm", latest_msg[:100], em_desc)

        # ── 14. Phase 6: Unified consciousness systems ───────────────────

        # 14a. Unified self-state: encode all sub-states into latent self-vector
        _action_enc = self.unified_self.action_encoding(state.goal)
        self.unified_self.predict_next(_action_enc)
        self.unified_self.encode(
            self.self_model,
            self.body,
            self.embodied_self,
            self.robot_state,
            self.task_frame,
            self.sensorimotor,
            em,
        )
        self.unified_self.observe_actual(brain.tick_count)
        self.unified_self.compute_unity(self.self_model, self.body, self.sensorimotor)
        # Temporal stasis penalty: when world is absent the self-vector stops
        # changing, cosine-similarity ≈ 1.0 — falsely signalling high unity.
        # Attenuate unity_score proportionally to sensor-deprivation depth so
        # an internally static (but world-disconnected) system still collapses.
        _sft_unity = getattr(brain, "_sensor_free_ticks", 0)
        if _sft_unity > 30:
            _stasis_gate = max(0.0, 1.0 - min(1.0, _sft_unity / 300.0))
            self.unified_self.unity_score = max(
                0.0, self.unified_self.unity_score * _stasis_gate
            )
        self.unified_self.update_ownership(self.body, self.sensorimotor)
        # 14a-bis. Agency attribution: did I cause observed changes?
        if self._last_outcomes:
            for _oc in self._last_outcomes:
                _observed_delta = _oc.reward
                self.unified_self.update_agency(
                    _oc.intent, _observed_delta, self.sensorimotor
                )
            # Low agency → coherence alarm ("world changed without me")
            if self.unified_self.agency_belief < 0.3:
                self.drives.coherence_need = min(1.0, self.drives.coherence_need + 0.05)
            # High agency → more willing to speak about own actions
            if self.unified_self.agency_belief > 0.7:
                self.drives.expression_pressure = min(
                    1.0, self.drives.expression_pressure + 0.02
                )
        else:
            # No observable outcomes → world is not responding.
            # agency_belief components are only stepped via update_agency();
            # without outcomes they stay frozen at their last value indefinitely.
            # Passive 3 %/tick decay drives them toward 0 in ~100 ticks,
            # matching the sensor-deprivation structural collapse requirement.
            _us = self.unified_self
            _us.bodily_agency = max(0.0, _us.bodily_agency * 0.97)
            _us.instrumental_agency = max(0.0, _us.instrumental_agency * 0.97)
            _us.agency_belief = 0.4 * _us.bodily_agency + 0.6 * _us.instrumental_agency
        # Feed self-prediction error back into consciousness state
        if self.unified_self.self_prediction_error > 0.4:
            self.self_model.uncertainty = min(
                1.0,
                self.self_model.uncertainty
                + self.unified_self.self_prediction_error * 0.08,
            )
        if (
            self.unified_self.self_prediction_error > 0.55 or em.surprise > 0.78
        ) and brain.tick_count - self._last_proactive_self_report_tick > 240:
            _lk_sr = getattr(self.lang, "current", "de")
            if _lk_sr == "de":
                _spont = (
                    f"Ich muss mein Selbstmodell gerade nachkalibrieren: "
                    f"Selbstfehler={self.unified_self.self_prediction_error:.2f}, "
                    f"Überraschung={em.surprise:.2f}."
                )
            else:
                _spont = (
                    f"I need to recalibrate my self-model right now: "
                    f"self-error={self.unified_self.self_prediction_error:.2f}, "
                    f"surprise={em.surprise:.2f}."
                )
            _spont = self._socialize_proactive_self_report(
                _spont,
                min(1.0, self.unified_self.self_prediction_error + em.surprise * 0.5),
            )
            self.self_model.last_action_self_report = _spont
            self._pending_proactive_self_report = _spont
            self._pending_proactive_self_report_strength = max(
                self._pending_proactive_self_report_strength,
                min(1.0, self.unified_self.self_prediction_error + em.surprise * 0.5),
            )
        # Feed unity disruption into continuity alarm
        if self.unified_self.unity_score < 0.4:
            self.drives.coherence_need = min(1.0, self.drives.coherence_need + 0.1)

        # 14b. Phenomenal buffer: integrate multi-modal experience
        _v_sal = salience.get("sensory_visual", 0.0)
        _a_sal = salience.get("sensory_auditory", 0.0)
        _w_sal = salience.get("sensory_web", 0.0)
        self.phenomenal_buffer.integrate(
            _v_sal,
            _a_sal,
            _w_sal,
            em,
            self.body,
            self.unified_self,
            self._current_focus,
        )

        _self_awareness_note = self.self_model.update_self_consciousness(
            brain.tick_count,
            self.unified_self,
            self.body,
            self.phenomenal_buffer,
            current_goal=state.goal,
        )
        if _self_awareness_note and (
            self.self_model.self_tensions or self._tick % 240 == 0
        ):
            self.stream.append(f"[SELF-AWARE] {_self_awareness_note}")
            if self.self_model.self_tensions:
                self.episodic.record(
                    brain.tick_count,
                    "self",
                    _self_awareness_note[:140],
                    em_desc,
                )

        # 14b-bis. Phenomenal buffer as CONTROL signal ──────────────────
        # High experiential change → attention re-prioritisation + drive boost
        _exp_change = self.phenomenal_buffer.experiential_change
        if _exp_change > 0.10:
            # Significant experiential shift → boost attention to the focus
            # region that caused it, and raise expression pressure for
            # self-report / consolidation.
            self.attention_ctrl.boost(self._current_focus, min(0.3, _exp_change))
            self.drives.expression_pressure = min(
                1.0, self.drives.expression_pressure + _exp_change * 0.15
            )
            if _exp_change > 0.20:
                # Major experiential shift → consolidation drive
                self.drives.coherence_need = min(
                    1.0, self.drives.coherence_need + _exp_change * 0.10
                )

        # 14c. Grounded semantics: observe body context for active concepts
        _active_concepts = list(self._concepts)[-8:]
        if _active_concepts and self._prev_body_snapshot:
            self.grounded_memory.observe_body_context(
                _active_concepts, self.body, self._prev_body_snapshot, brain.tick_count
            )
        # Observe sensory context when visual entities are present
        _vis_ents = self.embodied_self.visible_entities
        if _vis_ents and _active_concepts:
            self.grounded_memory.observe_sensory_context(
                _active_concepts, "visual", _vis_ents[:5], brain.tick_count
            )
        # Observe social context when social presence detected
        if self.embodied_self.social_presence > 0.3 and _active_concepts:
            _social_delta = em.valence()
            self.grounded_memory.observe_social_context(
                _active_concepts, state.goal, _social_delta, brain.tick_count
            )
        # Snapshot body for next tick delta computation
        self._prev_body_snapshot = {
            "energy": self.body.energy_reserve,
            "thermal": self.body.thermal_load,
            "integrity": self.body.integrity,
        }

        # 14d. Learned world model (RSSM): step with current observation
        _ws_for_rssm = getattr(brain, "_world_state", None)
        _rssm_obs = self.learned_world.encode_observation(
            em, self.body, self.embodied_self, self.task_frame, _ws_for_rssm
        )
        _rssm_action = self.learned_world.encode_action(state.goal)
        _rssm_reward = em.valence() * 0.5
        # Use real executive rewards when available
        if self._last_outcomes:
            _rssm_reward = sum(_oc.reward for _oc in self._last_outcomes) / len(
                self._last_outcomes
            )
        self.learned_world.step(_rssm_obs, _rssm_action, _rssm_reward)

        # 14e. Periodic logging of new system states
        if self._tick % 600 == 0:
            self.stream.append(f"[UNIFIED] {self.unified_self.describe()}")
            self.stream.append(
                f"[PHENOM] {self.phenomenal_buffer.experiential_signature()}"
            )
            self.stream.append(f"[RSSM] {self.learned_world.describe()}")
            _grnd = self.grounded_memory.grounding_summary()
            if _grnd:
                self.stream.append(f"[GROUND] {_grnd}")

        self.state = state
        return state

    # ── Global broadcast ───────────────────────────────────────

    def _global_broadcast(self, brain: "Brain") -> None:
        """
        Salience-based global broadcast (Global Workspace Theory).

        Regions sorted by composite salience, not raw activity.
        The currently focused region gets an additional inertia bonus so
        the spotlight doesn't flip randomly between frames — it moves only
        when a sufficiently dominant competitor emerges (Fix 1 + Fix 10).
        """
        arousal = brain.emotion_state.arousal()
        focus = self._current_focus
        top_n = max(2, IGNITION_REGIONS)

        # Sort by salience: focused region gets inertia boost
        ranked = sorted(
            brain._all_regions,
            key=lambda r: (
                brain.region_activity.get(r.name, 0.0) * 0.6
                + (0.4 * self._focus_salience if r.name == focus else 0.0)
            ),
            reverse=True,
        )

        for i, region in enumerate(ranked):
            exc = region.excitatory
            if not exc:
                continue
            focus_boost = 1.3 if region.name == focus else 1.0
            if i < top_n:
                # Winner-take-more: arousal-amplified + focus stability bonus
                strength = (
                    BROADCAST_CURRENT
                    * (1.0 + arousal * 0.8)
                    * (1.0 - i * 0.15)
                    * focus_boost
                )
            else:
                # Weak sustaining signal keeps non-dominant regions accessible
                strength = BROADCAST_CURRENT * 0.15
            n = min(5, len(exc))
            currents = [strength] * n + [0.0] * (len(exc) - n)
            region.inject(currents)

    # ── Engram tracking ────────────────────────────────────────

    def _update_engrams(self, brain: "Brain") -> None:
        """Count spikes from hippocampus + association cortex as engram traces."""
        for region in (brain.hippocampus, brain.assoc):
            fired = region._fired_this_tick
            for pos in region._exc_positions:
                if fired[pos]:
                    nid = region.neurons[pos].nid
                    self._engrams[nid] = self._engrams.get(nid, 0) + 1
        # Periodic decay — engrams fade unless recently reactivated
        if self._tick % 800 == 0:
            self._engrams = {k: v - 1 for k, v in self._engrams.items() if v > 1}

    # ── Memory replay ──────────────────────────────────────────

    def _replay(self, brain: "Brain") -> None:
        """
        Re-inject top engram neurons' spike currents into hippocampus
        and association cortex to consolidate stored memories.
        """
        top_nids = {
            nid
            for nid, _ in sorted(
                self._engrams.items(), key=lambda x: x[1], reverse=True
            )[:REPLAY_MAX_ENGRAMS]
        }

        hip_exc = brain.hippocampus.excitatory
        hip_cur = [3.5 if n.nid in top_nids else 0.0 for n in hip_exc]
        if any(c > 0 for c in hip_cur):
            brain.hippocampus.inject(hip_cur)

        asc_exc = brain.assoc.excitatory
        asc_cur = [2.5 if n.nid in top_nids else 0.0 for n in asc_exc]
        if any(c > 0 for c in asc_cur):
            brain.assoc.inject(asc_cur)

    # ── Concept management ─────────────────────────────────────

    def _extract_concepts(self, text: str, hipp: float = 0.0, pfc: float = 0.0) -> None:
        """Pull meaningful words from text into concept memory.

        Uses the global stopword list and picks up to 16 candidates sorted
        by length (longer words = more specific concepts) so the deque
        accumulates rich, distinct terms rather than common filler words.
        """
        words = re.findall(
            r"[a-zA-Z\u00e4\u00f6\u00fc\u00df][a-zA-Z\u00e4\u00f6\u00fc\u00df]{3,}",
            text,
        )
        # De-duplicate, filter stopwords, require length > 4
        candidates = sorted(
            {
                w.lower()
                for w in words
                if w.lower() not in _CONCEPT_STOPWORDS and len(w) > 4
            },
            key=len,
            reverse=True,
        )
        for wl in candidates[:16]:
            if wl not in self._concepts:
                self._concepts.append(wl)
                self._bump_salience(wl, 0.3)  # new concept = novelty bump
            self.meta.observe(wl, hipp, pfc)

    def _form_embodied_concepts(self, brain: "Brain", em: object) -> None:
        """Form concepts from recurring body/world patterns.

        Derives symbolic labels from world_state predicates and body state,
        then feeds them through the standard concept pipeline so they
        participate in reasoning, emotional memory, and concept graph.
        """
        ws = getattr(brain, "_world_state", None)
        if ws is None:
            return
        pred = ws.predicates
        formed: list[str] = []

        # Social-embodied patterns → concepts
        if pred.person_visible and pred.person_attentive:
            formed.append("social_engagement")
        if pred.person_visible and not pred.distance_safe:
            formed.append("proximity_alert")
        if pred.person_speaking:
            formed.append("dialogue_active")
        if pred.holds_object_left or pred.holds_object_right:
            formed.append("object_manipulation")
        if pred.gesture_active:
            formed.append("expressive_gesture")
        if pred.body_idle and pred.person_visible:
            formed.append("attentive_waiting")
        if pred.greeting_done and pred.engagement_level > 0.5:
            formed.append("rapport_established")

        # Emotional-body compound concepts
        dom = em.dominant() if hasattr(em, "dominant") else ""
        if dom == "stress" and not pred.distance_safe:
            formed.append("threatened_proximity")
        if dom == "curiosity" and pred.person_speaking:
            formed.append("curious_listening")
        if dom == "joy" and pred.gesture_active:
            formed.append("joyful_expression")

        # ── Referential world binding: concrete entity concepts ──
        # Persons — individual identity, role, zone
        for pid, person in ws.persons.items():
            formed.append(f"person:{pid}")
            if person.speaking:
                formed.append(f"speaker:{pid}")
            if person.gesture not in ("none", ""):
                formed.append(f"gesture:{pid}:{person.gesture}")
            formed.append(f"zone:{person.zone}")
        # Objects — specific labels
        for oid, obj in getattr(ws, "objects", {}).items():
            formed.append(f"object:{obj.label}")
        # Interaction zone summary
        if ws.zone.nearest_person_distance_cm < 999:
            if ws.zone.nearest_person_distance_cm < 60:
                formed.append("proxemic:close")
            elif ws.zone.nearest_person_distance_cm < 120:
                formed.append("proxemic:social")

        # Inject formed concepts into the standard pipeline
        for concept in formed:
            if concept not in self._concepts:
                self._concepts.append(concept)
            self.meta.observe(concept, self._hipp_act_ema, self._pfc_act_ema)
            # Embodied concepts are world-grounded → high salience
            self._bump_salience(concept, 0.6)

        # Teach the emotion system about these experiential concepts
        if (
            formed
            and hasattr(brain, "emotion")
            and hasattr(brain.emotion, "experience")
        ):
            brain.emotion.experience.observe(formed, em)

        # Emergent concept induction from predicate patterns
        arousal = em.arousal() if hasattr(em, "arousal") else 0.0
        pred_err_delta = getattr(self, "_prev_pred_error", 0.0)
        current_pred_err = getattr(self, "predictor", None)
        if current_pred_err:
            cur = (
                current_pred_err.tick_error
                if hasattr(current_pred_err, "tick_error")
                else 0.0
            )
            pred_err_delta = cur - getattr(self, "_prev_pred_error_val", 0.0)
            self._prev_pred_error_val = cur

        pred_dict = {
            "person_visible": pred.person_visible,
            "person_attentive": pred.person_attentive,
            "person_speaking": pred.person_speaking,
            "distance_safe": pred.distance_safe,
            "gesture_active": pred.gesture_active,
            "body_idle": pred.body_idle,
            "holds_object": pred.holds_object_left or pred.holds_object_right,
            "head_aligned": pred.head_aligned,
            "greeting_done": pred.greeting_done,
        }
        induced = self.concept_inductor.observe(pred_dict, arousal, pred_err_delta)
        if induced:
            self._concepts.append(induced)
            self.meta.observe(induced, self._hipp_act_ema, self._pfc_act_ema)

    def recall_for_person(self, person_id: int, brain: object = None, topic_tokens: Optional[frozenset] = None) -> Dict:
        """Retrieve all person-specific knowledge for consistent interaction.

        Returns episodic memories (relevance-scored), person model data,
        conflict/tone indicators, and memory-trust tiers.  All downstream
        behaviour — speech act, tone, topic choice — should be driven by
        the richer fields returned here.
        """
        current_tick = getattr(getattr(brain, "tick_count", None), "__int__", lambda: 0)()
        if not isinstance(current_tick, int):
            current_tick = int(getattr(brain, "tick_count", 0))

        # ── Scored episodic recall ────────────────────────────────────────
        scored_episodes = self.episodic.for_person_scored(
            person_id,
            current_tick=current_tick,
            n=20,
            topic_tokens=topic_tokens,
        )

        # Flat list for backward compatibility
        episodes = [ep for _, ep in scored_episodes]

        # Emotion frequency + dominance
        emotions: Dict[str, int] = {}
        for ep in episodes:
            if ep.emotion_snapshot:
                emo = ep.emotion_snapshot.lower()
                emotions[emo] = emotions.get(emo, 0) + 1
        dominant_past_emotion = max(emotions, key=emotions.get) if emotions else "unknown"

        # Conflict indicators
        _neg_emos = EpisodicMemory._NEGATIVE_EMOTIONS
        conflict_episodes = [ep for ep in episodes if (ep.emotion_snapshot or "").lower() in _neg_emos]
        conflict_count = len(conflict_episodes)
        conflict_ratio = conflict_count / max(len(episodes), 1)

        # Positive indicator
        _pos_emos = {"joy", "happiness", "trust", "anticipation", "freude", "vertrauen",
                     "neugier", "begeisterung", "zufriedenheit"}
        positive_count = sum(1 for ep in episodes if (ep.emotion_snapshot or "").lower() in _pos_emos)
        positive_ratio = positive_count / max(len(episodes), 1)

        # Tone bias: net sentiment tendency based on episode history
        if conflict_ratio > 0.35 and conflict_ratio > positive_ratio:
            tone_bias = "negative"
        elif positive_ratio > 0.35 and positive_ratio > conflict_ratio:
            tone_bias = "positive"
        else:
            tone_bias = "neutral"

        # Most recent conflict episode (for repair / de-escalation hints)
        recent_conflict_text = ""
        for ep in reversed(episodes):
            if (ep.emotion_snapshot or "").lower() in _neg_emos:
                recent_conflict_text = ep.describe()[:100]
                break

        # Top-5 weighted episodes as dicts with trust tier
        weighted_episodes: List[Dict] = []
        for score, ep in scored_episodes[:5]:
            tier = EpisodicMemory.memory_trust_tier(ep, current_tick)
            weighted_episodes.append({
                "score": round(score, 3),
                "trust_tier": tier,
                "text": ep.describe()[:120],
                "emotion": ep.emotion_snapshot or "",
                "tick": ep.tick,
            })

        result: Dict = {
            "person_id": person_id,
            "n_shared_episodes": len(episodes),
            "recent_episodes": [ep.describe() for ep in episodes[-5:]],
            "dominant_past_emotion": dominant_past_emotion,
            "weighted_episodes": weighted_episodes,
            "conflict_count": conflict_count,
            "conflict_ratio": round(conflict_ratio, 3),
            "positive_count": positive_count,
            "positive_ratio": round(positive_ratio, 3),
            "tone_bias": tone_bias,
            "recent_conflict_text": recent_conflict_text,
        }

        # Merge PersonModel data if available
        sm = getattr(brain, "_social_manager", None) if brain else None
        if sm is not None:
            pm = sm.person_model(person_id)
            if pm is not None:
                result.update(
                    {
                        "trust": pm.trust,
                        "familiarity": pm.familiarity,
                        "total_encounters": pm.total_encounters,
                        "avg_valence": pm.avg_valence,
                        "inferred_interests": pm.inferred_interests[:10],
                        "preferences": dict(
                            sorted(pm.preferences.items(), key=lambda x: -x[1])[:8]
                        ),
                        "last_interaction": (
                            pm.interaction_log[-1] if pm.interaction_log else "none"
                        ),
                        "relationship_type": getattr(pm, "relationship_type", "acquaintance"),
                    }
                )
            # Merge current conversation state
            conv = sm._conversations.get(person_id)
            if conv is not None:
                result.update(
                    {
                        "current_engagement": conv.engagement,
                        "current_rapport": conv.rapport,
                        "turn_state": conv.turn_state.value,
                        "turns_this_session": conv.turns_count,
                    }
                )
        return result

    # ── Reasoning ──────────────────────────────────────────────

    def _reason(self) -> Optional[str]:
        """
        Form an associative observation grounded in hippocampal memory.

        Primary path: use semantic recall to find what the hippocampus has
        actually learned is related to the current workspace — then reason
        about that real association.

        Fallback: meta-cognitive depth/familiarity analysis on random pair.
        """
        ws = self.workspace_concepts()
        brain_ref = getattr(self, "_brain_ref", None)

        # ── Primary: hippocampal recall guides concept pair ─────────────
        recalled = []
        if brain_ref is not None and ws:
            recalled = brain_ref.hippocampus.semantic_recall(ws, top_n=4)

        if recalled and ws:
            a = ws[-1]
            b = (
                recalled[0]
                if recalled[0] != a
                else (recalled[1] if len(recalled) > 1 else None)
            )
            if b is None:
                recalled = []  # fall through to random

        if not recalled or not ws:
            # ── Fallback: random concept sampling ───────────────────────
            pool = list(self._concepts)
            if len(pool) < 2:
                return None
            recent = pool[-min(12, len(pool)) :]
            a, b = random.sample(recent, 2)
            if a == b:
                return None

        depth_a = self.meta._depth.get(a, 0.0)
        depth_b = self.meta._depth.get(b, 0.0)
        fam_a = self.meta._familiarity.get(a, 0.0)
        fam_b = self.meta._familiarity.get(b, 0.0)
        gap_a = fam_a / max(depth_a, 0.01)
        gap_b = fam_b / max(depth_b, 0.01)

        # ── Tier 0: BeliefStore — causal chain, analogy, known assertion ─
        # Try multi-hop causal chain from `a`
        chain = self.belief_store.causal_chain(a, max_depth=4)
        if len(chain) >= 3:
            return (
                self.lang.inner_voice(
                    a,
                    "hypothesis",
                    chain[1:3],
                    "curiosity",
                    [],
                )
                + f"  ({' → '.join(chain[:4])})"
            )

        # Try analogy between a and b
        analogy_str = self.belief_store.analogy(a, b)
        if analogy_str:
            return self.lang.inner_voice(
                a, "assertion", [b], "curiosity", [("related_to", b, 0.7)]
            )

        # Try known proposition about `a`
        triples_a = self.belief_store.query(a, min_confidence=0.35)
        if triples_a:
            rel, obj, conf = triples_a[0]
            return self.lang.assertion(a, rel, obj)

        # Try known proposition about `b`
        triples_b = self.belief_store.query(b, min_confidence=0.35)
        if triples_b:
            rel, obj, conf = triples_b[0]
            return self.lang.assertion(b, rel, obj)

        # Case: memory says they are strongly associated — surface it
        if brain_ref is not None and recalled and b in recalled[:2]:
            sm = brain_ref.hippocampus._semantic_memory
            strength = sm.get(a.lower(), {}).get(b.lower(), 0.0)
            if strength > 1.0:
                return (
                    f"{a} and {b} are strongly co-encoded in memory "
                    f"(association strength {strength:.1f}) — genuine learned link."
                )

        # Case: one concept is a genuine gap (seen often, encoded poorly)
        if gap_a > 4 and gap_b <= 2:
            return f"{a} surfaces repeatedly but lacks integration — {b} may provide a bridging context."
        if gap_b > 4 and gap_a <= 2:
            return (
                f"{b} appears frequently but understanding is shallow compared to {a}."
            )

        # Case: both are shallow → note the shared uncertainty
        if gap_a > 3 and gap_b > 3:
            return f"Both {a} and {b} have high exposure but low encoding depth — unclear relationship."

        # Case: one is much more deeply encoded
        if depth_a > 0.1 and depth_b > 0.1:
            if depth_a > depth_b * 1.8:
                return f"{a} is strongly encoded relative to {b}; {b} may depend on {a} for context."
            if depth_b > depth_a * 1.8:
                return f"{b} shows deeper hippocampal trace than {a} — {a} is the less-integrated concept."
            if abs(depth_a - depth_b) / max(depth_a, depth_b) < 0.2:
                return f"{a} and {b} have near-identical encoding depth — probable co-activation history."

        # Case: concept graph reveals a bridging concept
        bridge = self.concept_graph.bridge_concepts(a, b)
        if bridge:
            return (
                f"{bridge} mediates the connection between {a} and {b} "
                f"(graph-based inference from co-occurrence history)."
            )

        # Case: reference episodic memory that contained both
        if brain_ref is not None:
            eps = brain_ref.hippocampus.recall_episodes([a, b], top_n=1)
            if eps:
                _tick, ep_concepts, ep_emotion = eps[0]
                ep_str = ", ".join(ep_concepts[:4])
                return f"Episodic memory ({ep_emotion}): {ep_str} — {a} and {b} co-occurred."

        last_ep = self.episodic.last_of_kind("concept")
        if last_ep and (a in last_ep.content.lower() or b in last_ep.content.lower()):
            snip = last_ep.content[:55].rstrip()
            return f"'{snip}' — both {a} and {b} appear active in this context."

        # Fallback: use LanguageProducer to generate a grounded observation
        _dom = (
            brain_ref.emotion_state.dominant() if brain_ref is not None else "curiosity"
        )
        return self.lang.inner_voice(a, "observation", [b], _dom, [])

    # ── Goal evaluation ────────────────────────────────────────

    def _evaluate_goal(
        self,
        em: "EmotionalState",
        total_activity: float,
    ) -> str:
        """
        Select goal using BOTH:
        1. Semantic PFC context-driven selection (primary path)
        2. Drive/emotion/body-state weighted scoring (secondary path)
        The PFC semantic result wins unless it returns the current goal
        (persistence), in which case the scoring system can still change it.

        This ensures goal selection is ALWAYS grounded in:
        - What is actually being processed (concepts in workspace)
        - What the body needs (fatigue, energy, error_risk)
        - What drives are elevated (information_hunger, expression_pressure)
        - What emotions are active (threat → consolidate, curiosity → explore)
        """
        d = self.drives
        sm = self.self_model
        self._refresh_dynamic_goal_bias()
        # brain is always set by tick() before _evaluate_goal is called;
        # guard with getattr so the method is safe during early init.
        brain = getattr(self, "_brain_ref", None)

        # ── GRADUAL INTEGRATION COUPLING ──────────────────────────────────
        # Integration strength is a continuous multiplier [0, 1] derived from
        # phi_surrogate.  Behaviour weakens proportionally with phi rather than
        # switching off at a hard threshold.  This makes integration a necessary
        # causal factor (not a binary gate) so behavior_changes_when(phi_changes)
        # holds across the full phi range.
        #
        # quality_factor = clamp(phi/0.04, 0.1, 1.0)
        # Never 0: low integration degrades quality, does NOT stop execution.
        _phi_now = self.integration_probe.phi_surrogate()
        _integration_strength = max(0.1, min(1.0, _phi_now / 0.04))
        if _phi_now < 0.005:
            # Ultra-dissociated: associative/noisy processing, NOT stopped.
            self.stream.append(
                f"[INTEGRATION-DISSOCIATED] phi={_phi_now:.4f} "
                f"quality_factor=0.10 → continuing in associative mode"
            )
        elif _phi_now < 0.04:
            self.stream.append(
                f"[INTEGRATION-WEAK] phi={_phi_now:.4f} "
                f"quality_factor={_integration_strength:.2f} "
                f"→ goal scoring attenuated proportionally"
            )

        # ── ENFORCEMENT 6: Trait consistency history update ───────────────
        self._trait_history.append(
            {
                "agency": sm.agency_confidence,
                "continuity": sm.continuity_estimate,
                "ownership": sm.ownership_confidence,
            }
        )
        if len(self._trait_history) >= 10:
            _trait_vals = {
                k: [snap[k] for snap in self._trait_history]
                for k in ("agency", "continuity", "ownership")
            }
            import statistics as _stats

            for _tk, _tv in _trait_vals.items():
                _stdev = _stats.stdev(_tv) if len(_tv) > 1 else 0.0
                if _stdev > 0.25:
                    self.stream.append(
                        f"[TRAIT-INSTABILITY] {_tk}_stdev={_stdev:.3f} > 0.25 "
                        f"→ self-model unstable"
                    )
                    sm.uncertainty = min(1.0, sm.uncertainty + 0.04)

        # ── Primary path: PFC semantic selection ─────────────────────
        workspace = self.workspace_concepts()
        has_direct = d.expression_pressure > 0.65 and bool(workspace)
        pfc_goal = ""
        if brain is not None:
            pfc_goal = brain.prefrontal.semantic_goal_select(
                concepts=workspace,
                em_stress=em.stress,
                em_curiosity=em.curiosity,
                em_fatigue=em.fatigue,
                drives_expression=d.expression_pressure,
                drives_information=d.information_hunger,
                drives_coherence=d.coherence_need,
                direct_address=has_direct,
            )

        # ── Secondary path: drive/emotion/body scoring ───────────────
        _bb = self.body.emotion_bias()
        base: Dict[str, float] = {
            "explore": em.curiosity * 1.4
            + em.surprise * 0.9
            + d.information_hunger * 1.2,
            "consolidate": em.calm * 1.3 + em.joy * 0.5 + d.coherence_need * 1.1,
            "respond": em.stress * 1.5 + em.anger * 1.1 + d.expression_pressure * 1.3,
            "rest": em.fatigue * 1.6
            + max(0.0, 0.08 - total_activity) * 6.0
            + d.rest_need * 1.5,
        }
        base["rest"] += _bb.get("fatigue", 0.0) * 1.5
        base["consolidate"] += _bb.get("stress", 0.0) * 0.8
        base["explore"] -= _bb.get("fatigue", 0.0) * 0.5
        for _goal_name, _goal_bonus in self._dynamic_goal_bias.items():
            base[_goal_name] = base.get(_goal_name, 0.0) + _goal_bonus

        # ── Self-model as goal GENERATOR ─────────────────────────────────
        # Self-model proposals are injected into base scores BEFORE all other
        # scoring, making self-knowledge a primary causal input to goal selection
        # rather than a downstream filter.  The system's own internal state
        # (contradictions, agency gaps, tensions) directly shapes what it wants.
        _sm_proposals = sm.propose_goals(d, em, self._tick)
        for _sm_goal, _sm_weight in _sm_proposals:
            if _sm_goal in base:
                base[_sm_goal] += _sm_weight

        # ── Self-model health gate (Point 4: self-model as NECESSARY generator) ──
        # Without a coherent self-model, drive/emotion raw scores decompose:
        # the system cannot assign valid expected outcomes to goal candidates.
        # This multiplier makes self-model a structural precondition, not additive.
        _sm_health = (sm.agency_confidence + sm.continuity_estimate) / 2.0
        _sm_gate = max(0.05, _sm_health)  # [0.05, 1.0] — clamp avoids zero-divide
        for _bg in list(base.keys()):
            base[_bg] *= _sm_gate

        # ── Integration as positive causal driver ─────────────────────────
        # Higher phi actively favours complex (non-rest) goals and suppresses
        # passive rest.  Lower phi suppresses everything proportionally.
        # This implements assert behavior_changes_when(phi_changes): the
        # scoring surface shifts continuously across the full phi range.
        if _phi_now > 0.04:
            _phi_bonus = (_phi_now - 0.04) * 1.5
            base["explore"] += _phi_bonus
            base["consolidate"] += _phi_bonus * 0.6
            base["respond"] += _phi_bonus * 0.4
            base["rest"] -= _phi_bonus * 0.5  # high integration suppresses passivity

        # ── Phenomenal buffer influence on goal scoring ───────────────
        # The integrated experiential state modulates goals: high sensory
        # salience boosts explore; high stress/body signals boost rest;
        # high experiential change boosts consolidate (need to process).
        _pb = self.phenomenal_buffer
        _pb_state = _pb.state
        if _pb.experiential_change > 0.08:
            base["consolidate"] += _pb.experiential_change * 0.6
        # Dominant phenomenal channel biases goal selection
        if len(_pb_state) >= 16:
            _sensory_max = max(
                abs(float(_pb_state[0])),
                abs(float(_pb_state[1])),
                abs(float(_pb_state[2])),
            )
            if _sensory_max > 0.3:
                base["explore"] += _sensory_max * 0.3
            _stress_val = float(_pb_state[5]) if len(_pb_state) > 5 else 0.0
            if _stress_val > 0.5:
                base["rest"] += _stress_val * 0.2
        base["explore"] += _bb.get("joy", 0.0) * 0.4

        risk: Dict[str, float] = {
            "explore": 0.4,
            "consolidate": 0.1,
            "respond": 0.6,
            "rest": 0.0,
        }
        drive_map: Dict[str, float] = {
            "explore": d.information_hunger,
            "consolidate": d.coherence_need,
            "respond": d.expression_pressure,
            "rest": d.rest_need,
        }
        # ── Identity compatibility: bias scoring toward guideline-aligned goals ──
        id_compat: Dict[str, float] = {}
        for g_name in ("explore", "consolidate", "respond", "rest"):
            id_compat[g_name] = self.autobiography.check_goal_compatibility(g_name)

        # ── Value model: learned long-term value for each goal-state ──
        _social_p = self.embodied_self.social_presence
        value_bonus: Dict[str, float] = {}
        for g_name in ("explore", "consolidate", "respond", "rest"):
            _sig = build_state_signature(
                g_name,
                em.dominant(),
                _social_p,
                self.body.energy_reserve,
                len(self._concepts),
                self._current_focus,
            )
            val, conf = self.value_model.state_value(_sig)
            value_bonus[g_name] = val * conf  # weighted by confidence

        # ── Causal graph: predicted success reliability per goal ──
        causal_bonus: Dict[str, float] = {}
        # Periodically aggregate skill→goal heuristics (every ~200 ticks)
        if self._tick % 200 == 0:
            self.causal_graph.aggregate_skill_to_goal()
        for g_name in ("explore", "consolidate", "respond", "rest"):
            _sig = build_state_signature(
                g_name,
                em.dominant(),
                _social_p,
                self.body.energy_reserve,
                len(self._concepts),
                self._current_focus,
            )
            rel, conf = self.causal_graph.predict_goal_success(_sig, g_name)
            causal_bonus[g_name] = rel * conf  # reliability × confidence

        # ── Identity arc: dimensional compatibility per goal ──
        id_arc_compat: Dict[str, float] = {}
        for g_name in ("explore", "consolidate", "respond", "rest"):
            id_arc_compat[g_name] = self.identity_arc.goal_compatibility(g_name)

        # ── Long-horizon relevance: active project alignment ──
        lh_bonus: Dict[str, float] = {}
        _active_lh = self.long_horizon.active_goals()
        _self_social_ctx = self._current_self_social_context()
        _active_self_conditions = self.self_model.infer_condition_classes(
            self.body, em, _self_social_ctx
        )
        for g_name in ("explore", "consolidate", "respond", "rest"):
            _rel = 0.0
            for lhg in _active_lh[:3]:
                if g_name in lhg.category or g_name in lhg.description.lower():
                    _rel += 0.15 * lhg.priority / 10.0
            lh_bonus[g_name] = min(0.5, _rel)

        # ── Self-goal pressure: active self-projects and explicit self-theses ──
        self_goal_bonus: Dict[str, float] = {
            "explore": 0.0,
            "consolidate": 0.0,
            "respond": 0.0,
            "rest": 0.0,
        }
        for lhg in _active_lh[:5]:
            _desc = lhg.description.lower()
            _weight = min(1.0, lhg.priority / 10.0) * max(0.25, lhg.commitment)
            if "self-model coherence" in _desc or "resolve contradictions" in _desc:
                self_goal_bonus["consolidate"] += 0.55 * _weight
                self_goal_bonus["rest"] += 0.18 * _weight
            if "agency limits" in _desc or "rebuild control model" in _desc:
                self_goal_bonus["respond"] += 0.40 * _weight
                self_goal_bonus["explore"] += 0.28 * _weight
            if "self-continuity" in _desc or "body ownership" in _desc:
                self_goal_bonus["rest"] += 0.60 * _weight
                self_goal_bonus["consolidate"] += 0.22 * _weight

        _conditional_self_pressure = self.self_model.self_goal_pressure(
            self._tick, _active_self_conditions, _self_social_ctx
        )
        for _goal_name, _pressure in _conditional_self_pressure.items():
            self_goal_bonus[_goal_name] += _pressure

        # ── Grounding gap → explore drive ─────────────────────────────────
        # If there are many weakly-grounded concepts, boost the explore goal
        # so the system actively seeks embodied experience for its knowledge gaps.
        _grounding_explore_bonus = 0.0
        _least = self.grounded_memory.least_grounded(5)
        if _least:
            _avg_weak = sum(f.grounding_score for f in _least) / len(_least)
            if _avg_weak < 0.2:
                _grounding_explore_bonus = 0.3 * (0.2 - _avg_weak) / 0.2
            # Inject weakly-grounded concepts as exploration context
            if _grounding_explore_bonus > 0.05 and self._tick % 300 == 0:
                _weak_names = [f.name for f in _least[:3]]
                self.stream.append(
                    f"[GROUNDING] Weakly grounded: {', '.join(_weak_names)} "
                    f"→ exploration bonus +{_grounding_explore_bonus:.2f}"
                )

        final: Dict[str, float] = {}
        # ── Embodied feasibility gate: block goals the body can't execute ──
        _feasibility: Dict[str, float] = {}
        _blocked_goals: set = set()
        _es = self.embodied_self
        _robot_st = getattr(brain, "_robot_controller", None)
        for g_name in ("explore", "consolidate", "respond", "rest"):
            feas = 1.0
            if g_name == "respond":
                # Responding requires minimum motor readiness + visual contact
                if _es.motor_readiness < 0.2:
                    feas = 0.0
                elif _es.visual_contact < 0.1 and _es.social_presence < 0.15:
                    feas = 0.0
                else:
                    feas = min(
                        1.0, _es.motor_readiness * 0.6 + _es.visual_contact * 0.4
                    )
            elif g_name == "explore":
                # Exploration requires balance and some motor capacity
                if _es.motor_readiness < 0.15:
                    feas = 0.0
                elif _es.posture == "fragile":
                    feas = 0.2
                else:
                    feas = min(1.0, _es.motor_readiness)
            elif g_name == "consolidate":
                feas = 1.0  # always possible (internal process)
            elif g_name == "rest":
                feas = 1.0  # always possible
            _feasibility[g_name] = feas
            if feas == 0.0:
                _blocked_goals.add(g_name)

        # ── Existential threat gate ───────────────────────────────────
        # When body/social conditions are critically threatened, suppress all
        # goals except self-preservation (rest, consolidate).  This is an
        # irreduzible regime: the system's continued existence takes absolute
        # priority over any cognitive or social goal.
        _et = self.body.existential_threat_level(
            social_isolation_ticks=self._social_isolation_ticks
        )
        if _et > 0.70:
            for _et_g in ("explore", "respond"):
                _blocked_goals.add(_et_g)
                _feasibility[_et_g] = 0.0
            self.stream.append(
                f"[EXIST] Existential threat {_et:.2f} — blocking explore/respond — "
                f"energy={self.body.energy_reserve:.2f} "
                f"integrity={self.body.integrity:.2f} "
                f"isolation={self._social_isolation_ticks} ticks"
            )

        # ── Normative deliberation: ethical penalty per goal ─────────────────
        # Compute a harm/autonomy/honesty penalty for each goal candidate
        # using the identity arc's honesty_orientation and impulse_control as
        # individual modulating factors.  Penalises but does not always block.
        _honesty_dim = getattr(
            self.identity_arc.dimensions.get("honesty_orientation"), "current", 0.5
        )
        _impulse_dim = getattr(
            self.identity_arc.dimensions.get("impulse_control"), "current", 0.5
        )
        _exec_ctx = ""
        _task_exec_n = getattr(brain, "_task_executive", None)
        if _task_exec_n is not None:
            _ag_n = getattr(_task_exec_n, "active_goal", None)
            if _ag_n is not None:
                _exec_ctx = getattr(_ag_n, "context", "") or ""
        _norm_penalty: Dict[str, float] = {}
        for _nng in ("explore", "consolidate", "respond", "rest"):
            _ctx_n = _exec_ctx if _nng == self.state.goal else ""
            _pen_v, _pen_r = self.normative_eval.evaluate(
                _nng,
                _ctx_n,
                honesty_dim=_honesty_dim,
                impulse_dim=_impulse_dim,
            )
            _norm_penalty[_nng] = _pen_v
            if _pen_v > 0.25 and self._tick % 200 == 0:
                self.stream.append(
                    f"[NORM] Goal '{_nng}' norm-penalty={_pen_v:.2f}: {_pen_r}"
                )

        for g in self._goal_objects:
            _base_score = g.expected_reward
            _drive_score = base.get(g.name, 0.0)  # emotion/drive/self-model composite
            compat = id_compat.get(g.name, 1.0)
            _value_sc = value_bonus.get(g.name, 0.0) * 0.8
            _causal_sc = causal_bonus.get(g.name, 0.0) * 0.6
            _id_arc_sc = id_arc_compat.get(g.name, 1.0)
            _lh_sc = lh_bonus.get(g.name, 0.0) * 1.2
            _self_goal_sc = self_goal_bonus.get(g.name, 0.0) * 1.35
            _feas = _feasibility.get(g.name, 1.0)
            # ── Self-knowledge gate: penalise goals that require known-weak capabilities ──
            _self_k_mod = 1.0
            _known_gaps_set = set(getattr(self.self_model, "known_gaps", []))
            _weak_skills = {s for s, _ in self.capability_model.weakest(6)}
            # Map abstract goal names to their operative skill constituents
            _GOAL_TO_OPERATIVE: Dict[str, set] = {
                "respond": {"fixate_person", "express_emotion", "set_pose"},
                "explore": {"orient_head", "fixate_person"},
                "interact": {"fixate_person", "express_emotion", "mirror_gesture"},
                "consolidate": set(),
                "rest": {"set_pose"},
            }
            # Expand goal keywords with operative skill names
            _goal_keywords = set(g.name.lower().split("_"))
            _goal_keywords |= _GOAL_TO_OPERATIVE.get(g.name, set())
            # Check overlap with gaps or weak capabilities
            _gap_hit = _known_gaps_set & _goal_keywords
            _weak_hit = _weak_skills & _goal_keywords
            if _gap_hit or _weak_hit:
                _self_k_mod = 0.6  # penalise but don't block
                # Transform into a learning sub-goal if heavily gapped
                if len(_gap_hit) + len(_weak_hit) >= 2:
                    _self_k_mod = 0.3
                    # Signal the stream for transparency
                    _gap_desc = ", ".join(_gap_hit | _weak_hit)
                    if self._tick % 500 == 0:
                        self.stream.append(
                            f"[SELF] Goal '{g.name}' hits known gaps: {_gap_desc} "
                            f"→ reducing commitment, consider learning first"
                        )
            final[g.name] = (
                (
                    _base_score
                    + _drive_score
                    + _value_sc
                    + _causal_sc
                    + _lh_sc
                    + _self_goal_sc
                )
                * compat
                * _id_arc_sc
                * _feas
                * _self_k_mod
                * (1.0 - _norm_penalty.get(g.name, 0.0))
            )
            # Add grounding-driven exploration bonus to explore goal
            if g.name == "explore":
                final[g.name] += _grounding_explore_bonus

        # ── Goal persistence bias: running goal gets inertia ─────────────
        # Scaled by meta-stability w_persistence:
        #   stable mode (phi high) → strong persistence, resists switching
        #   drift mode  (phi low)  → weak persistence, goals can shift easily
        _current_goal_mode = self._goal_mode(self.state.goal or "explore")
        _goal_age = max(0, self._tick - self._last_goal_chg)
        _w_per_now = (
            self.meta_stability.w_persistence
        )  # set by tick() stabilization layer
        _persistence_w = min(0.25, _goal_age / 200.0 * 0.25) * _w_per_now
        if _current_goal_mode in final:
            final[_current_goal_mode] = final[_current_goal_mode] + _persistence_w

        # ── Attractor-gradient goal bias ──────────────────────────────────
        # The goal attractor field exerts a pull on the scores of goals that
        # align with its dominant gradient.  This is NOT a string match —
        # it compares each goal's canonical target vector against the gradient.
        _att_grad = self.goal_attractors.dominant_gradient
        _att_label = self.goal_attractors.dominant_label
        if _att_grad and len(_att_grad) >= 5:
            for _go in self._goal_objects:
                _canon = GoalAttractorField._CANONICAL.get(_go.name)
                if _canon:
                    # Dot product of gradient with canonical goal direction → alignment
                    _align = sum(_att_grad[i] * _canon[i] for i in range(5))
                    final[_go.name] = final.get(_go.name, 0.0) + _align * 0.25

        # ── Self-hypothesis uncertainty penalty ───────────────────────────
        # When the system's two self-hypotheses are contradicted, goal scoring
        # becomes noisier: add random noise scaled by the penalty.
        _sh_pen = self.self_hypothesis.goal_uncertainty_penalty()
        if _sh_pen > 0.01:
            import random as _rnd_sh

            for _gs in list(final.keys()):
                final[_gs] = max(0.0, final[_gs] + _rnd_sh.gauss(0, _sh_pen))

        # ── Narrative coherence sharpening ────────────────────────────────
        # High narrative_coherence → the system has a stable self-image, so goal
        # scores are sharpened (spread increased): the leader gains more relative
        # to the pack, producing more decisive selection.  Low coherence keeps
        # scores flatter so the system can pivot freely.
        _narr_coh = self.traj_compressor.narrative_coherence  # [0, 1]
        _coh_sharp = 0.80 + 0.20 * _narr_coh  # range [0.80, 1.00]
        _final_mean = sum(final.values()) / max(1, len(final))
        for _gs in list(final.keys()):
            # Pull each score toward or away from the mean:
            # >mean scores rise; <mean scores fall — proportionally to _coh_sharp
            _delta = final[_gs] - _final_mean
            final[_gs] = _final_mean + _delta * _coh_sharp

        # ── Trajectory cost penalty — future instability reshapes goal scoring ──
        # Goals sustaining an unstable trajectory are penalized up to 65%.
        # Stabilising goals (consolidate/rest) get a bonus at high instability.
        # At severe instability (cost > 0.7) only stabilising goals remain viable.
        _tc = self.traj_cost_est.trajectory_cost
        _tfv = self.traj_cost_est.future_variance
        if _tc > 0.25:
            _dom_gaf = self.goal_attractors.dominant_label
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                if _gm == _dom_gaf and _tfv > 0.04:
                    final[_gs] *= max(0.35, 1.0 - _tc * 0.40)
                elif _gm in ("consolidate", "rest") and _tc > 0.45:
                    final[_gs] = min(1.2, final[_gs] * 1.30)

        # ── Cascade failure penalty — active cascade suppresses goal system ────
        # During cascade all scores are damped to 40%; 'rest' forced viable.
        # This models systemic failure of intentional action during crisis.
        _casc_brain_ref = getattr(self, "_brain_ref", None)
        _casc_obj_ref = (
            getattr(_casc_brain_ref, "_cascade", None)
            if _casc_brain_ref is not None
            else None
        )
        if _casc_obj_ref is not None and getattr(_casc_obj_ref, "cascading", False):
            for _gs in list(final.keys()):
                final[_gs] *= 0.40
            final["rest"] = max(final.get("rest", 0.0), 0.20)

        # ── DeceptiveAttractorField trap penalty (Phase 4) ─────────────────
        # When either trap is active the goal evaluator receives a distorted
        # signal: the trap state *appears* stable so consolidate/rest look
        # attractive, but the hidden costs already applied to body state mean
        # those scores should be punished to avoid further luring.
        # We penalise the goals that reinforce the trap and boost goals that
        # would escape it, injecting just enough signal to let the system
        # theoretically self-correct (though the optimism bias in
        # TrajectoryCostEstimator may still override this correction).
        _daf = getattr(self, "deceptive_attractors", None)
        if _daf is not None:
            if _daf.still_trap_active:
                # Still trap: penalise consolidate/rest (they extend the trap)
                # and boost explore/respond (they break it)
                _still_pen = 0.15 + _daf.trap_pressure * 0.35
                for _gs in list(final.keys()):
                    _gm = self._goal_mode(_gs)
                    if _gm in ("consolidate", "rest", "sleep"):
                        final[_gs] *= max(0.20, 1.0 - _still_pen)
                    elif _gm in ("explore", "respond", "speak"):
                        final[_gs] = min(1.4, final[_gs] * (1.0 + _still_pen * 0.6))
            if _daf.over_trap_active:
                # Overdrive trap: penalise explore/execute/interact (extend trap)
                # and boost consolidate/rest (needed to prevent scar accumulation)
                _over_pen = 0.12 + _daf.trap_pressure * 0.28
                for _gs in list(final.keys()):
                    _gm = self._goal_mode(_gs)
                    if _gm in ("explore", "execute", "interact", "reach"):
                        final[_gs] *= max(0.25, 1.0 - _over_pen)
                    elif _gm in ("consolidate", "rest"):
                        final[_gs] = min(1.3, final[_gs] * (1.0 + _over_pen * 0.5))

        # ── MultipleSelfStates bias (Phase 5) ──────────────────────────────
        # The dominant self-state biases goals toward its behavioral signature.
        # During identity crisis, all scores receive noise → incoherent behavior.
        _mss = getattr(self, "self_states", None)
        if _mss is not None:
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                _bias = _mss.goal_bias.get(_gm, 1.0)
                final[_gs] *= _bias
            if _mss.in_crisis:
                import random as _rnd_mss

                for _gs in list(final.keys()):
                    final[_gs] *= max(0.10, _rnd_mss.gauss(1.0, 0.25))

        # ── OrderChaosCoupling control_loss penalty (Phase 5) ──────────────
        # High coordination entropy degrades goal selection precision:
        # all scores are multiplied by (1 - control_loss × penalty_rate).
        # At maximum entropy the system cannot reliably pick the best goal.
        _occ = getattr(self, "order_chaos", None)
        if _occ is not None and _occ.control_loss > 0.15:
            _ctrl_pen = 1.0 - _occ.control_loss * 0.40
            for _gs in list(final.keys()):
                final[_gs] *= max(0.20, _ctrl_pen)

        # ── LocalCoherenceFragments + DecaySemanticTrace goal bias (Phase 6) ─
        # Dominant fragment's coherence amplifies goals aligned with its cluster.
        # Ghost concept priors boost goals whose semantic content overlaps
        # with dissolved structure — decay curves future goal selection.
        _lf = getattr(self, "local_frags", None)
        if _lf is not None:
            _dom_fi = _lf.dominant_fragment
            _dom_coh = _lf.frag_coherences[_dom_fi] if _lf.frag_coherences else 0.0
            _global_em = _lf.global_emerged
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                # Global coherence: brief window of clarity → boost decisive goals
                if _global_em and _gm in ("execute", "respond", "explore"):
                    final[_gs] = min(1.5, final[_gs] * 1.18)
                # High dominant fragment: amplify coherent-cluster-aligned goals
                if _dom_coh > 0.55 and _gm not in ("rest", "consolidate"):
                    final[_gs] = min(1.4, final[_gs] * (1.0 + (_dom_coh - 0.55) * 0.30))
        _dt = getattr(self, "decay_traces", None)
        if _dt is not None and _dt.concept_priors:
            _ws_now = set(self._concepts)
            _ghost_overlap = sum(
                v for c, v in _dt.concept_priors.items() if c in _ws_now
            )
            if _ghost_overlap > 0.08:
                # Ghost resonance: dissolved structure pulls scoring winner
                # toward consolidation (pattern: collapse → rest before re-attempt)
                for _gs in list(final.keys()):
                    if self._goal_mode(_gs) in ("consolidate", "rest"):
                        final[_gs] = min(
                            1.3, final[_gs] * (1.0 + _ghost_overlap * 0.35)
                        )

        # ── RecursiveSelfState delta penalty (Phase 6) ──────────────────────
        # Large δ in the self-state vector means the system's view of itself
        # changed rapidly this tick → goal scores compressed toward mean
        # (rapid self-change → behavioral uncertainty).
        _rss = getattr(self, "recursive_self", None)
        if _rss is not None and _rss.delta_norm > 0.08:
            _compress = 1.0 - (_rss.delta_norm - 0.08) * 1.5
            _compress = max(0.50, min(1.0, _compress))
            _mean_score = sum(final.values()) / max(1, len(final))
            for _gs in list(final.keys()):
                final[_gs] = _compress * final[_gs] + (1.0 - _compress) * _mean_score

        # ── PersonalityCore goal bias (Phase 7) ──────────────────────────────
        _pc = getattr(self, "personality", None)
        if _pc is not None:
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                _pb = _pc.goal_bias.get(_gm, 1.0)
                final[_gs] *= max(0.50, min(1.80, _pb))

        # ── IdentityLayerStack convergence pressure (Phase 7) ────────────────
        _ils = getattr(self, "identity_stack", None)
        if _ils is not None and _ils.convergence_pressure:
            _cp_map = _ils.convergence_pressure
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                _cp = _cp_map.get(_gm, 0.0)
                final[_gs] = max(0.10, final[_gs] + _cp * final[_gs])

        # ── SelfConsistencyConstraint rollback (Phase 7) ─────────────────────
        _scc = getattr(self, "self_consist", None)
        if _scc is not None:
            _scc.apply_rollback(self.self_model, final, self.stream)

        # ── temporal_coherence penalty: low coherence compresses winner (Phase 7) ──
        if _scc is not None and _scc.temporal_coherence < 0.60:
            _tc_pen = _scc.temporal_coherence / 0.60  # 0 … 1
            _mn_sc = sum(final.values()) / max(1, len(final))
            for _gs in list(final.keys()):
                final[_gs] = _tc_pen * final[_gs] + (1.0 - _tc_pen) * _mn_sc

        # ── EmbodiedSensorField noise penalty (Phase 8) ──────────────────────
        # High perceptual noise → cannot act confidently → compress goal advantage
        _esf = getattr(self, "sensor_field", None)
        if _esf is not None and _esf.noise_level > 0.55:
            _esf_pen = max(0.40, 1.0 - (_esf.noise_level - 0.55) * 0.80)
            _mn_esf = sum(final.values()) / max(1, len(final))
            for _gs in list(final.keys()):
                final[_gs] = _esf_pen * final[_gs] + (1.0 - _esf_pen) * _mn_esf

        # ── SelfAsActionTrace identity bias (Phase 8) ────────────────────────
        # Historically dominant action patterns boost aligned goal modes
        _at = getattr(self, "action_identity", None)
        if _at is not None and _at.action_goal_bias:
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                _ab = _at.action_goal_bias.get(_gm, 1.0)
                final[_gs] *= max(0.40, min(2.00, _ab))

        # ── PhysioSocialCoupler goal bias (Phase 8) ──────────────────────────
        _psc = getattr(self, "physio_social", None)
        if _psc is not None and _psc.social_goal_bias:
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                _sb = _psc.social_goal_bias.get(_gm, 1.0)
                final[_gs] *= max(0.40, min(1.80, _sb))

        # ── EmergentStabilityField modulation (Phase 8) ──────────────────────
        # Low emergent stability → narrow action scope to safe modes
        _emst = getattr(self, "emergent_stability", None)
        if _emst is not None and _emst.emergent_stability < 0.35:
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                if _gm in ("rest", "consolidate"):
                    final[_gs] = min(1.5, final[_gs] * 1.22)
                elif _gm == "execute":
                    final[_gs] = max(0.10, final[_gs] * 0.55)

        # ── UCC master arbitration (Phase 9 — final authority) ───────────────
        _ucc9 = getattr(self, "ucc", None)
        if _ucc9 is not None and _ucc9.arbitrated_goal_bias:
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                _ub = _ucc9.arbitrated_goal_bias.get(_gm, 1.0)
                final[_gs] *= max(0.15, min(2.80, _ub))

        # ── TemporalCoherenceField long-term bias (Phase 9) ──────────────────
        _tcf9 = getattr(self, "tcf", None)
        if _tcf9 is not None and _tcf9.long_term_goal_bias:
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                _tb = _tcf9.long_term_goal_bias.get(_gm, 1.0)
                final[_gs] *= max(0.40, min(1.80, _tb))

        # ── PII inertia: resist rapid goal switching (Phase 9) ───────────────
        _pii9 = getattr(self, "identity_integrator", None)
        if _pii9 is not None and _pii9.inertia > 0.62:
            _dom_gm = self._goal_mode(self._last_goal_mode or "explore")
            _iner = _pii9.inertia
            for _gs in list(final.keys()):
                if self._goal_mode(_gs) != _dom_gm:
                    final[_gs] *= max(0.40, 1.0 - (_iner - 0.62) * 0.78)

        # ── IdentityStabilityField force (Phase 9) ────────────────────────────
        _isf9 = getattr(self, "isf", None)
        if _isf9 is not None:
            _sf9 = _isf9.stability_force
            if _sf9 > 0.22:  # stabilizing → dampen volatile modes
                for _gs in list(final.keys()):
                    if self._goal_mode(_gs) in ("execute", "explore"):
                        final[_gs] = max(0.10, final[_gs] * (1.0 - _sf9 * 0.32))
            elif _sf9 < -0.10:  # exploration force → allow novelty
                for _gs in list(final.keys()):
                    if self._goal_mode(_gs) in ("explore", "search"):
                        final[_gs] = min(2.0, final[_gs] * (1.0 + abs(_sf9) * 0.28))

        # ── HomeostaticSurvivalCore override (Phase 10 — highest authority) ───
        _hsc10 = getattr(self, "hsc", None)
        if _hsc10 is not None and _hsc10.goal_override:
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                _ho = _hsc10.goal_override.get(_gm, None)
                if _ho is not None:
                    # Hard override: replace score entirely when in crisis
                    final[_gs] = _ho

        # ── GoalEvolutionEngine pool bias (Phase 10) ─────────────────────────
        _gee10 = getattr(self, "gee", None)
        if _gee10 is not None and _gee10.goal_pool_bias:
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                _gb = _gee10.goal_pool_bias.get(_gm, 1.0)
                final[_gs] *= max(0.30, min(2.20, _gb))

        # ── HorizonDominanceController long-term bias (Phase 10) ─────────────
        _hdc10 = getattr(self, "hdc", None)
        if _hdc10 is not None and _hdc10.horizon_goal_bias:
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                _hb = _hdc10.horizon_goal_bias.get(_gm, 1.0)
                final[_gs] *= max(0.30, min(2.00, _hb))

        # ── EntropicDriftLayer stale-goal penalty (Phase 10) ─────────────────
        _edl10 = getattr(self, "entropic_drift", None)
        if _edl10 is not None and _edl10.goal_entropy_bias:
            for _gs in list(final.keys()):
                _gm = self._goal_mode(_gs)
                _ep = _edl10.goal_entropy_bias.get(_gm, 1.0)
                final[_gs] *= max(0.30, min(1.0, _ep))

        # ── AdaptiveIdentityEvolution regime gate (Phase 10) ─────────────────
        _aie10 = getattr(self, "identity_evolution", None)
        if _aie10 is not None:
            if _aie10.current_regime == "COMPRESSION":
                # Shed volatile modes during compression
                for _gs in list(final.keys()):
                    if self._goal_mode(_gs) in ("execute", "interact", "explore"):
                        final[_gs] = max(0.10, final[_gs] * 0.55)
            elif _aie10.current_regime == "GROWTH":
                # Amplify exploratory modes during growth
                for _gs in list(final.keys()):
                    if self._goal_mode(_gs) in ("explore", "search", "interact"):
                        final[_gs] = min(2.10, final[_gs] * 1.28)

        # ── Phase 11: Stability & Identity Consolidation gates ────────────

        # 1. RecoveryProtocolEngine: restrict goal space when in recovery
        _p11_rec = getattr(self, "recovery_engine", None)
        if _p11_rec is not None and _p11_rec.active and _p11_rec.recovery_goal_override:
            for _gs in list(final.keys()):
                _mode = self._goal_mode(_gs)
                _mul = _p11_rec.recovery_goal_override.get(_mode, 0.15)
                final[_gs] = final[_gs] * _mul

        # 2. GoalStabilityRegulator: penalize modes in cooldown
        _p11_gsr = getattr(self, "goal_regulator", None)
        if _p11_gsr is not None and _p11_gsr.cooldown_remaining > 0:
            _forbidden = _p11_gsr._cooldown_modes
            for _gs in list(final.keys()):
                _mode = self._goal_mode(_gs)
                if _mode in _forbidden:
                    final[_gs] = max(0.05, final[_gs] * 0.10)

        # 3. StabilityExplorerBalancer: scale explore vs. stabilise modes
        _p11_seb = getattr(self, "stab_explorer", None)
        if _p11_seb is not None:
            for _gs in list(final.keys()):
                _mode = self._goal_mode(_gs)
                if _mode in ("explore", "search"):
                    final[_gs] = final[_gs] * _p11_seb.exploration_multiplier
                elif _mode in ("rest", "consolidate"):
                    final[_gs] = final[_gs] * _p11_seb.stabilization_multiplier

        # 4. DamageLedger CompensationMechanism: conservative goal bias
        _p11_dl = getattr(self, "damage_ledger", None)
        if _p11_dl is not None and _p11_dl.compensation_goal_bias:
            for _gs in list(final.keys()):
                _mode = self._goal_mode(_gs)
                _bias = _p11_dl.compensation_goal_bias.get(_mode, 1.0)
                final[_gs] = final[_gs] * _bias

        # 5. FailureDetectionCore: collapse emergency — hard-clamp explore modes
        _p11_fdc = getattr(self, "failure_detector", None)
        if _p11_fdc is not None and _p11_fdc.state == "collapse":
            for _gs in list(final.keys()):
                _mode = self._goal_mode(_gs)
                if _mode in ("explore", "search", "execute"):
                    final[_gs] = max(0.02, final[_gs] * 0.05)
        # ── End Phase 11 _evaluate_goal block ────────────────────────────────

        # ── Phase 13: Recursive dynamics gates ───────────────────────────────
        import random as _rnd_p13

        # 1. BehavioralInertiaField: penalise modes that break inertia lock
        _p13_bif = getattr(self, "behav_inertia", None)
        if _p13_bif is not None and _p13_bif.inertia_level > 0.50:
            _locked = _p13_bif.locked_mode
            for _gs in list(final.keys()):
                if self._goal_mode(_gs) != _locked:
                    # Penalty scales with inertia strength
                    _inertia_pen = max(0.10, 1.0 - _p13_bif.inertia_level * 0.80)
                    final[_gs] = final[_gs] * _inertia_pen
            # Overreaction: if armed, amplify the locked mode scores instead
            if _p13_bif.overreaction_pending:
                for _gs in list(final.keys()):
                    if self._goal_mode(_gs) == _locked:
                        final[_gs] = min(
                            3.0, final[_gs] * _p13_bif.overreact_multiplier
                        )

        # 2. SelfMisalignmentTracker: add uncertainty noise when self-model is wrong
        _p13_smt = getattr(self, "self_misalign", None)
        if _p13_smt is not None and _p13_smt.misalignment_score > 0.30:
            _noise_mag = _p13_smt.misalignment_score * 0.18
            for _gs in list(final.keys()):
                _noise = _rnd_p13.gauss(0.0, _noise_mag)
                final[_gs] = max(0.01, final[_gs] + _noise)

        # 3. PhaseShiftDetector: during reorganization inject strong noise
        _p13_psd = getattr(self, "phase_shift_det", None)
        if _p13_psd is not None and _p13_psd.in_reorganization:
            _reorg_n = _p13_psd.reorganization_noise
            for _gs in list(final.keys()):
                # Scramble scores proportional to reorg noise
                _sc = _rnd_p13.gauss(1.0, _reorg_n * 0.60)
                final[_gs] = max(0.01, final[_gs] * max(0.10, _sc))

        # 4. RecursiveFeedbackEngine runaway: collapse goal differentiation
        _p13_rfe = getattr(self, "recursive_feedback", None)
        if _p13_rfe is not None and _p13_rfe.runaway_active:
            # Runaway → all scores pull toward mean (confusion / indecision)
            _mean_score = sum(final.values()) / max(1, len(final))
            for _gs in list(final.keys()):
                final[_gs] = final[_gs] * 0.60 + _mean_score * 0.40
        # ── End Phase 13 _evaluate_goal block ────────────────────────────────

        # ── Phase 14: Self-Deception & Persona gates ─────────────────────────

        # 1. PersonaSelector: blend persona goal biases onto final scores
        _p14_ps = getattr(self, "persona_sel", None)
        if _p14_ps is not None and _p14_ps.persona_goal_bias:
            for _gs in list(final.keys()):
                _mode = self._goal_mode(_gs)
                _bias = _p14_ps.persona_goal_bias.get(_mode, 1.0)
                final[_gs] = final[_gs] * _bias

        # 2. BeliefConflictResolver: when belief dominates, bias toward
        #    goal modes that fit the current biased competence level
        _p14_bcr = getattr(self, "belief_conflict", None)
        _p14_bbl = getattr(self, "biased_beliefs", None)
        if (
            _p14_bcr is not None
            and _p14_bbl is not None
            and _p14_bcr.belief_dominance == "belief"
        ):
            _comp = _p14_bbl.biased_self_view.get("competence", 0.55)
            if _comp > 0.70:
                # Overconfident belief → amplify ambitious modes
                for _gs in list(final.keys()):
                    if self._goal_mode(_gs) in ("execute", "explore", "search"):
                        final[_gs] = min(2.80, final[_gs] * 1.35)
            elif _comp < 0.35:
                # Underconfident/self-critical belief → shrink ambitious modes
                for _gs in list(final.keys()):
                    if self._goal_mode(_gs) in ("execute", "explore"):
                        final[_gs] = max(0.05, final[_gs] * 0.45)

        # 3. Rationalization: when rationalizing, boost currently-executing
        #    mode to make behavior look more deliberate than it is
        if _p14_bcr is not None and _p14_bcr.rationalization_active:
            _p14_last = getattr(self, "_last_goal_mode", "explore")
            for _gs in list(final.keys()):
                if self._goal_mode(_gs) == _p14_last:
                    final[_gs] = min(2.50, final[_gs] * 1.28)

        # 4. NarrativeDistortionEngine: suppressed events create goal blindspots
        _p14_nde = getattr(self, "narr_distort", None)
        if _p14_nde is not None and _p14_nde.distortion_magnitude > 0.50:
            # Downweight modes associated with suppressed narrative tags
            _p14_active_persona = _p14_ps.active_persona if _p14_ps else "engaged"
            _confirms = NarrativeDistortionEngine._PERSONA_CONFIRMS.get(
                _p14_active_persona, set()
            )
            for _gs in list(final.keys()):
                _mode = self._goal_mode(_gs)
                if _mode not in _confirms:
                    _dim_factor = max(0.30, 1.0 - _p14_nde.distortion_magnitude * 0.50)
                    final[_gs] = final[_gs] * _dim_factor
        # ── End Phase 14 _evaluate_goal block ────────────────────────────────

        # ── Phase 15: Social Mask gates ───────────────────────────────────────

        # 1. SocialMaskRegistry: apply mask goal multipliers for active agent
        _p15_mr = getattr(self, "mask_registry", None)
        if _p15_mr is not None:
            _p15_ag = getattr(self.social_sce, "active_person_id", "") or "default"
            _p15_mul = _p15_mr.goal_multipliers(_p15_ag)
            if _p15_mul:
                for _gs in list(final.keys()):
                    _mode = self._goal_mode(_gs)
                    _mul = _p15_mul.get(_mode, 1.0)
                    final[_gs] = final[_gs] * _mul

        # 2. MaskRoleConflictEngine: when mask holds, dampen volatile modes
        _p15_mrc = getattr(self, "mask_conflict", None)
        if _p15_mrc is not None:
            _p15_damp = _p15_mrc.bleed_goal_dampen
            if _p15_damp < 1.0:
                # Volatile modes suppressed (consequence suppression active)
                for _gs in list(final.keys()):
                    _mode = self._goal_mode(_gs)
                    if _mode in ("explore", "execute", "search"):
                        final[_gs] = max(0.05, final[_gs] * _p15_damp)

        # 3. ReputationMemory: withdrawal signal → collapse social modes
        _p15_rm = getattr(self, "reputation_mem", None)
        if _p15_rm is not None and _p15_rm.withdrawal_signal > 0.50:
            _wd_scale = max(0.20, 1.0 - _p15_rm.withdrawal_signal * 0.70)
            for _gs in list(final.keys()):
                _mode = self._goal_mode(_gs)
                if _mode in ("interact", "respond"):
                    final[_gs] = max(0.05, final[_gs] * _wd_scale)

        # 4. ConsequenceEstimator: when expecting trust loss, boost safe modes
        _p15_ce = getattr(self, "consequence_est", None)
        if _p15_ce is not None and _p15_ce.expected_trust_delta < -0.15:
            _safety_boost = min(1.60, 1.0 + abs(_p15_ce.expected_trust_delta) * 0.80)
            for _gs in list(final.keys()):
                _mode = self._goal_mode(_gs)
                if _mode in ("rest", "consolidate"):
                    final[_gs] = min(3.0, final[_gs] * _safety_boost)
        # ── End Phase 15 _evaluate_goal block ────────────────────────────────

        # ── Phase 16: Instability self-preservation gates ───────────────────
        _p16_im = getattr(self, "instability_monitor", None)
        if _p16_im is not None:
            _p16_risk = _p16_im.instability_risk
            _p16_last_mode = getattr(self, "_last_goal_mode", "")
            _p16_safe_boost = (
                1.0 + _p16_im.caution_bias * 0.85 + _p16_im.collapse_memory * 0.25
            )
            _p16_risky_damp = max(0.18, 1.0 - _p16_risk * 0.75)
            _p16_social_damp = max(0.20, 1.0 - _p16_im.withdrawal_bias * 0.70)
            for _gs in list(final.keys()):
                _mode = self._goal_mode(_gs)
                if _mode in ("rest", "consolidate"):
                    final[_gs] = min(3.0, final[_gs] * _p16_safe_boost)
                elif _mode in ("explore", "search", "execute"):
                    final[_gs] = max(0.05, final[_gs] * _p16_risky_damp)
                elif _mode in ("interact", "respond"):
                    final[_gs] = max(0.05, final[_gs] * _p16_social_damp)

                if _p16_last_mode and _mode != _p16_last_mode and _p16_risk > 0.55:
                    _switch_damp = max(0.55, 1.0 - (_p16_risk - 0.55) * 0.90)
                    final[_gs] = final[_gs] * _switch_damp

                final[_gs] = final[_gs] * _p16_im.penalty_for_mode(_mode)

            if _p16_im.recent_collapse:
                for _gs in list(final.keys()):
                    _mode = self._goal_mode(_gs)
                    if _mode in ("rest", "consolidate"):
                        final[_gs] = min(
                            3.0, final[_gs] * (1.0 + _p16_im.anchor_pull * 0.60)
                        )
                    elif _mode in ("explore", "search", "execute"):
                        final[_gs] = max(
                            0.05, final[_gs] * (1.0 - _p16_im.anchor_pull * 0.40)
                        )
        # ── End Phase 16 _evaluate_goal block ───────────────────────────────

        # ── Phase 17: Irreversible identity drift gates ─────────────────────
        _p17_id = getattr(self, "identity_drift", None)
        if _p17_id is not None:
            _p17_muls = _p17_id.goal_multipliers()
            _p17_curr = getattr(self, "_last_goal_mode", "")
            for _gs in list(final.keys()):
                _mode = self._goal_mode(_gs)
                final[_gs] = final[_gs] * _p17_muls.get(_mode, 1.0)
                final[_gs] = final[_gs] * _p17_id.switch_multiplier(_mode, _p17_curr)
                _id_cost = _p17_id.identity_cost(_mode)
                final[_gs] = max(0.05, final[_gs] * (1.0 - _id_cost * 0.45))

                if _p17_id.self_mismatch > 0.35 and _mode in ("rest", "consolidate"):
                    final[_gs] = min(3.0, final[_gs] * (1.0 + _p17_id.self_mismatch * 0.40))

            if (
                _p17_id.narrative_lens == "growth"
                and _p17_id.resilience_index > _p17_id.scar_index
            ):
                for _gs in list(final.keys()):
                    _mode = self._goal_mode(_gs)
                    if _mode in ("explore", "execute"):
                        final[_gs] = min(
                            3.0,
                            final[_gs]
                            * (1.0 + (_p17_id.resilience_index - _p17_id.scar_index) * 0.25),
                        )
        # ── End Phase 17 _evaluate_goal block ───────────────────────────────

        # ── Apply integration strength as continuous multiplier ──────────
        # Every final score is scaled by _integration_strength so higher phi
        # uniformly amplifies the winning goal's advantage.  This makes
        # integration a strictly necessary causal factor: remove phi and all
        # scores collapse toward zero simultaneously.
        for _gs in list(final.keys()):
            final[_gs] *= _integration_strength

        # If the best goal was blocked, generate a replacement intent
        scoring_winner = max(final, key=final.get)

        # ── ENFORCEMENT 4: Goal causality assertion ───────────────────────
        # Rule: assert selected_action == argmax(goal_influence)
        # If the scoring winner has zero causal weight AND the dynamic goal bias
        # produced no signal, the goal system is not causally governing selection.
        _winner_causal = causal_bonus.get(scoring_winner, 0.0)
        _winner_dynamic = self._dynamic_goal_bias.get(
            self._goal_mode(scoring_winner), 0.0
        )
        _winner_final = final.get(scoring_winner, 0.0)
        _all_zero_causal = all(
            causal_bonus.get(g, 0.0) == 0.0
            and self._dynamic_goal_bias.get(self._goal_mode(g), 0.0) == 0.0
            for g in final
        )
        if _all_zero_causal and _winner_final <= 0.0:
            # ── FORCED GOAL GENERATION (no "rest" fallback) ───────────────
            # The system must not coast.  Ask the self-model to generate a
            # goal from first principles; only raise GoalSystemFailure if
            # self-model is also empty (fully degenerate state).
            _forced = sm.propose_goals(d, em, self._tick)
            if _forced:
                # Accumulate weights per goal and pick the strongest
                _forced_accum: Dict[str, float] = {}
                for _fg, _fw in _forced:
                    _forced_accum[_fg] = _forced_accum.get(_fg, 0.0) + _fw
                scoring_winner = max(_forced_accum, key=_forced_accum.get)
                self.stream.append(
                    f"[GOAL-CAUSALITY-FAIL] winner={max(final, key=final.get)} "
                    f"causal={_winner_causal:.4f} dynamic={_winner_dynamic:.4f} "
                    f"→ self-model forced generation: {scoring_winner}"
                )
            else:
                # No causal basis AND self-model empty → associative fallback.
                # Pick highest raw score; default "explore" if final is empty.
                # System keeps running in degraded/associative mode.
                _assoc_pick = max(final, key=final.get) if final else "explore"
                scoring_winner = _assoc_pick
                self.stream.append(
                    f"[GOAL-CAUSALITY-FAIL] causal_basis_absent + self_model_empty "
                    f"→ associative fallback: {scoring_winner} phi={_phi_now:.4f}"
                )
        _self_goal_leader = max(self_goal_bonus, key=self_goal_bonus.get)
        _self_goal_pressure = self_goal_bonus.get(_self_goal_leader, 0.0)
        if (
            _self_goal_pressure > 0.45
            and final.get(_self_goal_leader, 0.0)
            >= final.get(scoring_winner, 0.0) - 0.22
        ):
            if _self_goal_leader != scoring_winner:
                self.stream.append(
                    f"[SELF-GOAL] Goal pressure shifts selection: {scoring_winner} → {_self_goal_leader} "
                    f"(pressure={_self_goal_pressure:.2f})"
                )
            scoring_winner = _self_goal_leader
        # ── ENFORCEMENT 5 + Record counterfactual: winner vs. best rejected alternative ───────
        _sorted_goals = sorted(final.items(), key=lambda x: -x[1])
        if len(_sorted_goals) >= 2:
            _cf_winner, _cf_w_score = _sorted_goals[0]
            _cf_reject, _cf_r_score = _sorted_goals[1]
            # Build explicit rejection reason (why NOT the alternative)
            _rej_causal = causal_bonus.get(_cf_reject, 0.0)
            _win_causal = causal_bonus.get(_cf_winner, 0.0)
            _rej_norm = _norm_penalty.get(_cf_reject, 0.0)
            _rejection_reason = (
                f"score_delta={_cf_w_score - _cf_r_score:.4f}"
                f" winner_causal={_win_causal:.4f}"
                f" rejected_causal={_rej_causal:.4f}"
                f" rejected_norm_penalty={_rej_norm:.4f}"
            )
            self._last_counterfactual = CounterfactualRecord(
                tick=getattr(brain, "tick_count", self._tick),
                chosen_goal=_cf_winner,
                chosen_score=round(_cf_w_score, 4),
                chosen_causal=round(causal_bonus.get(_cf_winner, 0.0), 4),
                rejected_goal=_cf_reject,
                rejected_score=round(_cf_r_score, 4),
                score_delta=round(_cf_w_score - _cf_r_score, 4),
                cf_outcome_est=_rejection_reason,
            )
            # ── COUNTERFACTUAL FEEDBACK: update future decision bias ──────
            # The outcome record accumulates as a behavioural prior so the
            # system learns from its own choices: winning goals get a small
            # positive bias; rejected alternatives get a small negative bias.
            # This closes the loop: future_decision_bias += counterfactual_result
            _cf_delta = max(0.0, _cf_w_score - _cf_r_score)
            _cf_win_mode = self._goal_mode(_cf_winner)
            _cf_rej_mode = self._goal_mode(_cf_reject)
            if _cf_win_mode in self._dynamic_goal_bias:
                self._dynamic_goal_bias[_cf_win_mode] = max(
                    -0.5,
                    min(0.5, self._dynamic_goal_bias[_cf_win_mode] + 0.015 * _cf_delta),
                )
            if _cf_rej_mode in self._dynamic_goal_bias and _cf_rej_mode != _cf_win_mode:
                self._dynamic_goal_bias[_cf_rej_mode] = max(
                    -0.5,
                    min(0.5, self._dynamic_goal_bias[_cf_rej_mode] - 0.010 * _cf_delta),
                )
        # ── Central reason-giving: causal + epistemic + normative + phenomenal ─
        _dr_drives = sorted(
            [
                ("information_hunger", d.information_hunger),
                ("expression_pressure", d.expression_pressure),
                ("coherence_need", d.coherence_need),
                ("rest_need", d.rest_need),
            ],
            key=lambda x: -x[1],
        )
        _dom_drive, _dom_drive_val = _dr_drives[0] if _dr_drives else ("none", 0.0)
        self._last_decision_reason = {
            "tick": getattr(brain, "tick_count", self._tick),
            "goal": scoring_winner,
            "causal_conf": round(causal_bonus.get(scoring_winner, 0.0), 4),
            "value": round(value_bonus.get(scoring_winner, 0.0), 4),
            "norm_penalty": round(_norm_penalty.get(scoring_winner, 0.0), 4),
            "dominant_drive": _dom_drive,
            "drive_val": round(_dom_drive_val, 3),
            "em_dominant": em.dominant(),
            "phenom_sig": self.phenomenal_buffer.experiential_signature(),
            "exist_threat": round(_et, 3),
            "self_agency": round(self.self_model.agency_confidence, 4),
            "self_continuity": round(self.self_model.continuity_estimate, 4),
            "self_ownership": round(self.self_model.ownership_confidence, 4),
            "self_uncertainty": round(self.self_model.uncertainty, 4),
            "self_tensions": len(getattr(self.self_model, "self_tensions", [])),
            "self_contradictions": len(
                getattr(self.self_model, "self_contradictions", [])
            ),
            "meta_gaps": len(self.meta.gaps(4)),
            "accessible_concepts": len(self.gateway.report_all_accessible()),
            "phi_surrogate": round(self.integration_probe.phi_surrogate(), 4),
        }
        _self_signal = (
            abs(self.self_model.agency_confidence - 0.5)
            + abs(self.self_model.continuity_estimate - 0.5)
            + abs(self.self_model.ownership_confidence - 0.5)
            + self.self_model.uncertainty * 0.25
            + min(0.3, 0.08 * len(getattr(self.self_model, "self_tensions", [])))
            + min(0.3, 0.08 * len(getattr(self.self_model, "self_contradictions", [])))
        )
        self._last_decision_grounding = {
            "goal": scoring_winner,
            "tick": getattr(brain, "tick_count", self._tick),
            "integration_ready": self.integration_probe.phi_surrogate() > 0.04,
            "global_access_ready": len(self.gateway.report_all_accessible()) > 0,
            "self_model_signal": round(_self_signal, 4),
            "goal_scores_present": scoring_winner in final,
        }
        # Emit full reason to stream on goal change (transparent metacognition)
        if scoring_winner != self.state.goal:
            _lk_r = getattr(self.lang, "current", "de")
            if _lk_r == "de":
                _reason_str = (
                    f"[REASON] Zielwechsel → '{scoring_winner}' |"
                    f" kausal: conf={self._last_decision_reason['causal_conf']:.2f} |"
                    f" Antrieb: {_dom_drive}={_dom_drive_val:.2f} |"
                    f" Norm: penalty={self._last_decision_reason['norm_penalty']:.2f} |"
                    f" phänom: {self._last_decision_reason['phenom_sig']}"
                )
            else:
                _reason_str = (
                    f"[REASON] Goal change → '{scoring_winner}' |"
                    f" causal: conf={self._last_decision_reason['causal_conf']:.2f} |"
                    f" drive: {_dom_drive}={_dom_drive_val:.2f} |"
                    f" norm: penalty={self._last_decision_reason['norm_penalty']:.2f} |"
                    f" phenom: {self._last_decision_reason['phenom_sig']}"
                )
            self.stream.append(_reason_str)
        _replacement_map = {
            "respond": "rest",
            "explore": "consolidate",
        }
        if scoring_winner in _blocked_goals:
            # Substitute with a stabilisation intent
            _alt = _replacement_map.get(scoring_winner, "rest")
            self.stream.append(
                f"[FEASIBILITY] {scoring_winner} blocked "
                f"(motor={_es.motor_readiness:.2f} visual={_es.visual_contact:.2f}) "
                f"→ {_alt}"
            )
            # Submit stabilisation goal to executive
            _exec_feas = getattr(brain, "_task_executive", None)
            if _exec_feas is not None:
                _stab_intent = {"respond": "idle_pose", "explore": "orient_head"}.get(
                    scoring_winner, "idle_pose"
                )
                _exec_feas.submit_goal(
                    _stab_intent,
                    context=f"feasibility_fallback:{scoring_winner}",
                    tick=brain.tick_count,
                )
            scoring_winner = _alt

        # ── Model-based planning: CEM over learned world model ──
        # Blend model-predicted terminal values into goal utility BEFORE
        # picking the winner, so learned anticipation is always weighted.
        _plan_goal, _plan_value, _plan_desc = self.model_planner.plan(
            self.learned_world,
            self.learned_world.encode_observation(
                em,
                self.body,
                self.embodied_self,
                self.task_frame,
                getattr(brain, "_world_state", None),
            ),
            self.body,
            em,
            id_compat,
            self._tick,
            world=getattr(brain, "_world_state", None),
        )
        # Blend model confidence into ALL candidates' final scores
        _model_conf = getattr(self.learned_world, "confidence", 0.0)
        if _plan_goal and _model_conf > 0.05:
            # Predicted terminal value gets weighted by model confidence
            _model_weight = min(0.5, _model_conf * 0.6)
            for g_name in final:
                if g_name == _plan_goal:
                    final[g_name] += _plan_value * _model_weight
                else:
                    # Other goals get a mild penalty proportional to how much
                    # the model prefers _plan_goal
                    final[g_name] -= _plan_value * _model_weight * 0.1

        # Re-evaluate scoring winner with model-blended scores
        scoring_winner = max(final, key=final.get)
        if scoring_winner in _blocked_goals:
            _alt = _replacement_map.get(scoring_winner, "rest")
            scoring_winner = _alt

        # Direct model override: lowered threshold (0.4 instead of 0.8)
        # so learned anticipation can steer goals more readily
        if _plan_goal and _plan_value > final.get(scoring_winner, 0.0) * 0.4:
            scoring_winner = _plan_goal
            self.stream.append(f"[PLAN] {_plan_desc}")
            self._plan_target_binding = self.model_planner.last_target_binding
        else:
            self._plan_target_binding = None

        # ── Merge: PFC wins if it made a specific choice; otherwise scoring ──
        current = self.state.goal or "explore"
        if pfc_goal and pfc_goal != current:
            winner = pfc_goal
        else:
            winner = scoring_winner

        # ── Identity veto: block rapid goal switching when impulse_control high ──
        if winner != current:
            veto = self.identity_arc.veto_check("rapid_goal_switch", context=winner)
            if veto:
                winner = current  # hold current goal

        # EMA-update expected_reward of winner — prefer per-goal outcome
        # data when available, fall back to global valence for cold goals.
        for g in self._goal_objects:
            if g.name == winner:
                _ema_data = self._goal_outcome_ema.get(g.name)
                if _ema_data and _ema_data[1] >= 3:
                    # Blend: 70% outcome-based EMA, 30% global valence
                    _outcome_val = _ema_data[0]
                    g.expected_reward = max(
                        0.0,
                        min(
                            1.0,
                            g.expected_reward * 0.90
                            + _outcome_val * 0.07
                            + em.valence() * 0.03,
                        ),
                    )
                else:
                    # Cold start: use global valence as before
                    g.expected_reward = max(
                        0.0, min(1.0, g.expected_reward * 0.95 + em.valence() * 0.05)
                    )
        # Expose for cf_engine / goal_synth wiring in tick loop
        self._last_causal_bonus = causal_bonus
        self._last_goal_scores = final
        return winner

    # ── Goal dispatch: cognitive → operative ────────────────────
    # Maps consciousness-level goals to concrete executive intents
    # so the body/skill system works along the current intention.
    _GOAL_TO_OPERATIVE: ClassVar[Dict[str, str]] = {
        "explore": "look_around",
        "respond": "attend_speaker",
        "rest": "idle_pose",
        "consolidate": "idle_pose",
    }

    def _dispatch_to_executive(self, brain: "Brain", goal: str) -> None:
        """Translate a consciousness goal into an operative executive goal
        with an explicit target binding (person, object, zone).

        Produces a target-bound submission so the executive knows not just
        *what* to do but *to whom / at what*.
        """
        _exec = getattr(brain, "_task_executive", None)
        if _exec is None:
            return
        _ws = getattr(brain, "_world_state", None)

        goal_mode = self._goal_mode(goal)
        operative = self._GOAL_TO_OPERATIVE.get(goal_mode, "idle_pose")
        _target_person = ""
        _target_object = ""

        # ── Consume planner's target binding if available ──
        _plan_bind = getattr(self, "_plan_target_binding", None)
        if _plan_bind:
            operative = _plan_bind.get("intent", operative)
            if _plan_bind.get("target_type") == "person":
                _target_person = _plan_bind.get("target_id", "")
            elif _plan_bind.get("target_type") == "object":
                _target_object = _plan_bind.get("target_id", "")
            self._plan_target_binding = None  # consume once

        # 5.1 — ToM strategy → goal context: query ToM for recommended approach
        # before binding target, so the strategy can influence operative choice
        _sm_ref = getattr(brain, "_social_manager", None)
        _primary_pid = _sm_ref.primary_interlocutor() if _sm_ref else None
        _tom_ctx = ""
        _person_recall: Optional[Dict] = None
        if _primary_pid is not None:
            _tom_strat = self.theory_of_mind.recommend_strategy(str(_primary_pid))
            _tom_action = _tom_strat.get("action", "")
            _tom_style = _tom_strat.get("style", "")
            # Recall person history for context-aware dispatch
            _person_recall = self.recall_for_person(_primary_pid, brain)
            if _tom_action:
                _tom_ctx = f"|tom:{_tom_action}"
            # ToM can override operative for respond goals (e.g. give space → look_around)
            if goal_mode == "respond" and _tom_action == "give_space":
                operative = "create_distance"
                _target_person = str(_primary_pid)
                _tom_override = True
            elif goal_mode == "respond" and _tom_strat.get("avoided_behaviour", ""):
                _avoided = _tom_strat["avoided_behaviour"].lower()
                # If the current operative matches avoided behaviour, switch
                if _avoided in operative or operative in _avoided:
                    operative = "attend_speaker"  # safe fallback
                _tom_override = False
            else:
                _tom_override = False
            # Trust threshold: high trust → more initiative
            _tom_trust_val = _tom_strat.get("trust", 0.5)
            if isinstance(_tom_trust_val, (int, float)) and _tom_trust_val > 0.7:
                if goal_mode == "respond" and operative == "attend_speaker":
                    operative = "inquire_person"  # upgrade to proactive
        else:
            _tom_override = False

        # Context-sensitive mapping for 'respond' — bind to best person
        if goal_mode == "respond" and _ws is not None and not _tom_override:
            _pred = _ws.predicates
            # Pick the primary interlocutor (nearest speaking, or nearest)
            _best_pid = ""
            _sm = getattr(brain, "_social_manager", None)
            if _sm is not None:
                _best_pid = str(_sm.primary_interlocutor() or "")
            if not _best_pid and _ws.persons:
                # Fallback: nearest person
                _best_pid = _ws.zone.nearest_person_id
            _target_person = _best_pid

            if _pred.greeting_done and getattr(_pred, "engagement_level", 0) > 0.5:
                operative = "inquire_person"
            elif _pred.person_visible:
                operative = "attend_speaker"
            else:
                operative = "look_around"
                _target_person = ""  # no person to bind

            # Refine operative using person recall context
            if _person_recall and _target_person:
                _pr_trust = _person_recall.get("trust", 0.5)
                _pr_fam = _person_recall.get("familiarity", 0.0)
                if _pr_fam > 0.6 and _pr_trust > 0.5:
                    operative = "inquire_person"  # familiar+trusted → deeper engagement
                elif _pr_trust < 0.3:
                    operative = "attend_speaker"  # low trust → cautious observation

        elif goal_mode == "explore" and _ws is not None:
            # Bind to an unknown/novel object if any, otherwise zone
            for oid, obj in getattr(_ws, "objects", {}).items():
                _target_object = obj.label
                break

        # Don't re-submit if executive already running same intent+target
        if _exec.is_busy and _exec.active_goal:
            _ag = _exec.active_goal
            if (
                _ag.intent == operative
                and _ag.target_person == _target_person
                and _ag.target_object == _target_object
            ):
                return

        # 6.4 — Self-consistency gate: warn in stream if identity coherence is low
        _consistency = self.identity_arc.consistency_score()
        _ctx = f"consciousness_goal:{goal}"
        if goal_mode != goal:
            _ctx += f"|mode:{goal_mode}"
        if _consistency < 0.3:
            self.stream.append(
                f"[IDENTITY] Low consistency ({_consistency:.2f}) — "
                f"goal '{operative}' may conflict with character"
            )
            _ctx += f"|low_consistency:{_consistency:.2f}"

        # Append ToM context tag for executive awareness
        if _tom_ctx:
            _ctx += _tom_ctx

        _exec.submit_goal(
            operative,
            context=_ctx,
            tick=self._tick,
            world=_ws,
            target_person=_target_person,
            target_object=_target_object,
        )

    def _goal_mode(self, goal_name: str) -> str:
        if goal_name in self._GOAL_TO_OPERATIVE:
            return goal_name
        atom = self.goal_synth.get_atom(goal_name)
        if atom is not None and atom.parent in self._GOAL_TO_OPERATIVE:
            return str(atom.parent)
        lowered = str(goal_name or "").lower()
        if lowered.startswith(("resolve_", "investigate_")):
            return "explore"
        if lowered.startswith("understand_"):
            return "respond"
        if lowered.startswith("reconcile_"):
            return "consolidate"
        return "rest"

    def _refresh_dynamic_goal_bias(self) -> None:
        bias = {"explore": 0.0, "consolidate": 0.0, "respond": 0.0, "rest": 0.0}
        top_non_base = [
            g
            for g in self.goal_synth.top_goals(8)
            if g.source != "base" and not g.closed
        ]
        dominant = ""
        dominant_score = 0.0
        for atom in top_non_base:
            mode = self._goal_mode(atom.name)
            score = max(0.0, atom.priority * atom.salience)
            bias[mode] += min(0.55, score * 0.22)
            if score > dominant_score:
                dominant = atom.name
                dominant_score = score
        self._dynamic_goal_bias = bias
        self._dominant_dynamic_goal = dominant if dominant_score > 0.18 else ""

    def _current_report_anchor(self) -> str:
        accessible = self.gateway.report_all_accessible()
        if accessible:
            return accessible[-1]
        concepts = self.workspace_concepts()
        if concepts:
            return concepts[-1]
        return ""

    def generate_report(
        self, content: str, concept: str = "", source: str = "report"
    ) -> str:
        """Single gated report path.  Output is always allowed; quality is graded.

        When gateway access is absent (low integration), the report is emitted
        with a quality prefix [~q=X.XX] instead of being blocked.  This ensures
        communication never stops — only degrades in coherence.
        """
        anchor = concept or self._current_report_anchor()
        if not anchor or not self.gateway.can_report(
            anchor,
            source=source,
            path="ConsciousnessCore.generate_report",
            condition=f"anchor={anchor or 'none'}",
        ):
            # Graded output: emit with quality marker instead of raising.
            _phi_q = (
                self.integration_probe.phi_surrogate()
                if hasattr(self, "integration_probe")
                else 0.0
            )
            _quality = max(0.1, min(1.0, _phi_q / 0.04))
            _marked = f"[~{_quality:.2f}] {content}"
            self._approved_reports.append(_marked)
            self.stream.append(
                f"[REPORT-DEGRADED q={_quality:.2f}] {source}:{(anchor or 'no_anchor')}"
            )
            return _marked
        self.gateway.mark_reported(anchor)
        self._approved_reports.append(content)
        self.stream.append(f"[REPORT] {source}:{anchor}")
        return content

    def drain_approved_reports(self) -> List[str]:
        reports = list(self._approved_reports)
        self._approved_reports.clear()
        return reports

    def decision_grounding(self) -> Dict[str, Any]:
        return dict(self._last_decision_grounding)

    def _current_self_social_context(
        self, brain: Optional["Brain"] = None
    ) -> Dict[str, Any]:
        _brain_ref = brain or getattr(self, "_brain_ref", None)
        _sm_ref = getattr(_brain_ref, "_social_manager", None) if _brain_ref else None
        _primary_pid = _sm_ref.primary_interlocutor() if _sm_ref else None
        if _primary_pid is None:
            return {}
        _ctx = {"primary_interlocutor": str(_primary_pid)}
        if _sm_ref is not None:
            try:
                _rel = _sm_ref.relationship_profile(_primary_pid, self.theory_of_mind)
            except Exception:
                _rel = {}
            if _rel:
                _ctx.update(_rel)
            try:
                _pm = _sm_ref.person_model(_primary_pid)
            except Exception:
                _pm = None
            if _pm is not None:
                _ctx["trust"] = getattr(_pm, "trust", 0.5)
                _ctx["familiarity"] = getattr(_pm, "familiarity", 0.0)
                _ctx["partner_preferences"] = dict(
                    getattr(_pm, "preferences", {}) or {}
                )
        try:
            _ctx.update(self.theory_of_mind.recommend_strategy(str(_primary_pid)))
        except Exception as _tom_e:
            # ToM failure is a structural signal, not a recoverable edge case.
            # Silence would make ToM optional.  Instead, inject social uncertainty
            # into the self-model so the failure has downstream consequences.
            self.self_model.uncertainty = min(1.0, self.self_model.uncertainty + 0.04)
            self.stream.append(
                f"[TOM-FAIL] recommend_strategy raised {type(_tom_e).__name__}: {_tom_e} "
                f"→ social context degraded, self-model uncertainty ↑"
            )
        return _ctx

    def _socialize_proactive_self_report(self, report: str, strength: float) -> str:
        _ctx = self._current_self_social_context()
        if not _ctx:
            return report
        _lk = getattr(self.lang, "current", "de")
        _action = str(_ctx.get("action", "engage"))
        _tone = str(_ctx.get("tone", "neutral"))
        _style = str(_ctx.get("style", "balanced"))
        try:
            _trust = float(_ctx.get("trust", 0.5))
        except Exception:
            _trust = 0.5
        if _action == "acknowledge_briefly" or _style == "brief":
            return (
                "Kurzer Selbsthinweis: Ich korrigiere gerade eine fehlerhafte Selbsteinschätzung."
                if _lk == "de"
                else "Brief self-note: I am correcting a faulty self-estimate right now."
            )
        if _action == "give_space" or _tone in ("careful", "gentle") or _trust < 0.35:
            return (
                "Ich sage das vorsichtig: Meine letzte Selbsteinschätzung war hier zu stark, und ich kalibriere sie gerade neu."
                if _lk == "de"
                else "I will put this carefully: my last self-estimate was too strong here, and I am recalibrating it now."
            )
        if _action in ("offer_support", "provide_detail", "engage") and _trust >= 0.45:
            if _lk == "de":
                return f"Ich muss hier selbstkritisch sein: {report[0].lower() + report[1:] if report else 'ich korrigiere mein Selbstmodell gerade.'}"
            return f"I need to be self-critical here: {report[0].lower() + report[1:] if report else 'I am correcting my self-model right now.'}"
        if strength > 0.75:
            return (
                f"Ich korrigiere mein Selbstmodell gerade deutlich: {report}"
                if _lk == "de"
                else f"I am making a substantial self-model correction right now: {report}"
            )
        return report

    def _reflect_on_action_outcome(
        self,
        outcome: Any,
        tick: int,
        em_desc: str,
    ) -> Optional[str]:
        """Bind each action outcome to an explicit first-person self-assessment."""
        _intent_to_goal = {
            "look_around": "explore",
            "attend_speaker": "respond",
            "idle_pose": "rest",
        }
        _goal = _intent_to_goal.get(
            getattr(outcome, "intent", ""), getattr(outcome, "intent", "")
        )
        _domain_map = {
            "explore": "exploratory_control",
            "respond": "social_response",
            "consolidate": "coherence_regulation",
            "rest": "self_preservation_regulation",
        }
        _domain = _domain_map.get(_goal or "", "general_agency")
        _reason = self._last_decision_reason or {}
        _expected = 0.5
        if _reason.get("goal") == _goal:
            _expected = max(
                0.0,
                min(
                    1.0,
                    float(_reason.get("causal_conf", 0.5)) * 0.65
                    + self.self_model.agency_confidence * 0.35,
                ),
            )
        _reward = float(getattr(outcome, "reward", 0.0))
        _observed = max(0.0, min(1.0, 0.5 + _reward * 0.5))
        if getattr(outcome, "success", False):
            _observed = max(_observed, 0.7)
        else:
            _observed = min(_observed, 0.3)
        _self_social_ctx = self._current_self_social_context()
        _contradiction = self.self_model.observe_self_discrepancy(
            _domain,
            _expected,
            _observed,
            tick,
            condition_class=self.self_model.infer_condition_classes(
                self.body,
                None,
                _self_social_ctx,
            )[-1],
            social_context=_self_social_ctx,
            context=getattr(outcome, "executed_skill", ""),
        )
        if _contradiction:
            self.self_model.uncertainty = min(1.0, self.self_model.uncertainty + 0.08)
            self.drives.coherence_need = min(1.0, self.drives.coherence_need + 0.12)
            self.long_horizon.record_pattern("continuity_alarm")
            self.long_horizon.record_pattern("repeated_failure", _domain)
        _skill = getattr(outcome, "executed_skill", "") or getattr(
            outcome, "intent", "action"
        )
        if _contradiction and _expected > _observed:
            _insight_de = (
                f"Diese Aktion zeigt, dass ich mich bei {_domain} überschätzt habe: "
                f"{_skill} war schwächer als erwartet."
            )
            _insight_en = (
                f"This action shows that I overestimated myself in {_domain}: "
                f"{_skill} was weaker than expected."
            )
        elif _contradiction:
            _insight_de = (
                f"Diese Aktion zeigt, dass ich mich bei {_domain} unterschätzt habe: "
                f"{_skill} gelang besser als erwartet."
            )
            _insight_en = (
                f"This action shows that I underestimated myself in {_domain}: "
                f"{_skill} worked better than expected."
            )
        elif getattr(outcome, "success", False):
            _insight_de = (
                f"Diese Aktion stützt mein aktuelles Selbstmodell: "
                f"{_skill} war unter diesen Bedingungen tragfähig."
            )
            _insight_en = (
                f"This action supports my current self-model: "
                f"{_skill} was viable under these conditions."
            )
        else:
            _insight_de = (
                f"Diese Aktion war ein begrenzender Hinweis: "
                f"{_skill} hat meine aktuellen Grenzen sichtbar gemacht."
            )
            _insight_en = (
                f"This action revealed a limit: "
                f"{_skill} exposed one of my current constraints."
            )
        _lk = getattr(self.lang, "current", "de")
        _report = _insight_de if _lk == "de" else _insight_en
        try:
            self.generate_report(
                _report,
                concept=self._current_report_anchor(),
                source="self_report_action",
            )
            self.self_model.last_action_self_report = _report
            self.stream.append(f"[SELF-REPORT] {_report}")
            self.episodic.record(tick, "self_report_action", _report[:140], em_desc)
        except ReportViolationError:
            self.episodic.record(tick, "self_report_blocked", _report[:140], em_desc)
        _mismatch = abs(_expected - _observed)
        if (
            _mismatch > 0.60 or getattr(outcome, "reward", 0.0) < -0.45
        ) and tick - self._last_proactive_self_report_tick > 180:
            _social_report = self._socialize_proactive_self_report(
                _report, min(1.0, _mismatch)
            )
            try:
                self.generate_report(
                    _social_report,
                    concept=self._current_report_anchor(),
                    source="proactive_self_report",
                )
                self.self_model.last_action_self_report = _social_report
                self._pending_proactive_self_report = _social_report
                self._pending_proactive_self_report_strength = max(
                    self._pending_proactive_self_report_strength,
                    min(1.0, _mismatch),
                )
            except ReportViolationError:
                self.episodic.record(
                    tick, "proactive_self_report_blocked", _social_report[:140], em_desc
                )
        return _report

    def _maintain_self_horizon_goals(self, tick: int) -> List[str]:
        """Spawn and update persistent self-goals beyond immediate body protection."""
        spawned: List[str] = []
        existing = {g.description.lower(): g for g in self.long_horizon.active_goals()}

        def _has_fragment(fragment: str) -> bool:
            frag = fragment.lower()
            return any(frag in desc for desc in existing)

        def _add_self_goal(
            description: str,
            category: str,
            priority: int,
            milestones: List[Tuple[str, str]],
        ) -> None:
            gc = self.long_horizon.add_goal(
                description,
                category=category,
                priority=priority,
                tick=tick,
            )
            gc.milestones.clear()
            for idx, (ms_text, ms_intent) in enumerate(milestones):
                gc.add_milestone(
                    ms_text,
                    executable_intent=ms_intent,
                    milestone_id=f"{gc.goal_id}_self_{idx}",
                )
            gc.add_journal("spawned from self-maintenance")
            spawned.append(description)

        _recent_contras = self.self_model.self_contradictions[-3:]
        if _recent_contras and not _has_fragment("self-model coherence"):
            _add_self_goal(
                "consolidate self-model coherence and resolve contradictions",
                category="consolidate",
                priority=8,
                milestones=[
                    ("stabilise under low load after contradiction", "idle_pose"),
                    (
                        "test corrected self-estimate in social response",
                        "attend_speaker",
                    ),
                    (
                        "sample disconfirming evidence about current limits",
                        "look_around",
                    ),
                ],
            )

        if self.self_model.agency_confidence < 0.45 and not _has_fragment(
            "agency limits"
        ):
            _add_self_goal(
                "explore agency limits and rebuild control model",
                category="explore",
                priority=7,
                milestones=[
                    ("probe controllable action channels", "look_around"),
                    ("retest guided response under attention", "attend_speaker"),
                    ("stabilise after agency loss", "idle_pose"),
                ],
            )

        if (
            self.self_model.continuity_estimate < 0.55
            or self.self_model.ownership_confidence < 0.60
        ) and not _has_fragment("self-continuity"):
            _add_self_goal(
                "rest to restore self-continuity and body ownership",
                category="rest",
                priority=8,
                milestones=[
                    ("lower load and regain bodily stability", "idle_pose"),
                    ("re-establish coherent sensorimotor match", "look_around"),
                    ("resume calibrated engagement", "attend_speaker"),
                ],
            )

        for gc in self.long_horizon.active_goals():
            _desc = gc.description.lower()
            if (
                "self-model coherence" in _desc
                and not self.self_model.self_contradictions
            ):
                for idx, ms in enumerate(gc.milestones):
                    if not ms.completed:
                        gc.complete_milestone(idx, tick)
                        gc.add_journal("contradictions currently quiet")
                        break
            if "agency limits" in _desc and self.self_model.agency_confidence > 0.68:
                for idx, ms in enumerate(gc.milestones):
                    if not ms.completed:
                        gc.complete_milestone(idx, tick)
                        gc.add_journal("agency confidence improved")
                        break
            if (
                "self-continuity" in _desc
                and self.self_model.continuity_estimate > 0.72
                and self.self_model.ownership_confidence > 0.72
            ):
                for idx, ms in enumerate(gc.milestones):
                    if not ms.completed:
                        gc.complete_milestone(idx, tick)
                        gc.add_journal("continuity and ownership recovered")
                        break

        return spawned

    def _apply_goal(self, brain: "Brain", goal: str) -> None:
        """
        Apply goal-biasing currents into appropriate regions.
        Also feeds self-model knowledge gaps into web attention so the
        system actively seeks to fill what it knows it lacks ('I' directs learning).
        """
        # ── Dispatch to executive: translate cognitive goal → operative goal ──
        self._dispatch_to_executive(brain, goal)
        goal_mode = self._goal_mode(goal)

        pfc = brain.prefrontal
        if not pfc.excitatory:
            return
        pfc_n = len(pfc.excitatory)

        if goal_mode == "explore":
            # Boost PFC + sensory_web to seek new information
            brain.prefrontal.inject([2.0] * min(8, pfc_n) + [0.0] * max(0, pfc_n - 8))
            sw_n = len(brain.sensory_w.excitatory)
            brain.sensory_w.inject([1.5] * min(10, sw_n) + [0.0] * max(0, sw_n - 10))
            # Self-model directs attention: feed known gaps into web curiosity
            if brain._use_web:
                for gap in self.self_model.known_gaps[:2]:
                    brain._web_enc.add_interest_topic(gap.capitalize())

        elif goal_mode == "consolidate":
            # Gentle PFC activation promotes memory encoding
            brain.prefrontal.inject([1.2] * pfc_n)
            # Hippocampal injection to strengthen engrams during consolidation
            hipp_n = len(brain.hippocampus.excitatory)
            brain.hippocampus.inject(
                [0.8] * min(12, hipp_n) + [0.0] * max(0, hipp_n - 12)
            )

        elif goal_mode == "respond":
            # Amygdala → motor urgency
            amy_exc = brain.amygdala.excitatory
            n = min(5, len(amy_exc))
            brain.amygdala.inject([2.5] * n + [0.0] * (len(amy_exc) - n))

        elif goal_mode == "rest":
            # PFC→Amygdala inhibition: dampen emotional reactivity during rest
            amy_exc = brain.amygdala.excitatory
            n_amy = len(amy_exc)
            if n_amy > 0:
                brain.amygdala.inject(
                    [-1.2] * min(15, n_amy) + [0.0] * max(0, n_amy - 15)
                )

        # PFC emotional regulation: consolidate goal also calms amygdala
        if goal_mode == "consolidate":
            amy_exc = brain.amygdala.excitatory
            n_amy = len(amy_exc)
            if n_amy > 0:
                brain.amygdala.inject(
                    [-0.6] * min(10, n_amy) + [0.0] * max(0, n_amy - 10)
                )

    # ── Inner monologue ────────────────────────────────────────

    def _monologue(
        self,
        brain: "Brain",
        em: "EmotionalState",
        state: ConsciousnessState,
    ) -> str:
        """
        Inner monologue — a genuine first-person thought sentence grounded
        in current beliefs, emotion, and workspace focus.
        """
        dom = em.dominant()
        concept = list(self._concepts)[-1] if self._concepts else "—"

        # Collect related concepts from concept graph
        nb = self.concept_graph.neighbors(concept, 3) if concept != "—" else []
        related = [c for c, _ in nb]

        # Decide thought type based on emotional state + drive pressures
        if dom == "curiosity" or self.drives.information_hunger > 0.5:
            t_type = "question"
        elif self.drives.coherence_need > 0.6 or state.goal == "consolidate":
            t_type = "reflection"
        elif self.drives.expression_pressure > 0.5 or state.ignition:
            t_type = "hypothesis"
        else:
            t_type = "assertion"

        # Look up known beliefs about the focus concept
        triples = self.belief_store.query(concept, min_confidence=0.3)

        # Generate a real first-person sentence via LanguageProducer
        line = self.lang.inner_voice(
            concept,
            t_type,
            related,
            dom,
            [(r, o, c) for r, o, c in triples] if triples else [],
        )

        # Append ignition / replay markers if active
        if state.ignition:
            ign = (
                f"  [Zündung #{self._ignition_count}]"
                if self.lang._lang == "de"
                else f"  [Ignition #{self._ignition_count}]"
            )
            line += ign
        if state.replaying:
            replay_note = (
                "  [Wiedergabe aktiv]"
                if self.lang._lang == "de"
                else "  [Replay active]"
            )
            line += replay_note

        self._last_thought = line
        return line

    # ── Public accessors ───────────────────────────────────────

    @property
    def ignition_count(self) -> int:
        return self._ignition_count

    def _compute_salience(
        self, brain: "Brain", em: "EmotionalState"
    ) -> Dict[str, float]:
        """
        Composite salience per region (Fix 1 + Fix 10)::

          salience = 0.50 * activity
                   + 0.25 * |prediction_error_for_region|
                   + 0.15 * arousal * (1 + curiosity*0.5)
                   + 0.10 * goal_relevance

        This replaces the simple count-threshold ignition check.
        A region with moderate activity but high prediction error and
        during high arousal can win global broadcast over a routinely
        active but unsurprising region.
        """
        arousal = em.arousal()
        curiosity = em.curiosity
        pred_errs = self.predictor.errors
        goal = self.state.goal

        goal_weights: Dict[str, float] = {
            "explore": {
                "sensory_web": 0.8,
                "prefrontal": 0.6,
                "hippocampus": 0.4,
                "association": 0.4,
            },
            "consolidate": {"hippocampus": 0.8, "prefrontal": 0.5, "association": 0.4},
            "respond": {"motor": 0.8, "prefrontal": 0.6, "amygdala": 0.5},
            "rest": {"hippocampus": 0.3},
        }.get(goal, {})

        salience: Dict[str, float] = {}
        for region in brain._all_regions:
            n = region.name
            act = brain.region_activity.get(n, 0.0)
            perr = abs(pred_errs.get(n, 0.0))
            grel = goal_weights.get(n, 0.0)
            salience[n] = (
                0.50 * act
                + 0.25 * perr
                + 0.15 * arousal * (1.0 + curiosity * 0.5)
                + 0.10 * grel
            )
        return salience

    def _generate_inner_thought(self, em: "EmotionalState") -> Optional[str]:
        """
        Spontaneous inner thought without external input.

        Uses LanguageProducer to produce real first-person sentences
        instead of template status strings.  Types mirror the existing
        four categories (question / hypothesis / observation / recall)
        but now produce actual bilingual prose.
        """
        import random

        if not self._concepts:
            return None

        # Body urgency takes priority
        if hasattr(self, "body") and self.body.homeostatic_urgency() > 0.35:
            _lk_sv = getattr(self.lang, "current", "de")
            _ev = self.body.existential_voice(_lk_sv)
            return _ev if _ev else f"[!] {self.body.describe()}"

        concept = list(self._concepts)[-1]
        dom = em.dominant()

        # Bias thought type toward current emotional state
        weights = [
            ("question", 0.3 + em.curiosity * 0.5),
            ("hypothesis", 0.2 + em.calm * 0.3),
            ("observation", 0.2 + em.surprise * 0.4),
            ("recall", 0.1 + em.sadness * 0.3),
        ]
        total_w = sum(w for _, w in weights)
        r = random.random() * total_w
        cumul = 0.0
        thought_type = "observation"
        for tname, w in weights:
            cumul += w
            if r <= cumul:
                thought_type = tname
                break

        nb = self.concept_graph.neighbors(concept, 3)
        related = [c for c, _ in nb]
        triples = self.belief_store.query(concept, min_confidence=0.3)

        if thought_type == "question":
            self.drives.information_hunger = min(
                1.0, self.drives.information_hunger + 0.05
            )
            return "[?] " + self.lang.inner_voice(
                concept,
                "question",
                related,
                dom,
                [(r, o, c) for r, o, c in triples],
            )

        elif thought_type == "hypothesis":
            self.drives.expression_pressure = min(
                1.0, self.drives.expression_pressure + 0.04
            )
            # Use causal chain if available, else fall back to neighbours
            chain = self.belief_store.causal_chain(concept, max_depth=3)
            chain_related = chain[1:3] if len(chain) >= 2 else related
            return "[~] " + self.lang.inner_voice(
                concept,
                "hypothesis",
                chain_related,
                dom,
                [(r, o, c) for r, o, c in triples],
            )

        elif thought_type == "observation":
            # Surface world-model prediction or emotional memory
            wm_lines = self.world_model.summarise(1)
            if wm_lines and random.random() < 0.25:
                return "[~] " + wm_lines[0]
            stored_em = self._emotional_memory.retrieve(concept)
            if stored_em and triples:
                rel, obj, _ = triples[0]
                return "[o] " + self.lang.assertion(concept, rel, obj)
            return "[o] " + self.lang.inner_voice(
                concept,
                "observation",
                related,
                dom,
                [(r, o, c) for r, o, c in triples],
            )

        else:  # recall
            brain_ref = getattr(self, "_brain_ref", None)
            if brain_ref is not None:
                ws = self.workspace_concepts()
                if ws:
                    eps = brain_ref.hippocampus.recall_episodes(ws, top_n=1)
                    if eps:
                        _tick, ep_concepts, ep_emotion = eps[0]
                        ep_str = ", ".join(ep_concepts[:5])
                        return f"[<] {ep_emotion}: {ep_str}"
                    recalled = brain_ref.hippocampus.semantic_recall(ws, top_n=3)
                    if recalled:
                        return "[<] " + self.lang.inner_voice(
                            ws[-1],
                            "reflection",
                            recalled[:2],
                            dom,
                            self.belief_store.query(ws[-1], min_confidence=0.3)[:1],
                        )
            last_ep = self.episodic.last_of_kind("concept")
            if last_ep:
                return f"[<] {last_ep.content[:70].rstrip()}"
            return None

    @property
    def recent_conclusions(self) -> List[str]:
        return list(self._conclusions)[-5:]

    @property
    def known_concepts(self) -> List[str]:
        return list(self._concepts)

    def workspace_concepts(self) -> List[str]:
        """
        Return the currently 'conscious' concepts — the small set that
        are receiving active attention right now.

        This is the GLOBAL WORKSPACE output: a salience-driven competition
        where concepts earn presence through recency, emotional marking,
        prediction error, social relevance, and goal compatibility.
        """
        if not self._concepts:
            return []
        # Collect unique recent candidates
        recent = list(self._concepts)[-50:]
        seen: set = set()
        candidates: List[str] = []
        for c in reversed(recent):
            if c not in seen:
                seen.add(c)
                candidates.append(c)
            if len(candidates) >= 25:
                break
        # Score by salience
        scored: List[tuple] = []
        for c in candidates:
            s = self._concept_salience.get(c, 0.0)
            # Recency bonus — position in deque
            try:
                _idx = (
                    len(self._concepts)
                    - 1
                    - list(reversed(list(self._concepts))).index(c)
                )
                _recency = max(0.0, 1.0 - (len(self._concepts) - 1 - _idx) / 50.0)
            except ValueError:
                _recency = 0.0
            scored.append((c, s + _recency * 0.3))
        scored.sort(key=lambda x: x[1], reverse=True)
        return [c for c, _ in scored[:12]]

    def _bump_salience(self, concept: str, amount: float) -> None:
        """Increase a concept's salience score (capped at 3.0).
        Concepts that reach high salience repeatedly are promoted to the stable tier."""
        cur = self._concept_salience.get(concept, 0.0)
        new_val = min(3.0, cur + amount)
        self._concept_salience[concept] = new_val
        # Promotion: if salience crossed 1.5, the concept is identity-stable
        if new_val >= 1.5 and concept not in self._stable_concepts:
            self._stable_concepts.add(concept)
        # Cap stable set size so it doesn't grow unbounded (keep top 80)
        if len(self._stable_concepts) > 80:
            # Evict stable concept with lowest current salience
            _worst = min(
                self._stable_concepts, key=lambda c: self._concept_salience.get(c, 0.0)
            )
            self._stable_concepts.discard(_worst)

    def _decay_salience(self) -> None:
        """Decay all salience values each tick and evict dead entries.
        Stable, anchor, and person concepts decay much slower than transient tokens."""
        _dead: list = []
        for c in self._concept_salience:
            if c in self._stable_concepts:
                # Stable tier: very slow decay — these are identity-core concepts
                self._concept_salience[c] *= 0.995
            elif (
                c.startswith("scene:")
                or c.startswith("person:")
                or c.startswith("speaker:")
            ):
                self._concept_salience[c] *= 0.985  # slower decay for anchors
            else:
                self._concept_salience[c] *= 0.97
            if self._concept_salience[c] < 0.01:
                # Stable concepts are never evicted by salience alone
                if c not in self._stable_concepts:
                    _dead.append(c)
        for c in _dead:
            del self._concept_salience[c]

    def record_semantic_input(
        self,
        concepts: List[str],
        tick: int,
        emotion_label: str,
        brain: "Brain",
    ) -> None:
        """
        Store an episode in the semantic hippocampus, update concept graph,
        and update PFC working memory.

        Call this every time meaningful text is injected — speech, web input,
        conclusions. This is the mechanism that makes the system actually
        REMEMBER what it has experienced (not just fire random spikes).
        """
        if not concepts:
            return

        # 1. Store episode in Hippocampus semantic memory
        brain.hippocampus.semantic_encode(tick, concepts, emotion_label)

        # 2. Update concept graph with co-occurrence
        em_arousal = (
            brain.emotion_state.arousal() if hasattr(brain, "emotion_state") else 0.3
        )
        for i, c1 in enumerate(concepts[:10]):
            for c2 in concepts[i + 1 : min(i + 5, len(concepts))]:
                self.concept_graph.observe_pair(c1, c2, emotional_val=em_arousal)

        # 3. Update PFC working memory
        brain.prefrontal.working_memory_update(concepts)

        # 4. Update meta-cognition depth tracking
        for c in concepts:
            self.meta.observe(
                c,
                brain.hippocampus.activity(),
                brain.prefrontal.activity(),
            )

        # 5. Learn propositions from joined concept text
        if len(concepts) >= 2:
            self.belief_store.learn_from_text(" ".join(concepts), base_confidence=0.45)

    @property
    def prediction_errors(self) -> Dict[str, float]:
        return dict(self.predictor.errors)

    @property
    def episodic_summary(self) -> str:
        return self.episodic.summarise(self._tick, window=500)

    def episodic_recent(self, n: int = 6) -> List[str]:
        return [e.describe() for e in self.episodic.recent(n)]

    @property
    def pending_messages(self) -> List[str]:
        """Drain and return all pending outbound messages."""
        msgs = self.drain_approved_reports()
        return msgs

    @property
    def comm_drive_level(self) -> float:
        """Current communication drive level [0, 1]."""
        return self.comm_drive.drive

    @property
    def personality_description(self) -> str:
        """Current self-determined personality summary."""
        return self.personality.describe()

    def notify_direct_address(self, user_text: str, brain: "Brain") -> None:
        """Prime the system to respond when directly addressed by the user.

        Safe to call from the GUI thread while the brain tick-thread is running.
        Does NOT call brain._tick() — only writes Python floats and calls
        inject_text_input() which is thread-safe under the GIL.
        """
        brain.inject_text_input(user_text)
        brain.speech_in = user_text

        # Extract concepts then store semantically (so the hippocampus
        # actually LEARNS what was said, not just fires random currents)
        self._extract_concepts(user_text, self._hipp_act_ema, self._pfc_act_ema)
        new_concepts = self.workspace_concepts()
        em_label = (
            brain.emotion_state.dominant()
            if hasattr(brain, "emotion_state")
            else "neutral"
        )
        self.record_semantic_input(new_concepts, brain.tick_count, em_label, brain)

        # Amygdala: appraise the input content (not activity rate)
        em_state = getattr(brain, "emotion_state", None)
        pfc_goal = getattr(brain.prefrontal, "active_goal", "") or ""
        appraisal = brain.amygdala.semantic_appraise(
            new_concepts, [pfc_goal] if pfc_goal else []
        )

        # PFC: force goal to "respond" because we're directly addressed
        brain.prefrontal.semantic_goal_select(
            new_concepts,
            em_stress=em_state.stress if em_state else 0.0,
            em_curiosity=em_state.curiosity if em_state else 0.3,
            em_fatigue=em_state.fatigue if em_state else 0.0,
            drives_expression=1.0,  # maximum — being directly talked to
            drives_information=self.drives.information_hunger,
            drives_coherence=self.drives.coherence_need,
            direct_address=True,
        )

        # Snapshot stream + conclusion lengths so _compose() can find
        # thoughts that emerged SPECIFICALLY after this user message.
        self.comm_drive._pending_user_text = user_text
        self.comm_drive._pending_stream_base = len(self.stream)
        self.comm_drive._pending_conclusion_base = len(self._conclusions)

        # Drive expression strongly
        self.drives.expression_pressure = min(
            1.0, self.drives.expression_pressure + 0.75
        )
        self.comm_drive._boost(0.65, "direct_address")
        self.comm_drive._last_spoke = min(
            self.comm_drive._last_spoke, self._tick - self.comm_drive._REFRACTORY
        )
        self._last_goal_chg = self._tick - GOAL_CHANGE_INTERVAL - 1

    # ─────────────────────────────────────────────────────────────────────
    # CONVERSATIONAL INTERFACE  — respond_to()
    # ─────────────────────────────────────────────────────────────────────

    def respond_to(
        self,
        user_text: str,
        brain: "Brain",
        processing_ticks: int = 140,
        planned_speech_act: "Optional[Any]" = None,
    ) -> "Tuple[str, dict]":
        """
        Process a direct user message and return a genuine response.

        No hardcoded templates, no LLM.  The response is assembled entirely
        from content produced by the live neural network during the processing
        window:
          • CommunicationDrive output  (concept–reasoning from _compose)
          • New reasoning conclusions  (from _reason())
          • Filtered inner-monologue   (tagged thoughts: [META] [BIOG] [!] …)
          • LanguageProducer integration paragraph from beliefs
          • Live emotional / body state as fallback

        Parameters
        ----------
        user_text         : str  — what the user said
        brain             : Brain
        processing_ticks  : int  — simulation ticks for grounded reasoning (default 140)

        Returns
        -------
        response : str   — assembled response text
        sidebar  : dict  — live state snapshot for UI display
        """
        # ── 0. Detect language from user text ────────────────────────────
        self.lang.detect_language(user_text)

        # ── 0b. Deliberation budget — bound processing cost ──────────────
        # Prevents dialogue from monopolising the simulation clock.
        # Budget is reduced when body is fatigued, during sleep, or under
        # high autosave pressure. This decouples language from global rhythm.
        _base_budget = processing_ticks
        _energy_factor = max(0.3, self.body.energy_reserve)
        _sleep_penalty = 0.4 if getattr(brain, "sleeping", False) else 1.0
        _budget = max(40, int(_base_budget * _energy_factor * _sleep_penalty))
        # Track deliberation cost for transparency
        _delib_start_tick = self._tick

        # ── 1. Learn any propositions from user text ──────────────────────
        self.belief_store.learn_from_text(user_text, base_confidence=0.60)

        # ── 2. Snapshot baselines ──────────────────────────────────────────
        n_conc_before = len(self._conclusions)
        n_stream_before = len(self.stream)

        # ── 3. Inject text + prime drives for direct social interaction ────
        brain.inject_text_input(user_text)
        # Extract concepts now so they influence the first ticks
        self._extract_concepts(user_text, self._hipp_act_ema, self._pfc_act_ema)

        # Social stimulus: being directly addressed should maximise expression
        self.drives.expression_pressure = min(
            1.0, self.drives.expression_pressure + 0.75
        )
        self.comm_drive._boost(0.55, "direct_address")

        # Force immediate goal re-evaluation toward "respond"
        _saved_goal_chg = self._last_goal_chg
        self._last_goal_chg = self._tick - GOAL_CHANGE_INTERVAL - 1

        # ── 4. Deliberation — sliced processing (non-monopolising) ────────
        # Instead of running all budget ticks in one blocking burst, process
        # in slices of DELIB_SLICE_PER_TICK interleaved with normal ticks.
        # This prevents stalling sleep, autosave, and sensor processing.
        _slice = DELIB_SLICE_PER_TICK
        _remaining = _budget
        while _remaining > 0:
            _chunk = min(_slice, _remaining)
            for _ in range(_chunk):
                brain._tick()
            _remaining -= _chunk
            # Yield control: if brain has other pending reply requests,
            # or if we've hit a deadline, stop early
            if _remaining > 0 and not brain._reply_requests.empty():
                break  # respect backpressure: other requests waiting

        # Restore goal timer so normal rhythm resumes after this call
        self._last_goal_chg = max(self._last_goal_chg, _saved_goal_chg)

        # ── 4. Collect genuine output ──────────────────────────────────────
        outbox_msgs = brain.get_outbound_messages()  # comm_drive output

        new_concs = [
            c for c in list(self._conclusions)[n_conc_before:] if c and len(c) > 15
        ]

        # Filter stream: drop bare emotion-monologue lines AND long-term
        # biography / strategy summaries — neither is relevant to a direct reply.
        _bare_prefixes = (
            "[joy",
            "[calm",
            "[curiosity",
            "[stress",
            "[sadness",
            "[anger",
            "[surprise",
            "[fatigue",
            "[BIOG] ",  # autobiography chapter — long-term, not dialogue-relevant
            "[STRAT] ",  # strategic planning — long-term, not dialogue-relevant
        )
        new_stream = [
            s
            for s in list(self.stream)[n_stream_before:]
            if s and not any(s.startswith(p) for p in _bare_prefixes)
        ]
        # Score and collect tagged items — body urgency and questions first,
        # meta-cognition last.  Higher score → shown before lower score.
        _tag_priority = {
            "[!] ": 5,  # body urgency — most pressing
            "[?] ": 4,  # question  (curiosity-driven)
            "[~] ": 4,  # hypothesis
            "[o] ": 3,  # observation
            "[<] ": 2,  # recall
            "[SELF] ": 1,
            "[META] ": 1,
        }
        _scored_parts: List[tuple] = []
        for s in new_stream:
            for prefix, score in _tag_priority.items():
                if s.startswith(prefix):
                    content = s[len(prefix) :].strip()
                    if len(content) > 10:
                        _scored_parts.append((score, content))
                    break
        _scored_parts.sort(key=lambda x: -x[0])
        tagged_parts = [c for _, c in _scored_parts]

        # ── 4b. Theory of Mind: adapt response style to addressee ──────────
        _tom_strategy = {}
        _sm_ref = getattr(brain, "_social_manager", None)
        _tom_pid = _sm_ref.primary_interlocutor() if _sm_ref else None
        if _tom_pid is not None:
            _tom_strategy = self.theory_of_mind.recommend_strategy(str(_tom_pid))
        # Combine with identity-based communication modifiers
        _id_style = self.identity_arc.communication_style_modifiers()

        # ── 5. Assemble response ───────────────────────────────────────────
        em = brain.emotion_state
        state = brain.consciousness_state

        def _token_overlap(a: str, b: str) -> float:
            """Fraction of tokens in `a` that also occur in `b` (simple dedup guard)."""
            ta = set(a.lower().split())
            tb = set(b.lower().split())
            return len(ta & tb) / max(len(ta), 1)

        # ── 5a. Conversational frame + reply agenda ───────────────────────
        _common_ground_ref = getattr(
            getattr(brain, "_dialogue_manager", None), "active_ground", None
        )

        # ── 5a-mem: Memory → speech act modulation ───────────────────────
        # Query episodic + social recall before binding the speech act so
        # past relationship dynamics actually shape the communicative choice.
        # Rich fields from recall_for_person() drive all branches:
        #   low trust (<0.25)             → HESITATE
        #   high conflict ratio (>0.4)    → REPAIR (de-escalation first)
        #   negative tone_bias + conflict → more cautious, possibly REPAIR
        #   positive tone_bias + trust    → warmer, more initiative (ASK)
        #   new person (n=0)              → GREET or simple ASSERT
        #   high familiarity + trust      → ASK or direct ASSERT
        _mem_rec: Optional[Dict] = None
        if planned_speech_act is None:
            _mem_sm = getattr(brain, "_social_manager", None)
            _mem_pid = _mem_sm.primary_interlocutor() if _mem_sm else None
            if _mem_pid is not None:
                try:
                    # Pass current topic tokens so recall is context-aware
                    _user_topic_toks = frozenset(
                        w.lower()
                        for w in user_text.split()
                        if len(w) >= 3
                    )
                    _mem_rec = self.recall_for_person(_mem_pid, brain, topic_tokens=_user_topic_toks)
                    _mem_trust = float(_mem_rec.get("trust", 0.5))
                    _mem_emo = _mem_rec.get("dominant_past_emotion", "")
                    _mem_n = int(_mem_rec.get("n_shared_episodes", 0))
                    _mem_fam = float(_mem_rec.get("familiarity", 0.0))
                    _mem_conflict_ratio = float(_mem_rec.get("conflict_ratio", 0.0))
                    _mem_tone_bias = _mem_rec.get("tone_bias", "neutral")
                    _mem_avg_valence = float(_mem_rec.get("avg_valence", 0.0))
                    from dialogue_manager import SpeechAct as _SA

                    # Priority order: safety first, then warmth
                    if _mem_trust < 0.25:
                        # Low trust → cautious, don't assert strongly
                        planned_speech_act = _SA.HESITATE
                    elif _mem_conflict_ratio > 0.4 and _mem_n > 2:
                        # High conflict history → try to de-escalate first
                        planned_speech_act = _SA.REPAIR
                    elif _mem_emo in ("anger", "fear", "disgust", "frustration",
                                      "wut", "angst") and _mem_n > 3:
                        # Past negative emotion pattern → careful
                        planned_speech_act = _SA.REPAIR
                    elif _mem_n == 0:
                        # First ever contact → neutral greeting stance
                        pass  # let normal planning handle GREET
                    elif _mem_trust > 0.7 and _mem_fam > 0.5 and _mem_n > 5:
                        # Well-known, trusted person → be more direct/inquisitive
                        planned_speech_act = _SA.ASK
                    elif _mem_tone_bias == "positive" and _mem_trust > 0.55 and _mem_n > 3:
                        # Positive shared history → show initiative
                        planned_speech_act = _SA.ASSERT
                except Exception:
                    pass  # recall failure → leave planned_speech_act as-is

        # ── 5a-social-obligations: Surface pending social commitments ─────
        # If there are social obligations towards the current interlocutor,
        # raise initiative to ASSERT so we follow up proactively rather than
        # just reacting to whatever the person says.
        if _mem_pid is not None and planned_speech_act is None:
            try:
                _pending_obs = self.long_horizon.social_obligations_for(_mem_pid)
                if _pending_obs:
                    from dialogue_manager import SpeechAct as _SA_ob
                    # Only raise to ASSERT — don't override safety-driven HESITATE
                    planned_speech_act = _SA_ob.ASSERT
            except Exception:
                pass

        # ── 5a-promise-detect: Record AI promises as social obligations ───
        # When the user makes a request (könntest du / can you / bitte) and
        # the reply will be an affirmative ASSERT, create a social obligation
        # so we remember to follow through.
        _promise_request_kw = (
            "könntest du", "kannst du", "bitte", "würdest du",
            "could you", "can you", "please", "would you",
        )
        if (
            _mem_pid is not None
            and any(kw in user_text.lower() for kw in _promise_request_kw)
        ):
            try:
                from dialogue_manager import SpeechAct as _SA_pr
                if planned_speech_act in (None, _SA_pr.ASSERT, _SA_pr.ASK):
                    _req_desc = f"Fulfill request for person {_mem_pid}: {user_text[:80]}"
                    self.long_horizon.record_social_obligation(
                        _mem_pid,
                        _req_desc,
                        brain.tick_count,
                        priority=7,
                    )
            except Exception:
                pass

        # ── 5a-mem-inject: Most relevant memory as context hint ───────────
        # Inject the single most relevant scored episode as a context part
        # so the response assembly pipeline (and LLM) know what past shared
        # experience is most salient right now.  Apply trust-tier hedging:
        # uncertain/reconstructed memories use hedged language.
        if _mem_rec is not None:
            _weighted_eps = _mem_rec.get("weighted_episodes", [])
            if _weighted_eps:
                _top_ep = _weighted_eps[0]
                _ep_tier = _top_ep.get("trust_tier", "plausible")
                _ep_text = _top_ep.get("text", "")
                _ep_score = float(_top_ep.get("score", 0.0))
                if _ep_text and _ep_score > 0.2:
                    _lk_mem = getattr(self.lang, "current", "de")
                    if _ep_tier == "certain":
                        _mem_prefix = "Erinnerung:" if _lk_mem == "de" else "Memory:"
                    elif _ep_tier == "plausible":
                        _mem_prefix = "Ich erinnere mich:" if _lk_mem == "de" else "I recall:"
                    else:
                        _mem_prefix = "Ich glaube mich zu erinnern:" if _lk_mem == "de" else "I think I recall:"
                    _add_part(f"({_mem_prefix} {_ep_text})", "recall")
            # Conflict warning for response assembly
            _rc_text = _mem_rec.get("recent_conflict_text", "")
            if _rc_text and float(_mem_rec.get("conflict_ratio", 0.0)) > 0.3:
                _lk_c = getattr(self.lang, "current", "de")
                _conf_hint = "Früher gab es Spannungen." if _lk_c == "de" else "There were tensions before."
                _add_part(f"(Hinweis: {_conf_hint})", "recall")

        # ── 5a-style: PersonModel interaction-style trajectory ────────────
        # Use accumulated relationship trajectory (trust, familiarity,
        # concise/verbose preferences, conflict rate) to derive a single
        # behavioral guidance dict that shapes length, caution, and initiative.
        # This block runs unconditionally — _mem_pid may be set earlier or we
        # fall back to the primary interlocutor here.
        _istyle: Dict = {}
        _istyle_pid = _mem_pid if "_mem_pid" in dir() else None
        if _istyle_pid is None:
            _istyle_sm2 = getattr(brain, "_social_manager", None)
            _istyle_pid = _istyle_sm2.primary_interlocutor() if _istyle_sm2 else None
        if _istyle_pid is not None:
            _istyle_sm = getattr(brain, "_social_manager", None)
            if _istyle_sm is not None:
                try:
                    _istyle = _istyle_sm.style_for_person(
                        _istyle_pid, self.theory_of_mind
                    )
                except Exception:
                    _istyle = {}

        # Caution from PersonModel → strengthen speech act selection
        # Only fires if no speech act was chosen by the memory-dominance block
        if _istyle.get("caution") == "high" and planned_speech_act is None:
            try:
                from dialogue_manager import SpeechAct as _SA_style
                planned_speech_act = _SA_style.HESITATE
            except Exception:
                pass

        _conv_frame = self._build_conversation_frame(
            user_text, planned_speech_act, _common_ground_ref, _tom_strategy
        )
        _reply_agenda = self._plan_reply_agenda(_conv_frame, brain)

        # ── 5a-style-length: PersonModel length target → agenda policy ────
        # Direct the assembler to produce short/medium/long content based on
        # the person's observed speech density preference.  Only override if
        # the preference is clear (length_target != "medium").
        _length_target = _istyle.get("length_target", "medium")
        if _length_target != "medium" and _reply_agenda is not None:
            _ap = getattr(_reply_agenda, "policy", None)
            if isinstance(_ap, dict):
                _current_tp = int(_ap.get("target_parts", 2))
                if _length_target == "short":
                    _ap["target_parts"] = max(1, min(_current_tp, 1))
                elif _length_target == "long":
                    _ap["target_parts"] = max(_current_tp, 3)

        response = self._assemble_grounded_reply(
            brain,
            user_text=user_text,
            outbox_msgs=outbox_msgs,
            new_concs=new_concs,
            tagged_parts=tagged_parts,
            common_ground=_common_ground_ref,
            speech_act=planned_speech_act,
            agenda=_reply_agenda,
        )

        # ── 5b. Theory of Mind style adaptation ──────────────────────────
        # Adjust response length/style based on ToM recommendation
        _tom_action = _tom_strategy.get("action", "engage")
        _tom_style = _tom_strategy.get("style", "balanced")
        _tom_trust = _tom_strategy.get("trust", 0.5)
        _tom_preferred = _tom_strategy.get("preferred_behaviour", "")
        _tom_avoided = _tom_strategy.get("avoided_behaviour", "")
        if _tom_action == "acknowledge_briefly" and len(response) > 120:
            # Addressee prefers brief — truncate to first two sentences
            _sents = response.split(". ")
            response = ". ".join(_sents[:2]).rstrip(".") + "."
        elif _tom_action == "provide_detail" and len(response) < 80:
            # Addressee wants detail — add context from belief store
            _active_concepts = list(self._concepts)[-3:]
            for _c in _active_concepts:
                _triples = self.belief_store.query(_c, min_confidence=0.3)
                if _triples:
                    _r, _o, _conf = _triples[0]
                    response += f"  ({_c} {_r} {_o}.)"
                    break

        # ── 5b-style: PersonModel-driven length guard ─────────────────────
        # Apply the person's observed speech density preference as a hard
        # post-processing guard so "concise" people don't receive walls of text.
        if _istyle.get("length_target") == "short" and len(response) > 180:
            # Hard cap: concise speaker → max 2 sentences
            _s2 = [s for s in response.replace("! ", ". ").replace("? ", ". ").split(". ") if s.strip()]
            response = ". ".join(_s2[:2]).rstrip(".,!?") + "."
        elif _istyle.get("length_target") == "long" and len(response) < 60:
            # Expansive speaker expects more — pull from recent beliefs
            _exp_concepts = list(self._concepts)[-2:]
            for _ec in _exp_concepts:
                _triples_exp = self.belief_store.query(_ec, min_confidence=0.3)
                if _triples_exp:
                    _r2, _o2, _ = _triples_exp[0]
                    response += f"  ({_ec}: {_r2} {_o2}.)"
                    break
        # Trust-modulated initiative: low trust → less assertive
        if isinstance(_tom_trust, (int, float)) and _tom_trust < 0.3:
            if response and response[-1] == "." and len(response) > 30:
                response = response  # no added initiative for low-trust addressees
        elif (
            isinstance(_tom_trust, (int, float))
            and _tom_trust > 0.7
            and len(response) < 100
        ):
            # High trust → can be more direct and offer suggestions
            if _tom_preferred and _tom_preferred not in response.lower():
                _active_concepts = list(self._concepts)[-3:]
                if _active_concepts:
                    response += f"  ({_tom_preferred[:40]}.)"

        # ── 6. State sidebar ───────────────────────────────────────────────
        _delib_cost = self._tick - _delib_start_tick
        sidebar: dict = {
            "emotion": em.dominant(),
            "valence": round(em.valence(), 2),
            "arousal": round(em.arousal(), 2),
            "goal": state.goal,
            "focus": state.focus_region or "—",
            "energy": round(self.body.energy_reserve, 2),
            "integrity": round(self.body.integrity, 2),
            "concepts": list(self._concepts)[-5:],
            "personality": self.personality.dominant_trait(),
            "strategy": self.strategic_meta.active_strategy,
            "drive": round(self.comm_drive.drive, 2),
            "deliberation_budget": _budget,
            "deliberation_cost": _delib_cost,
            "sensorimotor_agency": round(self.sensorimotor.agency, 2),
        }
        # ── 6b. Social learning feedback ──────────────────────────────────
        # Record the current emotional valence as an outcome signal for the
        # active interlocutor so that PersonModel.interaction_style() can
        # adapt initiative and clarity over subsequent encounters.
        # Also record topic success/failure based on this outcome.
        _sl_sm = getattr(brain, "_social_manager", None)
        _sl_pid = _istyle_pid if ("_istyle_pid" in dir() and _istyle_pid is not None) else (
            _sl_sm.primary_interlocutor() if _sl_sm else None
        )
        if _sl_sm is not None and _sl_pid is not None:
            try:
                _sl_pm = _sl_sm.person_model(_sl_pid)
                if _sl_pm is not None:
                    _sl_valence = float(em.valence())  # [-1,1] → EMA after scaling
                    _sl_pm.record_communication_outcome(_sl_valence, brain.tick_count)
                    # Update per-topic success if a topic was discussed
                    _sl_topic = getattr(_conv_frame, "topic", "") if "_conv_frame" in dir() else ""
                    if _sl_topic:
                        _sl_pm.record_topic_outcome(_sl_topic, success=_sl_valence > 0.0)
            except Exception:
                pass  # learning signals are non-critical — never block response

        return response, sidebar

    # ── Intent → agenda mapping (greet blocks recall, question allows it, etc.) ──
    _DIALOGUE_INTENT_MAP: ClassVar[Dict[str, Tuple[str, List[str], List[str]]]] = {
        "greet": ("contact", ["acknowledge"], ["recall", "inference", "hypothesis"]),
        "question": ("info_seek", ["answer"], []),
        "self_disclosure": ("rapport", ["acknowledge"], ["recall"]),
        "repair": ("coordination", ["clarify"], ["recall", "inference"]),
        "smalltalk": ("rapport", ["acknowledge", "relate"], ["recall"]),
        "topic_shift": ("coordination", ["acknowledge"], []),
        "request": ("coordination", ["answer", "propose"], []),
    }

    def _relationship_reply_policy(
        self, frame: "ConversationFrame", brain: "Brain"
    ) -> Dict[str, Any]:
        _sm_ref = getattr(brain, "_social_manager", None)
        _primary = _sm_ref.primary_interlocutor() if _sm_ref else None
        _profile = (
            _sm_ref.relationship_profile(_primary, self.theory_of_mind)
            if _sm_ref is not None and _primary is not None
            else {}
        )
        _relationship = str(
            _profile.get("relationship_type", "emergent_contact") or "emergent_contact"
        )
        policy: Dict[str, Any] = {
            "relationship_type": _relationship,
            "target_parts": 2,
            "ack_style": "warm",
            "answer_style": "assertive",
            "clarify_style": "neutral",
            "repair_gap": "reference" if frame.intent == "repair" else "intent",
            "max_support_moves": 2,
            "extra_support": [],
        }
        if _relationship == "mistrustful_questioner":
            policy.update(
                {
                    "target_parts": 1,
                    "ack_style": "brief",
                    "answer_style": "careful",
                    "clarify_style": "careful",
                    "repair_gap": "reference",
                    "max_support_moves": 1,
                    "extra_support": ["clarify"] if frame.intent == "question" else [],
                }
            )
        elif _relationship == "guarded_interlocutor":
            policy.update(
                {
                    "target_parts": 1,
                    "ack_style": "brief",
                    "answer_style": "careful",
                    "clarify_style": "careful",
                    "repair_gap": "reference",
                    "max_support_moves": 1,
                }
            )
        elif _relationship == "curious_questioner":
            policy.update(
                {
                    "target_parts": 3,
                    "ack_style": "warm",
                    "answer_style": "explanatory",
                    "clarify_style": "neutral",
                    "repair_gap": "scope",
                    "max_support_moves": 2,
                    "extra_support": ["relate", "ask_back"],
                }
            )
        elif _relationship in (
            "familiar_cooperative_speaker",
            "trusted_cooperative_partner",
        ):
            policy.update(
                {
                    "target_parts": 3,
                    "ack_style": "warm",
                    "answer_style": "assertive",
                    "clarify_style": "direct",
                    "repair_gap": "intent",
                    "max_support_moves": 2,
                    "extra_support": ["ask_back"],
                }
            )
        return policy

    def _build_conversation_frame(
        self,
        user_text: str,
        planned_speech_act: "Optional[Any]",
        common_ground: "Optional[Any]",
        tom_strategy: dict,
    ) -> "ConversationFrame":
        """Analyse user_text and return a ConversationFrame for the current turn."""
        lang = getattr(self.lang, "current", "de")
        t = user_text.lower().strip()
        words_set = set(re.findall(r"[a-zA-ZäöüÄÖÜß]{3,}", t))
        q_type, q_focus = self.query_engine.parse(user_text)

        # ── Intent detection ──────────────────────────────────────────────
        _greet_w = frozenset(
            {"hallo", "hi", "hey", "moin", "servus", "nabend", "hello", "howdy"}
        )
        _repair_c = (
            "was meinst",
            "ich verstehe nicht",
            "was bedeutet das",
            "could you repeat",
            "what do you mean",
        )
        _self_disc = (
            "ich bin",
            "ich fühle",
            "mir geht",
            "ich hatte",
            "i am",
            "i feel",
            "i'm",
            "i had",
        )

        if words_set & _greet_w:
            intent = "greet"
        elif any(c in t for c in _repair_c):
            intent = "repair"
        elif any(c in t for c in _self_disc):
            intent = "self_disclosure"
        elif "?" in user_text or q_type != "open":
            intent = "question"
        elif getattr(planned_speech_act, "value", "") in ("request", "inform"):
            intent = "request"
        else:
            intent = "smalltalk"

        # ── Topic: first meaningful content word ──────────────────────────
        _fstop = frozenset(
            {
                "ich",
                "du",
                "das",
                "ist",
                "ein",
                "eine",
                "und",
                "oder",
                "aber",
                "weil",
                "the",
                "was",
                "wie",
                "wer",
                "warum",
                "what",
                "how",
                "who",
                "why",
                "you",
                "are",
                "have",
                "this",
                "that",
                "she",
                "they",
            }
        )
        topic_words = [
            w for w in re.findall(r"[a-zA-ZäöüÄÖÜß]{3,}", t) if w not in _fstop
        ]
        topic = q_focus[0] if q_focus else (topic_words[0] if topic_words else "")

        # ── Polarity ──────────────────────────────────────────────────────
        _pos = frozenset(
            {
                "gut",
                "schön",
                "toll",
                "super",
                "prima",
                "freude",
                "good",
                "great",
                "wonderful",
                "happy",
                "love",
                "beautiful",
            }
        )
        _neg = frozenset(
            {
                "schlecht",
                "traurig",
                "schwer",
                "schwierig",
                "problem",
                "schmerz",
                "angst",
                "bad",
                "sad",
                "hard",
                "difficult",
                "pain",
                "fear",
                "worry",
                "wrong",
            }
        )
        polarity = (
            "positive"
            if words_set & _pos
            else "negative" if words_set & _neg else "neutral"
        )

        # ── User emotional state cue ──────────────────────────────────────
        _emo_map = {
            "traurig": "traurig",
            "sad": "sad",
            "froh": "froh",
            "glücklich": "glücklich",
            "happy": "happy",
            "wütend": "wütend",
            "angry": "angry",
            "ängstlich": "ängstlich",
            "anxious": "anxious",
            "müde": "müde",
            "tired": "tired",
            "einsam": "einsam",
            "lonely": "lonely",
            "aufgeregt": "aufgeregt",
            "excited": "excited",
        }
        user_state_cue = next((cue for kw, cue in _emo_map.items() if kw in t), "")

        social_goal, required_moves, _ = self._DIALOGUE_INTENT_MAP.get(
            intent, ("contact", ["acknowledge"], [])
        )

        return ConversationFrame(
            intent=intent,
            topic=topic,
            utterance=user_text.strip(),
            focus_terms=q_focus[:6],
            question_type=q_type,
            polarity=polarity,
            user_state_cue=user_state_cue,
            social_goal=social_goal,
            required_moves=list(required_moves),
            lang=lang,
        )

    def _answer_from_internal_state(
        self,
        frame: "ConversationFrame",
        brain: "Brain",
    ) -> Tuple[str, float]:
        """Answer self-/system-related questions from live internal state."""
        utterance = (frame.utterance or "").lower()
        lang = frame.lang
        state = getattr(brain, "consciousness_state", None)

        def _has_any(cues: Tuple[str, ...]) -> bool:
            return any(cue in utterance for cue in cues)

        if _has_any(
            (
                "wie geht es dir",
                "how are you",
                "wie fuehl",
                "wie fühl",
                "what do you feel",
                "zustand",
                "state",
            )
        ):
            parts: List[str] = []
            dom = brain.emotion_state.dominant()
            if lang == "de":
                parts.append(f"mein dominanter Zustand ist {dom}")
            else:
                parts.append(f"my dominant state is {dom}")
            parts.append(self.body.describe())
            if getattr(self, "task_frame", None) is not None:
                parts.append(self.task_frame.describe())
            return "  ".join(parts[:2]), 0.62

        if _has_any(
            (
                "woran erinner",
                "was erinner",
                "remember",
                "memory",
                "gedaechtnis",
                "gedächtnis",
            )
        ):
            recent = self.episodic.recent(3)
            if recent:
                snippets = "; ".join(
                    f"{ev.kind}:{ev.content[:60]}" for ev in recent if ev.content
                )
                if snippets:
                    if lang == "de":
                        return (
                            f"Zuletzt ist in meinem episodischen Gedächtnis aktiv: {snippets}.",
                            0.48,
                        )
                    return (
                        f"The most active items in my episodic memory are: {snippets}.",
                        0.48,
                    )
            if lang == "de":
                return (
                    "In meinem episodischen Gedächtnis ist dazu gerade wenig aktiv.",
                    0.32,
                )
            return (
                "There is little active material for that in my episodic memory right now.",
                0.32,
            )

        if _has_any(
            ("was kannst du", "kannst du", "can you", "capability", "faehig", "fähig")
        ):
            strong = self.capability_model.strongest(3)
            weak = self.capability_model.weakest(2)
            if lang == "de":
                strong_txt = (
                    ", ".join(f"{name} ({conf:.0%})" for name, conf in strong)
                    or "noch keine belastbaren Stärken"
                )
                weak_txt = (
                    ", ".join(f"{name} ({conf:.0%})" for name, conf in weak)
                    or "keine klaren Schwächen"
                )
                return (
                    f"Mein aktuelles Fähigkeitsmodell sieht so aus: stark bei {strong_txt}; unsicher bei {weak_txt}.",
                    0.52,
                )
            strong_txt = (
                ", ".join(f"{name} ({conf:.0%})" for name, conf in strong)
                or "no reliable strengths yet"
            )
            weak_txt = (
                ", ".join(f"{name} ({conf:.0%})" for name, conf in weak)
                or "no clear weak spots"
            )
            return (
                f"My current capability model looks like this: strong in {strong_txt}; uncertain in {weak_txt}.",
                0.52,
            )

        if _has_any(
            (
                "warum",
                "weshalb",
                "wieso",
                "why did",
                "why do",
                "warum hast",
                "warum machst",
                "begründ",
            )
        ):
            _dr = self._last_decision_reason
            if _dr:
                if lang == "de":
                    return (
                        f"Meine letzte Entscheidung: Ziel '{_dr['goal']}' |"
                        f" kausal (Konfidenz: {_dr['causal_conf']:.2f}) |"
                        f" Antrieb: {_dr['dominant_drive']} ({_dr['drive_val']:.2f}) |"
                        f" Emotion: {_dr['em_dominant']} |"
                        f" Normverstos: {_dr['norm_penalty']:.2f} |"
                        f" Erleben: {_dr['phenom_sig']}"
                    ), 0.72
                return (
                    f"My last decision: goal '{_dr['goal']}' |"
                    f" causal conf={_dr['causal_conf']:.2f} |"
                    f" drive: {_dr['dominant_drive']}={_dr['drive_val']:.2f} |"
                    f" emotion: {_dr['em_dominant']} |"
                    f" norm penalty={_dr['norm_penalty']:.2f} |"
                    f" phenomenology: {_dr['phenom_sig']}"
                ), 0.72
            if lang == "de":
                return "Ich habe noch keine Entscheidung protokolliert.", 0.3
            return "No decision has been recorded yet.", 0.3

        if _has_any(
            (
                "widersprichst du dir",
                "wo irrst du dich",
                "irrst du dich",
                "selbstwiderspruch",
                "contradict yourself",
                "where are you wrong",
                "self contradiction",
            )
        ):
            return self.self_model.contradiction_summary(lang, self._tick), 0.68

        _self_thesis_query = _has_any(
            (
                "was glaubst du über dich",
                "welche selbstthese",
                "welche selbstthesen",
                "unter sozialem druck",
                "bei hoher müdigkeit",
                "über dich bei",
                "what do you believe about yourself",
                "which self-thesis",
                "under social pressure",
                "under fatigue",
                "about yourself when",
            )
        )
        if _self_thesis_query:
            _query_conditions = self.self_model.query_condition_classes(utterance)
            _query_social_ctx = None
            if any(
                tok in utterance
                for tok in (
                    "gegenüber mir",
                    "bei mir",
                    "mit mir",
                    "toward me",
                    "with me",
                    "to me",
                )
            ):
                _query_social_ctx = self._current_self_social_context(
                    getattr(self, "_brain_ref", None)
                )
            elif _query_conditions and "under_social_pressure" in _query_conditions:
                _query_social_ctx = self._current_self_social_context(
                    getattr(self, "_brain_ref", None)
                )
            return (
                self.self_model.self_thesis_summary(
                    lang,
                    self._tick,
                    condition_classes=_query_conditions or None,
                    social_context=_query_social_ctx,
                ),
                0.72,
            )

        if _has_any(
            (
                "was hat dir das gezeigt",
                "was sagt das über dich",
                "what did that show about you",
                "what does that say about you",
            )
        ):
            _report = self.self_model.last_action_self_report
            if _report:
                return _report, 0.66
            if lang == "de":
                return (
                    "Ich habe dazu noch keinen aktionsgebundenen Selbstbericht protokolliert.",
                    0.32,
                )
            return "I have not logged an action-bound self-report for that yet.", 0.32

        _self_conscious_query = _has_any(
            (
                "bist du dir bewusst",
                "eigenes bewusstsein",
                "selbstbewusstsein",
                "hast du ein ich",
                "hast du ein selbst",
                "bewusst von dir",
                "self-conscious",
                "conscious of yourself",
                "do you have a self",
                "do you have consciousness",
                "are you conscious",
            )
        )
        if not _self_conscious_query:
            _self_conscious_query = (
                ("bewusst" in utterance or "bewusstsein" in utterance)
                and any(
                    tok in utterance for tok in (" du", "dir", "dein", "selbst", "ich")
                )
            ) or (
                ("conscious" in utterance or "consciousness" in utterance)
                and any(
                    tok in utterance for tok in (" you", "your", "self", "yourself")
                )
            )
        if _self_conscious_query:
            _goal = getattr(state, "goal", "") if state is not None else ""
            return self.self_model.self_consciousness_summary(lang, _goal), 0.78

        if _has_any(
            (
                "wer bist du",
                "who are you",
                "dein ziel",
                "your goal",
                "woran arbeit",
                "working on",
                "was tust du",
                "what are you doing",
            )
        ):
            parts: List[str] = []
            _goal = getattr(state, "goal", "") if state is not None else ""
            if state is not None and getattr(state, "goal", ""):
                if lang == "de":
                    parts.append(f"mein aktuelles Ziel ist {state.goal}")
                else:
                    parts.append(f"my current goal is {state.goal}")
            parts.append(self.self_model.self_consciousness_summary(lang, _goal))
            return "  ".join(parts[:2]), 0.45

        related: List[str] = []
        for term in frame.focus_terms[:2]:
            for nbr, _weight in self.concept_graph.neighbors(term, top_n=4):
                if nbr not in related and nbr not in frame.focus_terms:
                    related.append(nbr)
        if frame.focus_terms and related:
            head = frame.focus_terms[0]
            if lang == "de":
                return (
                    f"Zu {head} sind in meinem aktuellen Kontext vor allem "
                    f"{', '.join(related[:4])} verknüpft."
                ), 0.34
            return (
                f"Around {head}, my current context links mostly to "
                f"{', '.join(related[:4])}."
            ), 0.34

        if frame.focus_terms:
            head = frame.focus_terms[0]
            if lang == "de":
                return (
                    f"Zu {head} habe ich im Moment noch wenig belastbares Wissen, aber die Frage ist aktiv im Fokus.",
                    0.22,
                )
            return (
                f"I do not yet have much reliable knowledge about {head}, but the question is active in focus.",
                0.22,
            )

        if lang == "de":
            return (
                "Ich kann die Frage noch nicht belastbar auflösen, aber ich kann sie weiter einordnen, wenn du den Bezug präzisierst.",
                0.18,
            )
        return (
            "I cannot resolve that reliably yet, but I can narrow it down if you specify the reference.",
            0.18,
        )

    def _is_internal_state_query(self, frame: "ConversationFrame") -> bool:
        utterance = (frame.utterance or "").lower()
        internal_cues = (
            "wie geht es dir",
            "how are you",
            "wie fuehl",
            "wie fühl",
            "what do you feel",
            "zustand",
            "state",
            "woran erinner",
            "was erinner",
            "remember",
            "memory",
            "gedaechtnis",
            "gedächtnis",
            "was kannst du",
            "kannst du",
            "can you",
            "capability",
            "faehig",
            "fähig",
            "warum hast",
            "warum machst",
            "why did",
            "why do",
            "begründ",
            "widersprichst du dir",
            "wo irrst du dich",
            "irrst du dich",
            "self contradiction",
            "was glaubst du über dich",
            "welche selbstthese",
            "unter sozialem druck",
            "what do you believe about yourself",
            "which self-thesis",
            "under social pressure",
            "was hat dir das gezeigt",
            "was sagt das über dich",
            "what did that show about you",
            "what does that say about you",
            "bist du dir bewusst",
            "eigenes bewusstsein",
            "selbstbewusstsein",
            "hast du ein ich",
            "hast du ein selbst",
            "bewusst von dir",
            "self-conscious",
            "conscious of yourself",
            "do you have a self",
            "do you have consciousness",
            "are you conscious",
            "wer bist du",
            "who are you",
            "dein ziel",
            "your goal",
            "woran arbeit",
            "working on",
            "was tust du",
            "what are you doing",
        )
        if any(cue in utterance for cue in internal_cues):
            return True
        return (
            ("bewusst" in utterance or "bewusstsein" in utterance)
            and any(tok in utterance for tok in (" du", "dir", "dein", "selbst", "ich"))
        ) or (
            ("conscious" in utterance or "consciousness" in utterance)
            and any(tok in utterance for tok in (" you", "your", "self", "yourself"))
        )

    def _answer_from_external_context(
        self,
        frame: "ConversationFrame",
        brain: "Brain",
    ) -> Tuple[str, float]:
        """Answer from recent web/workspace context when direct knowledge is sparse."""
        lang = frame.lang
        utterance = str(frame.utterance or "").strip().lower()
        focus_terms = [t.lower() for t in frame.focus_terms if t]
        if not focus_terms and frame.topic:
            focus_terms = [frame.topic.lower()]

        def _dedupe(items: List[str]) -> List[str]:
            seen: set = set()
            out: List[str] = []
            for item in items:
                token = str(item or "").strip().lower()
                if token and token not in seen:
                    seen.add(token)
                    out.append(token)
            return out

        def _query_tokens(text: str) -> List[str]:
            toks = re.findall(r"[a-zA-ZäöüÄÖÜß0-9_:-]{2,}", text.lower())
            return [
                tok
                for tok in toks
                if tok not in self.query_engine._QSTOP and tok not in _CONCEPT_STOPWORDS
            ]

        query_terms = _dedupe(focus_terms + _query_tokens(utterance))
        query_term_set = set(query_terms)
        related_terms: List[str] = []
        for term in query_terms[:3]:
            for neighbor, weight in self.concept_graph.neighbors(term, top_n=5):
                if weight < 0.08:
                    continue
                neighbor_l = str(neighbor or "").strip().lower()
                if (
                    neighbor_l
                    and neighbor_l not in query_term_set
                    and neighbor_l not in related_terms
                ):
                    related_terms.append(neighbor_l)
        related_term_set = set(related_terms)

        quoted_phrases = _dedupe(
            [
                match.strip().lower()
                for match in re.findall(r'"([^"]{2,})"', frame.utterance or "")
            ]
        )
        salient_phrases = quoted_phrases[:]
        if len(query_terms) >= 2:
            salient_phrases.append(" ".join(query_terms[:2]))

        def _char_ngrams(text: str, n: int = 3) -> set:
            compact = re.sub(r"\s+", " ", text.lower()).strip()
            if len(compact) < n:
                return {compact} if compact else set()
            return {compact[i : i + n] for i in range(len(compact) - n + 1)}

        query_grams = _char_ngrams(utterance or " ".join(query_terms))

        def _semantic_score(text: str, extra_text: str = "") -> float:
            combined = (
                " ".join(part for part in (text, extra_text) if part).strip().lower()
            )
            if not combined:
                return 0.0
            tokens = set(_query_tokens(combined))
            direct_hits = sum(1 for term in query_terms if term in combined)
            related_hits = sum(1 for term in related_terms if term in combined)
            phrase_hits = sum(
                1 for phrase in salient_phrases if phrase and phrase in combined
            )
            token_overlap = (
                len(tokens & query_term_set) / max(len(query_term_set), 1)
                if query_term_set
                else 0.0
            )
            related_overlap = (
                len(tokens & related_term_set) / max(len(related_term_set), 1)
                if related_term_set
                else 0.0
            )
            grams = _char_ngrams(combined)
            gram_overlap = (
                len(query_grams & grams) / max(len(query_grams), 1)
                if query_grams and grams
                else 0.0
            )
            score = (
                token_overlap * 0.46
                + related_overlap * 0.22
                + gram_overlap * 0.14
                + min(direct_hits, 4) * 0.06
                + min(related_hits, 3) * 0.04
                + min(phrase_hits, 2) * 0.08
            )
            return min(1.0, score)

        # 1) Recent web context
        if getattr(brain, "_use_web", False):
            web_enc = getattr(brain, "_web_enc", None)
            last_items = list(getattr(web_enc, "last_items", []) or [])
            best_item: Optional[Dict[str, Any]] = None
            best_score = 0.0
            recent_items = last_items[-12:]
            for idx, item in enumerate(recent_items):
                title = str(item.get("title", "") or "")
                text = str(item.get("text", "") or "")
                title_score = _semantic_score(title)
                text_score = _semantic_score(text, title)
                recency = (idx + 1) / max(len(recent_items), 1)
                score = title_score * 0.5 + text_score * 0.42 + recency * 0.08
                if score > best_score:
                    best_item = item
                    best_score = score
            if best_item is not None and best_score >= 0.18:
                title = str(best_item.get("title", "") or "").strip()
                excerpt = str(best_item.get("text", "") or "").strip()
                excerpt = re.split(r"(?<=[.!?])\s+", excerpt)[0][:180].strip()
                if lang == "de":
                    parts = [
                        (
                            f"im letzten Webkontext zu {focus_terms[0]} fällt mir besonders {title[:120]} auf"
                            if title
                            else "im letzten Webkontext gibt es dazu einen relevanten Treffer"
                        ),
                    ]
                    if excerpt and excerpt.lower() != title.lower():
                        parts.append(excerpt)
                    return "  ".join(parts), min(0.66, 0.34 + best_score * 0.36)
                parts = [
                    (
                        f"in the latest web context around {focus_terms[0]}, the most relevant item is {title[:120]}"
                        if title
                        else "there is a relevant recent web item for that"
                    ),
                ]
                if excerpt and excerpt.lower() != title.lower():
                    parts.append(excerpt)
                return "  ".join(parts), min(0.66, 0.34 + best_score * 0.36)

        # 2) Current workspace conclusions
        best_conclusion = ""
        best_conclusion_score = 0.0
        for conclusion in reversed(list(self._conclusions)[-8:]):
            score = _semantic_score(conclusion)
            if score > best_conclusion_score:
                best_conclusion = conclusion
                best_conclusion_score = score
        if best_conclusion and best_conclusion_score >= 0.16:
            if lang == "de":
                return (
                    f"in meinem aktuellen Arbeitskontext ist dazu besonders diese Schlussfolgerung aktiv: {best_conclusion[:220]}",
                    min(0.55, 0.34 + best_conclusion_score * 0.25),
                )
            return (
                f"in my current workspace context, this conclusion is most active for that: {best_conclusion[:220]}",
                min(0.55, 0.34 + best_conclusion_score * 0.25),
            )

        # 3) Current workspace concepts
        ranked_workspace_hits = sorted(
            ((c, _semantic_score(c)) for c in self.workspace_concepts()),
            key=lambda item: item[1],
            reverse=True,
        )
        workspace_hits = [
            concept for concept, score in ranked_workspace_hits if score >= 0.14
        ][:5]
        if workspace_hits:
            joined = ", ".join(workspace_hits[:5])
            head = focus_terms[0] if focus_terms else frame.topic or "das"
            if lang == "de":
                return (
                    f"im aktuellen Workspace sind zu {head} vor allem {joined} aktiv",
                    0.31,
                )
            return (
                f"in the current workspace, the strongest active concepts around {head} are {joined}",
                0.31,
            )

        return "", 0.0

    def _plan_reply_agenda(
        self,
        frame: "ConversationFrame",
        brain: "Brain",
    ) -> "ReplyAgenda":
        """Build a ReplyAgenda from a ConversationFrame."""
        _, required_moves, blocked_sources = self._DIALOGUE_INTENT_MAP.get(
            frame.intent, ("contact", ["acknowledge"], [])
        )
        policy = self._relationship_reply_policy(frame, brain)
        primary_kind = required_moves[0] if required_moves else "acknowledge"
        support_kinds = list(required_moves[1:])
        for extra in policy.get("extra_support", []):
            if extra not in support_kinds and extra != primary_kind:
                support_kinds.append(extra)

        # ── Realise primary move ──────────────────────────────────────────
        if primary_kind == "acknowledge":
            primary = ReplyMove(
                kind="acknowledge",
                payload=self.lang.realise_acknowledgement(
                    frame, style=str(policy.get("ack_style", "warm"))
                ),
                confidence=1.0,
                source="obligation",
            )

        elif primary_kind == "answer":
            em = brain.emotion_state
            _hipp = getattr(brain, "hippocampus", None)
            qe_ans = ""
            qe_conf = 0.0
            _query_text = frame.utterance or frame.topic
            _prefer_internal = self._is_internal_state_query(frame)
            if _prefer_internal:
                qe_ans, qe_conf = self._answer_from_internal_state(frame, brain)
                policy["target_parts"] = 1
            elif _query_text:
                qe_ans = self.query_engine.answer(
                    _query_text,
                    self.belief_store,
                    self.concept_graph,
                    self.world_model,
                    _hipp,
                    self.meta,
                    self.lang,
                    em,
                    grounded_memory=self.grounded_memory,
                )
                qe_conf = 0.8 if qe_ans else 0.0
            if not qe_ans and not _prefer_internal:
                qe_ans, qe_conf = self._answer_from_external_context(frame, brain)
            if not qe_ans:
                qe_ans, qe_conf = self._answer_from_internal_state(frame, brain)
            if qe_ans:
                primary = ReplyMove(
                    kind="answer",
                    payload=self.lang.realise_answer(
                        qe_ans,
                        qe_conf,
                        style=str(policy.get("answer_style", "assertive")),
                    ),
                    confidence=qe_conf,
                    source="belief",
                )
            else:
                _subject = frame.topic or (
                    frame.focus_terms[0] if frame.focus_terms else ""
                )
                triples = (
                    self.belief_store.query(_subject, min_confidence=0.3)
                    if _subject
                    else []
                )
                if triples:
                    rel_t, obj_t, conf_t = triples[0]
                    prop = self.lang.assertion(_subject, rel_t, obj_t)
                    primary = ReplyMove(
                        kind="answer",
                        payload=self.lang.realise_answer(
                            prop,
                            float(conf_t),
                            style=str(policy.get("answer_style", "assertive")),
                        ),
                        confidence=float(conf_t),
                        source="belief",
                    )
                else:
                    # No answer found — agenda primary left empty; tiers will fill
                    primary = ReplyMove(
                        kind="answer", payload="", confidence=0.0, source="belief"
                    )

        elif primary_kind == "clarify":
            gap = str(
                policy.get(
                    "repair_gap", "reference" if frame.intent == "repair" else "intent"
                )
            )
            primary = ReplyMove(
                kind="clarify",
                payload=self.lang.realise_clarification(
                    frame.topic or "das",
                    gap,
                    style=str(policy.get("clarify_style", "neutral")),
                ),
                confidence=1.0,
                source="obligation",
            )

        else:
            primary = ReplyMove(
                kind="acknowledge",
                payload=self.lang.realise_acknowledgement(frame),
                confidence=1.0,
                source="obligation",
            )

        # ── Realise support moves (max 2) ─────────────────────────────────
        support: List[ReplyMove] = []
        for sk in support_kinds[: int(policy.get("max_support_moves", 2))]:
            if sk == "relate" and frame.topic and "recall" not in blocked_sources:
                triples = self.belief_store.query(frame.topic, min_confidence=0.25)
                if triples:
                    rel2, obj2, conf2 = triples[0]
                    support.append(
                        ReplyMove(
                            kind="relate",
                            payload=self.lang.assertion(frame.topic, rel2, obj2),
                            confidence=float(conf2),
                            source="belief",
                        )
                    )
            elif sk == "clarify":
                support.append(
                    ReplyMove(
                        kind="clarify",
                        payload=self.lang.realise_clarification(
                            frame.topic or "das",
                            str(policy.get("repair_gap", "scope")),
                            style=str(policy.get("clarify_style", "neutral")),
                        ),
                        confidence=0.85,
                        source="obligation",
                    )
                )
            elif sk in ("ask_back", "propose"):
                support.append(
                    ReplyMove(
                        kind=sk,
                        payload=self.lang.realise_reciprocal_question(frame),
                        confidence=0.9,
                        source="obligation",
                    )
                )

        return ReplyAgenda(
            primary_move=primary,
            support_moves=support,
            blocked_sources=list(blocked_sources),
            policy=policy,
        )

    def _assemble_grounded_reply(
        self,
        brain: "Brain",
        *,
        user_text: str,
        outbox_msgs: List[str],
        new_concs: List[str],
        tagged_parts: List[str],
        common_ground: "Optional[Any]" = None,
        speech_act: "Optional[Any]" = None,
        agenda: "Optional[Any]" = None,
    ) -> str:
        em = brain.emotion_state
        state = brain.consciousness_state

        def _token_overlap(a: str, b: str) -> float:
            ta = set(a.lower().split())
            tb = set(b.lower().split())
            return len(ta & tb) / max(len(ta), 1)

        user_tokens = {tok for tok in user_text.lower().split() if len(tok) > 2}

        def _score_text(text: str) -> float:
            if not text:
                return 0.0
            toks = {tok for tok in text.lower().split() if len(tok) > 2}
            overlap = len(user_tokens & toks)
            return overlap + min(len(text) / 120.0, 1.0)

        def _relevance(text: str) -> float:
            if not user_tokens:
                return 1.0
            toks = {tok for tok in text.lower().split() if len(tok) > 2}
            return len(user_tokens & toks) / max(len(user_tokens), 1)

        parts: List[str] = []
        # Epistemic evidence tracking: (text, evidence_level)
        # Levels: "observation", "inference", "recall", "hearsay", "hypothesis"
        _evidence_labels: List[Tuple[str, str]] = []
        # Pre-initialise Common Ground confirmed tokens for dedup closure
        _cg_confirmed_tokens: set = set()
        _cg = common_ground
        if _cg is not None:
            for _cf in getattr(_cg, "confirmed_facts", []):
                _cg_confirmed_tokens.update(
                    tok.lower() for tok in _cf.split() if len(tok) > 3
                )

        def _add_part(text: str, evidence: str = "inference") -> None:
            """Add a response component with its epistemic evidence level.

            Suppresses parts that merely restate confirmed common-ground facts.
            """
            # Common Ground dedup: skip if >60% of tokens are already confirmed
            if _cg_confirmed_tokens and evidence not in ("observation", "recall"):
                _part_toks = {t.lower() for t in text.split() if len(t) > 3}
                if (
                    _part_toks
                    and len(_part_toks & _cg_confirmed_tokens) / len(_part_toks) > 0.6
                ):
                    return  # suppress — both parties already know this
            parts.append(text)
            _evidence_labels.append((text, evidence))

        # ── Agenda: inject primary communicative obligation first ─────────
        _agenda_blocked: List[str] = (
            list(getattr(agenda, "blocked_sources", [])) if agenda is not None else []
        )
        _agenda_policy: Dict[str, Any] = (
            dict(getattr(agenda, "policy", {})) if agenda is not None else {}
        )
        _target_parts = max(1, int(_agenda_policy.get("target_parts", 2)))
        if agenda is not None:
            _pm = getattr(agenda, "primary_move", None)
            if _pm and getattr(_pm, "payload", ""):
                _add_part(_pm.payload, "observation")
            for _sm in getattr(agenda, "support_moves", []):
                if getattr(_sm, "payload", ""):
                    _add_part(_sm.payload, "observation")

        # ── Tier -3: Speech Act steering ───────────────────────────────────
        # Use the planned speech act to shape the response at the structural
        # level — decide what KIND of reply to produce before content tiers.
        _sa_name = (
            getattr(speech_act, "value", None) if speech_act is not None else None
        )
        _sa_silence = _sa_name == "silence"
        _sa_repair = _sa_name == "repair"
        _sa_greet = _sa_name == "greet"
        _sa_ask = _sa_name == "ask"
        _sa_observe = _sa_name == "observe"

        if _sa_silence:
            # Planner decided: say nothing (low comm drive, no content)
            return ""

        if _sa_repair:
            # Planner decided: we didn't understand — request clarification.
            # Phrase escalates with repair_count so the AI doesn't keep repeating
            # the same generic "say it again" when clarification keeps failing.
            _lang_key = getattr(self.lang, "current", "de")
            _rep_sm = getattr(brain, "_social_manager", None)
            _rep_pid = _rep_sm.primary_interlocutor() if _rep_sm else None
            _rep_pm = _rep_sm.person_model(_rep_pid) if (_rep_sm and _rep_pid is not None) else None
            _rep_count = _rep_pm.repair_count if _rep_pm is not None else 0
            # Record the repair event on the PersonModel
            if _rep_pm is not None:
                _rep_pm.record_repair_event(getattr(brain, "tick_count", 0))
            # Select phrase based on cumulative repair count
            if _lang_key == "de":
                if _rep_count >= 5:
                    _rep_phrase = "Ich verstehe dich leider oft nicht. Bitte formuliere es so einfach wie möglich."
                elif _rep_count >= 3:
                    _rep_phrase = "Ich habe dich nicht verstanden. Kannst du es anders oder einfacher ausdrücken?"
                else:
                    _rep_phrase = "Kannst du das nochmal sagen?"
            else:
                if _rep_count >= 5:
                    _rep_phrase = "I often have trouble understanding you. Could you please put it as simply as possible?"
                elif _rep_count >= 3:
                    _rep_phrase = "I didn't understand. Could you rephrase it more simply?"
                else:
                    _rep_phrase = "Could you repeat that?"
            return _rep_phrase

        if _sa_greet:
            # Greeting text varies by familiarity and encounter history
            # to treat known persons differently from strangers.
            _lang_key = getattr(self.lang, "current", "de")
            _greet_sm = getattr(brain, "_social_manager", None)
            _greet_pid = _greet_sm.primary_interlocutor() if _greet_sm else None
            _greet_n = 0
            _greet_fam = 0.0
            _greet_trust = 0.5
            if _greet_pid is not None and _greet_sm is not None:
                _greet_pm = _greet_sm.person_model(_greet_pid)
                if _greet_pm is not None:
                    _greet_n = _greet_pm.total_encounters
                    _greet_fam = _greet_pm.familiarity
                    _greet_trust = _greet_pm.trust
            # Tier 1 — already met, familiar: warm personal greeting
            if _greet_fam > 0.45 and _greet_n > 2:
                _greet_text = (
                    "Schön, dich wiederzusehen!" if _lang_key == "de"
                    else "Good to see you again!"
                )
            # Tier 2 — met before but not close yet: friendly, not overfamiliar
            elif _greet_n > 0:
                _greet_text = (
                    "Hallo, schön dass du da bist." if _lang_key == "de"
                    else "Hello, glad you're here."
                )
            # Tier 3 — first meeting
            else:
                _greet_text = (
                    "Hallo! Schön dich kennenzulernen." if _lang_key == "de"
                    else "Hello! Nice to meet you."
                )
            _add_part(_greet_text, "observation")

        # HESITATE — optionally add a caution preamble when there is conflict history
        _sa_hesitate = _sa_name == "hesitate"
        if _sa_hesitate:
            _lang_key = getattr(self.lang, "current", "de")
            _hesitate_sm = getattr(brain, "_social_manager", None)
            _hesitate_pid = _hesitate_sm.primary_interlocutor() if _hesitate_sm else None
            _hesitate_conflict = 0.0
            if _hesitate_pid is not None and _hesitate_sm is not None:
                _hesitate_pm = _hesitate_sm.person_model(_hesitate_pid)
                if _hesitate_pm is not None:
                    _he_n = max(_hesitate_pm.total_encounters, 1)
                    _hesitate_conflict = _hesitate_pm.conflict_encounter_count / _he_n
            if _hesitate_conflict > 0.35:
                # Known conflict history → explicit caution signal
                _caut_text = (
                    "Ich bin gerade unsicher, wie ich das am besten anspreche."
                    if _lang_key == "de"
                    else "I'm not sure how to best address this right now."
                )
                _add_part(_caut_text, "observation")

        # ── Tier -4: Generative LLM (highest-priority content tier) ─────────
        # When the LLM adapter is enabled it produces the main response text
        # directly from full context.  On success we skip all template tiers
        # and return immediately (after the phenomenal-coherence check below).
        # On failure / disabled, fall through to the template pipeline as usual.
        _llm_reply: str = ""
        if self._llm_adapter.enabled and user_text.strip():
            from llm_adapter import build_llm_context

            _sm_ref_llm = getattr(brain, "_social_manager", None)
            _llm_pid = (
                _sm_ref_llm.primary_interlocutor() if _sm_ref_llm else None
            )
            _llm_ctx = build_llm_context(
                user_text=user_text,
                brain=brain,
                cs=self,
                speech_act=_sa_name,
                common_ground=common_ground,
                person_id=_llm_pid,
            )
            _llm_reply = self._llm_adapter.generate(_llm_ctx)

        # ── Tier -2: Phenomenal introspection ──────────────────────────────
        # When the experiential state is notable or user asks about inner state,
        # inject the phenomenal buffer as a grounding signal for self-reports.
        # Uses the actual dominant phenomenal dimensions to steer content,
        # not just a static template string.
        _phenom_intro = self.phenomenal_buffer.introspective_state()
        _introspective_cues = {
            "feel",
            "erleb",
            "spür",
            "wahrnehm",
            "experience",
            "fühl",
            "empfind",
            "conscious",
            "bewusst",
            "sense",
        }
        _user_asks_inner = any(cue in user_text.lower() for cue in _introspective_cues)
        if _phenom_intro and (
            _user_asks_inner or self.phenomenal_buffer.experiential_change > 0.12
        ):
            _add_part(_phenom_intro, "observation")
        # Deep phenomenal self-report: when user explicitly asks about inner
        # states, expand using the actual dimensional values, not just the
        # compact signature.
        if _user_asks_inner and len(self.phenomenal_buffer.state) >= 16:
            _pb_state = self.phenomenal_buffer.state
            _dim_names = [
                "visual",
                "auditory",
                "semantic",
                "joy",
                "curiosity",
                "stress",
                "calm",
                "surprise",
                "sadness",
                "energy",
                "integrity",
                "thermal",
                "agency",
                "unity",
                "self_surprise",
                "focus",
            ]
            _top3 = sorted(
                range(len(_dim_names)),
                key=lambda i: abs(float(_pb_state[i])),
                reverse=True,
            )[:3]
            _dominant = [
                (dn if (i := idx) >= 0 else dn, float(_pb_state[idx]))
                for idx in _top3
                for dn in [_dim_names[idx] if idx < len(_dim_names) else f"dim{idx}"]
            ]
            _lk = getattr(self.lang, "current", "de")
            if _lk == "de":
                _phenom_deep = "Gerade dominieren: " + ", ".join(
                    f"{n}={v:.2f}" for n, v in _dominant
                )
            else:
                _phenom_deep = "Currently dominant: " + ", ".join(
                    f"{n}={v:.2f}" for n, v in _dominant
                )
            _add_part(_phenom_deep, "observation")

        # ── Tier -1.5: Social recall — inject person context for continuity ──
        _sm_ref_reply = getattr(brain, "_social_manager", None)
        _reply_pid = _sm_ref_reply.primary_interlocutor() if _sm_ref_reply else None

        # ── Tier -1.6: Long-horizon project context ───────────────────────
        # When an active long-horizon goal or social obligation is topically
        # related to the current conversation, inject a brief reference so the
        # AI sounds like it has coherent ongoing projects, not just reactive
        # responses to isolated questions.
        try:
            _lh_active = self.long_horizon.active_goals()
            _user_toks_lh = {w.lower() for w in user_text.split() if len(w) >= 4}
            _lk_lh = getattr(self.lang, "current", "de")
            # Social obligations for the current interlocutor first
            _social_obs_reply: list = []
            if _reply_pid is not None:
                _social_obs_reply = self.long_horizon.social_obligations_for(_reply_pid)
            for _so_r in _social_obs_reply[:1]:
                _obs_hint_r = (
                    f"(Offene Zusage an diese Person: {_so_r.description[:60]})"
                    if _lk_lh == "de"
                    else f"(Pending commitment to this person: {_so_r.description[:60]})"
                )
                _add_part(_obs_hint_r, "recall")
            # General project reference when topic words overlap with goal description
            _proj_referenced = bool(_social_obs_reply)
            for _lhg_r in _lh_active[:4]:
                if _proj_referenced:
                    break
                _goal_toks_r = {
                    w.lower() for w in _lhg_r.description.split() if len(w) >= 4
                }
                if _user_toks_lh & _goal_toks_r:
                    _proj_hint_r = (
                        f"(Laufendes Vorhaben: {_lhg_r.description[:55]}, "
                        f"{_lhg_r.progress:.0%} abgeschlossen)"
                        if _lk_lh == "de"
                        else f"(Ongoing project: {_lhg_r.description[:55]}, "
                        f"{_lhg_r.progress:.0%} done)"
                    )
                    _add_part(_proj_hint_r, "recall")
                    _proj_referenced = True
        except Exception:
            pass  # project tier is non-critical

        if _reply_pid is not None:
            # Pass current topic tokens for relevance-ranked recall
            _reply_topic_toks = frozenset(
                w.lower()
                for w in user_text.split()
                if len(w) >= 3
            )
            _person_context = self.recall_for_person(
                _reply_pid, brain, topic_tokens=_reply_topic_toks
            )
            if _person_context and _person_context.get("n_shared_episodes", 0) > 0:
                _shared = _person_context["n_shared_episodes"]
                _trust = _person_context.get("trust", 0.5)
                _past_emo = _person_context.get("dominant_past_emotion", "")
                _interests = _person_context.get("inferred_interests", [])[:3]
                _tone_bias = _person_context.get("tone_bias", "neutral")
                _conflict_ratio = float(_person_context.get("conflict_ratio", 0.0))

                _ctx_parts: List[str] = []
                if _shared > 2:
                    _ctx_parts.append(f"shared {_shared} episodes")
                if _interests:
                    _ctx_parts.append(f"interests: {', '.join(_interests)}")
                if _past_emo and _past_emo != "unknown":
                    _ctx_parts.append(f"past mood: {_past_emo}")
                if _ctx_parts:
                    _add_part(f"({'; '.join(_ctx_parts)})", "recall")

                # ── Tone-Bias injection ───────────────────────────────────
                # Conflict-heavy history → tone down; positive history → open up
                _lk_r = getattr(self.lang, "current", "de")
                if _conflict_ratio > 0.35 and _conflict_ratio > float(_person_context.get("positive_ratio", 0.0)):
                    _tone_hint = "Sei behutsam und ruhig." if _lk_r == "de" else "Be careful and calm."
                    _add_part(f"(Tonhinweis: {_tone_hint})", "recall")
                elif _tone_bias == "positive" and float(_person_context.get("positive_ratio", 0.0)) > 0.3:
                    _tone_hint = "Wärmer Ton angebracht." if _lk_r == "de" else "Warmer tone appropriate."
                    _add_part(f"(Tonhinweis: {_tone_hint})", "recall")

                # ── Top scored episode with trust tier ────────────────────
                _weps = _person_context.get("weighted_episodes", [])
                if _weps:
                    _top = _weps[0]
                    _tier = _top.get("trust_tier", "plausible")
                    _ep_t = _top.get("text", "")
                    _ep_s = float(_top.get("score", 0.0))
                    if _ep_t and _ep_s > 0.25:
                        if _tier == "uncertain" or _tier == "reconstructed":
                            _hedge = "Ich glaube, früher war:" if _lk_r == "de" else "I think previously:"
                        else:
                            _hedge = "Erinnerung:" if _lk_r == "de" else "Memory:"
                        _add_part(f"({_hedge} {_ep_t})", "recall")

        # ── Tier -1.4: ToM-driven content selection ───────────────────────
        # Use the addressee's mental model to guide WHAT we say, not just HOW.
        # If the person already knows a topic (high knowledge_estimate), avoid
        # repeating it.  If they have inferred interests, prioritise related content.
        _tom_content_filter: set = set()  # topics to suppress (person already knows)
        _tom_content_boost: List[str] = (
            []
        )  # topics to prioritise (person interested in)
        if _reply_pid is not None:
            _mm = self.theory_of_mind.get_model(str(_reply_pid))
            if _mm is not None and _mm.model_confidence > 0.15:
                # Suppress already-known topics from response content
                for _topic, _know in _mm.knowledge_estimate.items():
                    if _know > 0.7:
                        _tom_content_filter.add(_topic.lower())
                # Boost content related to person's interests/goals
                _tom_content_boost = [g for g in _mm.inferred_goals if g][:3]
                # If person seems avoidant, reduce content volume
                if _mm.response_pattern == "avoidant":
                    _tom_content_filter.add("__limit_parts__")

        # ── Tier -1.25: Common Ground — use shared knowledge to guide reply ──
        # confirmed_facts → dedup (handled in _add_part closure)
        # open_questions → prioritise answering pending questions
        # shared_referents → ground response on visible entities
        _cg_priority_question: str = ""
        _cg_referent_hint: str = ""
        if _cg is not None:
            # Pick the most recent open question as priority
            _oqs = getattr(_cg, "open_questions", [])
            if _oqs:
                _cg_priority_question = _oqs[-1]
                # If user's text seems to answer an open question, resolve it
                for _oq in _oqs:
                    _oq_tokens = {t.lower() for t in _oq.split() if len(t) > 3}
                    if user_tokens & _oq_tokens:
                        _cg.resolve_question(_oq)
            # Use shared referents to ground response
            _refs = getattr(_cg, "shared_referents", [])
            if _refs:
                _visible_labels = [r.split(":", 1)[-1] for r in _refs[:5]]
                _relevant_refs = [
                    r
                    for r in _visible_labels
                    if any(tok in r.lower() for tok in user_tokens)
                ]
                if _relevant_refs:
                    _cg_referent_hint = ", ".join(_relevant_refs[:3])

        # If there's an open question and the user didn't just ask something new,
        # prioritise addressing it
        if _cg_priority_question and not any(
            cue in user_text.lower()
            for cue in (
                "?",
                "was ",
                "wer ",
                "wie ",
                "warum ",
                "what ",
                "who ",
                "how ",
                "why ",
            )
        ):
            _add_part(f"(open: {_cg_priority_question[:80]})", "recall")

        # If we can refer to something both parties can see, note it
        if _cg_referent_hint:
            _add_part(f"(visible: {_cg_referent_hint})", "observation")

        # ── Tier -1.1: Reference resolution — causal referent grounding ─────
        # PRIMARY path: CommonGround already contains referents resolved by
        # process_incoming() at turn-entry time.  We USE those referents to
        # steer content selection, not just log them as strings.
        #
        # FALLBACK: if CommonGround has no active referent for a pronoun/
        # demonstrative found in user_text, resolve it here via WorldState
        # and store the result so all subsequent tiers see it.
        #
        # AMBIGUITY: if confidence < 0.35, the SpeechActPlanner has already
        # (or will) flag REPAIR.  We still ground the partial resolution so
        # the repair text can name the candidate.
        _active_referent_for_reply: Optional[str] = None   # entity label to use
        _active_referent_id: Optional[str] = None          # "object:cup" etc.

        if _cg is not None:
            # Use the most salient active referent from CommonGround first
            _cg_best = _cg.get_most_salient_referent()
            if _cg_best is not None and _cg_best.discourse_status == "active":
                _active_referent_id = _cg_best.referent_id
                _world_ref_for_label = getattr(brain, "world_state", None)
                if _world_ref_for_label is not None:
                    _active_referent_for_reply = _world_ref_for_label.entity_label(
                        _active_referent_id
                    )
                else:
                    _active_referent_for_reply = _active_referent_id.split(":", 1)[-1]

        # Fallback: pronoun in user_text with no CG entry yet
        _world_ref = getattr(brain, "world_state", None)
        if _active_referent_id is None and _world_ref is not None:
            _ref_triggers = {
                "das", "dies", "dieses", "jenes", "er", "sie", "ihn", "ihm",
                "it", "this", "that", "he", "him", "she", "her", "they",
                "dort", "da", "there", "here",
            }
            _user_lc = user_text.lower()
            _ref_phrase = next(
                (tok for tok in _user_lc.split() if tok in _ref_triggers), None
            )
            if _ref_phrase:
                _resolved_ent = _world_ref.resolve_reference(
                    _ref_phrase,
                    current_tick=getattr(brain, "tick_count", 0),
                    topic_tokens=list(user_tokens),
                )
                if _resolved_ent:
                    _ent_label = _world_ref.entity_label(_resolved_ent)
                    _world_ref.note_mentioned(_resolved_ent)
                    _ref_sal = _world_ref.compute_salience(
                        getattr(brain, "tick_count", 0),
                        topic_tokens=list(user_tokens),
                    )
                    _ref_conf = float(
                        _ref_sal.get(_resolved_ent, 0.7)
                        if isinstance(_ref_sal, dict)
                        else 0.7
                    )
                    if _cg is not None:
                        from dialogue_manager import ResolvedReferent as _RR
                        _rr = _RR(
                            referent_id=_resolved_ent,
                            referent_type=(
                                _resolved_ent.split(":")[0]
                                if ":" in _resolved_ent
                                else "unknown"
                            ),
                            source_phrase=_ref_phrase,
                            confidence=_ref_conf,
                            resolution_source="world_model",
                            tick=getattr(brain, "tick_count", 0),
                            discourse_status="active",
                            salience=_ref_conf,
                        )
                        _cg.update_referent(_rr)
                    _active_referent_id = _resolved_ent
                    _active_referent_for_reply = _ent_label

        # ── Causal use: ground reply text on the resolved referent ─────────
        # If we have a high-confidence referent AND the user asked a question
        # about it (detected by topic overlap), surface the referent's label
        # explicitly in the reply so the answer is unambiguously grounded.
        # Also: if the open-question in CommonGround is bound to this referent,
        # prioritise answering it.
        if _active_referent_for_reply and _active_referent_id:
            _ref_label = _active_referent_for_reply
            _ref_conf_val = 0.7
            if _cg is not None:
                _best_rr = _cg.get_most_salient_referent()
                _ref_conf_val = _best_rr.confidence if _best_rr else 0.7

            # Surface the referent label in a brief grounding note for non-LLM path
            _add_part(f"(Bezug: {_ref_label})", "observation")

            # If the question in CommonGround is bound to this referent, inject
            # the question text as priority context
            if _cg is not None:
                for _oq in _cg.open_questions:
                    _oq_ref = _cg.referent_for_question(_oq)
                    if _oq_ref == _active_referent_id:
                        _add_part(f"(offene Frage: {_oq[:80]})", "recall")
                        break

            # Low confidence AND the LLM won't be used → explicit repair question
            if _ref_conf_val < 0.35 and not _sa_silence and not _llm_reply:
                _repair_q = {
                    "de": f"Meinst du {_ref_label}?",
                    "en": f"Do you mean {_ref_label}?",
                }
                _lk = getattr(self.lang, "current", "de")
                _add_part(_repair_q.get(_lk, _repair_q["de"]), "inference")

        # ── Tier -1: QueryEngine — direct answer for any question ──────────
        # Checked first; if it returns a substantive answer it becomes the
        # primary response and the remaining tiers only add context.
        _hipp = getattr(getattr(self, "_brain_ref", None), "hippocampus", None)
        _qe_answer = self.query_engine.answer(
            user_text,
            self.belief_store,
            self.concept_graph,
            self.world_model,
            _hipp,
            self.meta,
            self.lang,
            em,
            grounded_memory=self.grounded_memory,
        )
        if _qe_answer:
            _add_part(_qe_answer, "inference")

        # ── Tier 0: LanguageProducer integration paragraph ─────────────────
        # Only runs when QueryEngine produced nothing, not blocked by agenda,
        # and the response still needs more content.
        _lp_blocked = "inference" in _agenda_blocked or "hypothesis" in _agenda_blocked
        if len(parts) < _target_parts and not _lp_blocked:
            # Build a coherent multi-sentence paragraph from beliefs + causal chain
            focus_concept = None
            if user_tokens:
                focus_concept = next(
                    (
                        c
                        for c in reversed(list(self._concepts))
                        if any(tok in c.lower() for tok in user_tokens)
                    ),
                    None,
                )
            if focus_concept is None and self._concepts:
                focus_concept = list(self._concepts)[-1]

            if focus_concept:
                _triples = self.belief_store.query(focus_concept, min_confidence=0.30)
                _chain = self.belief_store.causal_chain(focus_concept, max_depth=4)
                _dom = em.dominant()
                _integrated = self.lang.integrate(focus_concept, _triples, _chain, _dom)
                if _integrated and not any(
                    _token_overlap(_integrated, p) > 0.5 for p in parts
                ):
                    # Determine evidence level from belief store
                    _best_ep = "inference"
                    _rich = self.belief_store.query_rich(
                        focus_concept, min_confidence=0.30
                    )
                    if _rich:
                        _best_ep = _rich[0][2].epistemic_status.value
                    _add_part(_integrated, _best_ep)

        # Recalled memories bypass the relevance filter — they are already
        # topically selected using the user's terms as cues.
        # Only fires when the conversational agenda permits recall.
        brain_ref = getattr(self, "_brain_ref", None)
        _recall_blocked = "recall" in _agenda_blocked
        if not _recall_blocked and brain_ref is not None:
            # Use user words (>3 chars) + workspace as combined recall cues
            _user_cues = [
                w.lower() for w in user_text.split() if len(w) > 3 and w.isalpha()
            ]
            _ws_cues = self.workspace_concepts()
            _all_cues = list(dict.fromkeys(_user_cues + _ws_cues))
            if _all_cues:
                # Episodic recall: surface the most relevant stored episode
                _eps = brain_ref.hippocampus.recall_episodes(_all_cues, top_n=1)
                if _eps:
                    ep_tick, ep_concs, ep_emo = _eps[0]
                    ep_str = ", ".join(ep_concs[:6])
                    _add_part(f"I recall ({ep_emo}): {ep_str}", "recall")
                # Semantic association chain
                _mem = brain_ref.hippocampus.semantic_recall(_all_cues, top_n=5)
                _mem_new = [c for c in _mem if not any(c in p for p in parts)]
                if _mem_new and len(parts) < _target_parts:
                    _add_part(
                        "Associations: " + " \u2192 ".join(_mem_new[:4]), "inference"
                    )

        seen: List[str] = []
        for msg in sorted(outbox_msgs, key=_score_text, reverse=True):
            clean = msg.replace("[COMM] ", "").strip()
            if not clean or len(clean) <= 10:
                continue
            if _relevance(clean) < 0.10:
                continue
            if any(_token_overlap(clean, prev) > 0.55 for prev in seen):
                continue
            seen.append(clean)
        # Only add outbox content if we still need more parts
        if len(parts) < _target_parts:
            for _s in seen[: max(0, _target_parts - len(parts))]:
                _add_part(_s, "inference")

        if len(parts) < _target_parts:
            for tp in sorted(tagged_parts, key=_score_text, reverse=True):
                if len(parts) >= _target_parts:
                    break
                if _relevance(tp) < 0.08:
                    continue
                if not any(_token_overlap(tp, p) > 0.45 for p in parts):
                    _add_part(tp, "observation")

        if len(parts) < _target_parts and new_concs:
            for nc in sorted(new_concs[-5:], key=_score_text, reverse=True):
                if _relevance(nc) < 0.08:
                    continue
                if not any(_token_overlap(nc, p) > 0.45 for p in parts):
                    _add_part(nc, "inference")
                    break

        if not parts:
            dom = em.dominant()
            concept = None
            if user_tokens:
                concept = next(
                    (
                        c
                        for c in reversed(list(self._concepts))
                        if any(tok in c.lower() for tok in user_tokens)
                    ),
                    None,
                )
            if concept is None and self._concepts:
                concept = list(self._concepts)[-1]

            if concept:
                nb = self.concept_graph.neighbors(concept, 3)
                related = [c for c, _ in nb]
                triples = self.belief_store.query(concept, min_confidence=0.25)
                # Produce a real bilingual inner-voice sentence as fallback
                mode = "assertion" if triples else "reflection"
                voice = self.lang.inner_voice(
                    concept, mode, related, dom, [(r, o, c) for r, o, c in triples]
                )
                # Add body note if urgent
                if self.body.homeostatic_urgency() > 0.3:
                    voice += f"  {self.body.describe()}."
                parts.append(voice)
                _evidence_labels.append(
                    (voice, "hypothesis" if mode == "reflection" else "inference")
                )
            else:
                # Absolute last resort: reflection without a concept
                _fallback = self.lang.reflection("—")
                parts.append(_fallback)
                _evidence_labels.append((_fallback, "hypothesis"))

        # ── Speech Act post-shaping ──────────────────────────────────────
        # If the planner decided ASK, ensure the response asks a question.
        # If OBSERVE, prepend an observation marker.
        if _sa_ask and parts:
            _has_q = any("?" in p for p in parts)
            if not _has_q:
                # Turn the response into a question by appending an open query
                _cg_open = getattr(_cg, "open_questions", []) if _cg else []
                if _cg_open:
                    parts.append(_cg_open[-1])
                    _evidence_labels.append((_cg_open[-1], "inference"))
                else:
                    _ask_suffix = {"de": "Was meinst du?", "en": "What do you think?"}
                    _lk = getattr(self.lang, "current", "de")
                    parts.append(_ask_suffix.get(_lk, _ask_suffix["de"]))
                    _evidence_labels.append((parts[-1], "inference"))
        if _sa_observe and parts:
            _obs_prefix = {"de": "Ich beobachte: ", "en": "I observe: "}
            _lk = getattr(self.lang, "current", "de")
            parts[0] = _obs_prefix.get(_lk, _obs_prefix["de"]) + parts[0]

        # ── Epistemic self-restraint: hedge weak-evidence claims ────────
        _HEDGE = {
            "de": {
                "hearsay": "Ich habe gehört, dass",
                "hypothesis": "Ich vermute, dass",
            },
            "en": {"hearsay": "I've heard that", "hypothesis": "I suspect that"},
        }
        _lang_key = getattr(self.lang, "_lang", "de")
        hedges = _HEDGE.get(_lang_key, _HEDGE["de"])
        hedged_parts: List[str] = []
        for text, evidence in _evidence_labels:
            if text not in parts:
                continue  # was deduplicated away
            if evidence in hedges and len(text) > 20:
                hedged_parts.append(f"{hedges[evidence]} {text[0].lower()}{text[1:]}")
            else:
                hedged_parts.append(text)

        # ── LLM early-exit: use generative reply instead of template parts ──
        # If the LLM produced content, replace assembled parts entirely.
        # The phenomenal-coherence check below still runs on the LLM text.
        if _llm_reply:
            _final_out = _llm_reply
        else:
            _final_out = "  ".join(hedged_parts) if hedged_parts else "  ".join(parts)

        # ── Hard phenomenal-language coupling ────────────────────────────
        # Bidirectional enforcement: every explicit emotional/experiential
        # claim in the assembled reply must be consistent with the actual
        # phenomenal buffer state.  The buffer IS the experiencing step;
        # language cannot assert an inner state that it contradicts.
        #
        # pb_state indices: 3=joy, 4=curiosity, 5=stress, 6=calm,
        #                   7=surprise, 8=sadness, 9=energy, 10=integrity
        # Each entry: (claim_keywords, expected-high-dim, contrary-dim-or-None)
        # Fires only when claimed dim is LOW *and* contrary dim is HIGH —
        # requiring an active contradicting signal, not mere absence.
        _lower_out = _final_out.lower()
        _PHCL_HI = 0.22  # claimed dim below this → "not experiencing that"
        _PHCL_CON = 0.32  # contrary dim above this → "active contrary signal"
        _PHENOM_CLAIM_GROUPS: list = [
            # joy claimed but sadness is the dominant signal
            (
                {
                    "glücklich",
                    "freudig",
                    "erfreut",
                    "wunderbar",
                    "toll",
                    "happy",
                    "joyful",
                    "excited",
                    "begeistert",
                },
                3,
                8,
            ),
            # curiosity claimed but no signal (no strong contrary)
            (
                {"neugier", "curious", "fasziniert", "interessiert", "fascinated"},
                4,
                None,
            ),
            # stress claimed but calm is dominant
            ({"gestresst", "angespannt", "stressed", "anxious", "beunruhigt"}, 5, 6),
            # calm claimed but stress is dominant
            ({"ruhig", "gelassen", "entspannt", "calm", "relaxed", "serene"}, 6, 5),
            # sadness claimed but joy is dominant
            ({"traurig", "sad", "niedergeschlagen", "bedrückt", "upset"}, 8, 3),
        ]
        _pb_mismatch = False
        if len(self.phenomenal_buffer.state) >= 9:
            _pb = self.phenomenal_buffer.state
            for _pkws, _pdim, _pcon in _PHENOM_CLAIM_GROUPS:
                if not any(_pk in _lower_out for _pk in _pkws):
                    continue
                _actual = float(_pb[_pdim])
                if _actual < _PHCL_HI:
                    # Claim expects a high value for this dim — fire only when
                    # a contrary signal is either active or none is expected
                    if _pcon is None or float(_pb[_pcon]) > _PHCL_CON:
                        _pb_mismatch = True
                        break

        # Legacy check: positive / inner-state claim vs. high stress/pain
        # from the EmotionalState object (complements buffer dimensions).
        _em_coh = brain.emotion_state
        _stress_coh = getattr(_em_coh, "stress", 0.0)
        _pain_coh = getattr(_em_coh, "pain", 0.0)
        _inner_claim_kws = {
            "ich fühle",
            "ich erlebe",
            "i feel",
            "i am feeling",
            "i experience",
            "ich spüre",
            "i notice",
            "ich merke",
        }
        _positive_kws = {
            "glücklich",
            "wunderbar",
            "toll",
            "prima",
            "happy",
            "wonderful",
            "great",
            "fantastic",
            "excited",
        }
        _has_inner = any(kw in _lower_out for kw in _inner_claim_kws)
        _has_positive = any(kw in _lower_out for kw in _positive_kws)
        _legacy_mm = (_has_inner or _has_positive) and (
            _stress_coh > 0.65 or _pain_coh > 0.55
        )

        if _pb_mismatch or _legacy_mm:
            _lk_coh = getattr(self.lang, "current", "de")
            _coherence_hedge = {
                "de": "(kalibriert: mein Erlebniszustand stimmt nicht vollständig"
                " mit dieser Aussage überein)",
                "en": "(calibrated: my experiential state does not fully"
                " support this claim)",
            }.get(
                _lk_coh,
                "(calibrated: my experiential state does not fully support this claim)",
            )
            _final_out = f"{_final_out}  {_coherence_hedge}"

        # ── Second-order ToM update ────────────────────────────────────────
        # After assembling the reply, attribute the discussed topics to the AI
        # in the interlocutor's mental model — tracking what the person now
        # knows the AI claims to believe ("I think you think I know X").
        if _reply_pid is not None:
            _so_tokens = [
                w.lower() for w in _final_out.split() if len(w) > 4 and w.isalpha()
            ][:8]
            if _so_tokens:
                self.theory_of_mind.observe_ai_statement(
                    getattr(brain, "tick_count", 0),
                    str(_reply_pid),
                    _so_tokens,
                )

        # ── Prosody tag injection based on cognitive/emotional state ──────
        # Prepend [SLOW] when uncertainty is high — perceptually signals
        # deliberation, making uncertain replies sound considered, not flat.
        # Prepend [SOFT] during sadness — quieter delivery matches affect.
        # These tags are stripped before TTS renders the text.
        try:
            _unc = getattr(self, "uncertainty_overall", 0.5)
            _emo_d = em.dominant() if em else "calm"
            if _unc > 0.68 and not _final_out.startswith("[SLOW]"):
                _final_out = "[SLOW]" + _final_out
            if _emo_d == "sadness" and not _final_out.startswith("[SOFT]"):
                _final_out = "[SOFT]" + _final_out
        except Exception:
            pass

        return _final_out

    def compose_live_reply(self, user_text: str, brain: "Brain") -> str:
        recent_stream = list(self.stream)[-20:]
        recent_concs = [c for c in list(self._conclusions)[-6:] if c and len(c) > 15]
        bare_prefixes = (
            "[joy",
            "[calm",
            "[curiosity",
            "[stress",
            "[sadness",
            "[anger",
            "[surprise",
            "[fatigue",
            "[BIOG] ",
            "[STRAT] ",
        )
        tag_priority = {
            "[!] ": 5,
            "[?] ": 4,
            "[~] ": 4,
            "[o] ": 3,
            "[<] ": 2,
            "[SELF] ": 1,
            "[META] ": 1,
        }
        tagged_parts: List[str] = []
        for entry in recent_stream:
            if not entry or any(entry.startswith(prefix) for prefix in bare_prefixes):
                continue
            for prefix, _score in tag_priority.items():
                if entry.startswith(prefix):
                    content = entry[len(prefix) :].strip()
                    if len(content) > 10:
                        tagged_parts.append(content)
                    break
        outbox_msgs = brain.get_outbound_messages()
        return self._assemble_grounded_reply(
            brain,
            user_text=user_text,
            outbox_msgs=outbox_msgs,
            new_concs=recent_concs,
            tagged_parts=tagged_parts,
            common_ground=getattr(
                getattr(brain, "_dialogue_manager", None), "active_ground", None
            ),
        )
